const e="https://www.churchofjesuschrist.org/study/scriptures",a=JSON.parse('[{"id":"doctrine-and-covenants","title":"Doutrina e Convênios","englishTitle":"Doctrine and Covenants","volume":"Doctrine and Covenants","volumeId":"dc-testament","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Escutai, ó povo da minha igreja, diz a voz daquele que habita no alto e cujos olhos estão sobre todos os homens; sim, em verdade vos digo: Escutai, ó povos distantes e vós, que estais nas ilhas do mar, escutai juntamente."},{"verse":2,"text":"Pois em verdade a voz do Senhor dirige-se a todos os homens e ninguém há de escapar; e não haverá olho que não veja nem ouvido que não ouça nem coração que não seja penetrado."},{"verse":3,"text":"E os rebeldes serão afligidos com muita tristeza, porque suas iniquidades serão proclamadas em cima dos telhados e seus feitos secretos serão revelados."},{"verse":4,"text":"E a voz de advertência irá a todos os povos pela boca de meus discípulos, que escolhi nestes últimos dias."},{"verse":5,"text":"E eles irão e ninguém os deterá, porque eu, o Senhor, os mandei ir."},{"verse":6,"text":"Eis que esta é a minha autoridade e a autoridade de meus servos e o meu prefácio ao livro de meus mandamentos, os quais lhes dei para que os publicassem para vós, ó habitantes da Terra."},{"verse":7,"text":"Portanto, temei e tremei, ó povos, porque o que eu, o Senhor, neles decretei, neles será cumprido."},{"verse":8,"text":"E em verdade vos digo que àqueles que saírem para levar estas novas aos habitantes da Terra será dado poder para selar, tanto na Terra como nos céus, os incrédulos e rebeldes;"},{"verse":9,"text":"Sim, em verdade, selá-los para o dia em que a ira de Deus se derramar sem medida sobre os iníquos —"},{"verse":10,"text":"Para o dia em que o Senhor vier recompensar cada homem de acordo com suas obras e medir cada homem com a mesma medida com que ele houver medido seu próximo."},{"verse":11,"text":"Portanto, a voz do Senhor chega aos confins da Terra, para que ouçam os que quiserem ouvir:"},{"verse":12,"text":"Preparai-vos, preparai-vos para o que está para vir, porque o Senhor está perto;"},{"verse":13,"text":"E a ira do Senhor está acesa e sua espada está lavada nos céus e sobre os habitantes da Terra cairá."},{"verse":14,"text":"E o braço do Senhor será revelado; e chegará o dia em que aqueles que não ouvirem a voz do Senhor nem a voz de seus servos nem atenderem às palavras dos profetas e apóstolos serão afastados do meio do povo;"},{"verse":15,"text":"Pois desviaram-se de minhas ordenanças e quebraram meu convênio eterno."},{"verse":16,"text":"Não buscam o Senhor para estabelecer sua retidão, mas todo homem anda em seu próprio caminho e segundo a imagem de seu próprio deus, cuja imagem é à semelhança do mundo e cuja substância é a de um ídolo que envelhece e perecerá em Babilônia, sim, Babilônia, a grande, que cairá."},{"verse":17,"text":"Portanto, eu, o Senhor, conhecendo as calamidades que adviriam aos habitantes da Terra, chamei meu servo Joseph Smith Júnior e falei-lhe do céu e dei-lhe mandamentos;"},{"verse":18,"text":"E também a outros dei mandamentos de proclamar estas coisas ao mundo; e tudo isso para que se cumprisse o que foi escrito pelos profetas —"},{"verse":19,"text":"As coisas fracas do mundo virão e abaterão as poderosas e fortes, para que o homem não aconselhe seu próximo nem confie no braço de carne —"},{"verse":20,"text":"Que todo homem, porém, fale em nome de Deus, o Senhor, sim, o Salvador do mundo;"},{"verse":21,"text":"Para que a fé também aumente na Terra;"},{"verse":22,"text":"Para que o meu eterno convênio seja estabelecido;"},{"verse":23,"text":"Para que a plenitude do meu evangelho seja proclamada pelos fracos e pelos simples aos confins da Terra e perante reis e governantes."},{"verse":24,"text":"Eis que eu sou Deus e disse-o; estes mandamentos são meus e foram dados a meus servos em sua fraqueza, conforme a sua maneira de falar, para que alcançassem entendimento."},{"verse":25,"text":"E se errassem, isso fosse revelado;"},{"verse":26,"text":"E se buscassem sabedoria, fossem instruídos;"},{"verse":27,"text":"E se pecassem, fossem repreendidos, para que se arrependessem;"},{"verse":28,"text":"E se fossem humildes, fossem fortalecidos e abençoados do alto e recebessem conhecimento de tempos em tempos."},{"verse":29,"text":"Sim, e para que meu servo Joseph Smith Júnior depois de haver recebido o registro dos nefitas, tivesse poder para traduzir, pela misericórdia de Deus, pelo poder de Deus, o Livro de Mórmon."},{"verse":30,"text":"E também para que aqueles a quem foram dados estes mandamentos tivessem poder para estabelecer o alicerce desta igreja e tirá-la da obscuridade e das trevas, a única igreja verdadeira e viva na face de toda a Terra, com a qual eu, o Senhor, me deleito, falando à igreja coletiva e não individualmente —"},{"verse":31,"text":"Pois eu, o Senhor, não posso encarar o pecado com o mínimo grau de tolerância;"},{"verse":32,"text":"Entretanto, aquele que se arrepender e cumprir os mandamentos do Senhor será perdoado;"},{"verse":33,"text":"E aquele que não se arrepender, dele será tirada até a luz que recebeu, pois o meu Espírito não contenderá para sempre com o homem, diz o Senhor dos Exércitos."},{"verse":34,"text":"E também em verdade vos digo, ó habitantes da Terra: Eu, o Senhor, estou disposto a tornar conhecidas estas coisas a toda carne;"},{"verse":35,"text":"Porque não faço acepção de pessoas e desejo que todos os homens saibam que o dia rapidamente se aproxima; ainda não é chegada a hora, mas está perto, em que a paz será tirada da Terra e o diabo terá poder sobre seu próprio domínio."},{"verse":36,"text":"E também o Senhor terá poder sobre seus santos e reinará em seu meio e descerá para julgar Idumeia, ou seja, o mundo."},{"verse":37,"text":"Examinai estes mandamentos, porque são verdadeiros e fiéis; e as profecias e as promessas neles contidas serão todas cumpridas."},{"verse":38,"text":"O que eu, o Senhor, disse está dito e não me desculpo; e ainda que passem os céus e a Terra, minha palavra não passará, mas será toda cumprida, seja pela minha própria voz ou pela voz de meus servos, é o mesmo."},{"verse":39,"text":"Pois eis que o Senhor é Deus e o Espírito testifica; e o testemunho é verdadeiro e a verdade permanece para todo o sempre. Amém."}]},{"chapter":2,"verses":[{"verse":1,"text":"Eis que vos revelarei o Sacerdócio pela mão de Elias, o profeta, antes da vinda do grande e terrível dia do Senhor."},{"verse":2,"text":"E ele plantará no coração dos filhos as promessas feitas aos pais, e o coração dos filhos voltar-se-á para seus pais."},{"verse":3,"text":"Se assim não fosse, toda a Terra seria completamente devastada na sua vinda."}]},{"chapter":3,"verses":[{"verse":1,"text":"As obras e os desígnios e os propósitos de Deus não podem ser frustrados nem podem se dissipar."},{"verse":2,"text":"Porque Deus não anda por veredas tortuosas, nem se volta para a direita ou para a esquerda, nem se desvia daquilo que disse; portanto, as suas veredas são retas e o seu caminho é um círculo eterno."},{"verse":3,"text":"Lembra-te, lembra-te de que não é a obra de Deus que se frustra, mas a obra dos homens;"},{"verse":4,"text":"Pois embora um homem tenha muitas revelações e tenha poder para realizar muitas obras grandiosas, contudo, se ele se vangloriar da própria força e ignorar os conselhos de Deus e seguir os ditames da própria vontade e de seus desejos carnais, cairá e trará sobre si a vingança de um Deus justo."},{"verse":5,"text":"Eis que essas coisas te foram confiadas, mas quão rigorosos foram os mandamentos que recebeste; e lembra-te também das promessas que te foram feitas, caso não os transgredisses."},{"verse":6,"text":"E eis que mui frequentemente transgrediste os mandamentos e as leis de Deus e seguiste as persuasões dos homens!"},{"verse":7,"text":"Pois eis que não devias ter temido mais aos homens do que a Deus. Embora os homens ignorem os conselhos de Deus e desprezem suas palavras —"},{"verse":8,"text":"Ainda assim, tu deverias ter sido fiel e ele teria estendido o braço, amparando-te contra todos os dardos inflamados do adversário; e teria permanecido contigo em todos os momentos de angústia."},{"verse":9,"text":"Eis que tu és Joseph e foste escolhido para fazer a obra do Senhor, mas por causa de transgressão, se não ficares atento, cairás."},{"verse":10,"text":"Lembra-te, porém, de que Deus é misericordioso; portanto, arrepende-te do que fizeste contrário ao mandamento que te dei e és ainda escolhido; e és chamado à obra outra vez;"},{"verse":11,"text":"A não ser que faças isso, serás abandonado e tornar-te-ás como os outros homens e não mais terás o dom."},{"verse":12,"text":"E quando entregaste aquilo que Deus te deu visão e poder para traduzir, entregaste o que era sagrado nas mãos de um homem iníquo,"},{"verse":13,"text":"Que ignorou os conselhos de Deus e quebrou as mais sagradas promessas feitas perante Deus; e confiou no próprio discernimento e vangloriou-se da própria sabedoria."},{"verse":14,"text":"E essa é a razão pela qual perdeste os teus privilégios por certo tempo —"},{"verse":15,"text":"Porque permitiste que o conselho de teu orientador fosse pisado desde o princípio."},{"verse":16,"text":"Apesar disso, minha obra avançará, pois como o conhecimento sobre um Salvador veio ao mundo pelo testemunho dos judeus, da mesma forma o conhecimento sobre um Salvador chegará ao meu povo —"},{"verse":17,"text":"E aos nefitas e aos jacobitas e aos josefitas e aos zoramitas, pelo testemunho de seus antepassados —"},{"verse":18,"text":"E esse testemunho chegará ao conhecimento dos lamanitas e dos lemuelitas e dos ismaelitas, que degeneraram na incredulidade devido à iniquidade de seus antepassados, a quem o Senhor permitiu que destruíssem seus irmãos, os nefitas, por causa de suas iniquidades e abominações."},{"verse":19,"text":"E para este fim específico as placas que contêm esses registros foram preservadas — para que se cumprissem as promessas do Senhor a seu povo;"},{"verse":20,"text":"E para que os lamanitas tivessem conhecimento de seus antepassados e conhecessem as promessas do Senhor e cressem no evangelho e confiassem nos méritos de Jesus Cristo e fossem glorificados pela fé em seu nome; e para que, pelo seu arrependimento, fossem salvos. Amém."}]},{"chapter":4,"verses":[{"verse":1,"text":"Agora eis que uma obra maravilhosa está para iniciar-se entre os filhos dos homens."},{"verse":2,"text":"Portanto, ó vós que embarcais no serviço de Deus, vede que o sirvais de todo o coração, poder, mente e força, para que vos apresenteis sem culpa perante Deus no último dia."},{"verse":3,"text":"Portanto, se tendes desejo de servir a Deus, sois chamados ao trabalho;"},{"verse":4,"text":"Porque eis que o campo já está branco para a ceifa; e eis que aquele que lança a sua foice com vigor faz reserva, de modo que não perece, mas traz salvação a sua alma;"},{"verse":5,"text":"E fé, esperança, caridade e amor, com os olhos fitos na glória de Deus, qualificam-no para o trabalho."},{"verse":6,"text":"Lembrai-vos da fé, da virtude, do conhecimento, da temperança, da paciência, da bondade fraternal, da piedade, da caridade, da humildade, da diligência."},{"verse":7,"text":"Pedi e recebereis; batei e ser-vos-á aberto. Amém."}]},{"chapter":5,"verses":[{"verse":1,"text":"Eis que te digo que como o meu servo Martin Harris desejou receber de minhas mãos um testemunho de que tu, meu servo Joseph Smith Júnior, possuis as placas sobre as quais testemunhaste e que afirmaste teres recebido de mim;"},{"verse":2,"text":"E agora, eis que isto lhe dirás: Aquele que te falou, disse: Eu, o Senhor, sou Deus e dei estas coisas a ti, meu servo Joseph Smith Júnior, e ordenei-te que fosses testemunha destas coisas;"},{"verse":3,"text":"E fiz com que estabelecesses um convênio comigo de que não as mostrarias a não ser às pessoas a quem eu te ordenasse; e não tens poder sobre elas, a não ser que eu to conceda."},{"verse":4,"text":"E tens um dom para traduzir as placas; e este é o primeiro dom que te conferi; e ordenei-te que não afirmasses ter qualquer outro dom, até que meu propósito fosse cumprido nisso; porque não te concederei outro dom até que isto esteja terminado."},{"verse":5,"text":"Em verdade eu te digo que aos habitantes da Terra sobrevirão desgraças, se não derem ouvidos às minhas palavras;"},{"verse":6,"text":"Pois futuramente serás ordenado e sairás levando minhas palavras aos filhos dos homens."},{"verse":7,"text":"Eis que, se não quiserem acreditar em minhas palavras, não crerão em ti, meu servo Joseph, ainda que te fosse possível mostrar-lhes todas essas coisas que te confiei."},{"verse":8,"text":"Oh! esta geração incrédula e obstinada — minha ira está acesa contra ela."},{"verse":9,"text":"Eis que em verdade eu te digo: Reservei as coisas que te confiei, meu servo Joseph, para um sábio propósito meu, que será revelado às gerações futuras;"},{"verse":10,"text":"Esta geração, porém, receberá minha palavra por teu intermédio;"},{"verse":11,"text":"E ao teu testemunho serão acrescentados os testemunhos de três de meus servos, que chamarei e ordenarei, a quem mostrarei essas coisas; e serão enviados com minhas palavras, dadas por teu intermédio."},{"verse":12,"text":"Sim, saberão com certeza que essas coisas são verdadeiras, porque dos céus lhas declararei."},{"verse":13,"text":"Dar-lhes-ei poder para verem e considerarem essas coisas como são;"},{"verse":14,"text":"E a ninguém mais desta geração concederei este poder para receber esse mesmo testemunho neste momento em que minha igreja começa a surgir e a sair do deserto — brilhante como a lua e formosa como o sol e terrível como um exército com estandartes."},{"verse":15,"text":"E enviarei o depoimento de três testemunhas de minha palavra."},{"verse":16,"text":"E eis que visitarei com a manifestação de meu Espírito aqueles que crerem em minhas palavras e eles de mim nascerão, sim, da água e do Espírito —"},{"verse":17,"text":"E tu deves esperar ainda um pouco mais, porque ainda não foste ordenado —"},{"verse":18,"text":"E o testemunho delas também irá condenar esta geração, se contra elas endurecer o coração;"},{"verse":19,"text":"Porque haverá um flagelo assolador entre os habitantes da Terra e continuará a derramar-se de tempos em tempos, se eles não se arrependerem, até que a Terra fique vazia e seus habitantes sejam consumidos e totalmente destruídos pelo resplendor da minha vinda."},{"verse":20,"text":"Eis que te digo estas coisas, assim como também falei ao povo acerca da destruição de Jerusalém; e minha palavra será confirmada agora, como tem sido confirmada até aqui."},{"verse":21,"text":"E agora te ordeno, meu servo Joseph, que te arrependas e andes mais retamente diante de mim; e que não cedas mais às persuasões dos homens;"},{"verse":22,"text":"E que sejas firme na obediência aos mandamentos que te dei; e se fizeres isto, eis que te concedo vida eterna, mesmo que sejas morto."},{"verse":23,"text":"E agora também te falo, meu servo Joseph, com respeito ao homem que deseja o testemunho —"},{"verse":24,"text":"Eis que lhe digo que ele se exalta a si mesmo e não se humilha suficientemente perante mim; mas se prostrar-se perante mim e humilhar-se em fervorosa oração e fé, com o coração sincero, então permitirei que veja as coisas que deseja ver."},{"verse":25,"text":"E então ele dirá ao povo desta geração: Eis que vi as coisas que o Senhor mostrou a Joseph Smith Júnior e sei, sem dúvida, que são verdadeiras, porque as vi; pois foram-me mostradas pelo poder de Deus e não dos homens."},{"verse":26,"text":"E eu, o Senhor, ordeno a meu servo Martin Harris que não lhes diga nada mais a respeito destas coisas, exceto: Vi-as e foram-me mostradas pelo poder de Deus; e estas são as palavras que deverá dizer."},{"verse":27,"text":"Mas se negar isso, quebrará o convênio que fez anteriormente comigo e eis que será condenado."},{"verse":28,"text":"E agora, a não ser que se humilhe e reconheça perante mim os seus erros e faça convênio comigo de que guardará meus mandamentos e exerça fé em mim, eis que lhe digo que não verá essas coisas, porque não lhe permitirei ver as coisas de que falei."},{"verse":29,"text":"E se for esse o caso, eu te ordeno, meu servo Joseph, que lhe digas que nada mais faça nem me importune mais a respeito deste assunto."},{"verse":30,"text":"E se for esse o caso, eis que te digo, Joseph: Quando tiveres traduzido mais algumas páginas, para por uns tempos, até que eu te ordene novamente; então poderás voltar a traduzir."},{"verse":31,"text":"E a não ser que faças isso, eis que não terás mais dom e tomarei as coisas que te confiei."},{"verse":32,"text":"E agora, porque antevejo emboscadas para te destruírem, sim, antevejo que se meu servo Martin Harris não se humilhar e não receber de minha mão um testemunho, cairá em transgressão;"},{"verse":33,"text":"E há muitos que estão à espreita para eliminar-te da face da Terra; e por isso, para que teus dias se prolonguem, dei-te estes mandamentos."},{"verse":34,"text":"Sim, por essa razão eu disse: Para e espera até que eu te ordene; e providenciarei meios para realizares as coisas que te ordenei."},{"verse":35,"text":"E se fores fiel na observância de meus mandamentos, serás elevado no último dia. Amém."}]},{"chapter":6,"verses":[{"verse":1,"text":"Uma grande e maravilhosa obra está para iniciar-se entre os filhos dos homens."},{"verse":2,"text":"Eis que eu sou Deus; atenta para a minha palavra, que é viva e poderosa, mais penetrante que uma espada de dois gumes, que penetra até dividir as juntas e medulas; portanto, atenta para as minhas palavras."},{"verse":3,"text":"Eis que o campo já está branco para a ceifa; portanto, quem deseja ceifar que lance a sua foice com vigor e ceife enquanto durar o dia, a fim de entesourar para sua alma salvação eterna no reino de Deus."},{"verse":4,"text":"Sim, aquele que lança sua foice e ceifa é chamado por Deus."},{"verse":5,"text":"Portanto, se me pedires, receberás; se bateres, ser-te-á aberto."},{"verse":6,"text":"Agora, como me pediste, eis que te digo: Guarda meus mandamentos e procura trazer à luz e estabelecer a causa de Sião;"},{"verse":7,"text":"Não busque riquezas, mas sabedoria, e eis que os mistérios de Deus te serão revelados e então serás enriquecido. Eis que é rico aquele que tem a vida eterna."},{"verse":8,"text":"Em verdade, em verdade te digo: Aquilo que desejares de mim ser-te-á concedido; e se o desejares, serás o instrumento para que se faça muito de bom nesta geração."},{"verse":9,"text":"Não pregues coisa alguma a esta geração, a não ser arrependimento; guarda meus mandamentos e ajuda a trazer à luz minha obra, de acordo com meus mandamentos; e serás abençoado."},{"verse":10,"text":"Eis que tens um dom e abençoado és por causa de teu dom. Lembra-te de que ele é sagrado e que vem do alto —"},{"verse":11,"text":"E se perguntares, conhecerás mistérios que são grandes e maravilhosos; portanto, exercerás teu dom para que desvendes mistérios, para que leves muitos a conhecerem a verdade, sim, para convencê-los do erro de seus caminhos."},{"verse":12,"text":"Não dês a conhecer teu dom, a não ser àqueles que são de tua fé. Não trates com leviandade as coisas sagradas."},{"verse":13,"text":"Se fizeres o bem, sim, e te conservares fiel até o fim, serás salvo no reino de Deus, o que é o maior de todos os dons de Deus; porque não há dom maior que o da salvação."},{"verse":14,"text":"Em verdade, em verdade te digo: Bem-aventurado és pelo que fizeste; porque me procuraste e eis que, tantas vezes quantas inquiriste, recebeste instruções de meu Espírito. Se assim não fora, não terias chegado ao lugar onde agora estás."},{"verse":15,"text":"Eis que tu sabes que me inquiriste e que te iluminei a mente; e agora te digo estas coisas para que saibas que foste iluminado pelo Espírito da verdade;"},{"verse":16,"text":"Sim, digo-te para que saibas que ninguém há, a não ser Deus, que conheça teus pensamentos e os intentos de teu coração."},{"verse":17,"text":"Digo-te estas coisas como um testemunho a ti de que as palavras, ou seja, a obra que estás escrevendo é verdadeira."},{"verse":18,"text":"Portanto, sê diligente; apoia fielmente meu servo Joseph em qualquer circunstância difícil em que se encontrar por causa da palavra."},{"verse":19,"text":"Admoesta-o a respeito de suas faltas e aceita suas admoestações. Sê paciente; sê sóbrio; sê temperante; tem paciência, fé, esperança e caridade."},{"verse":20,"text":"Eis que tu és Oliver e falei contigo por causa de teus desejos; portanto, entesoura estas palavras no coração. Sê fiel e diligente na observância dos mandamentos de Deus e envolver-te-ei nos braços de meu amor."},{"verse":21,"text":"Eis que eu sou Jesus Cristo, o Filho de Deus. Sou o mesmo que vim para os meus e os meus não me receberam. Eu sou a luz que resplandece nas trevas e as trevas não a compreendem."},{"verse":22,"text":"Em verdade, em verdade eu te digo: Se desejas mais um testemunho, volve tua mente para a noite em que clamaste a mim em teu coração a fim de saberes a respeito da veracidade destas coisas."},{"verse":23,"text":"Não dei paz a tua mente quanto ao assunto? Que maior testemunho podes ter que o de Deus?"},{"verse":24,"text":"E agora, eis que recebeste um testemunho; porque, se eu te disse coisas que homem algum sabe, não recebeste um testemunho?"},{"verse":25,"text":"E eis que te concedo o dom, se de mim o desejas, de traduzir, sim, como meu servo Joseph."},{"verse":26,"text":"Em verdade, em verdade te digo que existem registros que contêm muito de meu evangelho, os quais foram retidos por causa da iniquidade do povo;"},{"verse":27,"text":"E agora te ordeno que, se tens bons desejos — um desejo de acumular para ti tesouros no céu — então auxilia a trazer à luz, com teu dom, as partes de minhas escrituras que foram escondidas por causa de iniquidade."},{"verse":28,"text":"E agora eis que te concedo, e também a meu servo Joseph, as chaves desse dom, que trará à luz esse ministério; e pela boca de duas ou três testemunhas toda palavra será estabelecida."},{"verse":29,"text":"Em verdade, em verdade vos digo: Se rejeitarem minhas palavras e esta parte de meu evangelho e ministério, bem-aventurados sereis, porque não poderão fazer a vós mais do que fizeram a mim."},{"verse":30,"text":"E mesmo se vos fizerem o que fizeram a mim, bem-aventurados sereis, pois habitareis comigo em glória."},{"verse":31,"text":"Mas se não rejeitarem minhas palavras, as quais serão estabelecidas pelo testemunho que será dado, bem-aventurados serão e, então, tereis regozijo no fruto dos vossos labores."},{"verse":32,"text":"Em verdade, em verdade vos digo, como disse a meus discípulos: Onde dois ou três estiverem reunidos em meu nome, tratando de alguma coisa, eis que ali estarei no meio deles — assim também estou no meio de vós."},{"verse":33,"text":"Não tenhais receio de praticar o bem, meus filhos, pois o que semeardes, isso colhereis; portanto, se semeardes o bem, colhereis o bem como vossa recompensa."},{"verse":34,"text":"Portanto, não temais, pequeno rebanho; fazei o bem; deixai que a Terra e o inferno se unam contra vós, pois se estiverdes estabelecidos sobre minha rocha, eles não poderão prevalecer."},{"verse":35,"text":"Eis que eu não vos condeno; segui vossos caminhos e não pequeis mais; executai com seriedade a obra que vos ordenei."},{"verse":36,"text":"Buscai-me em cada pensamento; não duvideis, não temais."},{"verse":37,"text":"Vede as feridas que me perfuraram o lado e também as marcas dos cravos em minhas mãos e pés; sede fiéis, guardai meus mandamentos e herdareis o reino do céu. Amém."}]},{"chapter":7,"verses":[{"verse":1,"text":"E O Senhor disse-me: João, meu amado, o que desejas? Pois se pedires o que desejas, ser-te-á concedido."},{"verse":2,"text":"E eu disse-lhe: Senhor, dá-me poder sobre a morte, para que eu viva e traga almas a ti."},{"verse":3,"text":"E o Senhor disse-me: Em verdade, em verdade te digo: Visto que o desejaste, permanecerás até que eu venha em minha glória e profetizarás perante nações, tribos, línguas e povos."},{"verse":4,"text":"E por esse motivo o Senhor disse a Pedro: Se eu quero que ele fique até que eu venha, que te importa a ti? Pois ele pediu-me que pudesse trazer almas a mim, mas tu me pediste para ir rapidamente ter comigo em meu reino."},{"verse":5,"text":"Digo-te, Pedro, que esse foi um bom desejo; mas o meu amado desejou fazer mais, ou seja, uma obra ainda maior entre os homens do que aquilo que fez antes."},{"verse":6,"text":"Sim, ele se propôs a uma obra maior; portanto, torná-lo-ei como fogo flamejante e um anjo ministrador; ele ministrará em favor daqueles que serão os herdeiros da salvação e habitam a Terra."},{"verse":7,"text":"E farei com que ministres junto a ele e a teu irmão Tiago; e a vós três darei este poder e as chaves deste ministério até que eu venha."},{"verse":8,"text":"Em verdade vos digo que ambos recebereis conforme vossos desejos, pois ambos vos regozijais naquilo que desejastes."}]},{"chapter":8,"verses":[{"verse":1,"text":"Oliver Cowdery, em verdade em verdade eu te digo que, tão certamente quanto vive o Senhor, que é teu Deus e teu Redentor, tão certamente receberás conhecimento de todas as coisas que pedires com fé, com um coração honesto, crendo que receberás conhecimento concernente a gravações de velhos registros que são antigos, os quais contêm aquelas partes de minhas escrituras das quais se falou pela manifestação de meu Espírito."},{"verse":2,"text":"Sim, eis que eu te falarei em tua mente e em teu coração, pelo Espírito Santo que virá sobre ti e que habitará em teu coração."},{"verse":3,"text":"Ora, eis que este é o espírito de revelação; eis que este é o espírito pelo qual Moisés conduziu os filhos de Israel através do Mar Vermelho, em terra seca."},{"verse":4,"text":"Portanto, este é teu dom; usa-o e serás abençoado, porque te livrará das mãos de teus inimigos, ao passo que, se assim não fosse, eles te matariam e levariam tua alma à destruição."},{"verse":5,"text":"Oh! Lembra-te destas palavras e guarda meus mandamentos. Lembra-te, este é teu dom."},{"verse":6,"text":"Agora, este não é teu único dom; porque tens outro dom, que é o dom de Aarão; eis que esse dom tem manifestado muitas coisas a ti;"},{"verse":7,"text":"Eis que nenhum outro poder existe, a não ser o poder de Deus, que faça com que esse dom de Aarão esteja contigo."},{"verse":8,"text":"Portanto, não duvides, porque é o dom de Deus; e tê-lo-ás em tuas mãos e farás obras maravilhosas; e nenhum poder será capaz de tirá-lo de tuas mãos, porque é a obra de Deus."},{"verse":9,"text":"E, portanto, qualquer coisa que pedires que eu te diga por esse meio conceder-te-ei e receberás conhecimento a respeito dela."},{"verse":10,"text":"Lembra-te de que sem fé nada podes fazer; portanto, pede com fé. Não trates essas coisas levianamente; não peças o que não deves."},{"verse":11,"text":"Pede que te seja concedido conhecer os mistérios de Deus e que possas traduzir e receber conhecimento de todos os registros antigos que foram ocultos e que são sagrados; e ser-te-á feito segundo a tua fé."},{"verse":12,"text":"Eis que fui eu quem o disse; e eu sou o mesmo que te falou desde o princípio. Amém."}]},{"chapter":9,"verses":[{"verse":1,"text":"Eis que eu te digo, meu filho, que por não teres traduzido conforme me havias pedido e começado outra vez a escrever para meu servo Joseph Smith Júnior desejo que assim continues até que tenhas terminado este registro que confiei a ele."},{"verse":2,"text":"E então, eis que te concederei poder para ajudares a traduzir outros registros que tenho."},{"verse":3,"text":"Sê paciente, meu filho, porque isto é segundo minha sabedoria e não convém que traduzas neste momento."},{"verse":4,"text":"Eis que o trabalho para o qual és chamado é escrever para meu servo Joseph."},{"verse":5,"text":"E eis que foi por não teres continuado como no princípio, quando começaste a traduzir, que tirei esse privilégio de ti."},{"verse":6,"text":"Não murmures, meu filho, porque foi segundo minha sabedoria que agi contigo dessa maneira."},{"verse":7,"text":"Eis que não compreendeste; supuseste que eu o concederia a ti, quando nada fizeste a não ser pedir-me."},{"verse":8,"text":"Mas eis que eu te digo que deves estudá-lo bem em tua mente; depois me deves perguntar se está certo e, se estiver certo, farei arder dentro de ti o teu peito; portanto, sentirás que está certo."},{"verse":9,"text":"Mas se não estiver certo, não terás tais sentimentos; terás, porém, um estupor de pensamento que te fará esquecer o que estiver errado; portanto, não podes escrever aquilo que é sagrado a não ser que te seja concedido por mim."},{"verse":10,"text":"Ora, se tivesses sabido disto, poderias ter traduzido; contudo, não convém que traduzas agora."},{"verse":11,"text":"Eis que era conveniente quando começaste, mas temeste e a hora passou; e agora não convém."},{"verse":12,"text":"Pois não vês que, para compensar, dei força suficiente a meu servo Joseph? E a nenhum de vós condenei."},{"verse":13,"text":"Faze isto que te ordenei e prosperarás. Sê fiel e não cedas a tentação alguma."},{"verse":14,"text":"Permanece firme no trabalho para o qual te chamei e nem um fio de cabelo de tua cabeça se perderá; e serás elevado no último dia. Amém."}]},{"chapter":10,"verses":[{"verse":1,"text":"Agora, eis que te digo que porque entregaste esses escritos, que recebeste poder para traduzir por meio do Urim e Tumim, nas mãos de um homem iníquo, tu os perdeste."},{"verse":2,"text":"E ao mesmo tempo perdeste também o teu dom, escurecendo-se a tua mente."},{"verse":3,"text":"Não obstante, agora te é restituído; portanto, sê fiel e continua, até terminares, o restante do trabalho de tradução como iniciaste."},{"verse":4,"text":"Não corras mais depressa nem trabalhes mais do que te permitam as tuas forças e os meios concedidos para que te seja possível traduzir; mas sê diligente até o fim."},{"verse":5,"text":"Ora sempre, para que saias vencedor; sim, para que venças Satanás e escapes das mãos dos servos de Satanás, que apoiam o trabalho dele."},{"verse":6,"text":"Eis que tentaram destruir-te; sim, até o homem em quem confiaste procurou destruir-te."},{"verse":7,"text":"E por isso eu disse que ele é um homem iníquo, porque procurou tirar as coisas que te foram confiadas; e também procurou destruir teu dom."},{"verse":8,"text":"E porque entregaste os escritos em suas mãos, eis que homens iníquos os tiraram de ti."},{"verse":9,"text":"Portanto, os entregaste, sim, aquilo que era sagrado, à iniquidade."},{"verse":10,"text":"E eis que Satanás os incitou em seus corações a alterarem as palavras que fizeste escrever, ou seja, que tu traduziste e que saíram de tuas mãos."},{"verse":11,"text":"E eis que te digo que, porque alteraram as palavras, leem diferentemente do que traduziste e fizeste escrever;"},{"verse":12,"text":"E dessa forma o diabo procurou armar um plano astuto a fim de destruir esta obra;"},{"verse":13,"text":"Pois ele incitou-os em seus corações a fazerem isso para que, mentindo, possam dizer que te apanharam nas palavras que fingiste traduzir."},{"verse":14,"text":"Em verdade eu te digo que não permitirei que Satanás realize seus desígnios iníquos com relação a isto."},{"verse":15,"text":"Pois eis que os incitou em seus corações a te persuadirem a tentar o Senhor teu Deus, pedindo para traduzi-las outra vez."},{"verse":16,"text":"E então, eis que dizem e pensam no coração — Veremos se Deus lhe deu poder para traduzir; se assim for, dar-lhe-á novamente;"},{"verse":17,"text":"E se Deus lhe der poder outra vez ou se ele traduzir de novo, ou seja, se escrever as mesmas palavras, eis que nós as temos conosco e as alteramos;"},{"verse":18,"text":"Portanto, não coincidirão; e diremos que mentiu em suas palavras e que ele não tem dom algum e que não possui qualquer poder;"},{"verse":19,"text":"Portanto, nós o destruiremos e também a obra; e faremos isso para que no final não sejamos envergonhados e para que obtenhamos a glória do mundo."},{"verse":20,"text":"Em verdade, em verdade eu te digo que Satanás exerce grande poder sobre seus corações e incita-os à iniquidade, contra aquilo que é bom;"},{"verse":21,"text":"E seus corações são corruptos e cheios de iniquidade e abominações; e amam as trevas mais que a luz, porque suas ações são más; portanto, não recorrerão a mim."},{"verse":22,"text":"Satanás incita-os a fim de conduzir suas almas à destruição."},{"verse":23,"text":"E assim fez um plano astuto, pensando destruir a obra de Deus; mas eu exigirei isso de suas mãos e tornar-se-á em vergonha e condenação para eles no dia do juízo."},{"verse":24,"text":"Sim, ele incita-lhes os corações a irarem-se contra esta obra."},{"verse":25,"text":"Sim, diz-lhes: Enganai e ficai à espreita para apanhar, a fim de destruir; pois eis que nisso não há dano. E assim os lisonjeia e diz-lhes que não é pecado mentir a fim de apanhar um homem em mentira para destruí-lo."},{"verse":26,"text":"E assim os lisonjeia e conduz, até arrastar suas almas para o inferno; e assim os faz cair em suas próprias armadilhas."},{"verse":27,"text":"E assim vai de cima para baixo e de cá para lá na Terra, procurando destruir a alma dos homens."},{"verse":28,"text":"Em verdade, em verdade eu te digo: Ai daquele que mente para enganar, porque supõe que outro minta para enganar, pois esse não está isento da justiça de Deus."},{"verse":29,"text":"Ora, eis que eles alteraram estas palavras porque Satanás lhes disse: Ele enganou-vos — e assim os lisonjeia e leva-os a praticarem iniquidades, a fim de fazer com que tentes o Senhor teu Deus."},{"verse":30,"text":"Eis que te digo que não deverás tornar a traduzir aquelas palavras que saíram de tuas mãos;"},{"verse":31,"text":"Pois eis que não levarão a efeito seus desígnios iníquos de mentir sobre aquelas palavras. Pois eis que, se escreveres as mesmas palavras, dirão que mentiste e que fingiste traduzir, mas que te contradisseste."},{"verse":32,"text":"E eis que publicarão isso e Satanás endurecerá o coração das pessoas a fim de enfurecê-las contra ti, para que não creiam em minhas palavras."},{"verse":33,"text":"Assim Satanás pensa anular teu testemunho nesta geração, para que a obra não venha à luz nesta geração."},{"verse":34,"text":"Mas eis que aqui há sabedoria; e porque te revelo sabedoria e te dou mandamentos sobre o que deves fazer com relação a estas coisas, não a reveles ao mundo até que termines o trabalho de tradução."},{"verse":35,"text":"Não te maravilhes de que eu te tenha dito: Aqui há sabedoria, não a reveles ao mundo — porque eu disse: Não a reveles ao mundo, para que sejas preservado."},{"verse":36,"text":"Eis que não digo que não a reveles aos justos;"},{"verse":37,"text":"Mas como nem sempre podes julgar os justos, ou seja, como nem sempre podes discernir os iníquos dos justos, digo-te: Mantém silêncio até que me pareça conveniente dar a conhecer ao mundo todas as coisas concernentes ao assunto."},{"verse":38,"text":"E agora, em verdade eu te digo que um relato daquelas coisas que escreveste e que saíram de tuas mãos está gravado nas placas de Néfi;"},{"verse":39,"text":"Sim; e lembra-te de que naqueles escritos se mencionava que um relato mais minucioso destas coisas fora feito nas placas de Néfi."},{"verse":40,"text":"E agora, porque o relato que está gravado nas placas de Néfi é mais minucioso quanto às coisas que, segundo minha sabedoria, eu levaria ao conhecimento do povo neste relato —"},{"verse":41,"text":"Traduzirás, portanto, o que está gravado nas placas de Néfi, até chegares ao reinado do rei Benjamim, ou até a parte que traduziste, que está contigo;"},{"verse":42,"text":"E eis que o publicarás como registro de Néfi; e assim confundirei os que alteraram minhas palavras."},{"verse":43,"text":"Não permitirei que eles destruam minha obra; sim, mostrar-lhes-ei que minha sabedoria é maior do que a astúcia do diabo."},{"verse":44,"text":"Eis que eles têm somente uma parte, ou seja, um resumo do relato de Néfi."},{"verse":45,"text":"Eis que há muitas coisas gravadas nas placas de Néfi que lançam maior luz sobre meu evangelho; portanto, segundo minha sabedoria, deves traduzir essa primeira parte das gravações de Néfi e incluí-la nesta obra."},{"verse":46,"text":"E eis que todo o restante deste trabalho contém todas as partes de meu evangelho que meus santos profetas, sim, e também meus discípulos pediram, em suas orações, que fossem dadas a este povo."},{"verse":47,"text":"E eu disse-lhes que lhes seria concedido de acordo com a fé expressa em suas orações;"},{"verse":48,"text":"Sim, e esta era a fé que tinham — que meu evangelho, o qual lhes dei para que pregassem em seus dias, chegaria a seus irmãos, os lamanitas, e também a todos os que se houvessem tornado lamanitas por causa de suas dissensões."},{"verse":49,"text":"Ora, isto não é tudo — a fé expressa em suas orações era que esse evangelho também se tornaria conhecido caso outras nações ocupassem esta terra;"},{"verse":50,"text":"E assim deixaram uma bênção sobre esta terra em suas orações, para que todo aquele que cresse neste evangelho, nesta terra, tivesse vida eterna;"},{"verse":51,"text":"Sim, que ele ficasse ao alcance de todos, qualquer que fosse a nação, tribo, língua ou povo a que pertencessem."},{"verse":52,"text":"E agora eis que, de acordo com a fé expressa em suas orações, levarei esta parte de meu evangelho ao conhecimento de meu povo. Eis que não a levo para destruir aquilo que receberam, mas para edificá-lo."},{"verse":53,"text":"E por isso eu disse: Se os desta geração não endurecerem o coração, estabelecerei minha igreja entre eles."},{"verse":54,"text":"Ora, não digo isto para destruir minha igreja, mas digo isto para edificar minha igreja."},{"verse":55,"text":"Portanto, todos os que pertencem a minha igreja não precisam temer, porque herdarão o reino dos céus."},{"verse":56,"text":"Mas os que não me temem nem guardam meus mandamentos, mas edificam igrejas para si mesmos a fim de obter lucro, sim, e todos os que praticam iniquidade e edificam o reino do diabo — sim, em verdade, em verdade eu te digo que são esses os que perturbarei e farei tremer e estremecer até as entranhas."},{"verse":57,"text":"Eis que eu sou Jesus Cristo, o Filho de Deus. Vim para os meus e os meus não me receberam."},{"verse":58,"text":"Eu sou a luz que resplandece nas trevas e as trevas não a compreendem."},{"verse":59,"text":"Eu sou aquele que disse a meus discípulos — Tenho outras ovelhas que não são deste aprisco — e muitos houve que não me compreenderam."},{"verse":60,"text":"E mostrarei a este povo que eu tinha outras ovelhas e que elas eram um ramo da casa de Jacó;"},{"verse":61,"text":"E trarei à luz as obras maravilhosas que fizeram em meu nome;"},{"verse":62,"text":"Sim, e também trarei à luz meu evangelho, que lhes foi ministrado, e eis que eles não negarão o que recebeste; edificá-lo-ão, porém, e trarão à luz os pontos verdadeiros de minha doutrina, sim, e a única doutrina que está em mim."},{"verse":63,"text":"E isto faço para estabelecer meu evangelho, para que não haja tanta contenda; sim, Satanás incita o coração do povo a contender com relação aos pontos de minha doutrina; e nestas coisas erram, porque torcem as escrituras e não as compreendem."},{"verse":64,"text":"Portanto, desvendar-lhes-ei este grande mistério;"},{"verse":65,"text":"Pois eis que eu os ajuntarei como uma galinha ajunta seus pintinhos debaixo das asas, se eles não endurecerem o coração;"},{"verse":66,"text":"Sim, se desejarem vir, poderão vir e tomar de graça das águas da vida."},{"verse":67,"text":"Eis que esta é a minha doutrina: Aquele que se arrepende e vem a mim, esse é a minha igreja."},{"verse":68,"text":"Aquele que declara mais ou menos do que isso, esse não é meu, mas está contra mim; portanto, ele não é da minha igreja."},{"verse":69,"text":"E agora, eis que aquele que é da minha igreja e nela persevera até o fim, esse estabelecerei sobre minha rocha; e as portas do inferno não prevalecerão contra ele."},{"verse":70,"text":"E agora, lembra-te das palavras daquele que é a vida e a luz do mundo, teu Redentor, teu Senhor e teu Deus. Amém."}]},{"chapter":11,"verses":[{"verse":1,"text":"Uma grande e maravilhosa obra está para iniciar-se entre os filhos dos homens."},{"verse":2,"text":"Eis que eu sou Deus; atenta para a minha palavra, que é viva e poderosa, mais penetrante que uma espada de dois gumes, que penetra até dividir as juntas e medulas; portanto, atenta para a minha palavra."},{"verse":3,"text":"Eis que o campo já está branco para a ceifa; portanto, quem deseja ceifar que lance a foice com vigor e ceife enquanto durar o dia, a fim de entesourar para sua alma a salvação eterna no reino de Deus."},{"verse":4,"text":"Sim, aquele que lança sua foice e ceifa é chamado por Deus."},{"verse":5,"text":"Portanto, se me pedires, receberás; se bateres, ser-te-á aberto."},{"verse":6,"text":"Agora, como pediste, eis que te digo: Guarda meus mandamentos e procura trazer à luz e estabelecer a causa de Sião."},{"verse":7,"text":"Não busques riquezas, mas sabedoria; e eis que os mistérios de Deus te serão revelados e então serás enriquecido. Eis que é rico aquele que tem a vida eterna."},{"verse":8,"text":"Em verdade, em verdade eu te digo que aquilo que desejares de mim ser-te-á concedido; e se o desejares, serás o instrumento para que se faça muito de bom nesta geração."},{"verse":9,"text":"Não pregues a esta geração coisa alguma a não ser arrependimento. Guarda meus mandamentos e ajuda a trazer à luz a minha obra, de acordo com meus mandamentos; e serás abençoado."},{"verse":10,"text":"Eis que tens um dom, ou melhor, terás um dom se me pedires com fé, com um coração sincero, crendo no poder de Jesus ou em meu poder que fala a ti;"},{"verse":11,"text":"Pois eis que sou eu quem fala; eis que eu sou a luz que resplandece nas trevas e pelo meu poder dou-te estas palavras."},{"verse":12,"text":"E agora, em verdade, em verdade eu te digo: Põe tua confiança naquele Espírito que leva a fazer o bem — sim, a agir justamente, a andar em humildade, a julgar com retidão; e esse é o meu Espírito."},{"verse":13,"text":"Em verdade, em verdade eu te digo: Dar-te-ei do meu Espírito, o qual iluminará tua mente e encher-te-á a alma de alegria;"},{"verse":14,"text":"E então saberás, ou seja, por esse meio saberás todas as coisas, relativas à retidão, que desejares de mim, com fé, acreditando em mim que receberás."},{"verse":15,"text":"Eis que te digo que não precisas supor teres sido chamado a pregar até que sejas chamado."},{"verse":16,"text":"Espera um pouco mais até que tenhas minha palavra, minha rocha, minha igreja e meu evangelho, a fim de que conheças indubitavelmente minha doutrina."},{"verse":17,"text":"E então, eis que te será feito de acordo com teus desejos, sim, de acordo com tua fé."},{"verse":18,"text":"Guarda meus mandamentos; mantém silêncio; recorre ao meu Espírito;"},{"verse":19,"text":"Sim, apega-te a mim de todo o coração a fim de ajudares a trazer à luz as coisas de que se tem falado — sim, a tradução de minha obra; sê paciente até que a realizes."},{"verse":20,"text":"Eis que esta é a tua obra: Guardar meus mandamentos, sim, com todo teu poder, mente e força."},{"verse":21,"text":"Não procures pregar minha palavra, mas primeiro procura obter minha palavra e então tua língua será desatada; e então, se o desejares, terás meu Espírito e minha palavra, sim, o poder de Deus para convencer os homens."},{"verse":22,"text":"Mas por enquanto mantém silêncio; estuda minha palavra, que foi pregada aos filhos dos homens, e estuda também minha palavra que será pregada aos filhos dos homens, ou seja, que está agora sendo traduzida, sim, até que tenhas obtido tudo o que concederei aos filhos dos homens nesta geração; e então a isto todas as coisas serão acrescentadas."},{"verse":23,"text":"Eis que tu és Hyrum, meu filho; busca o reino de Deus e todas as coisas serão acrescentadas de acordo com aquilo que é justo."},{"verse":24,"text":"Edifica sobre minha rocha, que é meu evangelho;"},{"verse":25,"text":"Não negues o espírito de revelação nem o espírito de profecia, porque ai daquele que nega essas coisas;"},{"verse":26,"text":"Portanto, entesoura essas coisas em teu coração até o momento em que, segundo minha sabedoria, saias a pregar."},{"verse":27,"text":"Eis que falo a todos os que têm desejos bons e lançaram sua foice para ceifar."},{"verse":28,"text":"Eis que eu sou Jesus Cristo, o Filho de Deus. Eu sou a vida e a luz do mundo."},{"verse":29,"text":"Eu sou o mesmo que vim aos meus e os meus não me receberam;"},{"verse":30,"text":"Mas em verdade, em verdade eu te digo que a todos os que me receberem darei poder para se tornarem filhos de Deus, sim, àqueles que crerem em meu nome. Amém."}]},{"chapter":12,"verses":[{"verse":1,"text":"Uma obra grande e maravilhosa está para iniciar-se entre os filhos dos homens."},{"verse":2,"text":"Eis que eu sou Deus; atenta para a minha palavra, que é viva e poderosa, mais penetrante que uma espada de dois gumes, que penetra até dividir as juntas e medulas; portanto, atenta para a minha palavra."},{"verse":3,"text":"Eis que o campo já está branco para a ceifa; portanto, quem deseja ceifar lance a foice com vigor e ceife enquanto durar o dia, a fim de entesourar para sua alma a salvação eterna no reino de Deus."},{"verse":4,"text":"Sim, aquele que lançar sua foice e ceifar será chamado por Deus."},{"verse":5,"text":"Portanto, se me pedires, receberás; se bateres, ser-te-á aberto."},{"verse":6,"text":"Agora, como pediste, eis que te digo: Guarda meus mandamentos e procura trazer à luz e estabelecer a causa de Sião."},{"verse":7,"text":"Eis que falo a ti e também a todos os que têm o desejo de trazer à luz e estabelecer esta obra;"},{"verse":8,"text":"E ninguém pode auxiliar nesta obra a menos que seja humilde e cheio de amor, tendo fé, esperança e caridade, sendo temperante em todas as coisas, em tudo o que lhe for confiado."},{"verse":9,"text":"Eis que eu sou a luz e a vida do mundo, que diz estas palavras; portanto, escuta com toda a tua força e então serás chamado. Amém."}]},{"chapter":13,"verses":[{"verse":1,"text":"A vós, meus conservos, em nome do Messias, eu confiro o Sacerdócio de Aarão, que possui as chaves do ministério de anjos e do evangelho do arrependimento e do batismo por imersão para remissão de pecados; e ele nunca mais será tirado da Terra, até que os filhos de Levi tornem a fazer, em retidão, uma oferta ao Senhor."}]},{"chapter":14,"verses":[{"verse":1,"text":"Uma obra grande e maravilhosa está para iniciar-se entre os filhos dos homens."},{"verse":2,"text":"Eis que eu sou Deus; atenta para a minha palavra, que é viva e poderosa, mais penetrante que uma espada de dois gumes, que penetra até dividir as juntas e medulas; portanto, atenta para a minha palavra."},{"verse":3,"text":"Eis que o campo já está branco para a ceifa; portanto, quem deseja ceifar que lance a foice com vigor e ceife enquanto durar o dia, a fim de entesourar para sua alma a salvação eterna no reino de Deus."},{"verse":4,"text":"Sim, aquele que lançar sua foice e ceifar será chamado por Deus."},{"verse":5,"text":"Portanto, se me pedires, receberás; se bateres, ser-te-á aberto."},{"verse":6,"text":"Procura trazer à luz e estabelecer minha Sião. Guarda meus mandamentos em todas as coisas."},{"verse":7,"text":"E se guardares meus mandamentos e perseverares até o fim, terás vida eterna, que é o maior de todos os dons de Deus."},{"verse":8,"text":"E acontecerá que, se pedires ao Pai em meu nome, com fé, acreditando, receberás o Espírito Santo, o qual inspira o que dizer, para que sirvas de testemunha das coisas que irás ouvir e ver; e também para que proclames o arrependimento a esta geração."},{"verse":9,"text":"Eis que eu sou Jesus Cristo, o Filho do Deus vivo, que criou os céus e a Terra, uma luz que não pode ser escondida nas trevas;"},{"verse":10,"text":"Portanto, devo levar a plenitude do meu evangelho dos gentios à casa de Israel."},{"verse":11,"text":"E eis que tu és David e és chamado para ajudar; se fizeres isso e fores fiel, serás abençoado tanto espiritual como materialmente e grande será teu galardão. Amém."}]},{"chapter":15,"verses":[{"verse":1,"text":"Escuta, meu servo John, e dá ouvidos às palavras de Jesus Cristo, teu Senhor e teu Redentor."},{"verse":2,"text":"Pois eis que te falo com clareza e com poder, pois meu braço está sobre toda a Terra."},{"verse":3,"text":"Dir-te-ei aquilo que nenhum homem sabe, a não ser eu e tu somente —"},{"verse":4,"text":"Pois muitas vezes desejaste saber de mim o que seria de maior valor para ti."},{"verse":5,"text":"Eis que abençoado és por isso e por teres declarado minhas palavras, que te dei de acordo com meus mandamentos."},{"verse":6,"text":"E agora, eis que eu te digo que a coisa de maior valor para ti será declarar arrependimento a este povo, a fim de trazeres almas a mim e descansares com elas no reino de meu Pai. Amém."}]},{"chapter":16,"verses":[{"verse":1,"text":"Escuta, meu servo Peter, e dá ouvidos às palavras de Jesus Cristo, teu Senhor e teu Redentor."},{"verse":2,"text":"Pois eis que te falo com clareza e com poder, pois meu braço está sobre toda a Terra."},{"verse":3,"text":"Dir-te-ei aquilo que nenhum homem sabe, a não ser eu e tu somente —"},{"verse":4,"text":"Pois muitas vezes desejaste saber de mim o que seria de maior valor para ti."},{"verse":5,"text":"Eis que abençoado és por isso e por teres declarado minhas palavras, que te dei de acordo com meus mandamentos."},{"verse":6,"text":"E agora, eis que te digo que a coisa de maior valor para ti será declarar arrependimento a este povo, a fim de trazeres almas a mim e descansares com elas no reino de meu Pai. Amém."}]},{"chapter":17,"verses":[{"verse":1,"text":"Eis que vos digo que devereis confiar em minha palavra e, se o fizerdes de todo o coração, vereis as placas e também o peitoral, a espada de Labão, o Urim e Tumim, que foram dados ao irmão de Jarede no monte quando ele falou com o Senhor face a face; e os guias milagrosos que foram dados a Leí enquanto estava no deserto, às margens do Mar Vermelho."},{"verse":2,"text":"E é por vossa fé que os vereis, sim, por aquela fé que possuíam os profetas da antiguidade."},{"verse":3,"text":"E depois de terdes alcançado fé e visto com os próprios olhos, testificareis a respeito deles pelo poder de Deus."},{"verse":4,"text":"E isso fareis para que meu servo Joseph Smith Júnior não seja destruído, para que eu realize meus justos propósitos para com os filhos dos homens nesta obra."},{"verse":5,"text":"E testificareis que os vistes, assim como meu servo Joseph Smith Júnior os viu; e foi pelo meu poder que ele os viu e foi porque teve fé."},{"verse":6,"text":"E ele traduziu o livro, sim, aquela parte que lhe ordenei; e assim como vive vosso Senhor e vosso Deus, ele é verdadeiro."},{"verse":7,"text":"Portanto, vós recebestes o mesmo poder e a mesma fé e o mesmo dom que ele;"},{"verse":8,"text":"E se cumprirdes estes últimos mandamentos que vos dei, as portas do inferno não prevalecerão contra vós; porque minha graça vos basta e sereis elevados no último dia."},{"verse":9,"text":"E eu, Jesus Cristo, vosso Senhor e vosso Deus, vo-lo disse, a fim de realizar meus justos propósitos para com os filhos dos homens. Amém."}]},{"chapter":18,"verses":[{"verse":1,"text":"Agora, eis que por causa daquilo que tu, meu servo Oliver Cowdery, desejaste saber de mim, digo-te estas palavras:"},{"verse":2,"text":"Eis que te manifestei por meu Espírito, em muitas ocasiões, que as coisas que escreveste são verdadeiras; portanto, sabes que são verdadeiras."},{"verse":3,"text":"E se tu sabes que são verdadeiras, eis que te dou um mandamento de que confies nas coisas que estão escritas;"},{"verse":4,"text":"Porque nelas estão escritas todas as coisas concernentes ao alicerce de minha igreja, meu evangelho e minha rocha."},{"verse":5,"text":"Portanto, se edificares a minha igreja sobre o alicerce de meu evangelho e minha rocha, as portas do inferno não prevalecerão contra ti."},{"verse":6,"text":"Eis que o mundo está amadurecendo em iniquidade; e é necessário que os filhos dos homens, tanto os gentios como a casa de Israel, sejam levados ao arrependimento."},{"verse":7,"text":"E assim, como foste batizado pelas mãos de meu servo Joseph Smith Júnior, de acordo com aquilo que lhe ordenei, ele cumpriu aquilo que lhe ordenei."},{"verse":8,"text":"E agora não te maravilhes de que eu o tenha chamado por um propósito meu, propósito esse que me é conhecido; portanto, se ele for diligente na observância de meus mandamentos, será abençoado com vida eterna; e seu nome é Joseph."},{"verse":9,"text":"E agora, Oliver Cowdery, dirijo-me a ti e também a David Whitmer, por meio de mandamento; pois eis que ordeno a todos os homens de todos os lugares que se arrependam; e falo a vós como falei a Paulo, meu apóstolo, porque sois chamados pelo mesmo chamado que ele."},{"verse":10,"text":"Lembrai-vos de que o valor das almas é grande à vista de Deus;"},{"verse":11,"text":"Pois eis que o Senhor vosso Redentor sofreu a morte na carne; portanto, sofreu a dor de todos os homens, para que todos os homens se arrependessem e viessem a ele."},{"verse":12,"text":"E ressuscitou dentre os mortos, para trazer a si todos os homens, sob condição de arrependimento."},{"verse":13,"text":"E quão grande é sua alegria pela alma que se arrepende!"},{"verse":14,"text":"Portanto, sois chamados para clamar arrependimento a este povo."},{"verse":15,"text":"E, se trabalhardes todos os vossos dias clamando arrependimento a este povo e trouxerdes a mim mesmo que seja uma só alma, quão grande será vossa alegria com ela no reino de meu Pai!"},{"verse":16,"text":"E agora, se vossa alegria é grande com uma só alma que tiverdes trazido a mim no reino de meu Pai, quão grande será vossa alegria se me trouxerdes muitas almas!"},{"verse":17,"text":"Eis que tendes diante de vós meu evangelho e minha rocha e minha salvação."},{"verse":18,"text":"Pedi ao Pai em meu nome com fé, acreditando que recebereis, e tereis o Espírito Santo, que manifesta todas as coisas que são convenientes aos filhos dos homens."},{"verse":19,"text":"E se não tendes fé, esperança e caridade, nada podeis fazer."},{"verse":20,"text":"Não contendais com igreja alguma, a menos que seja a igreja do diabo."},{"verse":21,"text":"Tomai sobre vós o nome de Cristo e falai a verdade com seriedade."},{"verse":22,"text":"E todos os que se arrependerem e forem batizados em meu nome, que é Jesus Cristo, e perseverarem até o fim, serão salvos."},{"verse":23,"text":"Eis que Jesus Cristo é o nome dado pelo Pai; e não é dado qualquer outro nome pelo qual o homem possa ser salvo;"},{"verse":24,"text":"Portanto, todos os homens devem tomar sobre si o nome que é dado pelo Pai, pois por esse nome serão chamados no último dia;"},{"verse":25,"text":"Portanto, se não sabem o nome pelo qual são chamados, não podem ter lugar no reino de meu Pai."},{"verse":26,"text":"E agora, eis que há outros chamados para declararem o meu evangelho, tanto aos gentios como aos judeus;"},{"verse":27,"text":"Sim, doze; e os Doze serão meus discípulos e tomarão sobre si o meu nome; e os Doze são aqueles que desejam, de todo coração, tomar sobre si o meu nome."},{"verse":28,"text":"E se desejam, de todo coração, tomar sobre si o meu nome, são chamados para ir a todo o mundo, pregar meu evangelho a toda criatura."},{"verse":29,"text":"E são eles os ordenados por mim para batizar em meu nome, de acordo com o que está escrito;"},{"verse":30,"text":"E tendes diante de vós o que está escrito; portanto, deveis fazer de acordo com as palavras que estão escritas."},{"verse":31,"text":"E agora falo a vós, os Doze: Eis que a minha graça vos basta; deveis andar retamente perante mim e não pecar."},{"verse":32,"text":"E eis que sois aqueles ordenados por mim para ordenar sacerdotes e mestres; para declarar meu evangelho, de acordo com o poder do Espírito Santo que está em vós e de acordo com os chamados e dons de Deus aos homens;"},{"verse":33,"text":"E eu, Jesus Cristo, vosso Senhor e vosso Deus, disse-o."},{"verse":34,"text":"Estas palavras não são de homens nem de um homem, mas são minhas; portanto, vós testificareis que são minhas e não de um homem;"},{"verse":35,"text":"Pois é a minha voz que vo-las diz; pois vos são dadas pelo meu Espírito; e pelo meu poder vós as podeis ler uns para os outros; e se não fosse pelo meu poder, não as poderíeis ter;"},{"verse":36,"text":"Portanto, podeis testificar que ouvistes a minha voz e conheceis as minhas palavras."},{"verse":37,"text":"E agora, eis que eu dou a ti, Oliver Cowdery, e também a ti, David Whitmer, o encargo de procurar os Doze, que terão os desejos que mencionei;"},{"verse":38,"text":"E por seus desejos e suas obras conhecê-los-eis."},{"verse":39,"text":"E quando os tiverdes encontrado, revelareis estas coisas a eles."},{"verse":40,"text":"E prostar-vos-eis e adorareis o Pai em meu nome."},{"verse":41,"text":"É preciso que pregueis ao mundo, dizendo: Deveis arrepender-vos e ser batizados em nome de Jesus Cristo;"},{"verse":42,"text":"Porque todos os homens devem arrepender-se e ser batizados; e não só homens, mas mulheres e crianças que tiverem alcançado a idade da responsabilidade."},{"verse":43,"text":"E agora, depois de terdes recebido isto, deveis guardar meus mandamentos em todas as coisas;"},{"verse":44,"text":"E por vossas mãos realizarei uma obra maravilhosa entre os filhos dos homens para convencer a muitos de seus pecados, para que se arrependam e se aproximem do reino de meu Pai."},{"verse":45,"text":"Portanto, as bênçãos que vos dou estão acima de todas as coisas."},{"verse":46,"text":"E depois de terdes recebido isto, se não guardardes meus mandamentos, não podereis ser salvos no reino de meu Pai."},{"verse":47,"text":"Eis que eu, Jesus Cristo, vosso Senhor e vosso Deus e vosso Redentor, pelo poder de meu Espírito, disse-o. Amém."}]},{"chapter":19,"verses":[{"verse":1,"text":"Eu sou o Alfa e o Ômega, Cristo, o Senhor; sim, eu sou ele, o princípio e o fim, o Redentor do mundo."},{"verse":2,"text":"Eu, tendo cumprido e consumado a vontade daquele a quem pertenço, ou seja, o Pai, a meu respeito — tendo feito isso para sujeitar a mim todas as coisas —"},{"verse":3,"text":"Retendo todo o poder, até para destruir Satanás e suas obras no fim do mundo; e no último grande dia do juízo, que pronunciarei sobre seus habitantes, julgando a cada homem de acordo com suas obras e as ações que houver praticado."},{"verse":4,"text":"E certamente todo homem deve arrepender-se ou sofrer, pois eu, Deus, sou infinito."},{"verse":5,"text":"Portanto, não revogarei os julgamentos que pronunciar, mas sobrevirão desgraça, pranto, lamentação e ranger de dentes, sim, àqueles que se acharem à minha esquerda."},{"verse":6,"text":"Contudo, não está escrito que não haverá fim para esse tormento, mas está escrito tormento infinito."},{"verse":7,"text":"Também, está escrito condenação eterna; portanto, está mais explícito do que outras escrituras, a fim de influenciar o coração dos filhos dos homens inteiramente para a glória de meu nome."},{"verse":8,"text":"Explicar-vos-ei, portanto, este mistério, porque vos convém conhecê-lo, assim como meus apóstolos."},{"verse":9,"text":"Falo a vós que fostes escolhidos com referência a este assunto, como se fôsseis um, para que entreis em meu descanso."},{"verse":10,"text":"Pois eis que o mistério da divindade, quão grande é! Pois eis que eu sou infinito e o castigo que é dado pela minha mão é castigo infinito, pois Infinito é meu nome. Portanto —"},{"verse":11,"text":"Castigo eterno é castigo de Deus."},{"verse":12,"text":"Castigo infinito é castigo de Deus."},{"verse":13,"text":"Portanto, ordeno que te arrependas e guardes os mandamentos que recebeste pela mão de Joseph Smith Júnior em meu nome;"},{"verse":14,"text":"E é pela minha onipotência que os recebeste;"},{"verse":15,"text":"Portanto, ordeno que te arrependas — arrepende-te, para que eu não te fira com a vara de minha boca e com minha ira e com minha cólera e teus sofrimentos sejam dolorosos — quão dolorosos tu não sabes, quão intensos tu não sabes, sim, quão difíceis de suportar tu não sabes."},{"verse":16,"text":"Pois eis que eu, Deus, sofri essas coisas por todos, para que não precisem sofrer caso se arrependam;"},{"verse":17,"text":"Mas se não se arrependerem, terão que sofrer assim como eu sofri;"},{"verse":18,"text":"Sofrimento que fez com que eu, Deus, o mais grandioso de todos, tremesse de dor e sangrasse por todos os poros; e sofresse, tanto no corpo como no espírito — e desejasse não ter de beber a amarga taça e recuar —"},{"verse":19,"text":"Todavia, glória seja para o Pai; eu bebi e terminei meus preparativos para os filhos dos homens."},{"verse":20,"text":"Assim, ordeno outra vez que te arrependas, para que eu não te humilhe com minha onipotência; e que confesses teus pecados para que não sofras esses castigos dos quais falei, os quais experimentaste em pequeníssima, sim, em ínfima proporção, quando retirei meu Espírito."},{"verse":21,"text":"E ordeno-te que nada pregues a não ser arrependimento; e não mostres estas coisas ao mundo até que me pareça prudente."},{"verse":22,"text":"Porque agora não podem tolerar carne, devem receber leite; portanto, não deverão conhecer estas coisas, para que não pereçam."},{"verse":23,"text":"Aprende de mim e ouve minhas palavras; anda na mansidão de meu Espírito e terás paz em mim."},{"verse":24,"text":"Eu sou Jesus Cristo; vim pela vontade do Pai, e cumpro a sua vontade."},{"verse":25,"text":"E também te ordeno que não cobices a mulher de teu próximo; nem procures tirar a vida de teu próximo."},{"verse":26,"text":"E também te ordeno que não te apegues a tua propriedade, mas oferece-a liberalmente para a impressão do Livro de Mórmon, que contém a verdade e a palavra de Deus —"},{"verse":27,"text":"Que é minha palavra aos gentios; para que logo seja levado aos judeus, de quem os lamanitas são remanescentes, para que creiam no evangelho e não mais esperem que venha um Messias que já veio."},{"verse":28,"text":"E também te ordeno que ores em voz alta, assim como em teu coração; sim, perante o mundo, como também em segredo; em público, assim como em particular."},{"verse":29,"text":"E proclamarás boas novas; sim, anuncia-as sobre as montanhas e todos os lugares elevados e a todo povo que te seja permitido ver."},{"verse":30,"text":"E assim farás com toda humildade, confiando em mim, não ofendendo ofensores."},{"verse":31,"text":"E de dogmas não falarás, mas declararás arrependimento e fé no Salvador e remissão de pecados por batismo e por fogo, sim, pelo Espírito Santo."},{"verse":32,"text":"Eis que este é um grande e o último mandamento que te darei quanto a este assunto; pois isto bastará para tua jornada diária, até o fim de tua vida."},{"verse":33,"text":"E sofrimento terás se desprezares estes conselhos, sim, em verdade a destruição de ti mesmo e de tua propriedade."},{"verse":34,"text":"Dá uma porção de teus bens, sim, parte de tuas terras e de tudo, exceto o sustento de tua família."},{"verse":35,"text":"Paga a dívida contraída com o impressor. Livra-te da servidão."},{"verse":36,"text":"Deixa tua casa e teu lar, exceto quando desejares ver tua família;"},{"verse":37,"text":"E fala abertamente a todos; sim, prega, exorta, declara a verdade em alta voz e com tom de regozijo, clamando: Hosana, hosana, bendito seja o nome do Senhor Deus!"},{"verse":38,"text":"Ora sempre e derramarei meu Espírito sobre ti e grande será tua bênção — sim, até maior do que se obtivesses tesouros da Terra e corruptibilidade na mesma medida."},{"verse":39,"text":"Eis que podes ler isto sem te regozijares e encheres de alegria o coração?"},{"verse":40,"text":"Ou podes tu continuar a andar como um guia cego?"},{"verse":41,"text":"Ou podes ser humilde e dócil e conduzires-te sabiamente perante mim? Sim, vem a mim, teu Salvador. Amém."}]},{"chapter":20,"verses":[{"verse":1,"text":"O surgimento da Igreja de Cristo nestes últimos dias, sendo mil oitocentos e trinta anos depois da vinda de nosso Senhor e Salvador Jesus Cristo na carne, tendo a Igreja sido devidamente organizada e estabelecida em conformidade com as leis de nosso país, pela vontade e mandamentos de Deus, no quarto mês e no sexto dia do mês que é chamado abril —"},{"verse":2,"text":"Mandamentos esses dados a Joseph Smith Júnior que foi chamado por Deus e ordenado apóstolo de Jesus Cristo para ser o primeiro élder desta igreja;"},{"verse":3,"text":"E a Oliver Cowdery, que foi também chamado por Deus como apóstolo de Jesus Cristo para ser o segundo élder desta igreja e ordenado sob sua mão;"},{"verse":4,"text":"E isso de acordo com a graça de nosso Senhor e Salvador Jesus Cristo, a quem toda a glória seja dada, agora e para sempre. Amém."},{"verse":5,"text":"Depois de haver sido verdadeiramente manifestado a este primeiro élder que ele recebera a remissão de seus pecados, ele outra vez se emaranhou nas vaidades do mundo;"},{"verse":6,"text":"Mas depois de arrepender-se e humilhar-se sinceramente, pela fé, Deus abençoou-o por meio de um santo anjo cujo semblante era como relâmpago e cujas vestes eram mais puras e brancas do que qualquer outra brancura;"},{"verse":7,"text":"E deu-lhe mandamentos que o inspiraram;"},{"verse":8,"text":"E deu-lhe poder do alto, pelos meios que haviam antes sido preparados, para traduzir o Livro de Mórmon;"},{"verse":9,"text":"Que contém um registro de um povo decaído e a plenitude do evangelho de Jesus Cristo aos gentios e também aos judeus;"},{"verse":10,"text":"O qual foi dado por inspiração e é confirmado a outros pelo ministério de anjos, sendo por eles proclamado ao mundo —"},{"verse":11,"text":"Provando ao mundo que as santas escrituras são verdadeiras e que Deus inspira os homens e chama-os para sua santa obra, nesta época e nesta geração, assim como em gerações passadas;"},{"verse":12,"text":"Mostrando assim que ele é o mesmo Deus ontem, hoje e para sempre. Amém."},{"verse":13,"text":"Portanto, tendo tão grandes testemunhas, por elas será julgado o mundo, tantos quantos daqui em diante tiverem conhecimento desta obra."},{"verse":14,"text":"E os que a receberem com fé e agirem retamente receberão uma coroa de vida eterna;"},{"verse":15,"text":"Mas para aqueles que endurecerem o coração em incredulidade e a rejeitarem, isso se tornará em sua própria condenação —"},{"verse":16,"text":"Porque o Senhor Deus o disse; e nós, os élderes da igreja, ouvimos e testemunhamos as palavras da gloriosa Majestade nas alturas, a quem seja glória para todo o sempre. Amém."},{"verse":17,"text":"Por estas coisas sabemos que há um Deus no céu, que é infinito e eterno, de eternidade a eternidade, o mesmo Deus imutável, o criador do céu e da Terra e de tudo o que neles há;"},{"verse":18,"text":"E que ele criou o homem, homem e mulher, a sua própria imagem e conforme a sua semelhança os criou;"},{"verse":19,"text":"E deu-lhes mandamentos de que deveriam amá-lo e servi-lo, o único Deus vivo e verdadeiro; e que ele seria o único ser a quem deveriam adorar."},{"verse":20,"text":"Mas, pela transgressão dessas santas leis, o homem tornou-se sensual e diabólico e um homem decaído."},{"verse":21,"text":"Portanto, o Deus Todo-Poderoso deu seu Filho Unigênito, como está escrito nessas escrituras que por ele foram dadas."},{"verse":22,"text":"Sofreu tentações, mas não lhes deu atenção."},{"verse":23,"text":"Foi crucificado, morreu e ressuscitou no terceiro dia;"},{"verse":24,"text":"E subiu ao céu, para assentar-se à direita do Pai a fim de reinar em onipotência, de acordo com a vontade do Pai;"},{"verse":25,"text":"Para que todos os que cressem e fossem batizados em seu santo nome e perseverassem com fé, até o fim, fossem salvos —"},{"verse":26,"text":"Não somente os que creram após sua vinda na carne, no meridiano dos tempos, mas todos, desde o princípio, sim, todos os que existiram antes de sua vinda, que creram nas palavras dos santos profetas, os quais falaram segundo foram inspirados pelo dom do Espírito Santo, que verdadeiramente testemunharam a respeito dele em todas as coisas, tivessem vida eterna,"},{"verse":27,"text":"Como também os que viriam depois e creriam nos dons e chamados de Deus pelo Espírito Santo, que presta testemunho do Pai e do Filho;"},{"verse":28,"text":"E o Pai, o Filho e o Espírito Santo são um Deus, infinito e eterno, sem fim. Amém."},{"verse":29,"text":"E sabemos que todos os homens precisam arrepender-se e crer no nome de Jesus Cristo e adorar ao Pai em seu nome e perseverar com fé em seu nome até o fim; do contrário não podem ser salvos no reino de Deus."},{"verse":30,"text":"E sabemos que a justificação pela graça de nosso Senhor e Salvador Jesus Cristo é justa e verdadeira;"},{"verse":31,"text":"E sabemos também que a santificação pela graça de nosso Senhor e Salvador Jesus Cristo é justa e verdadeira, para todos os que amam e servem a Deus com todo o seu poder, mente e força."},{"verse":32,"text":"Mas existe também a possibilidade de que um homem caia da graça e aparte-se do Deus vivo;"},{"verse":33,"text":"Portanto, que a igreja esteja atenta e ore sempre para não cair em tentação;"},{"verse":34,"text":"Sim, até os santificados estejam também atentos."},{"verse":35,"text":"E sabemos que estas coisas são verdadeiras e estão de acordo com as revelações de João, não aumentando nem diminuindo as profecias de seu livro, as santas escrituras ou as revelações de Deus que serão dadas daqui em diante pelo dom e poder do Espírito Santo, pela voz de Deus ou pelo ministério de anjos."},{"verse":36,"text":"E o Senhor Deus disse-o; e honra, poder e glória sejam dados a seu santo nome, agora e para sempre. Amém."},{"verse":37,"text":"E também, por meio de mandamento à igreja com respeito ao modo de batizar: Todos aqueles que se humilharem perante Deus e desejarem ser batizados e se apresentarem com o coração quebrantado e o espírito contrito; e testificarem à igreja que verdadeiramente se arrependeram de todos os seus pecados e estão dispostos a tomar sobre si o nome de Jesus Cristo, tendo o firme propósito de servi-lo até o fim; e realmente manifestarem por suas obras que receberam o Espírito de Cristo para a remissão de seus pecados, serão recebidos pelo batismo na sua igreja."},{"verse":38,"text":"O dever dos élderes, sacerdotes, mestres, diáconos e membros da igreja de Cristo: Um apóstolo é um élder e batizar é seu chamado;"},{"verse":39,"text":"E ordenar outros élderes, sacerdotes, mestres e diáconos;"},{"verse":40,"text":"E administrar o pão e o vinho — os emblemas da carne e sangue de Cristo —"},{"verse":41,"text":"E confirmar os que são batizados na igreja, pela imposição de mãos para o batismo de fogo e do Espírito Santo, de acordo com as escrituras;"},{"verse":42,"text":"E ensinar, explicar, exortar, batizar e zelar pela igreja;"},{"verse":43,"text":"E confirmar a igreja, impondo as mãos e conferindo o Espírito Santo;"},{"verse":44,"text":"E dirigir todas as reuniões."},{"verse":45,"text":"Os élderes devem dirigir as reuniões conforme guiados pelo Espírito Santo, de acordo com os mandamentos e revelações de Deus."},{"verse":46,"text":"O dever do sacerdote é pregar, ensinar, explicar, exortar, batizar e administrar o sacramento."},{"verse":47,"text":"E visitar a casa de todos os membros, exortando-os a orarem em voz alta e em segredo e a cumprirem todas as obrigações familiares."},{"verse":48,"text":"E ele pode também ordenar outros sacerdotes, mestres e diáconos."},{"verse":49,"text":"E deve dirigir as reuniões quando não houver um élder presente;"},{"verse":50,"text":"Mas quando houver um élder presente, deve somente pregar, ensinar, explicar, exortar e batizar."},{"verse":51,"text":"E visitar a casa de todos os membros, exortando-os a orarem em voz alta e em segredo e a cumprirem todas as obrigações familiares."},{"verse":52,"text":"Em todos esses deveres o sacerdote deve assistir o élder, se a ocasião o exigir."},{"verse":53,"text":"O dever do mestre é zelar sempre pela igreja, estar com os membros e fortalecê-los;"},{"verse":54,"text":"E certificar-se que não haja iniquidade na igreja nem aspereza entre uns e outros nem mentiras, maledicências ou calúnias;"},{"verse":55,"text":"E certificar-se que a igreja se reúna amiúde e também certificar-se que todos os membros cumpram seus deveres."},{"verse":56,"text":"E ele deve dirigir as reuniões, na ausência do élder ou sacerdote —"},{"verse":57,"text":"E deve ser auxiliado sempre, em todos os seus deveres na igreja, pelos diáconos, se a ocasião o exigir."},{"verse":58,"text":"Mas nem os mestres nem os diáconos têm autoridade para batizar, administrar o sacramento ou impor as mãos;"},{"verse":59,"text":"Devem, contudo, admoestar, explicar, exortar e ensinar e convidar todos a virem a Cristo."},{"verse":60,"text":"Todo élder, sacerdote, mestre ou diácono deve ser ordenado de acordo com os dons e chamados que de Deus receber; e deve ser ordenado pelo poder do Espírito Santo, que está naquele que o ordena."},{"verse":61,"text":"Os diversos élderes que compõem esta igreja de Cristo devem reunir-se em conferência de três em três meses ou de tempos em tempos, conforme determinado ou designado nessas conferências;"},{"verse":62,"text":"E essas conferências devem tratar qualquer assunto da igreja que necessite ser tratado na ocasião."},{"verse":63,"text":"Os élderes devem receber suas licenças de outros élderes, pelo voto da igreja a que pertencem ou das conferências."},{"verse":64,"text":"Todo sacerdote, mestre ou diácono que é ordenado por um sacerdote pode receber dele, no momento, um certificado que, quando apresentado a um élder, lhe dará direito a uma licença, a qual o autorizará a cumprir os deveres de seu chamado; ou ele pode receber essa licença da conferência."},{"verse":65,"text":"Nenhuma pessoa deve ser ordenada para qualquer ofício nesta igreja, onde houver um ramo devidamente organizado, sem o voto daquela igreja;"},{"verse":66,"text":"Mas os élderes presidentes, os bispos viajantes, os sumos conselheiros, os sumos sacerdotes e os élderes têm o privilégio de fazer ordenações onde não houver ramo da igreja em que se possa convocar uma votação."},{"verse":67,"text":"Todo presidente do sumo sacerdócio (ou élder presidente), bispo, sumo conselheiro e sumo sacerdote deve ser ordenado sob a direção de um sumo conselho ou conferência geral."},{"verse":68,"text":"O dever dos membros depois de terem sido recebidos pelo batismo: Os élderes ou os sacerdotes devem ter tempo suficiente para explicar todas as coisas concernentes à igreja de Cristo, para que eles as compreendam antes de tomarem o sacramento e serem confirmados pela imposição das mãos dos élderes, a fim de que todas as coisas sejam feitas em ordem."},{"verse":69,"text":"E os membros manifestarão perante a igreja e também perante os élderes, por conduta e linguagem piedosas, que são dignos dela, a fim de que haja obras e fé segundo as santas escrituras — andando em santidade perante o Senhor."},{"verse":70,"text":"Todo membro da igreja de Cristo que tiver filhos deverá trazê-los aos élderes diante da igreja, os quais lhes devem impor as mãos em nome de Jesus Cristo, abençoando-os em nome dele."},{"verse":71,"text":"Ninguém pode ser recebido na igreja de Cristo a não ser que tenha alcançado a idade da responsabilidade perante Deus e seja capaz de arrepender-se."},{"verse":72,"text":"O batismo deve ser administrado da seguinte maneira, a todos os que se arrependem:"},{"verse":73,"text":"A pessoa que foi chamada por Deus e tem autoridade de Jesus Cristo para batizar descerá à água com aquele que se apresentou para o batismo e dirá, chamando-o pelo nome: Tendo sido comissionado por Jesus Cristo, eu te batizo em nome do Pai e do Filho e do Espírito Santo. Amém."},{"verse":74,"text":"Então imergirá a pessoa na água e depois sairão da água."},{"verse":75,"text":"É conveniente que a igreja se reúna amiúde para partilhar do pão e do vinho, em lembrança do Senhor Jesus;"},{"verse":76,"text":"E o élder ou o sacerdote administrá-los-á; e desta maneira deverá administrá-los: Ajoelhar-se-á com a igreja e invocará o Pai em solene oração, dizendo:"},{"verse":77,"text":"Ó Deus, Pai Eterno, nós te rogamos em nome de teu Filho, Jesus Cristo, que abençoes e santifiques este pão para as almas de todos os que partilharem dele, para que o comam em lembrança do corpo de teu Filho e testifiquem a ti, ó Deus, Pai Eterno, que desejam tomar sobre si o nome de teu Filho e recordá-lo sempre e guardar os mandamentos que ele lhes deu, para que possam ter sempre consigo o seu Espírito. Amém."},{"verse":78,"text":"A maneira de administrar o vinho: Ele também tomará o cálice e dirá:"},{"verse":79,"text":"Ó Deus, Pai Eterno, nós te rogamos em nome de teu Filho, Jesus Cristo, que abençoes e santifiques este vinho para as almas de todos os que beberem dele, para que o façam em lembrança do sangue de teu Filho, que por eles foi derramado, e testifiquem a ti, ó Deus, Pai Eterno, que sempre se lembram dele, para que possam ter consigo o seu Espírito. Amém."},{"verse":80,"text":"Qualquer membro da igreja de Cristo que transgredir ou for surpreendido em alguma ofensa será tratado como indicam as escrituras."},{"verse":81,"text":"Será dever das diversas igrejas que compõem a igreja de Cristo mandar um ou mais de seus mestres para assistirem às diversas conferências realizadas pelos élderes da igreja,"},{"verse":82,"text":"Com uma lista dos nomes dos diversos membros que se tiverem afiliado à igreja desde a última conferência; ou enviá-la pela mão de algum sacerdote, para que uma lista regular de todos os nomes de toda a igreja seja conservada num livro por um dos élderes, o qual será designado pelos outros élderes de tempos em tempos;"},{"verse":83,"text":"E também para que, se alguém tiver sido expulso da igreja, seu nome seja riscado do registro geral de nomes."},{"verse":84,"text":"Todos os membros que se mudam da igreja onde residem e vão para uma igreja onde não são conhecidos podem levar uma carta atestando que são membros regulares e dignos, atestado esse que poderá ser assinado por qualquer élder ou sacerdote, caso a pessoa que vá receber a carta conheça pessoalmente o élder ou sacerdote; pode ainda ser assinada pelos mestres ou diáconos da igreja."}]},{"chapter":21,"verses":[{"verse":1,"text":"Eis que um registro será escrito entre vós; e nele serás chamado vidente, tradutor, profeta, apóstolo de Jesus Cristo, élder da igreja pela vontade de Deus, o Pai, e pela graça de vosso Senhor Jesus Cristo,"},{"verse":2,"text":"Sendo inspirado pelo Espírito Santo a lançar o alicerce dela e edificá-la para a santíssima fé."},{"verse":3,"text":"Igreja essa organizada e estabelecida no ano de mil oitocentos e trinta de vosso Senhor, no quarto mês e no sexto dia do mês que é chamado abril."},{"verse":4,"text":"Portanto, vós, ou seja, a igreja, dareis ouvidos a todas as palavras e mandamentos que ele vos transmitir à medida que ele os receber, andando em toda santidade diante de mim;"},{"verse":5,"text":"Pois suas palavras recebereis como de minha própria boca, com toda paciência e fé."},{"verse":6,"text":"Porque, assim fazendo, as portas do inferno não prevalecerão contra vós; sim, e o Senhor Deus afastará de vós os poderes das trevas e fará tremerem os céus para o vosso bem e para a glória de seu nome."},{"verse":7,"text":"Pois assim diz o Senhor Deus: Inspirei-o a promover a causa de Sião com grande poder voltado para o bem; e conheço sua diligência e ouvi suas orações."},{"verse":8,"text":"Sim, vi seu pranto por Sião e farei com que já não se lamente por ela; pois chegados são os dias de seu regozijo pela remissão de seus pecados e pelas manifestações de minhas bênçãos sobre suas obras."},{"verse":9,"text":"Pois eis que abençoarei todos os que trabalharem em minha vinha com uma grandiosa bênção e eles acreditarão nas palavras dele, que lhe são dadas por meu intermédio, pelo Consolador, o qual manifesta que Jesus foi crucificado por homens pecadores, pelos pecados do mundo, sim, para a remissão de pecados do coração contrito."},{"verse":10,"text":"Portanto, é-me conveniente que ele seja ordenado por ti, Oliver Cowdery, meu apóstolo;"},{"verse":11,"text":"Sendo esta uma ordenança para ti, que és um élder sob a mão dele, sendo ele o primeiro para ti, para que sejas um élder desta igreja de Cristo, que leva meu nome —"},{"verse":12,"text":"E o primeiro pregador desta igreja, para a igreja e perante o mundo, sim, e perante os gentios; sim, isto diz o Senhor Deus, também aos judeus. Amém."}]},{"chapter":22,"verses":[{"verse":1,"text":"Eis que vos digo que todos os convênios antigos fiz eu com que neste fossem invalidados; e este é um novo e eterno convênio, que era desde o princípio."},{"verse":2,"text":"Portanto, embora seja um homem batizado cem vezes, de nada lhe aproveita, pois não podeis entrar pela porta estreita por meio da lei de Moisés nem por vossas obras mortas."},{"verse":3,"text":"Pois foi por causa de vossas obras mortas que fiz com que este último convênio e esta igreja me fossem edificados, como nos dias antigos."},{"verse":4,"text":"Portanto, entrai pela porta, como ordenei, e não procureis aconselhar a vosso Deus. Amém."}]},{"chapter":23,"verses":[{"verse":1,"text":"Eis que te digo algumas palavras, Oliver. Eis que abençoado és e não estás sob condenação alguma. Acautela-te, porém, contra o orgulho, para que não caias em tentação."},{"verse":2,"text":"Dá a conhecer teu chamado à igreja e também ao mundo; e teu coração será aberto para pregar a verdade de agora em diante e para sempre. Amém."},{"verse":3,"text":"Eis que te digo algumas palavras, Hyrum; pois também não estás sob condenação alguma e teu coração está aberto e tua língua desatada; e teu chamado é para exortar e fortalecer a igreja continuamente. Portanto, teu dever será para com a igreja eternamente; e isto por causa de tua família. Amém."},{"verse":4,"text":"Eis que te digo algumas palavras, Samuel; pois também não estás sob condenação alguma e teu chamado é para exortar e fortalecer a igreja; e ainda não foste chamado para pregar ao mundo. Amém."},{"verse":5,"text":"Eis que te digo algumas palavras, Joseph; pois também não estás sob condenação alguma e teu chamado também é para exortar e fortalecer a igreja; e esse será o teu dever de agora em diante e para sempre. Amém."},{"verse":6,"text":"Eis que te declaro, Joseph Knight, por estas palavras, que deves tomar tua cruz e, ao tomá-la, deves orar vocalmente perante o mundo, assim como em segredo e no seio de tua família e entre teus amigos e em todos os locais."},{"verse":7,"text":"E eis que é teu dever unir-te à igreja verdadeira e fazer com que tuas palavras sejam continuamente de exortação, para que recebas a recompensa do trabalhador. Amém."}]},{"chapter":24,"verses":[{"verse":1,"text":"Eis que foste chamado e escolhido para escrever o Livro de Mórmon e para meu ministério; e livrei-te de tuas aflições e aconselhei-te, pelo que tens sido livrado de todos os teus inimigos e dos poderes de Satanás e das trevas!"},{"verse":2,"text":"Contudo, não tens desculpa para tuas transgressões; portanto, vai e não peques mais."},{"verse":3,"text":"Magnifica teu ofício; e após haveres semeado teus campos e os teres protegido, vai depressa à igreja que está em Colesville, Fayette e Manchester e eles sustentar-te-ão; e abençoá-los-ei tanto espiritual como materialmente;"},{"verse":4,"text":"Mas, caso não te recebam, enviarei sobre eles maldição em vez de bênção."},{"verse":5,"text":"E continuarás a invocar a Deus em meu nome e a escrever as coisas que te serão dadas pelo Consolador e a explicar todas as escrituras à igreja."},{"verse":6,"text":"E no momento preciso ser-te-á dado o que hás de dizer e escrever; e eles deverão ouvir; caso contrário, enviar-lhes-ei maldição em vez de bênção."},{"verse":7,"text":"Pois tu servirás exclusivamente a Sião; e nisto terás força."},{"verse":8,"text":"Sê paciente nas aflições, pois terás muitas; suporta-as, contudo, pois eis que estou contigo até o fim dos teus dias."},{"verse":9,"text":"E nas obras terrenas não terás força, porque teu chamado não é esse. Dedica-te a teu chamado e terás com o que magnificar teu ofício e explicar todas as escrituras e continuar impondo as mãos e confirmando as igrejas."},{"verse":10,"text":"E teu irmão Oliver continuará levando meu nome diante do mundo e da igreja. E não deverá supor que possa falar em demasia sobre a minha causa; e eis que estou com ele até o fim."},{"verse":11,"text":"Em mim terá glória e não em si mesmo, seja em fraqueza ou em força, em cativeiro ou liberdade."},{"verse":12,"text":"E em todos os tempos e em todos os locais abrirá a boca e anunciará meu evangelho como com a voz de uma trombeta, tanto de dia como à noite. E dar-lhe-ei uma força que não é conhecida entre os homens."},{"verse":13,"text":"Não soliciteis milagres a não ser que eu vos ordene, exceto para expulsar demônios, curar os enfermos e contra serpentes venenosas e contra venenos mortíferos;"},{"verse":14,"text":"E estas coisas não fareis, a não ser que vos sejam pedidas por aqueles que as desejarem, a fim de que se cumpram as escrituras; pois agireis de acordo com o que está escrito."},{"verse":15,"text":"E onde quer que entrardes e não vos receberem em meu nome, deixareis maldição em vez de bênção, sacudindo o pó de vossos pés, em testemunho contra eles e limpando os pés pelo caminho."},{"verse":16,"text":"E acontecerá que a quem vos deitar as mãos com violência, ordenareis que seja afligido em meu nome; e eis que, de acordo com vossas palavras, eu o ferirei em meu próprio e devido tempo."},{"verse":17,"text":"E quem contra ti comparecer perante a lei, pela lei será amaldiçoado."},{"verse":18,"text":"E não levarás bolsa nem alforje nem bordões nem duas túnicas, porque a igreja te dará, no momento exato, a comida e o vestuário e os sapatos e o dinheiro e o alforje de que necessitares."},{"verse":19,"text":"Pois tu és chamado para podar vigorosamente a minha vinha, sim, pela última vez; sim, e também todos aqueles a quem ordenaste; e eles seguirão estas normas. Amém."}]},{"chapter":25,"verses":[{"verse":1,"text":"Escuta a voz do Senhor teu Deus, enquanto me dirijo a ti, Emma Smith, minha filha; pois em verdade eu te digo: Todos os que recebem meu evangelho são filhos e filhas em meu reino."},{"verse":2,"text":"Dou-te uma revelação com respeito à minha vontade; e se fores fiel e andares nos caminhos da virtude perante mim, preservar-te-ei a vida, e receberás uma herança em Sião."},{"verse":3,"text":"Eis que teus pecados te são perdoados e és uma mulher eleita, a quem chamei."},{"verse":4,"text":"Não murmures por causa das coisas que não viste, porque foram ocultas a ti e ao mundo, o que considero sábio para um tempo futuro."},{"verse":5,"text":"O dever de teu chamado será confortar meu servo Joseph Smith Júnior, teu marido, em suas aflições, com palavras consoladoras, com espírito de mansidão."},{"verse":6,"text":"E quando ele viajar, irás com ele; e servir-lhe-ás de escrevente enquanto não houver quem o faça, para que eu possa enviar o meu servo Oliver Cowdery aonde eu desejar."},{"verse":7,"text":"E serás ordenada sob suas mãos para explicar as escrituras e exortar a igreja, conforme te for revelado pelo meu Espírito."},{"verse":8,"text":"Pois ele imporá as mãos sobre ti e receberás o Espírito Santo e teu tempo será dedicado a escrever e a aprender muito."},{"verse":9,"text":"E não precisas temer, porque teu marido te apoiará na igreja; pois seu chamado é para benefício deles, a fim de que lhes sejam reveladas todas as coisas que eu desejar, de acordo com sua fé."},{"verse":10,"text":"E em verdade eu te digo que deverás deixar as coisas deste mundo e buscar as coisas de um melhor."},{"verse":11,"text":"E também te será concedido fazer uma seleção de hinos sacros para serem usados em minha igreja conforme te for dado, o que me é agradável."},{"verse":12,"text":"Porque minha alma se deleita com o canto do coração; sim, o canto dos justos é uma prece a mim e será respondido com uma bênção sobre sua cabeça."},{"verse":13,"text":"Portanto, rejubila-te e alegra-te e apega-te aos convênios que fizeste."},{"verse":14,"text":"Continua em espírito de mansidão, acautelando-te contra o orgulho. Que tua alma se deleite em teu marido e na glória que sobre ele virá."},{"verse":15,"text":"Guarda meus mandamentos continuamente e receberás uma coroa de retidão. E, a não ser que faças isso, onde estou não poderás vir."},{"verse":16,"text":"E em verdade, em verdade eu te digo que esta é a minha voz para todos. Amém."}]},{"chapter":26,"verses":[{"verse":1,"text":"Eis que vos digo que devereis dedicar vosso tempo ao estudo das escrituras e à pregação e à confirmação da igreja em Colesville; e à realização de vossos labores na terra, como é requerido, até depois de irdes ao oeste a fim de realizar a próxima conferência; então vos será dado saber o que fareis."},{"verse":2,"text":"E todas as coisas serão feitas de comum acordo na igreja, por meio de muita oração e fé, pois todas as coisas recebereis pela fé. Amém."}]},{"chapter":27,"verses":[{"verse":1,"text":"Ouvi a voz de Jesus Cristo, vosso Senhor, vosso Deus e vosso Redentor, cuja palavra é viva e poderosa."},{"verse":2,"text":"Pois eis que vos digo que não importa o que se come ou o que se bebe ao participar do sacramento, se o fizerdes com os olhos fitos na minha glória — lembrando perante o Pai o meu corpo, que foi sacrificado por vós, e o meu sangue, que foi derramado para a remissão de vossos pecados."},{"verse":3,"text":"Portanto, um mandamento vos dou, que não compreis vinho nem bebida forte de vossos inimigos;"},{"verse":4,"text":"Portanto, nenhum tomareis, a não ser que seja novo, feito por vós, sim, neste reino de meu Pai que será edificado na Terra."},{"verse":5,"text":"Eis que nisto há sabedoria; portanto, não vos maravilheis, porque virá a hora em que, na Terra, beberei do fruto da vide convosco e com Morôni, a quem enviei para vos revelar o Livro de Mórmon, que contém a plenitude do meu evangelho eterno, e a quem confiei as chaves do registro da vara de Efraim;"},{"verse":6,"text":"E também com Elias, a quem confiei as chaves para restaurar todas as coisas mencionadas pela boca de todos os santos profetas, desde o princípio do mundo, concernentes aos últimos dias;"},{"verse":7,"text":"E também João, o filho de Zacarias, Zacarias esse que ele (Elias) visitou, dando-lhe a promessa de um filho que se chamaria João e que seria cheio do espírito de Elias;"},{"verse":8,"text":"E esse João enviei a vós, meus servos Joseph Smith Júnior e Oliver Cowdery, para ordenar-vos ao primeiro sacerdócio que recebestes, a fim de que fôsseis chamados e ordenados como foi Aarão;"},{"verse":9,"text":"E também Elias, o profeta, a quem confiei as chaves do poder de conversão do coração dos pais aos filhos e do coração dos filhos aos pais, para que toda a Terra não fosse ferida com maldição;"},{"verse":10,"text":"E também com José e Jacó e Isaque e Abraão, vossos pais, por meio de quem as promessas permanecem;"},{"verse":11,"text":"E também com Miguel, ou seja, Adão, o pai de todos, o príncipe de todos, o ancião de dias;"},{"verse":12,"text":"E também com Pedro e Tiago e João, que vos enviei, por intermédio de quem vos ordenei e confirmei para serdes apóstolos e testemunhas especiais de meu nome e para portardes as chaves de vosso ministério e das mesmas coisas que a eles revelei;"},{"verse":13,"text":"A quem confiei as chaves de meu reino e uma dispensação do evangelho para os últimos tempos; e para a plenitude dos tempos, quando reunirei em uma todas as coisas, tanto as que estão no céu como as que estão na Terra;"},{"verse":14,"text":"E também com todos os que, do mundo, o Pai me deu."},{"verse":15,"text":"Portanto, alegrai-vos e rejubilai-vos e cingi os lombos e tomai sobre vós toda a minha armadura, para que possais resistir no dia mau, havendo feito tudo, a fim de subsistirdes."},{"verse":16,"text":"Estai, pois, firmes, tendo cingidos os lombos com a verdade, tendo vestida a couraça da retidão e calçados os pés com a preparação do evangelho da paz, o qual, para vos confiar, enviei meus anjos;"},{"verse":17,"text":"Tomando o escudo da fé com o qual podereis apagar todos os dardos inflamados dos iníquos;"},{"verse":18,"text":"E tomai o capacete da salvação e a espada de meu Espírito, que derramarei sobre vós, e minha palavra, que vos revelo; e concordai acerca de todas as coisas que me pedirdes; e sede fiéis até que eu venha e sereis arrebatados, para que onde eu estiver estejais vós também. Amém."}]},{"chapter":28,"verses":[{"verse":1,"text":"Eis que te digo, Oliver, que te será concedido ser ouvido pela igreja em todas as coisas que lhes ensinares por meio do Consolador, a respeito das revelações e dos mandamentos que dei."},{"verse":2,"text":"Mas eis que em verdade, em verdade eu te digo: Ninguém será designado para receber mandamentos e revelações nesta igreja, a não ser meu servo Joseph Smith Júnior porque ele as recebe como Moisés."},{"verse":3,"text":"E tu serás obediente às coisas que eu lhe der, tal como Aarão, para declarar fielmente à igreja, com poder e autoridade, os mandamentos e as revelações."},{"verse":4,"text":"E se em toda e qualquer ocasião fores levado pelo Consolador a falar ou a ensinar, por meio de mandamento à igreja, poderás fazê-lo."},{"verse":5,"text":"Não deverás, porém, escrever por meio de mandamento, mas segundo a sabedoria;"},{"verse":6,"text":"E não darás ordens àquele que está acima de ti e à frente da igreja;"},{"verse":7,"text":"Pois dei a ele as chaves dos mistérios e as revelações que estão seladas, até que lhes designe outro em seu lugar."},{"verse":8,"text":"E agora, eis que eu te digo que irás aos lamanitas para pregar-lhes meu evangelho; e se aceitarem os teus ensinamentos, estabelecerás entre eles a minha igreja; e receberás revelações, mas não as escreverás como mandamentos."},{"verse":9,"text":"E agora, eis que te digo que não foi revelado e nenhum homem sabe onde será construída a cidade de Sião, mas será revelado mais tarde. Eis que te digo que será nas fronteiras, próximo aos lamanitas."},{"verse":10,"text":"Não deverás deixar este local até depois da conferência; e meu servo Joseph será designado, pela voz da conferência, para presidi-la; e o que ele te disser, falarás."},{"verse":11,"text":"E também, deverás procurar teu irmão Hiram Page, em particular, e dizer-lhe que as coisas que ele escreveu por meio daquela pedra não procedem de mim; e que Satanás o iludiu;"},{"verse":12,"text":"Pois eis que essas coisas não lhe foram designadas e a ninguém desta igreja será designada qualquer coisa contrária aos convênios da igreja."},{"verse":13,"text":"Pois todas as coisas na igreja devem ser feitas em ordem e de comum acordo e pela oração da fé."},{"verse":14,"text":"E ajudarás a resolver todas essas coisas, de acordo com os convênios da igreja, antes de iniciares tua viagem entre os lamanitas."},{"verse":15,"text":"E desde o momento em que partires até regressares, ser-te-á indicado o que fazer."},{"verse":16,"text":"E deverás abrir a boca em todas as ocasiões, declarando meu evangelho em tom de regozijo. Amém."}]},{"chapter":29,"verses":[{"verse":1,"text":"Dai ouvidos à voz de Jesus Cristo, vosso Redentor, o Grande Eu Sou, cujo braço de misericórdia expiou vossos pecados;"},{"verse":2,"text":"Que ajuntará seu povo, assim como a galinha ajunta sob as asas seus pintinhos, sim, tantos quantos atenderem à minha voz e se humilharem perante mim e invocarem-me em fervorosa oração."},{"verse":3,"text":"Eis que em verdade, em verdade vos digo que neste momento vossos pecados vos são perdoados e por isso recebeis estas coisas; mas lembrai-vos de não mais pecar para que não vos sobrevenham perigos."},{"verse":4,"text":"Em verdade vos digo que sois escolhidos dentre os do mundo para declarardes meu evangelho com som de regozijo, com a voz como de uma trombeta."},{"verse":5,"text":"Rejubilai-vos e alegrai-vos, porque estou no meio de vós e sou vosso advogado junto ao Pai; e é de seu agrado dar-vos o reino."},{"verse":6,"text":"E, como está escrito: Tudo o que pedirdes com fé, estando unidos em oração, de acordo com minhas ordens, recebereis."},{"verse":7,"text":"E vós sois chamados para efetuardes a reunião de meus eleitos; pois os meus eleitos ouvem a minha voz e não endurecem o coração."},{"verse":8,"text":"Portanto, o Pai decretou que serão reunidos em um mesmo local na face desta terra, a fim de preparar-lhes o coração e para que estejam prontos em todas as coisas para o dia em que tribulações e desolações forem enviadas sobre os iníquos."},{"verse":9,"text":"Porque a hora está próxima e logo vem o dia em que a Terra estará madura; e todos os soberbos e os que praticam iniquidade serão como o restolho; e queimá-los-ei, diz o Senhor dos Exércitos, para que não haja iniquidade sobre a Terra;"},{"verse":10,"text":"Porque a hora está próxima e aquilo que foi dito por meus apóstolos deve ser cumprido; pois como disseram, assim há de acontecer;"},{"verse":11,"text":"Pois revelar-me-ei do céu com poder e grande glória, com todas as suas hostes, e em retidão habitarei com os homens na Terra por mil anos; e os iníquos não permanecerão."},{"verse":12,"text":"E também em verdade, em verdade vos digo que foi proclamado em firme decreto, pela vontade do Pai, que os meus apóstolos, os Doze que estiveram comigo em meu ministério em Jerusalém, postar-se-ão à minha direita, no dia da minha vinda em um pilar de fogo, estando trajados com mantos de retidão, com coroas na cabeça, em glória como eu estou, para julgar toda a casa de Israel, sim, todos os que me amaram e guardaram os meus mandamentos; e ninguém mais."},{"verse":13,"text":"Pois uma trombeta soará longa e estrondosamente, sim, como no Monte Sinai; e toda a Terra estremecerá e eles surgirão — sim, os mortos que morreram em mim, para receber a coroa de retidão e serem vestidos, assim como eu, a fim de estarem comigo, para que sejamos um."},{"verse":14,"text":"Mas eis que vos digo que, antes que venha esse grande dia, o sol escurecerá e a lua tornar-se-á em sangue e as estrelas cairão do céu e haverá maiores sinais acima no céu e embaixo na Terra."},{"verse":15,"text":"E haverá choro e gemidos entre as hostes dos homens;"},{"verse":16,"text":"E será enviada uma grande chuva de pedras para destruir as colheitas da Terra."},{"verse":17,"text":"E acontecerá, por causa da iniquidade do mundo, que eu me vingarei dos ímpios, pois não se arrependerão; porque o cálice de minha indignação está repleto e eis que meu sangue não os purificará se eles não me ouvirem."},{"verse":18,"text":"Portanto, eu, o Senhor Deus, mandarei moscas sobre a face da Terra, as quais se apoderarão de seus habitantes, comer-lhes-ão a carne e farão com que neles se criem bicheiras;"},{"verse":19,"text":"E a língua deles será refreada para que não falem contra mim; e sua carne desprender-se-á dos ossos e seus olhos cairão das órbitas;"},{"verse":20,"text":"E acontecerá que as bestas da floresta e as aves do céu os devorarão."},{"verse":21,"text":"E a grande e abominável igreja, que é a prostituta de toda a Terra, será abatida por fogo devorador, como foi dito pela boca de Ezequiel, o profeta que falou destas coisas, as quais não se cumpriram, mas, tão certamente como eu vivo, cumprir-se-ão, porque não hão de reinar abominações."},{"verse":22,"text":"E também em verdade, em verdade vos digo que quando terminarem os mil anos e os homens novamente começarem a negar seu Deus, então pouparei a Terra, mas por pouco tempo;"},{"verse":23,"text":"E virá o fim; e os céus e a Terra serão consumidos e passarão; e haverá um novo céu e uma nova Terra."},{"verse":24,"text":"Pois todas as coisas velhas passarão e todas as coisas tornar-se-ão novas, sim, o céu e a Terra e toda a sua plenitude, tanto homens como animais, as aves do céu e os peixes do mar;"},{"verse":25,"text":"E nem um único fio de cabelo nem argueiro serão perdidos, pois são obra de minhas mãos."},{"verse":26,"text":"Mas eis que em verdade vos digo: Antes que passe a Terra, Miguel, meu arcanjo, soará sua trombeta e então todos os mortos despertarão, pois suas sepulturas serão abertas e eles surgirão — sim, todos."},{"verse":27,"text":"E os justos serão reunidos à minha direita para a vida eterna; e os iníquos à minha esquerda envergonhar-me-ei de reivindicar perante o Pai;"},{"verse":28,"text":"Portanto, eu lhes direi: Apartai-vos de mim, malditos, para o fogo eterno, preparado para o diabo e seus anjos."},{"verse":29,"text":"E agora, eis que vos digo que nunca, em tempo algum, declarei de minha própria boca que eles voltariam, pois onde eu estou eles não podem vir, porque não têm poder."},{"verse":30,"text":"Lembrai-vos, porém, de que aos homens não são dados todos os meus juízos; e assim como as palavras saíram de minha boca, assim serão cumpridas, para que os primeiros sejam os últimos e para que os últimos sejam os primeiros em todas as coisas que eu criei pela palavra de meu poder, que é o poder de meu Espírito."},{"verse":31,"text":"Pois pelo poder de meu Espírito criei-as; sim, todas as coisas, tanto espirituais como físicas —"},{"verse":32,"text":"Primeiro as espirituais, depois as físicas, o que é o começo de minha obra; e também, primeiro as físicas e depois as espirituais, o que é o fim de minha obra —"},{"verse":33,"text":"Falando-vos para que compreendais naturalmente; mas para mim mesmo, minhas obras não têm fim nem começo; mas isto vos é dado para que compreendais, pois me perguntastes de comum acordo."},{"verse":34,"text":"Portanto, em verdade vos digo que todas as coisas são espirituais para mim e em tempo algum vos dei uma lei que fosse terrena; nem a homem algum nem aos filhos dos homens nem a Adão, vosso pai, a quem criei."},{"verse":35,"text":"Eis que lhe permiti que fosse seu próprio árbitro; e dei-lhe mandamentos, mas nenhum mandamento terreno lhe dei, porque meus mandamentos são espirituais; eles não são naturais nem físicos nem carnais nem sensuais."},{"verse":36,"text":"E aconteceu que Adão, sendo tentado pelo diabo — pois eis que o diabo existiu antes de Adão, pois rebelou-se contra mim, dizendo: Dá-me a tua honra, a qual é o meu poder; e também uma terça parte das hostes do céu ele afastou de mim por causa do arbítrio que possuíam;"},{"verse":37,"text":"E eles foram lançados abaixo e assim surgiram o diabo e seus anjos;"},{"verse":38,"text":"E eis que há um local preparado para eles desde o princípio e esse local é o inferno."},{"verse":39,"text":"E é necessário que o diabo tente os filhos dos homens, ou eles não poderiam ser seus próprios árbitros; porque, se nunca tivessem o amargo, não poderiam conhecer o doce —"},{"verse":40,"text":"Portanto, aconteceu que o diabo tentou Adão e ele comeu do fruto proibido e transgrediu o mandamento, pelo que se tornou sujeito à vontade do diabo porque cedeu à tentação."},{"verse":41,"text":"Portanto, eu, o Senhor Deus, fiz com que ele fosse expulso do Jardim do Éden, de minha presença, por causa de sua transgressão, na qual ele se tornou espiritualmente morto, o que é a primeira morte, a mesma morte que é a última morte, a morte espiritual, que será pronunciada sobre os iníquos quando eu disser: Apartai-vos, malditos."},{"verse":42,"text":"Mas eis que vos digo que eu, o Senhor Deus, permiti a Adão e sua semente que não sofressem a morte física até que eu, o Senhor Deus, mandasse anjos para pregar-lhes o arrependimento e a redenção por meio da fé no nome de meu Filho Unigênito."},{"verse":43,"text":"E assim eu, o Senhor Deus, determinei para o homem os dias de sua provação — para que por sua morte natural ele fosse levantado em imortalidade para a vida eterna, sim, todos os que cressem;"},{"verse":44,"text":"E os que não cressem, para a condenação eterna, pois não podem ser redimidos de sua queda espiritual porque não se arrependem;"},{"verse":45,"text":"Pois eles amam as trevas mais que a luz e suas ações são iníquas e eles recebem seu salário daquele a quem decidem obedecer."},{"verse":46,"text":"Mas eis que vos digo que as criancinhas são redimidas desde a fundação do mundo, por meio de meu Unigênito;"},{"verse":47,"text":"Portanto, não podem pecar, porque a Satanás não é dado poder para tentar criancinhas até que comecem a se tornar responsáveis perante mim;"},{"verse":48,"text":"Pois a elas é concedido de acordo com a minha vontade, segundo o que me apraz, para que grandes coisas sejam requeridas das mãos de seus pais."},{"verse":49,"text":"E outra vez vos digo: a quem, possuindo conhecimento, não ordenei que se arrependesse?"},{"verse":50,"text":"E quanto ao que não possui entendimento, cabe-me agir de acordo com o que está escrito. E agora nada mais vos declaro neste momento. Amém."}]},{"chapter":30,"verses":[{"verse":1,"text":"Eis que te digo, David, que temeste os homens e não confiaste em mim para receber forças, como devias."},{"verse":2,"text":"Mas tua mente tem estado mais nas coisas terrenas do que nas coisas que vêm de mim, teu Criador, e no ministério para o qual foste chamado; não deste ouvidos ao meu Espírito e àqueles que foram colocados acima de ti, mas foste persuadido por aqueles que não ordenei."},{"verse":3,"text":"Portanto, o que te resta é recorrer a mim e refletir sobre as coisas que recebeste."},{"verse":4,"text":"E teu lar será na casa de teu pai até que eu te dê outros mandamentos. E dedicar-te-ás ao ministério na igreja e perante o mundo e nas regiões circunvizinhas. Amém."},{"verse":5,"text":"Eis que te digo, Peter, que farás tua viagem com teu irmão Oliver; porque é chegada a hora em que me é conveniente que abras a boca para proclamar meu evangelho; portanto, não temas, mas dá ouvidos às palavras e aos conselhos de teu irmão."},{"verse":6,"text":"E aflige-te com todas as suas aflições, sempre elevando o teu coração a mim em oração e fé, para a libertação dele e tua, pois dei-lhe poder para edificar minha igreja entre os lamanitas;"},{"verse":7,"text":"E a ninguém designei como seu conselheiro, para estar acima dele na igreja no que se refere aos negócios da igreja, exceto seu irmão Joseph Smith Júnior."},{"verse":8,"text":"Portanto, dá ouvidos a estas coisas e sê diligente na obediência a meus mandamentos; e serás abençoado para a vida eterna. Amém."},{"verse":9,"text":"Eis que eu te digo, meu servo John, que, de agora em diante, começarás a proclamar meu evangelho como com a voz de uma trombeta."},{"verse":10,"text":"E teu trabalho será na casa de teu irmão Philip Burroughs e arredores, sim, onde quer que sejas ouvido, até que eu te ordene partir."},{"verse":11,"text":"E todo o teu trabalho, daqui em diante, será em Sião, com toda a tua alma; sim, abrirás sempre tua boca pela minha causa, não temendo o que o homem possa fazer, porque estou contigo. Amém."}]},{"chapter":31,"verses":[{"verse":1,"text":"Thomas, meu filho, bem-aventurado és tu por causa de tua fé em minha obra."},{"verse":2,"text":"Eis que tens tido muitas aflições por causa de tua família; entretanto abençoarei a ti e a tua família, sim, teus pequeninos; e dia virá em que eles acreditarão e conhecerão a verdade e serão um contigo na minha igreja."},{"verse":3,"text":"Eleva o coração e regozija-te, pois é chegada a hora de tua missão; e tua língua será desatada e anunciarás boas novas de grande alegria a esta geração."},{"verse":4,"text":"Anunciarás as coisas que foram reveladas a meu servo Joseph Smith Júnior. Daqui em diante começarás a pregar, sim, a ceifar o campo que já está branco para ser queimado."},{"verse":5,"text":"Portanto, lança a foice com toda a tua alma e teus pecados te são perdoados; e haverá muitos feixes sobre tuas costas, porque o trabalhador é digno de seu salário. Portanto, a tua família viverá."},{"verse":6,"text":"Eis que em verdade te digo: Deixa-os só por pouco tempo para declarares minha palavra e preparar-lhes-ei um lugar."},{"verse":7,"text":"Sim, abrirei o coração do povo e eles te receberão. E pelas tuas mãos estabelecerei uma igreja;"},{"verse":8,"text":"E tu os fortalecerás e os prepararás para o dia em que serão reunidos."},{"verse":9,"text":"Sê paciente nas aflições, não injuries os que te injuriarem. Governa tua casa com mansidão e sê firme."},{"verse":10,"text":"Eis que te digo que serás como um médico para a Igreja, mas não para o mundo, pois não te receberão."},{"verse":11,"text":"Vai aonde quer que eu deseje e ser-te-á indicado pelo Consolador o que fazer e aonde ir."},{"verse":12,"text":"Ora sempre, para não caíres em tentação e não perderes tua recompensa."},{"verse":13,"text":"Sê fiel até o fim e eis que estou contigo. Estas palavras não são de um homem nem de homens, mas de mim, Jesus Cristo, teu Redentor, pela vontade do Pai. Amém."}]},{"chapter":32,"verses":[{"verse":1,"text":"E agora, concernente a meu servo Parley P. Pratt, eis que lhe digo que, tão certamente como eu vivo, desejo que ele proclame meu evangelho e aprenda de mim e seja manso e humilde de coração."},{"verse":2,"text":"E o que lhe designei é que vá ao deserto, entre os lamanitas, com meus servos Oliver Cowdery e Peter Whitmer Júnior."},{"verse":3,"text":"E Ziba Peterson também irá com eles; e eu mesmo irei com eles e estarei em seu meio; e eu sou seu advogado junto ao Pai e nada prevalecerá contra eles."},{"verse":4,"text":"E darão ouvidos ao que está escrito, sem reivindicar qualquer outra revelação; e deverão orar sempre para que eu torne compreensível o que está escrito."},{"verse":5,"text":"E eles darão ouvidos a estas palavras sem frivolidade; e abençoá-los-ei. Amém."}]},{"chapter":33,"verses":[{"verse":1,"text":"Eis que vos digo, meus servos Ezra e Northrop: Abri os ouvidos e atendei à voz do Senhor vosso Deus, cuja palavra é viva e poderosa, mais penetrante que uma espada de dois gumes, que penetra até dividir as juntas e medulas, alma e espírito; e discerne os pensamentos e as intenções do coração."},{"verse":2,"text":"Pois em verdade, em verdade vos digo que sois chamados para elevar a voz como com o som de uma trombeta, a fim de declarar meu evangelho a uma geração corrompida e perversa."},{"verse":3,"text":"Pois eis que o campo já está branco para a ceifa; e é a décima primeira hora e a última vez que chamarei trabalhadores para a minha vinha."},{"verse":4,"text":"E minha vinha corrompeu-se inteiramente; e não há quem pratique o bem, a não ser alguns; e eles erram em muitos casos por causa das artimanhas sacerdotais, tendo todos a mente corrupta."},{"verse":5,"text":"E em verdade, em verdade vos digo que estabeleci esta igreja e a chamei do deserto."},{"verse":6,"text":"E da mesma forma reunirei meus eleitos dos quatro cantos da Terra, sim, todos os que crerem em mim e atenderem à minha voz."},{"verse":7,"text":"Sim, em verdade, em verdade vos digo que o campo já está branco para a ceifa; portanto, lançai vossas foices e ceifai com todo o poder, mente e força."},{"verse":8,"text":"Abri vossa boca e ela encher-se-á e tornar-vos-eis como Néfi de outrora, que viajou de Jerusalém pelo deserto."},{"verse":9,"text":"Sim, abri vossa boca e não vos caleis; e haverá muitos feixes sobre vossas costas, pois eis que estou convosco."},{"verse":10,"text":"Sim, abri vossa boca e ela encher-se-á, dizendo: Arrependei-vos, arrependei-vos e preparai o caminho do Senhor e endireitai suas veredas; pois o reino do céu está próximo;"},{"verse":11,"text":"Sim, arrependei-vos e sede batizados, cada um de vós, para a remissão de vossos pecados; sim, sede batizados com água e então virá o batismo do fogo e do Espírito Santo."},{"verse":12,"text":"Eis que em verdade, em verdade vos digo: Este é o meu evangelho; e lembrai-vos de que eles terão fé em mim ou de modo algum poderão ser salvos;"},{"verse":13,"text":"E sobre esta rocha edificarei a minha igreja; sim, sobre esta rocha estais edificados e, se perseverardes, as portas do inferno não prevalecerão contra vós."},{"verse":14,"text":"E lembrar-vos-eis das regras e convênios da igreja para observá-los."},{"verse":15,"text":"E os que tiverem fé confirmareis na minha igreja, pela imposição das mãos, e conceder-lhes-ei o dom do Espírito Santo."},{"verse":16,"text":"E o Livro de Mórmon e as santas escrituras são dadas por mim para vossa instrução; e o poder de meu Espírito vivifica todas as coisas."},{"verse":17,"text":"Portanto, sede fiéis, orando sempre, mantendo vossas lâmpadas preparadas e acesas e tendo convosco óleo, para que estejais prontos na vinda do Esposo —"},{"verse":18,"text":"Porque eis que em verdade, em verdade vos digo que depressa venho. Assim seja. Amém."}]},{"chapter":34,"verses":[{"verse":1,"text":"Meu filho Orson, escuta, ouve e considera o que te direi eu, o Senhor Deus, Jesus Cristo, teu Redentor;"},{"verse":2,"text":"A luz e a vida do mundo, uma luz que resplandece nas trevas e as trevas não a compreendem;"},{"verse":3,"text":"Aquele que amou o mundo de tal maneira que deu a própria vida para que todos os que cressem pudessem tornar-se os filhos de Deus. Portanto, tu és meu filho;"},{"verse":4,"text":"E bem-aventurado és porque creste;"},{"verse":5,"text":"E mais bem-aventurado és porque foste chamado por mim para pregar meu evangelho —"},{"verse":6,"text":"Para elevar a tua voz como que com o som de uma trombeta, longa e estrondosamente, e clamar arrependimento a uma geração corrompida e perversa, preparando o caminho do Senhor para a sua segunda vinda."},{"verse":7,"text":"Pois eis que em verdade, em verdade eu te digo: Aproxima-se o tempo em que virei em uma nuvem, com poder e grande glória."},{"verse":8,"text":"E será um grande dia ao tempo da minha vinda, porque todas as nações estremecerão."},{"verse":9,"text":"Mas antes que venha esse grande dia, o sol escurecerá e a lua tornar-se-á em sangue; e as estrelas recusarão seu brilho e algumas cairão; e grandes destruições aguardam os iníquos."},{"verse":10,"text":"Portanto, eleva a tua voz e não te cales, porque o Senhor Deus falou; portanto, profetiza e ser-te-á dado pelo poder do Espírito Santo."},{"verse":11,"text":"E se fores fiel, eis que estou contigo até a minha vinda —"},{"verse":12,"text":"E em verdade, em verdade eu te digo: Depressa venho. Eu sou teu Senhor e teu Redentor. Assim seja. Amém."}]},{"chapter":35,"verses":[{"verse":1,"text":"Ouvi a voz do Senhor vosso Deus, sim, o Alfa e o Ômega, o princípio e o fim, cujo caminho é um círculo eterno, o mesmo hoje, ontem e para sempre."},{"verse":2,"text":"Eu sou Jesus Cristo, o Filho de Deus, que foi crucificado pelos pecados do mundo, sim, de todos os que crerem em meu nome, para que se tornem filhos de Deus, sim, um em mim, como eu sou um no Pai, como o Pai é um em mim, para que sejamos um."},{"verse":3,"text":"Eis que em verdade, em verdade digo a meu servo Sidney: Tenho olhado para ti e tuas obras. Ouvi tuas orações e preparei-te para uma obra maior."},{"verse":4,"text":"Bendito és porque farás grandes coisas. Eis que foste enviado, assim como João, para preparar o caminho diante de mim e diante de Elias, o profeta, que deveria vir e tu não o sabias."},{"verse":5,"text":"Tu batizaste com água para o arrependimento, mas eles não receberam o Espírito Santo;"},{"verse":6,"text":"Mas agora, dou-te o mandamento de batizar com água e eles receberão o Espírito Santo pela imposição das mãos, assim como os apóstolos da antiguidade."},{"verse":7,"text":"E acontecerá que uma grande obra se realizará na terra, sim, entre os gentios, pois sua loucura e suas abominações serão manifestadas aos olhos de todo o povo."},{"verse":8,"text":"Pois eu sou Deus e meu braço não está encolhido; e mostrarei milagres, sinais e maravilhas a todos os que crerem em meu nome."},{"verse":9,"text":"E os que pedirem em meu nome, com fé, expulsarão demônios; curarão doentes; farão com que cegos vejam e surdos ouçam e mudos falem e coxos andem."},{"verse":10,"text":"E rapidamente se aproxima o tempo em que se mostrarão grandes coisas aos filhos dos homens;"},{"verse":11,"text":"Mas sem fé nada será mostrado, exceto desolações sobre Babilônia, a mesma que fez com que todas as nações bebessem do vinho da ira de sua fornicação."},{"verse":12,"text":"E não há quem faça o bem, exceto os que estão prontos para receber a plenitude do meu evangelho, que enviei a esta geração."},{"verse":13,"text":"Portanto, recorro às coisas fracas do mundo, aos que são indoutos e desprezados, para que debulhem as nações pelo poder do meu Espírito;"},{"verse":14,"text":"E o braço deles será o meu braço e serei seu escudo e seu broquel e cingir-lhes-ei os lombos e eles lutarão virilmente por mim; e seus inimigos estarão sob seus pés; e deixarei cair a espada em seu favor e pelo fogo de minha indignação preservá-los-ei."},{"verse":15,"text":"E aos pobres e mansos será pregado o evangelho; e eles estarão esperando a hora de minha vinda, pois está próxima —"},{"verse":16,"text":"E aprenderão a parábola da figueira, pois já se aproxima o verão."},{"verse":17,"text":"E enviei a plenitude do meu evangelho pela mão de meu servo Joseph; e na fraqueza abençoei-o;"},{"verse":18,"text":"E dei-lhe as chaves do mistério das coisas que foram seladas, sim, das que existiram desde a fundação do mundo e das que virão, a partir de agora até a ocasião de minha vinda, se ele permanecer em mim; e, se não, porei outro em seu lugar."},{"verse":19,"text":"Portanto, vela por ele para que sua fé não desfaleça; e isso será dado pelo Consolador, o Espírito Santo, que sabe todas as coisas."},{"verse":20,"text":"E dou-te um mandamento — que escrevas por ele; e as escrituras serão dadas tal como se acham em meu próprio seio, para salvação de meus eleitos;"},{"verse":21,"text":"Pois hão de ouvir a minha voz e ver-me e não estarão adormecidos, podendo suportar o dia de minha vinda; porque estarão purificados, assim como eu sou puro."},{"verse":22,"text":"E agora te digo: Permanece com ele e ele viajará contigo; não o desampares e certamente estas coisas serão cumpridas."},{"verse":23,"text":"E quando não estiveres escrevendo, eis que a ele será permitido profetizar; e pregarás meu evangelho e citarás os santos profetas para comprovar as palavras dele, conforme lhe forem dadas."},{"verse":24,"text":"Guardai todos os mandamentos e convênios com que estais comprometidos e eu farei com que os céus estremeçam para o vosso bem; e Satanás há de tremer e Sião há de rejubilar-se sobre os montes e florescer;"},{"verse":25,"text":"E Israel será salvo em meu próprio e devido tempo; e pelas chaves que dei será guiado e não mais será confundido."},{"verse":26,"text":"Rejubilai-vos e alegrai-vos, vossa redenção aproxima-se."},{"verse":27,"text":"Não temais, pequeno rebanho, o reino é vosso até minha vinda. Eis que depressa venho. Assim seja. Amém."}]},{"chapter":36,"verses":[{"verse":1,"text":"Assim diz o Senhor Deus, o Poderoso de Israel: Eis que te digo, meu servo Edward, que bendito és tu e teus pecados te são perdoados; e és chamado para pregar o meu evangelho como com a voz de uma trombeta."},{"verse":2,"text":"E imporei sobre ti minha mão, pela mão de meu servo Sidney Rigdon, e tu receberás meu Espírito, o Espírito Santo, o Consolador, que te ensinará as coisas pacíficas do reino;"},{"verse":3,"text":"E anunciá-las-ás em alta voz, dizendo: Hosana, bendito seja o nome do Deus Altíssimo."},{"verse":4,"text":"E agora te dou este chamado e mandamento, concernente a todos os homens:"},{"verse":5,"text":"Que todos os que se apresentarem a meus servos Sidney Rigdon e Joseph Smith Júnior abraçando este chamado e mandamento, sejam ordenados e enviados a pregar o evangelho eterno entre as nações —"},{"verse":6,"text":"Clamando arrependimento e dizendo: Salvai-vos desta geração perversa e saí do fogo, odiando até mesmo as vestes manchadas com a carne."},{"verse":7,"text":"E esse mandamento será dado aos élderes de minha igreja, para que todo homem que o abrace com sinceridade de coração seja ordenado e enviado como eu disse."},{"verse":8,"text":"Eu sou Jesus Cristo, o Filho de Deus; portanto, cinge os teus lombos e de repente eu virei ao meu templo. Assim seja. Amém."}]},{"chapter":37,"verses":[{"verse":1,"text":"Eis que vos digo que não me convém traduzirdes mais até irdes para o Ohio; e isto por causa do inimigo e para o vosso bem."},{"verse":2,"text":"E outra vez vos digo que não devereis ir até que tenhais pregado meu evangelho naquela região e fortalecido a igreja onde quer que ela se encontre e mais especialmente em Colesville; pois eis que eles oram a mim com muita fé."},{"verse":3,"text":"E também um mandamento dou à igreja, que me convém que se reúnam no Ohio, em preparação para quando a eles regressar meu servo Oliver Cowdery."},{"verse":4,"text":"Eis que nisto há sabedoria; e que todo homem escolha por si mesmo até que eu venha. Assim seja. Amém."}]},{"chapter":38,"verses":[{"verse":1,"text":"Assim diz o Senhor vosso Deus, Jesus Cristo, o Grande Eu Sou, o Alfa e o Ômega, o princípio e o fim, aquele que olhou por sobre a vasta extensão da eternidade e todas as hostes seráficas dos céus antes que o mundo fosse feito;"},{"verse":2,"text":"Aquele que conhece todas as coisas, porque todas as coisas estão presentes diante de meus olhos;"},{"verse":3,"text":"Eu sou aquele que falou e o mundo foi feito; e todas as coisas por mim vieram a existir."},{"verse":4,"text":"Sou aquele que arrebatou a Sião de Enoque para meu próprio seio; e em verdade eu digo que todos os que creram em meu nome, pois eu sou Cristo, e em meu próprio nome, em virtude do sangue que derramei, por eles intercedi perante o Pai."},{"verse":5,"text":"Mas eis que o restante dos iníquos mantive em cadeias de trevas até o julgamento do grande dia, que se dará no fim da Terra;"},{"verse":6,"text":"E assim farei que sejam mantidos os iníquos que não ouvirem a minha voz, mas endurecerem o coração; e terrível é sua condenação."},{"verse":7,"text":"Mas eis que em verdade, em verdade vos digo que meus olhos estão sobre vós. Estou no meio de vós e não me podeis ver;"},{"verse":8,"text":"Mas logo vem o dia em que me vereis e sabereis que eu sou; porque o véu da escuridão logo será rasgado e aquele que não estiver purificado não suportará esse dia."},{"verse":9,"text":"Portanto, cingi vossos lombos e preparai-vos. Eis que o reino é vosso e o inimigo não prevalecerá."},{"verse":10,"text":"Em verdade vos digo que sois limpos, mas não todos; e ninguém mais há com quem me compraza;"},{"verse":11,"text":"Pois toda carne está corrompida diante de mim; e os poderes das trevas prevalecem na Terra, entre os filhos dos homens, na presença de todas as hostes do céu —"},{"verse":12,"text":"Pelo que reina o silêncio e toda a eternidade está aflita; e os anjos esperam o grande comando para ceifar a Terra, para colher o joio a fim de ser queimado; e eis que o inimigo está reunido."},{"verse":13,"text":"E agora eu vos revelo um mistério, uma coisa que se acha em câmaras secretas para, com o passar do tempo, causar vossa destruição; e não o sabíeis;"},{"verse":14,"text":"Mas agora vo-lo digo e benditos sois, não por causa de vossa iniquidade nem de vosso coração incrédulo; pois em verdade alguns de vós sois culpados perante mim, mas serei misericordioso com vossas fraquezas."},{"verse":15,"text":"Portanto, sede fortes de agora em diante; não temais, pois o reino é vosso."},{"verse":16,"text":"E para vossa salvação dou-vos um mandamento, pois ouvi vossas orações; e os pobres têm-se queixado perante mim e os ricos fiz eu; e toda carne é minha e não faço acepção de pessoas."},{"verse":17,"text":"E fiz rica a Terra e eis que é o meu escabelo; portanto, sobre ela tornarei a ficar de pé."},{"verse":18,"text":"E agora vos ofereço e considero apropriado dar-vos maiores riquezas, sim, uma terra de promissão, uma terra que mana leite e mel, sobre a qual não haverá maldição quando o Senhor vier;"},{"verse":19,"text":"E dá-la-ei a vós, como terra de vossa herança, se a buscardes de todo o coração."},{"verse":20,"text":"E este será meu convênio convosco: Vós a recebereis como terra de vossa herança e como herança de vossos filhos para sempre, enquanto a Terra durar; e tornareis a possuí-la na eternidade, para não mais passar."},{"verse":21,"text":"Mas em verdade vos digo que tempo virá em que não tereis rei nem governante, porque eu serei vosso rei e olharei por vós."},{"verse":22,"text":"Portanto, ouvi a minha voz e segui-me; e sereis um povo livre e não tereis leis a não ser as minhas leis, quando eu vier, porque sou o vosso legislador; e o que pode deter minha mão?"},{"verse":23,"text":"Mas em verdade vos digo: Ensinai-vos uns aos outros, de acordo com o ofício para o qual vos designei;"},{"verse":24,"text":"E que todo homem estime a seu irmão como a si mesmo e pratique a virtude e a santidade diante de mim."},{"verse":25,"text":"E novamente vos digo: Que todo homem estime a seu irmão como a si mesmo."},{"verse":26,"text":"Pois qual é o homem entre vós que, tendo doze filhos que o servem obedientemente e não faz acepção deles, diz a um: Veste-te com mantos e senta-te aqui; e ao outro: Veste-te com trapos e senta-te acolá — e, olhando para seus filhos, diria: Sou justo?"},{"verse":27,"text":"Eis que isto vos dei como parábola e é como eu sou. Digo-vos: Sede um; e se não sois um, não sois meus."},{"verse":28,"text":"E outra vez vos digo que o inimigo nas câmaras secretas procura tirar-vos a vida."},{"verse":29,"text":"Ouvis falar de guerras em países distantes e dizeis que logo haverá grandes guerras em países distantes, mas não conheceis o coração dos homens em vossa própria terra."},{"verse":30,"text":"Digo-vos estas coisas por causa de vossas orações; portanto, acumulai sabedoria em vosso íntimo, para que a maldade dos homens não vos revele estas coisas, pela sua iniquidade, de uma forma que vos fale ao ouvido com voz mais alta do que aquela que estremecerá a Terra; mas se estiverdes preparados, não temereis."},{"verse":31,"text":"E para que escapeis ao poder do inimigo e vos unais a mim como um povo digno, sem mancha nem culpa —"},{"verse":32,"text":"Portanto, por esta razão vos dei o mandamento de que fôsseis para o Ohio; e lá vos darei minha lei e lá sereis investidos de poder do alto;"},{"verse":33,"text":"E de lá os que eu desejar irão a todas as nações e ser-lhes-á dito o que fazer; eis que tenho uma grande obra reservada, pois Israel será salvo e guiá-lo-ei para onde eu desejar; e nenhum poder deterá minha mão."},{"verse":34,"text":"E agora dou à igreja, nesta região, o mandamento de designar certos homens; e serão designados pela voz da igreja;"},{"verse":35,"text":"E eles cuidarão dos pobres e necessitados e ministrar-lhes-ão auxílio para que não sofram; e deverão enviá-los para onde ordenei que fossem."},{"verse":36,"text":"E este será o seu trabalho: administrar os negócios das propriedades desta igreja."},{"verse":37,"text":"E os que têm fazendas que não possam ser vendidas, que as deixem ou aluguem, como lhes parecer melhor."},{"verse":38,"text":"Certificai-vos de que todas as coisas sejam preservadas; e quando homens forem investidos de poder do alto e enviados, todas essas coisas serão reunidas no seio da igreja."},{"verse":39,"text":"E se buscardes as riquezas que é da vontade do Pai vos dar, sereis o mais rico de todos os povos, porque tereis as riquezas da eternidade; e é necessário que as riquezas da Terra sejam minhas para dá-las; mas precavei-vos contra o orgulho, para que não vos torneis como os nefitas de outrora."},{"verse":40,"text":"E outra vez vos digo: Dou-vos um mandamento de que todos os homens, sejam élderes, sacerdotes, mestres e também os membros, dediquem-se com vigor, com o trabalho de suas mãos, à preparação e execução das coisas que ordenei."},{"verse":41,"text":"E que vossa pregação seja a voz de advertência de cada homem a seu próximo, com brandura e mansidão."},{"verse":42,"text":"E saí do meio dos iníquos. Salvai-vos. Sede limpos, vós que portais os vasos do Senhor. Assim seja. Amém."}]},{"chapter":39,"verses":[{"verse":1,"text":"Escuta e dá ouvidos à voz daquele que é de toda a eternidade a toda a eternidade, o Grande Eu Sou, sim, Jesus Cristo —"},{"verse":2,"text":"A luz e a vida do mundo; uma luz que resplandece nas trevas e as trevas não a compreendem;"},{"verse":3,"text":"O mesmo que vim aos meus no meridiano dos tempos e os meus não me receberam;"},{"verse":4,"text":"Mas a todos os que me receberam dei poder para tornarem-se meus filhos; e também, a todos os que me receberem darei poder para tornarem-se meus filhos."},{"verse":5,"text":"E em verdade, em verdade eu te digo: Aquele que recebe o meu evangelho, a mim me recebe; e o que não recebe o meu evangelho, não me recebe a mim."},{"verse":6,"text":"E este é o meu evangelho: Arrependimento e batismo na água; e depois o batismo do fogo e do Espírito Santo, sim, o Consolador, o qual manifesta todas as coisas e ensina as coisas pacíficas do reino."},{"verse":7,"text":"E agora, eis que te digo, meu servo James: Tenho observado tuas obras e conheço-te."},{"verse":8,"text":"E em verdade eu te digo: Teu coração é agora reto diante de mim; e eis que sobre tua cabeça conferi grandes bênçãos;"},{"verse":9,"text":"Entretanto conheceste grandes tristezas, porque me rejeitaste muitas vezes por causa do orgulho e dos cuidados do mundo."},{"verse":10,"text":"Mas eis que chegados são os dias de tua libertação, se atenderes à minha voz, que te diz: Levanta-te e sê batizado e lava teus pecados, invocando meu nome; e receberás o meu Espírito e uma bênção maior do que todas as que jamais conheceste."},{"verse":11,"text":"E se fazes isto, preparei-te para um trabalho maior. Tu pregarás a plenitude do meu evangelho, o qual enviei nestes últimos dias, o convênio que enviei para recuperar meu povo, que é da casa de Israel."},{"verse":12,"text":"E acontecerá que o poder descansará sobre ti; terás grande fé e eu estarei contigo e irei adiante de tua face."},{"verse":13,"text":"Tu és chamado para trabalhar em minha vinha e para edificar minha igreja e para trazer Sião à luz, para que se regozije sobre os montes e floresça."},{"verse":14,"text":"Eis que em verdade, em verdade te digo que não és chamado para ir às terras do leste, mas és chamado a fim de ir para o Ohio."},{"verse":15,"text":"E sendo que meu povo há de reunir-se no Ohio, reservei-lhes uma bênção que não é conhecida entre os filhos dos homens e que será derramada sobre suas cabeças. E de lá homens sairão para todas as nações."},{"verse":16,"text":"Eis que em verdade, em verdade te digo que o povo em Ohio clama a mim com grande fé, crendo que deterei meu julgamento de sobre as nações; mas não posso negar minha palavra."},{"verse":17,"text":"Portanto, aplica-te com vigor e chama trabalhadores fiéis para minha vinha, a fim de que seja podada pela última vez."},{"verse":18,"text":"E quando se arrependerem e aceitarem a plenitude do meu evangelho e tornarem-se santificados, deterei meu julgamento."},{"verse":19,"text":"Portanto, prossegue, clamando em alta voz, dizendo: O reino dos céus está próximo; clamando: Hosana! Bendito seja o nome do Deus Altíssimo."},{"verse":20,"text":"Segue batizando com água, preparando o caminho diante da minha face, para a hora de minha vinda;"},{"verse":21,"text":"Porque o tempo se aproxima; o dia ou a hora ninguém sabe, mas certamente virá."},{"verse":22,"text":"E o que recebe estas coisas, a mim me recebe; e eles serão reunidos comigo nesta vida e na eternidade."},{"verse":23,"text":"E também acontecerá que sobre todos os que batizares com água imporás as mãos; e eles receberão o dom do Espírito Santo e estarão aguardando os sinais da minha vinda e conhecer-me-ão."},{"verse":24,"text":"Eis que depressa venho. Assim seja. Amém."}]},{"chapter":40,"verses":[{"verse":1,"text":"Eis que em verdade vos digo que o coração de meu servo James Covel era reto diante de mim, pois fizera comigo convênio de que obedeceria à minha palavra."},{"verse":2,"text":"E ele recebeu a palavra com alegria, mas imediatamente Satanás o tentou; e o temor da perseguição e os cuidados do mundo fizeram-no rejeitar a palavra."},{"verse":3,"text":"Portanto, quebrou meu convênio e cabe a mim fazer com ele o que me parecer melhor. Amém."}]},{"chapter":41,"verses":[{"verse":1,"text":"Escutai e dai ouvidos, ó vós, meu povo, diz o Senhor e vosso Deus, vós, que me deleito em abençoar com as maiores de todas as bênçãos, vós que me dais ouvidos; e vós, que não me ouvis e que professastes meu nome, amaldiçoarei com a mais pesada de todas as maldições."},{"verse":2,"text":"Escutai, ó élderes da minha igreja a quem chamei: Eis que vos dou o mandamento de vos reunirdes para chegardes a um acordo quanto à minha palavra;"},{"verse":3,"text":"E pela oração de vossa fé recebereis minha lei, para que saibais como governar minha igreja e como ter todas as coisas em ordem perante mim."},{"verse":4,"text":"E serei vosso governante quando eu vier e eis que depressa venho; e fareis com que minha lei seja guardada."},{"verse":5,"text":"Aquele que recebe a minha lei e a pratica é meu discípulo; e aquele que diz que a recebe e não a pratica, esse não é meu discípulo e será expulso de vosso meio;"},{"verse":6,"text":"Pois não é certo que as coisas que pertencem aos filhos do reino sejam dadas aos que não são dignos, ou aos cães; ou que as pérolas sejam lançadas aos porcos."},{"verse":7,"text":"E também, é certo que meu servo Joseph Smith Júnior mande construir uma casa onde morar e traduzir."},{"verse":8,"text":"E também é certo que meu servo Sidney Rigdon viva como bem lhe pareça, contanto que guarde meus mandamentos."},{"verse":9,"text":"E também chamei meu servo Edward Partridge; e dou o mandamento de que seja designado pela voz da igreja e ordenado bispo da igreja; e que deixe seu negócio e empregue todo o seu tempo no serviço da igreja;"},{"verse":10,"text":"Para cuidar de todas as coisas, conforme lhe for designado nas minhas leis no dia em que eu as der."},{"verse":11,"text":"E isso porque seu coração é puro perante mim, pois ele é semelhante a Natanael dos tempos antigos, em quem não havia dolo."},{"verse":12,"text":"Estas palavras são dadas a vós e são puras diante de mim; portanto, tende cuidado com o modo como as tratais, porque vossas almas responderão por elas no dia do juízo. Assim seja. Amém."}]},{"chapter":42,"verses":[{"verse":1,"text":"Escutai, ó vós, élderes de minha igreja, que vos reunistes em meu nome, sim, Jesus Cristo, o Filho do Deus vivo, o Salvador do mundo; porquanto credes em meu nome e guardais meus mandamentos."},{"verse":2,"text":"Outra vez vos digo: Escutai e dai ouvidos e obedecei à lei que vos darei."},{"verse":3,"text":"Pois em verdade eu digo: Como vos reunistes de acordo com o mandamento que vos dei e estais de acordo no tocante a isto e invocaste o Pai em meu nome, assim recebereis."},{"verse":4,"text":"Eis que em verdade vos digo: Dou-vos este primeiro mandamento de que devereis ir em meu nome, cada um de vós, exceto meus servos Joseph Smith Júnior e Sidney Rigdon."},{"verse":5,"text":"E dou-lhes o mandamento de que deverão ir por pouco tempo; e pelo poder do Espírito ser-lhes-á dado saber quando regressar."},{"verse":6,"text":"Ireis no poder do meu Espírito, pregando meu evangelho, de dois em dois, em meu nome, elevando vossas vozes como com o som de uma trombeta, declarando minha palavra como anjos de Deus."},{"verse":7,"text":"E saireis batizando com água e dizendo: Arrependei-vos, arrependei-vos, pois o reino dos céus está próximo."},{"verse":8,"text":"E, partindo deste local, entrareis nas regiões do lado oeste; e à medida que encontrardes pessoas que vos aceitem, estabelecereis minha igreja em cada região —"},{"verse":9,"text":"Até que venha o tempo em que vos seja revelado do alto, quando a cidade de Nova Jerusalém será preparada a fim de que sejais reunidos em um, para serdes o meu povo; e eu serei o vosso Deus."},{"verse":10,"text":"E também vos digo que meu servo Edward Partridge ocupará o cargo para o qual o designei; e acontecerá que, se ele transgredir, outro será designado em seu lugar. Assim seja. Amém."},{"verse":11,"text":"E também vos digo que a ninguém será permitido sair a pregar meu evangelho ou estabelecer minha igreja, a não ser que tenha sido ordenado por alguém que tenha autoridade; e que a igreja saiba que tem autoridade e foi apropriadamente ordenado pelos dirigentes da igreja."},{"verse":12,"text":"E também os élderes, sacerdotes e mestres desta igreja ensinarão os princípios de meu evangelho que estão na Bíblia e no Livro de Mórmon, no qual se acha a plenitude do evangelho."},{"verse":13,"text":"E observarão os convênios e regras da igreja e cumpri-los-ão e estes serão seus ensinamentos, conforme forem dirigidos pelo Espírito."},{"verse":14,"text":"E o Espírito ser-vos-á dado pela oração da fé; e se não receberdes o Espírito, não ensinareis."},{"verse":15,"text":"E tudo isto fareis como vos ordenei com respeito ao vosso ensino, até que seja dada a plenitude de minhas escrituras."},{"verse":16,"text":"E ao elevardes vossa voz pelo Consolador, falareis e profetizareis como me parecer melhor;"},{"verse":17,"text":"Porque eis que o Consolador conhece todas as coisas e presta testemunho do Pai e do Filho."},{"verse":18,"text":"E agora, eis que falo à igreja. Não matarás; e o que matar não terá perdão neste mundo nem no mundo vindouro."},{"verse":19,"text":"E outra vez, digo: Não matarás; mas o que matar morrerá."},{"verse":20,"text":"Não furtarás; o que furtar e não se arrepender será expulso."},{"verse":21,"text":"Não mentirás; o que mentir e não se arrepender será expulso."},{"verse":22,"text":"Amarás tua esposa de todo o teu coração e a ela te apegarás e a nenhuma outra."},{"verse":23,"text":"E aquele que olhar uma mulher para a cobiçar negará a fé e não terá o Espírito; e se não se arrepender, será expulso."},{"verse":24,"text":"Não cometerás adultério; e o que cometer adultério e não se arrepender será expulso."},{"verse":25,"text":"Mas o que haja cometido adultério e se arrepender de todo o coração e abandoná-lo e não mais o cometer, perdoarás;"},{"verse":26,"text":"Mas, se o fizer outra vez, não será perdoado, mas será expulso."},{"verse":27,"text":"Não falarás mal de teu próximo nem lhe farás mal algum."},{"verse":28,"text":"Sabes que as minhas leis com respeito a estas coisas são dadas nas minhas escrituras; o que pecar e não se arrepender será expulso."},{"verse":29,"text":"Se me amares, servir-me-ás e guardarás todos os meus mandamentos."},{"verse":30,"text":"E eis que te lembrarás dos pobres e consagrarás de tuas propriedades, para sustento deles, aquilo que tiveres para lhes dar, com um convênio e uma promessa que não poderão ser violados."},{"verse":31,"text":"E se deres de teus bens aos pobres, a mim o farás; e eles serão entregues ao bispo de minha igreja e seus conselheiros, dois dos élderes ou sumos sacerdotes que ele indicar ou tiver indicado e designado para esse propósito."},{"verse":32,"text":"E acontecerá que, uma vez entregues ao bispo de minha igreja e depois de haver ele recebido esses testemunhos concernentes à consagração das propriedades de minha igreja, de modo que elas não possam ser tomadas da igreja, conforme os meus mandamentos, todo homem será responsável perante mim, um mordomo de seus próprios bens ou do que tiver recebido por consagração, aquilo que for suficiente para si e sua família."},{"verse":33,"text":"E também, se houver propriedades nas mãos da igreja ou de qualquer de seus membros após esta primeira consagração, mais do que o necessário para seu sustento, o que for um resíduo a ser consagrado ao bispo será conservado para que, de tempos em tempos, seja dado aos que não têm, a fim de que todo homem necessitado possa ser amplamente suprido e receba de acordo com suas necessidades."},{"verse":34,"text":"Portanto, o restante será guardado em meu armazém para dar aos pobres e necessitados, segundo designação do sumo conselho da igreja e do bispo e seu conselho;"},{"verse":35,"text":"E para comprar terras para benefício da igreja e para construir casas de adoração e edificar a Nova Jerusalém que será depois revelada —"},{"verse":36,"text":"Para que meu povo do convênio esteja reunido como um no dia em que eu vier ao meu templo. E isto farei para a salvação de meu povo."},{"verse":37,"text":"E acontecerá que o que pecar e não se arrepender será expulso da igreja e não receberá de volta o que houver consagrado aos pobres e necessitados de minha igreja, ou, em outras palavras, a mim —"},{"verse":38,"text":"Porque quando o fazeis ao menor destes, a mim o fazeis."},{"verse":39,"text":"Pois acontecerá que o que eu disse pela boca de meus profetas será cumprido; pois consagrarei das riquezas daqueles que abraçam meu evangelho entre os gentios aos pobres de meu povo, que são da casa de Israel."},{"verse":40,"text":"E também, que não haja orgulho em teu coração; sejam simples todas as tuas vestes e sua beleza, a beleza da obra de tuas próprias mãos;"},{"verse":41,"text":"E sejam todas as coisas feitas com limpeza diante de mim."},{"verse":42,"text":"Não serás ocioso; porque o ocioso não comerá o pão nem usará as vestes do trabalhador."},{"verse":43,"text":"E os que entre vós estiverem doentes e não tiverem fé para ser curados, mas acreditarem, serão alimentados com todo carinho, com ervas e comidas leves; e não pela mão de um inimigo."},{"verse":44,"text":"E os élderes da igreja, dois ou mais, serão chamados e orarão por eles, impondo-lhes as mãos em meu nome; e se morrerem, morrerão em mim; e se viverem, viverão em mim."},{"verse":45,"text":"Juntos vivereis em amor, de modo que chorareis a perda dos que morrerem; e mais especialmente dos que não têm esperança de uma ressurreição gloriosa."},{"verse":46,"text":"E acontecerá que aqueles que morrerem em mim não provarão a morte, porque lhes será doce;"},{"verse":47,"text":"E os que não morrem em mim, ai deles, porque amarga é sua morte."},{"verse":48,"text":"E também acontecerá que aquele que tiver fé em mim para ser curado e não estiver designado para morrer, será curado."},{"verse":49,"text":"Aquele que tiver fé para ver, verá."},{"verse":50,"text":"Aquele que tiver fé para ouvir, ouvirá."},{"verse":51,"text":"O coxo que tiver fé para saltar, saltará."},{"verse":52,"text":"E aqueles que não têm fé para fazer estas coisas, mas acreditam em mim, têm poder para tornarem-se meus filhos; e se não desobedecerem às minhas leis, tu suportarás as suas enfermidades."},{"verse":53,"text":"Permanecerás firme no local de tua mordomia."},{"verse":54,"text":"Não tomarás a vestimenta de teu irmão; pagarás pelo que receberes de teu irmão."},{"verse":55,"text":"E se receberes mais do que o necessário para teu sustento, entregá-lo-ás a meu armazém, para que todas as coisas sejam feitas de acordo com o que eu disse."},{"verse":56,"text":"Pedirás e minhas escrituras serão dadas como determinei e serão preservadas em segurança;"},{"verse":57,"text":"E convém que guardes silêncio a respeito delas e não as ensines até que as tenhas recebido em sua totalidade."},{"verse":58,"text":"E dou-te o mandamento de que então as ensines a todos os homens; pois elas serão ensinadas a todas as nações, tribos, línguas e povos."},{"verse":59,"text":"Tomarás as coisas que recebeste, que te foram dadas em minhas escrituras como lei, para que sejam a lei que governará minha igreja;"},{"verse":60,"text":"E o que assim fizer será salvo; e o que não o fizer será condenado, caso continue."},{"verse":61,"text":"Se pedires, receberás revelação sobre revelação, conhecimento sobre conhecimento, para que conheças os mistérios e as coisas pacíficas — aquilo que traz alegria, que traz vida eterna."},{"verse":62,"text":"Pedirás e ser-te-á revelado, em meu próprio e devido tempo, onde a Nova Jerusalém será construída."},{"verse":63,"text":"E eis que acontecerá que meus servos serão enviados ao leste e ao oeste, ao norte e ao sul."},{"verse":64,"text":"E mesmo agora, os que forem para o leste ensinem aqueles que se converterem a fugir para o oeste; e isto em consequência do que sucederá na Terra e de combinações secretas."},{"verse":65,"text":"Eis que observarás todas estas coisas e grande será tua recompensa; porque a vós é dado conhecer os mistérios do reino, mas ao mundo não é dado conhecê-los."},{"verse":66,"text":"Observareis as leis que tendes recebido e sereis fiéis."},{"verse":67,"text":"E no futuro recebereis convênios da igreja, os quais serão suficientes para vos estabelecerdes, tanto aqui como na Nova Jerusalém."},{"verse":68,"text":"Portanto, aquele que tem falta de sabedoria peça-a a mim; e dar-lhe-ei liberalmente e não o lançarei em rosto."},{"verse":69,"text":"Alegrai-vos e regozijai-vos, porque a vós foi dado o reino; ou, em outras palavras, as chaves da igreja. Assim seja. Amém."},{"verse":70,"text":"Os sacerdotes e os mestres terão suas mordomias, assim como os membros."},{"verse":71,"text":"E as famílias dos élderes ou dos sumos sacerdotes designados para ajudar o bispo, como conselheiros em todas as coisas, receberão seu sustento da propriedade consagrada ao bispo para benefício dos pobres e para outros propósitos, como mencionado antes;"},{"verse":72,"text":"Ou receberão uma justa remuneração por todos os seus serviços, seja uma mordomia ou outra coisa — conforme o que os conselheiros e o bispo considerem melhor ou decidam."},{"verse":73,"text":"E o bispo também receberá seu sustento ou uma justa remuneração por todos os seus serviços na igreja."},{"verse":74,"text":"Eis que em verdade vos digo que quaisquer pessoas entre vós que tenham repudiado o cônjuge por causa de fornicação, ou, em outras palavras, se com toda a humildade testificarem diante de vós ser esse o caso, não as expulsareis de vosso meio;"},{"verse":75,"text":"Mas se descobrirdes que uma pessoa abandonou o cônjuge por causa de adultério e é ela mesma a culpada e seu cônjuge vive, essa pessoa será expulsa de vosso meio."},{"verse":76,"text":"E também vos digo que devereis ser diligentes e cuidadosos em vossas investigações, para que não recebais tais pessoas entre vós, se forem casadas;"},{"verse":77,"text":"E se não forem casadas, deverão arrepender-se de todos os pecados; caso contrário, não as recebereis."},{"verse":78,"text":"E também, toda pessoa que pertencer a esta igreja de Cristo esforçar-se-á para guardar todos os mandamentos e convênios da igreja."},{"verse":79,"text":"E acontecerá que, se qualquer dentre vós matar, será entregue para ser julgado de acordo com as leis do país; pois lembrai-vos de que ele não terá perdão; e o caso será provado de acordo com as leis do país."},{"verse":80,"text":"E se qualquer pessoa, homem ou mulher, cometer adultério, será julgada diante de dois ou mais élderes da igreja; e toda palavra contra ele ou ela será confirmada por duas testemunhas da igreja e não do inimigo; mas se houver mais de duas testemunhas, será melhor."},{"verse":81,"text":"Não obstante, a pessoa será condenada pela boca de duas testemunhas; e os élderes apresentarão o caso diante da igreja e a igreja levantará a mão contra ela, para que seja julgada de acordo com a lei de Deus."},{"verse":82,"text":"E se for possível, é necessário que o bispo esteja presente também."},{"verse":83,"text":"E assim fareis em todos os casos que vos forem apresentados."},{"verse":84,"text":"E se um homem ou uma mulher roubar, será entregue à lei do país."},{"verse":85,"text":"E se ele ou ela furtar, será entregue à lei do país."},{"verse":86,"text":"E se ele ou ela mentir, será entregue à lei do país."},{"verse":87,"text":"E se ele ou ela cometer qualquer iniquidade, será entregue à lei, sim, à lei de Deus."},{"verse":88,"text":"E se teu irmão ou tua irmã te ofender, aparta-te com ele ou ela a sós; e se ele ou ela confessar, reconciliar-vos-eis."},{"verse":89,"text":"Mas se ele ou ela não confessar, ele ou ela será por ti entregue à igreja, não aos membros, mas aos élderes. E isso será feito numa reunião e não perante o mundo."},{"verse":90,"text":"E se teu irmão ou tua irmã ofender a muitos, ele ou ela será repreendido diante de muitos."},{"verse":91,"text":"E se alguém ofender publicamente, será repreendido publicamente, para que se envergonhe. E se não confessar, será entregue à lei de Deus."},{"verse":92,"text":"Se alguém ofender em segredo, será repreendido em segredo, para que tenha oportunidade de confessar em segredo a quem quer que tenha ofendido e a Deus, para que a igreja não fale com reprovação a seu respeito."},{"verse":93,"text":"E assim agireis em todas as coisas."}]},{"chapter":43,"verses":[{"verse":1,"text":"Escutai, ó élderes de minha igreja, e dai ouvidos às palavras que vos direi."},{"verse":2,"text":"Pois eis que em verdade, em verdade vos digo que recebestes um mandamento como lei para minha igreja, por meio daquele que designei para receber mandamentos e revelações de minha mão."},{"verse":3,"text":"E isto sabereis com certeza — que não há qualquer outro designado para receber mandamentos e revelações para vós, até que ele seja levado, se ele permanecer em mim."},{"verse":4,"text":"Mas em verdade, em verdade vos digo que nenhum outro será designado para receber esse dom, a menos que seja por meio dele; pois, se esse dom for dele tirado, ele não terá poder, a não ser para designar outro em seu lugar."},{"verse":5,"text":"E isto vos será por lei: Não recebereis os ensinamentos de qualquer pessoa que os apresente a vós como revelações ou como mandamentos."},{"verse":6,"text":"E isto vos dou para que não sejais enganados, para que saibais que não vêm de mim."},{"verse":7,"text":"Pois em verdade vos digo que aquele que for ordenado por mim entrará pela porta e deverá ser ordenado como eu antes vos disse, para ensinar as revelações que recebestes e que recebereis por meio daquele que designei."},{"verse":8,"text":"E agora, eis que vos dou o mandamento de que, quando estiverdes congregados, deveis instruir-vos e edificar-vos uns aos outros, para que saibais como agir e como dirigir minha igreja, como proceder com respeito aos pontos de minha lei e dos mandamentos que dei."},{"verse":9,"text":"E assim vos tornareis instruídos na lei de minha igreja; e sereis santificados por meio daquilo que recebestes e vos obrigareis a agir em toda a santidade diante de mim —"},{"verse":10,"text":"Para que, se assim fizerdes, glória seja acrescentada ao reino que recebestes. Se assim não fizerdes, até o que recebestes vos será tirado."},{"verse":11,"text":"Purgai a iniquidade que existe entre vós; santificai-vos perante mim;"},{"verse":12,"text":"E, se desejais as glórias do reino, designai meu servo Joseph Smith Júnior, e sustentai-o perante mim pela oração da fé."},{"verse":13,"text":"E também vos digo que, se desejais os mistérios do reino, fornecei-lhe alimento, roupas e tudo o mais de que ele necessitar para fazer o trabalho que lhe ordenei;"},{"verse":14,"text":"E se assim não fizerdes, ele permanecerá com aqueles que o receberam, a fim de que para mim mesmo eu reserve um povo puro diante de mim."},{"verse":15,"text":"E também eu digo: Escutai, ó élderes de minha igreja, a quem designei: Não sois enviados para serdes ensinados, mas para ensinardes aos filhos dos homens as coisas que pus em vossas mãos pelo poder de meu Espírito;"},{"verse":16,"text":"Sereis ensinados do alto. Santificai-vos e sereis investidos de poder, para que ensineis como falei."},{"verse":17,"text":"Escutai, pois eis que o grande dia do Senhor está perto."},{"verse":18,"text":"Pois aproxima-se o dia em que dos céus o Senhor fará ressoar a sua voz; os céus estremecerão e a Terra tremerá; e a trombeta de Deus soará longa e fortemente e dirá às nações adormecidas: Vós, santos, levantai-vos e vivei; vós, pecadores, permanecei e dormi até que eu volte a chamar-vos."},{"verse":19,"text":"Portanto, cingi vossos lombos para que não sejais achados entre os iníquos."},{"verse":20,"text":"Elevai a voz sem cessar. Chamai as nações ao arrependimento, tanto velhos como jovens, tanto servos como livres, dizendo: Preparai-vos para o grande dia do Senhor;"},{"verse":21,"text":"Pois se eu, que sou homem, elevo a minha voz e vos convido ao arrependimento e vós me detestais, o que direis quando vier o dia em que os trovões ecoarem a sua voz desde os confins da Terra, falando aos ouvidos de todos os que vivem, dizendo: Arrependei-vos e preparai-vos para o grande dia do Senhor?"},{"verse":22,"text":"Sim, e quando os relâmpagos resplandecerem desde o oriente até o ocidente e manifestarem a sua voz a todos os que vivem e fizerem zumbir os ouvidos de todos os que ouvem, dizendo estas palavras: Arrependei-vos, porque é chegado o grande dia do Senhor?"},{"verse":23,"text":"E também, dos céus o Senhor fará ressoar a sua voz, dizendo: Escutai, ó nações da Terra, e ouvi as palavras do Deus que vos criou."},{"verse":24,"text":"Ó vós, nações da Terra, quantas vezes eu quis ajuntar-vos como a galinha ajunta seus pintos debaixo das asas, mas vós não o quisestes!"},{"verse":25,"text":"Quantas vezes vos chamei pela boca de meus servos e pelo ministério de anjos e por minha própria voz; e pela voz de trovões e pela voz de relâmpagos e pela voz da tempestade; e pela voz dos terremotos e grandes chuvas de pedra; e pela voz da fome e pestilências de toda espécie; e pelo grande som de uma trombeta e pela voz do julgamento e pela voz da misericórdia, todo o dia; e pela voz da glória e honra e das riquezas da vida eterna quis salvar-vos com salvação eterna, mas vós não o quisestes!"},{"verse":26,"text":"Eis que chegado é o dia em que está cheio o cálice da ira de minha indignação."},{"verse":27,"text":"Eis que em verdade vos digo que estas são as palavras do Senhor vosso Deus."},{"verse":28,"text":"Portanto, trabalhai, trabalhai na minha vinha pela última vez — pela última vez chamai os habitantes da Terra."},{"verse":29,"text":"Pois em meu próprio e devido tempo virei à Terra com julgamento e o meu povo será redimido e reinará comigo na Terra."},{"verse":30,"text":"Pois o grande Milênio, do qual falei pela boca de meus servos, virá."},{"verse":31,"text":"Pois Satanás será amarrado e, quando for libertado, reinará apenas por pouco tempo e então virá o fim da Terra."},{"verse":32,"text":"E aquele que viver em retidão será transformado num piscar de olhos e a Terra passará como se fosse por fogo."},{"verse":33,"text":"E os iníquos irão para o fogo inextinguível, e seu fim, homem algum na Terra sabe nem nunca saberá, até que compareçam perante mim em julgamento."},{"verse":34,"text":"Escutai estas palavras. Eis que eu sou Jesus Cristo, o Salvador do mundo. Entesourai estas coisas em vosso coração; e que as verdades solenes da eternidade repousem em vossa mente."},{"verse":35,"text":"Sede sóbrios. Guardai todos os meus mandamentos. Assim seja. Amém."}]},{"chapter":44,"verses":[{"verse":1,"text":"Eis que assim diz o Senhor a vós, meus servos: É-me conveniente que os élderes de minha igreja sejam convocados, do leste e do oeste, do norte e do sul, por carta ou algum outro meio."},{"verse":2,"text":"E acontecerá que, se forem fiéis e exercerem fé em mim, derramarei meu Espírito sobre eles no dia em que se congregarem."},{"verse":3,"text":"E acontecerá que irão às regiões circunvizinhas e pregarão arrependimento ao povo."},{"verse":4,"text":"E muitos serão convertidos, de maneira que obtereis poder para vos organizar conforme as leis do homem;"},{"verse":5,"text":"Para que vossos inimigos não tenham poder sobre vós e sejais preservados em todas as coisas; a fim de que guardeis as minhas leis e se quebrem todos os vínculos com os quais o inimigo procura destruir meu povo."},{"verse":6,"text":"Eis que vos digo que deveis visitar os pobres e os necessitados e ministrar-lhes auxílio, para que sejam amparados até que todas as coisas possam ser feitas de acordo com a lei que de mim recebestes. Amém."}]},{"chapter":45,"verses":[{"verse":1,"text":"Escutai, ó povo de minha igreja, a quem foi dado o reino; escutai e dai ouvidos àquele que estabeleceu os fundamentos da Terra, que fez os céus e todas as suas hostes, e por quem foram feitas todas as coisas que vivem e se movem e têm seu ser."},{"verse":2,"text":"E também digo: Escutai a minha voz, para que a morte não vos surpreenda; na hora que menos esperais o verão terá passado, a colheita estará terminada e vossa alma não estará salva."},{"verse":3,"text":"Ouvi aquele que é o advogado junto ao Pai, que está pleiteando vossa causa perante ele —"},{"verse":4,"text":"Dizendo: Pai, contempla os sofrimentos e a morte daquele que não cometeu pecado, em quem te rejubilaste; contempla o sangue de teu Filho, que foi derramado, o sangue daquele que deste para que fosses glorificado;"},{"verse":5,"text":"Portanto, Pai, poupa estes meus irmãos que creem em meu nome, para que venham a mim e tenham vida eterna."},{"verse":6,"text":"Escutai, ó povo da minha igreja, e vós, élderes, juntos escutai e ouvi a minha voz durante o tempo que se chama hoje; e não endureçais o coração;"},{"verse":7,"text":"Pois em verdade vos digo que eu sou o Alfa e o Ômega, o princípio e o fim, a luz e a vida do mundo — uma luz que resplandece nas trevas e as trevas não a compreendem."},{"verse":8,"text":"Eu vim aos meus e os meus não me receberam; mas a todos os que me receberam dei poder para realizar muitos milagres e para se tornarem os filhos de Deus; e aos que creram em meu nome, dei poder para alcançarem a vida eterna."},{"verse":9,"text":"E assim também mandei ao mundo meu eterno convênio, para ser uma luz para o mundo, para ser um modelo para meu povo e para que os gentios o procurem; e para ser um mensageiro diante de minha face e preparar o caminho diante de mim."},{"verse":10,"text":"Portanto, entrai nele; e com aquele que vier eu arrazoarei, como fiz com os homens em dias passados; e mostrar-vos-ei meu forte argumento."},{"verse":11,"text":"Portanto, juntos escutai e deixai-me mostrar-vos minha sabedoria — a sabedoria daquele que dizeis ser o Deus de Enoque e de seus irmãos,"},{"verse":12,"text":"Que foram apartados da Terra e recebidos em mim — uma cidade reservada até que venha o dia da retidão — dia procurado por todos os homens santos e não encontrado devido a iniquidades e abominações;"},{"verse":13,"text":"E eles confessaram ser estranhos e peregrinos na Terra;"},{"verse":14,"text":"Mas receberam a promessa de que o encontrariam e o veriam na carne."},{"verse":15,"text":"Portanto, escutai e arrazoarei convosco; e falar-vos-ei e profetizarei como fiz com os homens em dias passados."},{"verse":16,"text":"E mostrá-lo-ei claramente, como a meus discípulos o mostrei quando estive diante deles na carne e falei-lhes, dizendo: Como me tendes perguntado sobre os sinais da minha vinda, no dia em que, nas nuvens dos céus, eu vier em minha glória para cumprir as promessas que fiz a vossos pais,"},{"verse":17,"text":"Pois uma vez que tendes considerado como aprisionamento o longo tempo em que vosso espírito esteve ausente de vosso corpo, mostrar-vos-ei como virá o dia da redenção e também a restauração de Israel disperso."},{"verse":18,"text":"E agora vedes este templo situado em Jerusalém, que chamais casa de Deus; e vossos inimigos dizem que essa casa jamais cairá."},{"verse":19,"text":"Mas em verdade vos digo que desolação virá sobre esta geração como um ladrão na noite; e este povo será destruído e dispersado por entre todas as nações."},{"verse":20,"text":"E este templo que agora vedes será derrubado, de modo que não ficará pedra sobre pedra."},{"verse":21,"text":"E acontecerá que esta geração de judeus não passará sem que se cumpram todas as desolações de que vos falei em relação a eles."},{"verse":22,"text":"Dizeis saber que o fim do mundo virá; dizeis também saber que os céus e a Terra passarão;"},{"verse":23,"text":"E com isto dizeis a verdade, porque assim é; mas estas coisas de que vos falei não passarão até que tudo se cumpra."},{"verse":24,"text":"E isto vos disse concernente a Jerusalém; e quando vier aquele dia, um remanescente será disperso entre todas as nações;"},{"verse":25,"text":"Mas serão reunidos outra vez; contudo, permanecerão até que os tempos dos gentios se cumpram."},{"verse":26,"text":"E naqueles dias se ouvirá de guerras e rumores de guerras e toda a Terra estará em comoção e o coração dos homens falhará; e dirão que Cristo retarda sua vinda até o fim da Terra."},{"verse":27,"text":"E o amor dos homens esfriará e a iniquidade será abundante."},{"verse":28,"text":"E quando os tempos dos gentios chegarem, uma luz resplandecerá entre aqueles que se assentam em trevas; e será a plenitude do meu evangelho;"},{"verse":29,"text":"Mas eles não a recebem, porque não percebem a luz e desviam de mim o coração por causa dos preceitos dos homens."},{"verse":30,"text":"E nessa geração se cumprirá o tempo dos gentios."},{"verse":31,"text":"E haverá homens nessa geração que não passarão até que vejam uma praga terrível; pois uma doença desoladora cobrirá a terra."},{"verse":32,"text":"Mas os meus discípulos permanecerão em lugares santos e não serão movidos; mas, entre os iníquos, homens levantarão a voz e amaldiçoarão a Deus e morrerão."},{"verse":33,"text":"E haverá terremotos também em diversos lugares e muitas desolações; e ainda assim os homens endurecerão o coração contra mim e levantarão a espada uns contra os outros e matar-se-ão uns aos outros."},{"verse":34,"text":"E quando eu, o Senhor, disse estas palavras aos meus discípulos, eles se perturbaram."},{"verse":35,"text":"E disse-lhes: Não vos perturbeis, porque, quando todas estas coisas acontecerem, sabereis que as promessas que vos foram feitas serão cumpridas."},{"verse":36,"text":"E quando começar a raiar a luz, será para eles como uma parábola que vos mostrarei —"},{"verse":37,"text":"Olhais e vedes as figueiras e com vossos olhos as contemplais; e quando começam a brotar e suas folhas estão ainda tenras, dizeis que o verão está próximo;"},{"verse":38,"text":"Assim também será no dia em que eles virem todas essas coisas; então saberão que a hora está próxima."},{"verse":39,"text":"E acontecerá que aquele que me teme estará esperando que venha o grande dia do Senhor, sim, os sinais da vinda do Filho do Homem."},{"verse":40,"text":"E verão sinais e maravilhas, pois serão mostrados em cima nos céus e embaixo na Terra."},{"verse":41,"text":"E verão sangue e fogo e vapores de fumaça."},{"verse":42,"text":"E antes que venha o dia do Senhor, o sol se escurecerá, a lua tornar-se-á em sangue e as estrelas cairão do céu."},{"verse":43,"text":"E o remanescente será reunido neste local;"},{"verse":44,"text":"E então me procurarão, e eis que virei; e ver-me-ão nas nuvens do céu, revestido de poder e grande glória, com todos os santos anjos; e quem não me procurar será rejeitado."},{"verse":45,"text":"Mas antes que desça o braço do Senhor, um anjo soará sua trombeta e os santos que dormiram ressurgirão para encontrar-me nas nuvens."},{"verse":46,"text":"Portanto, se dormistes em paz, bem-aventurados sois; porque como agora me vedes e sabeis que eu sou, assim também vireis a mim e vossa alma viverá e vossa redenção será aperfeiçoada; e os santos ressurgirão dos quatro cantos da Terra."},{"verse":47,"text":"Então o braço do Senhor descerá sobre as nações."},{"verse":48,"text":"E então o Senhor assentará o pé sobre este monte e ele será fendido pelo meio; e a Terra tremerá e vacilará de um lado para outro e os céus também estremecerão."},{"verse":49,"text":"E o Senhor fará soar a sua voz e todos os confins da Terra ouvi-la-ão; e as nações da Terra prantearão e os que riram verão sua insensatez."},{"verse":50,"text":"E calamidade cobrirá o desdenhador e o escarnecedor será consumido; e os que tiverem procurado a iniquidade serão cortados e lançados no fogo."},{"verse":51,"text":"E então os judeus irão olhar para mim e dizer: Que feridas são essas em tuas mãos e em teus pés?"},{"verse":52,"text":"Então saberão que eu sou o Senhor, pois dir-lhes-ei: Estas são as feridas com que fui ferido na casa de meus amigos. Eu sou aquele que foi levantado. Eu sou Jesus, que foi crucificado. Eu sou o Filho de Deus."},{"verse":53,"text":"E então eles prantearão por causa de suas iniquidades; e lamentar-se-ão por terem perseguido o seu rei."},{"verse":54,"text":"E então as nações pagãs serão redimidas e os que não conheceram lei alguma tomarão parte na primeira ressurreição; e ser-lhes-á tolerável."},{"verse":55,"text":"E Satanás será amarrado, para que não tenha lugar no coração dos filhos dos homens."},{"verse":56,"text":"E nesse dia, quando eu vier em minha glória, cumprir-se-á a parábola de que falei, concernente às dez virgens."},{"verse":57,"text":"Pois aqueles que são prudentes e tiverem recebido a verdade e tomado o Santo Espírito por seu guia e não tiverem sido enganados — em verdade vos digo que não serão cortados e lançados no fogo, mas suportarão o dia."},{"verse":58,"text":"E a Terra ser-lhes-á dada por herança e multiplicar-se-ão e tornar-se-ão fortes; e seus filhos crescerão sem pecado para a salvação."},{"verse":59,"text":"Porque o Senhor estará em seu meio e sua glória estará sobre eles; e ele será seu rei e seu legislador."},{"verse":60,"text":"E agora, eis que vos digo que nada mais vos será dado saber concernente a este capítulo, até que o Novo Testamento seja traduzido; e nele todas estas coisas serão dadas a conhecer;"},{"verse":61,"text":"Portanto, agora vos permito traduzi-lo, para que estejais preparados para as coisas que hão de vir."},{"verse":62,"text":"Pois em verdade vos digo que grandes coisas vos esperam;"},{"verse":63,"text":"Ouvis falar de guerras em terras estrangeiras; mas eis que vos digo que estão próximas, sim, às vossas portas; e daqui a não muitos anos ouvireis falar de guerras nas vossas próprias terras."},{"verse":64,"text":"Portanto, eu, o Senhor, disse: Saí das terras do leste, reuni-vos, ó élderes de minha igreja; ide para as regiões do oeste, chamai os habitantes ao arrependimento e, à medida que eles se arrependerem, estabelecei igrejas para mim."},{"verse":65,"text":"E com um só coração e com um só pensamento, ajuntai vossas riquezas para comprar uma herança que mais tarde vos será designada."},{"verse":66,"text":"E ela será chamada a Nova Jerusalém, uma terra de paz, uma cidade de refúgio, um lugar seguro para os santos do Deus Altíssimo;"},{"verse":67,"text":"E a glória do Senhor ali estará e o terror do Senhor também ali estará, tanto que os iníquos não virão a ela; e será chamada Sião."},{"verse":68,"text":"E acontecerá entre os iníquos que todo homem que não tomar sua espada contra seu próximo terá que fugir para Sião, por segurança."},{"verse":69,"text":"E reunir-se-ão nela, de todas as nações debaixo dos céus; e serão o único povo que não estará em guerra entre si."},{"verse":70,"text":"E entre os iníquos dir-se-á: Não subamos para lutar contra Sião, porque os habitantes de Sião são terríveis; portanto, não podemos resistir."},{"verse":71,"text":"E acontecerá que os justos serão reunidos dentre todas as nações e virão a Sião cantando com cânticos de eterna alegria."},{"verse":72,"text":"E agora vos digo: Não deixeis que estas coisas se espalhem pelo mundo até que me seja conveniente, para que realizeis esta obra aos olhos do povo e aos olhos de vossos inimigos, para que eles não saibam de vossas obras até que tenhais realizado o que vos mandei;"},{"verse":73,"text":"Para que, quando o souberem, reflitam sobre estas coisas."},{"verse":74,"text":"Pois quando o Senhor aparecer, será tão terrível para eles que serão tomados de temor e permanecerão afastados e estremecerão."},{"verse":75,"text":"E todas as nações temerão por causa do terror do Senhor e do poder de sua força. Assim seja. Amém."}]},{"chapter":46,"verses":[{"verse":1,"text":"Escutai, ó povo da minha igreja; pois, em verdade vos digo, que estas coisas foram declaradas para vosso proveito e instrução."},{"verse":2,"text":"Mas não obstante as coisas que estão escritas, sempre foi ordenado aos élderes da minha igreja, desde o princípio — e sempre o será — dirigirem todas as reuniões conforme inspirados e guiados pelo Santo Espírito."},{"verse":3,"text":"Não obstante, tendes ordem de jamais excluir quem quer que seja de vossas reuniões públicas, que são realizadas diante do mundo."},{"verse":4,"text":"Tendes ordem também de não excluir de vossas reuniões sacramentais ninguém que pertença à igreja; não obstante, se alguém tiver transgredido, que não participe do sacramento até que haja uma reconciliação."},{"verse":5,"text":"E também vos digo que não deveis excluir de vossas reuniões sacramentais quem quer que esteja sinceramente procurando o reino — digo isto com respeito aos que não são da igreja."},{"verse":6,"text":"E torno a dizer-vos, com respeito às vossas reuniões de confirmação, que se houver alguém que não for da igreja, mas estiver sinceramente procurando o reino, não o excluireis."},{"verse":7,"text":"Tendes ordem, porém, de em todas as coisas pedir a Deus, que dá liberalmente; e aquilo que o Espírito vos testificar, assim quisera eu que fizésseis em toda santidade de coração, andando retamente perante mim, refletindo sobre o resultado da vossa salvação, fazendo todas as coisas com oração e ação de graças, para que não sejais seduzidos por espíritos malignos, ou pelas doutrinas de demônios, ou por mandamentos de homens; porque alguns são de homens e outros, de demônios;"},{"verse":8,"text":"Portanto, acautelai-vos para que não vos enganem; e, para que não sejais enganados, procurai com zelo os melhores dons, lembrando sempre por que são dados;"},{"verse":9,"text":"Pois em verdade vos digo: Eles são dados em benefício daqueles que me amam e guardam todos os meus mandamentos e daqueles que procuram assim fazer; para que sejam beneficiados todos os que buscam ou que me pedem e que pedem não um sinal para satisfazer suas concupiscências."},{"verse":10,"text":"E também em verdade vos digo: Quisera que sempre vos lembrásseis e sempre retivésseis em vossa mente o que são esses dons dados à igreja."},{"verse":11,"text":"Pois a todos não são dados todos os dons; pois há muitos dons e a cada homem é dado um dom pelo Espírito de Deus."},{"verse":12,"text":"A alguns é dado um, a outros é dado outro, para que desse modo todos sejam beneficiados."},{"verse":13,"text":"A alguns é dado saber, pelo Espírito Santo, que Jesus Cristo é o Filho de Deus e que foi crucificado pelos pecados do mundo."},{"verse":14,"text":"A outros é dado crer nas palavras deles, para que tenham também vida eterna se permanecerem fiéis."},{"verse":15,"text":"E também o Espírito Santo faz saber a alguns as diferenças de administração, conforme for agradável ao mesmo Senhor, segundo desejar o Senhor, que molda suas misericórdias às condições dos filhos dos homens."},{"verse":16,"text":"E também a alguns é dado perceber, pelo Espírito Santo, se as diversidades de operações são de Deus, para que as manifestações do Espírito sejam dadas a todo homem para seu proveito."},{"verse":17,"text":"E também em verdade vos digo: A alguns é dada, pelo Espírito de Deus, a palavra de sabedoria."},{"verse":18,"text":"A outros é dada a palavra de conhecimento, para que todos possam ser ensinados a serem sábios e a terem conhecimento."},{"verse":19,"text":"E também a alguns é dado ter fé para serem curados;"},{"verse":20,"text":"E a outros é dado ter fé para curar."},{"verse":21,"text":"E também a alguns é dada a operação de milagres;"},{"verse":22,"text":"E a outros é dado profetizar;"},{"verse":23,"text":"E a outros, o discernimento de espíritos."},{"verse":24,"text":"E também a alguns é dado falar em línguas;"},{"verse":25,"text":"E a outros é dada a interpretação de línguas."},{"verse":26,"text":"E todos estes dons vêm de Deus, para benefício dos filhos de Deus."},{"verse":27,"text":"E ao bispo da igreja e àqueles designados e ordenados por Deus para zelarem pela igreja e para serem élderes da igreja, será dado discernir todos esses dons, para que ninguém haja entre vós que, sem ser de Deus, professe tê-los."},{"verse":28,"text":"E acontecerá que aquele que pedir em Espírito receberá em Espírito;"},{"verse":29,"text":"Para que a alguns seja dado possuir todos esses dons, para que haja uma cabeça, a fim de que todo membro se beneficie com isso."},{"verse":30,"text":"Aquele que pede em Espírito pede de acordo com a vontade de Deus; portanto, é feito como pede."},{"verse":31,"text":"E também vos digo: Todas as coisas devem ser feitas em nome de Cristo, tudo aquilo que fizerdes no Espírito;"},{"verse":32,"text":"E no Espírito deveis render graças a Deus por todas as bênçãos com que sois abençoados."},{"verse":33,"text":"E deveis praticar a virtude e a santidade perante mim continuamente. Assim seja. Amém."}]},{"chapter":47,"verses":[{"verse":1,"text":"Eis que me é conveniente que meu servo John escreva e conserve uma história regular e assista-te, meu servo Joseph, na transcrição de todas as coisas que te serão dadas, até que ele seja chamado para outros deveres."},{"verse":2,"text":"Ademais, em verdade eu te digo que ele também poderá elevar a sua voz nas reuniões, sempre que for conveniente."},{"verse":3,"text":"E também te digo que ele será encarregado de continuamente fazer o registro e escrever a história da igreja; pois Oliver Cowdery designei para outro ofício."},{"verse":4,"text":"Portanto, se for fiel, ser-lhe-á dado pelo Consolador escrever estas coisas. Assim seja. Amém."}]},{"chapter":48,"verses":[{"verse":1,"text":"É necessário que, por enquanto, permaneçais em vossas moradias, como convenha à vossa condição."},{"verse":2,"text":"E se possuirdes terras, repartireis com os irmãos do leste;"},{"verse":3,"text":"E se não possuirdes terras, que eles comprem, por enquanto, nas regiões circunvizinhas, como lhes parecer bem, pois é necessário que por agora tenham lugares para morar."},{"verse":4,"text":"É necessário que economizeis todo o dinheiro que puderdes e que obtenhais em retidão tudo o que puderdes, para que, no devido tempo, tenhais condições de comprar terras para uma herança, sim, para a cidade."},{"verse":5,"text":"O local não será ainda revelado; mas depois que vossos irmãos vierem do leste, deverão ser designados alguns homens e a eles será dado saber o local, ou seja, ser-lhes-á revelado."},{"verse":6,"text":"E eles serão designados para comprar as terras e iniciar a construção do alicerce da cidade; e então começareis a reunir-vos com vossa família, cada homem de acordo com sua família, de acordo com suas condições e conforme lhe for designado pela presidência e pelo bispo da igreja, segundo as leis e os mandamentos que recebestes e que recebereis daqui em diante. Assim seja. Amém."}]},{"chapter":49,"verses":[{"verse":1,"text":"Escutai minha palavra, meus servos Sidney e Parley e Leman; pois eis que em verdade vos digo que vos dou o mandamento de irdes pregar aos Shakers o meu evangelho que recebestes, da forma como o recebestes."},{"verse":2,"text":"Eis que vos digo que eles desejam conhecer a verdade em parte, mas não toda, pois não são retos diante de mim e precisam arrepender-se."},{"verse":3,"text":"Portanto, meus servos Sidney e Parley, envio-vos a pregar-lhes o evangelho."},{"verse":4,"text":"E meu servo Leman será ordenado para esse trabalho a fim de arrazoar com eles, não conforme o que recebeu deles, mas conforme o que lhe será ensinado por vós, meus servos; e, fazendo isso, abençoá-lo-ei; caso contrário, ele não prosperará."},{"verse":5,"text":"Assim diz o Senhor; pois eu sou Deus e enviei meu Filho Unigênito ao mundo para a redenção do mundo; e decretei que aquele que o recebesse seria salvo e aquele que não o recebesse seria condenado —"},{"verse":6,"text":"E fizeram ao Filho do Homem o que quiseram; e na mão direita de sua glória tomou ele o seu poder; e agora reina nos céus e reinará até que desça à Terra, para pôr debaixo de seus pés todos os inimigos, tempo esse que está próximo —"},{"verse":7,"text":"Eu, o Senhor Deus, disse-o; mas a hora e o dia nenhum homem sabe, nem os anjos nos céus; nem o saberão até que ele venha."},{"verse":8,"text":"Portanto, eu desejo que todos os homens se arrependam, porque todos estão debaixo do pecado, exceto aqueles que reservei para mim, homens santos dos quais não sabeis."},{"verse":9,"text":"Digo-vos, pois, que vos enviei o meu convênio eterno, aquele que existiu desde o princípio."},{"verse":10,"text":"E aquilo que prometi, eu cumpri; e as nações da Terra a isso se curvarão; e se não o fizerem por si mesmas, serão abatidas, porque aquele que agora a si mesmo se exalta, será humilhado pela força."},{"verse":11,"text":"Portanto, dou-vos mandamento de vos dirigirdes a esse povo e dizer, como meu apóstolo da antiguidade, cujo nome era Pedro:"},{"verse":12,"text":"Crede no nome do Senhor Jesus, que esteve na Terra e que virá, o princípio e o fim;"},{"verse":13,"text":"Arrependei-vos e sede batizados em nome de Jesus Cristo, para a remissão de pecados, de acordo com o santo mandamento;"},{"verse":14,"text":"E todo o que isto fizer receberá o dom do Espírito Santo, pela imposição das mãos dos élderes da igreja."},{"verse":15,"text":"E também, em verdade vos digo que aquele que proíbe o casamento não é aprovado por Deus, porque o casamento foi instituído por Deus para o homem."},{"verse":16,"text":"Portanto, é legítimo que ele tenha uma esposa e os dois serão uma só carne; e tudo isto para que a Terra cumpra o fim de sua criação;"},{"verse":17,"text":"E para que se encha com a medida do homem, de acordo com sua criação antes que o mundo fosse feito."},{"verse":18,"text":"E todo o que manda que se abstenha de carne, que o homem dela não faça uso, não é autorizado por Deus;"},{"verse":19,"text":"Porque eis que as bestas do campo e as aves do ar e aquilo que provém da terra foram estabelecidos para uso do homem, para alimento e para vestuário e a fim de que ele tenha em abundância."},{"verse":20,"text":"Mas não foi determinado que possuísse um homem mais do que o outro; portanto, o mundo se acha em pecado."},{"verse":21,"text":"E ai do homem que derrama sangue ou desperdiça carne sem necessidade."},{"verse":22,"text":"E também, em verdade vos digo que o Filho do Homem não virá na forma de uma mulher nem na de um homem viajando pela terra."},{"verse":23,"text":"Portanto, não vos deixeis enganar, mas continuai firmes, à espera de que os céus sejam sacudidos e a Terra trema e cambaleie como um homem embriagado; e os vales sejam elevados e as montanhas sejam rebaixadas e os lugares acidentados sejam aplainados — e tudo isso quando o anjo soar sua trombeta."},{"verse":24,"text":"Mas antes que venha o grande dia do Senhor, Jacó prosperará no deserto e os lamanitas florescerão como a rosa."},{"verse":25,"text":"Sião florescerá nos outeiros e nas montanhas regozijar-se-á; e será reunida no lugar que designei."},{"verse":26,"text":"Eis que vos digo: Ide, como vos mandei; arrependei-vos de todos os vossos pecados; pedi e recebereis; batei e ser-vos-á aberto."},{"verse":27,"text":"Eis que eu irei adiante de vós e serei vossa retaguarda; e estarei no meio de vós e não sereis confundidos."},{"verse":28,"text":"Eis que eu sou Jesus Cristo e depressa venho. Assim seja. Amém."}]},{"chapter":50,"verses":[{"verse":1,"text":"Escutai, ó élderes da minha igreja, e dai ouvidos à voz do Deus vivo; e atentai para as palavras de sabedoria que vos serão dadas, segundo o que haveis perguntado e concordado com relação à igreja e aos espíritos que estão espalhados pela Terra."},{"verse":2,"text":"Eis que em verdade vos digo que há muitos espíritos que são espíritos falsos, os quais saíram pela Terra enganando o mundo."},{"verse":3,"text":"E Satanás também vos procurou enganar a fim de derrotar-vos."},{"verse":4,"text":"Eis que eu, o Senhor, vos tenho observado e tenho visto abominações na igreja que professa o meu nome."},{"verse":5,"text":"Mas bem-aventurados os que são fiéis e perseveram, seja na vida ou na morte, porque herdarão a vida eterna."},{"verse":6,"text":"Mas ai daqueles que são enganadores e hipócritas, porque assim diz o Senhor: Levá-los-ei a julgamento."},{"verse":7,"text":"Eis que em verdade vos digo que há entre vós hipócritas que enganaram alguns, o que deu poder ao adversário; mas eis que esses serão resgatados;"},{"verse":8,"text":"Mas os hipócritas serão detectados e serão afastados, seja na vida ou na morte, como eu desejar; e ai dos que são cortados da minha igreja, porque os mesmos foram vencidos pelo mundo."},{"verse":9,"text":"Portanto, que todo homem fique atento para que não faça o que não for verdadeiro e reto perante mim."},{"verse":10,"text":"E agora vinde, diz o Senhor, pelo Espírito, aos élderes de sua igreja; e juntos arrazoemos para que compreendais;"},{"verse":11,"text":"Arrazoemos assim como um homem arrazoa com outro, face a face."},{"verse":12,"text":"Ora, quando um homem arrazoa, é compreendido pelo homem, porque arrazoa como um homem; assim também eu, o Senhor, arrazoarei convosco para que compreendais."},{"verse":13,"text":"Portanto, eu, o Senhor, faço-vos esta pergunta: Para que fostes ordenados?"},{"verse":14,"text":"Para pregar meu evangelho pelo Espírito, sim, o Consolador que foi enviado para ensinar a verdade."},{"verse":15,"text":"E então recebestes espíritos que não pudestes compreender e os recebestes como se fossem de Deus; e nisto estais justificados?"},{"verse":16,"text":"Eis que vós mesmos respondereis a esta pergunta; não obstante, serei misericordioso para convosco; aquele dentre vós que for fraco, no futuro será tornado forte."},{"verse":17,"text":"Em verdade vos digo: Aquele que é ordenado por mim e enviado para pregar a palavra da verdade pelo Consolador, no Espírito da verdade, prega-a pelo Espírito da verdade ou de alguma outra forma?"},{"verse":18,"text":"E se for de alguma outra forma, não é de Deus."},{"verse":19,"text":"E também, aquele que recebe a palavra da verdade, recebe-a pelo Espírito da verdade ou de alguma outra forma?"},{"verse":20,"text":"Se for de alguma outra forma, não é de Deus."},{"verse":21,"text":"Então como é que não podeis compreender e saber que aquele que recebe a palavra pelo Espírito da verdade recebe-a como é pregada pelo Espírito da verdade?"},{"verse":22,"text":"Portanto, aquele que prega e aquele que recebe se compreendem um ao outro e ambos são edificados e juntos se regozijam."},{"verse":23,"text":"E aquilo que não edifica não é de Deus e é trevas."},{"verse":24,"text":"Aquilo que é de Deus é luz; e aquele que recebe luz e persevera em Deus recebe mais luz; e essa luz se torna mais e mais brilhante, até o dia perfeito."},{"verse":25,"text":"E também em verdade vos digo e digo para que conheçais a verdade, para que afugenteis as trevas do meio de vós;"},{"verse":26,"text":"Aquele que é ordenado por Deus e enviado, esse é designado para ser o maior, não obstante ser o menor e o servo de todos."},{"verse":27,"text":"Portanto, ele é possuidor de todas as coisas; porque todas as coisas lhe são sujeitas, tanto na Terra como no céu, a vida e a luz, o Espírito e o poder, enviados pela vontade do Pai, por meio de Jesus Cristo, seu Filho."},{"verse":28,"text":"Mas nenhum homem é possuidor de todas as coisas, a menos que seja purificado e lavado de todo pecado."},{"verse":29,"text":"E se fordes purificados e lavados de todo pecado, pedireis ao Pai o que quer que desejardes, em nome de Jesus, e será feito."},{"verse":30,"text":"Mas sabei isto: Ser-vos-á indicado o que devereis pedir; e ao serdes designados como cabeça, os espíritos ser-vos-ão sujeitos."},{"verse":31,"text":"Portanto, acontecerá que, se virdes manifestado um espírito que não podeis compreender e não conhecerdes esse espírito, perguntareis ao Pai em nome de Jesus; e se ele não vos der a conhecer, então sabereis que não é de Deus."},{"verse":32,"text":"E ser-vos-á dado poder sobre esse espírito; e proclamareis contra esse espírito, em alta voz, que ele não é de Deus —"},{"verse":33,"text":"Não com acusações injuriosas, para que não sejais vencidos, nem com jactância ou regozijo, para que não sejais por ele apanhados."},{"verse":34,"text":"Aquele que recebe de Deus, reconheça que é de Deus; e que se regozije por Deus considerá-lo digno de receber."},{"verse":35,"text":"E dando ouvidos e fazendo essas coisas que recebestes e que mais adiante recebereis — e o reino vos é dado pelo Pai, assim como o poder para vencer todas as coisas que não são por ele ordenadas —"},{"verse":36,"text":"E eis que em verdade vos digo: Bem-aventurados sois vós que estais agora ouvindo estas minhas palavras da boca de meu servo, porque vossos pecados vos são perdoados."},{"verse":37,"text":"Que meu servo Joseph Wakefield, em quem me comprazo, e meu servo Parley P. Pratt visitem as igrejas e fortaleçam-nas com palavras de exortação;"},{"verse":38,"text":"E também meu servo John Corrill ou todos os meus servos que forem ordenados a esse ofício; e que trabalhem na vinha e que nenhum homem os impeça de fazer aquilo que lhes designei —"},{"verse":39,"text":"Portanto, nisto meu servo Edward Partridge não é justificado; contudo, que se arrependa e será perdoado."},{"verse":40,"text":"Eis que vós sois criancinhas e não podeis suportar todas as coisas agora; é preciso que cresçais em graça e no conhecimento da verdade."},{"verse":41,"text":"Não temais, filhinhos, porque sois meus e eu venci o mundo; e fazeis parte daqueles que meu Pai me deu;"},{"verse":42,"text":"E nenhum dos que meu Pai me deu se perderá."},{"verse":43,"text":"E o Pai e eu somos um. Eu estou no Pai e o Pai em mim; e sendo que me recebestes, estais em mim e eu em vós."},{"verse":44,"text":"Portanto, estou em vosso meio e sou o bom pastor e a pedra de Israel. Aquele que edificar sobre esta rocha jamais cairá."},{"verse":45,"text":"E vem o dia em que ouvireis a minha voz e me vereis, e sabereis que eu sou."},{"verse":46,"text":"Vigiai, portanto, para que estejais prontos. Assim seja. Amém."}]},{"chapter":51,"verses":[{"verse":1,"text":"Escutai-me, diz o Senhor vosso Deus, e falarei a meu servo Edward Partridge e dar-lhe-ei instruções; porque é necessário que receba instruções sobre como organizar este povo."},{"verse":2,"text":"Porque é necessário que sejam organizados de acordo com minhas leis; caso contrário, serão cortados."},{"verse":3,"text":"Portanto, que meu servo Edward Partridge e aqueles que ele escolheu, com os quais me comprazo, designem a este povo suas porções, igualmente a cada homem, de acordo com sua família e de acordo com suas condições e suas carências e necessidades."},{"verse":4,"text":"E que meu servo Edward Partridge, quando designar a um homem sua porção, dê-lhe um documento que lhe assegure sua porção, para que a conserve, sim, esse direito e essa herança na igreja, até que transgrida e não seja considerado digno de pertencer a ela, pela voz da igreja, de acordo com as leis e os convênios da igreja."},{"verse":5,"text":"E se transgredir e não for considerado digno de pertencer à igreja, não terá poder para reclamar a porção que consagrou ao bispo para os pobres e necessitados da igreja; portanto, ele não conservará a dádiva, mas terá direito somente à porção que tenha recebido por documento."},{"verse":6,"text":"E assim todas as coisas serão asseguradas, de acordo com as leis do país."},{"verse":7,"text":"E aquilo que pertencer a este povo seja a ele designado."},{"verse":8,"text":"E quanto ao dinheiro deixado para este povo: Que se designe um agente para este povo a fim de, com o dinheiro, prover alimento e vestuário, segundo as necessidades deste povo."},{"verse":9,"text":"E que todo homem negocie honestamente e seja igual entre este povo e receba igualmente, para que sejais um, assim como vos ordenei."},{"verse":10,"text":"E que aquilo que pertencer a este povo não seja dele tirado e dado ao de outra igreja."},{"verse":11,"text":"Portanto, se outra igreja receber dinheiro desta igreja, deverá pagar-lhe conforme o que combinarem;"},{"verse":12,"text":"E isto será feito por intermédio do bispo ou do agente, que será designado pela voz da igreja."},{"verse":13,"text":"E também, que o bispo designe um armazém para esta igreja; e que todas as coisas, tanto em dinheiro como em mantimentos, que ultrapassem as necessidades deste povo, conservem-se nas mãos do bispo."},{"verse":14,"text":"E que ele também reserve o necessário para suas próprias necessidades e para as necessidades de sua família, já que estará tratando deste negócio."},{"verse":15,"text":"E assim concedo a este povo o privilégio de organizar-se de acordo com minhas leis."},{"verse":16,"text":"E consagro-lhes esta terra por um certo tempo, até que eu, o Senhor, proveja a sua subsistência de outra forma e ordene-lhes que partam daqui;"},{"verse":17,"text":"E a hora e o dia não lhes são indicados; portanto, que vivam nesta terra como se aqui fossem permanecer anos; e isso lhes reverterá para o bem."},{"verse":18,"text":"Eis que isso será um exemplo para meu servo Edward Partridge em outros lugares, em todas as igrejas."},{"verse":19,"text":"E quem for um mordomo fiel, justo e sábio, entrará no gozo do seu Senhor e herdará a vida eterna."},{"verse":20,"text":"Em verdade vos digo: Eu sou Jesus Cristo, que depressa vem, em uma hora que não pensais. Assim seja. Amém."}]},{"chapter":52,"verses":[{"verse":1,"text":"Eis que assim diz o Senhor aos élderes que chamou e escolheu nestes últimos dias pela voz de seu Espírito —"},{"verse":2,"text":"Dizendo: Eu, o Senhor, dar-vos-ei a conhecer o que desejo que façais deste momento até a próxima conferência, que se realizará em Missouri, na terra que consagrarei a meu povo, o qual é um remanescente de Jacó, e aos que são herdeiros de acordo com o convênio."},{"verse":3,"text":"Portanto, em verdade vos digo: Que meus servos Joseph Smith Júnior e Sidney Rigdon viajem logo que possam fazer os preparativos para deixar seus lares, indo para a terra de Missouri."},{"verse":4,"text":"E se me forem fiéis, ser-lhes-á dado saber o que deverão fazer;"},{"verse":5,"text":"E também, se me forem fiéis, ser-lhes-á dada a conhecer a terra de vossa herança."},{"verse":6,"text":"E se não forem fiéis, serão afastados como eu desejar, como me parecer bem."},{"verse":7,"text":"E também em verdade vos digo: Que meus servos Lyman Wight e John Corrill viajem rapidamente;"},{"verse":8,"text":"E também que meu servo John Murdock e meu servo Hyrum Smith viajem para o mesmo lugar, via Detroit."},{"verse":9,"text":"E partam de lá pregando a palavra pelo caminho, dizendo nada mais do que escreveram os profetas e apóstolos e o que lhes for ensinado pelo Consolador por meio da oração da fé."},{"verse":10,"text":"Que vão de dois em dois e assim preguem pelo caminho em todas as congregações, batizando com água e impondo as mãos quando saírem da água."},{"verse":11,"text":"Pois assim diz o Senhor: Abreviarei minha obra em retidão, pois dias virão em que enviarei julgamento para alcançar a vitória."},{"verse":12,"text":"E que meu servo Lyman Wight se acautele, pois Satanás deseja peneirá-lo como palha."},{"verse":13,"text":"E eis que aquele que for fiel será feito governante de muitas coisas."},{"verse":14,"text":"E também eu vos darei um modelo em todas as coisas, para que não sejais enganados; porque Satanás está solto na terra, enganando as nações —"},{"verse":15,"text":"Portanto, aquele que ora, cujo espírito é contrito, esse é aceito por mim, se obedecer às minhas ordenanças."},{"verse":16,"text":"Aquele que fala, cujo espírito é contrito, cuja linguagem é mansa e edifica, esse é de Deus, se obedecer às minhas ordenanças."},{"verse":17,"text":"E também aquele que estremece sob o meu poder será fortalecido e produzirá frutos de louvor e sabedoria, de acordo com as revelações e verdades que vos dei."},{"verse":18,"text":"E também aquele que é vencido e não produz frutos, de acordo com este modelo, não é meu."},{"verse":19,"text":"Portanto, por este modelo discernireis os espíritos em todos os casos debaixo dos céus."},{"verse":20,"text":"E chegados são os dias; de acordo com a fé dos homens, ser-lhes-á feito."},{"verse":21,"text":"Eis que este mandamento é dado a todos os élderes que escolhi."},{"verse":22,"text":"E também em verdade vos digo: Que meus servos Thomas B. Marsh e Ezra Thayre também viajem para essa mesma terra, pregando a palavra pelo caminho."},{"verse":23,"text":"E também que meus servos Isaac Morley e Ezra Booth viajem para essa mesma terra, também pregando a palavra pelo caminho."},{"verse":24,"text":"E também que meus servos Edward Partridge e Martin Harris viajem com meus servos Sidney Rigdon e Joseph Smith Júnior."},{"verse":25,"text":"Que meus servos David Whitmer e Harvey Whitlock também viajem para essa mesma terra e preguem pelo caminho."},{"verse":26,"text":"E que meus servos Parley P. Pratt e Orson Pratt viajem para essa mesma terra e preguem pelo caminho."},{"verse":27,"text":"E que meus servos Solomon Hancock e Simeon Carter também viajem para essa mesma terra e preguem pelo caminho."},{"verse":28,"text":"Que meus servos Edson Fuller e Jacob Scott também façam sua viagem."},{"verse":29,"text":"Que meus servos Levi W. Hancock e Zebedee Coltrin também façam sua viagem."},{"verse":30,"text":"Que meus servos Reynolds Cahoon e Samuel H. Smith também façam sua viagem."},{"verse":31,"text":"Que meus servos Wheeler Baldwin e William Carter também façam sua viagem."},{"verse":32,"text":"E que meus servos Newel Knight e Selah J. Griffin sejam ambos ordenados e também viajem."},{"verse":33,"text":"Sim, em verdade eu digo: Que todos esses viajem para um lugar, seguindo caminhos diversos; e que um homem não construa sobre o alicerce de outro nem viaje seguindo suas pegadas."},{"verse":34,"text":"Aquele que for fiel será guardado e abençoado com muitos frutos."},{"verse":35,"text":"E também vos digo: Que meus servos Joseph Wakefield e Solomon Humphrey viajem para as terras do leste;"},{"verse":36,"text":"Que trabalhem com suas famílias, nada mais declarando do que os profetas e apóstolos, as coisas que viram e ouviram e em que firmemente creem, para que se cumpram as profecias."},{"verse":37,"text":"Em consequência de transgressão, aquilo que foi conferido a Heman Basset seja dele tirado e conferido a Simonds Ryder."},{"verse":38,"text":"E também em verdade vos digo: Que Jared Carter seja ordenado sacerdote e que também George James seja ordenado sacerdote."},{"verse":39,"text":"Que os élderes restantes velem pelas igrejas e preguem a palavra nas regiões circunvizinhas; e que trabalhem com as próprias mãos, a fim de que não se pratique idolatria nem iniquidade."},{"verse":40,"text":"E em todas as coisas lembrai-vos dos pobres e necessitados, dos doentes e dos aflitos, porque aquele que não faz estas coisas não é meu discípulo."},{"verse":41,"text":"E também que meus servos Joseph Smith Júnior, Sidney Rigdon e Edward Partridge levem consigo uma recomendação da igreja. E que também seja obtida uma para meu servo Oliver Cowdery."},{"verse":42,"text":"E assim, como eu disse, se fordes fiéis vos reunireis para vos regozijardes na terra de Missouri, que é a terra de vossa herança, que é, no presente, a terra de vossos inimigos."},{"verse":43,"text":"Mas eis que eu, o Senhor, apressarei a construção da cidade a seu tempo e coroarei os fiéis com alegria e com regozijo."},{"verse":44,"text":"Eis que eu sou Jesus Cristo, o Filho de Deus, e elevá-los-ei no último dia. Assim seja. Amém."}]},{"chapter":53,"verses":[{"verse":1,"text":"Eis que eu te digo, meu servo Sidney Gilbert, que ouvi tuas orações; e pediste-me que te fosse dado saber, pelo Senhor teu Deus, concernente a teu chamado e eleição na igreja que eu, o Senhor, levantei nestes últimos dias."},{"verse":2,"text":"Eis que eu, o Senhor, que fui crucificado pelos pecados do mundo, te dou o mandamento de que renuncies ao mundo."},{"verse":3,"text":"Toma sobre ti minha ordenação, sim, a de élder, para pregares fé e arrependimento e remissão de pecados, de acordo com minha palavra, e o recebimento do Espírito Santo pela imposição de mãos;"},{"verse":4,"text":"E também para seres um agente nesta igreja no lugar que for designado pelo bispo, de acordo com os mandamentos que serão dados daqui em diante."},{"verse":5,"text":"E também em verdade eu te digo: Viajarás com meus servos Joseph Smith Júnior e Sidney Rigdon."},{"verse":6,"text":"Eis que estas são as primeiras ordenanças que receberás; e o restante será conhecido em uma época futura, de acordo com teu trabalho na minha vinha."},{"verse":7,"text":"E também quisera eu que aprendesses que somente é salvo aquele que persevera até o fim. Assim seja. Amém."}]},{"chapter":54,"verses":[{"verse":1,"text":"Eis que assim diz o Senhor, o Alfa e o Ômega, o princípio e o fim, aquele que foi crucificado pelos pecados do mundo:"},{"verse":2,"text":"Eis que em verdade, em verdade eu te digo, meu servo Newel Knight, que permaneças firme no ofício para o qual te designei."},{"verse":3,"text":"E se teus irmãos desejam escapar de seus inimigos, que se arrependam de todos os seus pecados e se tornem verdadeiramente humildes e contritos perante mim."},{"verse":4,"text":"E como o convênio que fizeram comigo foi quebrado, tornou-se nulo e sem efeito."},{"verse":5,"text":"E ai daquele por meio de quem ocorre esta ofensa, pois seria melhor para ele que se tivesse afogado nas profundezas do mar."},{"verse":6,"text":"Mas bem-aventurados são os que guardaram o convênio e observaram o mandamento, porque obterão misericórdia."},{"verse":7,"text":"Portanto, agora fugi da terra, para que vossos inimigos não caiam sobre vós; e empreendei vossa viagem e designai a quem desejardes para ser vosso líder e pagar dinheiros por vós."},{"verse":8,"text":"E assim viajareis para as regiões do oeste, para a terra de Missouri, até às fronteiras dos lamanitas."},{"verse":9,"text":"E depois que tiverdes terminado a viagem, eis que vos digo: Procurai um meio de vida à maneira dos homens, até que eu vos prepare um lugar."},{"verse":10,"text":"E também sede pacientes nas tribulações até que eu venha; e eis que depressa venho e o meu galardão está comigo; e aqueles que cedo me buscaram encontrarão descanso para sua alma. Assim seja. Amém."}]},{"chapter":55,"verses":[{"verse":1,"text":"Eis que assim te diz o Senhor, meu servo William, sim, o Senhor de toda a Terra: Foste chamado e escolhido; e depois que tiveres sido batizado com água e se o fizeres com os olhos fitos unicamente na minha glória, terás a remissão de teus pecados e receberás o Santo Espírito pela imposição de mãos;"},{"verse":2,"text":"E então serás ordenado pela mão de meu servo Joseph Smith Júnior para ser um élder desta igreja, para pregar o arrependimento e a remissão de pecados por meio do batismo, em nome de Jesus Cristo, o Filho do Deus vivo."},{"verse":3,"text":"E terás poder para conferir o Santo Espírito a todos sobre quem impuseres tuas mãos, se estiverem contritos perante mim."},{"verse":4,"text":"E também serás ordenado para assistir meu servo Oliver Cowdery na tarefa de imprimir e de selecionar e escrever livros para as escolas desta igreja, a fim de que as criancinhas também recebam instrução diante de mim, como me é agradável."},{"verse":5,"text":"E também em verdade eu te digo que, por esse motivo, farás tua viagem com meus servos Joseph Smith Júnior e Sidney Rigdon, a fim de que te estabeleças na terra de tua herança para fazeres esse trabalho."},{"verse":6,"text":"E também que meu servo Joseph Coe viaje com eles. O restante será dado a conhecer mais tarde, de acordo com a minha vontade. Amém."}]},{"chapter":56,"verses":[{"verse":1,"text":"Escutai, ó povo, vós que professais meu nome, diz o Senhor vosso Deus; pois eis que minha cólera está acesa contra os rebeldes e eles conhecerão meu braço e minha indignação no dia da visitação e da ira sobre as nações."},{"verse":2,"text":"E aquele que não tomar sua cruz e me seguir e guardar meus mandamentos não será salvo."},{"verse":3,"text":"Eis que eu, o Senhor, ordeno; e aquele que não obedecer será cortado em meu próprio e devido tempo, depois que eu tiver ordenado e o mandamento for quebrado."},{"verse":4,"text":"Portanto, eu, o Senhor, ordeno e revogo, como me parece bem; e tudo isso recairá sobre a cabeça dos rebeldes, diz o Senhor."},{"verse":5,"text":"Portanto, revogo o mandamento que foi dado a meus servos Thomas B. Marsh e Ezra Thayre e dou um novo mandamento, a meu servo Thomas, de empreender rapidamente sua viagem à terra de Missouri; e meu servo Selah J. Griffin irá também com ele."},{"verse":6,"text":"Pois eis que eu revogo o mandamento que foi dado a meus servos Selah J. Griffin e Newel Knight, em consequência da obstinação de meu povo que está em Thompson e de suas rebeliões."},{"verse":7,"text":"Portanto, que meu servo Newel Knight permaneça com eles; e todos os que forem contritos perante mim e quiserem ir, poderão ir, sendo por ele guiados à terra que designei."},{"verse":8,"text":"E também em verdade vos digo que meu servo Ezra Thayre deve arrepender-se de seu orgulho e de seu egoísmo e obedecer ao mandamento anterior que lhe dei com respeito ao lugar em que vive."},{"verse":9,"text":"E se assim fizer, uma vez que não serão efetuadas divisões na terra, ele ainda será designado para ir à terra de Missouri;"},{"verse":10,"text":"Caso contrário, ele receberá o dinheiro que pagou e deverá deixar o lugar e será afastado de minha igreja, diz o Senhor Deus dos Exércitos;"},{"verse":11,"text":"E ainda que passem o céu e a Terra, estas palavras não passarão, mas serão cumpridas."},{"verse":12,"text":"E se meu servo Joseph Smith Júnior precisar pagar o dinheiro, eis que eu, o Senhor, devolvê-lo-ei a ele na terra de Missouri, para que aqueles de quem ele receber sejam recompensados novamente de acordo com o que fizerem;"},{"verse":13,"text":"Pois, de acordo com o que fizerem, receberão, sim, em terras para sua herança."},{"verse":14,"text":"Eis que assim diz o Senhor a meu povo: Tendes muitas coisas para fazer e muito do que vos arrepender; pois eis que os vossos pecados subiram a mim, e não são perdoados, porque procurais aconselhar à vossa própria maneira."},{"verse":15,"text":"E vosso coração não está satisfeito. E não obedeceis à verdade, mas tendes prazer na iniquidade."},{"verse":16,"text":"Ai de vós, homens ricos, que não compartilhais vossos bens com os pobres, pois vossas riquezas irão corromper-vos a alma; e esta será vossa lamentação no dia da visitação e do julgamento e da indignação: Passada é a colheita, findo é o verão; e a minha alma não está salva!"},{"verse":17,"text":"Ai de vós, homens pobres, cujo coração não está quebrantado, cujo espírito não é contrito e cujo ventre não está satisfeito e cujas mãos não cessam de se apoderar de bens alheios, cujos olhos estão cheios de cobiça e que não trabalhais com as próprias mãos!"},{"verse":18,"text":"Mas bem-aventurados os pobres que são puros de coração, cujo coração está quebrantado e cujo espírito é contrito, pois eles verão o reino de Deus vindo em poder e grande glória para sua libertação; pois deles será a gordura da terra."},{"verse":19,"text":"Pois eis que o Senhor virá e, com ele, seu galardão; e recompensará a cada homem e os pobres regozijar-se-ão;"},{"verse":20,"text":"E suas gerações herdarão a Terra de geração em geração, para todo o sempre. E agora cesso de falar-vos. Assim seja. Amém."}]},{"chapter":57,"verses":[{"verse":1,"text":"Escutai, ó élderes de minha igreja, diz o Senhor vosso Deus, vós, que de acordo com meus mandamentos vos haveis reunido nesta terra, que é a terra de Missouri, terra que designei e consagrei para a reunião dos santos."},{"verse":2,"text":"Portanto, esta é a terra da promissão e o local para a cidade de Sião."},{"verse":3,"text":"E assim diz o Senhor vosso Deus: Se desejais receber sabedoria, eis aqui sabedoria. Eis que o lugar que é agora chamado Independence é o lugar central; e um local para o templo se acha a oeste, num terreno não longe do tribunal."},{"verse":4,"text":"Portanto, é sábio que os santos comprem a terra e também todas as áreas do oeste até a linha que passa diretamente entre judeus e gentios;"},{"verse":5,"text":"E também toda a área que confina com os prados, na medida que meus discípulos puderem comprar terras. Eis que isto é sabedoria: Que eles a obtenham para herança eterna."},{"verse":6,"text":"E que meu servo Sidney Gilbert permaneça no ofício para o qual o designei, a fim de receber dinheiro, ser o agente da igreja, comprar terras em todas as regiões circunvizinhas, desde que isso se faça em retidão e como a prudência ditar."},{"verse":7,"text":"E que meu servo Edward Partridge ocupe o cargo para o qual o designei e divida entre os santos a herança, como eu ordenei; e também os que ele nomeou para assisti-lo."},{"verse":8,"text":"E também em verdade vos digo: Que meu servo Sidney Gilbert se estabeleça neste lugar e monte uma loja para vender mercadorias sem fraude, a fim de obter dinheiro para comprar terras para o bem dos santos e a fim de obter tudo o que os discípulos necessitarem para estabelecer-se em sua herança."},{"verse":9,"text":"E que também meu servo Sidney Gilbert obtenha uma licença — eis que aqui há sabedoria e aquele que ler que compreenda — para que também possa enviar mercadorias ao povo, por intermédio daqueles que ele desejar como empregados;"},{"verse":10,"text":"E assim abastecer meus santos a fim de que meu evangelho possa ser pregado aos que estão nas trevas e na região e sombra da morte."},{"verse":11,"text":"E também em verdade vos digo: Que meu servo William W. Phelps se estabeleça neste lugar como impressor da igreja."},{"verse":12,"text":"E se o mundo receber seus escritos — eis que aqui há sabedoria — que obtenha o que puder obter em retidão, para o bem dos santos."},{"verse":13,"text":"E que meu servo Oliver Cowdery o assista, sim, como ordenei, em qualquer lugar que eu lhe designar, a fim de copiar, corrigir e selecionar, para que todas as coisas sejam feitas corretamente perante mim, como for confirmado pelo Espírito por intermédio dele."},{"verse":14,"text":"E assim, que aqueles que mencionei se estabeleçam na terra de Sião com suas famílias, o mais depressa possível, para fazerem as coisas de acordo com o que falei."},{"verse":15,"text":"E agora, com respeito à reunião: Que o bispo e o agente façam preparativos para as famílias que receberam ordem de vir para esta terra, o mais depressa possível; e estabeleçam-nas em sua herança."},{"verse":16,"text":"E aos demais élderes e membros, outras instruções serão dadas mais tarde. Assim seja. Amém."}]},{"chapter":58,"verses":[{"verse":1,"text":"Escutai, ó élderes de minha igreja, e dai ouvidos à minha palavra, e aprendei de mim a minha vontade concernente a vós, e também a esta terra para a qual vos enviei."},{"verse":2,"text":"Pois em verdade vos digo: Bem-aventurado é o que guarda meus mandamentos, seja na vida ou na morte; e o que é fiel nas tribulações recebe maior recompensa no reino do céu."},{"verse":3,"text":"Por agora não podeis, com vossos olhos naturais, ver o desígnio de vosso Deus com respeito às coisas que virão mais tarde nem a glória que se seguirá depois de muitas tribulações."},{"verse":4,"text":"Pois após muitas tribulações vêm as bênçãos. Portanto, vem o dia em que sereis coroados de muita glória; ainda não é chegada a hora, mas está próxima."},{"verse":5,"text":"Lembrai-vos disto, que eu vos digo de antemão, para que o guardeis no coração e recebais o que se seguirá."},{"verse":6,"text":"Eis que em verdade vos digo, que por este motivo vos enviei — para que fôsseis obedientes e para que vosso coração estivesse preparado para prestar testemunho das coisas que estão para vir;"},{"verse":7,"text":"E também para que tivésseis a honra de estabelecer o alicerce e de testificar quanto à terra na qual a Sião de Deus será edificada;"},{"verse":8,"text":"E também para que um banquete de coisas gordas fosse preparado para os pobres; sim, um banquete de coisas gordas, de vinho puro bem refinado, para que a Terra saiba que a boca dos profetas não falhará;"},{"verse":9,"text":"Sim, uma ceia da casa do Senhor, bem preparada, para a qual todas as nações serão convidadas."},{"verse":10,"text":"Primeiro o rico e o instruído, o sábio e o nobre;"},{"verse":11,"text":"E depois vem o dia do meu poder; então o pobre, o coxo e o cego e o surdo virão às bodas do Cordeiro e participarão da ceia do Senhor, preparada para o grande dia que virá."},{"verse":12,"text":"Eis que eu, o Senhor, o disse."},{"verse":13,"text":"E para que o testemunho saia de Sião, sim, da boca da cidade da herança de Deus —"},{"verse":14,"text":"Sim, por essa razão mandei-vos aqui e escolhi meu servo Edward Partridge e designei-lhe sua missão nesta terra."},{"verse":15,"text":"Mas se ele não se arrepender de seus pecados, que são incredulidade e cegueira de coração, que se acautele para não cair."},{"verse":16,"text":"Eis que lhe é dada sua missão e não será dada outra vez."},{"verse":17,"text":"E quem tem essa missão é designado para ser juiz em Israel, como nos tempos antigos, para dividir as terras da herança de Deus entre seus filhos;"},{"verse":18,"text":"E para julgar seu povo pelo testemunho dos justos e com a assistência de seus conselheiros, de acordo com as leis do reino, que são dadas pelos profetas de Deus."},{"verse":19,"text":"Pois em verdade vos digo: Minha lei será observada nesta terra."},{"verse":20,"text":"Que ninguém se julgue governante; mas que governe Deus o que julga, de acordo com sua própria vontade ou, em outras palavras, o que aconselha ou se assenta na cadeira de juiz."},{"verse":21,"text":"Que ninguém quebre as leis do país, porque o que guarda as leis de Deus não tem necessidade de quebrar as leis do país."},{"verse":22,"text":"Portanto, sujeitai-vos aos poderes existentes até que reine aquele cujo direito é reinar; e subjugue todos os inimigos sob seus pés."},{"verse":23,"text":"Eis que as leis que recebestes de minha mão são as leis da igreja e, como tal, considerá-las-eis. Eis que aqui há sabedoria."},{"verse":24,"text":"E agora, como falei a respeito de meu servo Edward Partridge, esta terra é a terra de sua residência e dos que ele nomeou como seus conselheiros; e também a terra da residência daquele a quem designei para cuidar de meu armazém;"},{"verse":25,"text":"Portanto, que tragam suas famílias para esta terra, como decidirem entre eles e mim."},{"verse":26,"text":"Pois eis que não é conveniente que em todas as coisas eu mande; pois o que é compelido em todas as coisas é servo indolente e não sábio; portanto, não recebe recompensa."},{"verse":27,"text":"Em verdade eu digo: Os homens devem ocupar-se zelosamente numa boa causa e fazer muitas coisas de sua livre e espontânea vontade e realizar muita retidão."},{"verse":28,"text":"Pois neles está o poder e nisso são seus próprios árbitros. E se os homens fizerem o bem, de modo algum perderão sua recompensa."},{"verse":29,"text":"Mas o que nada faz até que seja mandado e recebe um mandamento com o coração duvidoso e guarda-o com indolência, é condenado."},{"verse":30,"text":"Quem sou eu que fiz o homem, diz o Senhor, para considerar inocente o que não obedece aos meus mandamentos?"},{"verse":31,"text":"Quem sou eu, diz o Senhor, para prometer e não cumprir?"},{"verse":32,"text":"Eu mando, e os homens não obedecem; revogo, e eles não recebem a bênção."},{"verse":33,"text":"Depois dizem em seu coração: Esta não é a obra do Senhor, porque suas promessas não se cumprem. Mas ai deles, porque sua recompensa os espreita de baixo e não de cima."},{"verse":34,"text":"E agora eu vos dou mais instruções com respeito a esta terra."},{"verse":35,"text":"Considero conveniente que meu servo Martin Harris dê o exemplo à igreja, entregando seu dinheiro ao bispo da igreja."},{"verse":36,"text":"E também esta é uma lei para todo homem que vier para esta terra a fim de receber uma herança; e ele fará com seu dinheiro o que a lei determinar."},{"verse":37,"text":"E é prudente também que se comprem terras em Independence para o armazém e também para a tipografia."},{"verse":38,"text":"E outras instruções com respeito ao meu servo Martin Harris ser-lhe-ão dadas pelo Espírito, para que ele receba sua herança como lhe aprouver;"},{"verse":39,"text":"E que se arrependa de seus pecados, pois procura o louvor do mundo."},{"verse":40,"text":"E também que meu servo William W. Phelps ocupe o cargo para o qual o designei e receba sua herança na terra;"},{"verse":41,"text":"E também ele precisa arrepender-se porque eu, o Senhor, não estou satisfeito com ele, pois procura sobressair-se e não é suficientemente humilde perante mim."},{"verse":42,"text":"Eis que aquele que se arrependeu de seus pecados é perdoado e eu, o Senhor, deles não mais me lembro."},{"verse":43,"text":"Desta maneira sabereis se um homem se arrepende de seus pecados — eis que ele os confessará e abandonará."},{"verse":44,"text":"E agora, em verdade falo a respeito dos demais élderes de minha igreja; não chegará, por muitos anos, a hora de receberem sua herança nesta terra, a não ser que o desejem pela oração da fé e segundo o que lhes for designado pelo Senhor."},{"verse":45,"text":"Pois eis que dos confins da Terra reunirão os povos."},{"verse":46,"text":"Portanto, congregai-vos; e os que não forem designados para permanecer nesta terra, que preguem o evangelho nas regiões circunvizinhas; e depois disso, que regressem a seus lares."},{"verse":47,"text":"Que preguem pelo caminho e prestem testemunho da verdade em todos os lugares, chamando ao arrependimento os ricos, os nobres e os plebeus e os pobres."},{"verse":48,"text":"E que edifiquem igrejas, se os habitantes da Terra se arrependerem."},{"verse":49,"text":"E que pela voz da igreja seja nomeado um agente para a igreja de Ohio, a fim de receber dinheiro para a compra de terras em Sião."},{"verse":50,"text":"E dou ao meu servo, Sidney Rigdon, o mandamento de fazer por escrito uma descrição da terra de Sião e uma exposição da vontade de Deus, como lhe for manifestada pelo Espírito;"},{"verse":51,"text":"E uma epístola e uma subscrição, para serem apresentadas a todas as igrejas com o fim de obter dinheiro para ser entregue nas mãos do bispo ou do agente, como lhe parecer melhor ou como determinar, com o propósito de comprar terras para herança dos filhos de Deus."},{"verse":52,"text":"Pois eis que em verdade vos digo que o Senhor deseja que os discípulos e os filhos dos homens abram o coração para comprar toda esta região o mais depressa possível."},{"verse":53,"text":"Eis que aqui há sabedoria. Que façam isto; do contrário não receberão qualquer herança, a não ser por derramamento de sangue."},{"verse":54,"text":"E também, quando se obtiverem terras, que se envie trabalhadores de toda classe a esta terra, a fim de trabalharem para os santos de Deus."},{"verse":55,"text":"Que todas essas coisas sejam feitas em ordem; e que os privilégios das terras sejam anunciados de tempos em tempos pelo bispo ou pelo agente da igreja."},{"verse":56,"text":"E que o trabalho da reunião não seja feito às pressas nem fugindo, mas seja feito conforme aconselharem os élderes da igreja nas conferências, de acordo com o conhecimento que eles receberem de tempos em tempos."},{"verse":57,"text":"E que meu servo Sidney Rigdon consagre e dedique ao Senhor esta terra e o local para o templo."},{"verse":58,"text":"E que se convoque uma conferência; e que depois os meus servos Sidney Rigdon e Joseph Smith Júnior regressem; e também Oliver Cowdery com eles, para concluírem o restante da obra que lhes designei em sua própria terra; e o restante, como for determinado pelas conferências."},{"verse":59,"text":"E que nenhum homem regresse desta terra sem testificar pelo caminho aquilo que sabe e em que seguramente acredita."},{"verse":60,"text":"E que seja tirado de Ziba Peterson o que lhe foi conferido; e que ele permaneça como membro da igreja e trabalhe com as próprias mãos, juntamente com os irmãos, até que seja suficientemente castigado por todos os seus pecados, pois ele não os confessa e pensa escondê-los."},{"verse":61,"text":"Que os demais élderes desta igreja, que estão vindo para esta terra, alguns dos quais são extremamente abençoados, também realizem uma conferência nesta terra."},{"verse":62,"text":"E que meu servo Edward Partridge dirija a conferência que será realizada por eles."},{"verse":63,"text":"E que também regressem pregando o evangelho pelo caminho, testificando quanto às coisas que lhes forem reveladas."},{"verse":64,"text":"Pois, em verdade, o som deverá partir deste lugar para todo o mundo e para os confins da Terra — o evangelho deverá ser pregado a toda criatura; e sinais seguirão os que crerem."},{"verse":65,"text":"E eis que o Filho do Homem vem. Amém."}]},{"chapter":59,"verses":[{"verse":1,"text":"Eis que, diz o Senhor, bem-aventurados são os que subiram a esta terra com os olhos fitos na minha glória, de acordo com meus mandamentos."},{"verse":2,"text":"Porque os que viverem herdarão a Terra e os que morrerem descansarão de todos os seus labores e suas obras segui-los-ão; e nas mansões de meu Pai, que lhes preparei, receberão uma coroa."},{"verse":3,"text":"Sim, bem-aventurados aqueles cujos pés estão sobre a terra de Sião, que obedeceram a meu evangelho; pois receberão como recompensa as coisas boas da terra e ela produzirá com sua força."},{"verse":4,"text":"E também serão coroados com bênçãos do alto, sim, e com mandamentos, não poucos, e com revelações em seu tempo — aqueles que são fiéis e diligentes perante mim."},{"verse":5,"text":"Portanto, dou-lhes um mandamento que diz assim: Amarás o Senhor teu Deus de todo o teu coração, de todo o teu poder, mente e força; e em nome de Jesus Cristo servi-lo-ás."},{"verse":6,"text":"Amarás o teu próximo como a ti mesmo. Não furtarás nem cometerás adultério nem matarás nem farás coisa alguma semelhante."},{"verse":7,"text":"Agradecerás ao Senhor teu Deus em todas as coisas."},{"verse":8,"text":"Oferecerás um sacrifício ao Senhor teu Deus em retidão, sim, um coração quebrantado e um espírito contrito."},{"verse":9,"text":"E para que mais plenamente te conserves limpo das manchas do mundo, irás à casa de oração e oferecerás teus sacramentos no meu dia santificado;"},{"verse":10,"text":"Porque em verdade esse é um dia designado para descansares de teus labores e prestares tua devoção ao Altíssimo;"},{"verse":11,"text":"Contudo, teus votos serão oferecidos em retidão todos os dias e em todos os momentos;"},{"verse":12,"text":"Lembra-te, porém, de que no dia do Senhor oferecerás tuas oblações e teus sacramentos ao Altíssimo, confessando teus pecados a teus irmãos e perante o Senhor."},{"verse":13,"text":"E nesse dia não farás qualquer outra coisa; seja teu alimento preparado com singeleza de coração para que teu jejum seja perfeito, ou, em outras palavras, para que tua alegria seja completa."},{"verse":14,"text":"Em verdade, isto é jejum e oração, ou, em outras palavras, regozijo e oração."},{"verse":15,"text":"E se fizerdes estas coisas com ação de graças, com o coração e o semblante alegres, sem muito riso porque isso é pecado, mas com o coração feliz e o semblante alegre —"},{"verse":16,"text":"Em verdade eu digo que, se isso fizerdes, a plenitude da Terra será vossa, as feras do campo e as aves do céu e aquilo que sobe nas árvores e anda na terra;"},{"verse":17,"text":"Sim, e as ervas e as coisas boas que provêm da terra, sejam para alimento ou para vestuário ou para casas ou para estábulos ou para pomares ou para hortas ou para vinhas;"},{"verse":18,"text":"Sim, todas as coisas que provêm da terra, em sua estação, são feitas para o benefício e uso do homem, tanto para agradar aos olhos como para alegrar o coração;"},{"verse":19,"text":"Sim, para servir de alimento e para vestuário, para o paladar e o olfato, para fortalecer o corpo e avivar a alma."},{"verse":20,"text":"E agrada a Deus ter dado ao homem todas essas coisas; pois para esse fim foram feitas, para serem usadas com discernimento, não com excesso nem por extorsão."},{"verse":21,"text":"E em nada ofende o homem a Deus ou contra ninguém está acesa sua ira, a não ser contra os que não confessam sua mão em todas as coisas e não obedecem a seus mandamentos."},{"verse":22,"text":"Eis que isto está de acordo com a lei e os profetas; portanto, não me importuneis mais a respeito deste assunto."},{"verse":23,"text":"Aprendei que aquele que pratica as obras da retidão receberá sua recompensa, sim, paz neste mundo e vida eterna no mundo vindouro."},{"verse":24,"text":"Eu, o Senhor, disse-o e o Espírito testifica. Amém."}]},{"chapter":60,"verses":[{"verse":1,"text":"Eis que assim diz o Senhor aos élderes de sua igreja, que deverão regressar rapidamente à terra de onde vieram: Eis que me agrada terdes vindo até aqui;"},{"verse":2,"text":"Com alguns, porém, não estou satisfeito, porque não abrem a boca; mas escondem o talento que lhes dei, por causa do temor aos homens. Ai desses, porque contra eles está acesa a minha ira."},{"verse":3,"text":"E acontecerá que, se não forem mais fiéis a mim, deles será tirado até aquilo que têm."},{"verse":4,"text":"Porque eu, o Senhor, governo em cima nos céus e entre os exércitos da Terra; e no dia em que eu reunir minhas joias, todos os homens saberão o que é que revela o poder de Deus."},{"verse":5,"text":"Mas em verdade falar-vos-ei a respeito de vossa viagem à terra de onde viestes. Que seja feita ou comprada uma embarcação, como vos parecer melhor, a mim não importa, e viajai rapidamente para o lugar chamado St. Louis."},{"verse":6,"text":"E que, de lá, meus servos Sidney Rigdon, Joseph Smith Júnior e Oliver Cowdery viajem para Cincinnati;"},{"verse":7,"text":"E que nesse lugar levantem a voz e proclamem minha palavra em alta voz, sem ira nem dúvida, levantando mãos santas sobre eles. Porque posso tornar-vos santos e vossos pecados vos são perdoados."},{"verse":8,"text":"E que os demais partam de St. Louis, de dois em dois, e preguem a palavra, sem pressa, entre as congregações dos iníquos, até regressarem às igrejas de onde vieram."},{"verse":9,"text":"E tudo isso para o bem das igrejas; com esse intento enviei-os."},{"verse":10,"text":"E que meu servo Edward Partridge destine uma parte do dinheiro que lhe dei a meus élderes que têm ordem de regressar;"},{"verse":11,"text":"E aquele que puder, que o restitua por meio do agente; e o que não puder, dele não se exigirá."},{"verse":12,"text":"E agora falo dos outros que hão de vir para esta terra."},{"verse":13,"text":"Eis que eles foram enviados para pregar meu evangelho entre as congregações dos iníquos; portanto, dou-lhes o seguinte mandamento: Não desperdiçarás teu tempo nem enterrarás teu talento, de modo que não seja conhecido."},{"verse":14,"text":"E depois que tiveres vindo à terra de Sião e proclamado minha palavra, regressarás rapidamente, proclamando minha palavra entre as congregações dos iníquos, sem pressa, sem ira nem contendas."},{"verse":15,"text":"E sacode o pó de teus pés contra os que não te receberem, não em sua presença, para não provocá-los, mas em segredo; e lava teus pés, como testemunho contra eles no dia do juízo."},{"verse":16,"text":"Eis que isto vos é suficiente e é a vontade daquele que vos enviou."},{"verse":17,"text":"E pela boca de meu servo Joseph Smith Júnior saber-se-á a respeito de Sidney Rigdon e Oliver Cowdery. Quanto ao restante, mais tarde. Assim seja. Amém."}]},{"chapter":61,"verses":[{"verse":1,"text":"Vede e escutai a voz daquele que tem todo o poder, que é de eternidade em eternidade, sim, o Alfa e o Ômega, o princípio e o fim."},{"verse":2,"text":"Eis que em verdade assim vos diz o Senhor, ó élderes de minha igreja, que estais reunidos neste lugar e cujos pecados vos são agora perdoados, pois eu, o Senhor, perdoo pecados e sou misericordioso para com aqueles que confessam seus pecados com o coração humilde;"},{"verse":3,"text":"Mas, em verdade vos digo que não é necessário que todo este grupo de meus élderes se mova rapidamente sobre as águas, enquanto os habitantes, em ambos os lados, perecem na incredulidade."},{"verse":4,"text":"Contudo, permiti-o, para que pudésseis testificar; eis que há muitos perigos sobre as águas e mais especialmente daqui para a frente;"},{"verse":5,"text":"Porque eu, o Senhor, em minha ira decretei muitas destruições sobre as águas; sim, e especialmente sobre estas águas."},{"verse":6,"text":"Contudo, toda carne está em minha mão; e o que dentre vós for fiel não perecerá por meio das águas."},{"verse":7,"text":"Portanto, é conveniente que meu servo Sidney Gilbert e meu servo William W. Phelps se apressem na sua incumbência e missão."},{"verse":8,"text":"Contudo, eu não podia permitir que partísseis até que tivésseis sido repreendidos por todos os vossos pecados, a fim de que fôsseis um, para que não perecêsseis em iniquidade;"},{"verse":9,"text":"Mas agora, em verdade eu digo: É minha vontade que partais. Portanto, que meus servos Sidney Gilbert e William W. Phelps tomem seus antigos companheiros e viajem rapidamente, para que cumpram sua missão; e pela fé vencerão;"},{"verse":10,"text":"E se forem fiéis, serão preservados; e eu, o Senhor, estarei com eles."},{"verse":11,"text":"E que os demais levem as roupas de que necessitarem."},{"verse":12,"text":"Que meu servo Sidney Gilbert leve consigo o que não for indispensável, conforme determinardes."},{"verse":13,"text":"E agora eis que, para vosso bem, vos dei um mandamento concernente a estas coisas; e eu, o Senhor, arrazoarei convosco como com os homens na antiguidade."},{"verse":14,"text":"Eis que eu, o Senhor, no princípio abençoei as águas; nos últimos dias, porém, pela boca de meu servo João, amaldiçoei as águas."},{"verse":15,"text":"Portanto, dias virão em que carne alguma estará segura sobre as águas."},{"verse":16,"text":"E dias virão em que se dirá que ninguém poderá subir à terra de Sião sobre as águas, a não ser o que for reto de coração."},{"verse":17,"text":"E como eu, o Senhor, no princípio amaldiçoei a terra, assim nos últimos dias abençoei-a, em seu tempo, para uso de meus santos, a fim de que partilhem de sua gordura."},{"verse":18,"text":"E agora vos dou um mandamento — e o que digo a um digo a todos — de que antecipadamente aviseis vossos irmãos a respeito destas águas, a fim de que, ao viajarem sobre elas, não falhe a sua fé e sejam apanhados em armadilhas;"},{"verse":19,"text":"Eu, o Senhor, decretei e o destruidor move-se sobre sua superfície; e não revogo o decreto."},{"verse":20,"text":"Eu, o Senhor, estava irado convosco ontem, mas hoje minha ira desviou-se."},{"verse":21,"text":"Portanto, que aqueles de quem falei viajem apressadamente; novamente vos digo: Que viajem apressadamente."},{"verse":22,"text":"E depois de pouco tempo não me importa como viajem, se por água, se por terra, desde que cumpram sua missão; que se faça de acordo com o que lhes for revelado, segundo seu parecer daqui em diante."},{"verse":23,"text":"E agora, concernente a meus servos Sidney Rigdon, Joseph Smith Júnior e Oliver Cowdery: Que não venham mais sobre as águas, a não ser que seja pelo canal, quando viajarem para suas casas; ou, em outras palavras, não deverão viajar sobre as águas, a não ser pelo canal."},{"verse":24,"text":"Eis que eu, o Senhor, determinei a meus santos a maneira de viajar; e eis que esta é a maneira: que após saírem do canal viajem por terra, sendo que lhes foi ordenado que subam para a terra de Sião;"},{"verse":25,"text":"E farão como os filhos de Israel, armando suas tendas pelo caminho."},{"verse":26,"text":"E eis que dareis este mandamento a todos os vossos irmãos."},{"verse":27,"text":"Contudo, àquele a quem é dado poder para comandar as águas, a ele é dado, pelo Espírito, conhecer todos os seus caminhos;"},{"verse":28,"text":"Portanto, que faça como o Espírito do Deus vivo lhe ordenar, seja na terra ou sobre as águas, conforme eu desejar daqui em diante."},{"verse":29,"text":"E a vós é dado o curso para os santos, ou seja, o caminho pelo qual os santos do acampamento do Senhor deverão viajar."},{"verse":30,"text":"E também em verdade vos digo: Meus servos Sidney Rigdon, Joseph Smith Júnior e Oliver Cowdery não deverão abrir a boca nas congregações dos iníquos, até que cheguem a Cincinnati;"},{"verse":31,"text":"E nesse lugar elevarão a sua voz a Deus contra esse povo, sim, àquele cuja ira está acesa contra suas iniquidades, um povo que está quase amadurecido para a destruição."},{"verse":32,"text":"E de lá seguirão rumo às congregações de seus irmãos, porque suas obras são agora mais necessárias entre eles do que nas congregações dos iníquos."},{"verse":33,"text":"E agora, concernente aos demais, que viajem e declarem a palavra entre as congregações dos iníquos, como lhes é manifestada;"},{"verse":34,"text":"E se assim fizerem, purificarão suas vestes e ficarão imaculados perante mim."},{"verse":35,"text":"E que viajem juntos, ou de dois em dois, como lhes parecer melhor, mas o meu servo Reynolds Cahoon e o meu servo Samuel H. Smith, com quem me comprazo, não devem ser separados até que voltem para casa; e isto para um sábio propósito meu."},{"verse":36,"text":"E agora, em verdade vos digo e o que digo a um digo a todos: Tende bom ânimo, filhinhos; pois estou no vosso meio e não vos desamparei;"},{"verse":37,"text":"E sendo que vos humilhastes perante mim, as bênçãos do reino são vossas."},{"verse":38,"text":"Cingi vossos lombos e vigiai e sede sóbrios, esperando a vinda do Filho do Homem, pois ele virá numa hora em que não pensais."},{"verse":39,"text":"Orai sempre para não entrardes em tentação, para que suporteis o dia de sua vinda, seja na vida ou na morte. Assim seja. Amém."}]},{"chapter":62,"verses":[{"verse":1,"text":"Eis que, escutai, ó élderes de minha igreja, diz o Senhor vosso Deus, sim, Jesus Cristo, vosso advogado, que conhece as fraquezas dos homens e sabe como socorrer os que são tentados."},{"verse":2,"text":"E em verdade meus olhos estão sobre os que ainda não subiram à terra de Sião; portanto, vossa missão ainda não está completa."},{"verse":3,"text":"Não obstante, bem-aventurados sois, porque o testemunho que prestastes está registrado no céu para ser visto pelos anjos; e eles se regozijam por vós e vossos pecados vos são perdoados."},{"verse":4,"text":"E agora continuai vossa viagem. Reuni-vos na terra de Sião; realizai uma reunião e rejubilai-vos juntos e oferecei um sacramento ao Altíssimo."},{"verse":5,"text":"E então podereis regressar para testificar, sim, todos juntos ou de dois em dois, como vos parecer melhor, a mim não importa; somente sede fiéis e anunciai alegres novas aos habitantes da Terra ou entre as congregações dos iníquos."},{"verse":6,"text":"Eis que eu, o Senhor, vos reuni para que se cumprisse a promessa de que aqueles de vós que fossem fiéis seriam preservados e juntos se regozijariam na terra de Missouri. Eu, o Senhor, prometo aos fiéis e não posso mentir."},{"verse":7,"text":"Eu, o Senhor, estou de acordo, se qualquer de vós desejar viajar a cavalo ou em mulas ou em carroças, que receba essa bênção, se a receber da mão do Senhor com um coração grato em todas as coisas."},{"verse":8,"text":"Essas coisas vos são dadas para que as façais com discernimento e conforme as orientações do Espírito."},{"verse":9,"text":"Eis que vosso é o reino. E eis que eu estou sempre com os fiéis. Assim seja. Amém."}]},{"chapter":63,"verses":[{"verse":1,"text":"Escutai, ó povo, e abri o coração e de longe ouvi; e escutai, vós que vos chamais povo do Senhor; e ouvi a palavra do Senhor e a sua vontade a respeito de vós."},{"verse":2,"text":"Sim, em verdade digo: Ouvi a palavra daquele cuja ira está acesa contra os iníquos e os rebeldes;"},{"verse":3,"text":"O qual toma a quem deseja tomar e preserva a vida daqueles que deseja preservar;"},{"verse":4,"text":"Que constrói conforme seu desejo e prazer; e destrói quando lhe apraz e pode lançar a alma ao inferno."},{"verse":5,"text":"Eis que eu, o Senhor, faço ouvir a minha voz, e ela será obedecida."},{"verse":6,"text":"Portanto, em verdade eu digo: Que os iníquos prestem atenção e que os rebeldes temam e estremeçam; e que os incrédulos fechem os lábios, pois o dia da ira cairá sobre eles como um furacão; e toda carne saberá que eu sou Deus."},{"verse":7,"text":"E o que busca sinais verá sinais, mas não para a salvação."},{"verse":8,"text":"Em verdade vos digo: Há entre vós quem busque sinais e tem havido desde o princípio."},{"verse":9,"text":"Mas eis que a fé não vem por sinais, mas sinais seguem os que creem."},{"verse":10,"text":"Sim, sinais vêm pela fé, não pela vontade do homem nem como lhes agrada, mas pela vontade de Deus."},{"verse":11,"text":"Sim, sinais vêm pela fé, para produzir obras grandiosas, pois sem fé homem algum agrada a Deus; e Deus não se agrada daquele com quem está irado; portanto, a esses não mostra qualquer sinal, a não ser com ira, para sua condenação."},{"verse":12,"text":"Portanto, eu, o Senhor, não me agrado daqueles de vós que têm procurado sinais e maravilhas para alcançar a fé e não em benefício dos homens para minha glória."},{"verse":13,"text":"Contudo, dou mandamentos e muitos se afastaram de meus mandamentos e não os guardaram."},{"verse":14,"text":"Houve entre vós adúlteros e adúlteras; alguns deles se afastaram de vós e outros, que mais tarde serão revelados, permanecem convosco."},{"verse":15,"text":"Que esses se acautelem e se arrependam depressa, para que o julgamento não recaia sobre eles como uma armadilha e sua loucura seja manifestada e suas obras, aos olhos do povo, os acompanhem."},{"verse":16,"text":"E em verdade vos digo, como disse antes: Aquele que olhar para uma mulher para a cobiçar, ou se alguém em seu coração cometer adultério, não terá o Espírito, mas negará a fé e temerá."},{"verse":17,"text":"Portanto, eu, o Senhor, disse que o medroso e o incrédulo e todos os mentirosos e aqueles que amam e cometem a mentira, bem como o libertino e o feiticeiro, terão sua parte no lago que arde com fogo e enxofre, que é a segunda morte."},{"verse":18,"text":"Em verdade eu digo que eles não terão parte na primeira ressurreição."},{"verse":19,"text":"E agora eis que eu, o Senhor, vos digo que não sois justificados, porque estas coisas existem entre vós."},{"verse":20,"text":"Contudo, o que permanecer na fé e fizer a minha vontade, vencerá; e, quando vier o dia da transfiguração, receberá uma herança na Terra;"},{"verse":21,"text":"Quando a Terra for transfigurada, sim, de acordo com o modelo mostrado aos meus apóstolos sobre o monte; relato cuja plenitude ainda não recebestes."},{"verse":22,"text":"E agora, em verdade vos digo que, como disse que vos tornaria conhecida a minha vontade, eis que vo-la tornarei conhecida, não por meio de mandamento, pois há muitos que não se esforçam para guardar meus mandamentos."},{"verse":23,"text":"Mas ao que guarda meus mandamentos darei os mistérios de meu reino; e será como uma fonte de água viva vertendo para a vida eterna."},{"verse":24,"text":"E agora, eis que esta é a vontade do Senhor vosso Deus concernente a seus santos: Que se reúnam na terra de Sião, não às pressas, para que não haja confusão, a qual produz pestilência."},{"verse":25,"text":"Eis a terra de Sião — eu, o Senhor, retenho-a em minhas próprias mãos;"},{"verse":26,"text":"Contudo, eu, o Senhor, dou a César as coisas que são de César."},{"verse":27,"text":"Portanto, eu, o Senhor, desejo que compreis as terras para que tenhais vantagem no mundo, para que tenhais direitos sobre o mundo, para que eles não sejam levados a encolerizarem-se."},{"verse":28,"text":"Porque Satanás incute-lhes no coração, contra vós, a ira e o derramamento de sangue."},{"verse":29,"text":"Portanto, a terra de Sião não será obtida a não ser por compra ou por sangue; caso contrário, não há herança para vós."},{"verse":30,"text":"E se por compra, eis que sois bem-aventurados;"},{"verse":31,"text":"E se por sangue, como vos é proibido derramar sangue, eis que vossos inimigos estarão sobre vós e sereis flagelados de cidade em cidade e de sinagoga em sinagoga; e apenas poucos restarão para receber a herança."},{"verse":32,"text":"Eu, o Senhor, estou irado com os iníquos; estou negando meu Espírito aos habitantes da Terra."},{"verse":33,"text":"Em minha ira jurei e decretei guerras sobre a face da Terra; e o iníquo matará o iníquo e temor virá sobre todo homem;"},{"verse":34,"text":"E os santos também mal escaparão; contudo, eu, o Senhor, estou com eles e, da presença de meu Pai, descerei no céu e consumirei os iníquos com fogo inextinguível."},{"verse":35,"text":"E eis que isso não é já, mas dentro em pouco."},{"verse":36,"text":"Portanto, uma vez que eu, o Senhor, decretei todas estas coisas sobre a face da Terra, desejo que meus santos se reúnam na terra de Sião;"},{"verse":37,"text":"E que todo homem tome a retidão em suas mãos e cinja seus lombos com a fidelidade; e aos habitantes da Terra levante uma voz de advertência e declare, tanto por palavra como por fuga, que a desolação virá sobre os iníquos."},{"verse":38,"text":"Portanto, que meus discípulos em Kirtland, que moram nesta fazenda, ponham em ordem seus interesses materiais."},{"verse":39,"text":"Que meu servo Titus Billings, que dela é encarregado, disponha da terra a fim de estar preparado na próxima primavera, com os que nela habitam, para viajar para a terra de Sião, com exceção daqueles que reservarei para mim mesmo e que não irão até que eu ordene."},{"verse":40,"text":"E que todo o dinheiro disponível, não me importa se pouco ou muito, seja mandado à terra de Sião, aos que designei para recebê-lo."},{"verse":41,"text":"Eis que eu, o Senhor, darei a meu servo Joseph Smith Júnior poder para discernir pelo Espírito os que subirão à terra de Sião e os de meus discípulos que ficarão."},{"verse":42,"text":"Que meu servo Newel K. Whitney mantenha sua loja, ou, em outras palavras, a loja, ainda por algum tempo."},{"verse":43,"text":"Contudo, que dê todo o dinheiro que possa dar, para que seja mandado à terra de Sião."},{"verse":44,"text":"Eis que estas coisas estão em suas mãos; que ele aja com sabedoria."},{"verse":45,"text":"Em verdade eu digo: Que seja ele ordenado agente dos discípulos que ficarem e que seja ordenado com esse poder;"},{"verse":46,"text":"E que agora visite depressa as igrejas com meu servo Oliver Cowdery, expondo-lhes estas coisas. Eis que esta é a minha vontade — obter dinheiro como orientei."},{"verse":47,"text":"Aquele que for fiel e perseverar, vencerá o mundo."},{"verse":48,"text":"Aquele que enviar tesouros à terra de Sião receberá uma herança neste mundo e também uma recompensa no mundo vindouro; e suas obras segui-lo-ão."},{"verse":49,"text":"Sim, e bem-aventurados os que morrerem no Senhor, daqui em diante, pois quando o Senhor vier e as coisas velhas passarem e todas as coisas se tornarem novas, eles se levantarão dentre os mortos e não mais morrerão; e na cidade santa receberão uma herança perante o Senhor."},{"verse":50,"text":"E o que estiver vivo quando o Senhor vier e tiver guardado a fé, bem-aventurado será; contudo, é-lhe designado morrer na idade do homem."},{"verse":51,"text":"Portanto, as crianças irão crescer até se tornarem velhas; os velhos morrerão, mas não dormirão no pó; antes, serão transformados num piscar de olhos."},{"verse":52,"text":"Portanto, por esse motivo pregaram os apóstolos ao mundo a ressurreição dos mortos."},{"verse":53,"text":"Estas são as coisas que deveis procurar; e, falando à maneira do Senhor, elas agora estão próximas e num tempo futuro, sim, no dia da vinda do Filho do Homem."},{"verse":54,"text":"E até aquela hora haverá virgens néscias entre as prudentes; e naquela hora haverá uma separação total dos justos e dos iníquos; e naquele dia mandarei meus anjos para arrancar os iníquos e arremessá-los no fogo inextinguível."},{"verse":55,"text":"E agora, eis que em verdade vos digo: Eu, o Senhor, não estou satisfeito com meu servo Sidney Rigdon; ele exaltou-se a si mesmo em seu coração e não recebeu conselho, mas ofendeu o Espírito;"},{"verse":56,"text":"Portanto, o que escreveu não é aceitável ao Senhor e ele deverá fazê-lo de novo; e se o Senhor não o aceitar, eis que ele não mais permanecerá no cargo para o qual o designei."},{"verse":57,"text":"E também em verdade vos digo: Aqueles que em seu coração e com humildade desejarem chamar os pecadores ao arrependimento, sejam ordenados com esse poder."},{"verse":58,"text":"Pois este é um dia de advertência e não de muitas palavras. Pois eu, o Senhor, não serei escarnecido nos últimos dias."},{"verse":59,"text":"Eis que eu sou de cima e meu poder jaz abaixo. Eu estou sobre tudo e em tudo e através de tudo e penetro todas as coisas; e vem o dia em que todas as coisas me serão sujeitas."},{"verse":60,"text":"Eis que sou o Alfa e o Ômega, sim, Jesus Cristo."},{"verse":61,"text":"Portanto, que todos os homens se acautelem de como tomam meu nome em seus lábios —"},{"verse":62,"text":"Pois eis que em verdade eu digo que muitos há que estão sob esta condenação, que usam o nome do Senhor e usam-no em vão, não tendo autoridade."},{"verse":63,"text":"Portanto, que a igreja se arrependa de seus pecados e eu, o Senhor, possuí-los-ei; do contrário, serão cortados."},{"verse":64,"text":"Lembrai-vos de que aquilo que vem de cima é sagrado e deve ser mencionado com cuidado e por indução do Espírito; e nisto não há condenação alguma e recebereis o Espírito por meio de oração; portanto, sem isto permanece a condenação."},{"verse":65,"text":"Que meus servos Joseph Smith Júnior e Sidney Rigdon procurem para si uma casa, como forem instruídos pelo Espírito por meio de oração."},{"verse":66,"text":"Estas coisas devem ser vencidas pela paciência, para que recebam um peso eterno de glória mais excelente; de outra maneira, receberão uma condenação maior. Amém."}]},{"chapter":64,"verses":[{"verse":1,"text":"Eis que assim vos diz o Senhor vosso Deus: Ó élderes da minha igreja, atendei e ouvi, e recebei a minha vontade concernente a vós."},{"verse":2,"text":"Pois em verdade vos digo: Desejo que vençais o mundo; portanto, terei compaixão de vós."},{"verse":3,"text":"Há entre vós aqueles que pecaram; mas em verdade eu digo que, por esta vez, para minha glória e para a salvação das almas, perdoei-vos vossos pecados."},{"verse":4,"text":"Serei misericordioso convosco, pois a vós dei o reino."},{"verse":5,"text":"E as chaves dos mistérios do reino não serão tiradas de meu servo Joseph Smith Júnior pelos meios que designei, enquanto ele viver, caso ele obedeça às minhas ordenanças."},{"verse":6,"text":"Há os que, sem razão, procuraram falhas nele;"},{"verse":7,"text":"Contudo, ele pecou; mas em verdade vos digo: Eu, o Senhor, perdoo os pecados daqueles que confessam seus pecados perante mim e pedem perdão, se não pecaram para morte."},{"verse":8,"text":"Meus discípulos, nos dias antigos, procuraram pretextos uns contra os outros e em seu coração não se perdoaram; e por esse mal foram afligidos e severamente repreendidos."},{"verse":9,"text":"Portanto, digo-vos que vos deveis perdoar uns aos outros; pois aquele que não perdoa a seu irmão suas ofensas está em condenação diante do Senhor; pois nele permanece o pecado maior."},{"verse":10,"text":"Eu, o Senhor, perdoarei a quem desejo perdoar, mas de vós é exigido que perdoeis a todos os homens."},{"verse":11,"text":"E devíeis dizer em vosso coração: Que julgue Deus entre mim e ti e te recompense de acordo com teus feitos."},{"verse":12,"text":"E aquele que não se arrepender de seus pecados e não os confessar, trareis perante a igreja e fareis com ele conforme vos dizem as escrituras, seja por mandamento ou por revelação."},{"verse":13,"text":"E isso fareis para que Deus seja glorificado — não porque não os perdoais, não tendo compaixão, mas para que sejais justificados aos olhos da lei, para que não ofendais aquele que é vosso legislador."},{"verse":14,"text":"Em verdade eu vos digo: Por esse motivo fareis estas coisas."},{"verse":15,"text":"Eis que eu, o Senhor, estava zangado com aquele que foi meu servo, Ezra Booth, e também com meu servo Isaac Morley, porque não guardaram a lei nem o mandamento;"},{"verse":16,"text":"Em seu coração procuraram o mal e eu, o Senhor, retive meu Espírito. Condenaram como mau aquilo em que não havia mal; contudo, perdoei meu servo Isaac Morley."},{"verse":17,"text":"E também meu servo Edward Partridge — eis que ele pecou e Satanás procura destruir-lhe a alma; mas quando estas coisas se lhes tornarem conhecidas e eles se arrependerem do mal, serão perdoados."},{"verse":18,"text":"E agora, em verdade eu digo que me é conveniente que meu servo Sidney Gilbert, dentro de algumas semanas, retorne a seus negócios e a sua função de agente na terra de Sião;"},{"verse":19,"text":"E aquilo que viu e ouviu seja dado a conhecer a meus discípulos, para que não pereçam. E por essa razão disse eu estas coisas."},{"verse":20,"text":"E também vos digo que, para que meu servo Isaac Morley não seja tentado além do que lhe seja possível suportar e aconselhe erradamente, em vosso prejuízo, ordenei que sua fazenda fosse vendida."},{"verse":21,"text":"Não desejo que meu servo Frederick G. Williams venda sua fazenda, porque eu, o Senhor, desejo manter na terra de Kirtland uma posição firme pelo espaço de cinco anos, nos quais não derrubarei os iníquos, a fim de, assim, poder salvar alguns."},{"verse":22,"text":"E depois disso eu, o Senhor, não considerarei culpado qualquer que vá à terra de Sião com o coração aberto; pois eu, o Senhor, exijo o coração dos filhos dos homens."},{"verse":23,"text":"Eis que o tempo presente se chama hoje até a vinda do Filho do Homem e, em verdade, é um dia de sacrifício e um dia para o dízimo de meu povo; pois aquele que paga o dízimo não será queimado na sua vinda."},{"verse":24,"text":"Porque depois de hoje vem a queima — falando à maneira do Senhor — pois, em verdade eu digo, que amanhã todos os soberbos e os que praticam iniquidade serão como o restolho; e queimá-los-ei, pois sou o Senhor dos Exércitos, e não pouparei quem permanecer em Babilônia."},{"verse":25,"text":"Portanto, se credes em mim, trabalhareis enquanto é hoje."},{"verse":26,"text":"E não é conveniente que meus servos Newel K. Whitney e Sidney Gilbert vendam sua loja e os bens que aqui possuem, porque isso não é prudente até que o restante da igreja que aqui se encontra suba para a terra de Sião."},{"verse":27,"text":"Eis que as minhas leis dizem, ou seja, proíbem contrair dívidas com os vossos inimigos;"},{"verse":28,"text":"Mas eis que em tempo algum se diz que o Senhor não poderá tomar quando quiser e pagar como lhe aprouver."},{"verse":29,"text":"Portanto, como sois agentes, estais a serviço do Senhor; e tudo o que fazeis de acordo com a vontade do Senhor é negócio do Senhor."},{"verse":30,"text":"E ele escolheu-vos para suprirdes a seus santos nestes últimos dias, a fim de que obtenham uma herança na terra de Sião."},{"verse":31,"text":"E eis que eu, o Senhor, vos declaro — e minhas palavras são certas e não falharão — que eles irão obtê-la."},{"verse":32,"text":"Todas as coisas, porém, deverão realizar-se a seu tempo."},{"verse":33,"text":"Portanto, não vos canseis de fazer o bem, porque estais lançando o alicerce de uma grande obra. E de pequenas coisas provém aquilo que é grande."},{"verse":34,"text":"Eis que o Senhor requer o coração e uma mente solícita; e os que são solícitos e obedientes comerão do bem da terra de Sião nestes últimos dias."},{"verse":35,"text":"E os rebeldes serão cortados da terra de Sião e afastados e não herdarão a terra."},{"verse":36,"text":"Pois em verdade eu digo que os rebeldes não são do sangue de Efraim; portanto, serão extirpados."},{"verse":37,"text":"Eis que eu, o Senhor, fiz minha igreja, nestes últimos dias, semelhante a um juiz sentado sobre um monte ou um lugar alto para julgar as nações."},{"verse":38,"text":"Pois acontecerá que os habitantes de Sião julgarão todas as coisas pertinentes a Sião."},{"verse":39,"text":"E por eles pôr-se-ão à prova os mentirosos e hipócritas e conhecer-se-ão os que não forem apóstolos e profetas."},{"verse":40,"text":"E até o bispo, que é um juiz, e seus conselheiros, se não forem fiéis em suas mordomias, serão condenados; e outros serão postos em seu lugar."},{"verse":41,"text":"Pois eis que vos digo que Sião florescerá e a glória do Senhor estará sobre ela;"},{"verse":42,"text":"E será um estandarte para o povo e a ela virão de todas as nações debaixo do céu."},{"verse":43,"text":"E chegará o dia em que as nações da Terra estremecerão por causa dela e temerão por causa de seus homens terríveis. O Senhor disse-o. Amém."}]},{"chapter":65,"verses":[{"verse":1,"text":"Escutai e ouvi uma voz como a de alguém enviado do alto, que é forte e poderoso, cujas idas chegam aos confins da Terra, sim, cuja voz se dirige aos homens: Preparai o caminho do Senhor, endireitai suas veredas."},{"verse":2,"text":"As chaves do reino de Deus foram confiadas ao homem na Terra, e dali rolará o evangelho até os confins da Terra, como a pedra cortada da montanha, sem mãos, rolará até encher toda a Terra."},{"verse":3,"text":"Sim, uma voz clamando: Preparai o caminho do Senhor, preparai a ceia do Cordeiro, aprontai-vos para o Esposo."},{"verse":4,"text":"Orai ao Senhor, invocai seu santo nome, divulgai suas obras maravilhosas entre o povo."},{"verse":5,"text":"Invocai o Senhor, para que seu reino siga pela Terra e seus habitantes recebam-no e estejam preparados para os dias que virão, nos quais o Filho do Homem descerá no céu, revestido do esplendor de sua glória, para encontrar o reino de Deus que está estabelecido na Terra."},{"verse":6,"text":"Portanto, que o reino de Deus vá avante para que venha o reino dos céus, a fim de que tu, ó Deus, sejas glorificado no céu e na Terra; que teus inimigos sejam subjugados; pois tua é a honra, o poder e a glória para todo o sempre. Amém."}]},{"chapter":66,"verses":[{"verse":1,"text":"Eis que assim diz o Senhor a meu servo William E. McLellin: Bem-aventurado és, visto que te afastaste de tuas iniquidades e recebeste minhas verdades, diz o Senhor teu Redentor, o Salvador do mundo, sim, de todos os que creem em meu nome."},{"verse":2,"text":"Em verdade eu te digo: Bem-aventurado és tu por receberes meu convênio eterno, sim, a plenitude do meu evangelho, enviado aos filhos dos homens para que tenham vida e tornem-se participantes das glórias que serão reveladas nos últimos dias, como foi escrito pelos profetas e apóstolos da antiguidade."},{"verse":3,"text":"Em verdade eu te digo, meu servo William, que estás limpo, mas não de todo; arrepende-te, portanto, das coisas que não são agradáveis a minha vista, diz o Senhor, pois o Senhor irá mostrá-las a ti."},{"verse":4,"text":"E agora, em verdade eu, o Senhor, mostrar-te-ei o que desejo em relação a ti, ou seja, qual é a minha vontade em relação a ti."},{"verse":5,"text":"Eis que em verdade eu te digo, que é a minha vontade que proclames o meu evangelho de terra em terra e de cidade em cidade, sim, nas regiões circunvizinhas onde ainda não tiver sido proclamado."},{"verse":6,"text":"Não te detenhas muitos dias neste lugar; não subas ainda à terra de Sião; mas o que puderes enviar, envia; também, não penses em tua propriedade."},{"verse":7,"text":"Vai às terras do leste, presta testemunho em todos os lugares, a todo o povo e em suas sinagogas, arrazoando com o povo."},{"verse":8,"text":"Que meu servo Samuel H. Smith vá contigo; não o abandones e dá-lhe tuas instruções; e o que for fiel se tornará forte em todo lugar; e eu, o Senhor, irei convosco."},{"verse":9,"text":"Impõe as mãos sobre os doentes e recuperar-se-ão. Não regresses até que eu, o Senhor, te ordene. Sê paciente na aflição. Pede e receberás; bate e ser-te-á aberto."},{"verse":10,"text":"Procura não te embaraçar. Abandona toda iniquidade. Não cometas adultério — tentação que te tem afligido."},{"verse":11,"text":"Obedece a estas palavras, pois são verdadeiras e fiéis; e magnificarás teu ofício e impelirás muita gente a Sião com cânticos de eterna alegria sobre suas cabeças."},{"verse":12,"text":"Persevera nestas coisas até o fim e terás uma coroa de vida eterna à direita de meu Pai, que é cheio de graça e verdade."},{"verse":13,"text":"Em verdade, assim diz o Senhor teu Deus, teu Redentor, sim, Jesus Cristo. Amém."}]},{"chapter":67,"verses":[{"verse":1,"text":"Eis aqui, escutai, ó élderes da minha igreja que vos reunistes, cujas orações ouvi e cujo coração conheço e cujos desejos subiram a mim."},{"verse":2,"text":"Olhai! Meus olhos estão sobre vós e os céus e a Terra estão em minhas mãos; e as riquezas da eternidade são minhas e posso dá-las."},{"verse":3,"text":"Esforçastes-vos para crer que receberíeis a bênção que vos fora oferecida; mas eis que em verdade vos digo que havia temores em vosso coração e, em verdade, esta é a razão por que não a recebestes."},{"verse":4,"text":"E agora eu, o Senhor, vos dou um testemunho da veracidade desses mandamentos que estão diante de vós."},{"verse":5,"text":"Vossos olhos têm estado sobre meu servo Joseph Smith Júnior, e sua linguagem e suas imperfeições vós conheceis e em vosso coração tendes procurado conhecimento para exprimir-vos em melhor linguagem do que ele; isto também sabeis."},{"verse":6,"text":"Ora, no Livro de Mandamentos procurai o menor deles e escolhei o mais sábio dentre vós;"},{"verse":7,"text":"Ou, se houver entre vós alguém que produza um semelhante, então sereis justificados em dizer que não sabeis se são verdadeiros;"},{"verse":8,"text":"Mas se não conseguirdes produzir um semelhante, estareis sob condenação se não testificardes serem eles verdadeiros."},{"verse":9,"text":"Pois sabeis que nenhuma iniquidade há neles e o que é justo vem do alto, do Pai das luzes."},{"verse":10,"text":"E também em verdade vos digo que é vosso privilégio e uma promessa faço a vós que fostes ordenados para este ministério que, se vos despirdes de invejas e temores e vos humilhardes perante mim, pois não sois suficientemente humildes, o véu será rompido e ver-me-eis e sabereis que eu sou — não com a mente carnal nem natural, mas com a espiritual."},{"verse":11,"text":"Pois em tempo algum, na carne, o homem viu Deus, a não ser vivificado pelo Espírito de Deus."},{"verse":12,"text":"Nem pode homem natural algum suportar a presença de Deus; nem segundo a mente carnal."},{"verse":13,"text":"Não podeis suportar a presença de Deus agora nem o ministério de anjos; portanto, continuai pacientemente até que sejais aperfeiçoados."},{"verse":14,"text":"Não volteis atrás em vossos pensamentos; e quando fordes dignos, em meu próprio e devido tempo, vereis e sabereis aquilo que vos foi conferido pelas mãos de meu servo Joseph Smith Júnior. Amém."}]},{"chapter":68,"verses":[{"verse":1,"text":"Meu servo Orson Hyde foi chamado por sua ordenação para proclamar o evangelho eterno, pelo Espírito do Deus vivo, de povo em povo e de terra em terra, nas congregações dos iníquos, em suas sinagogas, arrazoando com eles e expondo-lhes todas as escrituras."},{"verse":2,"text":"E eis que este é um padrão para todos os que foram ordenados a este sacerdócio, cuja missão, como designada, é sair para pregar."},{"verse":3,"text":"E este é o padrão para eles: Que falem como forem movidos pelo Espírito Santo."},{"verse":4,"text":"E tudo que disserem, quando movidos pelo Espírito Santo, será escritura, será a vontade do Senhor, será a mente do Senhor, será a palavra do Senhor, será a voz do Senhor e o poder de Deus para a salvação."},{"verse":5,"text":"Eis que esta é a promessa do Senhor a vós, ó meus servos."},{"verse":6,"text":"Portanto, tende bom ânimo e não temais, porque eu, o Senhor, estou convosco e ficarei ao vosso lado; e testificareis de mim, Jesus Cristo, que eu sou o Filho do Deus vivo, que eu fui, que eu sou e que eu virei."},{"verse":7,"text":"Esta é a palavra do Senhor a ti, meu servo Orson Hyde, e também a meu servo Luke Johnson e a meu servo Lymam Johnson e a meu servo William E. McLellin e a todos os élderes fiéis de minha igreja:"},{"verse":8,"text":"Ide por todo o mundo, pregai o evangelho a toda criatura, agindo pela autoridade que eu vos dei, batizando em nome do Pai e do Filho e do Espírito Santo."},{"verse":9,"text":"E aquele que crer e for batizado será salvo; e quem não crer será condenado."},{"verse":10,"text":"E aquele que crer será abençoado com sinais que se seguem, sim, como está escrito."},{"verse":11,"text":"E a vós será dado conhecer os sinais dos tempos e os sinais da vinda do Filho do Homem;"},{"verse":12,"text":"E a vós será dado o poder de selar para a vida eterna todos aqueles de quem o Pai testemunhar. Amém."},{"verse":13,"text":"E agora, com respeito aos outros assuntos, fora os convênios e mandamentos, são estes:"},{"verse":14,"text":"Daqui em diante, no devido tempo do Senhor, outros bispos serão designados na igreja, para ministrar como o primeiro;"},{"verse":15,"text":"Portanto, eles serão sumos sacerdotes dignos e serão designados pela Primeira Presidência do Sacerdócio de Melquisedeque, exceto quando forem descendentes literais de Aarão."},{"verse":16,"text":"E se forem descendentes literais de Aarão, têm direito legal ao bispado, se forem o primogênito dentre os filhos de Aarão;"},{"verse":17,"text":"Pois o primogênito tem direito à presidência deste sacerdócio e às chaves ou autoridade do mesmo."},{"verse":18,"text":"Nenhum homem tem direito legal a este ofício, ou a possuir as chaves deste sacerdócio, a menos que seja descendente literal e o primogênito de Aarão."},{"verse":19,"text":"Mas como um sumo sacerdote do Sacerdócio de Melquisedeque tem autoridade para oficiar em todos os ofícios menores, ele pode oficiar no ofício de bispo quando não se achar um descendente literal de Aarão, desde que seja chamado, designado e ordenado a este poder, sob as mãos da Primeira Presidência do Sacerdócio de Melquisedeque."},{"verse":20,"text":"E um descendente literal de Aarão também deve ser designado por esta Presidência e ser digno e ungido e ordenado sob as mãos desta Presidência; caso contrário, não são legalmente autorizados para oficiar em seu sacerdócio."},{"verse":21,"text":"Mas em virtude do decreto referente ao direito que eles têm ao sacerdócio, transmitido de pai para filho, poderão reivindicar sua unção, se em qualquer tempo puderem provar sua linhagem ou provarem-na por revelação do Senhor, dada sob as mãos da Presidência acima mencionada."},{"verse":22,"text":"E também nenhum bispo ou sumo sacerdote que for designado para este ministério será julgado ou condenado por qualquer crime, a menos que seja diante da Primeira Presidência da igreja;"},{"verse":23,"text":"E se for considerado culpado diante desta Presidência e por testemunho que não possa ser refutado, ele será condenado;"},{"verse":24,"text":"E caso se arrependa, será perdoado de acordo com os convênios e mandamentos da igreja."},{"verse":25,"text":"E também, se em Sião ou em qualquer de suas estacas organizadas houver pais que, tendo filhos, não os ensinarem a compreender a doutrina do arrependimento, da fé em Cristo, o Filho do Deus vivo, e do batismo e do dom do Espírito Santo pela imposição das mãos, quando tiverem oito anos, sobre a cabeça dos pais seja o pecado."},{"verse":26,"text":"Pois isto será uma lei para os habitantes de Sião ou em qualquer de suas estacas que estejam organizadas."},{"verse":27,"text":"E seus filhos serão batizados para a remissão de seus pecados quando tiverem oito anos de idade; e receberão a imposição das mãos."},{"verse":28,"text":"E também ensinarão seus filhos a orar e a andar em retidão perante o Senhor."},{"verse":29,"text":"E os habitantes de Sião também observarão o dia do Senhor para santificá-lo."},{"verse":30,"text":"E os habitantes de Sião, se forem designados para trabalhar, também se lembrarão de fazer suas tarefas com toda fidelidade, pois o ocioso será lembrado perante o Senhor."},{"verse":31,"text":"Agora eu, o Senhor, não estou satisfeito com os habitantes de Sião, porque há ociosos entre eles; e seus filhos também estão crescendo em iniquidade; também não buscam sinceramente as riquezas da eternidade, mas seus olhos estão cheios de cobiça."},{"verse":32,"text":"Estas coisas não deveriam existir e precisam ser eliminadas de seu meio; portanto, que meu servo Oliver Cowdery leve estas palavras à terra de Sião."},{"verse":33,"text":"E dou-lhes um mandamento: Quem não oferecer suas orações perante o Senhor no momento devido, que seja lembrado perante o juiz de meu povo."},{"verse":34,"text":"Verdadeiras e fiéis são estas palavras; portanto, não as transgredireis nem as diminuireis."},{"verse":35,"text":"Eis que eu sou o Alfa e o Ômega e depressa venho. Amém."}]},{"chapter":69,"verses":[{"verse":1,"text":"Escutai-me, diz o Senhor vosso Deus, para o bem de meu servo Oliver Cowdery. Não é prudente que lhe sejam confiados os mandamentos e o dinheiro que ele levará para a terra de Sião, a não ser que vá com ele alguém que seja verdadeiro e fiel."},{"verse":2,"text":"Portanto, eu, o Senhor, desejo que meu servo John Whitmer vá com meu servo Oliver Cowdery;"},{"verse":3,"text":"E também que continue a escrever, e a registrar a história de todas as coisas importantes que observar e souber referentes à minha igreja;"},{"verse":4,"text":"E também que receba conselhos e auxílio de meu servo Oliver Cowdery e outros."},{"verse":5,"text":"E também meus servos que estão no exterior deverão enviar os relatórios de suas mordomias à terra de Sião;"},{"verse":6,"text":"Pois a terra de Sião será um centro e um lugar para receber e fazer todas estas coisas."},{"verse":7,"text":"Contudo, que meu servo John Whitmer viaje muitas vezes de lugar em lugar, de igreja em igreja, para que, mais facilmente, obtenha conhecimento —"},{"verse":8,"text":"Pregando e expondo, escrevendo, copiando, selecionando e obtendo todas as coisas que serão para o bem da igreja e para as gerações vindouras que crescerão na terra de Sião, para possuí-la de geração em geração, para todo o sempre. Amém."}]},{"chapter":70,"verses":[{"verse":1,"text":"Vede e escutai, ó habitantes de Sião, e todos vós, povo de minha igreja, que estais longe, e ouvi a palavra do Senhor, que dou a meu servo Joseph Smith Júnior; e também a meu servo Martin Harris e também a meu servo Oliver Cowdery e também a meu servo John Whitmer e também a meu servo Sidney Rigdon e também a meu servo William W. Phelps, como mandamento."},{"verse":2,"text":"Porque lhes dou um mandamento; portanto, escutai e ouvi, pois assim lhes diz o Senhor:"},{"verse":3,"text":"Eu, o Senhor, indiquei-os e ordenei-os para serem os mordomos responsáveis pelas revelações e mandamentos que lhes dei e que lhes darei mais adiante;"},{"verse":4,"text":"E um relatório dessa mordomia deles exigirei no dia do juízo."},{"verse":5,"text":"Portanto, designei-os, e este é o seu ofício na igreja de Deus, para administrar essas coisas e o que a elas se refere, sim, os seus ganhos."},{"verse":6,"text":"Portanto, dou-lhes o mandamento de não transmitirem estas coisas à igreja nem ao mundo;"},{"verse":7,"text":"Contudo, se receberem mais que o necessário para suas necessidades e carências, entregarão ao meu armazém;"},{"verse":8,"text":"E os ganhos serão consagrados aos habitantes de Sião e às suas gerações, caso se tornem herdeiros de acordo com as leis do reino."},{"verse":9,"text":"Eis que isto é o que o Senhor requer de todo homem em sua mordomia, segundo o que eu, o Senhor, designei ou designarei no futuro a qualquer homem."},{"verse":10,"text":"E eis que ninguém que pertence à igreja do Deus vivo está isento desta lei;"},{"verse":11,"text":"Sim, nem o bispo nem o agente que guarda o armazém do Senhor nem aquele a quem for designada uma mordomia de coisas materiais."},{"verse":12,"text":"Aquele que for designado para administrar as coisas espirituais é digno de seu salário, assim como o são aqueles a quem forem dadas mordomias para administrar as coisas materiais;"},{"verse":13,"text":"Sim, mais profusamente, profusão essa que lhes é multiplicada por meio das manifestações do Espírito."},{"verse":14,"text":"Contudo, nas coisas materiais sereis iguais e disto não reclamareis; caso contrário, será retida a profusão das manifestações do Espírito."},{"verse":15,"text":"Agora, dou este mandamento a meus servos para seu benefício enquanto permanecerem, como manifestação de minhas bênçãos sobre sua cabeça e como recompensa por sua diligência e para sua segurança;"},{"verse":16,"text":"Para alimento e para vestimenta; para herança; para moradias e para terras, em quaisquer circunstâncias em que eu, o Senhor, os colocar, e aonde quer que eu, o Senhor, os enviar."},{"verse":17,"text":"Pois eles foram fiéis sobre muitas coisas e agiram bem, uma vez que não pecaram."},{"verse":18,"text":"Eis que eu, o Senhor, sou misericordioso e abençoá-los-ei; e eles entrarão no gozo destas coisas. Assim seja. Amém."}]},{"chapter":71,"verses":[{"verse":1,"text":"Eis que assim vos diz o Senhor, meus servos Joseph Smith Júnior e Sidney Rigdon, que em verdade é chegada a hora em que me é necessário e conveniente que abrais a boca para proclamar meu evangelho e as coisas do reino, expondo seus mistérios pelas escrituras, conforme a porção do Espírito e do poder que vos será dada, sim, segundo a minha vontade."},{"verse":2,"text":"Em verdade vos digo: Pregai por algum tempo ao mundo, nas regiões circunvizinhas e também na igreja, até que vos seja indicado."},{"verse":3,"text":"Em verdade esta é uma missão temporária que vos dou."},{"verse":4,"text":"Portanto, trabalhai na minha vinha. Chamai os habitantes da Terra e testificai e preparai o caminho para os mandamentos e revelações que hão de vir."},{"verse":5,"text":"Ora, eis que isto é sabedoria; aquele que ler, que compreenda e também receba;"},{"verse":6,"text":"Pois ao que recebe será dado mais abundantemente, sim, poder."},{"verse":7,"text":"Portanto, confundi vossos inimigos; convidai-os para debater convosco, tanto em público como em particular; e, se fordes fiéis, a vergonha deles será manifestada."},{"verse":8,"text":"Portanto, que exponham eles seus fortes argumentos contra o Senhor."},{"verse":9,"text":"Em verdade, assim vos diz o Senhor: Arma alguma que se forme contra vós prosperará;"},{"verse":10,"text":"E se contra vós algum homem erguer a voz, em meu próprio e devido tempo será confundido."},{"verse":11,"text":"Portanto, guardai os meus mandamentos; eles são verdadeiros e fiéis. Assim seja. Amém."}]},{"chapter":72,"verses":[{"verse":1,"text":"Escutai e dai ouvidos à voz do Senhor, ó vós que vos reunistes, que sois os sumos sacerdotes de minha igreja, a quem foram dados o reino e o poder."},{"verse":2,"text":"Pois em verdade assim diz o Senhor: É-me conveniente que se designe, para vós ou dentre vós, um bispo para a igreja desta parte da vinha do Senhor."},{"verse":3,"text":"E em verdade nisto procedestes sabiamente, pois o Senhor requer que todo mordomo preste contas de sua mordomia, tanto nesta vida como na eternidade."},{"verse":4,"text":"Pois o que nesta vida for fiel e prudente será considerado digno de herdar as mansões preparadas para ele por meu Pai."},{"verse":5,"text":"Em verdade vos digo: Os élderes de minha igreja nesta parte de minha vinha prestarão contas de sua mordomia ao bispo que por mim será designado nesta parte de minha vinha."},{"verse":6,"text":"Registrar-se-ão estas coisas para serem entregues ao bispo de Sião."},{"verse":7,"text":"E conhecer-se-á o dever do bispo pelos mandamentos que foram dados e pela voz da conferência."},{"verse":8,"text":"E agora, em verdade vos digo: Meu servo Newel K. Whitney é o homem que será designado e ordenado para esse poder. Esta é a vontade do Senhor vosso Deus, vosso Redentor. Assim seja. Amém."},{"verse":9,"text":"A palavra do Senhor, como acréscimo à lei dada, revelando o dever do bispo que foi ordenado para a igreja nesta parte da vinha, que em verdade é esta —"},{"verse":10,"text":"Manter o armazém do Senhor; receber os fundos da igreja nesta parte da vinha;"},{"verse":11,"text":"Receber o relatório dos élderes como antes foi mandado, e prover às suas necessidades; eles pagarão o que receberem, se tiverem com o que pagar;"},{"verse":12,"text":"Para que isto também seja consagrado para o bem da igreja, para os pobres e necessitados."},{"verse":13,"text":"E aquele que não puder pagar apresentará uma conta ao bispo de Sião, que pagará a dívida com aquilo que o Senhor lhe puser nas mãos."},{"verse":14,"text":"E as obras dos fiéis que trabalham em coisas espirituais, na administração do evangelho e das coisas do reino na igreja e no mundo, responderão pela dívida junto ao bispo de Sião;"},{"verse":15,"text":"Assim o pagamento sairá da igreja, pois, de acordo com a lei, o homem que vem para Sião deve depositar todas as coisas junto ao bispo de Sião."},{"verse":16,"text":"E agora, em verdade vos digo que, como todo élder desta parte da vinha deve dar contas de sua mordomia ao bispo desta parte da vinha —"},{"verse":17,"text":"Um certificado do juiz ou bispo desta parte da vinha ao bispo de Sião torna aceitável todo homem e satisfaz todas as coisas, para que ele receba uma herança e para que seja recebido como mordomo prudente e como trabalhador fiel;"},{"verse":18,"text":"Caso contrário, não será aceito pelo bispo de Sião."},{"verse":19,"text":"E agora, em verdade vos digo que todo élder que prestar contas ao bispo da igreja nesta parte da vinha seja recomendado pela igreja ou igrejas em que trabalhar, para que ele e seus relatórios sejam aprovados em todas as coisas."},{"verse":20,"text":"E também que meus servos designados como mordomos dos assuntos literários de minha igreja tenham o direito de, em todas as coisas, pedir a assistência do bispo ou bispos —"},{"verse":21,"text":"Para que as revelações sejam publicadas e cheguem aos confins da Terra; para que também obtenham fundos que beneficiem a igreja em todas as coisas;"},{"verse":22,"text":"Para que também sejam aprovados em todas as coisas e sejam considerados mordomos prudentes."},{"verse":23,"text":"E agora, eis que isto será um exemplo para todos os ramos da minha igreja, em qualquer terra que forem estabelecidos. E agora termino minhas palavras. Amém."},{"verse":24,"text":"Algumas palavras acrescentadas às leis do reino, concernentes aos membros da igreja — os que forem designados pelo Santo Espírito para subirem a Sião e os que tiverem o privilégio de subir a Sião:"},{"verse":25,"text":"Que levem ao bispo um certificado de três élderes da igreja ou um certificado do bispo;"},{"verse":26,"text":"Caso contrário, o que subir à terra de Sião não será considerado mordomo prudente. Isto também é um exemplo. Amém."}]},{"chapter":73,"verses":[{"verse":1,"text":"Pois em verdade assim diz o Senhor: É-me conveniente que eles continuem pregando o evangelho e exortando as igrejas das regiões circunvizinhas até a conferência;"},{"verse":2,"text":"E então, eis que lhes serão indicadas pela voz da conferência suas diversas missões."},{"verse":3,"text":"Ora, diz o Senhor: Em verdade vos digo, meus servos Joseph Smith Júnior e Sidney Rigdon, que é preciso traduzir outra vez;"},{"verse":4,"text":"E, se for prático, pregar nas regiões circunvizinhas até a conferência; e, depois disso, é preciso continuar o trabalho da tradução até que esteja terminado."},{"verse":5,"text":"E que isto sirva de modelo para os élderes, até que se receba mais conhecimento, como está escrito."},{"verse":6,"text":"Agora não vos dou mais nesta ocasião. Cingi vossos lombos e sede sóbrios. Assim seja. Amém."}]},{"chapter":74,"verses":[{"verse":1,"text":"Pois o marido descrente é santificado pela mulher, e a mulher descrente é santificada pelo marido; de outra sorte, os seus filhos seriam imundos; mas agora são santos."},{"verse":2,"text":"Ora, nos dias dos apóstolos, observava-se a lei da circuncisão entre todos os judeus que não acreditavam no evangelho de Jesus Cristo."},{"verse":3,"text":"E aconteceu que surgiu uma grande contenda entre o povo, concernente à lei da circuncisão, porque o marido descrente se achava desejoso de que seus filhos fossem circuncidados e se tornassem sujeitos à lei de Moisés, lei essa que fora cumprida."},{"verse":4,"text":"E aconteceu que os filhos, tendo sido criados na sujeição à lei de Moisés, deram ouvidos às tradições de seus pais e não acreditaram no evangelho de Cristo; e nisso tornaram-se impuros."},{"verse":5,"text":"Portanto, por esta razão, o apóstolo escreveu à igreja, dando-lhes um mandamento, não do Senhor, mas de si mesmo, de que um crente não devia unir-se a um descrente; a não ser que se abolisse entre eles a lei de Moisés,"},{"verse":6,"text":"Para que seus filhos não fossem circuncidados; e que se abolisse a tradição que dizia serem as criancinhas imundas; pois assim era entre os judeus;"},{"verse":7,"text":"Mas as criancinhas são santas, sendo santificadas por meio da expiação de Jesus Cristo; e é isto que as escrituras significam."}]},{"chapter":75,"verses":[{"verse":1,"text":"Em verdade, em verdade vos digo, eu que falo pela voz de meu Espírito, sim, o Alfa e o Ômega, vosso Senhor e vosso Deus:"},{"verse":2,"text":"Escutai, ó vós que destes vossos nomes para sair proclamando meu evangelho e para podar a minha vinha."},{"verse":3,"text":"Eis que eu vos digo ser a minha vontade irdes sem demora e não serdes ociosos, mas trabalhardes com toda a força —"},{"verse":4,"text":"Levantando vossas vozes como que com o som de uma trombeta, proclamando a verdade conforme as revelações e mandamentos que vos dei."},{"verse":5,"text":"E assim, se fordes fiéis, sereis carregados com muitos molhos e coroados com honra e glória e imortalidade e vida eterna."},{"verse":6,"text":"Portanto, em verdade eu digo a meu servo William E. McLellin que revogo o encargo que lhe dei de ir às regiões do leste;"},{"verse":7,"text":"E dou-lhe um novo encargo e um novo mandamento, no qual eu, o Senhor, o castigo pelas murmurações de seu coração;"},{"verse":8,"text":"E ele pecou; contudo, eu o perdoo e digo-lhe também: Vai às regiões do sul."},{"verse":9,"text":"E que meu servo Luke Johnson vá com ele e proclamem as coisas que lhes ordenei —"},{"verse":10,"text":"Invocando o nome do Senhor pelo Consolador, que lhes ensinará todas as coisas que lhes forem convenientes —"},{"verse":11,"text":"Orando sempre para não desfalecerem; e se assim fizerem, estarei com eles até o fim."},{"verse":12,"text":"Eis que esta é a vontade do Senhor vosso Deus concernente a vós. Assim seja. Amém."},{"verse":13,"text":"E também, em verdade assim diz o Senhor: Que meu servo Orson Hyde e meu servo Samuel H. Smith viajem para as regiões do leste e proclamem as coisas que lhes ordenei; e se forem fiéis, eis que estarei com eles até o fim."},{"verse":14,"text":"E também, em verdade eu digo a meu servo Lyman Johnson e a meu servo Orson Pratt que deverão viajar para as regiões do leste; e eis que também estarei com eles até o fim."},{"verse":15,"text":"E também digo a meu servo Asa Dodds e a meu servo Calves Wilson, que deverão viajar para as regiões do oeste e proclamar meu evangelho, como lhes ordenei."},{"verse":16,"text":"E aquele que for fiel vencerá todas as coisas e será elevado no último dia."},{"verse":17,"text":"E também, digo a meu servo Major N. Ashley e a meu servo Burr Riggs que também viajem para as regiões do sul."},{"verse":18,"text":"Sim, que todos esses viajem, como lhes ordenei, indo de casa em casa, de povoado em povoado e de cidade em cidade."},{"verse":19,"text":"E em qualquer casa que entrardes e fordes recebidos, deixai nessa casa vossa bênção."},{"verse":20,"text":"E de qualquer casa em que entrardes e não fordes recebidos, saireis rapidamente e sacudireis o pó de vossos pés, como testemunho contra eles."},{"verse":21,"text":"E encher-vos-eis de regozijo e de alegria; e sabei que no dia do julgamento sereis juízes daquela casa e condená-la-eis;"},{"verse":22,"text":"E será mais tolerável para o pagão, no dia do juízo, do que para aquela casa; portanto, cingi os vossos lombos e sede fiéis; e vencereis todas as coisas, e sereis elevados no último dia. Assim seja. Amém."},{"verse":23,"text":"E também assim vos diz o Senhor, ó élderes da minha igreja, que destes vossos nomes a fim de conhecerdes a sua vontade concernente a vós —"},{"verse":24,"text":"Eis que vos digo que é dever da igreja ajudar a sustentar, e também sustentar, as famílias dos que são chamados e precisam ser enviados pelo mundo para proclamar o evangelho ao mundo."},{"verse":25,"text":"Portanto, eu, o Senhor, vos dou este mandamento: Obtende lugar para vossa família, visto que os vossos irmãos estão dispostos a abrir o coração."},{"verse":26,"text":"E todos os que puderem obter lugares para sua família e auxílio da igreja para ela, que não deixem de ir pelo mundo, seja para o leste ou para o oeste, para o norte ou para o sul."},{"verse":27,"text":"Que peçam, e receberão; batam, e ser-lhes-á aberto; e ser-lhes-á dado a conhecer do alto, pelo Consolador, aonde deverão ir."},{"verse":28,"text":"E também, em verdade vos digo que todo homem que for obrigado a manter sua própria família, que a mantenha; e de modo algum perderá sua coroa; e que trabalhe na igreja."},{"verse":29,"text":"Que todo homem seja diligente em todas as coisas. E o ocioso não terá lugar na igreja, a não ser que se arrependa e melhore o seu proceder."},{"verse":30,"text":"Portanto, que meu servo Simeon Carter e meu servo Emer Harris sejam unidos no ministério;"},{"verse":31,"text":"E também meu servo Ezra Thayre e meu servo Thomas B. Marsh;"},{"verse":32,"text":"Também meu servo Hyrum Smith e meu servo Reynolds Cahoon;"},{"verse":33,"text":"E também meu servo Daniel Stanton e meu servo Seymour Brunson;"},{"verse":34,"text":"E também meu servo Sylvester Smith e meu servo Gideon Carter;"},{"verse":35,"text":"E também meu servo Ruggles Eames e meu servo Stephen Burnett;"},{"verse":36,"text":"E também meu servo Micah B. Welton e também meu servo Eden Smith. Assim seja. Amém."}]},{"chapter":76,"verses":[{"verse":1,"text":"Ouvi, ó céus, e dai ouvidos, ó Terra, e regozijai-vos, vós, seus habitantes, pois o Senhor é Deus e além dele não há Salvador algum."},{"verse":2,"text":"Grande é sua sabedoria, maravilhosos são seus caminhos e a extensão de suas obras ninguém pode descobrir."},{"verse":3,"text":"Seus propósitos não falham, nem há quem seja capaz de reter a sua mão."},{"verse":4,"text":"De eternidade em eternidade ele é o mesmo e seus anos nunca se acabam."},{"verse":5,"text":"Pois assim diz o Senhor: Eu, o Senhor, sou misericordioso e benigno para com aqueles que me temem e deleito-me em honrar aqueles que me servem em retidão e em verdade até o fim."},{"verse":6,"text":"Grande será sua recompensa e eterna sua glória."},{"verse":7,"text":"E a eles revelarei todos os mistérios, sim, todos os mistérios ocultos de meu reino desde a antiguidade; e por eras futuras, dar-lhes-ei a conhecer a boa disposição da minha vontade concernente a todas as coisas relativas ao meu reino."},{"verse":8,"text":"Sim, até as maravilhas da eternidade conhecerão e coisas futuras mostrar-lhes-ei, sim, coisas de muitas gerações."},{"verse":9,"text":"E sua sabedoria será grande e seu entendimento alcançará os céus; e diante deles a sabedoria dos sábios perecerá e o entendimento dos prudentes se desvanecerá."},{"verse":10,"text":"Porque pelo meu Espírito os iluminarei, e pelo meu poder dar-lhes-ei a conhecer os segredos da minha vontade — sim, até as coisas que o olho não viu, nem o ouvido ouviu, e ainda não entraram no coração do homem."},{"verse":11,"text":"Nós, Joseph Smith Júnior e Sidney Rigdon, estando no Espírito, no décimo sexto dia de fevereiro do ano de mil oitocentos e trinta e dois de nosso Senhor —"},{"verse":12,"text":"Pelo poder do Espírito abriram-se nossos olhos e iluminou-se nosso entendimento, de modo a vermos e compreendermos as coisas de Deus —"},{"verse":13,"text":"Até as coisas que existiram desde o princípio, antes de o mundo existir, as quais foram ordenadas pelo Pai, por meio de seu Filho Unigênito, que estava no seio do Pai desde o princípio;"},{"verse":14,"text":"De quem testemunhamos; e o testemunho que prestamos é a plenitude do evangelho de Jesus Cristo, que é o Filho, o qual vimos e com quem conversamos na visão celestial."},{"verse":15,"text":"Pois enquanto trabalhávamos na tradução que o Senhor nos designara, chegamos ao vigésimo nono versículo do quinto capítulo de João, que nos foi dado como segue:"},{"verse":16,"text":"Falando da ressurreição dos mortos, com referência aos que ouvirão a voz do Filho do Homem:"},{"verse":17,"text":"E ressurgirão; os que fizeram o bem, na ressurreição dos justos, e os que fizeram o mal, na ressurreição dos injustos."},{"verse":18,"text":"Ora, isso nos maravilhou, pois foi-nos dado pelo Espírito."},{"verse":19,"text":"E enquanto meditávamos sobre essas coisas, o Senhor tocou os olhos do nosso entendimento e eles se abriram; e a glória do Senhor cercou-nos de resplendor."},{"verse":20,"text":"E contemplamos a glória do Filho, à direita do Pai, e recebemos de sua plenitude;"},{"verse":21,"text":"E vimos os santos anjos e os que são santificados diante de seu trono, adorando a Deus e ao Cordeiro, a quem adoram para todo o sempre."},{"verse":22,"text":"E agora, depois dos muitos testemunhos que se prestaram dele, este é o testemunho, último de todos, que nós damos dele: Que ele vive!"},{"verse":23,"text":"Porque o vimos, sim, à direita de Deus; e ouvimos a voz testificando que ele é o Unigênito do Pai —"},{"verse":24,"text":"Que por ele e por meio dele e dele os mundos são e foram criados; e seus habitantes são filhos e filhas gerados para Deus."},{"verse":25,"text":"E isto também vimos e testificamos: Que um anjo de Deus, que possuía autoridade na presença de Deus, que se rebelou contra o Filho Unigênito, a quem o Pai amava e que estava no seio do Pai, foi expulso da presença de Deus e do Filho,"},{"verse":26,"text":"E foi chamado Perdição, porque os céus prantearam por ele — ele era Lúcifer, um filho da manhã."},{"verse":27,"text":"E olhamos, e eis que ele caiu! Caiu, ele, um filho da manhã!"},{"verse":28,"text":"E enquanto ainda estávamos no Espírito, o Senhor ordenou-nos que escrevêssemos a visão; pois vimos Satanás, aquela antiga serpente, sim, o diabo, que se rebelou contra Deus e procurou tomar o reino de nosso Deus e seu Cristo —"},{"verse":29,"text":"Portanto, ele faz guerra contra os santos de Deus e cerca-os."},{"verse":30,"text":"E tivemos uma visão dos sofrimentos daqueles a quem fez guerra e subjugou, pois assim nos veio a voz do Senhor:"},{"verse":31,"text":"Assim diz o Senhor concernente a todos os que conhecem o meu poder e dele foram feitos participantes; e que se deixaram vencer pelo poder do diabo e negaram a verdade e desafiaram o meu poder —"},{"verse":32,"text":"Estes são os filhos de perdição, de quem eu digo que melhor lhes fora nunca terem nascido;"},{"verse":33,"text":"Pois são vasos de ira, condenados a sofrer a ira de Deus com o diabo e seus anjos na eternidade;"},{"verse":34,"text":"Sobre os quais eu disse que não há perdão neste mundo nem no mundo vindouro —"},{"verse":35,"text":"Tendo negado o Santo Espírito, depois de havê-lo recebido, e tendo negado o Filho Unigênito do Pai; tendo-o crucificado dentro de si e tendo-o envergonhado abertamente."},{"verse":36,"text":"Estes são os que irão para o lago de fogo e enxofre com o diabo e seus anjos —"},{"verse":37,"text":"E os únicos sobre quem a segunda morte terá qualquer poder;"},{"verse":38,"text":"Sim, em verdade, os únicos que não serão redimidos no devido tempo do Senhor depois de terem sofrido a sua ira."},{"verse":39,"text":"Pois todos os demais ressurgirão na ressurreição dos mortos, pelo triunfo e pela glória do Cordeiro que foi morto e que estava no seio do Pai antes que os mundos fossem feitos."},{"verse":40,"text":"E este é o evangelho, as alegres novas, que a voz do céu nos testificou —"},{"verse":41,"text":"Que ele veio ao mundo, sim, Jesus, para ser crucificado pelo mundo e para tomar sobre si os pecados do mundo e para santificar o mundo e purificá-lo de toda iniquidade;"},{"verse":42,"text":"Para que, por intermédio dele, fossem salvos todos os que o Pai havia posto em seu poder e feito por meio dele;"},{"verse":43,"text":"Ele que glorifica o Pai e salva todas as obras de suas mãos, exceto os filhos de perdição, que negam o Filho depois que o Pai o revelou."},{"verse":44,"text":"Portanto, ele salva todos exceto esses, os quais irão para o castigo infinito, que é castigo sem fim, que é castigo eterno, para reinar com o diabo e seus anjos na eternidade, onde seu bicho não morre e o fogo é inextinguível, o que é seu tormento —"},{"verse":45,"text":"E homem algum conhece o seu fim nem seu lugar nem seu tormento;"},{"verse":46,"text":"Nem foi revelado nem é nem será revelado ao homem, exceto àqueles que dele forem feitos participantes;"},{"verse":47,"text":"Contudo, eu, o Senhor, mostro-o em visão a muitos, mas imediatamente torno a encerrá-la;"},{"verse":48,"text":"Portanto, seu fim, sua largura, altura, profundidade e miséria eles não compreendem, nem homem algum, a não ser os que são ordenados a essa condenação."},{"verse":49,"text":"E ouvimos a voz, que dizia: Escrevei a visão, pois eis que este é o fim da visão dos sofrimentos dos ímpios."},{"verse":50,"text":"E tornamos a testificar — pois vimos e ouvimos; e este é o testemunho do evangelho de Cristo concernente àqueles que irão ressurgir na ressurreição dos justos —"},{"verse":51,"text":"Esses são os que receberam o testemunho de Jesus e creram em seu nome e foram batizados na semelhança de seu sepultamento, sendo sepultados na água em seu nome; e isto de acordo com o mandamento que ele deu —"},{"verse":52,"text":"Para que, guardando os mandamentos, fossem lavados e purificados de todos os seus pecados e recebessem o Santo Espírito pela imposição das mãos daquele que é ordenado e selado para esse poder;"},{"verse":53,"text":"E que vencem pela fé e são selados pelo Santo Espírito da promessa que o Pai derrama sobre todos os que são justos e fiéis."},{"verse":54,"text":"Estes são os que são a igreja do Primogênito."},{"verse":55,"text":"Estes são aqueles em cujas mãos o Pai colocou todas as coisas —"},{"verse":56,"text":"Estes são os que são os sacerdotes e reis, que receberam de sua plenitude e de sua glória;"},{"verse":57,"text":"E são sacerdotes do Altíssimo, segundo a ordem de Melquisedeque, que era segundo a ordem de Enoque, que era segundo a ordem do Filho Unigênito."},{"verse":58,"text":"Portanto, como está escrito, eles são deuses, sim, os filhos de Deus —"},{"verse":59,"text":"Portanto, todas as coisas são suas, seja a vida ou a morte, as coisas presentes ou as coisas futuras, todas são deles e eles são de Cristo e Cristo é de Deus."},{"verse":60,"text":"E eles vencerão todas as coisas."},{"verse":61,"text":"Portanto, que nenhum homem se glorie no homem, mas, antes, que se glorie em Deus, que subjugará todos os inimigos sob seus pés."},{"verse":62,"text":"Estes habitarão na presença de Deus e seu Cristo para todo o sempre."},{"verse":63,"text":"Estes são os que ele trará consigo, quando vier nas nuvens do céu para reinar na Terra sobre seu povo."},{"verse":64,"text":"Estes são os que terão parte na primeira ressurreição."},{"verse":65,"text":"Estes são os que surgirão na ressurreição dos justos."},{"verse":66,"text":"Estes são os que vieram ao Monte Sião e à cidade do Deus vivo, o lugar celestial, o mais santo de todos."},{"verse":67,"text":"Estes são os que vieram para uma inumerável hoste de anjos, para a assembleia geral e igreja de Enoque e do Primogênito."},{"verse":68,"text":"Estes são aqueles cujos nomes estão escritos no céu, onde Deus e Cristo são o juiz de todos."},{"verse":69,"text":"Estes são os que são homens justos, aperfeiçoados por meio de Jesus, o mediador do novo convênio, que efetuou esta expiação perfeita pelo derramamento de seu próprio sangue."},{"verse":70,"text":"Estes são aqueles cujo corpo é celestial, cuja glória é a do sol, sim, a glória de Deus, a mais elevada de todas, sendo que o sol do firmamento é citado como o símbolo dessa glória."},{"verse":71,"text":"E também vimos o mundo terrestre e eis que estes são os que pertencem ao terrestre, cuja glória difere da glória da igreja do Primogênito, que recebeu a plenitude do Pai, assim como a glória da lua difere da do sol no firmamento."},{"verse":72,"text":"Eis que estes são os que morreram sem lei;"},{"verse":73,"text":"E também aqueles que são os espíritos de homens mantidos na prisão, a quem o Filho visitou e pregou o evangelho para que fossem julgados segundo os homens na carne;"},{"verse":74,"text":"Os que não receberam o testemunho de Jesus na carne, mas receberam-no depois."},{"verse":75,"text":"Estes são os homens honrados da Terra, que foram cegados pela astúcia dos homens."},{"verse":76,"text":"Estes são os que recebem de sua glória, mas não de sua plenitude."},{"verse":77,"text":"Estes são os que recebem a presença do Filho, mas não da plenitude do Pai."},{"verse":78,"text":"Portanto, são corpos terrestres e não corpos celestiais; e diferem em glória, como a lua difere do sol."},{"verse":79,"text":"Estes são os que não são valentes no testemunho de Jesus; portanto, não obtêm a coroa no reino de nosso Deus."},{"verse":80,"text":"E agora, este é o fim da visão que tivemos do terrestre, que o Senhor nos mandou escrever enquanto ainda estávamos no Espírito."},{"verse":81,"text":"E também vimos a glória do telestial, cuja glória é a do menor, assim como a glória das estrelas difere da glória da lua no firmamento."},{"verse":82,"text":"Estes são os que não receberam o evangelho de Cristo nem o testemunho de Jesus."},{"verse":83,"text":"Estes são os que não negam o Santo Espírito."},{"verse":84,"text":"Estes são os que são lançados no inferno."},{"verse":85,"text":"Estes são os que não serão redimidos do diabo até a última ressurreição, até que o Senhor, sim, Cristo, o Cordeiro, tenha consumado sua obra."},{"verse":86,"text":"Estes são os que não recebem de sua plenitude no mundo eterno, mas do Santo Espírito pelo ministério do terrestre;"},{"verse":87,"text":"E o terrestre, pelo ministério do celestial."},{"verse":88,"text":"E também o telestial o recebe pela administração de anjos que são designados para ministrar em seu favor, ou seja, que lhes são designados como espíritos ministradores, pois eles serão herdeiros da salvação."},{"verse":89,"text":"E assim vimos, na visão celestial, a glória do telestial, que ultrapassa todo entendimento;"},{"verse":90,"text":"E nenhum homem a conhece, a não ser aquele a quem Deus a revelou."},{"verse":91,"text":"E assim vimos a glória do terrestre, que em todas as coisas supera a glória do telestial, sim, em glória e em poder e em força e em domínio."},{"verse":92,"text":"E assim vimos a glória do celestial, que supera em todas as coisas — onde Deus, sim, o Pai, reina sobre o seu trono para todo o sempre;"},{"verse":93,"text":"Diante de cujo trono todas as coisas curvam-se em humilde reverência e dão-lhe glória para todo o sempre."},{"verse":94,"text":"Aqueles que habitam em sua presença são a igreja do Primogênito; e eles veem como são vistos e conhecem como são conhecidos, tendo recebido de sua plenitude e de sua graça;"},{"verse":95,"text":"E ele os faz iguais em poder e em força e em domínio."},{"verse":96,"text":"E a glória do celestial é uma, como a glória do sol é uma."},{"verse":97,"text":"E a glória do terrestre é uma, como a glória da lua é uma."},{"verse":98,"text":"E a glória do telestial é uma, como a glória das estrelas é uma; pois como uma estrela difere de outra em glória, assim também diferem em glória uns dos outros no mundo telestial."},{"verse":99,"text":"Pois estes são os que são de Paulo e de Apolo e de Cefas."},{"verse":100,"text":"Estes são os que dizem que são alguns de um e alguns de outro — alguns de Cristo e alguns de João e alguns de Moisés e alguns de Elias e alguns de Esaías e alguns de Isaías e alguns de Enoque;"},{"verse":101,"text":"Mas não receberam o evangelho nem o testemunho de Jesus nem os profetas nem o convênio eterno."},{"verse":102,"text":"Por fim, todos estes são os que não serão reunidos com os santos para serem arrebatados para a igreja do Primogênito e recebidos na nuvem."},{"verse":103,"text":"Estes são os que são mentirosos e feiticeiros e adúlteros e libertinos; e todo aquele que ama e inventa mentiras."},{"verse":104,"text":"Estes são os que sofrem a ira de Deus na Terra."},{"verse":105,"text":"Estes são os que sofrem a vingança do fogo eterno."},{"verse":106,"text":"Estes são os que são lançados no inferno e sofrem a ira de Deus Todo-Poderoso, até a plenitude dos tempos, quando Cristo tiver subjugado todos os inimigos sob seus pés e tiver aperfeiçoado sua obra;"},{"verse":107,"text":"Quando ele entregar o reino e apresentá-lo ao Pai, imaculado, dizendo: Eu venci e pisei sozinho o lagar, sim, o lagar do furor da ira do Deus Todo-Poderoso."},{"verse":108,"text":"Então será ele coroado com a coroa de sua glória, para assentar-se no trono de seu poder a fim de reinar para todo o sempre."},{"verse":109,"text":"Mas eis que vimos a glória e os habitantes do mundo telestial, que eram inumeráveis como as estrelas do firmamento do céu ou como a areia da praia;"},{"verse":110,"text":"E ouvimos a voz do Senhor, dizendo: Todos estes dobrarão os joelhos e toda língua confessará àquele que se assenta no trono para todo o sempre;"},{"verse":111,"text":"Pois eles serão julgados de acordo com suas obras; e cada homem receberá, de acordo com suas próprias obras, seu próprio domínio nas mansões que estão preparadas;"},{"verse":112,"text":"E serão servos do Altíssimo; mas onde Deus e Cristo habitam não poderão vir para todo o sempre."},{"verse":113,"text":"Este é o fim da visão que tivemos e que se nos ordenou que escrevêssemos enquanto ainda estávamos no Espírito."},{"verse":114,"text":"Mas grandes e maravilhosas são as obras do Senhor e os mistérios de seu reino que ele nos mostrou, que ultrapassam todo o entendimento em glória e em força e em domínio;"},{"verse":115,"text":"Os quais ele nos mandou que não escrevêssemos enquanto ainda estávamos no Espírito; e não é lícito ao homem falar deles;"},{"verse":116,"text":"Nem é o homem capaz de torná-los conhecidos, porque são apenas para ser vistos e compreendidos pelo poder do Santo Espírito, que Deus confere àqueles que o amam e se purificam perante ele;"},{"verse":117,"text":"A quem ele concede este privilégio de ver e saber por si mesmos;"},{"verse":118,"text":"Para que, por meio do poder e da manifestação do Espírito, enquanto na carne, sejam capazes de suportar a sua presença no mundo de glória."},{"verse":119,"text":"E a Deus e ao Cordeiro sejam glória e honra e domínio para todo o sempre. Amém."}]},{"chapter":77,"verses":[{"verse":1,"text":"Pergunta. O que é o mar de vidro de que fala João no Apocalipse, capítulo 4, versículo 6?Resposta. É a Terra em seu estado santificado, imortal e eterno."},{"verse":2,"text":"P. O que devemos entender pelos quatro animais mencionados no mesmo versículo?R. São expressões figurativas empregadas por João, o Revelador, para descrever o céu, o paraíso de Deus, a felicidade do homem e dos animais e dos répteis e das aves do ar; o que é espiritual sendo à semelhança daquilo que é material; e aquilo que é material, à semelhança do que é espiritual; o espírito do homem à semelhança de sua pessoa, como também o espírito do animal e de todas as outras criaturas que Deus criou."},{"verse":3,"text":"P. Os quatro animais limitam-se aos próprios animais ou representam classes ou ordens?R. Limitam-se a quatro animais, individualmente, os quais foram mostrados a João para representar a glória das classes dos seres na ordem ou esfera de criação que lhes foi destinada, no gozo de sua felicidade eterna."},{"verse":4,"text":"P. O que devemos entender pelos olhos e asas dos animais?R. Seus olhos representam luz e conhecimento, isto é, eles são cheios de conhecimento; e suas asas representam poder para mover-se, para agir, etc."},{"verse":5,"text":"P. O que devemos entender pelos vinte e quatro anciãos de que fala João?R. Devemos entender que esses anciãos vistos por João eram anciãos que haviam sido fiéis no trabalho do ministério e haviam morrido; que pertenciam às sete igrejas e estavam então no paraíso de Deus."},{"verse":6,"text":"P. O que devemos entender pelo livro visto por João, que estava selado por fora com sete selos?R. Devemos entender que ele contém a vontade, os mistérios e as obras de Deus revelados; as coisas ocultas de sua administração, concernentes a esta Terra durante os sete mil anos de sua duração, ou seja, de sua existência física."},{"verse":7,"text":"P. O que devemos entender pelos sete selos com que o livro estava selado?R. Devemos entender que o primeiro selo contém as coisas dos primeiros mil anos, assim como o segundo as coisas dos mil anos seguintes e assim por diante, até o sétimo."},{"verse":8,"text":"P. O que devemos entender pelos quatro anjos de que fala o capítulo sete, versículo um do Apocalipse?R. Devemos entender que eles são quatro anjos enviados da presença de Deus, a quem foi dado poder sobre as quatro partes da Terra para poupar a vida e para destruir; estes são os que têm o evangelho eterno para entregá-lo a toda nação, tribo, língua e povo; tendo poder para cerrar os céus, selar para a vida ou lançar às regiões das trevas."},{"verse":9,"text":"P. O que devemos entender pelo anjo que subia do Oriente, no capítulo 7, versículo 2 do Apocalipse?R. Devemos entender que o anjo que subia do Oriente é aquele a quem é dado o selo do Deus vivo sobre as doze tribos de Israel; portanto, ele clama aos quatro anjos que têm o evangelho eterno, dizendo: Não danifiqueis a Terra nem o mar nem as árvores, até que tenhamos selado os servos do nosso Deus na testa. E, se vós aceitardes, este é Elias, que havia de vir para reunir as tribos de Israel e restaurar todas as coisas."},{"verse":10,"text":"P. Quando se cumprirão as coisas mencionadas neste capítulo?R. Cumprir-se-ão no sexto milênio, ou seja, na abertura do sexto selo."},{"verse":11,"text":"P. O que devemos entender pelo selamento dos cento e quarenta e quatro mil de todas as tribos de Israel — doze mil de cada tribo?R. Devemos entender que os que são selados são sumos sacerdotes, ordenados na santa ordem de Deus para administrar o evangelho eterno; pois eles são os que são ordenados de cada nação, tribo, língua e povo pelos anjos a quem é dado poder sobre as nações da Terra, a fim de trazerem à igreja do Primogênito todos os que desejarem vir."},{"verse":12,"text":"P. O que devemos entender pelo toque das trombetas mencionado no capítulo 8 do Apocalipse?R. Devemos entender que, assim como Deus fez o mundo em seis dias e no sétimo dia terminou sua obra, santificando-o, e também do pó da terra formou o homem, assim também, no princípio do sétimo milênio, o Senhor Deus santificará a Terra e consumará a salvação do homem e julgará todas as coisas e redimirá todas as coisas, exceto aquelas que ele não pôs sob o seu poder, quando terá selado todas as coisas, até o fim de todas as coisas; e o toque das trombetas dos sete anjos é a preparação e a consumação de sua obra, no princípio do sétimo milênio — a preparação do caminho antes do tempo de sua vinda."},{"verse":13,"text":"P. Quando se cumprirão as coisas escritas no capítulo 9 do Apocalipse?R. Cumprir-se-ão depois da abertura do sétimo selo, antes da vinda de Cristo."},{"verse":14,"text":"P. O que devemos entender pelo livrinho que João comeu, como mencionado no capítulo 10 de Apocalipse?R. Devemos entender que era uma missão e uma ordem para ele reunir as tribos de Israel; eis que este é Elias, o qual, como está escrito, deve vir restaurar todas as coisas."},{"verse":15,"text":"P. O que se deve entender pelas duas testemunhas, no capítulo 11 do Apocalipse?R. São dois profetas que serão levantados para a nação judaica nos últimos dias, na época da restauração, para profetizar aos judeus depois que tiverem sido reunidos e tiverem construído a cidade de Jerusalém na terra de seus pais."}]},{"chapter":78,"verses":[{"verse":1,"text":"O Senhor falou a Joseph Smith Júnior dizendo: Escutai-me, diz o Senhor vosso Deus, vós que sois ordenados ao sumo sacerdócio de minha igreja e que vos reunistes;"},{"verse":2,"text":"E dai ouvidos ao conselho daquele que vos ordenou do alto, que falará em vossos ouvidos palavras de sabedoria, para que vos seja dada salvação naquilo que apresentastes perante mim, diz o Senhor Deus."},{"verse":3,"text":"Pois em verdade vos digo: Chegado é o tempo e está perto; e eis que é necessário que haja uma organização de meu povo, para regulamentar e estabelecer os negócios do armazém para os pobres de meu povo, neste lugar e na terra de Sião —"},{"verse":4,"text":"Como estabelecimento e ordem permanente e eterna para minha igreja, a fim de promover a causa que abraçastes, para a salvação do homem e para a glória de vosso Pai que está nos céus;"},{"verse":5,"text":"Para que sejais iguais nos vínculos das coisas celestiais, sim, e também das coisas terrenas, para obtenção de coisas celestiais."},{"verse":6,"text":"Porque se não sois iguais em coisas terrenas, não podeis ser iguais na obtenção de coisas celestiais;"},{"verse":7,"text":"Pois se desejais que eu vos dê um lugar no mundo celestial, é preciso que vos prepareis, fazendo as coisas que eu mandei e que requeri de vós."},{"verse":8,"text":"E agora, em verdade assim diz o Senhor: É conveniente que todas as coisas sejam feitas para minha glória, por vós que estais unidos nesta ordem;"},{"verse":9,"text":"Ou, em outras palavras, que meu servo Newel K. Whitney e meu servo Joseph Smith Júnior e meu servo Sidney Rigdon assentem-se em conselho com os santos que estão em Sião;"},{"verse":10,"text":"Caso contrário, Satanás procura desviar da verdade o coração deles, para que se tornem cegos e não compreendam as coisas que para eles foram preparadas."},{"verse":11,"text":"Portanto, um mandamento vos dou: Preparai-vos e organizai-vos por meio de um contrato ou convênio eterno que não se possa quebrar."},{"verse":12,"text":"E aquele que o quebrar perderá seu cargo e a condição de membro da igreja; e será entregue às bofetadas de Satanás até o dia da redenção."},{"verse":13,"text":"Eis que esta é a preparação com a qual vos preparo e o alicerce e o exemplo que vos dou, por meio dos quais podeis cumprir os mandamentos que vos são dados;"},{"verse":14,"text":"Que pela minha providência, não obstante as tribulações que sobre vós cairão, a igreja permaneça independente, acima de todas as outras criaturas abaixo do mundo celestial;"},{"verse":15,"text":"A fim de que recebais a coroa para vós preparada e vos torneis governantes de muitos reinos, diz o Senhor Deus, o Santo de Sião, que estabeleceu os alicerces de Adão-ondi-Amã;"},{"verse":16,"text":"Que designou Miguel como vosso príncipe e firmou-lhe os pés e colocou-o no alto e deu-lhe as chaves da salvação, sob o conselho e a orientação do Santo, o qual não tem princípio de dias nem fim de vida."},{"verse":17,"text":"Em verdade, em verdade vos digo: Vós sois criancinhas e ainda não compreendestes quão grandiosas são as bênçãos que o Pai tem nas mãos e preparou para vós;"},{"verse":18,"text":"E não podeis suportar tudo agora; contudo, tende bom ânimo, porque eu vos guiarei. Vosso é o reino e são vossas as suas bênçãos e são vossas as riquezas da eternidade."},{"verse":19,"text":"E aquele que receber todas as coisas com gratidão será glorificado; e as coisas desta Terra ser-lhe-ão acrescentadas, mesmo centuplicadas, sim, mais."},{"verse":20,"text":"Portanto, fazei as coisas que vos mandei, diz vosso Redentor, sim, o Filho Amã, que prepara todas as coisas antes de vos arrebatar;"},{"verse":21,"text":"Pois vós sois a igreja do Primogênito; e ele vos arrebatará numa nuvem e determinará a cada homem sua porção."},{"verse":22,"text":"E aquele que for um mordomo prudente e fiel herdará todas as coisas. Amém."}]},{"chapter":79,"verses":[{"verse":1,"text":"Em verdade eu te digo que é a minha vontade que meu servo Jared Carter torne a ir às regiões do leste, de lugar em lugar, e de cidade em cidade, no poder da ordenação com o qual foi ordenado, proclamando boas novas de grande alegria, sim, o evangelho eterno."},{"verse":2,"text":"E enviarei sobre ele o Consolador, que lhe ensinará a verdade e o caminho que deverá seguir;"},{"verse":3,"text":"E se for fiel, tornarei a coroá-lo com molhos."},{"verse":4,"text":"Portanto, alegra teu coração, meu servo Jared Carter, e não temas, diz teu Senhor, sim, Jesus Cristo. Amém."}]},{"chapter":80,"verses":[{"verse":1,"text":"Em verdade, assim diz o Senhor a ti, meu servo Stephen Burnett: Sai, sai pelo mundo e prega o evangelho a toda criatura que esteja ao alcance da tua voz."},{"verse":2,"text":"E já que desejas um companheiro, dar-te-ei meu servo Eden Smith."},{"verse":3,"text":"Portanto, ide e pregai meu evangelho, seja para o norte ou para o sul, para o leste ou para o oeste, não importa, porque não vos podeis enganar."},{"verse":4,"text":"Portanto, declarai as coisas que ouvistes e em que verdadeiramente acreditais e sabeis ser verdadeiras."},{"verse":5,"text":"Eis que esta é a vontade daquele que vos chamou, vosso Redentor, sim, Jesus Cristo. Amém."}]},{"chapter":81,"verses":[{"verse":1,"text":"Em verdade, em verdade te digo, meu servo Frederick G. Williams: Atende à voz daquele que fala, à palavra do Senhor teu Deus, e ouve o chamado para o qual és chamado, ou seja, o de sumo sacerdote na minha igreja e conselheiro de meu servo Joseph Smith Júnior;"},{"verse":2,"text":"A quem dei as chaves do reino, as quais pertencem sempre à presidência do sumo sacerdócio;"},{"verse":3,"text":"Portanto, em verdade reconheço-o e abençoá-lo-ei, como também a ti, se fores fiel no conselho, no cargo para o qual te designei, com oração constante, em voz alta e em teu coração, em público e em particular, também em teu ministério, proclamando o evangelho na terra dos vivos e entre teus irmãos."},{"verse":4,"text":"Assim agindo, farás o maior dos bens a teus semelhantes e promoverás a glória daquele que é teu Senhor."},{"verse":5,"text":"Portanto, sê fiel; ocupa o cargo para o qual te designei; socorre os fracos, ergue as mãos que pendem e fortalece os joelhos enfraquecidos."},{"verse":6,"text":"E se fores fiel até o fim, terás uma coroa de imortalidade e vida eterna nas mansões que eu preparei na casa de meu Pai."},{"verse":7,"text":"Eis que estas são as palavras do Alfa e do Ômega, sim, Jesus Cristo. Amém."}]},{"chapter":82,"verses":[{"verse":1,"text":"Em verdade, em verdade vos digo, meus servos, que como vos tendes perdoado uns aos outros vossas ofensas, assim também eu, o Senhor, vos perdoo."},{"verse":2,"text":"Contudo, há entre vós alguns que pecaram muito; sim, todos vós pecastes; mas em verdade vos digo: Acautelai-vos daqui em diante; abstende-vos do pecado para que dolorosos julgamentos não vos caiam sobre a cabeça."},{"verse":3,"text":"Porque daquele a quem muito é dado, muito é exigido; e o que pecar contra a luz maior receberá a condenação maior."},{"verse":4,"text":"Invocais meu nome pedindo revelações e eu vo-las dou; e se não guardais minhas palavras, as quais vos dou, vós vos tornais transgressores; e justiça e julgamento são a penalidade afixada pela minha lei."},{"verse":5,"text":"Portanto, o que digo a um digo a todos: Vigiai, porque o adversário espalha seus domínios, e as trevas reinam;"},{"verse":6,"text":"E a ira de Deus está acesa contra os habitantes da Terra; e ninguém faz o bem, pois todos se desviaram do caminho."},{"verse":7,"text":"E agora, em verdade vos digo: Eu, o Senhor, não vos atribuirei pecado algum; segui vossos caminhos e não pequeis mais; mas à alma que pecar retornarão os pecados passados, diz o Senhor vosso Deus."},{"verse":8,"text":"E também vos digo: Dou-vos um novo mandamento para que compreendais a minha vontade concernente a vós;"},{"verse":9,"text":"Ou, em outras palavras, dou-vos instruções sobre como agirdes perante mim, a fim de que isso se transforme em vossa salvação."},{"verse":10,"text":"Eu, o Senhor, estou obrigado quando fazeis o que eu digo; mas quando não o fazeis, não tendes promessa alguma."},{"verse":11,"text":"Portanto, em verdade vos digo que é preciso que meus servos Edward Patridge e Newel K. Whitney, A. Sidney Gilbert e Sidney Rigdon e meu servo Joseph Smith e John Whitmer e Oliver Cowdery e W. W. Phelps e Martin Harris se unam, em vossas diversas mordomias, por um vínculo e convênio que não se desfaça por transgressão sem que isso cause julgamento imediato —"},{"verse":12,"text":"Para dirigir os negócios dos pobres e todas as coisas que dizem respeito ao bispado, tanto na terra de Sião como na de Kirtland;"},{"verse":13,"text":"Pois consagrei a terra de Kirtland, no meu próprio e devido tempo, para benefício dos santos do Altíssimo e como uma estaca de Sião."},{"verse":14,"text":"Pois Sião deve crescer em beleza e em santidade; suas fronteiras devem ser expandidas; suas estacas devem ser fortalecidas; sim, em verdade vos digo: Sião deve erguer-se e vestir suas formosas vestes."},{"verse":15,"text":"Portanto, dou-vos este mandamento de que vos unais por meio deste convênio; e isto será feito de acordo com as leis do Senhor."},{"verse":16,"text":"Eis que isto também me é sábio, para o vosso bem."},{"verse":17,"text":"E deveis ser iguais, ou, em outras palavras, deveis ter os mesmos direitos sobre as propriedades, para o benefício da administração dos negócios de vossas mordomias, cada homem de acordo com seus anseios e necessidades, desde que seus anseios sejam justos —"},{"verse":18,"text":"E tudo isso para o benefício da igreja do Deus vivo, para que todo homem desenvolva seus talentos, para que todo homem adquira outros talentos, sim, até cem vezes mais, para que sejam lançados no armazém do Senhor a fim de se tornarem propriedade comum de toda a igreja —"},{"verse":19,"text":"Todo homem procurando os interesses de seu próximo e fazendo todas as coisas com os olhos fitos na glória de Deus."},{"verse":20,"text":"Esta ordem designei como ordem eterna para vós e para vossos sucessores, desde que não pequeis."},{"verse":21,"text":"E a alma que pecar contra esse convênio e contra ele endurecer o coração será tratada de acordo com as leis da minha igreja e será entregue às bofetadas de Satanás até o dia da redenção."},{"verse":22,"text":"E agora, em verdade vos digo e nisto há sabedoria: Granjeai amigos com as riquezas da iniquidade e eles não vos destruirão."},{"verse":23,"text":"Deixai o julgamento somente para mim, porque ele é meu e eu recompensarei. A paz seja convosco; convosco continuem minhas bênçãos."},{"verse":24,"text":"Pois o reino é vosso e sê-lo-á para sempre, se não abandonardes vossa perseverança. Assim seja. Amém."}]},{"chapter":83,"verses":[{"verse":1,"text":"Em verdade assim diz o Senhor, como acréscimo às leis da igreja concernentes às mulheres e crianças que pertencem à igreja e que perderam seus maridos ou pais:"},{"verse":2,"text":"A mulher tem o direito de receber do seu marido o seu sustento, até que o seu marido lhe seja tirado; e se não for considerada transgressora, terá participação na igreja."},{"verse":3,"text":"E se não for fiel, não terá participação na igreja; contudo, poderá permanecer em sua herança, de acordo com as leis do país."},{"verse":4,"text":"Todos os filhos têm o direito de receber de seus pais o seu sustento até alcançarem a maioridade."},{"verse":5,"text":"E depois disso, eles têm direito de recorrer à igreja ou, em outras palavras, ao armazém do Senhor, caso seus pais não tenham com o que lhes dar herança."},{"verse":6,"text":"E o armazém deverá ser mantido pelas consagrações da igreja; e prover-se-á a subsistência das viúvas e dos órfãos, como também dos pobres. Amém."}]},{"chapter":84,"verses":[{"verse":1,"text":"Uma revelação de Jesus Cristo a seu servo Joseph Smith Júnior e seis élderes, ao unirem o coração e erguerem a voz ao céu."},{"verse":2,"text":"Sim, a palavra do Senhor com respeito a sua igreja, estabelecida nos últimos dias, para a restauração de seu povo, como falou pela boca de seus profetas; e para a reunião de seus santos no Monte Sião, que será a cidade de Nova Jerusalém."},{"verse":3,"text":"Cidade essa que será construída a partir do terreno do templo, designado pelo dedo do Senhor, nas fronteiras ocidentais do Estado de Missouri e dedicado pela mão de Joseph Smith Júnior e outros de quem o Senhor se agradava."},{"verse":4,"text":"Em verdade esta é a palavra do Senhor: Que a cidade de Nova Jerusalém seja construída pela reunião dos santos, a partir deste lugar, sim, o local do templo, templo esse que será erigido nesta geração."},{"verse":5,"text":"Pois em verdade esta geração toda não passará sem que seja construída uma casa para o Senhor; e uma nuvem descansará sobre ela, nuvem essa que será a glória do Senhor, que encherá a casa."},{"verse":6,"text":"E os filhos de Moisés, de acordo com o Santo Sacerdócio que ele recebeu sob as mãos de Jetro, seu sogro;"},{"verse":7,"text":"E Jetro recebeu-o sob as mãos de Calebe;"},{"verse":8,"text":"E Calebe recebeu-o sob as mãos de Eliú;"},{"verse":9,"text":"E Eliú, sob as mãos de Jeremias;"},{"verse":10,"text":"E Jeremias, sob as mãos de Gade;"},{"verse":11,"text":"E Gade, sob as mãos de Esaías;"},{"verse":12,"text":"E Esaías recebeu-o sob as mãos de Deus."},{"verse":13,"text":"Esaías também viveu nos dias de Abraão e foi abençoado por ele —"},{"verse":14,"text":"Esse Abraão recebeu o sacerdócio de Melquisedeque, que o recebeu através da linhagem de seus pais, até Noé;"},{"verse":15,"text":"E de Noé até Enoque, através da linhagem dos pais deles;"},{"verse":16,"text":"E de Enoque até Abel, que foi assassinado pela conspiração de seu irmão e que recebeu o sacerdócio pelos mandamentos de Deus, pelas mãos de seu pai Adão, que foi o primeiro homem —"},{"verse":17,"text":"Sacerdócio esse que continua na igreja de Deus em todas as gerações e que não tem princípio de dias nem fim de anos."},{"verse":18,"text":"E o Senhor também confirmou um sacerdócio sobre Aarão e sua semente, através de todas as suas gerações, sacerdócio esse que também continua e permanece para sempre com o sacerdócio que é segundo a mais santa ordem de Deus."},{"verse":19,"text":"E esse sacerdócio maior administra o evangelho e contém a chave dos mistérios do reino, sim, a chave do conhecimento de Deus."},{"verse":20,"text":"Portanto, em suas ordenanças manifesta-se o poder da divindade."},{"verse":21,"text":"E sem suas ordenanças e a autoridade do sacerdócio, o poder da divindade não se manifesta aos homens na carne;"},{"verse":22,"text":"Pois, sem isso, nenhum homem pode ver o rosto de Deus, o Pai, e viver."},{"verse":23,"text":"Ora, isso Moisés claramente ensinou aos filhos de Israel no deserto e procurou diligentemente santificar seu povo para que contemplassem a face de Deus;"},{"verse":24,"text":"Eles, porém, endureceram o coração e não puderam suportar sua presença; portanto, o Senhor, em sua ira, pois sua ira estava acesa contra eles, jurou que enquanto estivessem no deserto não entrariam para o seu descanso, descanso esse que é a plenitude de sua glória."},{"verse":25,"text":"Portanto, tirou Moisés do meio deles, como também o Santo Sacerdócio;"},{"verse":26,"text":"E o sacerdócio menor continuou, sacerdócio esse que contém a chave do ministério de anjos e do evangelho preparatório;"},{"verse":27,"text":"Evangelho esse que é o evangelho do arrependimento e do batismo e da remissão de pecados e a lei dos mandamentos carnais, que o Senhor, em sua ira, fez com que continuasse na casa de Aarão, entre os filhos de Israel, até João, a quem Deus levantou, sendo cheio do Espírito Santo desde o ventre de sua mãe."},{"verse":28,"text":"Pois foi batizado quando ainda na infância e, quando tinha oito dias de idade, foi ordenado por um anjo de Deus para esse poder, a fim de derrubar o reino dos judeus e endireitar as veredas do Senhor diante da face de seu povo, com o fim de prepará-lo para a vinda do Senhor, em cujas mãos é dado todo o poder."},{"verse":29,"text":"E também os ofícios de élder e bispo são apêndices necessários do sacerdócio maior."},{"verse":30,"text":"E também os ofícios de mestre e diácono são apêndices necessários do sacerdócio menor, sacerdócio esse que foi confirmado sobre Aarão e seus filhos."},{"verse":31,"text":"Portanto, como eu disse concernente aos filhos de Moisés — pois os filhos de Moisés e também os filhos de Aarão oferecerão uma oferta e um sacrifício aceitáveis na casa do Senhor, casa essa que será construída para o Senhor nesta geração, no local consagrado, como designei —"},{"verse":32,"text":"E os filhos de Moisés e de Aarão encher-se-ão da glória do Senhor no Monte Sião, na casa do Senhor, cujos filhos sois vós; e também muitos a quem chamei e enviei para edificar a minha igreja."},{"verse":33,"text":"Pois aqueles que forem fiéis de modo a obter estes dois sacerdócios de que falei e a magnificar seu chamado serão santificados pelo Espírito para a renovação do corpo."},{"verse":34,"text":"Tornam-se os filhos de Moisés e de Aarão e a semente de Abraão; e a igreja e reino e os eleitos de Deus."},{"verse":35,"text":"E também todos os que recebem esse sacerdócio a mim me recebem, diz o Senhor;"},{"verse":36,"text":"Pois aquele que recebe os meus servos, a mim me recebe;"},{"verse":37,"text":"E aquele que me recebe a mim, recebe a meu Pai;"},{"verse":38,"text":"E aquele que recebe a meu Pai, recebe o reino de meu Pai; portanto, tudo o que meu Pai possui ser-lhe-á dado."},{"verse":39,"text":"E isto está de acordo com o juramento e convênio que pertencem ao sacerdócio."},{"verse":40,"text":"Portanto, todos os que recebem o sacerdócio recebem esse juramento e convênio de meu Pai, que ele não pode quebrar nem pode ser removido."},{"verse":41,"text":"Mas aquele que quebrar esse convênio após tê-lo recebido e desviar-se dele totalmente não receberá perdão dos pecados neste mundo nem no mundo vindouro."},{"verse":42,"text":"E ai de todos os que recusam esse sacerdócio recebido por vós, que eu agora confirmo sobre vós, presentes neste dia, por minha própria voz, desde o céu; e eu mesmo coloquei-vos sob a responsabilidade das hostes celestiais e de meus anjos."},{"verse":43,"text":"E agora vos dou o mandamento de que vos acauteleis a respeito de vós mesmos, de que deis ouvidos diligentemente às palavras de vida eterna."},{"verse":44,"text":"Porque vivereis de toda palavra que sai da boca de Deus."},{"verse":45,"text":"Porque a palavra do Senhor é verdade; e tudo que é verdade é luz; e tudo que é luz é Espírito, sim, o Espírito de Jesus Cristo."},{"verse":46,"text":"E o Espírito dá luz a todo homem que vem ao mundo; e o Espírito ilumina todo homem no mundo que dá ouvidos à sua voz."},{"verse":47,"text":"E todo aquele que dá ouvidos à voz do Espírito vem a Deus, sim, o Pai."},{"verse":48,"text":"E o Pai ensina-lhe sobre o convênio que ele renovou e confirmou sobre vós, o qual é confirmado sobre vós para o vosso bem; e não somente para o vosso bem, mas para o bem do mundo todo."},{"verse":49,"text":"E o mundo todo se acha em pecado e geme sob as trevas e sob o jugo do pecado."},{"verse":50,"text":"E por isto podereis saber que estão sob o jugo do pecado, porque eles não vêm a mim."},{"verse":51,"text":"Porque aquele que não vem a mim está sob o jugo do pecado."},{"verse":52,"text":"E quem não recebe a minha voz não conhece a minha voz, e não é meu."},{"verse":53,"text":"E por isto podeis discernir os justos dos iníquos e saber que, neste momento, o mundo todo geme sob o pecado e as trevas."},{"verse":54,"text":"E em tempos passados, vossa mente escureceu-se por causa da descrença e porque tratastes com leviandade as coisas que recebestes —"},{"verse":55,"text":"Vaidade e descrença essas que levaram toda a igreja à condenação."},{"verse":56,"text":"E essa condenação encontra-se sobre os filhos de Sião, sim, sobre todos."},{"verse":57,"text":"E eles permanecerão sob essa condenação até que se arrependam e se lembrem do novo convênio, sim, o Livro de Mórmon e os mandamentos anteriores que lhes dei, não somente por palavras, mas agindo de acordo com o que escrevi —"},{"verse":58,"text":"Para que produzam frutos dignos do reino de seu Pai; caso contrário, há um flagelo e julgamento a derramar-se sobre os filhos de Sião."},{"verse":59,"text":"Pois contaminarão a minha terra santa os filhos do reino? Em verdade vos digo que não."},{"verse":60,"text":"Em verdade, em verdade vos digo, vós que agora ouvis as minhas palavras, que são a minha voz: Bem-aventurados sereis se receberdes estas coisas;"},{"verse":61,"text":"Porque vos perdoarei vossos pecados com este mandamento: Que permaneçais firmes em vossa mente, com solenidade e espírito de oração, prestando ao mundo todo testemunho das coisas que vos são comunicadas."},{"verse":62,"text":"Portanto, ide por todo o mundo; e ao lugar que não puderdes ir, enviareis, para que o testemunho parta de vós para todo o mundo e a toda criatura."},{"verse":63,"text":"E como disse a meus apóstolos, assim vos digo, porque sois meus apóstolos, sumos sacerdotes de Deus; sois aqueles que o Pai me deu; sois meus amigos;"},{"verse":64,"text":"Portanto, como disse a meus apóstolos, também vos digo que toda alma que acreditar em vossas palavras e for batizada pela água para remissão de pecados receberá o Espírito Santo."},{"verse":65,"text":"E estes sinais seguirão os que crerem:"},{"verse":66,"text":"Em meu nome realizarão muitas obras maravilhosas;"},{"verse":67,"text":"Em meu nome expulsarão demônios;"},{"verse":68,"text":"Em meu nome curarão os enfermos;"},{"verse":69,"text":"Em meu nome abrirão os olhos dos cegos e os ouvidos dos surdos;"},{"verse":70,"text":"E a língua dos mudos falará;"},{"verse":71,"text":"E se algum homem lhes administrar veneno, não lhes fará mal;"},{"verse":72,"text":"E o veneno de uma serpente não terá poder para lhes fazer mal."},{"verse":73,"text":"Dou-lhes, porém, o mandamento de que não se vangloriem destas coisas nem falem delas diante do mundo; pois estas coisas vos são dadas para vosso proveito e salvação."},{"verse":74,"text":"Em verdade, em verdade vos digo: Aqueles que não acreditarem em vossas palavras e não forem batizados na água em meu nome para remissão de seus pecados, para que recebam o Espírito Santo, serão condenados e não entrarão no reino de meu Pai, onde meu Pai e eu estamos."},{"verse":75,"text":"E esta revelação e mandamento que vos dou entra em vigor neste exato momento para todo o mundo; e o evangelho é para todos os que não o tenham recebido."},{"verse":76,"text":"Mas em verdade eu digo a todos aqueles a quem o reino foi dado: Sois vós que deveis pregar a eles para que se arrependam de suas obras malévolas anteriores; pois devem ser repreendidos por causa de seu coração mau e incrédulo, assim como vossos irmãos de Sião, por terem se rebelado contra vós quando vos enviei."},{"verse":77,"text":"E também vos digo, meus amigos, pois de agora em diante vos chamarei de amigos: É conveniente que eu vos dê este mandamento, a fim de que vos torneis como os meus amigos dos dias em que estava com eles, viajando para pregar o evangelho com o meu poder;"},{"verse":78,"text":"Pois não lhes permiti terem bolsa ou alforje nem duas túnicas."},{"verse":79,"text":"Eis que vos envio para provar o mundo; e o trabalhador é digno de seu salário."},{"verse":80,"text":"E não se cansará nem se turvará a mente do homem que sair a pregar este evangelho do reino, nem seu corpo, membros e juntas; nem um fio de seus cabelos cairá sem que se perceba. E não sofrerão fome nem sede."},{"verse":81,"text":"Portanto, não vos preocupeis com o amanhã, com o que haveis de comer nem com o que haveis de beber nem com o que haveis de vestir."},{"verse":82,"text":"Olhai para os lírios do campo, como eles crescem: Não trabalham nem fiam; e os reinos do mundo, em toda a sua glória, não se vestem como qualquer deles."},{"verse":83,"text":"Pois vosso Pai, que está no céu, sabe que necessitais de todas essas coisas."},{"verse":84,"text":"Portanto, deixai que o amanhã se preocupe com suas próprias coisas."},{"verse":85,"text":"Nem de antemão vos preocupeis com o que haveis de dizer; mas entesourai sempre em vossa mente as palavras de vida e na hora precisa vos será dada a porção que será concedida a cada homem."},{"verse":86,"text":"Portanto, que nenhum homem entre vós leve, de agora em diante, bolsa ou alforje, ao partir para proclamar este evangelho do reino, pois este mandamento é para todos os fiéis que na igreja são chamados por Deus para o ministério."},{"verse":87,"text":"Eis que eu vos envio para repreender o mundo por todas as suas más ações e para instruir quanto a um julgamento futuro."},{"verse":88,"text":"E quem vos receber, lá estarei também, pois irei adiante de vós. Estarei à vossa direita e à vossa esquerda e meu Espírito estará em vosso coração e meus anjos ao vosso redor para vos suster."},{"verse":89,"text":"Quem vos recebe, a mim me recebe; e ele vos alimentará e vos vestirá e vos dará dinheiro."},{"verse":90,"text":"E aquele que vos alimentar ou vos vestir ou vos der dinheiro, de modo algum perderá sua recompensa."},{"verse":91,"text":"Aquele que não fizer essas coisas não é meu discípulo; dessa forma conhecereis meus discípulos."},{"verse":92,"text":"Afastai-vos daquele que não vos receber e, a sós, lavai vossos pés com água, sim, com água pura, seja no calor ou no frio, e isso testificai a vosso Pai que está nos céus; e não volteis para junto daquele homem."},{"verse":93,"text":"E em qualquer povoado ou cidade que entrardes, fazei o mesmo."},{"verse":94,"text":"Contudo, procurai diligentemente e não esmoreçais; e ai da casa ou do povoado ou cidade que vos rejeitar ou rejeitar vossas palavras ou vosso testemunho quanto a mim."},{"verse":95,"text":"Ai, torno a dizer, da casa ou povoado ou cidade que vos rejeitar ou rejeitar vossas palavras ou vosso testemunho de mim;"},{"verse":96,"text":"Pois eu, o Todo-Poderoso, deitei as mãos sobre as nações para flagelá-las por suas iniquidades."},{"verse":97,"text":"E surgirão pragas e não serão tiradas da Terra até que eu tenha completado minha obra, que se abreviará em retidão —"},{"verse":98,"text":"Até que todos os que restarem me conheçam, sim, do menor até ao maior; e encham-se do conhecimento do Senhor e vejam olho a olho e ergam suas vozes e juntos cantem este novo cântico, dizendo:"},{"verse":99,"text":"O Senhor trouxe Sião outra vez;O Senhor redimiu seu povo, Israel,De acordo com a eleição da graçaQue se realizou pela féE convênio de seus pais."},{"verse":100,"text":"O Senhor redimiu seu povo;E Satanás está preso e o tempo já não existe.O Senhor reuniu todas as coisas em uma.O Senhor trouxe Sião do alto.O Senhor ergueu Sião de baixo."},{"verse":101,"text":"A Terra concebeu e deu à luz sua força;E a verdade está estabelecida em suas entranhas;E os céus sorriram sobre ela;E ela está vestida com a glória de seu Deus;Porque ele está no meio de seu povo."},{"verse":102,"text":"Glória e honra e força e poderSejam dados a nosso Deus; porque ele é cheio de misericórdia,Justiça, graça e verdade e pazPara todo o sempre. Amém."},{"verse":103,"text":"E também, em verdade, em verdade vos digo: É conveniente que todos os homens que saírem para proclamar meu evangelho eterno, se tiverem família e receberem dinheiro como presente, enviem-no a sua família ou usem-no em benefício dela, como o Senhor os instruir, pois isto me parece bom."},{"verse":104,"text":"E que todos os que receberem dinheiro e não tiverem família, enviem-no ao bispo de Sião ou ao bispo de Ohio, a fim de que seja consagrado para trazer à luz as revelações e para imprimi-las com a finalidade de estabelecer Sião."},{"verse":105,"text":"E se algum homem vos der um casaco ou um traje, tomai o velho e dai-o aos pobres e segui vosso caminho, rejubilando-vos."},{"verse":106,"text":"E se houver algum homem entre vós de Espírito forte, que tome consigo aquele que for fraco, para que seja edificado em toda mansidão a fim de também se tornar forte."},{"verse":107,"text":"Portanto, levai convosco os que são ordenados ao sacerdócio menor e enviai-os adiante de vós para marcar compromissos e preparar o caminho e cumprir os compromissos que não puderdes cumprir."},{"verse":108,"text":"Eis que foi assim que meus apóstolos, na antiguidade, edificaram-me a minha igreja."},{"verse":109,"text":"Portanto, que todo homem ocupe seu próprio cargo e trabalhe em seu próprio chamado; e que a cabeça não diga aos pés não ter deles necessidade; porque, sem os pés, como se sustentaria o corpo?"},{"verse":110,"text":"Também o corpo tem necessidade de todos os membros, para que todos sejam juntos edificados, a fim de que o sistema se mantenha perfeito."},{"verse":111,"text":"E eis que os sumos sacerdotes devem viajar, assim como os élderes e também os sacerdotes menores; mas os diáconos e os mestres devem ser designados para zelar pela igreja, para serem ministros locais da igreja."},{"verse":112,"text":"E o bispo, Newel K. Whitney, também deve viajar pelas redondezas e por entre todas as igrejas, buscando os pobres a fim de atender às suas necessidades, tornando humildes os ricos e os orgulhosos."},{"verse":113,"text":"Deve também empregar um agente que se encarregue e cuide de seus negócios seculares, conforme sua orientação."},{"verse":114,"text":"Contudo, que o bispo vá à cidade de Nova York e também à cidade de Albany e à cidade de Boston; e advirta o povo dessas cidades com o som do evangelho, em voz alta, da desolação e completa destruição que os aguardam, se rejeitarem estas coisas."},{"verse":115,"text":"Pois se rejeitarem estas coisas, a hora de seu julgamento estará próxima e sua casa se lhes fará deserta."},{"verse":116,"text":"Que ele confie em mim e não será confundido; e nenhum fio de cabelo de sua cabeça cairá sem que se perceba."},{"verse":117,"text":"E em verdade eu digo a vós, o restante de meus servos: Saí, como vos permitirem as circunstâncias, em vossos diversos chamados, indo às grandes e notáveis cidades e povoados, repreendendo o mundo em retidão por todos os seus feitos injustos e ímpios, explicando de modo claro e compreensível a ruína da abominação dos últimos dias."},{"verse":118,"text":"Pois convosco, diz o Senhor Todo-Poderoso, esmiuçarei seus reinos; não somente farei estremecer a Terra, mas também os céus estrelados tremerão."},{"verse":119,"text":"Pois eu, o Senhor, estendi minha mão para exercer os poderes do céu; não podeis vê-lo agora, mas em pouco o vereis e sabereis que eu sou e que virei e reinarei com meu povo."},{"verse":120,"text":"Eu sou o Alfa e o Ômega, o princípio e o fim. Amém."}]},{"chapter":85,"verses":[{"verse":1,"text":"É dever do secretário do Senhor, a quem ele designou, conservar uma história e um registro geral da igreja de todas as coisas que ocorrem em Sião; e de todos os que consagram propriedades e legalmente recebem heranças do bispo;"},{"verse":2,"text":"E também seu modo de vida, sua fé e obras; assim como dos apóstatas que apostatarem depois de haver recebido suas heranças."},{"verse":3,"text":"É contrário à vontade e ao mandamento de Deus que os que não recebem sua herança por consagração, de acordo com sua lei, dada por ele para cobrar os dízimos de seu povo a fim de prepará-los para o dia da vingança e queima, tenham seus nomes registrados com o povo de Deus."},{"verse":4,"text":"Não se conservará sua genealogia nem se encontrará nos registros ou na história da igreja."},{"verse":5,"text":"Seus nomes não serão encontrados, nem os nomes dos pais nem os nomes dos filhos escritos no livro da lei de Deus, diz o Senhor dos Exércitos."},{"verse":6,"text":"Assim diz a voz mansa e delicada, que sussurra através de todas as coisas e penetra todas as coisas e muitas vezes faz com que meus ossos estremeçam enquanto se manifesta, dizendo:"},{"verse":7,"text":"E acontecerá que eu, o Senhor Deus, enviarei alguém poderoso e forte, tendo na mão o cetro do poder, revestido de luz como um manto, cuja boca proferirá palavras, palavras eternas, ao passo que suas entranhas serão uma fonte de verdade, para pôr em ordem a casa de Deus e repartir por sorte as heranças dos santos, cujos nomes estejam registrados no livro da lei de Deus com os nomes de seus pais e de seus filhos;"},{"verse":8,"text":"Enquanto o homem que foi chamado por Deus e designado, que estende a mão para firmar a arca de Deus, cairá pela flecha da morte como uma árvore que é atingida pela flecha vívida do relâmpago."},{"verse":9,"text":"E todos aqueles que não se acharem inscritos no livro de recordações não terão herança alguma naquele dia, mas serão feitos em pedaços e sua porção lhes será designada entre incrédulos, onde há choro e ranger de dentes."},{"verse":10,"text":"Estas coisas não as digo de mim mesmo; portanto, como fala o Senhor, assim ele cumprirá."},{"verse":11,"text":"E aqueles que são do sacerdócio maior, cujos nomes não estão escritos no livro da lei, ou que apostataram, ou que foram eliminados da igreja, assim como o sacerdócio menor ou os membros, naquele dia não encontrarão uma herança entre os santos do Altíssimo;"},{"verse":12,"text":"Portanto, a eles será feito como aos filhos do sacerdote, como registrado no capítulo dois, versículos sessenta e um e sessenta e dois de Esdras."}]},{"chapter":86,"verses":[{"verse":1,"text":"Em verdade, assim diz o Senhor a vós, meus servos, em relação à parábola do trigo e do joio:"},{"verse":2,"text":"Eis que em verdade vos digo que o campo era o mundo; e os apóstolos eram os semeadores das sementes;"},{"verse":3,"text":"E depois de terem adormecido, a grande perseguidora da igreja, a apóstata, a prostituta, sim, Babilônia, que faz com que todas as nações bebam de seu cálice, em cujos corações o inimigo, sim, Satanás, assenta-se para reinar — eis que ele semeia o joio; portanto, o joio sufoca o trigo e impele a igreja para o deserto."},{"verse":4,"text":"Mas eis que nos últimos dias, sim, agora, enquanto o Senhor está começando a trazer à luz a palavra e a haste está brotando e está ainda tenra —"},{"verse":5,"text":"Eis que em verdade vos digo: Os anjos estão clamando ao Senhor dia e noite, pois estão prontos e esperando para ser enviados a ceifar os campos;"},{"verse":6,"text":"Diz-lhes, porém, o Senhor: Não arranqueis o joio enquanto a folha estiver ainda tenra (pois em verdade vossa fé é fraca), para que não destruais também o trigo."},{"verse":7,"text":"Portanto, deixai que o trigo e o joio cresçam juntos até que a colheita esteja completamente amadurecida; então colhereis primeiramente o trigo dentre o joio e, depois da colheita do trigo, eis que o joio será amarrado em feixes e o campo estará pronto para ser queimado."},{"verse":8,"text":"Portanto, assim diz o Senhor a vós, com quem o sacerdócio continuou através da linhagem de vossos pais —"},{"verse":9,"text":"Porque sois herdeiros legais segundo a carne e fostes escondidos do mundo com Cristo, em Deus —"},{"verse":10,"text":"Portanto, a vossa vida e o sacerdócio permaneceram; e é necessário que permaneçam por meio de vós e de vossa linhagem, até a restauração de todas as coisas proferidas pela boca de todos os santos profetas desde o princípio do mundo."},{"verse":11,"text":"Portanto, bem-aventurados sois se continuais em minha bondade, uma luz para os gentios; e por meio deste sacerdócio, um salvador para meu povo, Israel. O Senhor disse-o. Amém."}]},{"chapter":87,"verses":[{"verse":1,"text":"Em verdade, assim diz o Senhor em relação às guerras que logo ocorrerão, a começar pela rebelião da Carolina do Sul que, por fim, terminará com a morte e sofrimento de muitas almas;"},{"verse":2,"text":"E chegará o tempo em que a guerra se derramará sobre todas as nações, começando desse lugar."},{"verse":3,"text":"Pois eis que os estados do sul se dividirão contra os estados do norte e os estados do sul recorrerão a outras nações, mesmo à nação da Grã-Bretanha, como é chamada, e eles também recorrerão a outras nações a fim de se defenderem contra outras nações; e então a guerra se derramará sobre todas as nações."},{"verse":4,"text":"E acontecerá, depois de muitos dias, que escravos se levantarão contra seus senhores, os quais serão organizados e treinados para a guerra."},{"verse":5,"text":"E acontecerá também que os remanescentes dos que ficarem na terra se organizarão e se tornarão muito zangados; e afligirão os gentios com dolorosa aflição."},{"verse":6,"text":"E assim, pela espada e por derramamento de sangue, os habitantes da Terra lamentar-se-ão; e com fome e pragas e terremotos e também com o trovão do céu e o violento e vívido relâmpago, os habitantes da Terra sentirão a ira, a indignação e a mão castigadora de um Deus Todo-Poderoso, até que a destruição decretada ponha um fim total a todas as nações;"},{"verse":7,"text":"Para que o clamor dos santos e do sangue dos santos cesse de subir da Terra aos ouvidos do Senhor de Sabaote, pedindo que sejam vingados de seus inimigos."},{"verse":8,"text":"Portanto, permanecei em lugares santos e não sejais movidos até que venha o dia do Senhor; pois eis que depressa vem, diz o Senhor. Amém."}]},{"chapter":88,"verses":[{"verse":1,"text":"Em verdade assim vos diz o Senhor, a vós que vos reunistes para saber a sua vontade quanto a vós:"},{"verse":2,"text":"Eis que isto é agradável a vosso Senhor e os anjos regozijam-se por vossa causa; as esmolas de vossas orações subiram aos ouvidos do Senhor de Sabaote e estão registradas no livro de nomes dos santificados, sim, os do mundo celestial."},{"verse":3,"text":"Portanto, agora vos envio outro Consolador, sim, a vós, meus amigos, para que habite em vosso coração, sim, o Santo Espírito da promessa; esse outro Consolador é o mesmo que prometi a meus discípulos, como registrado no testemunho de João."},{"verse":4,"text":"Esse Consolador é a promessa de vida eterna que vos faço, sim, a glória do reino celestial;"},{"verse":5,"text":"Cuja glória é a da igreja do Primogênito, sim, de Deus, o mais santo de todos, por intermédio de Jesus Cristo, seu Filho —"},{"verse":6,"text":"Aquele que subiu ao alto, como também desceu abaixo de todas as coisas, no sentido de que compreendeu todas as coisas, para que fosse em tudo e através de todas as coisas, a luz da verdade;"},{"verse":7,"text":"Verdade essa que brilha. Essa é a luz de Cristo. Como também ele está no sol e é a luz do sol e o poder pelo qual foi feito."},{"verse":8,"text":"Como também ele está na lua e é a luz da lua e o poder pelo qual foi feita;"},{"verse":9,"text":"Como também a luz das estrelas e o poder pelo qual foram feitas;"},{"verse":10,"text":"E também a Terra e seu poder, sim, a Terra sobre a qual estais."},{"verse":11,"text":"E a luz que brilha, que vos ilumina, vem por meio daquele que ilumina vossos olhos; e é a mesma luz que vivifica vosso entendimento;"},{"verse":12,"text":"Luz essa que procede da presença de Deus para encher a imensidade do espaço —"},{"verse":13,"text":"A luz que está em todas as coisas, que dá vida a todas as coisas, que é a lei pela qual todas as coisas são governadas, sim, o poder de Deus, que se assenta em seu trono, que está no seio da eternidade, que está no meio de todas as coisas."},{"verse":14,"text":"Ora, em verdade vos digo que por meio da redenção que foi feita por vós realiza-se a ressurreição dos mortos."},{"verse":15,"text":"E o espírito e o corpo são a alma do homem."},{"verse":16,"text":"E a ressurreição dos mortos é a redenção da alma."},{"verse":17,"text":"E a redenção da alma realiza-se por meio daquele que vivifica todas as coisas, em cujo seio está decretado que os pobres e os mansos da Terra a herdarão."},{"verse":18,"text":"Portanto, é necessário que seja santificada de toda a iniquidade, a fim de ser preparada para a glória celestial;"},{"verse":19,"text":"Pois após ter cumprido o propósito de sua criação, será coroada com glória, sim, com a presença de Deus, o Pai;"},{"verse":20,"text":"Para que os corpos que forem do reino celestial possuam-na para todo o sempre; porque com esse intento foi feita e criada e com esse intento são eles santificados."},{"verse":21,"text":"E os que não forem santificados por meio da lei que vos dei, sim, a lei de Cristo, herdarão outro reino, sim, um reino terrestre ou um reino telestial."},{"verse":22,"text":"Porque aquele que não consegue viver a lei de um reino celestial não consegue suportar uma glória celestial."},{"verse":23,"text":"E aquele que não consegue viver a lei de um reino terrestre não consegue suportar uma glória terrestre."},{"verse":24,"text":"E aquele que não consegue viver a lei de um reino telestial não consegue suportar uma glória telestial; portanto, não é digno de um reino de glória. Portanto, deve permanecer num reino que não seja um reino de glória."},{"verse":25,"text":"E também, em verdade vos digo que a Terra vive a lei de um reino celestial, porque cumpre o propósito de sua criação e não transgride a lei —"},{"verse":26,"text":"Portanto, será santificada; sim, embora vá morrer, tornará a ser vivificada e suportará o poder pelo qual será vivificada; e os justos herdá-la-ão."},{"verse":27,"text":"Pois, apesar de morrerem, também tornarão a levantar-se, um corpo espiritual."},{"verse":28,"text":"Aqueles que forem de um espírito celestial receberão o mesmo corpo que era um corpo natural; sim, recebereis vosso corpo e vossa glória será a glória pela qual vosso corpo é vivificado."},{"verse":29,"text":"Vós, que fordes vivificados por uma porção da glória celestial, recebereis sua plenitude."},{"verse":30,"text":"E aqueles que forem vivificados por uma porção da glória terrestre receberão sua plenitude."},{"verse":31,"text":"E também aqueles que forem vivificados por uma porção da glória telestial receberão sua plenitude."},{"verse":32,"text":"E os que restarem também serão vivificados; contudo, regressarão a seu próprio lugar para usufruir aquilo que estiverem dispostos a receber, porque não estavam dispostos a usufruir aquilo que poderiam ter recebido."},{"verse":33,"text":"Pois de que vale a um homem ser-lhe conferida uma dádiva e não a receber? Eis que ele não se regozija no que lhe foi dado nem se regozija naquele que faz a doação."},{"verse":34,"text":"E também, em verdade vos digo que o que é governado pela lei é também preservado pela lei e é por ela aperfeiçoado e santificado."},{"verse":35,"text":"Aquilo que transgride uma lei e não obedece à lei, mas procura tornar-se uma lei para si mesmo e prefere permanecer no pecado, nele permanecendo inteiramente, não pode ser santificado por lei nem por misericórdia, justiça ou julgamento. Portanto, permanece imundo ainda."},{"verse":36,"text":"A todos os reinos se deu uma lei;"},{"verse":37,"text":"E há muitos reinos; pois não existe espaço em que não haja reino; e não existe reino em que não haja espaço, seja um reino maior ou um reino menor."},{"verse":38,"text":"E a todo reino é dada uma lei; e toda lei também tem certos limites e condições."},{"verse":39,"text":"Todos os seres que não se conformam a essas condições não são justificados."},{"verse":40,"text":"Pois a inteligência apega-se à inteligência; a sabedoria recebe a sabedoria; a verdade abraça a verdade; a virtude ama a virtude; a luz se apega à luz; a misericórdia se compadece da misericórdia e reclama o que é seu; a justiça segue seu curso e reclama o que é seu; o julgamento vai ante a face daquele que se assenta no trono e governa e executa todas as coisas."},{"verse":41,"text":"Ele compreende todas as coisas e todas as coisas estão diante dele e todas as coisas estão ao seu redor; e ele está acima de todas as coisas e em todas as coisas e através de todas as coisas e ao redor de todas as coisas; e todas as coisas existem por ele e dele, sim, Deus, para todo o sempre."},{"verse":42,"text":"E também, em verdade vos digo: Ele deu uma lei para todas as coisas, pela qual se movem em seu tempo e em suas estações;"},{"verse":43,"text":"E seus cursos são fixos, sim, os cursos dos céus e da Terra, que abrangem a Terra e todos os planetas."},{"verse":44,"text":"E transmitem luz uns aos outros em seu tempo e em suas estações, em seus minutos, em suas horas, em seus dias, em suas semanas, em seus meses e em seus anos — e tudo isto é um ano para Deus, mas não para o homem."},{"verse":45,"text":"A Terra gira em suas asas e o sol dá sua luz de dia e a lua dá sua luz à noite e as estrelas também dão sua luz, ao girarem em suas asas, em sua glória, no meio do poder de Deus."},{"verse":46,"text":"A que compararei estes reinos, para que compreendais?"},{"verse":47,"text":"Eis que todos estes são reinos; e qualquer homem que tiver visto um deles, ou o menor deles, viu Deus movendo-se em sua majestade e poder."},{"verse":48,"text":"Digo-vos: Ele viu-o; entretanto, aquele que veio para os seus não foi compreendido."},{"verse":49,"text":"A luz brilha nas trevas e as trevas não a compreendem; contudo, dia virá em que compreendereis até o próprio Deus, sendo vivificados nele e por ele."},{"verse":50,"text":"Então sabereis que me vistes, que eu sou e que sou a verdadeira luz que está em vós e que vós estais em mim; caso contrário, não poderíeis prosperar."},{"verse":51,"text":"Eis que compararei estes reinos a um homem que tem um campo e que a ele enviou seus servos para nele cavar."},{"verse":52,"text":"E disse ao primeiro: Vai e trabalha no campo; e na primeira hora procurar-te-ei e contemplarás a alegria de meu semblante."},{"verse":53,"text":"E disse ao segundo: Vai também para o campo e, na segunda hora, visitar-te-ei com a alegria de meu semblante."},{"verse":54,"text":"E também ao terceiro disse: Visitar-te-ei;"},{"verse":55,"text":"E ao quarto e assim por diante, até o décimo segundo."},{"verse":56,"text":"E o senhor do campo foi até o primeiro na primeira hora e permaneceu com ele toda aquela hora; e ele alegrou-se com a luz do semblante de seu senhor."},{"verse":57,"text":"E então apartou-se do primeiro a fim de visitar também o segundo e o terceiro e o quarto e assim por diante, até o décimo segundo."},{"verse":58,"text":"E assim todos eles receberam a luz do semblante de seu senhor, cada homem em sua hora e em seu tempo e em sua estação —"},{"verse":59,"text":"Começando pelo primeiro e assim por diante, até o último; e do último ao primeiro e do primeiro ao último;"},{"verse":60,"text":"Cada homem em sua própria ordem até que sua hora terminasse, de acordo com o que seu senhor lhe ordenara, para que seu senhor fosse nele glorificado e ele em seu senhor, a fim de que todos fossem glorificados."},{"verse":61,"text":"Portanto, a esta parábola compararei todos estes reinos e seus habitantes — cada reino em sua hora e em seu tempo e em sua estação, de acordo com o decreto de Deus."},{"verse":62,"text":"E também, em verdade vos digo, meus amigos: Deixo-vos estas palavras para que pondereis em vosso coração com este mandamento que vos dou de que me invoqueis enquanto estou perto —"},{"verse":63,"text":"Achegai-vos a mim e achegar-me-ei a vós; procurai-me diligentemente e achar-me-eis; pedi e recebereis; batei e ser-vos-á aberto."},{"verse":64,"text":"Tudo o que pedirdes ao Pai em meu nome vos será dado, se for para vosso bem;"},{"verse":65,"text":"E se pedirdes alguma coisa que não seja para o vosso bem, tornar-se-á em vossa condenação."},{"verse":66,"text":"Eis que o que ouvis é como a voz de alguém clamando no deserto — no deserto, porque não o podeis ver — a minha voz, porque a minha voz é Espírito; o meu Espírito é verdade; a verdade persiste e não tem fim; e se estiver em vós, prosperará."},{"verse":67,"text":"E se vossos olhos estiverem fitos em minha glória, todo o vosso corpo se encherá de luz e em vós não haverá trevas; e o corpo que é cheio de luz compreende todas as coisas."},{"verse":68,"text":"Portanto, santificai-vos, para que vossa mente concentre-se em Deus; e dias virão em que o vereis, porque ele vos desvendará sua face; e será em seu próprio tempo e a seu próprio modo e de acordo com sua própria vontade."},{"verse":69,"text":"Lembrai-vos da grande e última promessa que vos fiz; rechaçai vossos pensamentos ociosos e vossos risos excessivos."},{"verse":70,"text":"Permanecei, permanecei neste lugar e convocai uma assembleia solene, sim, daqueles que são os primeiros trabalhadores deste último reino."},{"verse":71,"text":"E que aqueles a quem advertiram em suas viagens invoquem o Senhor e ponderem por algum tempo, em seu coração, a advertência que receberam."},{"verse":72,"text":"Eis que cuidarei de vossos rebanhos e levantarei élderes e enviá-los-ei a eles."},{"verse":73,"text":"Eis que apressarei minha obra a seu tempo."},{"verse":74,"text":"E dou a vós, que sois os primeiros trabalhadores deste último reino, um mandamento de que vos reunais e vos organizeis e vos prepareis e vos santifiqueis; sim, purificai o coração e lavai as mãos e os pés perante mim, para que eu vos torne limpos;"},{"verse":75,"text":"Para que eu testifique a vosso Pai e vosso Deus e meu Deus, que estais limpos do sangue desta geração iníqua; para que, quando eu desejar, cumpra esta promessa, esta grande e última promessa que vos fiz;"},{"verse":76,"text":"Também vos dou um mandamento de que continueis em oração e jejum a partir de agora."},{"verse":77,"text":"E dou-vos um mandamento de que vos ensineis a doutrina do reino uns aos outros."},{"verse":78,"text":"Ensinai diligentemente e minha graça acompanhar-vos-á, para que sejais instruídos mais perfeitamente em teoria, em princípio, em doutrina, na lei do evangelho, em todas as coisas pertinentes ao reino de Deus, que vos convém compreender;"},{"verse":79,"text":"Tanto as coisas do céu como da Terra e de debaixo da Terra; coisas que foram, coisas que são, coisas que logo hão de suceder; coisas que estão em casa, coisas que estão no estrangeiro; as guerras e complexidades das nações e os julgamentos que estão sobre a terra; e também um conhecimento de países e reinos —"},{"verse":80,"text":"Para que estejais preparados em todas as coisas, quando eu vos enviar outra vez para magnificardes o chamado com o qual vos chamei e a missão com a qual vos comissionei."},{"verse":81,"text":"Eis que vos enviei para testificar e advertir o povo, e todo aquele que for advertido deverá advertir seu próximo."},{"verse":82,"text":"Portanto, não têm desculpa e seus pecados estão sobre sua própria cabeça."},{"verse":83,"text":"Aquele que cedo me buscar achar-me-á e não será abandonado."},{"verse":84,"text":"Portanto, permanecei e trabalhai diligentemente, a fim de que sejais aperfeiçoados em vosso ministério, para irdes aos gentios pela última vez — todos os que a boca do Senhor nomear — com o fim de ligar a lei e selar o testemunho e preparar os santos para a hora do julgamento que está para vir;"},{"verse":85,"text":"Para que suas almas escapem à ira de Deus, a ruína da abominação que espera os iníquos, tanto neste mundo como no mundo futuro. Em verdade vos digo que aqueles que não são os primeiros élderes continuem na vinha até que a boca do Senhor os chame, porque ainda não é chegada a sua hora; suas vestes não estão limpas do sangue desta geração."},{"verse":86,"text":"Permanecei na liberdade que vos faz livres; não vos embaraceis no pecado, mas que se conservem limpas as vossas mãos até que venha o Senhor."},{"verse":87,"text":"Pois em pouco tempo a Terra estremecerá e cambaleará de um lado para outro, como um homem embriagado; e o sol esconderá sua face e recusará sua luz; e a lua será banhada em sangue; e as estrelas tornar-se-ão muito zangadas e lançar-se-ão para baixo como o figo que cai de uma figueira."},{"verse":88,"text":"E depois de vosso testemunho vêm ira e indignação sobre o povo."},{"verse":89,"text":"Pois depois de vosso testemunho vem o testemunho de terremotos, que farão gemer a Terra em seu âmago; e homens cairão por terra e não poderão ficar de pé."},{"verse":90,"text":"E vem também o testemunho da voz de trovões e da voz de relâmpagos e da voz de tempestades e da voz das ondas do mar, arremessando-se além de seus limites."},{"verse":91,"text":"E todas as coisas estarão tumultuadas; e certamente o coração dos homens lhes falhará; pois o temor tomará conta de todos."},{"verse":92,"text":"E anjos voarão pelo meio do céu, clamando em alta voz, soando a trombeta de Deus, dizendo: Preparai-vos, preparai-vos, ó habitantes da Terra; pois é chegado o julgamento do nosso Deus. Eis que vem o Esposo; saí para encontrá-lo."},{"verse":93,"text":"E imediatamente aparecerá um grande sinal no céu e todo o povo o verá juntamente."},{"verse":94,"text":"E outro anjo soará sua trombeta, dizendo: Aquela grande igreja, a mãe das abominações, que fez com que todas as nações bebessem do vinho da ira de sua fornicação, que persegue os santos de Deus, que derramou seu sangue — aquela que se assenta sobre muitas águas e sobre as ilhas do mar — eis que ela é o joio da Terra; está amarrada em feixes; seus laços são fortalecidos, nenhum homem os pode desatar; portanto, está pronta para ser queimada. E ele soará sua trombeta longa e fortemente; e todas as nações a ouvirão."},{"verse":95,"text":"E haverá silêncio no céu pelo espaço de meia hora; e imediatamente depois a cortina do céu se desenrolará, como um rolo se desenrola depois de ter sido enrolado, e a face do Senhor será revelada;"},{"verse":96,"text":"E os santos que estiverem na Terra, que estiverem vivos, serão vivificados e arrebatados para encontrá-lo."},{"verse":97,"text":"E os que tiverem dormido em sua sepultura se levantarão, pois a sua cova será aberta; e eles também serão arrebatados para encontrá-lo no meio do pilar do céu —"},{"verse":98,"text":"Eles são de Cristo, as primícias, os que descerão com ele primeiro, e os que estão na Terra e em suas sepulturas, que serão os primeiros a serem arrebatados para encontrá-lo; e tudo isto pela voz do soar da trombeta do anjo de Deus."},{"verse":99,"text":"E depois disto um outro anjo soará, que é a segunda trombeta; e então virá a redenção daqueles que forem de Cristo na sua vinda; os que receberam sua parte naquela prisão preparada para eles, a fim de receberem o evangelho e serem julgados de acordo com os homens na carne."},{"verse":100,"text":"E também uma outra trombeta soará, que é a terceira trombeta; e então virão os espíritos de homens que deverão ser julgados e que se encontram sob condenação;"},{"verse":101,"text":"E esses são os remanescentes dos mortos; e não tornarão a viver até que os mil anos se acabem, nem até o fim da Terra."},{"verse":102,"text":"E uma outra trombeta soará, que é a quarta trombeta, dizendo: Entre os que hão de permanecer até o grande e último dia, sim, o fim, acham-se aqueles que hão de permanecer imundos ainda."},{"verse":103,"text":"E uma outra trombeta soará, que é a quinta trombeta, que é o quinto anjo que, voando no meio do céu, entrega o evangelho eterno a todas as nações, tribos, línguas e povos;"},{"verse":104,"text":"E esse será o som de sua trombeta, falando a todos, tanto no céu como na Terra e aos que estão debaixo da Terra; pois todo ouvido o ouvirá e todo joelho se dobrará e toda língua confessará, ao ouvirem eles o som da trombeta, dizendo: Temei a Deus e dai glória a ele, que se assenta em seu trono para todo o sempre; pois chegada é a hora de seu juízo."},{"verse":105,"text":"E também outro anjo, que é o sexto anjo, soará sua trombeta, dizendo: Caiu aquela que fez com que todas as nações bebessem do vinho da ira de sua fornicação; ela caiu, caiu!"},{"verse":106,"text":"E também outro anjo, que é o sétimo anjo, soará sua trombeta, dizendo: Está consumado, está consumado! O Cordeiro de Deus venceu e sozinho pisou o lagar, sim, o lagar do furor da ira do Deus Todo-Poderoso."},{"verse":107,"text":"E então os anjos serão coroados com a glória de seu poder e os santos encher-se-ão com sua glória e receberão sua herança e serão igualados a ele."},{"verse":108,"text":"E então o primeiro anjo tornará a soar sua trombeta aos ouvidos de todos os viventes e revelará os atos secretos dos homens e as obras grandiosas de Deus no primeiro milênio."},{"verse":109,"text":"E então o segundo anjo soará sua trombeta e revelará os atos secretos dos homens, e os pensamentos e intentos de seu coração, e as obras grandiosas de Deus no segundo milênio —"},{"verse":110,"text":"E assim por diante, até que o sétimo anjo soe sua trombeta; e ele colocar-se-á sobre a terra e sobre o mar e jurará, pelo nome daquele que se assenta em seu trono, que o tempo já não existe; e Satanás, aquela velha serpente que é chamada diabo, será amarrado e não será solto pelo espaço de mil anos."},{"verse":111,"text":"E então será solto por algum tempo a fim de reunir seus exércitos."},{"verse":112,"text":"E Miguel, o sétimo anjo, sim, o arcanjo, reunirá seus exércitos, sim, as hostes dos céus."},{"verse":113,"text":"E o diabo reunirá seus exércitos; sim, as hostes do inferno, e subirá para batalhar contra Miguel e seus exércitos."},{"verse":114,"text":"E então vem a batalha do grande Deus; e o diabo e seus exércitos serão arremessados em seu próprio lugar para que já não tenham poder sobre os santos."},{"verse":115,"text":"Porque Miguel lutará as batalhas deles e vencerá aquele que busca o trono do que se assenta no trono, sim, o Cordeiro."},{"verse":116,"text":"Esta é a glória de Deus e dos santificados; e eles já não verão a morte."},{"verse":117,"text":"Portanto, em verdade vos digo, meus amigos: Convocai vossa assembleia solene, como vos ordenei."},{"verse":118,"text":"E como nem todos têm fé, buscai diligentemente e ensinai-vos uns aos outros palavras de sabedoria; sim, nos melhores livros buscai palavras de sabedoria; procurai conhecimento, sim, pelo estudo e também pela fé."},{"verse":119,"text":"Organizai-vos; preparai todas as coisas necessárias e estabelecei uma casa, sim, uma casa de oração, uma casa de jejum, uma casa de fé, uma casa de aprendizado, uma casa de glória, uma casa de ordem, uma casa de Deus."},{"verse":120,"text":"Para que nela entreis em nome do Senhor; para que dela saiais em nome do Senhor; para que todas as vossas saudações sejam em nome do Senhor, com mãos elevadas ao Altíssimo."},{"verse":121,"text":"Portanto, cessai todas as vossas conversas levianas, todo riso, todas as vossas concupiscências, todo orgulho e frivolidade e todas as vossas ações iníquas."},{"verse":122,"text":"Dentre vós designai um professor e não falem todos ao mesmo tempo; mas cada um fale a seu tempo e todos ouçam suas palavras, para que quando todos houverem falado, todos sejam edificados por todos, para que todos tenham privilégios iguais."},{"verse":123,"text":"Vede que vos ameis uns aos outros; cessai de ser cobiçosos; aprendei a repartir uns com os outros, como requer o evangelho."},{"verse":124,"text":"Cessai de ser ociosos; cessai de ser impuros; cessai de achar faltas uns nos outros; cessai de dormir mais do que o necessário; recolhei-vos cedo, para que não vos canseis; levantai-vos cedo, para que vosso corpo e vossa mente sejam fortalecidos."},{"verse":125,"text":"E sobretudo, como que com um manto, revesti-vos do vínculo da caridade, que é o vínculo da perfeição e paz."},{"verse":126,"text":"Orai sempre, para que não desfaleçais, até que eu venha. Eis que depressa venho e vos receberei para mim mesmo. Amém."},{"verse":127,"text":"E também, a ordem da casa preparada para a presidência da escola dos profetas, estabelecida para sua instrução em todas as coisas que lhes convém, sim, para todos os oficiais da igreja ou, em outras palavras, os que são chamados para o ministério da igreja, a começar pelos sumos sacerdotes, até os diáconos —"},{"verse":128,"text":"E esta será a ordem da casa da presidência da escola: Aquele que for designado para presidente ou professor deverá estar em seu lugar, na casa que lhe será preparada."},{"verse":129,"text":"Portanto, será o primeiro na casa de Deus, num lugar em que a congregação da casa possa ouvir-lhe as palavras atenta e distintamente, sem que ele tenha de falar alto."},{"verse":130,"text":"E quando ele entrar na casa de Deus, pois deverá ser o primeiro a chegar — eis que isto é belo, para que ele sirva de exemplo —"},{"verse":131,"text":"Que se ofereça a si mesmo em oração, de joelhos perante Deus, em sinal ou lembrança do convênio eterno."},{"verse":132,"text":"E quando alguém entrar depois dele, que o professor se levante e, com mãos elevadas aos céus, sim, diretamente, saúde seu irmão ou irmãos com estas palavras:"},{"verse":133,"text":"És irmão ou sois irmãos? Saúdo-vos em nome do Senhor Jesus Cristo, em sinal ou lembrança do convênio eterno, convênio esse no qual vos recebo na fraternidade, com a determinação fixa, inamovível e imutável de ser vosso amigo e irmão pela graça de Deus, nos laços do amor, para caminhar em todos os mandamentos de Deus, imaculado, com ação de graças, para todo o sempre. Amém."},{"verse":134,"text":"E o que for considerado indigno desta saudação não terá lugar entre vós; porque não permitireis que minha casa seja por ele contaminada."},{"verse":135,"text":"E aquele que entrar e for fiel perante mim e for um irmão, ou se forem irmãos, saudarão o presidente ou professor com mãos elevadas ao céu, com essa mesma oração e convênio, ou dizendo Amém em sinal de acordo."},{"verse":136,"text":"Eis que em verdade vos digo: Isto vos é um exemplo de saudação na casa de Deus, na escola dos profetas."},{"verse":137,"text":"E sois chamados para fazer isso por meio de oração e ação de graças, como o Espírito vos levará a dizer em tudo o que fizerdes na casa do Senhor, na escola dos profetas, para que ela se torne um santuário, um tabernáculo do Santo Espírito para vossa edificação."},{"verse":138,"text":"E a ninguém recebereis entre vós nessa escola, a não ser que esteja limpo do sangue desta geração;"},{"verse":139,"text":"E ele será recebido pela ordenança do lava-pés, pois para esse fim foi instituída a ordenança do lava-pés."},{"verse":140,"text":"E também, a ordenança do lava-pés deve ser administrada pelo presidente, ou seja, o élder presidente da igreja."},{"verse":141,"text":"Deverá começar com oração; e depois de participar do pão e do vinho, ele deverá cingir-se de acordo com o modelo dado no décimo terceiro capítulo do testemunho de João concernente a mim. Amém."}]},{"chapter":89,"verses":[{"verse":1,"text":"Uma Palavra de Sabedoria, para o benefício do conselho de sumos sacerdotes, reunido em Kirtland, e da igreja e também dos santos de Sião —"},{"verse":2,"text":"Para ser enviada como saudação; não como mandamento ou coerção, mas como revelação e palavra de sabedoria, manifestando a ordem e a vontade de Deus quanto à salvação física de todos os santos nos últimos dias —"},{"verse":3,"text":"Dada como princípio com promessa, adaptada à capacidade dos fracos e do mais fraco de todos os santos, que são ou podem ser chamados santos."},{"verse":4,"text":"Eis que, em verdade, assim vos diz o Senhor: Devido a maldades e desígnios que existem e virão a existir no coração de homens conspiradores nos últimos dias, eu vos adverti e previno-vos, dando-vos esta palavra de sabedoria por revelação —"},{"verse":5,"text":"Eis que não é bom nem aceitável aos olhos de vosso Pai que alguém entre vós tome vinho ou bebida forte, exceto quando vos reunis para oferecer vossos sacramentos perante ele."},{"verse":6,"text":"E eis que deve ser vinho, sim, vinho puro de uva da videira, de vossa própria fabricação."},{"verse":7,"text":"E também bebidas fortes não são para o ventre, mas para lavar vosso corpo."},{"verse":8,"text":"E também tabaco não é para o corpo nem para o ventre e não é bom para o homem, mas é uma erva para machucaduras e todo gado doente, a qual se deve usar com discernimento e habilidade."},{"verse":9,"text":"E também bebidas quentes não são para o corpo nem para o ventre."},{"verse":10,"text":"E também em verdade vos digo: Todas as ervas salutares indicou Deus para a constituição, natureza e uso do homem —"},{"verse":11,"text":"Toda erva em sua estação e toda fruta em sua estação; todas essas para serem usadas com prudência e ação de graças."},{"verse":12,"text":"Sim, também a carne de animais e a das aves do ar, eu, o Senhor, indiquei para uso do homem, com gratidão; contudo, devem ser usadas moderadamente;"},{"verse":13,"text":"Agrada-me que não sejam usadas a não ser no inverno ou em tempos de frio ou de fome."},{"verse":14,"text":"Todos os grãos são indicados para uso do homem e dos animais, para ser o esteio da vida, não só para o homem, mas também para os animais do campo e as aves do céu e todos os animais selvagens que correm ou rastejam na terra;"},{"verse":15,"text":"E estes fez Deus para uso do homem apenas em épocas de escassez ou fome excessiva."},{"verse":16,"text":"Todos os grãos são bons para alimento do homem, como também o fruto da videira; aquilo que produz fruto, seja na terra ou acima da terra —"},{"verse":17,"text":"Contudo, o trigo para o homem e o milho para o boi e a aveia para o cavalo e o centeio para as aves e os porcos e para todos os animais do campo; e a cevada para todos os animais úteis e para bebidas suaves, como também outros grãos."},{"verse":18,"text":"E todos os santos que se lembrarem de guardar e fazer estas coisas, obedecendo aos mandamentos, receberão saúde para o umbigo e medula para os ossos;"},{"verse":19,"text":"E encontrarão sabedoria e grandes tesouros de conhecimento, sim, tesouros ocultos;"},{"verse":20,"text":"E correrão e não se cansarão; e caminharão e não desfalecerão."},{"verse":21,"text":"E eu, o Senhor, faço-lhes uma promessa de que o anjo destruidor passará por eles, como os filhos de Israel, e não os matará. Amém."}]},{"chapter":90,"verses":[{"verse":1,"text":"Assim diz o Senhor: Em verdade, em verdade te digo, meu filho, que teus pecados te são perdoados, de acordo com teu pedido, pois tuas orações e as orações de teus irmãos subiram a meus ouvidos."},{"verse":2,"text":"Portanto, serás abençoado, daqui em diante, tu que possuis as chaves do reino que te foram dadas; reino esse que está surgindo pela última vez."},{"verse":3,"text":"Em verdade te digo: As chaves deste reino jamais te serão tomadas, enquanto estiveres no mundo; tampouco no mundo vindouro;"},{"verse":4,"text":"Contudo, por teu intermédio os oráculos serão dados a um outro, sim, à igreja."},{"verse":5,"text":"E todos os que receberem os oráculos de Deus, que se acautelem de como os consideram, para que não os menosprezem e se ponham, assim, sob condenação e tropecem e caiam quando descerem as tempestades e assoprarem os ventos e caírem as chuvas e baterem contra sua casa."},{"verse":6,"text":"E também, em verdade eu digo a teus irmãos, Sidney Rigdon e Frederick G. Williams, que perdoados também lhes são os seus pecados; e eles são considerados iguais a ti na posse das chaves deste último reino;"},{"verse":7,"text":"Como também, pela tua administração, das chaves da escola dos profetas, que ordenei ser organizada;"},{"verse":8,"text":"Para que, dessa forma, sejam aperfeiçoados em seu ministério, para a salvação de Sião e das nações de Israel e dos gentios, todos os que crerem;"},{"verse":9,"text":"Para que, pela tua administração, recebam a palavra; e pela administração deles, a palavra chegue aos confins da Terra, primeiro aos gentios e, depois, eis que se voltarão para os judeus."},{"verse":10,"text":"E então virá o dia em que o braço do Senhor se revelará em poder, para convencer as nações, as nações pagãs, a casa de José, do evangelho de sua salvação."},{"verse":11,"text":"Pois acontecerá nesse dia que todo homem ouvirá a plenitude do evangelho em sua própria língua e em seu próprio idioma, por meio daqueles que são ordenados com esse poder, pela administração do Consolador que se derrama sobre eles para revelar Jesus Cristo."},{"verse":12,"text":"E agora, em verdade eu te digo: Dou-te o mandamento de que continues no ministério e na presidência."},{"verse":13,"text":"E quando tiveres terminado a tradução dos profetas, presidirás, daí em diante, os negócios da igreja e da escola;"},{"verse":14,"text":"E de tempos em tempos, conforme for manifestado pelo Consolador, receberás revelações para desvendar os mistérios do reino;"},{"verse":15,"text":"E porás em ordem as igrejas; e estudarás e aprenderás e familiarizar-te-ás com todos os bons livros e com línguas, idiomas e povos."},{"verse":16,"text":"E esta será vossa ocupação e missão por toda a vida: Presidir os conselhos e pôr em ordem todos os negócios desta igreja e reino."},{"verse":17,"text":"Não vos envergonheis nem vos confundais; mas sede admoestados em vossa altivez e orgulho, porque são uma armadilha para vossa alma."},{"verse":18,"text":"Ponde em ordem vossa casa; afastai de vós a indolência e a impureza."},{"verse":19,"text":"Agora, em verdade te digo: Providencie-se um lugar, logo que possível, para a família de teu conselheiro e escriba, Frederick G. Williams."},{"verse":20,"text":"E que o meu servo idoso, Joseph Smith Sênior, continue com a sua família no lugar onde mora atualmente; e que o local não seja vendido até que a boca do Senhor o determine."},{"verse":21,"text":"E que o meu conselheiro Sidney Rigdon permaneça onde agora reside, até que a boca do Senhor o determine."},{"verse":22,"text":"E que o bispo procure zelosamente conseguir um agente e que seja ele um homem que tenha riquezas em reserva — um homem de Deus e forte na fé —"},{"verse":23,"text":"Para que assim pague todas as dívidas, a fim de que o armazém do Senhor não caia em descrédito aos olhos do povo."},{"verse":24,"text":"Buscai diligentemente, orai sempre e sede crentes; e todas as coisas contribuirão para o vosso bem, se andardes retamente e vos lembrardes do convênio que fizestes uns com os outros."},{"verse":25,"text":"Que a vossa família seja pequena, especialmente a do meu servo idoso Joseph Smith Sênior, no que se refere aos que não pertencem à vossa família;"},{"verse":26,"text":"A fim de que as coisas que vos são supridas, para realizar minha obra, não sejam tomadas de vós e dadas a quem não é digno —"},{"verse":27,"text":"E sejais, assim, impedidos de realizar as coisas que vos mandei."},{"verse":28,"text":"E também, em verdade vos digo: Desejo que minha serva Vienna Jaques receba dinheiro para pagar suas despesas e suba para a terra de Sião;"},{"verse":29,"text":"E o restante do dinheiro seja consagrado a mim; e ela seja recompensada em meu próprio e devido tempo."},{"verse":30,"text":"Em verdade vos digo que, a meu ver, é conveniente que ela suba para a terra de Sião e receba uma herança da mão do bispo;"},{"verse":31,"text":"Para que se estabeleça em paz, se for fiel, e não fique ociosa daí em diante."},{"verse":32,"text":"E eis que em verdade vos digo, que deveis escrever esse mandamento e dizer a vossos irmãos de Sião, com saudação amorosa, que também vos chamei para presidir Sião, em meu próprio e devido tempo."},{"verse":33,"text":"Portanto, que cessem de importunar-me com esse assunto."},{"verse":34,"text":"Eis que vos digo que vossos irmãos de Sião começam a arrepender-se e os anjos regozijam-se por causa deles."},{"verse":35,"text":"Contudo, não estou satisfeito com muitas coisas; e não estou satisfeito com meu servo William E. McLellin nem com meu servo Sidney Gilbert; e também o bispo e outros têm muito de que se arrepender."},{"verse":36,"text":"Mas em verdade vos digo que eu, o Senhor, contenderei com Sião e argumentarei com seus fortes e castigá-la-ei até que vença e fique limpa perante mim."},{"verse":37,"text":"Pois ela não será removida de seu lugar. Eu, o Senhor, disse-o. Amém."}]},{"chapter":91,"verses":[{"verse":1,"text":"Em verdade, assim vos diz o Senhor com referência aos Apócrifos: Há muitas coisas neles que são verdadeiras e estão, na maior parte, traduzidas corretamente."},{"verse":2,"text":"Há muitas coisas neles que não são verdadeiras, que são acréscimos feitos pelas mãos de homens."},{"verse":3,"text":"Em verdade vos digo que não é necessário que se traduzam os Apócrifos."},{"verse":4,"text":"Portanto, aquele que os ler que compreenda, pois o Espírito manifesta a verdade;"},{"verse":5,"text":"E aquele que for iluminado pelo Espírito se beneficiará com eles;"},{"verse":6,"text":"E aquele que não receber pelo Espírito não poderá ser beneficiado. Portanto, não é necessário que sejam traduzidos. Amém."}]},{"chapter":92,"verses":[{"verse":1,"text":"Em verdade assim diz o Senhor: Dou à ordem unida, organizada conforme o mandamento previamente dado, uma revelação e mandamento, com referência a meu servo Frederick G. Williams, de que o recebais na ordem. O que digo a um digo a todos."},{"verse":2,"text":"E também te digo, meu servo Frederick G. Williams: Serás um membro ativo nessa ordem; e se fores fiel na obediência a todos os mandamentos anteriores, serás abençoado para sempre. Amém."}]},{"chapter":93,"verses":[{"verse":1,"text":"Em verdade, assim diz o Senhor: Acontecerá que toda alma que abandonar os seus pecados e vier a mim, e invocar o meu nome, e obedecer à minha voz, e guardar os meus mandamentos verá a minha face e saberá que eu sou;"},{"verse":2,"text":"E que eu sou a verdadeira luz que ilumina todo homem que vem ao mundo;"},{"verse":3,"text":"E que eu estou no Pai e o Pai em mim; e o Pai e eu somos um —"},{"verse":4,"text":"O Pai, porque me deu de sua plenitude, e o Filho, porque estive no mundo e fiz da carne meu tabernáculo e habitei entre os filhos dos homens."},{"verse":5,"text":"E estive no mundo e recebi de meu Pai; e as obras dele foram claramente manifestadas."},{"verse":6,"text":"E João viu e testificou a plenitude de minha glória; e a plenitude do testemunho de João será revelada posteriormente."},{"verse":7,"text":"E ele testificou, dizendo: Vi sua glória, que ele era no princípio, antes de o mundo existir;"},{"verse":8,"text":"Portanto, no princípio era o Verbo, pois ele era o Verbo, sim, o mensageiro da salvação —"},{"verse":9,"text":"A luz e o Redentor do mundo; o Espírito da verdade, que veio ao mundo, porque o mundo foi feito por ele e nele estava a vida dos homens e a luz dos homens."},{"verse":10,"text":"Os mundos foram feitos por ele; os homens foram feitos por ele; todas as coisas foram feitas por ele e por meio dele e dele."},{"verse":11,"text":"E eu, João, testifico que contemplei sua glória, como a glória do Unigênito do Pai, cheio de graça e verdade, sim, o Espírito da verdade, que veio e habitou na carne e habitou entre nós."},{"verse":12,"text":"E eu, João, vi que no princípio ele não recebeu da plenitude, mas recebeu graça por graça;"},{"verse":13,"text":"E a princípio não recebeu da plenitude, mas continuou de graça em graça, até receber a plenitude;"},{"verse":14,"text":"E assim foi chamado de Filho de Deus, porque não recebeu da plenitude no princípio."},{"verse":15,"text":"E eu, João, testifico e eis que se abriram os céus e o Espírito Santo desceu sobre ele, na forma de uma pomba, e pousou nele; e do céu ouviu-se uma voz que dizia: Este é meu Filho amado."},{"verse":16,"text":"E eu, João, testifico que ele recebeu a plenitude da glória do Pai;"},{"verse":17,"text":"E recebeu todo o poder, tanto nos céus como na Terra; e a glória do Pai estava com ele, porque ele habitava nele."},{"verse":18,"text":"E acontecerá que, se fordes fiéis, recebereis a plenitude do testemunho de João."},{"verse":19,"text":"E dou-vos estas palavras, para compreenderdes e saberdes como adorar e saberdes o que adorais, para que venhais ao Pai em meu nome e, no devido tempo, recebais de sua plenitude."},{"verse":20,"text":"Porque, se guardardes meus mandamentos, recebereis de sua plenitude e sereis glorificados em mim como eu o sou no Pai; portanto, digo-vos: Recebereis graça por graça."},{"verse":21,"text":"E agora, em verdade vos digo: Eu estava no princípio com o Pai e sou o Primogênito;"},{"verse":22,"text":"E todos os que são gerados por meu intermédio são participantes da mesma glória e são a igreja do Primogênito."},{"verse":23,"text":"Vós também no princípio estáveis com o Pai; aquilo que é Espírito, sim, o Espírito da verdade;"},{"verse":24,"text":"E a verdade é o conhecimento das coisas como são, como foram e como serão;"},{"verse":25,"text":"E o que for mais ou menos do que isto é o espírito daquele ser iníquo que é um mentiroso desde o princípio."},{"verse":26,"text":"O Espírito da verdade é de Deus. Eu sou o Espírito da verdade e João prestou testemunho de mim, dizendo: Ele recebeu a plenitude da verdade, sim, de toda verdade;"},{"verse":27,"text":"E homem algum recebe a plenitude a não ser que guarde seus mandamentos."},{"verse":28,"text":"Aquele que guarda seus mandamentos recebe verdade e luz, até ser glorificado na verdade e conhecer todas as coisas."},{"verse":29,"text":"O homem também estava no princípio com Deus. A inteligência, ou seja, a luz da verdade, não foi criada nem feita nem verdadeiramente pode sê-lo."},{"verse":30,"text":"Toda verdade é independente para agir por si mesma na esfera em que Deus a colocou, como também toda inteligência; caso contrário, não há existência."},{"verse":31,"text":"Eis que isto é o livre-arbítrio do homem e isto é a condenação do homem; porque aquilo que foi desde o princípio lhes é claramente manifestado e eles não recebem a luz."},{"verse":32,"text":"E todo homem cujo espírito não recebe a luz está sob condenação."},{"verse":33,"text":"Pois o homem é espírito. Os elementos são eternos, e espírito e elemento, inseparavelmente ligados, recebem a plenitude da alegria;"},{"verse":34,"text":"E, quando separados, não pode o homem receber a plenitude da alegria."},{"verse":35,"text":"Os elementos são o tabernáculo de Deus; sim, o homem é o tabernáculo de Deus, ou melhor, templos; e qualquer templo que for profanado, Deus destruirá esse templo."},{"verse":36,"text":"A glória de Deus é inteligência ou, em outras palavras, luz e verdade."},{"verse":37,"text":"A luz e a verdade rejeitam o ser maligno."},{"verse":38,"text":"Todo espírito de homem era inocente no princípio; e Deus, tendo redimido o homem da queda, os homens tornaram-se outra vez, em sua infância, inocentes perante Deus."},{"verse":39,"text":"E vem o ser maligno e tira a luz e a verdade dos filhos dos homens pela desobediência e por causa da tradição de seus pais."},{"verse":40,"text":"Eu, porém, ordenei que criásseis vossos filhos em luz e verdade."},{"verse":41,"text":"Mas em verdade, meu servo Frederick G. Williams, digo-te: Continuas sob esta condenação;"},{"verse":42,"text":"Não ensinaste luz e verdade a teus filhos, segundo os mandamentos; e aquele ser maligno ainda tem poder sobre ti, sendo essa a causa de tua aflição."},{"verse":43,"text":"E agora te dou um mandamento: Se quiseres ser libertado, terás que pôr em ordem tua própria casa, porque há muitas coisas que não estão certas em tua casa."},{"verse":44,"text":"Em verdade eu digo a meu servo Sidney Rigdon que, em algumas coisas, ele não guardou os mandamentos concernentes a seus filhos; portanto, que primeiro ponha em ordem sua casa."},{"verse":45,"text":"Em verdade eu digo a meu servo Joseph Smith Júnior ou, em outras palavras, chamar-vos-ei de amigos, porque sois meus amigos e tereis uma herança comigo —"},{"verse":46,"text":"Chamei-vos de servos por causa do mundo e vós sois seus servos por minha causa —"},{"verse":47,"text":"E agora, em verdade eu te digo, Joseph Smith Júnior: Tu não guardaste os mandamentos e necessário é que sejas repreendido perante o Senhor."},{"verse":48,"text":"A tua família precisa arrepender-se e abandonar certas coisas, e prestar mais atenção às tuas palavras; caso contrário, será removida de seu lugar."},{"verse":49,"text":"O que digo a um digo a todos; orai sempre, para que o ser maligno não tenha poder em vós e não vos remova de vosso lugar."},{"verse":50,"text":"Também o meu servo Newel K. Whitney, bispo da minha igreja, precisa ser castigado e pôr em ordem sua família; e fazer com que sejam mais diligentes e interessados em casa e orem sempre; caso contrário serão removidos de seu lugar."},{"verse":51,"text":"Agora vos digo, meus amigos: Que meu servo Sidney Rigdon faça sua viagem rapidamente e proclame também o ano aceitável do Senhor e o evangelho de salvação, conforme as palavras que eu lhe inspirar; e pela oração unânime de vossa fé, sustentá-lo-ei."},{"verse":52,"text":"E que meus servos Joseph Smith Júnior e Frederick G. Williams também se apressem; e ser-lhes-á dado de acordo com a oração da fé; e se guardardes minhas palavras, não sereis confundidos neste mundo nem no mundo vindouro."},{"verse":53,"text":"E em verdade vos digo que é a minha vontade que vos apresseis em traduzir as minhas escrituras, e em obter um conhecimento de história, e de países, e de reinos, de leis de Deus e do homem; e tudo isso para a salvação de Sião. Amém."}]},{"chapter":94,"verses":[{"verse":1,"text":"E também, em verdade vos digo, meus amigos: Um mandamento vos dou, de que comeceis a projetar e preparar o início e o alicerce da cidade da estaca de Sião, aqui na terra de Kirtland, começando pela minha casa."},{"verse":2,"text":"E eis que isso deverá ser feito de acordo com o modelo que vos dei."},{"verse":3,"text":"E que o primeiro terreno no sul me seja consagrado para a construção de uma casa para a presidência, para o trabalho da presidência de receber revelações; e para o trabalho do ministério da presidência, em todas as coisas concernentes à igreja e reino."},{"verse":4,"text":"Em verdade vos digo que deverá medir cinquenta e cinco pés de largura por sessenta e cinco de comprimento, na área interna."},{"verse":5,"text":"E haverá um andar inferior e um andar superior, de acordo com o modelo que vos será dado."},{"verse":6,"text":"E será dedicada ao Senhor desde seu alicerce, segundo a ordem do sacerdócio, segundo o modelo que vos será dado posteriormente."},{"verse":7,"text":"E será inteiramente dedicada ao Senhor para o trabalho da presidência."},{"verse":8,"text":"E não permitireis que qualquer coisa impura entre nela; e minha glória lá estará e minha presença lá estará."},{"verse":9,"text":"Mas se alguma coisa impura nela entrar, minha glória não estará lá; e minha presença lá não entrará."},{"verse":10,"text":"E também, em verdade vos digo: O segundo terreno no sul ser-me-á dedicado para a construção de uma casa para mim, a fim de imprimir-se a tradução de minhas escrituras e todas as coisas que eu vos ordenar."},{"verse":11,"text":"E terá cinquenta e cinco pés de largura por sessenta e cinco de comprimento, na área interna; e haverá um andar inferior e um andar superior."},{"verse":12,"text":"E esta casa será inteiramente dedicada ao Senhor desde seu alicerce, para o trabalho de impressão, em todas as coisas que eu vos ordenar; para ser santa, imaculada, segundo o modelo de todas as coisas, que vos será dado."},{"verse":13,"text":"E no terceiro terreno meu servo Hyrum Smith receberá sua herança."},{"verse":14,"text":"E no primeiro terreno e no segundo terreno, no norte, meus servos Reynolds Cahoon e Jared Carter receberão suas heranças —"},{"verse":15,"text":"Para que façam o trabalho que lhes designei, de serem o comitê responsável pela construção de minhas casas, de acordo com o mandamento que eu, o Senhor Deus, vos dei."},{"verse":16,"text":"Estas duas casas não deverão ser construídas até que eu vos dê um mandamento concernente a elas."},{"verse":17,"text":"E agora nada mais vos dou neste momento. Amém."}]},{"chapter":95,"verses":[{"verse":1,"text":"Em verdade assim diz o Senhor a vós, a quem amo; e a quem amo também castigo, para que seus pecados sejam perdoados, pois com o castigo preparo um meio para livrá-los da tentação em todas as coisas; e eu vos amo —"},{"verse":2,"text":"É necessário, portanto, que sejais castigados e repreendidos perante minha face;"},{"verse":3,"text":"Porque pecastes contra mim com um grave pecado, não tendo considerado, em todas as coisas, o grande mandamento que vos dei concernente à construção de minha casa;"},{"verse":4,"text":"Para a preparação com a qual tenciono preparar meus apóstolos para podarem minha vinha pela última vez, para que eu execute meu estranho ato, para que eu derrame o meu espírito sobre toda carne —"},{"verse":5,"text":"Mas eis que em verdade vos digo que há muitos entre vós que chamei e foram ordenados, mas poucos deles são escolhidos."},{"verse":6,"text":"Os que não são escolhidos pecaram gravemente, pois andam em trevas ao meio-dia."},{"verse":7,"text":"E por essa razão vos dei o mandamento de convocardes uma assembleia solene, para que vossos jejuns e vosso pranto subam aos ouvidos do Senhor de Sabaote que, por interpretação, significa o criador do primeiro dia, o princípio e o fim."},{"verse":8,"text":"Sim, em verdade vos digo: Dei-vos o mandamento de construirdes uma casa, onde tenciono investir os que escolhi com poder do alto;"},{"verse":9,"text":"Pois essa é a promessa do Pai a vós; portanto, ordeno que permaneçais, sim, como ordenei a meus apóstolos de Jerusalém."},{"verse":10,"text":"Contudo, meus servos pecaram com um gravíssimo pecado; e surgiram contendas na escola dos profetas, o que me foi muito penoso, diz vosso Senhor; portanto, enviei-os para serem castigados."},{"verse":11,"text":"Em verdade vos digo: É meu desejo que construais uma casa. Se guardardes meus mandamentos, tereis poder para construí-la."},{"verse":12,"text":"Se não guardardes meus mandamentos, o amor do Pai não continuará convosco; portanto, andareis em trevas."},{"verse":13,"text":"Ora, eis aqui sabedoria e a mente do Senhor: Que a casa seja construída, não segundo a maneira do mundo, pois não desejo que vivais segundo a maneira do mundo;"},{"verse":14,"text":"Portanto, que seja construída segundo a maneira que mostrarei a três de vós, a quem indicareis e ordenareis com esse poder."},{"verse":15,"text":"E medirá cinquenta e cinco pés de largura por sessenta e cinco de comprimento, na área interna."},{"verse":16,"text":"E que o andar inferior da área interna seja dedicado a mim para oferta de vossos sacramentos e para vossas pregações e vossos jejuns e vossas orações e a oferta de vossos desejos mais santos a mim, diz vosso Senhor."},{"verse":17,"text":"E que a parte superior da área interna seja dedicada a mim como a escola de meus apóstolos, diz o Filho Amã; ou, em outras palavras, Alfus; ou, em outras palavras, Omegus; sim, Jesus Cristo, vosso Senhor. Amém."}]},{"chapter":96,"verses":[{"verse":1,"text":"Eis que vos digo: Aqui há sabedoria, para que saibais como agir em relação a esse assunto, pois me convém que esta estaca, que estabeleci para o vigor de Sião, se fortaleça."},{"verse":2,"text":"Portanto, que meu servo Newel K. Whitney se encarregue do lugar que haveis mencionado, no qual pretendo construir minha casa santa."},{"verse":3,"text":"E também, que seja dividida em lotes, com prudência, para o benefício daqueles que buscam heranças, como for determinado por vós em conselho."},{"verse":4,"text":"Portanto, não deixeis de cuidar deste assunto e da porção que é necessária para beneficiar a minha ordem, com o objetivo de levar minha palavra aos filhos dos homens."},{"verse":5,"text":"Pois eis que em verdade vos digo: Isto é o que mais me convém, que minha palavra chegue aos filhos dos homens, com o propósito de abrandar-lhes o coração para o vosso bem. Assim seja. Amém."},{"verse":6,"text":"E também em verdade vos digo que me é sábio e conveniente que meu servo John Johnson, cuja oferta aceitei e cujas orações ouvi, a quem dou a promessa de vida eterna se guardar meus mandamentos de agora em diante —"},{"verse":7,"text":"Porque ele é descendente de José e participante das bênçãos da promessa feita a seus pais —"},{"verse":8,"text":"Em verdade vos digo que me é conveniente que ele se torne membro da ordem, a fim de que ajude a levar minha palavra aos filhos dos homens."},{"verse":9,"text":"Portanto, ordená-lo-eis para essa bênção; e ele procurará zelosamente liquidar os encargos que pesam sobre a casa mencionada por vós, para que nela possa morar. Assim seja. Amém."}]},{"chapter":97,"verses":[{"verse":1,"text":"Em verdade vos digo, meus amigos: Falo-vos com a minha voz, sim, a voz de meu Espírito, a fim de mostrar-vos a minha vontade relativa a vossos irmãos da terra de Sião, muitos dos quais são verdadeiramente humildes e procuram zelosamente adquirir sabedoria e encontrar a verdade."},{"verse":2,"text":"Em verdade, em verdade vos digo: Bem-aventurados são eles, porque vencerão; pois eu, o Senhor, mostro misericórdia a todos os mansos e a todos os que eu quiser, para que eu seja justificado quando os levar a julgamento."},{"verse":3,"text":"Eis que vos digo, concernente à escola de Sião: Eu, o Senhor, estou satisfeito por haver uma escola em Sião; e também com meu servo Parley P. Pratt, pois ele permanece em mim."},{"verse":4,"text":"E enquanto perseverar em mim, continuará a presidir a escola da terra de Sião, até que eu lhe dê outros mandamentos."},{"verse":5,"text":"E abençoá-lo-ei com uma multiplicidade de bênçãos ao expor todas as escrituras e mistérios para a edificação da escola e da igreja em Sião."},{"verse":6,"text":"E para com o restante da escola eu, o Senhor, estou disposto a mostrar misericórdia; contudo, existem alguns que precisam ser repreendidos e suas obras tornar-se-ão conhecidas."},{"verse":7,"text":"Está posto o machado à raiz das árvores; e toda árvore que não produzir bons frutos será cortada e lançada no fogo. Eu, o Senhor, disse-o."},{"verse":8,"text":"Em verdade vos digo: Todos os que, dentre eles, souberem que seu coração é honesto e está quebrantado e seu espírito, contrito; e que estiverem dispostos a observar seus convênios por meio de sacrifício — sim, todo sacrifício que eu, o Senhor, ordenar — esses serão aceitos por mim."},{"verse":9,"text":"Pois eu, o Senhor, farei com que produzam como uma árvore muito frutífera, plantada em terra fértil junto a um riacho de água pura, que produz muitos frutos preciosos."},{"verse":10,"text":"Em verdade vos digo que é meu desejo que a mim se construa uma casa na terra de Sião, conforme o modelo que vos dei."},{"verse":11,"text":"Sim, que se construa rapidamente, com o dízimo de meu povo."},{"verse":12,"text":"Eis que este é o dízimo e o sacrifício que eu, o Senhor, exijo de suas mãos — que a mim se construa uma casa para a salvação de Sião —"},{"verse":13,"text":"Como um lugar de ação de graças para todos os santos e um lugar de instrução para todos aqueles que forem chamados ao trabalho do ministério, em todos os seus diversos chamados e ofícios;"},{"verse":14,"text":"Para que sejam aperfeiçoados no entendimento de seu ministério, em teoria, em princípio e em doutrina, em todas as coisas concernentes ao reino de Deus na Terra, cujas chaves vos foram conferidas."},{"verse":15,"text":"E se meu povo me construir uma casa em nome do Senhor e não permitir que nela entre qualquer coisa impura, de modo que não seja profanada, minha glória descansará sobre ela;"},{"verse":16,"text":"Sim, e minha presença lá estará, porque entrarei nela; e todos os puros de coração que nela entrarem verão a Deus."},{"verse":17,"text":"Mas se for profanada, não entrarei nela e minha glória lá não estará; porque não entrarei em templos impuros."},{"verse":18,"text":"E agora, eis que, se fizer estas coisas, Sião prosperará e esparramar-se-á e tornar-se-á muito gloriosa, muito grandiosa e muito terrível."},{"verse":19,"text":"E as nações da Terra honrá-la-ão e dirão: Certamente Sião é a cidade do nosso Deus e certamente Sião não pode cair nem ser removida de seu lugar, porque Deus lá está e a mão do Senhor ali está;"},{"verse":20,"text":"E ele jurou, pelo poder de sua força, ser a sua salvação e sua torre alta."},{"verse":21,"text":"Portanto, em verdade, assim diz o Senhor: Que Sião se regozije, pois isto é Sião — os puros de coração; portanto, que Sião se regozije enquanto se lamentam todos os iníquos."},{"verse":22,"text":"Pois eis que a vingança vem rapidamente sobre os ímpios, como um furacão; e quem dela escapará?"},{"verse":23,"text":"O açoite do Senhor passará de noite e de dia e seu rumor afligirá todos os povos; sim, não cessará até que venha o Senhor."},{"verse":24,"text":"Porque a indignação do Senhor está acesa contra as abominações deles e todas as suas obras iníquas."},{"verse":25,"text":"Não obstante, Sião escapará se procurar fazer todas as coisas que lhe ordenei."},{"verse":26,"text":"Mas se não procurar fazer todas as coisas que eu lhe ordenei, visitá-la-ei de acordo com todas as suas obras, com aflição dolorosa, com pestilência, com pragas, com a espada, com vingança, com fogo devorador."},{"verse":27,"text":"Contudo, que lhe seja lido esta vez aos ouvidos que eu, o Senhor, aceitei sua oferta; e se não mais pecar, nenhuma destas coisas lhe sobrevirá;"},{"verse":28,"text":"E abençoá-la-ei com bênçãos e multiplicarei sobre ela e sobre suas gerações uma multiplicidade de bênçãos para todo o sempre, diz o Senhor vosso Deus. Amém."}]},{"chapter":98,"verses":[{"verse":1,"text":"Em verdade vos digo, meus amigos: Não temais; que se console vosso coração; sim, regozijai-vos sempre e em tudo dai graças;"},{"verse":2,"text":"Esperando pacientemente no Senhor, porque vossas orações chegaram aos ouvidos do Senhor de Sabaote e estão registradas com este selo e testamento — o Senhor jurou e decretou que serão atendidas."},{"verse":3,"text":"Portanto, ele vos faz essa promessa, com um convênio imutável de que serão cumpridas; e todas as coisas que vos tiverem afligido reverterão para o vosso bem e para a glória do meu nome, diz o Senhor."},{"verse":4,"text":"E agora, em verdade vos digo com respeito às leis do país: É a minha vontade que o meu povo procure fazer todas as coisas que eu lhe mandar."},{"verse":5,"text":"E a lei do país, que for constitucional, que apoiar o princípio da liberdade na observância de direitos e privilégios, pertencerá a toda a humanidade e será justificável perante mim."},{"verse":6,"text":"Portanto, eu, o Senhor, vos justifico, vós e vossos irmãos de minha igreja, no apoio à lei que é a lei constitucional do país;"},{"verse":7,"text":"E quanto às leis dos homens, o que for mais ou menos do que isso provém do mal."},{"verse":8,"text":"Eu, o Senhor Deus, liberto-vos; portanto, sois verdadeiramente livres. E a lei também vos liberta."},{"verse":9,"text":"Mas quando os iníquos governam, o povo pranteia."},{"verse":10,"text":"Deve-se, portanto, procurar diligentemente homens honestos e homens sábios; e homens bons e homens sábios devereis apoiar; pois o que for menos do que isto provém do mal."},{"verse":11,"text":"E dou-vos o mandamento de renunciardes a todo mal e vos apegardes a todo o bem e viverdes por toda palavra que sai da boca de Deus."},{"verse":12,"text":"Pois ele dará ao fiel linha sobre linha, preceito sobre preceito; e com isso vos testarei e provarei."},{"verse":13,"text":"E quem perder a vida na minha causa, por amor a meu nome, tornará a encontrá-la, sim, a vida eterna."},{"verse":14,"text":"Portanto, não temais os vossos inimigos, pois decretei em meu coração, diz o Senhor, que vos provarei em todas as coisas, para ver se permanecereis no meu convênio, mesmo até a morte, para que sejais considerados dignos."},{"verse":15,"text":"Porque se não permanecerdes em meu convênio, não sereis dignos de mim."},{"verse":16,"text":"Portanto, renunciai à guerra e proclamai a paz; e procurai diligentemente voltar o coração dos filhos para os seus pais e o coração dos pais para os filhos;"},{"verse":17,"text":"E também o coração dos judeus para os profetas e os profetas para os judeus; para que eu não venha e fira toda a Terra com uma maldição e toda carne seja consumida diante de mim."},{"verse":18,"text":"Não se inquiete vosso coração, pois na casa de meu Pai há muitas moradas e preparar-vos-ei um lugar; e onde meu Pai e eu estivermos, ali estareis também."},{"verse":19,"text":"Eis que eu, o Senhor, não estou satisfeito com muitos da igreja de Kirtland;"},{"verse":20,"text":"Porque não abandonam seus pecados nem seus caminhos iníquos, o orgulho de seu coração, nem sua cobiça nem todas as suas coisas detestáveis; e não observam as palavras de sabedoria e vida eterna que lhes dei."},{"verse":21,"text":"Em verdade vos digo que eu, o Senhor, os castigarei e farei o que me aprouver, se eles não se arrependerem e observarem todas as coisas que eu lhes disse."},{"verse":22,"text":"E também vos digo: Se fizerdes o que vos ordeno, eu, o Senhor, desviarei de vós toda ira e indignação; e as portas do inferno não prevalecerão contra vós."},{"verse":23,"text":"Agora, falo-vos com respeito às vossas famílias: Se os homens vos ferirem ou às vossas famílias uma vez, e suportardes isso pacientemente, e não os injuriardes nem procurardes vingança, sereis recompensados;"},{"verse":24,"text":"Mas se não suportardes isso pacientemente, será considerado uma medida justa contra vós."},{"verse":25,"text":"E também, se vosso inimigo vos ferir a segunda vez e não injuriardes vosso inimigo e suportardes isso pacientemente, vossa recompensa será centuplicada."},{"verse":26,"text":"E também, se ele vos ferir a terceira vez e suportardes isso pacientemente, vossa recompensa será quatro vezes duplicada;"},{"verse":27,"text":"E estes três testemunhos levantar-se-ão contra vosso inimigo, se ele não se arrepender; e não serão anulados."},{"verse":28,"text":"E agora, em verdade vos digo: Se esse inimigo escapar à minha vingança, de modo que não seja levado a julgamento perante mim, então o advertireis em meu nome, para que não mais vos ataque, nem vossa família, nem mesmo os filhos de vossos filhos até a terceira e a quarta geração."},{"verse":29,"text":"E então, se ele vos atacar, vós, vossos filhos ou os filhos de vossos filhos até a terceira e a quarta geração, entregá-lo-ei em vossas mãos;"},{"verse":30,"text":"E então, se o poupardes, sereis recompensados por vossa retidão; e também vossos filhos e os filhos de vossos filhos até a terceira e a quarta geração."},{"verse":31,"text":"Contudo, vosso inimigo está em vossas mãos; e se o recompensardes de acordo com suas obras, estareis justificados; e se ele procurou tirar-vos a vida e vossa vida estiver em perigo por causa dele, vosso inimigo encontra-se em vossas mãos e estais justificados."},{"verse":32,"text":"Eis que essa é a lei que dei a meu servo Néfi e a vossos pais, José e Jacó e Isaque e Abraão, e a todos os meus antigos profetas e apóstolos."},{"verse":33,"text":"E também, esta é a lei que dei a meus antigos: Que não saíssem para batalhar contra nenhuma nação, tribo, língua ou povo, a não ser que eu, o Senhor, lhes ordenasse."},{"verse":34,"text":"E se qualquer nação, língua ou povo declarasse guerra contra eles, deveriam primeiro mostrar um estandarte de paz a esse povo, nação ou língua;"},{"verse":35,"text":"E se esse povo não aceitasse a oferta de paz, nem a segunda nem a terceira vez, eles deveriam levar esses testemunhos ao Senhor;"},{"verse":36,"text":"Então eu, o Senhor, lhes daria um mandamento e justificaria os que saíssem para batalhar contra essa nação, língua ou povo."},{"verse":37,"text":"E eu, o Senhor, lutaria suas batalhas e as batalhas de seus filhos e as dos filhos de seus filhos, até que se tivessem vingado de todos os seus inimigos até a terceira e a quarta geração."},{"verse":38,"text":"Eis que isto é um exemplo para todos, diz o Senhor vosso Deus, de justificativa perante mim."},{"verse":39,"text":"E também, em verdade vos digo: Se depois de vosso inimigo vos ter atacado a primeira vez ele se arrepender e implorar vosso perdão, perdoá-lo-eis e já não usareis isso como testemunho contra vosso inimigo —"},{"verse":40,"text":"E assim por diante, até a segunda e a terceira vez; e tantas vezes quantas vosso inimigo se arrepender das ofensas com que vos tiver ofendido, perdoá-lo-eis, até setenta vezes sete."},{"verse":41,"text":"E se vos ofender e não se arrepender a primeira vez, mesmo assim o perdoareis."},{"verse":42,"text":"E se vos ofender a segunda vez e não se arrepender, mesmo assim o perdoareis."},{"verse":43,"text":"E se vos ofender a terceira vez e não se arrepender, também o perdoareis."},{"verse":44,"text":"Mas se vos ofender a quarta vez, não o perdoareis, mas trareis esses testemunhos diante do Senhor; e não serão anulados até que ele se tenha arrependido e vos recompensado quatro vezes mais de todas as coisas com que vos tiver ofendido."},{"verse":45,"text":"E se fizer isso, perdoá-lo-eis de todo o coração; e se ele não fizer isso, eu, o Senhor, me vingarei por vós de vosso inimigo cem vezes mais;"},{"verse":46,"text":"E sobre seus filhos e sobre os filhos dos filhos de todos os que me odeiam, até a terceira e a quarta geração."},{"verse":47,"text":"Mas se os filhos se arrependerem, ou os filhos dos filhos, e se voltarem para o Senhor seu Deus de todo o coração e com todo o poder, mente e força, e repararem ao quádruplo todas as ofensas com que tiverem ofendido, ou com que seus pais ou os pais de seus pais tiverem ofendido, então vossa indignação findará;"},{"verse":48,"text":"E a vingança já não cairá sobre eles, diz o Senhor vosso Deus, e suas ofensas jamais serão apresentadas como testemunho contra eles perante o Senhor. Amém."}]},{"chapter":99,"verses":[{"verse":1,"text":"Eis que assim diz o Senhor a meu servo John Murdock: Tu és chamado para ir às regiões do leste, de casa em casa, de povoado em povoado e de cidade em cidade, a fim de proclamar o evangelho eterno a seus habitantes, em meio a perseguições e iniquidades."},{"verse":2,"text":"E quem te recebe, a mim me recebe; e terás poder para declarar minha palavra em demostração de meu Santo Espírito."},{"verse":3,"text":"E quem te recebe como uma criancinha, recebe meu reino; e bem-aventurados são eles, pois obterão misericórdia."},{"verse":4,"text":"E quem te rejeitar, será rejeitado por meu Pai e sua casa; e limparás teus pés nos lugares secretos ao longo do caminho, como testemunho contra eles."},{"verse":5,"text":"E eis que depressa venho para julgar, para convencer a todos de suas ações iníquas cometidas contra mim, conforme está escrito sobre mim no livro."},{"verse":6,"text":"E agora em verdade eu te digo: Não convém ires até que tenhas tomado providências a respeito de teus filhos e sejam eles enviados bondosamente ao bispo de Sião."},{"verse":7,"text":"E depois de alguns anos, se o desejares de mim, poderás subir também para a boa terra, a fim de possuir tua herança."},{"verse":8,"text":"Caso contrário, continuarás a pregar meu evangelho até seres levado. Amém."}]},{"chapter":100,"verses":[{"verse":1,"text":"Em verdade, assim vos diz o Senhor, meus amigos Sidney e Joseph: Vossas famílias estão bem; encontram-se em minhas mãos e eu lhes farei o que me parecer bem; pois em mim todo o poder existe."},{"verse":2,"text":"Portanto, segui-me e dai ouvidos ao conselho que vos darei."},{"verse":3,"text":"Eis que tenho muita gente neste lugar, nas regiões circunvizinhas; e uma porta eficaz abrir-se-á nas regiões circunvizinhas nesta região leste."},{"verse":4,"text":"Portanto, eu, o Senhor, permiti que viésseis a este lugar; porque assim me era conveniente para a salvação de almas."},{"verse":5,"text":"Portanto, em verdade vos digo: Clamai a este povo; expressai os pensamentos que eu vos puser no coração e não sereis confundidos diante dos homens;"},{"verse":6,"text":"Pois naquela mesma hora, sim, naquele mesmo momento, ser-vos-á dado o que dizer."},{"verse":7,"text":"Mas um mandamento vos dou, de que tudo o que declarardes declarareis em meu nome, com solenidade de coração, com espírito de mansidão em todas as coisas."},{"verse":8,"text":"E prometo-vos que, se fizerdes isso, derramar-se-á o Espírito Santo testificando todas as coisas que disserdes."},{"verse":9,"text":"E convém a mim, meu servo Sidney, que sejas um porta-voz para este povo; sim, em verdade te ordenarei com este chamado, sim, de seres o porta-voz de meu servo Joseph."},{"verse":10,"text":"E dar-lhe-ei poder para que seja vigoroso em seu testemunho."},{"verse":11,"text":"E dar-te-ei poder para seres vigoroso na exposição de todas as escrituras, a fim de que sejas seu porta-voz; e ele será um revelador para ti, a fim de conheceres a verdade de todas as coisas relativas às coisas de meu reino na Terra."},{"verse":12,"text":"Portanto, continuai a vossa viagem; e que se alegre o vosso coração, pois eis que eu estarei convosco até o fim."},{"verse":13,"text":"E agora vos falo com respeito a Sião. Sião será redimida, embora castigada por algum tempo."},{"verse":14,"text":"Vossos irmãos, meus servos Orson Hyde e John Gould, estão em minhas mãos; e se guardarem meus mandamentos, serão salvos."},{"verse":15,"text":"Portanto, que se console vosso coração; pois todas as coisas contribuem para o bem daqueles que andam retamente e para a santificação da igreja."},{"verse":16,"text":"Pois levantarei para mim um povo puro, que me servirá em retidão;"},{"verse":17,"text":"E todos os que invocam o nome do Senhor e guardam seus mandamentos serão salvos. Assim seja. Amém."}]},{"chapter":101,"verses":[{"verse":1,"text":"Em verdade eu te digo, em relação a teus irmãos que foram afligidos, perseguidos e expulsos da terra de sua herança —"},{"verse":2,"text":"Eu, o Senhor, permiti que lhes sobreviessem aflições que os afligiram em consequência de suas transgressões;"},{"verse":3,"text":"Contudo, possuí-los-ei e serão meus no dia em que eu vier para reunir minhas joias."},{"verse":4,"text":"Portanto, é necessário que sejam corrigidos e provados, assim como Abraão, a quem foi ordenado oferecer o único filho."},{"verse":5,"text":"Pois todos os que não querem suportar a correção, mas negam-me, não podem ser santificados."},{"verse":6,"text":"Eis que eu te digo: Havia desarmonias e contendas e invejas e disputas e concupiscência e cobiça entre eles; portanto, com essas coisas, corromperam suas heranças."},{"verse":7,"text":"Foram vagarosos em atender à voz do Senhor seu Deus; portanto, o Senhor seu Deus é vagaroso em atender às suas orações, em responder-lhes no dia de suas tribulações."},{"verse":8,"text":"No dia de sua paz, trataram com leviandade meus conselhos; mas, no dia de suas tribulações, buscaram-me por necessidade."},{"verse":9,"text":"Em verdade eu te digo: Apesar de seus pecados, minhas entranhas estão cheias de compaixão por eles. Não os expulsarei totalmente; e no dia da ira, lembrar-me-ei da misericórdia."},{"verse":10,"text":"Eu jurei e decretei, num mandamento que vos dei anteriormente, que deixaria cair a espada de minha indignação em favor de meu povo; e assim como eu disse, acontecerá."},{"verse":11,"text":"Minha indignação logo se derramará sem medida sobre todas as nações; e isso farei quando estiver cheio o cálice de sua iniquidade."},{"verse":12,"text":"E nesse dia, todo aquele que se achar de atalaia, ou, em outras palavras, todo o meu Israel, será salvo."},{"verse":13,"text":"E os que foram dispersos serão reunidos."},{"verse":14,"text":"E todos os que prantearam serão consolados."},{"verse":15,"text":"E todos os que deram a vida pelo meu nome serão coroados."},{"verse":16,"text":"Portanto, que se console vosso coração no que diz respeito a Sião; pois toda carne está em minhas mãos; aquietai-vos e sabei que eu sou Deus."},{"verse":17,"text":"Sião não será removida de seu lugar, apesar de seus filhos estarem dispersos."},{"verse":18,"text":"Os que permanecerem e forem puros de coração retornarão para suas heranças, eles e seus filhos, com cânticos de eterna alegria, para edificar os lugares desolados de Sião —"},{"verse":19,"text":"E todas estas coisas para que os profetas se cumpram."},{"verse":20,"text":"E eis que não há outro lugar designado além daquele que designei; nem haverá outro lugar designado além daquele que designei para a reunião de meus santos —"},{"verse":21,"text":"Até chegar o dia em que não haja mais lugar para eles; e então lhes designarei outros lugares que tenho e serão chamados estacas, para as cortinas ou a força de Sião."},{"verse":22,"text":"Eis que é meu desejo que todos os que invocam meu nome e me adoram, de acordo com meu evangelho eterno, se reúnam e permaneçam em lugares santos;"},{"verse":23,"text":"E preparem-se para a revelação que virá quando o véu que cobre meu templo, em meu tabernáculo, que oculta a Terra, for retirado; e toda carne juntamente me verá."},{"verse":24,"text":"E toda coisa corruptível, seja do homem ou dos animais do campo ou das aves do céu ou dos peixes do mar, que habita na face da Terra, será consumida;"},{"verse":25,"text":"E também o que for de elementos derreter-se-á com calor fervente; e todas as coisas tornar-se-ão novas, para que meu conhecimento e minha glória habitem em toda a Terra."},{"verse":26,"text":"E nesse dia, a inimizade do homem e a inimizade das bestas, sim, a inimizade de toda carne terá fim de diante de minha face."},{"verse":27,"text":"E nesse dia, qualquer coisa que o homem pedir, ser-lhe-á dada;"},{"verse":28,"text":"E nesse dia Satanás não terá poder para tentar homem algum."},{"verse":29,"text":"E não haverá pranto, porque não haverá morte."},{"verse":30,"text":"Nesse dia uma criança não morrerá antes de envelhecer; e sua vida será como a idade de uma árvore."},{"verse":31,"text":"E quando morrer, não dormirá, isto é, na terra, mas será transformada num piscar de olhos e será arrebatada; e seu descanso será glorioso."},{"verse":32,"text":"Sim, em verdade vos digo: No dia em que o Senhor vier, ele revelará todas as coisas —"},{"verse":33,"text":"Coisas passadas e coisas ocultas que nenhum homem conheceu, coisas da Terra pelas quais foi feita e seu propósito e seu fim —"},{"verse":34,"text":"Coisas muito preciosas, coisas que estão no alto e coisas que estão em baixo, coisas que estão dentro da terra e sobre a terra e nos céus."},{"verse":35,"text":"E todos os que sofrerem perseguição pelo meu nome e perseverarem com fé, ainda que lhes seja requerido dar a vida por minha causa, participarão de toda esta glória."},{"verse":36,"text":"Portanto, não temais nem mesmo a morte; porque neste mundo vossa alegria não é completa, mas em mim vossa alegria é completa."},{"verse":37,"text":"Portanto, não vos preocupeis com o corpo nem com a vida do corpo; mas preocupai-vos com a alma e com a vida da alma."},{"verse":38,"text":"E buscai sempre a face do Senhor para que, em paciência, possuais vossa alma; e tereis vida eterna."},{"verse":39,"text":"Quando os homens são chamados ao meu evangelho eterno e fazem um convênio eterno, são considerados como o sal da Terra e o sabor dos homens;"},{"verse":40,"text":"São chamados para ser o sabor dos homens; portanto, se esse sal da Terra perder seu sabor, eis que, daí em diante, para nada mais presta senão para se lançar fora e ser pisado pelos homens."},{"verse":41,"text":"Eis que aqui há sabedoria no tocante aos filhos de Sião, sim, muitos, mas não todos; eles foram considerados transgressores, portanto, precisam ser corrigidos —"},{"verse":42,"text":"Aquele que a si mesmo se exaltar será humilhado; e aquele que a si mesmo se humilhar será exaltado."},{"verse":43,"text":"E agora vos narrarei uma parábola, para que conheçais a minha vontade concernente à redenção de Sião."},{"verse":44,"text":"Um certo nobre possuía um pedaço de terra muito bom; e disse aos seus servos: Ide à minha vinha, sim, a esse pedaço de terra muito bom, e plantai doze oliveiras;"},{"verse":45,"text":"E colocai atalaias ao seu redor e construí uma torre, para que se possa vigiar a redondeza; e um fique de atalaia na torre, a fim de que minhas oliveiras não sejam derrubadas quando vier o inimigo para saquear e tomar para si o fruto de minha vinha."},{"verse":46,"text":"Ora, os servos do nobre fizeram o que seu senhor lhes ordenara e plantaram as oliveiras e construíram uma sebe ao redor e colocaram atalaias e começaram a construir uma torre."},{"verse":47,"text":"E enquanto ainda estavam pondo seus alicerces, começaram a dizer entre si: E que necessidade tem meu senhor desta torre?"},{"verse":48,"text":"E consultaram-se por longo tempo, dizendo entre si: Que necessidade tem meu senhor desta torre, sendo que é tempo de paz?"},{"verse":49,"text":"Não poderia esse dinheiro ser dado aos banqueiros? Pois não há necessidade destas coisas."},{"verse":50,"text":"E enquanto discordavam entre si, tornaram-se muito preguiçosos e não deram ouvidos às ordens de seu senhor."},{"verse":51,"text":"E durante a noite chegou o inimigo e derrubou a sebe; e os servos do nobre levantaram-se atemorizados e fugiram; e o inimigo destruiu o trabalho deles e derrubou as oliveiras."},{"verse":52,"text":"Então, eis que o nobre, o senhor da vinha, chamou seus servos e perguntou-lhes: Ora, qual a causa deste grande mal?"},{"verse":53,"text":"Não devíeis ter feito o que vos mandei e — depois de haverdes plantado a vinha e construído a sebe ao redor e posto atalaias sobre seus muros — construído também a torre e posto um atalaia na torre e vigiado minha vinha, sem adormecer, para que o inimigo não vos atacasse?"},{"verse":54,"text":"E eis que o atalaia da torre teria visto o inimigo enquanto ainda estava distante; e então poderíeis ter-vos preparado e evitado que o inimigo derrubasse a sebe, salvando minha vinha da mão do destruidor."},{"verse":55,"text":"E o senhor da vinha disse a um de seus servos: Vai reunir o restante de meus servos e toma toda a força de minha casa, que são meus guerreiros, meus jovens e também os de meia-idade entre meus servos, que são a força de minha casa, salvo apenas os que designei para ficarem;"},{"verse":56,"text":"E ide imediatamente à terra de minha vinha e resgatai-a; pois é minha; comprei-a com dinheiro."},{"verse":57,"text":"Portanto, ide imediatamente à minha terra; derrubai os muros de meus inimigos; derrubai a sua torre e dispersai os seus atalaias."},{"verse":58,"text":"E caso se reúnam contra vós, vingai-me de meus inimigos para que logo eu venha com o restante de minha casa e ocupe a terra."},{"verse":59,"text":"E o servo disse a seu senhor: Quando acontecerão essas coisas?"},{"verse":60,"text":"E ele respondeu ao servo: Quando eu desejar; vai imediatamente e faze todas as coisas que te mandei;"},{"verse":61,"text":"E este será meu selo e minha bênção sobre ti — um mordomo fiel e prudente em minha casa, um governante em meu reino."},{"verse":62,"text":"E seu servo foi imediatamente e fez todas as coisas que seu senhor lhe mandara; e depois de muitos dias, todas as coisas se cumpriram."},{"verse":63,"text":"Também, em verdade vos digo: Mostrar-vos-ei o que me é prudente em relação a todas as igrejas, se estiverem dispostas a ser guiadas de uma forma reta e adequada para sua salvação —"},{"verse":64,"text":"Para que a obra da reunião de meus santos continue a fim de que eu os edifique ao meu nome em lugares santos; porque é chegado o tempo da ceifa e minha palavra precisa cumprir-se."},{"verse":65,"text":"Portanto, preciso reunir meu povo, segundo a parábola do trigo e do joio, para que o trigo seja recolhido nos celeiros a fim de possuir a vida eterna e ser coroado de glória celestial quando eu vier no reino de meu Pai para recompensar cada homem de acordo com suas obras;"},{"verse":66,"text":"Enquanto que o joio será atado em feixes e suas amarraduras, fortalecidas, para que se queime em fogo inextinguível."},{"verse":67,"text":"Portanto, um mandamento dou a todas as igrejas, de que continuem a reunir-se nos lugares que designei."},{"verse":68,"text":"Contudo, como vos disse num mandamento anterior, que vossa reunião não seja feita às pressas, nem por meio de fuga; mas que se preparem todas as coisas com antecedência."},{"verse":69,"text":"E para que se preparem todas as coisas com antecedência, observai o mandamento que vos dei concernente a estas coisas —"},{"verse":70,"text":"O qual diz, ou seja, ensina a comprar com dinheiro todas as terras, que puderem ser compradas com dinheiro, na região que circunda a terra que designei como terra de Sião, para o início da reunião de meus santos;"},{"verse":71,"text":"Todas as terras que puderem ser compradas no Condado de Jackson e nos condados das redondezas, deixando o resto em minhas mãos."},{"verse":72,"text":"Ora, em verdade vos digo: Que todas as igrejas juntem todo o seu dinheiro; que estas coisas sejam feitas a seu tempo, mas não às pressas; e preparai todas as coisas com antecedência."},{"verse":73,"text":"E que sejam designados homens honrados, sim, homens prudentes; e enviai-os para comprarem essas terras."},{"verse":74,"text":"E se as igrejas da região leste, quando forem organizadas, derem ouvidos a esse conselho, poderão comprar terras e reunir-se nelas; e desta forma estabelecer Sião."},{"verse":75,"text":"Já há uma reserva suficiente, sim, em abundância, para redimir Sião e estabelecer os seus lugares desolados, a fim de que já não sejam abatidos, caso as igrejas que levam o meu nome estejam dispostas a atender à minha voz."},{"verse":76,"text":"E também vos digo: É a minha vontade que aqueles que foram dispersos por seus inimigos continuem a exigir compensação e redenção das mãos daqueles que foram colocados como governantes e que têm autoridade sobre vós —"},{"verse":77,"text":"De acordo com as leis e a constituição do povo, que permiti fossem estabelecidas e que devem ser mantidas para os direitos e a proteção de toda carne, segundo princípios justos e santos;"},{"verse":78,"text":"Para que todo homem aja, em doutrina e princípio relativos ao futuro, de acordo com o arbítrio moral que lhe dei, para que todo homem seja responsável por seus próprios pecados no dia do juízo."},{"verse":79,"text":"Portanto, não é certo que homem algum seja escravo de outro."},{"verse":80,"text":"E com esse propósito estabeleci a Constituição deste país, pelas mãos de homens prudentes que levantei para esse propósito; e redimi a terra pelo derramamento de sangue."},{"verse":81,"text":"Ora, a que compararei os filhos de Sião? Compará-los-ei à parábola da mulher e do juiz injusto, porque os homens devem orar sempre e não desfalecer, a qual diz —"},{"verse":82,"text":"Havia, numa cidade, um juiz que não temia a Deus nem respeitava os homens."},{"verse":83,"text":"E havia naquela cidade uma viúva e ela procurou-o, dizendo: Vinga-me de meu adversário."},{"verse":84,"text":"E por algum tempo ele não o fez, mas depois disse consigo: Ainda que não tema a Deus nem respeite os homens, contudo, como esta viúva me importuna, vingá-la-ei para que não me importune vindo aqui continuamente."},{"verse":85,"text":"Assim compararei os filhos de Sião."},{"verse":86,"text":"Que insistam aos pés do juiz;"},{"verse":87,"text":"E se ele não lhes der ouvidos, que insistam aos pés do governador;"},{"verse":88,"text":"E se o governador não lhes der ouvidos, que insistam aos pés do presidente;"},{"verse":89,"text":"E se o presidente não lhes der ouvidos, o Senhor se erguerá e sairá de seu esconderijo e, em sua fúria, afligirá a nação;"},{"verse":90,"text":"E em seu intenso desagrado e em sua ardente ira, a seu tempo, cortará os mordomos iníquos, infiéis e injustos e designar-lhes-á sua porção entre os hipócritas e incrédulos."},{"verse":91,"text":"Sim, nas trevas exteriores, onde há pranto e gemido e ranger de dentes."},{"verse":92,"text":"Orai, portanto, para que seus ouvidos se abram a vossos clamores, para que eu possa ser misericordioso com eles, para que estas coisas não lhes sobrevenham."},{"verse":93,"text":"O que vos disse precisa acontecer, para que homem algum tenha desculpa;"},{"verse":94,"text":"Para que homens prudentes e governantes ouçam e compreendam o que nunca haviam considerado;"},{"verse":95,"text":"Para que eu execute o meu ato, o meu estranho ato, e execute a minha obra, a minha estranha obra, para que os homens discirnam os retos dos iníquos, diz vosso Deus."},{"verse":96,"text":"E também vos digo: É contrário ao meu mandamento e à minha vontade que o meu servo Sidney Gilbert venda aos meus inimigos o meu armazém, que designei para o meu povo."},{"verse":97,"text":"Que o que designei não seja profanado por meus inimigos com o consentimento daqueles que levam meu nome;"},{"verse":98,"text":"Porque esse é um sério e grave pecado contra mim e contra meu povo, em consequência das coisas que decretei e que logo cairão sobre as nações."},{"verse":99,"text":"Portanto, é a minha vontade que meu povo reivindique, e mantenha os seus direitos sobre o que lhes designei, embora não se lhes permita ali habitar."},{"verse":100,"text":"Contudo, não digo que lá não habitarão; porque se produzirem frutos e obras dignos de meu reino, ali habitarão."},{"verse":101,"text":"Edificarão e outros não herdarão; plantarão vinhas e comerão de seu fruto. Assim seja. Amém."}]},{"chapter":102,"verses":[{"verse":1,"text":"Neste dia reuniu-se um conselho geral de vinte e quatro sumos sacerdotes na casa de Joseph Smith Júnior, por revelação, e procedeu à organização do sumo conselho da igreja de Cristo, o qual consistiria em doze sumos sacerdotes e um ou três presidentes, conforme o caso exigisse."},{"verse":2,"text":"O sumo conselho foi designado por revelação com o propósito de resolver as dificuldades importantes que surgissem na igreja e que não pudessem ser resolvidas pela igreja ou pelo conselho do bispo a contento dos interessados."},{"verse":3,"text":"Joseph Smith Júnior, Sidney Rigdon e Frederick G. Williams foram aceitos como presidentes pelo voto do conselho; e Joseph Smith Sênior, John Smith, Joseph Coe, John Johnson, Martin Harris, John S. Carter, Jared Carter, Oliver Cowdery, Samuel H. Smith, Orson Hyde, Sylvester Smith e Luke Johnson, sumos sacerdotes, foram escolhidos pelo voto unânime do conselho para formar um conselho permanente na igreja."},{"verse":4,"text":"Aos conselheiros acima mencionados perguntou-se então se aceitavam a designação e se agiriam nesse chamado de acordo com a lei do céu, ao que todos responderam que aceitavam a designação e que agiriam no chamado de acordo com a graça de Deus a eles conferida."},{"verse":5,"text":"O número dos que compunham o conselho, que em nome da igreja e pela igreja votaram para a escolha dos conselheiros acima mencionados, era quarenta e três, como se segue: nove sumos sacerdotes, dezessete élderes, quatro sacerdotes e treze membros."},{"verse":6,"text":"Votou-se: Que o sumo conselho não tem poder para agir sem a presença de sete dos conselheiros acima mencionados ou seus sucessores devidamente designados."},{"verse":7,"text":"Estes sete terão poder para designar outros sumos sacerdotes que considerarem dignos e capazes de agir em lugar de conselheiros ausentes."},{"verse":8,"text":"Votou-se: Que quando ocorrer uma vaga por morte, remoção do cargo devido a transgressão ou mudança para fora dos limites do governo desta igreja de qualquer um dos conselheiros acima mencionados, a vaga será preenchida por indicação do presidente ou presidentes e sancionada pelo voto de um conselho geral de sumos sacerdotes, reunidos com esse fim para agir em nome da igreja."},{"verse":9,"text":"O presidente da igreja, que é também o presidente do conselho, é designado por revelação e reconhecido em sua administração pela voz da igreja."},{"verse":10,"text":"E está de acordo com a dignidade de seu chamado presidir o conselho da igreja, tendo ele o privilégio de ser assistido por outros dois presidentes, designados do mesmo modo que ele foi designado."},{"verse":11,"text":"E em caso de ausência de um ou de ambos os que tiverem sido designados para assisti-lo, ele terá poder para presidir o conselho sem um assistente; e em caso de ele próprio estar ausente, os outros presidentes, ambos ou um deles, terão poder para presidir em seu lugar."},{"verse":12,"text":"Quando um sumo conselho da igreja de Cristo for devidamente organizado, de acordo com o modelo precedente, será dever dos doze conselheiros, sorteando números, decidir qual dos doze falará primeiro, começando com o número um e assim por diante até o número doze."},{"verse":13,"text":"Sempre que este conselho se reunir para decidir qualquer caso, os doze conselheiros deverão considerar se é um caso difícil ou não; se não for, apenas dois conselheiros falarão sobre ele, de acordo com a forma descrita acima."},{"verse":14,"text":"Mas se acharem que é difícil, designar-se-ão quatro; e se mais difícil ainda, seis; mas em caso algum serão designados mais que seis para falar."},{"verse":15,"text":"O acusado, em todos os casos, tem direito ao apoio da metade do conselho, para evitarem-se insultos ou injustiças."},{"verse":16,"text":"E os conselheiros designados para falar perante o conselho devem apresentar o caso após o exame das evidências, em sua verdadeira luz; e todo homem deverá falar com equidade e justiça."},{"verse":17,"text":"Os conselheiros que sortearem os números pares, isto é, 2, 4, 6, 8, 10 e 12 são os que deverão defender o acusado e evitar insultos e injustiças."},{"verse":18,"text":"Em todos os casos, o acusador e o acusado terão o privilégio de falar por si mesmos diante do conselho, depois que as evidências tiverem sido ouvidas e os conselheiros designados para falar sobre o caso tiverem terminado seus comentários."},{"verse":19,"text":"Depois que as evidências forem ouvidas e os conselheiros, o acusador e o acusado tiverem falado, o presidente apresentará uma decisão segundo a compreensão que tiver do caso e pedirá aos doze conselheiros que a sancionem com seu voto."},{"verse":20,"text":"Mas se os outros conselheiros que não tiverem falado, ou qualquer um deles, depois de ouvir imparcialmente as evidências e os argumentos, descobrirem um erro na decisão do presidente, poderão manifestá-lo e o caso terá nova audiência."},{"verse":21,"text":"E se, depois de outra cuidadosa audiência, alguma luz for adicionada ao caso, a decisão será alterada de acordo com essa luz."},{"verse":22,"text":"Se nenhuma luz, porém, for adicionada, a primeira decisão prevalecerá, tendo a maioria do conselho poder para determiná-la."},{"verse":23,"text":"Em caso de dificuldade com respeito a doutrina ou princípio, se não houver material escrito suficiente para tornar claro o caso na mente do conselho, o presidente poderá consultar e obter a vontade do Senhor por revelação."},{"verse":24,"text":"Os sumos sacerdotes, quando estiverem fora, terão poder para convocar e organizar um conselho segundo o modelo acima, para resolver dificuldades quando ambas as partes, ou uma delas, solicitarem."},{"verse":25,"text":"E esse conselho de sumos sacerdotes terá poder para designar um de seus próprios membros para presidir tal conselho interinamente."},{"verse":26,"text":"Será dever desse conselho enviar imediatamente uma cópia da ata, com um relatório completo dos testemunhos apresentados, acompanhando suas decisões, ao sumo conselho da sede da Primeira Presidência da Igreja."},{"verse":27,"text":"Se ambas as partes, ou uma delas, não estiverem satisfeitas com a decisão do conselho, poderão apelar ao sumo conselho da sede da Primeira Presidência da Igreja e ter uma nova audiência, quando o caso será tratado de acordo com o primeiro modelo escrito, como se tal decisão não tivesse sido tomada."},{"verse":28,"text":"Este conselho de sumos sacerdotes em outros locais só deverá ser convocado nos casos mais difíceis relacionados a assuntos da igreja; e nenhum caso comum ou trivial será suficiente para convocar tal conselho."},{"verse":29,"text":"Os sumos sacerdotes viajantes ou residentes em outros locais têm poder para decidir se é ou não necessário convocar um conselho."},{"verse":30,"text":"Há uma distinção entre o sumo conselho ou os sumos sacerdotes viajantes que estiverem fora e o sumo conselho viajante composto dos doze apóstolos, em suas decisões."},{"verse":31,"text":"Da decisão do primeiro pode-se apelar; mas da decisão do último, não."},{"verse":32,"text":"O último pode apenas ser chamado a juízo pelas autoridades gerais da igreja em caso de transgressão."},{"verse":33,"text":"Resolveu-se: Que o presidente ou presidentes da sede da Primeira Presidência da Igreja terão poder para determinar se qualquer desses casos em que haja apelação tem direito a nova audiência, depois de examinar a apelação e as evidências e declarações que o acompanham."},{"verse":34,"text":"Os doze conselheiros então lançaram a sorte ou votos para determinar quem deveria falar primeiro e o resultado foi o seguinte: 1, Oliver Cowdery; 2, Joseph Coe; 3, Samuel H. Smith; 4, Luke Johnson; 5, John S. Carter; 6, Sylvester Smith; 7, John Johnson; 8, Orson Hyde; 9, Jared Carter; 10, Joseph Smith Sênior; 11, John Smith; 12, Martin Harris.Depois da oração, encerrou-se a conferência."},{"verse":35,"text":"Oliver Cowdery,"},{"verse":36,"text":"Orson Hyde,"},{"verse":37,"text":"Secretários"}]},{"chapter":103,"verses":[{"verse":1,"text":"Em verdade vos digo, meus amigos: Eis que vos darei uma revelação e mandamento, para que saibais agir no desempenho de vossos deveres referentes à salvação e redenção de vossos irmãos que foram dispersos na terra de Sião;"},{"verse":2,"text":"Tendo sido expulsos e feridos pelas mãos de meus inimigos, sobre quem derramarei minha ira sem medida, em meu próprio tempo."},{"verse":3,"text":"Pois até agora os tenho tolerado, para que enchessem a medida de suas iniquidades, para que se enchesse o seu cálice;"},{"verse":4,"text":"E para que os que chamam a si próprios pelo meu nome fossem castigados por algum tempo com um castigo severo e doloroso, por não terem, de forma alguma, atendido aos preceitos e mandamentos que lhes dei."},{"verse":5,"text":"Mas em verdade vos digo que decretei um decreto que meu povo executará se atender, de agora em diante, aos conselhos que eu, o Senhor seu Deus, lhe darei."},{"verse":6,"text":"Eis que, porque o decretei, eles começarão a prevalecer contra meus inimigos a partir deste exato momento."},{"verse":7,"text":"E tendo o cuidado de cumprir todas as palavras que eu, o Senhor seu Deus, lhes disser, jamais deixarão de prevalecer, até que os reinos do mundo sejam subjugados sob meus pés e a Terra seja dada aos santos a fim de que a possuam para todo o sempre."},{"verse":8,"text":"Mas se não guardarem meus mandamentos e não tiverem o cuidado de cumprir todas as palavras minhas, os reinos do mundo prevalecerão contra eles."},{"verse":9,"text":"Pois foram designados para serem uma luz para o mundo e salvadores de homens;"},{"verse":10,"text":"E se não forem salvadores de homens, serão como o sal que perdeu o sabor e, daí em diante, para nada mais presta senão para ser lançado fora e pisado pelos homens."},{"verse":11,"text":"Mas em verdade vos digo: Decretei que vossos irmãos que foram dispersos retornem às terras de sua herança e edifiquem os lugares desolados de Sião."},{"verse":12,"text":"Pois, após muita tribulação, como vos disse num mandamento anterior, vem a bênção."},{"verse":13,"text":"Eis que esta é a bênção que vos prometi depois de vossas tribulações e das tribulações de vossos irmãos — vossa redenção e a redenção de vossos irmãos, sim, sua volta à terra de Sião, para que se estabeleçam a fim de não mais serem derrubados."},{"verse":14,"text":"Contudo, se profanarem suas heranças, serão derrubados; porque não os pouparei se desonrarem suas heranças."},{"verse":15,"text":"Eis que vos digo que a redenção de Sião precisa vir por poder;"},{"verse":16,"text":"Portanto, suscitarei um homem para meu povo, que o guiará como Moisés guiou os filhos de Israel."},{"verse":17,"text":"Pois sois os filhos de Israel e da semente de Abraão; e necessário é que sejais tirados da escravidão por meio de poder e com um braço estendido."},{"verse":18,"text":"E assim como vossos pais foram guiados no princípio, assim será a redenção de Sião."},{"verse":19,"text":"Portanto, que não desfaleça vosso coração, pois não vos digo como disse a vossos pais: Meu anjo irá adiante de vós, mas não minha presença."},{"verse":20,"text":"Mas digo-vos: Meus anjos irão adiante de vós e também minha presença; e, dentro de algum tempo, possuireis a boa terra."},{"verse":21,"text":"Em verdade, em verdade vos digo que meu servo Joseph Smith Júnior, é o homem a quem comparei o servo com quem falou o Senhor da vinha, na parábola que vos dei."},{"verse":22,"text":"Portanto, que meu servo Joseph Smith Júnior diga à força de minha casa, meus jovens e os homens de meia idade: Reuni-vos na terra de Sião, na terra que comprei com dinheiro que me foi consagrado."},{"verse":23,"text":"E que todas as igrejas enviem homens prudentes com o dinheiro arrecadado, a fim de comprar terras, como lhes ordenei."},{"verse":24,"text":"E se meus inimigos vos atacarem para vos expulsarem de minha boa terra, que consagrei para ser a terra de Sião, e também de vossas próprias terras, após estes testemunhos que trouxestes perante mim contra eles, amaldiçoá-los-eis;"},{"verse":25,"text":"E quem amaldiçoardes, eu amaldiçoarei; e vingar-me-eis de meus inimigos."},{"verse":26,"text":"E minha presença estará convosco quando me vingardes de meus inimigos, até a terceira e quarta geração dos que me odeiam."},{"verse":27,"text":"Que nenhum homem tenha medo de perder sua vida por minha causa; porque aquele que perder a vida por minha causa tornará a achá-la."},{"verse":28,"text":"E aquele que não estiver disposto a perder a vida por minha causa não é meu discípulo."},{"verse":29,"text":"É a minha vontade que meu servo Sidney Rigdon eleve a sua voz nas congregações das regiões do leste, preparando as igrejas para guardarem os mandamentos que lhes dei concernentes à restauração e à redenção de Sião."},{"verse":30,"text":"É a minha vontade que meu servo Parley P. Pratt e meu servo Lyman Wight não regressem à terra de seus irmãos até que hajam conseguido grupos para subirem à terra de Sião, em número de dez ou de vinte ou de cinquenta ou de cem, até atingir os quinhentos da força de minha casa."},{"verse":31,"text":"Eis que essa é a minha vontade; pedi e recebereis; mas os homens nem sempre fazem a minha vontade."},{"verse":32,"text":"Portanto, se não conseguirdes quinhentos, procurai diligentemente para que, talvez, consigais trezentos."},{"verse":33,"text":"E se não conseguirdes trezentos, procurai diligentemente para que, talvez, consigais cem."},{"verse":34,"text":"Mas em verdade vos digo: Um mandamento vos dou, de que não subais à terra de Sião até que tenhais conseguido cem da força de minha casa para subirem convosco à terra de Sião."},{"verse":35,"text":"Portanto, como vos disse, pedi e recebereis; orai fervorosamente para que, talvez, meu servo Joseph Smith Júnior possa ir convosco, a fim de presidir no meio de meu povo e organizar meu reino na terra consagrada e estabelecer os filhos de Sião sobre as leis e mandamentos que vos foram e que vos serão dados."},{"verse":36,"text":"Toda vitória e toda glória ser-vos-ão manifestadas por meio de vossa diligência, fidelidade e orações de fé."},{"verse":37,"text":"Que meu servo Parley P. Pratt viaje com meu servo Joseph Smith Júnior."},{"verse":38,"text":"Que meu servo Lyman Wight viaje com meu servo Sidney Rigdon."},{"verse":39,"text":"Que meu servo Hyrum Smith viaje com meu servo Frederick G. Williams."},{"verse":40,"text":"Que meu servo Orson Hyde viaje com meu servo Orson Pratt, para onde quer que meu servo Joseph Smith Júnior os aconselhe, para cumprimento destes mandamentos que vos dei; e deixai o restante em minhas mãos. Assim seja. Amém."}]},{"chapter":104,"verses":[{"verse":1,"text":"Em verdade vos digo, meus amigos: Dou-vos um conselho e um mandamento concernente a todas as propriedades que pertencem à ordem que mandei organizar e estabelecer, a fim de ser uma ordem unida e uma ordem eterna para o benefício de minha igreja e para a salvação dos homens até que eu venha —"},{"verse":2,"text":"Com a promessa imutável e inalterável de que, se fossem fiéis, aqueles que mandei seriam abençoados com uma multiplicidade de bênçãos;"},{"verse":3,"text":"Mas, por não terem sido fiéis, estavam às portas da maldição."},{"verse":4,"text":"Contudo, sendo que alguns de meus servos não guardaram o mandamento, mas quebraram o convênio por cobiça e com palavras falsas, amaldiçoei-os com uma maldição severa e dolorosa."},{"verse":5,"text":"Porque eu, o Senhor, decretei em meu coração que, se qualquer homem que pertencer à ordem for considerado transgressor, ou, em outras palavras, quebrar o convênio com que estais comprometidos, será amaldiçoado na vida e será pisado por quem eu desejar;"},{"verse":6,"text":"Pois eu, o Senhor, não serei escarnecido quanto a estas coisas —"},{"verse":7,"text":"E tudo isso para que os inocentes dentre vós não sejam condenados com os injustos; e para que os culpados dentre vós não escapem; porque eu, o Senhor, vos prometi uma coroa de glória à minha direita."},{"verse":8,"text":"Portanto, se fordes considerados transgressores, não podereis escapar à minha ira nesta vida."},{"verse":9,"text":"Se fordes expulsos por transgressão, não podereis escapar às bofetadas de Satanás até o dia da redenção."},{"verse":10,"text":"E agora vos dou poder, a partir deste exato momento, caso qualquer homem dentre vós, que pertença à ordem, seja considerado transgressor e não se arrependa do mal, para entregá-lo às bofetadas de Satanás; e ele não terá poder para vos causar mal."},{"verse":11,"text":"Isto é minha sabedoria; portanto, dou-vos o mandamento de que vos organizeis e designeis a todo homem sua mordomia;"},{"verse":12,"text":"Para que todo homem me preste contas da mordomia que lhe for designada."},{"verse":13,"text":"Porque é conveniente que eu, o Senhor, faça cada homem responsável como mordomo de bênçãos terrenas, que fiz e preparei para as minhas criaturas."},{"verse":14,"text":"Eu, o Senhor, estendi os céus e formei a Terra, obra de minhas mãos; e todas as coisas que neles há são minhas."},{"verse":15,"text":"E é meu propósito suprir a meus santos, pois todas as coisas são minhas."},{"verse":16,"text":"Mas é necessário que seja feito a meu modo; e eis que este é o modo que eu, o Senhor, decretei para suprir meus santos, para que os pobres sejam aumentados naquilo que os ricos são diminuídos."},{"verse":17,"text":"Pois a Terra está repleta e há bastante e de sobra; sim, preparei todas as coisas e permiti que os filhos dos homens fossem seus próprios árbitros."},{"verse":18,"text":"Portanto, se algum homem tomar da abundância que fiz e não repartir sua porção com os pobres e os necessitados, de acordo com a lei de meu evangelho, ele, com os iníquos, erguerá seus olhos no inferno, estando em tormento."},{"verse":19,"text":"E agora, em verdade vos digo, com respeito às propriedades da ordem:"},{"verse":20,"text":"Que a meu servo Sidney Rigdon sejam designados o lugar em que agora reside, e o terreno do curtume como a sua mordomia, para seu sustento enquanto estiver trabalhando na minha vinha, de acordo com a minha vontade, quando eu lhe ordenar."},{"verse":21,"text":"E que todas as coisas sejam feitas de acordo com o conselho da ordem e pelo consentimento ou voto unânime da ordem radicada na terra de Kirtland."},{"verse":22,"text":"E esta mordomia e bênção, eu, o Senhor, confiro a meu servo Sidney Rigdon como bênção para ele e para sua semente depois dele."},{"verse":23,"text":"E multiplicarei suas bênçãos se for humilde perante mim."},{"verse":24,"text":"E também, que a meu servo Martin Harris e a sua semente depois dele seja designado, como sua mordomia, o terreno que meu servo John Johnson obteve em troca de sua herança anterior;"},{"verse":25,"text":"E, se ele for fiel, multiplicarei suas bênçãos e as de sua semente depois dele."},{"verse":26,"text":"E que meu servo Martin Harris dedique seu dinheiro à proclamação de minhas palavras, de acordo com o que meu servo Joseph Smith Júnior instruir."},{"verse":27,"text":"E também, que meu servo Frederick G. Williams receba o lugar em que agora reside."},{"verse":28,"text":"E que meu servo Oliver Cowdery receba o terreno vizinho à casa designada para ser a tipografia, que é o lote número um; e também o terreno em que reside seu pai."},{"verse":29,"text":"E que meus servos Frederick G. Williams e Oliver Cowdery recebam a tipografia e todas as coisas pertencentes a ela."},{"verse":30,"text":"E esta é a mordomia que lhes será designada."},{"verse":31,"text":"E, se forem fiéis, eis que os abençoarei e multiplicarei suas bênçãos."},{"verse":32,"text":"E esse é o princípio da mordomia que lhes designei — para eles e para sua semente depois deles."},{"verse":33,"text":"E, se forem fiéis, multiplicarei suas bênçãos e as de sua semente depois deles, sim, uma multiplicidade de bênçãos."},{"verse":34,"text":"E também que meu servo John Johnson receba a casa em que reside e a herança — tudo, exceto a terra reservada para a construção de minhas casas, que pertence a essa herança, e os terrenos designados para meu servo Oliver Cowdery."},{"verse":35,"text":"E, se for fiel, multiplicarei suas bênçãos."},{"verse":36,"text":"E é a minha vontade que ele venda os terrenos demarcados para a edificação da cidade dos meus santos, conforme lhe for dado saber pela voz do Espírito, e segundo o conselho da ordem, e pelo voto da ordem."},{"verse":37,"text":"E esse é o princípio da mordomia que lhe designei, como bênção para ele e sua semente depois dele."},{"verse":38,"text":"E, se for fiel, derramarei sobre ele uma multiplicidade de bênçãos."},{"verse":39,"text":"E também que a meu servo Newel K. Whitney sejam designadas as casas e o terreno onde agora reside e o terreno e o edifício em que se encontra o estabelecimento mercantil, assim como o lote da esquina ao sul do estabelecimento mercantil e também o terreno onde está situada a fábrica de potassa."},{"verse":40,"text":"E tudo isto designei como a mordomia de meu servo Newel K. Whitney, como uma bênção para ele e sua semente depois dele, em benefício do estabelecimento mercantil da minha ordem, que estabeleci para ser minha estaca na terra de Kirtland."},{"verse":41,"text":"Sim, em verdade esta é a mordomia que designei para meu servo N. K. Whitney, sim, todo este estabelecimento mercantil, para ele e seu agente e sua semente depois dele."},{"verse":42,"text":"E, se for fiel na obediência aos mandamentos que lhe dei, multiplicarei suas bênçãos e as de sua semente depois dele, sim, uma multiplicidade de bênçãos."},{"verse":43,"text":"E também, que seja designado a meu servo Joseph Smith Júnior o terreno que foi demarcado para a construção de minha casa, o qual mede quarenta varas de comprimento por doze de largura, assim como a herança onde agora reside seu pai;"},{"verse":44,"text":"E esse é o princípio da mordomia que lhe designei, como bênção para ele e para seu pai."},{"verse":45,"text":"Pois eis que reservei uma herança para o sustento de seu pai; portanto, ele será contado com a casa de meu servo Joseph Smith Júnior."},{"verse":46,"text":"E multiplicarei as bênçãos da casa de meu servo Joseph Smith Júnior, se for fiel, sim, uma multiplicidade de bênçãos."},{"verse":47,"text":"E agora vos dou um mandamento concernente a Sião, para que já não estejais ligados como ordem unida a vossos irmãos de Sião, a não ser deste modo:"},{"verse":48,"text":"Depois de estardes organizados, sereis chamados de Ordem Unida da Estaca de Sião, da cidade de Kirtland. E vossos irmãos, depois de se organizarem, serão chamados de Ordem Unida da Cidade de Sião."},{"verse":49,"text":"E organizar-se-ão em seus próprios nomes e em nome da ordem; e cuidarão de seus negócios em nome da ordem e em seus próprios nomes;"},{"verse":50,"text":"E fareis vossos negócios em nome da ordem e em vosso próprio nome."},{"verse":51,"text":"E isto mandei que se fizesse para vossa salvação e também para a salvação deles, em consequência de sua expulsão e do que está para vir."},{"verse":52,"text":"Havendo-se quebrado os convênios por transgressão, cobiça e palavras enganosas —"},{"verse":53,"text":"Portanto, a ordem unida com vossos irmãos está dissolvida, de modo que não estareis ligados a eles, a partir deste momento, a não ser do modo que determinei, por meio de empréstimos, conforme decisão dessa ordem em conselho, segundo permitirem vossas condições e o voto do conselho indicar."},{"verse":54,"text":"E também vos dou um mandamento concernente às mordomias que vos designei."},{"verse":55,"text":"Eis que todas estas propriedades são minhas; do contrário vossa fé é vã e sois considerados hipócritas; e os convênios que fizestes comigo estão quebrados;"},{"verse":56,"text":"E se as propriedades são minhas, então sois mordomos; caso contrário, não sois mordomos."},{"verse":57,"text":"Mas em verdade vos digo: Designei-vos para serdes mordomos da minha casa, sim, verdadeiramente mordomos."},{"verse":58,"text":"E por esta razão mandei que vos organizásseis, sim, para imprimirdes minhas palavras, a plenitude de minhas escrituras, as revelações que vos dei e que daqui em diante vos darei de tempos em tempos —"},{"verse":59,"text":"Com o propósito de edificar minha igreja e reino na Terra e de preparar meu povo para a época, que está próxima, em que habitarei com eles."},{"verse":60,"text":"E preparareis para vós um lugar para a tesouraria e consagrá-lo-eis ao meu nome."},{"verse":61,"text":"E designareis um dentre vós para manter a tesouraria e ele será ordenado para esta bênção."},{"verse":62,"text":"E haverá um selo sobre a tesouraria e todas as coisas sagradas serão depositadas na tesouraria; e homem algum dentre vós a reivindicará, nem mesmo em parte, porque pertencerá a todos vós de comum acordo."},{"verse":63,"text":"E a partir deste momento vo-la dou; e agora, procurai fazer uso da mordomia que vos designei, excluindo-se as coisas sagradas, com o propósito de imprimir estas coisas sagradas como eu disse."},{"verse":64,"text":"E manter-se-á a receita proveniente das coisas sagradas na tesouraria e pôr-se-á um selo sobre ela; e por ninguém será usada nem retirada da tesouraria nem se soltará o selo que lhe será colocado, a não ser pelo voto da ordem ou por mandamento."},{"verse":65,"text":"E assim conservareis a receita das coisas sagradas na tesouraria, para propósitos sacrossantos."},{"verse":66,"text":"E esta será chamada de tesouraria sagrada do Senhor; e manter-se-á um selo sobre ela, para que seja santa e consagrada ao Senhor."},{"verse":67,"text":"E também será preparada uma outra tesouraria e um tesoureiro será designado como encarregado dela; e sobre ela pôr-se-á um selo;"},{"verse":68,"text":"E todos os dinheiros que receberdes em vossa mordomia, provenientes dos melhoramentos que fizerdes nas propriedades que vos designei, sejam casas, terras, animais, ou qualquer outra coisa, com exceção dos escritos santos e sagrados que para mim reservei com propósitos sacrossantos, serão depositados na tesouraria logo que os receberdes, sejam cem ou cinquenta ou vinte ou dez ou cinco."},{"verse":69,"text":"Ou, em outras palavras, se qualquer homem dentre vós obtiver cinco dólares, que os deposite na tesouraria; ou, se obtiver dez ou vinte ou cinquenta ou cem, que faça o mesmo;"},{"verse":70,"text":"E que ninguém dentre vós diga que lhe pertencem, porque não serão considerados seus, nem mesmo em parte."},{"verse":71,"text":"E parte alguma deles será usada nem retirada da tesouraria, a não ser pelo voto e comum acordo da ordem."},{"verse":72,"text":"E este será o voto e o comum acordo da ordem: Quando qualquer homem dentre vós disser ao tesoureiro: Preciso disto para ajudar-me em minha mordomia —"},{"verse":73,"text":"Se forem cinco dólares ou dez dólares ou vinte ou cinquenta ou cem, o tesoureiro lhe dará a soma requerida para ajudá-lo em sua mordomia —"},{"verse":74,"text":"Até que ele seja considerado um transgressor e até que se demonstre claramente perante o conselho da ordem ser ele um mordomo infiel e imprudente."},{"verse":75,"text":"Mas enquanto estiver em plena comunhão com a ordem e for fiel e prudente em sua mordomia, esse será o sinal para o tesoureiro de que não lho deve negar."},{"verse":76,"text":"Mas em caso de transgressão, o tesoureiro ficará sujeito ao conselho e ao voto da ordem."},{"verse":77,"text":"E no caso de o tesoureiro ser considerado um mordomo infiel e imprudente, ele ficará sujeito ao conselho e ao voto da ordem e será removido de sua posição; e um outro será designado em seu lugar."},{"verse":78,"text":"E também, em verdade vos digo com respeito às vossas dívidas: Eis que é a minha vontade que pagueis todas as vossas dívidas."},{"verse":79,"text":"E é a minha vontade que vos humilheis perante mim, e alcanceis essa bênção por vossa diligência e humildade e pela oração da fé."},{"verse":80,"text":"E se fordes diligentes e humildes e exercitardes a oração da fé, eis que abrandarei o coração de vossos credores até eu vos enviar meios para liberar-vos."},{"verse":81,"text":"Portanto, escrevei rapidamente a Nova York e escrevei conforme vos for ditado pelo meu Espírito; e abrandarei o coração de vossos credores para que desistam de vos afligir."},{"verse":82,"text":"E se fordes humildes e fiéis e invocardes meu nome, eis que vos darei a vitória."},{"verse":83,"text":"Faço-vos a promessa de que desta vez sereis libertados de vossa escravidão."},{"verse":84,"text":"Se tiverdes a oportunidade de tomar dinheiro emprestado por centenas ou milhares, até tomardes emprestado o suficiente para libertar-vos dessa escravidão, podeis fazê-lo."},{"verse":85,"text":"E hipotecai, desta vez, as propriedades que pus em vossas mãos, dando vosso nome de comum acordo como bem vos parecer."},{"verse":86,"text":"Dou-vos permissão esta vez; e eis que, se fizerdes as coisas que vos mostrei, segundo meus mandamentos, o mestre não consentirá que sua casa seja destruída, pois todas essas coisas são minhas e vós sois meus mordomos. Assim seja. Amém."}]},{"chapter":105,"verses":[{"verse":1,"text":"Em verdade vos digo, a vós que vos reunistes a fim de conhecer a minha vontade relativa à redenção de meu povo aflito —"},{"verse":2,"text":"Eis que vos digo: Se não fosse por suas transgressões, o meu povo, falando a respeito da igreja e não de indivíduos, já poderia ter sido redimido."},{"verse":3,"text":"Mas eis que não aprenderam a ser obedientes às coisas que exigi de suas mãos, mas estão cheios de toda sorte de maldades e não repartem seu sustento com os pobres e aflitos dentre eles, como convém a santos;"},{"verse":4,"text":"E não estão unidos segundo a união exigida pela lei do reino celestial;"},{"verse":5,"text":"E Sião não pode ser edificada a não ser pelos princípios da lei do reino celestial; de outra forma, não posso recebê-la para mim mesmo."},{"verse":6,"text":"E meu povo precisa ser corrigido até aprender obediência, ainda que seja pelas coisas que sofre."},{"verse":7,"text":"Não falo sobre os que são designados para conduzir meu povo, que são os primeiros élderes de minha igreja, porque não estão todos sob esta condenação;"},{"verse":8,"text":"Mas falo sobre minhas igrejas em outros lugares. Muitos há que dirão: Onde está o Deus deles? Eis que ele os livrará em tempos de dificuldade ou não subiremos a Sião e guardaremos nosso dinheiro."},{"verse":9,"text":"Portanto, em consequência das transgressões de meu povo, é conveniente para mim que meus élderes esperem um pouco a redenção de Sião —"},{"verse":10,"text":"Para que estejam preparados e para que meu povo seja ensinado mais perfeitamente e tenha experiência e conheça mais perfeitamente os seus deveres e as coisas que exijo de suas mãos."},{"verse":11,"text":"E isso não poderá acontecer até que meus élderes sejam investidos de poder do alto."},{"verse":12,"text":"Pois eis que preparei uma grande investidura e bênção para derramar sobre eles, se forem fiéis e perseverarem em humildade diante de mim."},{"verse":13,"text":"Portanto, é conveniente para mim que meus élderes esperem algum tempo pela redenção de Sião."},{"verse":14,"text":"Porque eis que não exijo de suas mãos que lutem as batalhas de Sião; porque, como disse num mandamento anterior, assim também farei — lutarei vossas batalhas."},{"verse":15,"text":"Eis que enviei o destruidor para destruir e assolar meus inimigos; e em poucos anos já não existirão para profanar minha herança e blasfemar meu nome nas terras que consagrei para a reunião de meus santos."},{"verse":16,"text":"Eis que mandei meu servo Joseph Smith Júnior dizer à força de minha casa, sim, meus guerreiros, meus jovens e os homens de meia-idade, que se reunissem para a redenção de meu povo e derrubassem as torres de meus inimigos e dispersassem seus atalaias;"},{"verse":17,"text":"Mas a força da minha casa não deu ouvidos às minhas palavras."},{"verse":18,"text":"Mas, sendo que há alguns que deram ouvidos às minhas palavras, preparei uma bênção e uma investidura para eles, caso continuem fiéis."},{"verse":19,"text":"Ouvi suas orações e aceitarei sua oferta; a mim convém que sejam trazidos até aqui para uma prova de sua fé."},{"verse":20,"text":"E agora, em verdade vos digo: Dou-vos o mandamento de que todos os que subiram até aqui e puderem permanecer nas regiões circunvizinhas, que o façam;"},{"verse":21,"text":"E os que não puderem ficar, que têm famílias no leste, que permaneçam por algum tempo, conforme o que meu servo Joseph lhes indicar;"},{"verse":22,"text":"Pois aconselhá-lo-ei quanto a esse assunto e todas as coisas que ele lhes declarar serão cumpridas."},{"verse":23,"text":"E que todo o meu povo que habita as regiões circunvizinhas seja muito fiel e fervoroso e humilde perante mim; e não revelem as coisas que lhes revelei, até que me pareça prudente que sejam reveladas."},{"verse":24,"text":"Não faleis de julgamentos nem vos vanglorieis da fé ou de obras grandiosas, mas reuni-vos prudentemente, tanto quanto possível numa determinada região, considerando os sentimentos do povo;"},{"verse":25,"text":"E eis que vos concederei favor e graça a seus olhos, para que desfruteis paz e segurança enquanto dizeis ao povo: Praticai juízo e justiça para conosco, de acordo com a lei, e reparai os agravos que sofremos."},{"verse":26,"text":"Ora, eis que vos digo, meus amigos: Deste modo encontrareis favor aos olhos do povo, até que o exército de Israel se torne muito numeroso."},{"verse":27,"text":"E de tempos em tempos abrandarei o coração do povo, como abrandei o coração do Faraó, até que meu servo Joseph Smith Júnior e meus élderes, a quem designei, tenham tempo para reunir a força de minha casa;"},{"verse":28,"text":"E tenham enviado homens prudentes para cumprir o que ordenei concernente à compra de todas as terras que se possam comprar no Condado de Jackson, bem como nos condados vizinhos."},{"verse":29,"text":"Pois é a minha vontade que se comprem essas terras e que, depois de compradas, meus santos as possuam de acordo com as leis de consagração que dei."},{"verse":30,"text":"E depois que essas terras forem compradas, considerarei inocentes os exércitos de Israel por tomarem posse de suas próprias terras, as quais compraram previamente com seu dinheiro; e por derrubarem as torres de meus inimigos que nelas se encontrarem e por dispersarem suas sentinelas e por me vingarem de meus inimigos até a terceira e quarta geração daqueles que me odeiam."},{"verse":31,"text":"Mas, primeiro, que meu exército se torne muito numeroso e que se santifique perante mim, para que se torne belo como o sol e claro como a lua; e que seus estandartes sejam terríveis para todas as nações;"},{"verse":32,"text":"Que os reinos deste mundo sejam constrangidos a reconhecer que o reino de Sião é, realmente, o reino de nosso Deus e seu Cristo; portanto, sujeitemo-nos às suas leis."},{"verse":33,"text":"Em verdade vos digo: É-me conveniente que os primeiros élderes de minha igreja recebam sua investidura do alto em minha casa, que mandei fosse construída para o meu nome na terra de Kirtland."},{"verse":34,"text":"E que os mandamentos que dei com respeito a Sião e sua lei sejam executados e cumpridos após sua redenção."},{"verse":35,"text":"Houve um dia de chamado, mas chegada é a hora para um dia de escolha; e que se escolham os que forem dignos."},{"verse":36,"text":"E será manifestado a meu servo, pela voz do Espírito, quem são os escolhidos; e eles serão santificados;"},{"verse":37,"text":"E, caso sigam o conselho que recebem, terão poder, depois de muitos dias, para realizar todas as coisas concernentes a Sião."},{"verse":38,"text":"E também vos digo: Fazei um apelo de paz, não só ao povo que vos afligiu, mas também a todos os povos;"},{"verse":39,"text":"E erguei um estandarte de paz e proclamai a paz aos confins da Terra;"},{"verse":40,"text":"E fazei propostas de paz àqueles que vos afligiram, segundo a voz do Espírito que está em vós; e todas as coisas reverterão para o vosso bem."},{"verse":41,"text":"Portanto, sede fiéis; e eis que eu estarei convosco até o fim. Assim seja. Amém."}]},{"chapter":106,"verses":[{"verse":1,"text":"É a minha vontade que meu servo Warren A. Cowdery seja designado e ordenado sumo sacerdote presidente da minha igreja, na terra de Freedom e nas regiões circunvizinhas;"},{"verse":2,"text":"E pregue meu evangelho eterno e erga a voz e advirta o povo, não apenas onde mora, mas nos condados vizinhos;"},{"verse":3,"text":"E devote todo seu tempo a este elevado e santo chamado que agora lhe dou, buscando zelosamente o reino do céu e sua retidão; e todas as coisas necessárias lhe serão acrescentadas, pois digno é o obreiro de seu salário."},{"verse":4,"text":"E também, em verdade vos digo: A vinda do Senhor aproxima-se e surpreenderá o mundo como um ladrão na noite —"},{"verse":5,"text":"Portanto, cingi os vossos lombos, para que sejais os filhos da luz; e esse dia não vos surpreenderá como um ladrão."},{"verse":6,"text":"E também, em verdade eu vos digo: Houve alegria no céu quando meu servo Warren se curvou diante de meu cetro e se afastou das artimanhas dos homens;"},{"verse":7,"text":"Portanto, abençoado é meu servo Warren, pois terei misericórdia dele; e, não obstante a vaidade de seu coração, elevá-lo-ei, caso se humilhe perante mim."},{"verse":8,"text":"E conceder-lhe-ei graça e confiança para sustentar-se; e se ele continuar sendo uma testemunha fiel e uma luz para a igreja, preparei-lhe uma coroa nas mansões de meu Pai. Assim seja. Amém."}]},{"chapter":107,"verses":[{"verse":1,"text":"Há, na igreja, dois sacerdócios, a saber: o de Melquisedeque e o Aarônico, que inclui o Sacerdócio Levítico."},{"verse":2,"text":"A razão de o primeiro chamar-se Sacerdócio de Melquisedeque é que Melquisedeque foi um grande sumo sacerdote."},{"verse":3,"text":"Antes de sua época chamava-se Santo Sacerdócio segundo a Ordem do Filho de Deus."},{"verse":4,"text":"Mas por respeito ou reverência ao nome do Ser Supremo, a fim de se evitar a repetição frequente de seu nome, eles, a igreja na antiguidade, deram a esse sacerdócio o nome de Melquisedeque, ou seja, Sacerdócio de Melquisedeque."},{"verse":5,"text":"Todas as outras autoridades ou ofícios da igreja são apêndices desse sacerdócio."},{"verse":6,"text":"Há, porém, duas divisões ou categorias principais — uma é o Sacerdócio de Melquisedeque e a outra é o Sacerdócio Aarônico ou Levítico."},{"verse":7,"text":"O ofício de élder pertence ao Sacerdócio de Melquisedeque."},{"verse":8,"text":"O Sacerdócio de Melquisedeque tem o direito de presidir e tem poder e autoridade sobre todos os ofícios da igreja em todas as épocas do mundo, para administrar em assuntos espirituais."},{"verse":9,"text":"A presidência do sumo sacerdócio segundo a ordem de Melquisedeque tem o direito de oficiar em todos os ofícios da igreja."},{"verse":10,"text":"Os sumos sacerdotes segundo a ordem do Sacerdócio de Melquisedeque têm o direito de oficiar em sua própria posição, sob a direção da presidência, para administrar as coisas espirituais, e também no ofício de élder, sacerdote (da ordem Levítica), mestre, diácono e membro."},{"verse":11,"text":"Um élder tem o direito de oficiar no lugar do sumo sacerdote quando o sumo sacerdote não estiver presente."},{"verse":12,"text":"Ao sumo sacerdote e ao élder cabe administrar nos assuntos espirituais, conforme os convênios e mandamentos da igreja; e eles têm o direito de oficiar em todos estes ofícios da igreja quando não houver autoridades maiores presentes."},{"verse":13,"text":"O segundo sacerdócio chama-se Sacerdócio de Aarão, porque foi conferido a Aarão e sua semente por todas as suas gerações."},{"verse":14,"text":"A razão de ser chamado sacerdócio menor consiste em que ele é um apêndice do maior, ou seja, do Sacerdócio de Melquisedeque; e tem poder para administrar ordenanças exteriores."},{"verse":15,"text":"O bispado é a presidência desse sacerdócio e possui as chaves, ou seja, a autoridade do mesmo."},{"verse":16,"text":"Nenhum homem tem direito legal a esse ofício, de possuir as chaves desse sacerdócio, a menos que seja descendente literal de Aarão."},{"verse":17,"text":"Mas como um sumo sacerdote do Sacerdócio de Melquisedeque tem autoridade para oficiar em todos os ofícios menores, ele pode exercer o ofício de bispo, quando não se puder encontrar um descendente literal de Aarão, desde que seja chamado e designado e ordenado com esse poder pelas mãos da presidência do Sacerdócio de Melquisedeque."},{"verse":18,"text":"O poder e autoridade do maior, ou seja, do Sacerdócio de Melquisedeque, é possuir as chaves de todas as bênçãos espirituais da igreja —"},{"verse":19,"text":"Ter o privilégio de receber os mistérios do reino do céu, de que se lhes abram os céus, de comunicar-se com a assembleia geral e igreja do Primogênito; e usufruir a comunhão e presença de Deus, o Pai, e de Jesus, o mediador do novo convênio."},{"verse":20,"text":"O poder e autoridade do menor, ou seja, do Sacerdócio Aarônico, é possuir as chaves do ministério de anjos e administrar as ordenanças exteriores, a letra do evangelho, o batismo de arrependimento para remissão de pecados, conforme os convênios e mandamentos."},{"verse":21,"text":"Deve, necessariamente, haver presidentes, ou seja, oficiais presidentes que procedem ou são designados dentre os ordenados aos diversos ofícios desses dois sacerdócios."},{"verse":22,"text":"Do Sacerdócio de Melquisedeque, três sumos sacerdotes presidentes, escolhidos pelo grupo, designados e ordenados a esse ofício e apoiados pela confiança, fé e orações da igreja, formam o quórum da Presidência da Igreja."},{"verse":23,"text":"Os doze conselheiros viajantes são chamados para ser os Doze Apóstolos, ou seja, testemunhas especiais do nome de Cristo no mundo todo — diferindo assim dos outros oficiais da igreja nos deveres de seu chamado."},{"verse":24,"text":"E eles formam um quórum igual em autoridade e poder aos três presidentes previamente mencionados."},{"verse":25,"text":"Os Setenta também são chamados para pregar o evangelho e ser testemunhas especiais junto aos gentios e em todo o mundo — diferindo assim dos outros oficiais da igreja nos deveres de seu chamado."},{"verse":26,"text":"E eles formam um quórum igual em autoridade ao das Doze testemunhas especiais ou Apóstolos há pouco mencionados."},{"verse":27,"text":"E toda decisão tomada por um desses quóruns deve sê-lo pelo voto unânime do mesmo; isto é, cada membro de cada quórum deve concordar com suas decisões, a fim de que estas tenham o mesmo poder ou validade entre si —"},{"verse":28,"text":"A maioria pode formar um quórum, quando as circunstâncias não permitirem ser de outro modo —"},{"verse":29,"text":"Se assim não for, suas decisões não têm direito às mesmas bênçãos que as decisões de um quórum de três presidentes tinham antigamente, os quais eram ordenados segundo a ordem de Melquisedeque e eram homens justos e santos."},{"verse":30,"text":"As decisões destes quóruns, ou de qualquer deles, devem ser tomadas com toda retidão, com santidade e humildade de coração, mansidão e longanimidade; e com fé e virtude e conhecimento, temperança, paciência, piedade, bondade fraternal e caridade;"},{"verse":31,"text":"Porque existe a promessa de que se estas coisas sobejarem neles, não serão estéreis no conhecimento do Senhor."},{"verse":32,"text":"E no caso de qualquer decisão destes quóruns ser tomada de maneira iníqua, poderá ser apresentada à assembleia geral dos diversos quóruns, que constituem as autoridades espirituais da igreja; de outra forma, não haverá apelação de suas decisões."},{"verse":33,"text":"Os Doze constituem um Sumo Conselho Presidente Viajante, que tem por fim oficiar em nome do Senhor, sob a direção da Presidência da Igreja, conforme as instituições do céu; e edificar a igreja e regular todos os seus negócios em todas as nações, primeiro junto aos gentios e depois junto aos judeus."},{"verse":34,"text":"Os Setenta agirão em nome do Senhor, sob a direção dos Doze, ou seja, do sumo conselho viajante, edificando a igreja e regulando todos os seus negócios em todas as nações, primeiro junto aos gentios e depois junto aos judeus;"},{"verse":35,"text":"Enviando-se os Doze, que possuem as chaves, para abrirem a porta pela proclamação do evangelho de Jesus Cristo, primeiro junto aos gentios e depois junto aos judeus."},{"verse":36,"text":"Os sumos conselhos permanentes nas estacas de Sião formam um quórum igual em autoridade, nos negócios da igreja e em todas as decisões, ao quórum da presidência ou ao sumo conselho viajante."},{"verse":37,"text":"O sumo conselho de Sião forma um quórum igual em autoridade, nos negócios da igreja e em todas as suas decisões, aos conselhos dos Doze nas estacas de Sião."},{"verse":38,"text":"É dever do sumo conselho viajante recorrer aos Setenta e não a outros, quando houver necessidade de auxílio no preenchimento dos diversos chamados para pregar e administrar o evangelho."},{"verse":39,"text":"É dever dos Doze, em todos os grandes ramos da igreja, ordenar ministros evangélicos conforme lhes for designado por revelação —"},{"verse":40,"text":"Confirmou-se que a ordem desse sacerdócio é para ser transmitida de pai para filho e pertence por direito aos descendentes literais da semente escolhida, a quem foram feitas as promessas."},{"verse":41,"text":"Essa ordem foi instituída nos dias de Adão e transmitida, por linhagem, da seguinte maneira:"},{"verse":42,"text":"De Adão a Sete, que foi ordenado por Adão com a idade de sessenta e nove anos e por ele abençoado três anos antes de sua morte (de Adão); e recebeu a promessa de Deus, por seu pai, de que sua posteridade seria a escolhida do Senhor e preservada até o fim da Terra;"},{"verse":43,"text":"Porque ele (Sete) foi um homem perfeito e sua semelhança era a semelhança expressa de seu pai, tanto que parecia ser como o pai em todas as coisas, dele podendo distinguir-se apenas pela idade."},{"verse":44,"text":"Enos foi ordenado com a idade de cento e trinta e quatro anos e quatro meses, pelas mãos de Adão."},{"verse":45,"text":"Deus chamou Cainã no deserto quando ele tinha quarenta anos de idade; e ele encontrou Adão quando viajava para Cedolamaque. Cainã tinha oitenta e sete anos de idade quando recebeu sua ordenação."},{"verse":46,"text":"Maalalel tinha quatrocentos e noventa e seis anos e sete dias de idade quando foi ordenado pelas mãos de Adão, que também o abençoou."},{"verse":47,"text":"Jarede tinha duzentos anos quando foi ordenado pelas mãos de Adão, que também o abençoou."},{"verse":48,"text":"Enoque tinha vinte e cinco anos quando foi ordenado pelas mãos de Adão; e tinha sessenta e cinco quando Adão o abençoou."},{"verse":49,"text":"E ele viu o Senhor e andou com ele e estava diante de sua face continuamente; e andou com Deus trezentos e sessenta e cinco anos, tendo quatrocentos e trinta anos quando foi transladado."},{"verse":50,"text":"Matusalém tinha cem anos quando foi ordenado pelas mãos de Adão."},{"verse":51,"text":"Lameque tinha trinta e dois anos quando foi ordenado pelas mãos de Sete."},{"verse":52,"text":"Noé tinha dez anos quando foi ordenado pelas mãos de Matusalém."},{"verse":53,"text":"Três anos antes de sua morte, Adão chamou Sete, Enos, Cainã, Maalalel, Jarede, Enoque e Matusalém, todos sumos sacerdotes, e também o restante de sua posteridade que era justa, ao vale de Adão-ondi-Amã; e lá lhes conferiu sua última bênção."},{"verse":54,"text":"E o Senhor apareceu a eles; e ergueram-se e abençoaram Adão e chamaram-no Miguel, o príncipe, o arcanjo."},{"verse":55,"text":"E o Senhor confortou Adão e disse-lhe: Coloquei-te à cabeça; uma multidão de nações procederá de ti e deles serás por príncipe eternamente."},{"verse":56,"text":"E Adão levantou-se no meio da congregação; e embora curvado pela idade, estando cheio do Espírito Santo, predisse tudo que sucederia a sua posteridade, até a última geração."},{"verse":57,"text":"Todas estas coisas foram escritas no livro de Enoque e delas se testificará no devido tempo."},{"verse":58,"text":"É dever dos Doze, também, ordenar e organizar todos os outros oficiais da igreja, conforme a revelação que diz:"},{"verse":59,"text":"À igreja de Cristo na terra de Sião, como acréscimo às leis da igreja referentes a seus negócios —"},{"verse":60,"text":"Em verdade vos digo, diz o Senhor dos Exércitos: São necessários élderes presidentes para presidir os que têm o ofício de élder;"},{"verse":61,"text":"E também sacerdotes para presidir os que têm o ofício de sacerdote;"},{"verse":62,"text":"E também mestres para presidir, semelhantemente, os que têm o ofício de mestre e também os diáconos —"},{"verse":63,"text":"Portanto, de diácono para mestre e de mestre para sacerdote e de sacerdote para élder, cada um, respectivamente, conforme for designado, segundo os convênios e mandamentos da igreja;"},{"verse":64,"text":"Depois vem o sumo sacerdócio, que é o maior de todos."},{"verse":65,"text":"Portanto, é preciso que se indique alguém do sumo sacerdócio para presidir o sacerdócio; e ele será chamado presidente do sumo sacerdócio da Igreja;"},{"verse":66,"text":"Ou, em outras palavras, o Sumo Sacerdote Presidente do Sumo Sacerdócio da Igreja."},{"verse":67,"text":"Dele procederá a administração de ordenanças e bênçãos para a igreja, pela imposição das mãos."},{"verse":68,"text":"Portanto, o ofício de um bispo não lhe é igual; pois o ofício de um bispo é administrar todas as coisas materiais;"},{"verse":69,"text":"Contudo, um bispo precisa ser escolhido dentre o sumo sacerdócio, a menos que seja descendente literal de Aarão;"},{"verse":70,"text":"Pois, a menos que seja descendente literal de Aarão, não pode possuir as chaves desse sacerdócio."},{"verse":71,"text":"Contudo, um sumo sacerdote, isto é, segundo a ordem de Melquisedeque, pode ser designado para ministrar as coisas terrenas, tendo conhecimento delas pelo Espírito da verdade;"},{"verse":72,"text":"E também para ser juiz em Israel, cuidar dos negócios da igreja, julgar transgressores segundo o testemunho que lhe seja apresentado de acordo com as leis, com o auxílio de seus conselheiros a quem tiver escolhido ou escolher dentre os élderes da igreja."},{"verse":73,"text":"Esse é o dever de um bispo que não seja descendente literal de Aarão, mas que tiver sido ordenado ao sumo sacerdócio segundo a ordem de Melquisedeque."},{"verse":74,"text":"Assim ele será juiz, sim, juiz comum entre os habitantes de Sião ou numa estaca de Sião ou em qualquer ramo da igreja onde for designado para esse ministério, até que as fronteiras de Sião se expandam e torne-se necessário ter outros bispos ou juízes em Sião ou em outros lugares."},{"verse":75,"text":"E se outros bispos forem designados, agirão no mesmo ofício."},{"verse":76,"text":"Mas um descendente literal de Aarão tem direito legal à presidência deste sacerdócio, às chaves deste ministério, a agir independentemente no ofício de bispo, sem conselheiros, e a atuar como juiz em Israel, exceto no caso de julgamento do presidente do sumo sacerdócio segundo a ordem de Melquisedeque."},{"verse":77,"text":"E a decisão de qualquer destes conselhos deve concordar com o mandamento que diz:"},{"verse":78,"text":"Também, em verdade vos digo: Os assuntos mais importantes da igreja e os casos mais difíceis da igreja, caso a decisão dos bispos ou juízes não seja satisfatória, serão transmitidos e encaminhados ao conselho da igreja, perante a presidência do sumo sacerdócio."},{"verse":79,"text":"E a presidência do conselho do sumo sacerdócio terá poder para chamar outros sumos sacerdotes, sim, doze, para auxiliarem como conselheiros; e assim a presidência do sumo sacerdócio e seus conselheiros terão poder para decidir, baseando-se em testemunhos, de acordo com as leis da igreja."},{"verse":80,"text":"E após essa decisão o caso não mais será lembrado perante o Senhor; porque este é o mais alto conselho da igreja de Deus e tem a decisão final em controvérsias sobre assuntos espirituais."},{"verse":81,"text":"Nenhuma pessoa que pertença à igreja está isenta deste conselho da igreja."},{"verse":82,"text":"E se um presidente do sumo sacerdócio transgredir, será chamado perante o conselho comum da igreja, que será auxiliado por doze conselheiros do sumo sacerdócio;"},{"verse":83,"text":"E sua decisão a respeito dele porá fim à controvérsia sobre ele."},{"verse":84,"text":"Assim, ninguém estará isento da justiça e das leis de Deus, para que todas as coisas sejam feitas em ordem e com solenidade perante ele, de acordo com a verdade e a retidão."},{"verse":85,"text":"E também, em verdade vos digo: O dever de um presidente do ofício de diácono é presidir doze diáconos, sentar-se em conselho com eles e ensinar-lhes seus deveres, edificando-se uns aos outros conforme indicado nos convênios."},{"verse":86,"text":"E também o dever do presidente do ofício de mestre é presidir vinte e quatro mestres e sentar-se em conselho com eles, ensinando-lhes os deveres de seu ofício, como dados nos convênios."},{"verse":87,"text":"Também o dever do presidente do Sacerdócio de Aarão é presidir quarenta e oito sacerdotes e sentar-se em conselho com eles para ensinar-lhes os deveres de seu ofício, como dados nos convênios —"},{"verse":88,"text":"Esse presidente deve ser um bispo; porque este é um dos deveres desse sacerdócio."},{"verse":89,"text":"Também o dever do presidente do ofício de élder é presidir noventa e seis élderes e sentar-se em conselho com eles e ensinar-lhes segundo os convênios."},{"verse":90,"text":"Essa presidência é distinta da dos setenta e destina-se aos que não viajam pelo mundo todo."},{"verse":91,"text":"E também o dever do presidente do sumo sacerdócio é presidir toda a igreja e ser semelhante a Moisés —"},{"verse":92,"text":"Eis que nisto há sabedoria; sim, em ser um vidente, um revelador, um tradutor e um profeta, possuindo todos os dons de Deus que ele confere ao cabeça da igreja."},{"verse":93,"text":"E está de acordo com a visão que mostra a ordem dos Setenta, que eles devem ter sete presidentes para presidi-los, escolhidos dentre os setenta;"},{"verse":94,"text":"E o sétimo presidente desses presidentes presidirá os seis;"},{"verse":95,"text":"E esses sete presidentes escolherão outros setenta além dos primeiros setenta aos quais eles pertencem e devem presidi-los;"},{"verse":96,"text":"E também outros setenta, até sete vezes setenta, se o trabalho da vinha necessariamente o exigir."},{"verse":97,"text":"E esses setenta serão ministros viajantes, primeiro junto aos gentios e também junto aos judeus."},{"verse":98,"text":"Ao passo que outros oficiais da igreja, não pertencentes aos Doze nem aos Setenta, não têm a responsabilidade de viajar por todas as nações, mas viajarão como lhes permitir sua situação, embora possam ocupar ofícios tão elevados e de igual responsabilidade na igreja."},{"verse":99,"text":"Portanto, agora, que todo homem aprenda o seu dever e a agir no ofício para o qual for designado, com toda a diligência."},{"verse":100,"text":"Aquele que for preguiçoso não será considerado digno de permanecer; e o que não aprender seu dever e não mostrar ter sido aprovado não será considerado digno de permanecer. Assim seja. Amém."}]},{"chapter":108,"verses":[{"verse":1,"text":"Em verdade, assim te diz o Senhor, meu servo Lyman: Perdoados são os teus pecados, porque obedeceste à minha voz e vieste aqui esta manhã para receber conselhos daquele que designei."},{"verse":2,"text":"Portanto, que se tranquilize a tua alma com respeito à tua posição espiritual e não mais resistas à minha voz."},{"verse":3,"text":"E levanta-te e sê mais cuidadoso daqui em diante na observância das promessas que fizeste e fazes; e serás abençoado com bênçãos sumamente grandes."},{"verse":4,"text":"Espera pacientemente até que meus servos convoquem a assembleia solene; então serás lembrado com os primeiros de meus élderes e receberás o direito, por ordenação, com o restante de meus élderes por mim escolhidos."},{"verse":5,"text":"Eis que essa é a promessa do Pai a ti, se continuares fiel."},{"verse":6,"text":"E cumprir-se-á sobre ti, no dia em que receberes o direito de pregar meu evangelho onde eu te enviar e a partir desse momento."},{"verse":7,"text":"Portanto, fortalece os teus irmãos em todas as tuas conversas, em todas as tuas orações, em todas as tuas exortações, e em todos os teus feitos."},{"verse":8,"text":"E eis que eu estou contigo para abençoar-te e livrar-te para sempre. Amém."}]},{"chapter":109,"verses":[{"verse":1,"text":"Graças sejam dadas a teu nome, ó Senhor Deus de Israel, que cumpres os convênios e mostras misericórdia aos teus servos que andam retamente perante ti de todo o coração —"},{"verse":2,"text":"Tu, que mandaste teus servos construírem uma casa ao teu nome neste lugar [Kirtland]."},{"verse":3,"text":"E agora vês, ó Senhor, que teus servos agiram de acordo com teu mandamento."},{"verse":4,"text":"E agora te pedimos, Pai Santo, em nome de Jesus Cristo, o Filho de teu seio, em cujo nome apenas se pode administrar a salvação aos filhos dos homens; rogamos-te, ó Senhor, que aceites esta casa, obra de nossas mãos, de teus servos, que nos mandaste construir."},{"verse":5,"text":"Pois sabes que fizemos esta obra em meio a grandes tribulações; e, em nossa pobreza, demos de nossos bens para a construção de uma casa a teu nome, a fim de que o Filho do Homem tivesse um lugar onde se manifestar a seu povo."},{"verse":6,"text":"E como disseste em uma revelação que nos foi dada, chamando-nos de teus amigos, dizendo: Convocai vossa assembleia solene, como vos ordenei;"},{"verse":7,"text":"E como todos não têm fé, buscai diligentemente e ensinai-vos uns aos outros palavras de sabedoria; sim, nos melhores livros buscai palavras de sabedoria; procurai conhecimento, sim, pelo estudo e também pela fé;"},{"verse":8,"text":"Organizai-vos; preparai todas as coisas necessárias e estabelecei uma casa, sim, uma casa de oração, uma casa de jejum, uma casa de fé, uma casa de aprendizado, uma casa de glória, uma casa de ordem, uma casa de Deus;"},{"verse":9,"text":"Para que nela entreis em nome do Senhor; para que dela saiais em nome do Senhor; para que todas as vossas saudações sejam em nome do Senhor, com mãos elevadas ao Altíssimo —"},{"verse":10,"text":"E agora, Pai Santo, pedimos-te que nos assistas, a nós, teu povo, com tua graça, na convocação de nossa assembleia solene, a fim de que seja feita para tua honra e para tua divina aceitação;"},{"verse":11,"text":"E de uma forma que sejamos considerados dignos, a teus olhos, de assegurar o cumprimento das promessas que fizeste a nós, teu povo, nas revelações que nos foram dadas;"},{"verse":12,"text":"Para que tua glória descanse sobre teu povo e sobre esta tua casa que agora dedicamos a ti, para que seja santificada e consagrada como santa; e para que tua santa presença esteja continuamente nesta casa;"},{"verse":13,"text":"E para que todas as pessoas que atravessarem o umbral da casa do Senhor sintam o teu poder e sintam-se compelidos a reconhecer que tu a santificaste e que ela é a tua casa, um lugar de tua santidade."},{"verse":14,"text":"E permite, Pai Santo, que a todos os que adorarem nesta casa sejam ensinadas palavras de sabedoria dos melhores livros; e que procurem conhecimento, sim, pelo estudo e também pela fé, como disseste;"},{"verse":15,"text":"E que cresçam em ti e recebam a plenitude do Espírito Santo e organizem-se de acordo com as tuas leis e preparem-se para obter todas as coisas necessárias;"},{"verse":16,"text":"E que esta casa seja uma casa de oração, uma casa de jejum, uma casa de fé, uma casa de glória e de Deus, sim, tua casa;"},{"verse":17,"text":"Que todas as entradas de teu povo nesta casa sejam em nome do Senhor;"},{"verse":18,"text":"Que todas as suas saídas desta casa sejam em nome do Senhor;"},{"verse":19,"text":"E que todas as suas saudações sejam em nome do Senhor, com mãos santas elevadas ao Altíssimo;"},{"verse":20,"text":"E que não se permita que qualquer coisa imunda entre em tua casa para profaná-la;"},{"verse":21,"text":"E quando teu povo transgredir, quem quer que seja, que se arrependa rapidamente e volte para ti e encontre favor a teus olhos e que lhe sejam restituídas as bênçãos que tu ordenaste que fossem derramadas sobre os que te reverenciassem em tua casa."},{"verse":22,"text":"E rogamos-te, Pai Santo, que teus servos saiam desta casa armados de teu poder; e que teu nome esteja sobre eles e tua glória ao redor deles e que teus anjos os guardem;"},{"verse":23,"text":"E que deste lugar levem novas sumamente grandes e gloriosas aos confins da Terra, em verdade para que saibam que esta é tua obra e que estendeste a mão para cumprir o que disseste pela boca dos profetas, concernente aos últimos dias."},{"verse":24,"text":"Rogamos-te, Pai Santo, que estabeleças o povo que adorará e honrosamente terá um nome e uma posição nesta tua casa por todas as gerações e pela eternidade;"},{"verse":25,"text":"Que arma alguma formada contra eles prospere; que o que cavar uma cova para eles, nela caia ele mesmo;"},{"verse":26,"text":"Que nenhuma combinação iníqua tenha poder para levantar-se e prevalecer contra teu povo, sobre quem se colocará teu nome nesta casa;"},{"verse":27,"text":"E se algum povo se erguer contra este povo, que tua ira se acenda contra ele;"},{"verse":28,"text":"E se ferir este povo, tu o ferirás; batalharás por teu povo como o fizeste nos dias de batalha, para que sejam libertados das mãos de todos os seus inimigos."},{"verse":29,"text":"Rogamos-te, Pai Santo, que confundas e surpreendas e tragas vergonha e confusão a todos os que espalharam relatos mentirosos por toda parte sobre teu servo ou servos, caso não se arrependam quando o evangelho eterno for proclamado a seus ouvidos;"},{"verse":30,"text":"E que todas as suas obras sejam reduzidas a nada e varridas pela saraiva e pelos julgamentos que enviarás sobre eles, em tua ira, para que tenham fim as mentiras e calúnias contra o teu povo."},{"verse":31,"text":"Porque sabes, ó Senhor, que teus servos são inocentes perante ti ao prestarem testemunho de teu nome, pelo qual têm sofrido estas coisas."},{"verse":32,"text":"Portanto, te imploramos uma completa e total libertação deste jugo;"},{"verse":33,"text":"Retira-o, ó Senhor; retira-o do pescoço de teus servos pelo teu poder, para que nos ergamos no meio desta geração e façamos tua obra."},{"verse":34,"text":"Ó Jeová, tem misericórdia deste povo e, como todos os homens pecam, perdoa as transgressões de teu povo; e que sejam apagadas para sempre."},{"verse":35,"text":"Que a unção de teus ministros seja selada sobre eles com poder do alto."},{"verse":36,"text":"Que se cumpra neles, como naqueles no dia de Pentecostes; que se derrame o dom das línguas sobre teu povo, sim, línguas repartidas como que de fogo, e sua interpretação."},{"verse":37,"text":"E que tua casa se encha, como com um vento veemente e impetuoso, de tua glória."},{"verse":38,"text":"Põe sobre teus servos o testemunho do convênio, para que, quando saírem para proclamar tua palavra, selem a lei e preparem o coração de teus santos para todos esses julgamentos que estás prestes a enviar, em tua ira, sobre os habitantes da Terra, por causa de suas transgressões, a fim de que teu povo não desfaleça no dia da angústia."},{"verse":39,"text":"E em qualquer cidade que teus servos entrarem, e o povo dessa cidade aceitar o seu testemunho, concede a tua paz e a tua salvação a essa cidade; para que eles reúnam os justos dessa cidade, a fim de que venham a Sião ou às suas estacas, os lugares designados por ti, com cânticos de eterna alegria;"},{"verse":40,"text":"E até que isso se realize, não permitas que teus julgamentos caiam sobre essa cidade."},{"verse":41,"text":"E em qualquer cidade que teus servos entrarem e o povo dessa cidade não aceitar seu testemunho e teus servos exortarem-nos a que se salvem desta geração rebelde, que se faça a essa cidade de acordo com aquilo que disseste pela boca de teus profetas."},{"verse":42,"text":"Mas livra, ó Jeová, nós te imploramos, teus servos de suas mãos e limpa-os de seu sangue."},{"verse":43,"text":"Ó Senhor, não nos deleitamos com a destruição de nossos semelhantes; suas almas são preciosas a teus olhos;"},{"verse":44,"text":"Mas tua palavra tem que se cumprir. Ajuda teus servos a dizerem, com o auxílio de tua graça: Seja feita a tua vontade, ó Senhor, e não a nossa."},{"verse":45,"text":"Sabemos que disseste, pela boca de teus profetas, coisas terríveis concernentes aos iníquos nos últimos dias — que derramarás teus julgamentos sem medida;"},{"verse":46,"text":"Portanto, ó Senhor, livra teu povo da calamidade dos iníquos; permite a teus servos que selem a lei e liguem o testemunho, a fim de que estejam preparados para o dia da queima."},{"verse":47,"text":"Pedimos-te, Pai Santo, que te lembres daqueles que foram expulsos pelos habitantes do Condado de Jackson, Missouri, das terras de sua herança; e retira, ó Senhor, o jugo da aflição que sobre eles foi posto."},{"verse":48,"text":"Tu sabes, ó Senhor, que eles têm sido grandemente oprimidos e afligidos por homens iníquos; e nosso coração transborda de tristeza por causa de suas penosas cargas."},{"verse":49,"text":"Ó Senhor, até quando permitirás que este povo suporte essa aflição e que os clamores de seus inocentes ascendam a teus ouvidos e que seu sangue suba a ti como testemunho, sem mostrares teu testemunho em seu favor?"},{"verse":50,"text":"Tem misericórdia, ó Senhor, da turba iníqua que expulsou o teu povo; que eles cessem de saquear, que se arrependam de seus pecados se lhes for possível arrepender-se;"},{"verse":51,"text":"Mas se não o fizerem, desnuda teu braço, ó Senhor, e redime aquilo que estabeleceste como Sião para teu povo."},{"verse":52,"text":"E se não puder ser de outro modo, para que a causa de teu povo não fracasse perante ti, que tua ira se acenda e tua indignação caia sobre eles, para que sejam aniquilados, tanto raízes como ramos, de debaixo do céu;"},{"verse":53,"text":"Mas caso se arrependam, és clemente e misericordioso e desviarás tua ira quando contemplares a face de teu Ungido."},{"verse":54,"text":"Tem misericórdia, ó Senhor, de todas as nações da Terra; tem misericórdia dos governantes de nosso país; que os princípios que foram tão honrosa e nobremente defendidos por nossos pais, ou seja, a Constituição de nosso país, sejam estabelecidos para sempre."},{"verse":55,"text":"Lembra-te dos reis, dos príncipes, dos nobres e dos grandes da Terra e de todos os povos e das igrejas, de todos os pobres, dos necessitados e dos aflitos da Terra;"},{"verse":56,"text":"Que se abrande o coração deles quando teus servos saírem de tua casa, ó Jeová, para prestar testemunho de teu nome; que seus preconceitos cedam diante da verdade e teu povo obtenha favor aos olhos de todos;"},{"verse":57,"text":"Para que todos os confins da Terra saibam que nós, teus servos, ouvimos a tua voz e que tu nos enviaste;"},{"verse":58,"text":"Que dentre todos esses, teus servos, os filhos de Jacó, reúnam os justos para construírem uma cidade santa a teu nome, como lhes ordenaste."},{"verse":59,"text":"Rogamos-te que estabeleças outras estacas para Sião além desta, para que a reunião de teu povo prossiga em grande poder e majestade, a fim de que tua obra se abrevie em retidão."},{"verse":60,"text":"Agora, ó Senhor, estas palavras proferimos diante de ti a respeito das revelações e mandamentos que nos deste, a nós que somos identificados com os gentios."},{"verse":61,"text":"Mas sabes que tens um grande amor pelos filhos de Jacó, os quais por longo tempo têm estado dispersos pelas montanhas, em um dia nublado e de escuridão."},{"verse":62,"text":"Rogamos-te, portanto, que tenhas misericórdia dos filhos de Jacó, para que Jerusalém, desta hora em diante, comece a redimir-se;"},{"verse":63,"text":"E o jugo da servidão comece a retirar-se da casa de Davi;"},{"verse":64,"text":"E os filhos de Judá comecem a regressar às terras que deste a Abraão, seu pai."},{"verse":65,"text":"E faças com que os remanescentes de Jacó, que foram amaldiçoados e feridos por causa de suas transgressões, convertam-se de sua condição indômita e selvagem à plenitude do evangelho eterno;"},{"verse":66,"text":"Que deponham suas armas de carnificina e cessem suas rebeliões."},{"verse":67,"text":"E que todos os remanescentes dispersos de Israel, que foram impelidos para os confins da Terra, conheçam a verdade, creiam no Messias e sejam redimidos da opressão e regozijem-se perante ti."},{"verse":68,"text":"Ó Senhor, lembra-te de teu servo Joseph Smith Júnior e de todas as suas aflições e perseguições — como ele fez convênio com Jeová e um voto a ti, ó Poderoso Deus de Jacó — e dos mandamentos que lhe deste; e de que sinceramente se tem esforçado para fazer a tua vontade."},{"verse":69,"text":"Tem misericórdia, ó Senhor, de sua esposa e filhos; para que sejam exaltados em tua presença e preservados por tua mão protetora."},{"verse":70,"text":"Tem misericórdia de todos os seus parentes próximos, que seus preconceitos sejam derrubados e varridos como que por uma inundação; que se convertam e sejam redimidos com Israel e saibam que tu és Deus."},{"verse":71,"text":"Lembra-te, ó Senhor, dos presidentes, sim, de todos os presidentes de tua igreja, que tua mão direita os exalte com todas as suas famílias e seus parentes próximos; que se perpetuem seus nomes e que se conservem na lembrança eternamente, de geração em geração."},{"verse":72,"text":"Lembra-te de toda a tua igreja, ó Senhor, com todas as suas famílias e todos os seus parentes próximos, com todos os seus enfermos e aflitos, com todos os pobres e mansos da Terra; para que o reino que estabeleceste sem mãos se transforme em uma grande montanha e encha toda a Terra;"},{"verse":73,"text":"Que tua igreja saia do deserto da escuridão e resplandeça formosa como a lua, brilhante como o sol e terrível como um exército com estandartes;"},{"verse":74,"text":"E adorne-se como uma noiva para o dia em que desvendares os céus e fizeres com que os montes escoem em tua presença e os vales se exaltem e os lugares acidentados se aplainem, a fim de que tua glória encha a Terra;"},{"verse":75,"text":"Para que, quando a trombeta soar para os mortos, sejamos arrebatados na nuvem para encontrar-te e estejamos com o Senhor para sempre;"},{"verse":76,"text":"Que nossas vestes sejam puras, que nos trajemos com mantos de retidão, com palmas em nossas mãos e coroas de glória em nossa cabeça; e colhamos alegria eterna por todos os nossos sofrimentos."},{"verse":77,"text":"Ó Senhor Deus Todo-Poderoso, ouve estas nossas súplicas e responde-nos do céu, tua santa habitação, onde te assentas entronizado, com glória, honra, poder, majestade, força, domínio, verdade, justiça, juízo, misericórdia e plenitude infinita, de eternidade em eternidade."},{"verse":78,"text":"Ó ouve, ó ouve, ó ouve-nos, ó Senhor! E responde a estas súplicas e aceita a dedicação desta casa a ti, obra de nossas mãos, que construímos ao teu nome;"},{"verse":79,"text":"E também esta igreja, para que se ponha sobre ela o teu nome. E ajuda-nos, pelo poder de teu Espírito, para que misturemos nossa voz aos brilhantes e resplandescentes serafins que cercam teu trono com aclamações de louvor, cantando: Hosana a Deus e ao Cordeiro!"},{"verse":80,"text":"E que estes, teus ungidos, vistam-se de salvação e teus santos gritem de alegria. Amém e Amém."}]},{"chapter":110,"verses":[{"verse":1,"text":"Retirou-se o véu de nossa mente e abriram-se os olhos de nosso entendimento."},{"verse":2,"text":"Vimos o Senhor de pé no parapeito do púlpito, diante de nós; e sob seus pés havia um calçamento de ouro puro, da cor de âmbar."},{"verse":3,"text":"Os seus olhos eram como uma labareda de fogo; os cabelos de sua cabeça eram brancos como a pura neve; o seu semblante resplandecia mais do que o brilho do sol; e a sua voz era como o ruído de muitas águas, sim, a voz de Jeová, que dizia:"},{"verse":4,"text":"Eu sou o primeiro e o último; sou o que vive, sou o que foi morto; eu sou o vosso advogado junto ao Pai."},{"verse":5,"text":"Eis que perdoados vos são vossos pecados; estais limpos diante de mim; portanto, erguei a cabeça e regozijai-vos."},{"verse":6,"text":"Que se regozije o coração de vossos irmãos e o coração de todo o meu povo, que com sua força construiu esta casa ao meu nome."},{"verse":7,"text":"Pois eis que aceitei esta casa, e meu nome aqui estará; e manifestar-me-ei a meu povo com misericórdia nesta casa."},{"verse":8,"text":"Sim, aparecerei aos meus servos e falar-lhes-ei com a minha própria voz, se o meu povo guardar os meus mandamentos e não profanar esta casa santa."},{"verse":9,"text":"Sim, o coração de milhares e dezenas de milhares grandemente se regozijará, em consequência das bênçãos que serão derramadas e da investidura com que os meus servos foram investidos nesta casa."},{"verse":10,"text":"E a fama desta casa espalhar-se-á por terras estrangeiras; e este é o princípio da bênção que será derramada sobre a cabeça de meu povo. Assim seja. Amém."},{"verse":11,"text":"Depois de encerrar-se esta visão, os céus tornaram-se a abrir e Moisés apareceu diante de nós e conferiu-nos as chaves para coligar Israel das quatro partes da Terra e trazer as dez tribos da terra do norte."},{"verse":12,"text":"Depois disto, Elias apareceu e conferiu-nos a dispensação do evangelho de Abraão, dizendo que em nós e em nossa semente todas as gerações depois de nós seriam abençoadas."},{"verse":13,"text":"Concluída essa visão, outra grande e gloriosa visão abriu-se para nós; pois Elias, o profeta, que fora levado ao céu sem experimentar a morte, apareceu diante de nós e disse:"},{"verse":14,"text":"Eis que é chegado plenamente o tempo proferido pela boca de Malaquias — testificando que ele [Elias, o profeta] seria enviado antes que viesse o grande e terrível dia do Senhor —"},{"verse":15,"text":"Para voltar o coração dos pais para os filhos e os filhos para os pais, a fim de que a Terra toda não seja ferida com uma maldição —"},{"verse":16,"text":"Portanto, as chaves desta dispensação são confiadas às vossas mãos; e assim sabereis que o grande e terrível dia do Senhor está perto, sim, às portas."}]},{"chapter":111,"verses":[{"verse":1,"text":"Eu, o Senhor vosso Deus, não estou descontente com vossa viagem, apesar de vossa insensatez."},{"verse":2,"text":"Tenho muitos tesouros para vós nesta cidade, para o benefício de Sião, e muita gente, nesta cidade, que reunirei no devido tempo para o benefício de Sião, por intermédio de vós."},{"verse":3,"text":"Convém, portanto, que traveis conhecimento com homens desta cidade, como fordes guiados e como vos for indicado."},{"verse":4,"text":"E acontecerá que, no devido tempo, porei esta cidade em vossas mãos para que tenhais poder sobre ela, de modo que não descubram vossos planos secretos; e sua riqueza no que diz respeito a ouro e prata será vossa."},{"verse":5,"text":"Não vos preocupeis com vossas dívidas, porque vos darei poder para pagá-las."},{"verse":6,"text":"Não vos preocupeis com Sião, porque serei misericordioso com ela."},{"verse":7,"text":"Permanecei neste lugar e nas regiões circunvizinhas;"},{"verse":8,"text":"E o lugar onde é a minha vontade que permaneçais, principalmente, ser-vos-á indicado pela paz e poder de meu Espírito, que fluirá para vós."},{"verse":9,"text":"Esse local podereis alugar. E indagai diligentemente a respeito dos habitantes mais antigos e fundadores desta cidade;"},{"verse":10,"text":"Pois há mais de um tesouro para vós nesta cidade."},{"verse":11,"text":"Portanto, sede prudentes como as serpentes, mas sem pecado; e ordenarei todas as coisas para o vosso bem, tão depressa quanto fordes capazes de recebê-las. Amém."}]},{"chapter":112,"verses":[{"verse":1,"text":"Em verdade, assim diz o Senhor a ti, meu servo Thomas: Ouvi tuas orações; e tuas esmolas subiram como um memorial diante de mim, em favor daqueles teus irmãos que foram escolhidos e ordenados para prestar testemunho de meu nome e enviá-lo a todas as nações, tribos, línguas e povos pela instrumentalidade de meus servos."},{"verse":2,"text":"Em verdade eu te digo: Havia algumas coisas em teu coração e contigo com as quais eu, o Senhor, não estava contente."},{"verse":3,"text":"Contudo, sendo que te humilhaste, serás exaltado; portanto, todos os teus pecados são perdoados."},{"verse":4,"text":"Que teu coração tenha bom ânimo perante minha face; e prestarás testemunho de meu nome, não só aos gentios como também aos judeus; e enviarás minha palavra aos confins da Terra."},{"verse":5,"text":"Contende, portanto, toda manhã; e dia após dia emite a tua voz de advertência; e quando vier a noite, não permitas que os habitantes da Terra adormeçam por causa de tuas palavras."},{"verse":6,"text":"Que se conheça tua morada em Sião e não removas tua casa; porque eu, o Senhor, tenho uma grande obra para fazeres, proclamando meu nome entre os filhos dos homens."},{"verse":7,"text":"Portanto, cinge os teus lombos para o trabalho. Que se calcem também os teus pés, pois foste escolhido e o teu caminho fica entre as montanhas e entre muitas nações."},{"verse":8,"text":"E por tua palavra muitos soberbos serão humilhados e por tua palavra muitos humildes serão exaltados."},{"verse":9,"text":"A tua voz será uma repreensão para o transgressor; e diante de tua repreensão, que a língua do caluniador cesse sua perversidade."},{"verse":10,"text":"Sê humilde; e o Senhor teu Deus te conduzirá pela mão, e te dará resposta às tuas orações."},{"verse":11,"text":"Conheço teu coração e ouvi tuas orações a respeito de teus irmãos. Não sejas parcial em relação a eles, amando-os mais que muitos outros, mas ama-os como a ti mesmo; e que sobeje teu amor por todos os homens e por todos os que amam meu nome."},{"verse":12,"text":"E ora por teus irmãos dos Doze. Admoesta-os severamente por causa de meu nome e que sejam admoestados por todos os seus pecados; e, perante mim, sê fiel a meu nome."},{"verse":13,"text":"E depois de suas tentações e muitas tribulações, eis que eu, o Senhor, procurá-los-ei; e se não endurecerem o coração e não enrijecerem a cerviz contra mim, serão convertidos e curá-los-ei."},{"verse":14,"text":"Ora, digo a ti, e o que digo a ti digo a todos os Doze: Erguei-vos e cingi vossos lombos; tomai vossa cruz, segui-me e apascentai minhas ovelhas."},{"verse":15,"text":"Não vos exalteis; não vos rebeleis contra meu servo Joseph; pois, em verdade vos digo, que estou com ele e minha mão estará sobre ele; e as chaves que lhe dei, como também a vós, não serão tiradas dele até que eu venha."},{"verse":16,"text":"Em verdade eu te digo, meu servo Thomas: És o homem que escolhi para possuir as chaves de meu reino, no que diz respeito aos Doze, entre todas as nações —"},{"verse":17,"text":"A fim de que sejas meu servo, para abrir a porta do reino em todos os lugares em que o meu servo Joseph e meu servo Sidney e meu servo Hyrum não puderem ir;"},{"verse":18,"text":"Porque sobre eles, por algum tempo, depositei o fardo de todas as igrejas."},{"verse":19,"text":"Portanto, aonde quer que eles te mandarem, vai, e estarei contigo; e em todo lugar que proclamares meu nome, uma porta eficaz ser-te-á aberta, para que recebam minha palavra."},{"verse":20,"text":"Quem recebe minha palavra, a mim me recebe; e quem me recebe, recebe aqueles que enviei, a Primeira Presidência, a quem te dei como conselheiros por causa de meu nome."},{"verse":21,"text":"E digo-te também que todos os que enviares em meu nome pela voz de teus irmãos, os Doze, devidamente recomendados e autorizados por ti, terão poder para abrir a porta de meu reino a toda nação a que os enviares —"},{"verse":22,"text":"Caso eles se humilhem perante mim, e obedeçam à minha palavra, e deem ouvidos à voz de meu Espírito."},{"verse":23,"text":"Em verdade, em verdade eu te digo: Trevas cobrem a Terra e densa escuridão a mente do povo; e toda carne corrompeu-se diante de minha face."},{"verse":24,"text":"Eis que a vingança cairá rapidamente sobre os habitantes da Terra, um dia de ira, um dia de queima, um dia de desolação, de pranto, de luto e de lamentação; e, como uma tormenta, cairá sobre toda a face da Terra, diz o Senhor."},{"verse":25,"text":"E sobre minha casa principiará e de minha casa espalhar-se-á, diz o Senhor;"},{"verse":26,"text":"Primeiro entre os de vós, diz o Senhor, que professaram conhecer meu nome e não me conheceram; e blasfemaram contra mim no meio da minha casa, diz o Senhor."},{"verse":27,"text":"Portanto, vede que não vos preocupeis com os negócios da minha igreja neste lugar, diz o Senhor."},{"verse":28,"text":"Mas purificai o coração diante de mim; e depois ide por todo o mundo e pregai meu evangelho a toda criatura que não o tiver recebido;"},{"verse":29,"text":"E o que crer e for batizado será salvo; e o que não crer e não for batizado será condenado."},{"verse":30,"text":"Pois a vós, os Doze, e àqueles que forem convosco designados para ser vossos conselheiros e vossos líderes, a Primeira Presidência, é dado o poder deste sacerdócio para os últimos dias e pela última vez, dias esses que abrangem a dispensação da plenitude dos tempos,"},{"verse":31,"text":"Poder que possuís juntamente com todos os que receberam uma dispensação em qualquer tempo, desde o começo da criação;"},{"verse":32,"text":"Pois em verdade vos digo: As chaves da dispensação que recebestes foram transmitidas pelos antepassados e, finalmente, enviadas do céu a vós."},{"verse":33,"text":"Em verdade vos digo: Vede quão grandioso é vosso chamado. Purificai o coração e vossas vestes, para que o sangue desta geração não seja requerido de vossas mãos."},{"verse":34,"text":"Sede fiéis até que eu venha, pois depressa venho; e meu galardão está comigo para recompensar cada homem de acordo com suas obras. Eu sou o Alfa e o Ômega. Amém."}]},{"chapter":113,"verses":[{"verse":1,"text":"Quem é o Tronco de Jessé mencionado nos versículos 1, 2, 3, 4 e 5 do capítulo 11 de Isaías?"},{"verse":2,"text":"Em verdade, assim diz o Senhor: É Cristo."},{"verse":3,"text":"O que é o rebento mencionado no primeiro versículo do capítulo 11 de Isaías, que brotaria do Tronco de Jessé?"},{"verse":4,"text":"Eis que assim diz o Senhor: É um servo nas mãos de Cristo, que em parte é descendente de Jessé assim como de Efraim, ou seja, da casa de José, a quem foi dado muito poder."},{"verse":5,"text":"O que é a raiz de Jessé mencionada no versículo 10 do capítulo 11?"},{"verse":6,"text":"Eis que assim diz o Senhor: É um descendente de Jessé, assim como de José, a quem por direito pertencem o sacerdócio e as chaves do reino, posto por estandarte e para a coligação de meu povo nos últimos dias."},{"verse":7,"text":"Perguntas de Elias Higbee: Qual o significado da ordem dada no primeiro versículo do capítulo 52 de Isaías, que diz: Veste-te da tua fortaleza, ó Sião — e a que povo se referia Isaías?"},{"verse":8,"text":"Referia-se àqueles a quem Deus chamaria nos últimos dias, que possuiriam o poder do sacerdócio para fazer Sião voltar e efetuar a redenção de Israel; e vestir a sua fortaleza é vestir-se da autoridade do sacerdócio, à qual ela, Sião, tem direito por linhagem; também, para voltar ao poder que perdera."},{"verse":9,"text":"O que devemos entender por Sião soltando-se das cadeias de seu pescoço, no versículo 2?"},{"verse":10,"text":"Devemos entender que os remanescentes dispersos são exortados a regressar ao Senhor, de quem se afastaram; se o fizerem, o Senhor promete que lhes falará ou lhes dará revelações. Ver os versículos 6, 7 e 8. As cadeias de seu pescoço são as maldições de Deus sobre ela, ou seja, os remanescentes de Israel em sua dispersão entre os gentios."}]},{"chapter":114,"verses":[{"verse":1,"text":"Em verdade assim diz o Senhor: É prudente que meu servo David W. Patten resolva todos os seus negócios logo que possível e disponha de sua mercadoria a fim de realizar uma missão para mim, na próxima primavera, em companhia de outros, sim, doze incluindo ele próprio, para testificar meu nome e levar alegres novas a todo o mundo."},{"verse":2,"text":"Pois em verdade assim diz o Senhor: Visto que há entre vós alguns que negam meu nome, outros serão postos em seu lugar e receberão seu bispado. Amém."}]},{"chapter":115,"verses":[{"verse":1,"text":"Em verdade, assim vos diz o Senhor, meu servo Joseph Smith Júnior e também meu servo Sidney Rigdon e também meu servo Hyrum Smith e vossos conselheiros que são e serão designados daqui em diante;"},{"verse":2,"text":"E também a ti, meu servo Edward Partridge, e a teus conselheiros;"},{"verse":3,"text":"E também a meus servos fiéis do sumo conselho de minha Igreja em Sião, pois assim será chamada, e a todos os élderes e ao povo de minha Igreja de Jesus Cristo dos Santos dos Últimos Dias, dispersos por todo o mundo;"},{"verse":4,"text":"Pois assim será a minha igreja chamada nos últimos dias, sim, A Igreja de Jesus Cristo dos Santos dos Últimos Dias."},{"verse":5,"text":"Em verdade eu digo a vós todos: Erguei-vos e brilhai, para que vossa luz seja um estandarte para as nações;"},{"verse":6,"text":"E para que a reunião na terra de Sião e em suas estacas seja uma defesa e um refúgio contra a tempestade e contra a ira, quando for derramada, sem mistura, sobre toda a Terra."},{"verse":7,"text":"Que a cidade de Far West seja uma terra santa e consagrada a mim; e será chamada santíssima, pois o chão em que vos encontrais é santo."},{"verse":8,"text":"Portanto, eu vos ordeno que me construais uma casa, para a reunião de meus santos, a fim de que eles me adorem."},{"verse":9,"text":"E que se inicie essa obra e um alicerce e o trabalho preparatório neste próximo verão;"},{"verse":10,"text":"E que o início seja em quatro de julho próximo; e, daí em diante, que meu povo trabalhe diligentemente na construção de uma casa a meu nome;"},{"verse":11,"text":"E que daqui a um ano, a partir deste dia, recomecem a colocar o alicerce da minha casa."},{"verse":12,"text":"Assim, que deste tempo em diante trabalhem diligentemente até que esteja terminada, desde a pedra angular até o teto, até que nada reste inacabado."},{"verse":13,"text":"Em verdade vos digo: Que meu servo Joseph e meu servo Sidney e meu servo Hyrum não contraiam mais dívidas por causa da construção de uma casa a meu nome;"},{"verse":14,"text":"Mas que se construa uma casa a meu nome, conforme o modelo que lhes mostrarei."},{"verse":15,"text":"E se meu povo não a construir de acordo com o modelo que eu mostrar a sua presidência, não a aceitarei de suas mãos."},{"verse":16,"text":"Mas se meu povo a construir de acordo com o modelo que mostrarei a sua presidência, sim, meu servo Joseph e seus conselheiros, então a aceitarei das mãos de meu povo."},{"verse":17,"text":"E também, em verdade vos digo que é a minha vontade que a cidade de Far West seja edificada depressa pela reunião de meus santos;"},{"verse":18,"text":"E também que outros lugares sejam designados para estacas nas regiões circunvizinhas, como forem indicados a meu servo Joseph, de tempos em tempos."},{"verse":19,"text":"Pois eis que eu estarei com ele e santificá-lo-ei perante o povo; pois a ele dei as chaves deste reino e ministério. Assim seja. Amém."}]},{"chapter":116,"verses":[{"verse":1,"text":"O Senhor chama Spring Hill de Adão-ondi-Amã, porque, disse ele, é o lugar ao qual Adão virá para visitar seu povo, ou melhor, onde o Ancião de Dias se assentará, como mencionado por Daniel, o profeta."}]},{"chapter":117,"verses":[{"verse":1,"text":"Em verdade, assim diz o Senhor a meu servo William Marks e também a meu servo Newel K. Whitney: Que resolvam seus negócios rapidamente e partam da terra de Kirtland antes que eu, o Senhor, torne a enviar neve sobre a terra."},{"verse":2,"text":"Que acordem e se ergam e prossigam e não se demorem, porque eu, o Senhor, o ordeno."},{"verse":3,"text":"Portanto, caso se demorem, não será bom para eles."},{"verse":4,"text":"Que se arrependam de todos os seus pecados e de todas as suas cobiças perante mim, diz o Senhor; pois o que é propriedade para mim? diz o Senhor."},{"verse":5,"text":"Que as propriedades de Kirtland sejam dadas em pagamento de dívidas, diz o Senhor. Deixai-as ir, diz o Senhor, e o que restar, que fique em vossas mãos, diz o Senhor."},{"verse":6,"text":"Pois não pertencem a mim as aves do céu e também os peixes do mar e os animais das montanhas? Não fiz eu a Terra? Não tenho em minhas mãos o destino de todos os exércitos das nações da Terra?"},{"verse":7,"text":"Portanto, não farei eu com que lugares solitários brotem e floresçam e produzam em abundância? diz o Senhor."},{"verse":8,"text":"Não há lugar suficiente nas montanhas de Adão-ondi-Amã e nas planícies de Olaa Sineá, ou seja, a terra onde Adão habitou, de modo que cobiçais aquilo que é apenas uma gota e negligenciais assuntos de maior importância?"},{"verse":9,"text":"Portanto, subi à terra de meu povo, ou seja, Sião."},{"verse":10,"text":"Que meu servo William Marks seja fiel sobre poucas coisas e será governante de muitas. Que presida no meio de meu povo, na cidade de Far West, e que seja abençoado com as bênçãos de meu povo."},{"verse":11,"text":"Que meu servo Newel K. Whitney se envergonhe do bando dos nicolaítas e de todas as suas abominações secretas e de toda a sua pequenez de alma perante mim, diz o Senhor, e suba à terra de Adão-ondi-Amã e seja um bispo para meu povo, diz o Senhor, não no nome, mas em ações, diz o Senhor."},{"verse":12,"text":"E também vos digo: Lembro-me de meu servo Oliver Granger; eis que em verdade lhe digo que seu nome será conservado em lembrança sagrada de geração em geração, para todo o sempre, diz o Senhor."},{"verse":13,"text":"Portanto, que pleiteie sinceramente a redenção da Primeira Presidência da minha igreja, diz o Senhor; e, quando ele cair, tornará a erguer-se, pois seu sacrifício ser-me-á mais sagrado que seu crescimento, diz o Senhor."},{"verse":14,"text":"Portanto, que suba depressa à terra de Sião; e no devido tempo se fará comerciante ao meu nome, diz o Senhor, para benefício de meu povo."},{"verse":15,"text":"Portanto, que nenhum homem despreze meu servo Oliver Granger, mas que as bênçãos de meu povo estejam com ele para todo o sempre."},{"verse":16,"text":"E também, em verdade vos digo: Que todos os meus servos da terra de Kirtland se lembrem do Senhor seu Deus e também da minha casa; e conservem e preservem sua santidade; e derrubem os cambistas no meu próprio e devido tempo, diz o Senhor. Assim seja. Amém."}]},{"chapter":118,"verses":[{"verse":1,"text":"Em verdade assim diz o Senhor: Realize-se uma conferência imediatamente; organizem-se os Doze; e designem-se homens para tomar o lugar daqueles que caíram."},{"verse":2,"text":"Que meu servo Thomas permaneça durante um tempo na terra de Sião para publicar minha palavra."},{"verse":3,"text":"Que os restantes continuem a pregar a partir de então; e se o fizerem com o coração submisso, com mansidão e humildade, e longanimidade, eu, o Senhor, prometo-lhes que suprirei às suas famílias; e uma porta eficaz ser-lhes-á aberta daí em diante."},{"verse":4,"text":"E na próxima primavera, saiam para atravessar as grandes águas e ali promulgar meu evangelho em sua plenitude e prestar testemunho de meu nome."},{"verse":5,"text":"Que se despeçam de meus santos da cidade de Far West, no dia vinte e seis de abril próximo, no local onde será construída a minha casa, diz o Senhor."},{"verse":6,"text":"Que meu servo John Taylor e também meu servo John E. Page e também meu servo Wilford Woodruff e também meu servo Willard Richards sejam designados para tomar o lugar daqueles que caíram e sejam oficialmente notificados de sua designação."}]},{"chapter":119,"verses":[{"verse":1,"text":"Em verdade assim diz o Senhor: Exijo que todos os seus bens excedentes sejam entregues nas mãos do bispo da minha igreja em Sião,"},{"verse":2,"text":"Para a construção de minha casa e para a colocação do alicerce de Sião e para o sacerdócio; e para as dívidas da Presidência de minha Igreja."},{"verse":3,"text":"E esse será o início do dízimo de meu povo."},{"verse":4,"text":"E depois disso, os que assim tiverem pagado o dízimo pagarão a décima parte de toda a sua renda anual; e isto será uma lei permanente para eles, para meu santo sacerdócio, diz o Senhor."},{"verse":5,"text":"Em verdade vos digo: Acontecerá que todos os que se reunirem na terra de Sião darão seus bens excedentes como dízimo e observarão esta lei; caso contrário, não serão considerados dignos de habitar entre vós."},{"verse":6,"text":"E digo-vos: Se meu povo não observar esta lei para santificá-la e, por esta lei, não santificar a terra de Sião para mim, a fim de que nela sejam guardados os meus estatutos e os meus juízos, para que seja santíssima, eis que em verdade vos digo: Ela não será para vós uma terra de Sião."},{"verse":7,"text":"E isto será um modelo para todas as estacas de Sião. Assim seja. Amém."}]},{"chapter":120,"verses":[{"verse":1,"text":"Em verdade assim diz o Senhor: Chegado é o tempo em que sua distribuição será feita por um conselho composto da Primeira Presidência de minha Igreja e do bispo e seu conselho e de meu sumo conselho; e por minha própria voz a eles, diz o Senhor. Assim seja. Amém."}]},{"chapter":121,"verses":[{"verse":1,"text":"Ó Deus, onde estás? E onde está o pavilhão que cobre teu esconderijo?"},{"verse":2,"text":"Até quando tua mão será retida e teu olho, sim, teu olho puro, contemplará dos eternos céus os agravos contra teu povo e contra teus servos e teu ouvido será penetrado por seus lamentos?"},{"verse":3,"text":"Sim, ó Senhor, até quando suportarão esses agravos e essas opressões ilícitas, antes que se abrande teu coração e tuas entranhas deles se compadeçam?"},{"verse":4,"text":"Ó Senhor Deus Todo-Poderoso, criador do céu, da Terra e dos mares e de tudo o que neles há; e que controlas e sujeitas o diabo e o escuro e tenebroso domínio de Seol — estende tua mão; que teu olho penetre; que se erga teu pavilhão; que já não se cubra teu esconderijo; que teu ouvido se incline; que se abrande teu coração e que se compadeçam de nós tuas entranhas."},{"verse":5,"text":"Que se acenda tua ira contra nossos inimigos; e, na fúria de teu coração, com tua espada vinga-nos dos agravos que sofremos."},{"verse":6,"text":"Lembra-te de teus santos que estão sofrendo, ó nosso Deus; e teus servos regozijar-se-ão em teu nome para sempre."},{"verse":7,"text":"Meu filho, paz seja com tua alma; tua adversidade e tuas aflições não durarão mais que um momento;"},{"verse":8,"text":"E então, se as suportares bem, Deus te exaltará no alto; triunfarás sobre todos os teus inimigos."},{"verse":9,"text":"Teus amigos apoiam-te e tornarão a saudar-te com coração caloroso e com mãos amistosas."},{"verse":10,"text":"Ainda não estás como Jó; teus amigos não discutem contigo nem te acusam de transgressão, como fizeram a Jó."},{"verse":11,"text":"A esperança dos que te acusam de transgressão será destruída e suas expectativas derreter-se-ão como a geada branca se derrete aos raios ardentes do sol nascente;"},{"verse":12,"text":"E Deus também pôs a mão e o seu selo para mudar os tempos e as estações e para cegar-lhes a mente, a fim de que não compreendam suas obras maravilhosas; também para que os possa provar e surpreender em sua própria astúcia;"},{"verse":13,"text":"Também porque seu coração é corrupto; e que as coisas que desejam causar aos outros e que se deleitam em que os outros sofram recaiam sobre eles mesmos em alto grau;"},{"verse":14,"text":"Para que também se desapontem e desvaneçam-se suas esperanças;"},{"verse":15,"text":"E daqui a alguns anos, que eles e sua posteridade sejam varridos de debaixo do céu, diz Deus; que não reste qualquer deles para permanecer junto à muralha."},{"verse":16,"text":"Amaldiçoados são todos os que levantarem o calcanhar contra meus ungidos, diz o Senhor; e proclamarem terem eles pecado quando não pecaram perante mim, diz o Senhor, mas fizeram o que era agradável a meus olhos e que eu lhes ordenara."},{"verse":17,"text":"Mas os que clamam transgressão, fazem-no porque são, eles mesmos, servos do pecado e filhos da desobediência."},{"verse":18,"text":"E os que juram falsamente contra meus servos, para levá-los à escravidão e à morte —"},{"verse":19,"text":"Ai deles; porque ofenderam meus pequeninos serão separados das ordenanças de minha casa."},{"verse":20,"text":"Suas cestas não se encherão, suas casas e seus celeiros perecerão e eles próprios serão desprezados por aqueles que os lisonjeavam."},{"verse":21,"text":"Eles não terão direito ao sacerdócio nem sua posteridade depois deles, de geração em geração."},{"verse":22,"text":"Melhor lhes fora que uma pedra de moinho lhes tivesse sido amarrada ao pescoço, afogando-os no fundo do mar."},{"verse":23,"text":"Ai de todos os que afligem meu povo e expulsam-nos e matam e testificam contra eles, diz o Senhor dos Exércitos; uma geração de víboras não escapará à condenação do inferno."},{"verse":24,"text":"Eis que meus olhos veem e conhecem todas as suas obras; e tenho em reserva um julgamento rápido, a seu próprio tempo, para todos eles;"},{"verse":25,"text":"Pois cada homem tem um tempo designado, de acordo com suas obras."},{"verse":26,"text":"Deus vos dará conhecimento, por seu Santo Espírito, sim, pelo indescritível dom do Espírito Santo, conhecimento esse que não foi revelado desde a fundação do mundo até agora;"},{"verse":27,"text":"O qual nossos antepassados aguardaram com ansiedade que se revelasse nos últimos tempos e que lhes foi indicado pelos anjos como estando reservado para a plenitude de sua glória;"},{"verse":28,"text":"Um tempo futuro, no qual nada será retido — se há um Deus ou muitos deuses, eles serão manifestados."},{"verse":29,"text":"Todos os tronos e domínios, principados e poderes serão revelados e concedidos a todos os que tiverem perseverado valentemente por causa do evangelho de Jesus Cristo."},{"verse":30,"text":"E também, se existem limites determinados para os céus ou para os mares, ou para a terra seca, ou para o sol, lua, ou estrelas —"},{"verse":31,"text":"Todos os tempos de suas revoluções, todos os dias, meses e anos designados; e todos os dias de seus dias, meses e anos; e todas as suas glórias, leis e tempos determinados serão revelados nos dias da dispensação da plenitude dos tempos —"},{"verse":32,"text":"De acordo com o que foi determinado, no meio do Conselho do Eterno Deus de todos os outros deuses, antes que este mundo existisse, que seria reservado para seu cumprimento e fim, quando todo homem entrar em sua presença eterna e em seu descanso imortal."},{"verse":33,"text":"Até quando podem águas correntes permanecer impuras? Que poder deterá os céus? Seria tão inútil o homem estender seu braço débil para deter o rio Missouri em seu curso ou fazê-lo ir correnteza acima, como o seria impedir que o Todo-Poderoso derramasse conhecimento do céu sobre a cabeça dos santos dos últimos dias."},{"verse":34,"text":"Eis que muitos são chamados, mas poucos são escolhidos. E por que não são escolhidos?"},{"verse":35,"text":"Porque seu coração está tão fixo nas coisas deste mundo e aspiram tanto às honras dos homens, que eles não aprendem esta lição:"},{"verse":36,"text":"Que os direitos do sacerdócio são inseparavelmente ligados com os poderes do céu e que os poderes do céu não podem ser controlados nem exercidos a não ser de acordo com os princípios da retidão."},{"verse":37,"text":"Que eles nos podem ser conferidos, é verdade; mas quando nos propomos a encobrir nossos pecados ou satisfazer nosso orgulho, nossa vã ambição ou exercer controle ou domínio ou coação sobre a alma dos filhos dos homens, em qualquer grau de iniquidade, eis que os céus se afastam; o Espírito do Senhor se magoa e, quando se afasta, amém para o sacerdócio ou a autoridade desse homem."},{"verse":38,"text":"Eis que, antes de o perceber, é abandonado a si mesmo, para recalcitrar contra os aguilhões, perseguir os santos e lutar contra Deus."},{"verse":39,"text":"Aprendemos, por tristes experiências, que é a natureza e índole de quase todos os homens, tão logo suponham ter adquirido um pouco de autoridade, começar a exercer imediatamente domínio injusto."},{"verse":40,"text":"Portanto, muitos são chamados, mas poucos são escolhidos."},{"verse":41,"text":"Nenhum poder ou influência pode ou deve ser mantido em virtude do sacerdócio, a não ser com persuasão, com longanimidade, com brandura e mansidão e com amor não fingido;"},{"verse":42,"text":"Com bondade e conhecimento puro, que grandemente expandirão a alma, sem hipocrisia e sem dolo —"},{"verse":43,"text":"Repreendendo prontamente com firmeza, quando movido pelo Espírito Santo; e depois, mostrando então um amor maior por aquele que repreendeste, para que ele não te julgue seu inimigo;"},{"verse":44,"text":"Para que ele saiba que tua fidelidade é mais forte que os laços da morte."},{"verse":45,"text":"Que tuas entranhas também sejam cheias de caridade para com todos os homens e para com a família da fé; e que a virtude adorne teus pensamentos incessantemente; então tua confiança se fortalecerá na presença de Deus; e a doutrina do sacerdócio destilar-se-á sobre tua alma como o orvalho do céu."},{"verse":46,"text":"O Espírito Santo será teu companheiro constante, e teu cetro, um cetro imutável de retidão e verdade; e teu domínio será um domínio eterno e, sem medidas coercivas, fluirá para ti eternamente."}]},{"chapter":122,"verses":[{"verse":1,"text":"Os confins da Terra indagarão a respeito de teu nome e tolos zombarão de ti e o inferno se enfurecerá contra ti;"},{"verse":2,"text":"Enquanto os puros de coração e os prudentes e os nobres e os virtuosos procurarão conselho e autoridade e bênçãos sob tuas mãos constantemente."},{"verse":3,"text":"E teu povo nunca se voltará contra ti pelo testemunho de traidores."},{"verse":4,"text":"E embora a influência deles te lance em dificuldades, e em grades e paredes, considerar-te-ão com honra; e dentro em pouco, a tua voz será mais terrível no meio de teus inimigos do que o leão feroz, por causa da tua retidão; e o teu Deus estará ao teu lado para todo o sempre."},{"verse":5,"text":"Se te for requerido sofrer tribulações; se te encontrares em perigo entre os falsos irmãos; se te encontrares em perigo entre salteadores; se te encontrares em perigo na terra ou no mar;"},{"verse":6,"text":"Se fores acusado de toda sorte de falsidades; se os teus inimigos caírem sobre ti; se eles te arrancarem do convívio de teu pai e mãe e irmãos e irmãs; e se com uma espada desembainhada os teus inimigos te arrancarem do seio de tua esposa e de tua prole; e teu filho mais velho, embora com apenas seis anos de idade, agarrar-se às tuas vestes e disser: Meu pai, meu pai, por que não podes ficar conosco? Ó meu pai, o que os homens vão fazer contigo? e se então ele for arrancado de ti pela espada, e fores arrastado para a prisão, e teus inimigos te rondarem como lobos procurando o sangue do cordeiro;"},{"verse":7,"text":"E se fores lançado na cova ou nas mãos de assassinos, e receberes sentença de morte; se fores lançado no abismo; se vagas encapeladas conspirarem contra ti; se ventos furiosos se tornarem o teu inimigo; se os céus se cobrirem de escuridão, e todos os elementos se unirem para obstruir o caminho; e acima de tudo, se as próprias mandíbulas do inferno escancararem a boca para tragar-te, sabe, meu filho, que todas essas coisas te servirão de experiência, e serão para o teu bem."},{"verse":8,"text":"O Filho do Homem desceu abaixo de todas elas. És tu maior do que ele?"},{"verse":9,"text":"Portanto, persevera em teu caminho e o sacerdócio permanecerá contigo; pois os limites deles estão determinados e não podem ultrapassá-los. Teus dias são conhecidos e teus anos não serão diminuídos; portanto, não temas o que o homem possa fazer, pois Deus estará contigo para todo o sempre."}]},{"chapter":123,"verses":[{"verse":1,"text":"E também sugeriríamos, para vossa consideração, a conveniência de todos os santos compilarem o que souberem a respeito de todos os fatos e sofrimentos e maus tratos a eles infligidos pelo povo deste Estado;"},{"verse":2,"text":"E também de todos os bens e do montante dos prejuízos sofridos, tanto em relação ao caráter e a danos pessoais, como a bens materiais;"},{"verse":3,"text":"E também os nomes de todas as pessoas que tomaram parte em sua opressão, até onde se possa consegui-los e descobri-los."},{"verse":4,"text":"E talvez possa ser designado um comitê para descobrir essas coisas e ouvir declarações e depoimentos; e também para reunir as publicações difamatórias em circulação;"},{"verse":5,"text":"E tudo o que for publicado em revistas e em enciclopédias; e todas as histórias difamatórias publicadas e as que estão sendo escritas e por quem; e para mostrar toda a sucessão de velhacarias diabólicas e imposições nefandas e assassinas que têm sido praticadas contra este povo —"},{"verse":6,"text":"Para que não somente as publiquemos para todo o mundo, mas apresentemo-las aos chefes do governo em todo seu aspecto tenebroso e infernal, como a última tentativa requerida de nós por nosso Pai Celestial a fim de podermos reivindicar, plena e totalmente, a promessa que o chamará de seu esconderijo; e também para que não se deixe à nação qualquer desculpa antes de ele enviar o poder de seu braço forte."},{"verse":7,"text":"É uma obrigação imperiosa que temos para com Deus e para com os anjos, com quem seremos levados a estar; e também com relação a nós mesmos, a nossas mulheres e filhos, que foram obrigados a se curvar por causa de angústias, tristezas e preocupações, sob a mais execrável mão do assassinato, da tirania e da opressão, apoiada, instigada e sustentada pela influência desse espírito que tão fortemente fixou as crenças dos pais, que herdaram mentiras, no coração dos filhos; e encheu o mundo de confusão e está-se tornando cada vez mais forte e é agora a própria essência de toda corrupção; e toda a Terra geme sob o peso de sua iniquidade."},{"verse":8,"text":"É um jugo de ferro, é um laço forte; são as próprias algemas e correntes e cadeias e grilhões do inferno."},{"verse":9,"text":"Portanto, é uma obrigação imperiosa que temos, não só para com nossas próprias mulheres e filhos, mas para com as viúvas e os órfãos, cujos maridos e pais foram assassinados sob sua mão de ferro;"},{"verse":10,"text":"Atos esses, tenebrosos e difamadores, suficientes para fazer com que o próprio inferno estremeça, aterrorizado e pálido; e com que tremam e fiquem paralisadas as mãos do próprio diabo."},{"verse":11,"text":"E é também uma obrigação imperiosa que temos para com toda a geração que está surgindo e para com todos os puros de coração —"},{"verse":12,"text":"Pois ainda existe muita gente na Terra, em todas as seitas, partidos e denominações, que é cegada pela astúcia sutil dos homens que ficam à espreita para enganar, e que só está afastada da verdade por não saber onde encontrá-la —"},{"verse":13,"text":"Portanto, devemos consumir e esgotar nossa vida para trazer à luz todas as coisas ocultas das trevas, até onde as conheçamos; e elas são verdadeiramente manifestadas do céu —"},{"verse":14,"text":"Dessas devemos, portanto, cuidar com grande diligência."},{"verse":15,"text":"Que nenhum homem as considere coisas pequenas; porque muito há no futuro, com relação aos santos, que depende dessas coisas."},{"verse":16,"text":"Sabeis, irmãos, que um navio muito grande é beneficiado sobremaneira por um pequeno leme, durante uma tempestade, sendo mantido na direção do vento e das ondas."},{"verse":17,"text":"Portanto, amados irmãos, façamos alegremente todas as coisas que estiverem a nosso alcance; e depois aguardemos, com extrema segurança, para ver a salvação de Deus e a revelação de seu braço."}]},{"chapter":124,"verses":[{"verse":1,"text":"Em verdade, assim te diz o Senhor, meu servo Joseph Smith: Estou satisfeito com tua oferta e teus reconhecimentos; pois para esse fim te levantei, para mostrar minha sabedoria por meio das coisas fracas da Terra."},{"verse":2,"text":"Tuas orações são aceitáveis perante mim; e, em resposta a elas, digo-te que és agora chamado para fazer imediatamente uma proclamação solene de meu evangelho e desta estaca que estabeleci para ser uma pedra angular de Sião, a qual será polida com um refinamento semelhante ao de um palácio."},{"verse":3,"text":"Esta proclamação será feita a todos os reis do mundo, aos quatro cantos da Terra, ao ilustre presidente eleito e aos nobres governadores da nação em que vives e a todas as nações espalhadas pela face da Terra."},{"verse":4,"text":"Que seja escrita com espírito de mansidão e pelo poder do Espírito Santo que estará em ti quando a escreveres;"},{"verse":5,"text":"Pois pelo Espírito Santo ser-te-á dado conhecer a minha vontade com relação a esses reis e autoridades, até mesmo o que lhes sobrevirá em uma época futura."},{"verse":6,"text":"Pois eis que estou prestes a conclamá-los para darem ouvidos à luz e à glória de Sião, porque chegado é o tempo determinado para favorecê-la."},{"verse":7,"text":"Conclama-os, portanto, com uma proclamação vigorosa e com teu testemunho, sem os temer, porque eles são como a erva e toda sua glória como a flor da erva que logo cai, para que não se lhes deixe também qualquer desculpa —"},{"verse":8,"text":"E para que eu os visite no dia da visitação, quando eu tirar o véu que me cobre a face, para designar a porção do opressor entre os hipócritas, onde há ranger de dentes, caso rejeitem meus servos e meu testemunho que lhes revelei."},{"verse":9,"text":"E também os visitarei e abrandarei o coração de muitos deles para o vosso bem, para que encontreis graça aos olhos deles, para que venham à luz da verdade e os gentios, à exaltação ou, em outras palavras, ao enaltecimento de Sião."},{"verse":10,"text":"Pois o dia de minha visitação depressa vem, numa hora que não imaginais; e onde estará a segurança de meu povo e o refúgio para os que dele restarem?"},{"verse":11,"text":"Despertai, ó reis da Terra! Vinde, ó vinde com vosso ouro e vossa prata, em auxílio de meu povo, à casa das filhas de Sião."},{"verse":12,"text":"E também, em verdade eu te digo: Que meu servo Robert B. Thompson te ajude a escrever essa proclamação, pois estou satisfeito com ele e que esteja contigo;"},{"verse":13,"text":"Que ele, portanto, atenda a teu conselho e abençoá-lo-ei com uma multiplicidade de bênçãos; que seja fiel e verdadeiro em todas as coisas a partir de agora; e ele será grande aos meus olhos;"},{"verse":14,"text":"Que se lembre, porém, de que de suas mãos requererei sua mordomia."},{"verse":15,"text":"E também, em verdade eu te digo: Bem-aventurado é meu servo Hyrum Smith; pois eu, o Senhor, amo-o pela integridade do seu coração e porque ele ama o que é correto a meus olhos, diz o Senhor."},{"verse":16,"text":"Também que meu servo John C. Bennett te auxilie em teu trabalho de enviar minha palavra aos reis e povos da Terra; e permaneça a teu lado, meu servo Joseph Smith, na hora da aflição; e sua recompensa não falhará, se ele receber conselho."},{"verse":17,"text":"E por seu amor ele será grande, pois será meu se isso fizer, diz o Senhor. Vi a obra que ele fez, a qual aceito se ele continuar; e coroá-lo-ei com bênçãos e grande glória."},{"verse":18,"text":"E também te digo que é a minha vontade que meu servo Lyman Wight continue pregando em favor de Sião, com espírito de mansidão, confessando-me perante o mundo; e sustentá-lo-ei como sobre asas de águias; e ele obterá glória e honra para si e para o meu nome."},{"verse":19,"text":"Para que, quando terminar sua obra, eu o receba para mim, como recebi meu servo David Patten, que está comigo neste momento, e também meu servo Edward Partridge e também meu servo idoso Joseph Smith Sênior, que se assenta à direita de Abraão; e bem-aventurado e santo é ele, porque é meu."},{"verse":20,"text":"E também, em verdade eu te digo: Em meu servo George Miller não há dolo — pode-se confiar nele por causa da integridade de seu coração; e pelo amor que ele tem ao meu testemunho, eu, o Senhor, amo-o."},{"verse":21,"text":"Portanto, digo-te: Selo sobre sua cabeça o ofício de um bispado, como com meu servo Edward Partridge, para que receba as consagrações de minha casa, para que confira bênçãos aos pobres que existem entre meu povo, diz o Senhor. Que nenhum homem despreze meu servo George, porque ele me honrará."},{"verse":22,"text":"Que meu servo George e meu servo Lyman e meu servo John Snider e outros edifiquem uma casa a meu nome, uma casa como meu servo Joseph irá lhes mostrar, no local que ele também lhes mostrar."},{"verse":23,"text":"E será uma casa de hospedagem, uma casa onde os viajantes possam vir de longe para se hospedar; portanto, que seja uma boa casa, digna de toda aceitação, para que o viajante cansado encontre saúde e segurança enquanto reflete sobre a palavra do Senhor e sobre a pedra angular que designei para Sião."},{"verse":24,"text":"Esta casa será uma habitação saudável se for construída ao meu nome e se o dirigente que para ela for designado não permitir que seja profanada. Será santa; caso contrário, o Senhor teu Deus nela não habitará."},{"verse":25,"text":"E também, em verdade vos digo: Que todos os meus santos venham de longe."},{"verse":26,"text":"E enviai mensageiros rápidos, sim, mensageiros escolhidos, e dizei-lhes: Vinde com todo o vosso ouro e vossa prata e vossas pedras preciosas e com todas as vossas antiguidades; e todos os que tiverem conhecimento de antiguidades e estiverem dispostos a vir, que venham e tragam o álamo e a faia e o pinheiro, junto com todas as árvores preciosas da Terra;"},{"verse":27,"text":"E com ferro, com cobre e com latão; e com zinco e com todas as vossas coisas preciosas da Terra; e construí uma casa ao meu nome, para que nela habite o Altíssimo."},{"verse":28,"text":"Porque não há na Terra um lugar a que ele possa vir e restaurar aquilo que perdestes, ou seja, aquilo que ele tirou, sim, a plenitude do sacerdócio."},{"verse":29,"text":"Porque não existe na Terra uma fonte batismal onde eles, os meus santos, possam ser batizados pelos que estão mortos —"},{"verse":30,"text":"Pois essa ordenança pertence à minha casa, e não me pode ser aceitável, a não ser em dias de penúria, quando não puderdes construir-me uma casa."},{"verse":31,"text":"Ordeno-vos, porém, a todos vós, meus santos, construirdes-me uma casa; e concedo-vos um tempo suficiente para me construirdes uma casa; e, durante esse tempo, vossos batismos ser-me-ão aceitáveis."},{"verse":32,"text":"Mas eis que, findo esse prazo, os vossos batismos pelos vossos mortos não me serão aceitáveis; e se não fizerdes essas coisas, até o final do prazo, sereis rejeitados como igreja com vossos mortos, diz o Senhor vosso Deus."},{"verse":33,"text":"Pois em verdade vos digo que, depois de terdes tido tempo suficiente para construir-me uma casa, onde deverá ser feita a ordenança do batismo pelos mortos e para os quais a mesma foi instituída desde antes da fundação do mundo, os vossos batismos pelos vossos mortos não poderão ser aceitos por mim;"},{"verse":34,"text":"Pois nela são conferidas as chaves do santo sacerdócio, para que recebais honra e glória."},{"verse":35,"text":"E desse tempo em diante, vossos batismos pelos mortos realizados pelos que se encontram espalhados em outras partes não me serão aceitáveis, diz o Senhor."},{"verse":36,"text":"Porque se decretou que em Sião e em suas estacas e em Jerusalém, lugares esses que designei como refúgio, estarão os lugares para os vossos batismos pelos vossos mortos."},{"verse":37,"text":"E também, em verdade vos digo: Como me serão aceitáveis vossas abluções, se não as fizerdes em uma casa construída ao meu nome?"},{"verse":38,"text":"Pois, por essa razão, mandei Moisés construir um tabernáculo que deveriam carregar consigo pelo deserto; e construir uma casa na terra da promissão para que se revelassem as ordenanças que estiveram ocultas desde antes da fundação do mundo."},{"verse":39,"text":"Portanto, em verdade vos digo, que vossas unções e vossas abluções; e vossos batismos pelos mortos; e vossas assembleias solenes e memoriais dos vossos sacrifícios feitos pelos filhos de Levi por vós; e os vossos oráculos nos lugares santíssimos, onde recebeis conhecimento; e os vossos estatutos e juízos, para o início das revelações e do alicerce de Sião, e para a glória, honra, e investidura de todos os seus munícipes são prescritos pela ordenança de minha casa santa, a qual meu povo sempre recebe ordem de construir a meu santo nome."},{"verse":40,"text":"E em verdade vos digo: Que essa casa seja construída ao meu nome, a fim de que nela eu revele minhas ordenanças a meu povo;"},{"verse":41,"text":"Pois digno-me revelar à minha igreja coisas que têm sido mantidas ocultas desde antes da fundação do mundo, coisas pertinentes à dispensação da plenitude dos tempos."},{"verse":42,"text":"E eu mostrarei a meu servo Joseph todas as coisas relativas a essa casa e a seu sacerdócio, assim como o lugar onde será construída."},{"verse":43,"text":"E construí-la-eis no lugar em que planejastes, porque esse é o local que escolhi para sua construção."},{"verse":44,"text":"Se trabalhardes com toda a vossa força, consagrarei esse local para que se torne santo."},{"verse":45,"text":"E se meu povo der ouvidos à minha voz, e à voz de meus servos que designei para guiar meu povo, eis que, em verdade vos digo, não serão removidos do seu lugar."},{"verse":46,"text":"Mas se não derem ouvidos à minha voz, nem à voz desses homens que designei, não serão abençoados, porque profanam o meu solo santo, e as minhas santas ordenanças, e os estatutos, e as minhas santas palavras que lhes dou."},{"verse":47,"text":"E acontecerá que, se construirdes uma casa ao meu nome e não fizerdes as coisas que eu disser, não observarei o juramento que vos faço nem cumprirei as promessas que esperais de minhas mãos, diz o Senhor."},{"verse":48,"text":"Pois em vez de bênçãos, vós, com vossas obras, trazeis maldições, ira, indignação e julgamentos sobre a própria cabeça, com vossa insensatez e com as abominações que cometeis perante mim, diz o Senhor."},{"verse":49,"text":"Em verdade, em verdade vos digo que quando eu dou um mandamento a qualquer dos filhos dos homens de fazer um trabalho ao meu nome e esses filhos dos homens usam toda a sua força e tudo o que têm para realizar esse trabalho e não deixam de ser diligentes; e são atacados por seus inimigos e impedidos de realizar esse trabalho, eis que me convém já não requerer das mãos desses filhos dos homens o trabalho, mas aceitar suas ofertas."},{"verse":50,"text":"E a iniquidade e a transgressão das minhas santas leis e mandamentos farei recair sobre a cabeça daqueles que impediram o meu trabalho, até a terceira e quarta geração, enquanto não se arrependerem e me odiarem, diz o Senhor Deus."},{"verse":51,"text":"Portanto, por essa razão aceitei as ofertas daqueles a quem ordenei construir uma cidade e uma casa ao meu nome, no Condado de Jackson, Missouri, no que foram impedidos por seus inimigos, diz o Senhor vosso Deus."},{"verse":52,"text":"E farei sobrevirem julgamentos, ira e indignação, pranto e angústia e ranger de dentes sobre a cabeça deles até a terceira e quarta geração, enquanto me odiarem e não se arrependerem, diz o Senhor vosso Deus."},{"verse":53,"text":"E isso dou-vos como exemplo, para vossa consolação com respeito a todos os que foram mandados fazer um trabalho e foram impedidos pelas mãos de inimigos e por opressão, diz o Senhor vosso Deus."},{"verse":54,"text":"Pois eu sou o Senhor vosso Deus e salvarei todos os vossos irmãos, que eram puros de coração e foram mortos na terra de Missouri, diz o Senhor."},{"verse":55,"text":"E também, em verdade vos digo: Torno a ordenar-vos que construais uma casa ao meu nome, sim, neste lugar, para que me proveis serdes fiéis em todas as coisas que eu vos mandar, para que eu vos abençoe e vos coroe de honra, imortalidade e vida eterna."},{"verse":56,"text":"E agora vos digo, concernente à minha hospedaria que vos ordenei construir para alojamento de viajantes: Que seja construída ao meu nome e seja chamada pelo meu nome; e que o meu servo Joseph e a sua casa tenham lugar nela, de geração em geração."},{"verse":57,"text":"Pois fiz essa unção sobre sua cabeça a fim de que a bênção dele também esteja sobre a cabeça de sua posteridade depois dele."},{"verse":58,"text":"E como eu disse a Abraão, concernente às famílias da Terra, assim também digo a meu servo Joseph: Em ti e em tua semente as famílias da Terra serão abençoadas."},{"verse":59,"text":"Portanto, que meu servo Joseph e sua semente depois dele tenham lugar nessa casa, de geração em geração, para todo o sempre, diz o Senhor."},{"verse":60,"text":"E que o nome dessa casa seja Casa de Nauvoo; e que seja uma habitação agradável para o homem e um lugar de descanso para o viajante fatigado, para que ele contemple a glória de Sião e a glória desta que é sua pedra angular;"},{"verse":61,"text":"Para que receba também conselho daqueles que coloquei como plantas de renome e como sentinelas sobre seus muros."},{"verse":62,"text":"Eis que em verdade vos digo: Que meu servo George Miller e meu servo Lyman Wight e meu servo John Snider e meu servo Peter Haws se organizem e escolham um deles para presidente de seu quórum, com o propósito de construir essa casa."},{"verse":63,"text":"E deverão formular um estatuto que lhes permita vender ações para a construção dessa casa."},{"verse":64,"text":"E não deverão receber menos de cinquenta dólares por ação dessa casa; e ser-lhes-á permitido aceitar até quinze mil dólares de uma mesma pessoa por ações dessa casa."},{"verse":65,"text":"Mas não lhes será permitido receber, de uma mesma pessoa, mais de quinze mil dólares de capital."},{"verse":66,"text":"E não lhes será permitido aceitar, de uma mesma pessoa, menos de cinquenta dólares por uma ação dessa casa."},{"verse":67,"text":"E não lhes será permitido receber um homem como acionista dessa casa, a não ser que ele pague suas ações no momento em que as receber;"},{"verse":68,"text":"E receberá ações dessa casa em proporção à quantia que entregar em suas mãos; mas, se nada lhes pagar, não receberá ação alguma dessa casa."},{"verse":69,"text":"E se alguém lhes entregar dinheiro, será para compra de ações dessa casa, para si e sua posteridade depois dele, de geração em geração, enquanto ele e seus herdeiros retiverem essas ações e não as venderem nem transferirem por sua livre vontade e ação, se desejais fazer a minha vontade, diz o Senhor vosso Deus."},{"verse":70,"text":"E também em verdade vos digo: Se meu servo George Miller e meu servo Lyman Wight e meu servo John Snider e meu servo Peter Haws receberem qualquer capital, em dinheiro ou em propriedades equivalentes ao valor real do dinheiro, não deverão destinar qualquer parte desse capital a outro fim, a não ser o dessa casa."},{"verse":71,"text":"E se destinarem qualquer parte desse dinheiro a outro fim, que não essa casa, sem o consentimento do acionista, e não pagarem quatro vezes o valor do capital que destinarem a outro uso, serão amaldiçoados e removidos de seu lugar, diz o Senhor Deus; porque eu, o Senhor, sou Deus e não serei escarnecido em qualquer dessas coisas."},{"verse":72,"text":"Em verdade vos digo: Que meu servo Joseph compre ações de suas mãos para a construção dessa casa, como lhe parecer bem; mas meu servo Joseph não pode comprar mais de quinze mil dólares em ações dessa casa, nem menos de cinquenta dólares; nem o pode qualquer outro homem, diz o Senhor."},{"verse":73,"text":"E também há outros que desejam conhecer a minha vontade a respeito deles, pois pediram-me."},{"verse":74,"text":"Portanto, eu vos digo, em relação a meu servo Vinson Knight: Se ele quiser fazer a minha vontade, que adquira ações dessa casa para si e sua posteridade depois dele, de geração em geração."},{"verse":75,"text":"E que erga a voz, longa e estrondosamente, no meio do povo, rogando pelos pobres e necessitados; e que não fraqueje nem se lhe desfaleça o coração; e aceitarei suas ofertas, pois não serão para mim como as ofertas de Caim; pois ele será meu, diz o Senhor."},{"verse":76,"text":"Que sua família se regozije e que o coração deles se afaste da aflição, pois eu o escolhi e ungi e ele será honrado no meio de sua casa, pois perdoarei todos os seus pecados, diz o Senhor. Amém."},{"verse":77,"text":"Em verdade vos digo: Que meu servo Hyrum invista capital nessa casa como lhe parecer bem, para si e sua posteridade depois dele, de geração em geração."},{"verse":78,"text":"Que meu servo Isaac Galland invista capital nessa casa; pois eu, o Senhor, amo-o pelo serviço que tem prestado e perdoarei todos os seus pecados; portanto, que seus direitos nessa casa sejam lembrados, de geração em geração."},{"verse":79,"text":"Que meu servo Isaac Galland seja designado entre vós e seja ordenado e abençoado por meu servo William Marks, a fim de ir com meu servo Hyrum realizar o trabalho que meu servo Joseph lhes indicar; e serão grandemente abençoados."},{"verse":80,"text":"Que meu servo William Marks invista capital nessa casa, como lhe parecer bem, para si e sua posteridade, de geração em geração."},{"verse":81,"text":"Que meu servo Henry G. Sherwood invista capital nessa casa, como lhe parecer bem, para si e sua semente depois dele, de geração em geração."},{"verse":82,"text":"Que meu servo William Law invista capital nessa casa, para si e a sua semente depois dele, de geração em geração."},{"verse":83,"text":"Se ele desejar fazer a minha vontade, que não leve a sua família às terras do leste, sim, a Kirtland; contudo, eu, o Senhor, edificarei Kirtland, mas eu, o Senhor, tenho um flagelo preparado para os seus habitantes."},{"verse":84,"text":"E quanto a meu servo Almon Babbit: Há muitas coisas que não me agradam; eis que ele aspira a estabelecer seu próprio conselho, em vez do conselho que decretei, sim, o da Presidência de minha Igreja; e estabelece um bezerro de ouro para meu povo adorar."},{"verse":85,"text":"Que não se vá deste lugar homem algum que aqui haja vindo na tentativa de obedecer a meus mandamentos."},{"verse":86,"text":"Se viverem aqui, que vivam em mim; e se morrerem, que morram em mim; pois descansarão de todos os seus labores aqui e continuarão suas obras."},{"verse":87,"text":"Portanto, que meu servo William deposite sua confiança em mim e não tema com respeito a sua família, por causa da enfermidade que grassa na região. Se me amais, guardai meus mandamentos; e a enfermidade da região redundará em glória para vós."},{"verse":88,"text":"Que meu servo William vá proclamar meu evangelho eterno em alta voz e com grande alegria, conforme inspirado por meu Espírito, aos habitantes de Warsaw e também aos habitantes de Carthage e também aos habitantes de Burlington e também aos habitantes de Madison; e espere, paciente e diligentemente, mais instruções em minha conferência geral, diz o Senhor."},{"verse":89,"text":"Se ele desejar fazer a minha vontade, que daqui em diante atenda ao conselho de meu servo Joseph, e com seus bens apoie a causa dos pobres, e publique a nova tradução da minha santa palavra para os habitantes da Terra."},{"verse":90,"text":"E se assim fizer, abençoá-lo-ei com uma multiplicidade de bênçãos; e ele não será abandonado, nem a sua semente será vista suplicando pão."},{"verse":91,"text":"E também, em verdade vos digo: Que meu servo William seja designado, ordenado e ungido conselheiro de meu servo Joseph, em lugar de meu servo Hyrum, para que meu servo Hyrum ocupe o ofício de Sacerdócio e Patriarca, que por seu pai lhe foi designado por bênção e também por direito;"},{"verse":92,"text":"Que de agora em diante retenha as chaves das bênçãos patriarcais sobre a cabeça de todo o meu povo,"},{"verse":93,"text":"Para que quem ele abençoar seja abençoado; e quem ele amaldiçoar seja amaldiçoado; para que tudo que ligar na Terra seja ligado nos céus e tudo que ele desligar na Terra seja desligado nos céus."},{"verse":94,"text":"E deste momento em diante, designo-o profeta, vidente e revelador da minha igreja, como meu servo Joseph;"},{"verse":95,"text":"Para que também proceda de acordo com meu servo Joseph e que receba conselho de meu servo Joseph, o qual lhe mostrará as chaves pelas quais poderá pedir e receber e ser coroado com a mesma bênção e glória e honra e sacerdócio e dons do sacerdócio, que antes foram colocados sobre a cabeça daquele que era meu servo, Oliver Cowdery;"},{"verse":96,"text":"Que meu servo Hyrum testifique as coisas que eu lhe mostrar, para que seu nome seja lembrado com honra, de geração em geração, para todo o sempre."},{"verse":97,"text":"Que meu servo William Law também receba as chaves pelas quais poderá pedir e receber bênçãos; que seja humilde perante mim e sem dolo; e receberá meu Espírito, sim, o Consolador, que lhe manifestará a verdade de todas as coisas e mostrar-lhe-á, na hora exata, o que deverá dizer."},{"verse":98,"text":"E estes sinais segui-lo-ão: Curará os doentes, expulsará demônios e será protegido contra os que desejam dar-lhe veneno mortífero;"},{"verse":99,"text":"E será conduzido por veredas onde as serpentes venenosas não lhe poderão ferir o calcanhar e elevar-se-á, na imaginação de seus pensamentos, como que sobre asas de águias."},{"verse":100,"text":"E se eu desejar que ele levante os mortos, que ele não retenha a sua voz."},{"verse":101,"text":"Portanto, que meu servo William clame em alta voz e não se detenha, com alegria e regozijo e com hosanas àquele que se assenta no trono para todo o sempre, diz o Senhor vosso Deus."},{"verse":102,"text":"Eis que vos digo: Tenho uma missão reservada para meu servo William e para meu servo Hyrum e para eles somente; e que meu servo Joseph permaneça em casa, porque precisam dele. O remanescente mostrar-vos-ei depois. Assim seja. Amém."},{"verse":103,"text":"E também, em verdade vos digo: Se meu servo Sidney desejar servir-me e ser conselheiro de meu servo Joseph, que se levante e venha ocupar o cargo de seu chamado; e que se humilhe perante mim."},{"verse":104,"text":"E se me oferecer uma oferta aceitável e reconhecimentos e permanecer com meu povo, eis que eu, o Senhor vosso Deus, o curarei para que fique são; e ele tornará a erguer a voz nas montanhas e será um porta-voz diante de minha face."},{"verse":105,"text":"Que venha e estabeleça sua família perto da residência de meu servo Joseph."},{"verse":106,"text":"E em todas as suas viagens, que erga a voz como com o som de uma trombeta e advirta os habitantes da Terra que fujam da ira que virá."},{"verse":107,"text":"Que ele ajude meu servo Joseph e que também meu servo William Law ajude meu servo Joseph a fazer uma proclamação solene aos reis da Terra, assim como vos disse antes."},{"verse":108,"text":"Se meu servo Sidney desejar fazer a minha vontade, que não leve a sua família para as regiões do leste, mas que mude de casa, assim como eu disse."},{"verse":109,"text":"Eis que não é a minha vontade que ele procure encontrar segurança e refúgio fora da cidade que vos indiquei, sim, a cidade de Nauvoo."},{"verse":110,"text":"Em verdade vos digo: Mesmo agora, se ele atender à minha voz, tudo lhe irá bem. Assim seja. Amém."},{"verse":111,"text":"E também, em verdade vos digo: Que meu servo Amos Davies compre ações das mãos daqueles que designei para construir uma hospedaria, sim, a Casa de Nauvoo."},{"verse":112,"text":"Que faça isso se quiser ter participação; e que dê ouvidos aos conselhos de meu servo Joseph e trabalhe com suas próprias mãos a fim de conquistar a confiança dos homens."},{"verse":113,"text":"E quando tiver dado provas de fidelidade em todas as coisas que lhe forem confiadas, sim, mesmo que sejam poucas, será feito governante sobre muitas;"},{"verse":114,"text":"Portanto, que se humilhe para ser exaltado. Assim seja. Amém."},{"verse":115,"text":"E também, em verdade vos digo: Se o meu servo Robert D. Foster deseja obedecer à minha voz, que construa uma casa para o meu servo Joseph, de acordo com o contrato que fez com ele, pois a porta ser-lhe-á aberta de tempos em tempos."},{"verse":116,"text":"E que se arrependa de toda sua insensatez e revista-se de caridade; e cesse de praticar o mal e abandone todas as suas palavras ásperas;"},{"verse":117,"text":"E compre ações do quórum da Casa de Nauvoo, para si e sua posteridade depois dele, de geração em geração."},{"verse":118,"text":"E dê ouvidos aos conselhos de meus servos Joseph e Hyrum e William Law e às autoridades que escolhi para estabelecerem o alicerce de Sião; e tudo lhe irá bem para todo o sempre. Assim seja. Amém."},{"verse":119,"text":"E também, em verdade vos digo: Que nenhum homem compre ações do quórum da Casa de Nauvoo, a menos que creia no Livro de Mórmon e nas revelações que vos dei, diz o Senhor vosso Deus;"},{"verse":120,"text":"Porque o que é mais ou menos do que isso provém do mal e será acompanhado de maldições e não de bênçãos, diz o Senhor vosso Deus. Assim seja. Amém."},{"verse":121,"text":"E também, em verdade vos digo: Que o quórum da Casa de Nauvoo receba um salário justo por todos os serviços que prestarem na construção da Casa de Nauvoo; e que seu salário seja decidido entre eles quanto ao valor."},{"verse":122,"text":"E que todo homem que comprar ações contribua proporcionalmente para o salário deles, caso seja necessário para seu sustento, diz o Senhor; do contrário, seus serviços serão pagos com ações dessa casa. Assim seja. Amém."},{"verse":123,"text":"Em verdade vos digo: Agora vos indico os oficiais pertencentes a meu sacerdócio, para que tenhais suas chaves, sim, desse Sacerdócio que é segundo a ordem de Melquisedeque, que é segundo a ordem de meu Filho Unigênito."},{"verse":124,"text":"Primeiro dou-vos Hyrum Smith como vosso patriarca, para portar as bênçãos de selamento de minha igreja, sim, o Santo Espírito da promessa pelo qual sois selados para o dia da redenção, a fim de que não chegueis a cair, não obstante a hora de tentação que vos sobrevier."},{"verse":125,"text":"Dou-vos meu servo Joseph como élder presidente de toda a minha igreja, e para ser tradutor, revelador, vidente e profeta."},{"verse":126,"text":"Dou-lhe como conselheiros meu servo Sidney Rigdon e meu servo William Law, para constituírem um quórum e Primeira Presidência, a fim de receberem os oráculos para toda a igreja."},{"verse":127,"text":"Dou-vos meu servo Brigham Young como presidente do conselho viajante dos Doze;"},{"verse":128,"text":"Conselho esse que tem as chaves para abrir a autoridade de meu reino nos quatro cantos da Terra e, depois, enviar minha palavra a toda criatura."},{"verse":129,"text":"São eles: Heber C. Kimball, Parley P. Pratt, Orson Pratt, Orson Hyde, William Smith, John Taylor, John E. Page, Wilford Woodruff, Willard Richards, George A. Smith;"},{"verse":130,"text":"David Patten tomei para mim; eis que seu sacerdócio ninguém lho tirará; mas, em verdade vos digo, outro poderá ser designado para o mesmo chamado."},{"verse":131,"text":"E também vos digo: Dou-vos um sumo conselho, como pedra angular de Sião —"},{"verse":132,"text":"A saber: Samuel Bent, Henry G. Sherwood, George W. Harris, Charles C. Rich, Thomas Grover, Newel Knight, David Dort, Dunbar Wilson — Seymour Brunson tomei para mim; ninguém lhe tirará o sacerdócio, mas outro poderá ser designado ao mesmo sacerdócio em seu lugar; e em verdade vos digo: Que seja meu servo Aaron Johnson ordenado para esse chamado em seu lugar — David Fullmer, Alpheus Cutler, William Huntington."},{"verse":133,"text":"E também vos dou Don C. Smith como presidente de um quórum de sumos sacerdotes;"},{"verse":134,"text":"Ordenança essa instituída com o propósito de qualificar os que serão designados presidentes, ou seja, servos locais de diferentes estacas espalhadas fora daqui;"},{"verse":135,"text":"E poderão também viajar se o desejarem, mas são ordenados presidentes locais; este é o ofício de seu chamado, diz o Senhor vosso Deus."},{"verse":136,"text":"Dou-lhe Amasa Lyman e Noah Packard como conselheiros, para presidirem o quórum de sumos sacerdotes de minha igreja, diz o Senhor."},{"verse":137,"text":"E também vos digo: Dou-vos John A. Hicks, Samuel Williams e Jesse Baker, cujo sacerdócio deverá presidir o quórum de élderes, quórum esse instituído para que eles sejam ministros locais; no entanto poderão viajar, não obstante serem ordenados ministros locais de minha igreja, diz o Senhor."},{"verse":138,"text":"E também vos dou Joseph Young, Josiah Butterfield, Daniel Miles, Henry Herriman, Zera Pulsipher, Levy Hancock, James Foster, para que eles presidam o quórum de setentas;"},{"verse":139,"text":"Esse quórum é instituído para que eles sejam élderes viajantes, a fim de prestarem testemunho de meu nome em todo o mundo, aonde quer que o sumo conselho viajante, os meus apóstolos, os envie para preparar um caminho diante da minha face."},{"verse":140,"text":"A diferença entre esse quórum e o quórum de élderes é que um deverá viajar constantemente e o outro deverá presidir as igrejas de tempos em tempos; um tem a responsabilidade de presidir de tempos em tempos e o outro não tem responsabilidade de presidir, diz o Senhor vosso Deus."},{"verse":141,"text":"E também vos digo: Dou-vos Vinson Knight, Samuel H. Smith e Shadrach Roundy, se ele aceitar, para presidir o bispado; instruções sobre o dito bispado encontram-se no livro de Doutrina e Convênios."},{"verse":142,"text":"E também vos digo: Samuel Rolfe e seus conselheiros como sacerdotes e o presidente dos mestres e seus conselheiros e também o presidente dos diáconos e seus conselheiros e também o presidente da estaca e seus conselheiros."},{"verse":143,"text":"Os ofícios acima eu vos dei, assim como suas chaves, para auxílio e governo, para a obra do ministério e o aperfeiçoamento de meus santos."},{"verse":144,"text":"E dou-vos o mandamento de preencherdes todos esses cargos e aprovardes ou desaprovardes, na minha conferência geral, os nomes que mencionei;"},{"verse":145,"text":"E de preparardes acomodações para todos esses cargos em minha casa, quando a construirdes ao meu nome, diz o Senhor vosso Deus. Assim seja. Amém."}]},{"chapter":125,"verses":[{"verse":1,"text":"Qual é a vontade do Senhor concernente aos santos do Território de Iowa?"},{"verse":2,"text":"Em verdade, assim diz o Senhor: Eu vos digo que se aqueles que tomam sobre si o meu nome e esforçam-se para ser os meus santos desejarem fazer a minha vontade e guardar os meus mandamentos concernentes a eles, que se reúnam nos lugares que eu lhes designar por meio de meu servo Joseph, e construam cidades ao meu nome, a fim de se prepararem para aquilo que está reservado para uma época futura."},{"verse":3,"text":"Que construam uma cidade ao meu nome na terra em frente à cidade de Nauvoo; e que lhe seja dado o nome de Zaraenla."},{"verse":4,"text":"E que todos os que vierem do leste e do oeste e do norte e do sul, que desejem ali habitar, recebam sua herança nela, assim como na cidade de Nashville, ou na cidade de Nauvoo e em todas as estacas que designei, diz o Senhor."}]},{"chapter":126,"verses":[{"verse":1,"text":"Querido e bem-amado irmão Brigham Young, em verdade assim te diz o Senhor: Meu servo Brigham, não mais se requer de ti que deixes tua família como em tempos passados, porque tua oferta me é aceitável."},{"verse":2,"text":"Tenho visto teu trabalho e tua lida nas viagens que fizeste pelo meu nome."},{"verse":3,"text":"Ordeno-te, portanto, que envies minha palavra ao exterior e zeles especialmente por tua família, de agora em diante e para sempre. Amém."}]},{"chapter":127,"verses":[{"verse":1,"text":"Tendo o Senhor me revelado estarem os meus inimigos outra vez à minha procura, tanto em Missouri como neste Estado; e sendo que me perseguem sem motivo e não têm a menor sombra ou aparência de justiça ou direito a seu favor na formulação de processos contra mim; e sendo as suas pretensões todas baseadas na mais tenebrosa falsidade, achei conveniente e sábio abandonar o lugar por certo tempo, para minha própria segurança e a segurança deste povo. Quero dizer a todos com quem tenho relações comerciais, que encarreguei agentes e secretários para cuidar de todos os meus negócios de maneira correta e precisa, pagando todas as minhas dívidas a tempo, vendendo propriedades ou de outra forma, conforme o caso exigir ou as circunstâncias permitirem. Quando eu souber que a tempestade passou completamente, então voltarei para o meio de vós."},{"verse":2,"text":"E quanto aos perigos que de mim é requerido passar, parecem-me coisa pequena, pois a inveja e a ira dos homens têm-me acompanhado todos os dias de minha vida; e a causa parece-me um mistério, a menos que eu tenha sido ordenado desde antes da fundação do mundo para algum propósito bom ou mau, como preferirdes chamá-lo. Julgai por vós mesmos. Deus conhece todas essas coisas, sejam boas ou más. Contudo, estou habituado a nadar em águas profundas. Isso tudo se tornou uma segunda natureza para mim; e, como Paulo, glorio-me na tribulação; pois até este dia o Deus de meus pais livrou-me de todas elas e livrar-me-á daqui em diante; pois eis que triunfarei sobre todos os meus inimigos, porque o Senhor Deus o disse."},{"verse":3,"text":"Regozijem-se, portanto, todos os santos e alegrem-se muito; porque o Deus de Israel é o seu Deus e ele derramará uma justa recompensa sobre a cabeça de todos os seus opressores."},{"verse":4,"text":"E também, em verdade assim diz o Senhor: Que a obra de meu templo e todas as obras que vos designei continuem sem cessar; e que vossa diligência e vossa perseverança e paciência e vossos trabalhos se redobrem; e de modo algum perdereis vossa recompensa, diz o Senhor dos Exércitos. E se vos perseguirem, assim perseguiram eles os profetas e homens justos antes de vós. Para tudo isso há uma recompensa no céu."},{"verse":5,"text":"E também vos falo com relação ao batismo por vossos mortos."},{"verse":6,"text":"Em verdade, assim vos diz o Senhor a respeito de vossos mortos: Quando um de vós for batizado por vossos mortos, que haja um registrador e que ele seja testemunha ocular de vossos batismos; que ouça com seus ouvidos para testificar a verdade, diz o Senhor;"},{"verse":7,"text":"Para que todos os vossos registros sejam registrados no céu; para que tudo o que ligardes na Terra seja ligado no céu; tudo o que desligardes na Terra seja desligado no céu;"},{"verse":8,"text":"Pois estou prestes a restaurar na Terra muitas coisas relativas ao sacerdócio, diz o Senhor dos Exércitos."},{"verse":9,"text":"E também que todos os registros sejam conservados em ordem, para que sejam postos nos arquivos de meu santo templo, a fim de serem conservados na lembrança, de geração em geração, diz o Senhor dos Exércitos."},{"verse":10,"text":"Quero dizer a todos os santos que desejei, com grande desejo, falar-lhes do púlpito no domingo próximo sobre o assunto do batismo pelos mortos. Mas estando fora de meu alcance fazê-lo, escreverei a palavra do Senhor, de tempos em tempos, sobre o assunto; e enviá-la-ei pelo correio, assim como muitas outras coisas."},{"verse":11,"text":"Agora termino minha carta, por falta de tempo; pois o inimigo está alerta e, como disse o Salvador, o príncipe deste mundo vem, mas nada tem comigo."},{"verse":12,"text":"Eis que minha oração a Deus é para que todos vós sejais salvos. E subscrevo-me, vosso servo no Senhor, profeta e vidente de A Igreja de Jesus Cristo dos Santos dos Últimos Dias."},{"verse":13,"text":"Joseph Smith."}]},{"chapter":128,"verses":[{"verse":1,"text":"Como afirmei na carta a vós dirigida antes de deixar minha casa, que vos escreveria de tempos em tempos para informar-vos sobre vários assuntos, retomo agora a questão do batismo pelos mortos, pois esse assunto parece ocupar-me o pensamento e impor-se a meus sentimentos mais do que qualquer outro desde que meus inimigos começaram a me perseguir."},{"verse":2,"text":"Eu vos escrevi algumas palavras de revelação concernentes a um registrador. Vieram-me mais algumas ideias com relação a esse assunto, que agora dou a conhecer. Isto é, declarei em minha carta anterior que deveria haver um registrador, que fosse testemunha ocular e ouvisse com seus ouvidos, para fazer um registro da verdade perante o Senhor."},{"verse":3,"text":"Agora, com relação a esse assunto, seria muito difícil para um mesmo registrador estar presente todas as vezes e tratar de todos os assuntos. Para evitar essa dificuldade, pode-se designar um registrador bem qualificado, em cada ala da cidade, para fazer atas precisas; e que ele seja muito minucioso e exato ao anotar todos os procedimentos, afirmando em seu registro que viu com seus olhos e ouviu com seus ouvidos, dando a data, os nomes e assim por diante; e a história de toda a transação, indicando três indivíduos que estiverem presentes, se houver alguém presente, que possam, em qualquer ocasião em que forem chamados, certificar quanto ao mesmo, para que, pela boca de duas ou três testemunhas toda palavra seja confirmada."},{"verse":4,"text":"E que haja um registrador geral, a quem esses outros registros possam ser entregues, acompanhados de certificados com assinaturas, atestando ser verdadeiro o registro que fizeram. Então o registrador geral da igreja incluirá o registro no livro geral da igreja, juntamente com os certificados e todas as testemunhas presentes, e com sua própria declaração de que realmente acredita serem verdadeiras as afirmações e os registros, a julgar pelo conhecimento do caráter geral daqueles homens e sua designação pela igreja. E, quando isso for feito no livro geral da igreja, o registro será tão santo e confirmará a ordenança, como se ele tivesse visto com seus próprios olhos e ouvido com seus próprios ouvidos e feito um registro do mesmo no livro geral da igreja."},{"verse":5,"text":"Talvez penseis que essa ordem das coisas seja muito minuciosa; mas quero dizer-vos que é apenas em resposta à vontade de Deus, segundo a ordenança e preparação que o Senhor ordenou e preparou antes da fundação do mundo para a salvação dos que morressem sem conhecimento do evangelho."},{"verse":6,"text":"E ainda mais, quero que vos lembreis de que João, o Revelador, estava meditando sobre esse mesmo assunto, em relação aos mortos, quando declarou conforme encontrareis registrado em Apocalipse 20:12 — E vi os mortos, grandes e pequenos, que estavam diante de Deus; e abriram-se os livros; e abriu-se outro livro, que é o da vida; e os mortos foram julgados pelas coisas que estavam escritas nos livros, segundo as suas obras."},{"verse":7,"text":"Descobrireis, nessa citação, que se abriram os livros; e abriu-se um outro livro, que era o livro da vida; mas os mortos foram julgados pelas coisas que estavam escritas nos livros, segundo suas obras; consequentemente, os livros mencionados devem ser os livros que continham o registro de suas obras; e referem-se aos registros feitos na Terra. E o livro que era o livro da vida é o registro que se faz no céu; o princípio, portanto, concorda exatamente com a doutrina que vos é ordenada na revelação contida na carta que vos escrevi antes de deixar minha casa — para que todos os vossos registros sejam registrados no céu."},{"verse":8,"text":"Agora, a natureza desta ordenança consiste no poder do sacerdócio, pela revelação de Jesus Cristo, no qual se concede que tudo o que ligardes na Terra será ligado no céu e tudo o que desligardes na Terra será desligado no céu. Ou, em outras palavras, sob outro ponto de vista de tradução, tudo o que registrardes na Terra será registrado no céu e tudo o que não registrardes na Terra não será registrado no céu; pois pelos livros serão julgados os vossos mortos, segundo suas próprias obras, quer tenham eles mesmos cuidado das ordenanças em pessoa, quer por meio de seus agentes, segundo a ordenança que Deus preparou para sua salvação desde antes da fundação do mundo, segundo os registros que fizeram concernentes a seus mortos."},{"verse":9,"text":"A alguns a doutrina de que falamos poderá parecer muito arrojada — um poder que registra ou liga na Terra e liga nos céus. Contudo, em todas as épocas do mundo, sempre que o Senhor deu uma dispensação do sacerdócio a qualquer homem ou grupo de homens, por revelação real, esse poder sempre foi dado. Por isso, tudo o que esses homens fizeram com autoridade em nome do Senhor e fizeram-no verdadeira e fielmente, conservando um registro fiel e adequado do mesmo, tornou-se lei na Terra e nos céus e, de acordo com os decretos do grande Jeová, não podia ser revogado. Esta é uma palavra fiel. Quem a pode ouvir?"},{"verse":10,"text":"E também existe um precedente em Mateus 16:18, 19: Pois também eu te digo que tu és Pedro, e sobre esta pedra edificarei a minha igreja, e as portas do inferno não prevalecerão contra ela; e eu te darei as chaves do reino dos céus; e tudo o que ligares na Terra será ligado nos céus, e tudo o que desligares na Terra será desligado nos céus."},{"verse":11,"text":"Agora, o grande e importante segredo deste assunto e o summum bonum de toda a questão que se nos apresenta consiste em obterem-se os poderes do Santo Sacerdócio. Aquele a quem forem dadas essas chaves não terá dificuldade em obter um conhecimento dos fatos relativos à salvação dos filhos dos homens, tanto os mortos como os vivos."},{"verse":12,"text":"Nisto há glória e honra e imortalidade e vida eterna: A ordenança do batismo pela água, ou melhor, ser imerso na água para conformar-se à semelhança dos mortos, para que um princípio concorde com o outro; ser imerso na água e sair da água assemelha-se à ressurreição dos mortos ao saírem da sepultura; por isso instituiu-se essa ordenança para estabelecer uma relação com a ordenança do batismo pelos mortos, sendo à semelhança dos mortos."},{"verse":13,"text":"Por conseguinte, instituiu-se a fonte batismal como símbolo da sepultura e ordenou-se que fosse colocada abaixo do lugar onde os vivos costumam reunir-se, para representar os vivos e os mortos a fim de que cada coisa tenha sua semelhança e concordem uma com a outra — Aquilo que é terreno conforme o que é celestial, como declarou Paulo em 1 Coríntios 15:46, 47 e 48:"},{"verse":14,"text":"Mas não é primeiro o espiritual, senão o natural; depois o espiritual. O primeiro homem, da Terra, é terreno; o segundo homem, o Senhor, é do céu. Qual o terreno, tais são também os terrestres; e, qual o celestial, tais também os celestiais. E com a mesma precisão com que se fazem os registros da Terra relativos a vossos mortos, que são feitos com precisão, fazem-se os registros do céu. Este, portanto, é o poder de selar e ligar e, em certo sentido da palavra, as chaves do reino, que consistem na chave do conhecimento."},{"verse":15,"text":"E agora, meus amados irmãos e irmãs, eu vos asseguro que estes princípios referentes aos mortos e aos vivos não podem ser negligenciados no que tange à nossa salvação. Porque a sua salvação é necessária e essencial a nossa salvação, como diz Paulo com respeito aos pais — que eles, sem nós, não podem ser aperfeiçoados — nem podemos nós, sem nossos mortos, ser aperfeiçoados."},{"verse":16,"text":"E agora, com relação ao batismo pelos mortos, apresentarei outra citação de Paulo, em 1 Coríntios 15:29: Doutra maneira, que farão os que se batizam pelos mortos, se absolutamente os mortos não ressuscitam? Porque se batizam eles então pelos mortos?"},{"verse":17,"text":"E também, com relação a essa citação, mencionarei outra, tirada de um dos profetas que tinha os olhos fitos na restauração do sacerdócio, nas glórias a serem reveladas nos últimos dias e, de modo especial, no mais glorioso de todos os assuntos pertencentes ao evangelho eterno, ou seja, o batismo pelos mortos; pois Malaquias diz, no último capítulo, versículos cinco e seis: Eis que eu vos enviarei o profeta Elias, antes que venha o grande e terrível dia do Senhor; e ele converterá o coração dos pais aos filhos, e o coração dos filhos a seus pais; para que eu não venha, e fira a terra com maldição."},{"verse":18,"text":"Eu poderia ter feito uma tradução mais clara, mas é suficientemente clara como está, para servir ao meu propósito. É suficiente saber, neste caso, que a Terra será ferida com maldição, a menos que exista um elo de ligação de um ou outro tipo entre os pais e os filhos, sobre um assunto ou outro — e qual é esse assunto? É o batismo pelos mortos. Pois nós, sem eles, não podemos ser aperfeiçoados; nem podem eles, sem nós, ser aperfeiçoados. Nem podem eles nem podemos nós ser aperfeiçoados sem os que morreram no evangelho; pois é necessário, na introdução da dispensação da plenitude dos tempos, dispensação essa que está começando a introduzir-se, que uma total, completa e perfeita união e fusão de dispensações e chaves e poderes e glórias ocorram e sejam reveladas desde os dias de Adão até o tempo atual. E não somente isso, mas as coisas que nunca se revelaram desde a fundação do mundo, mas que se conservaram ocultas aos sábios e prudentes, serão reveladas a crianças e recém-nascidos nesta dispensação, que é a da plenitude dos tempos."},{"verse":19,"text":"Agora, o que ouvimos no evangelho que recebemos? Uma voz de alegria! Uma voz de misericórdia do céu; e uma voz de verdade saindo da Terra; alegres novas para os mortos; uma voz de alegria para os vivos e os mortos; boas novas de grande alegria. Quão formosos são sobre os montes os pés daqueles que anunciam alegres novas de coisas boas e que dizem a Sião: Eis que teu Deus reina! Como o orvalho de Carmelo, assim descerá sobre eles o conhecimento de Deus!"},{"verse":20,"text":"E também, o que ouvimos? Alegres novas de Cumora! Morôni, um anjo do céu, anunciando o cumprimento dos profetas — o livro a ser revelado. A voz do Senhor no ermo de Fayette, Condado de Sêneca, anunciando as três testemunhas que testificariam quanto ao livro! A voz de Miguel às margens do Susquehanna, identificando o diabo quando apareceu como um anjo de luz! A voz de Pedro, Tiago e João no ermo entre Harmony, Condado de Susquehanna, e Colesville, Condado de Broome, no rio Susquehanna, declarando-se possuidores das chaves do reino e da dispensação da plenitude dos tempos!"},{"verse":21,"text":"E também, a voz de Deus no quarto do velho Pai Whitmer, em Fayette, Condado de Sêneca; e em várias ocasiões e em lugares diversos, durante todas as viagens e tribulações desta Igreja de Jesus Cristo dos Santos dos Últimos Dias! E a voz de Miguel, o arcanjo, e a voz de Gabriel e de Rafael e de diversos anjos, de Miguel, ou seja, Adão, até o tempo atual, todos anunciando sua dispensação, seus direitos, suas chaves, suas honras, sua majestade e glória e o poder de seu sacerdócio; dando linha sobre linha, preceito sobre preceito; um pouco aqui, um pouco ali; dando-nos consolação pela proclamação do que está para vir, confirmando nossa esperança!"},{"verse":22,"text":"Irmãos, não prosseguiremos em tão grande causa? Ide avante e não para trás. Coragem, irmãos; e avante, avante para a vitória! Regozije-se vosso coração e muito se alegre. Prorrompa a Terra em canto. Entoem os mortos hinos de eterno louvor ao Rei Emanuel, que estabeleceu, antes da fundação do mundo, aquilo que nos permitiria redimi-los de sua prisão; pois os prisioneiros serão libertados."},{"verse":23,"text":"Que as montanhas gritem de alegria e todos vós, vales, clamai em alta voz; e todos vós, mares e terras secas, contai as maravilhas de vosso Eterno Rei! E vós, rios e riachos e ribeiros, fluí com alegria. Que as matas e todas as árvores do campo louvem ao Senhor; e vós, pedras sólidas, chorai de alegria! E que o sol, a lua e as estrelas da manhã cantem juntas e que todos os filhos de Deus gritem de alegria. E que as criações eternas proclamem seu nome para todo o sempre. E torno a dizer: Quão gloriosa é a voz que ouvimos do céu, proclamando a nossos ouvidos glória e salvação e honra e imortalidade e vida eterna; reinos, principados e poderes!"},{"verse":24,"text":"Eis que o grande dia do Senhor está perto; e quem suportará o dia de sua vinda e quem subsistirá quando ele aparecer? Pois ele é como o fogo do ourives e como o sabão dos lavandeiros; e assentar-se-á como um fundidor e purificador de prata e purificará os filhos de Levi e refiná-los-á como ouro e como prata, para que façam ao Senhor uma oferta em retidão. Que nós, portanto, como igreja e como povo e como santos dos últimos dias, façamos ao Senhor uma oferta em retidão; e apresentemos em seu templo santo, quando estiver terminado, um livro contendo os registros de nossos mortos, que seja digno de toda aceitação."},{"verse":25,"text":"Irmãos, tenho muitas coisas para vos dizer sobre o assunto; mas terminarei por agora e continuarei em outra ocasião. Subscrevo-me, como sempre, vosso humilde servo e amigo fiel."},{"verse":26,"text":"Joseph Smith."}]},{"chapter":129,"verses":[{"verse":1,"text":"No céu existem duas espécies de seres, a saber: Anjos, que são pessoas ressuscitadas e que têm um corpo de carne e ossos —"},{"verse":2,"text":"Por exemplo, Jesus disse: Apalpai-me e vede, pois um espírito não tem carne nem ossos, como vedes que eu tenho."},{"verse":3,"text":"Segundo: Os espíritos de homens justos tornados perfeitos, aqueles que não ressuscitaram, mas herdam a mesma glória."},{"verse":4,"text":"Quando aparecer um mensageiro dizendo ter uma mensagem de Deus, oferecei-lhe a mão e pedi-lhe que a aperte."},{"verse":5,"text":"Se for um anjo, ele o fará e sentireis sua mão."},{"verse":6,"text":"Se for o espírito de um homem justo tornado perfeito, ele virá em sua glória, porque essa é a única maneira em que pode aparecer —"},{"verse":7,"text":"Pedi-lhe que vos dê a mão e ele não se moverá, porque é contrário à ordem do céu que um homem justo engane; mas ele ainda assim transmitirá sua mensagem."},{"verse":8,"text":"Se for o diabo fazendo-se de anjo de luz, quando pedirdes que vos dê a mão, oferecer-vos-á a mão e não sentireis coisa alguma; podereis, portanto, identificá-lo."},{"verse":9,"text":"Essas são três importantes chaves pelas quais podereis saber se uma ministração provém de Deus."}]},{"chapter":130,"verses":[{"verse":1,"text":"Quando o Salvador se manifestar, vê-lo-emos como é. Veremos que é um homem como nós."},{"verse":2,"text":"E que a mesma sociabilidade que existe entre nós, aqui, existirá entre nós lá, só que será acompanhada de glória eterna, glória essa que não experimentamos agora."},{"verse":3,"text":"João 14:23 — A aparição do Pai e do Filho, nesse versículo, é uma aparição pessoal; e a ideia de que o Pai e o Filho habitam no coração do homem é uma velha concepção sectária e é falsa."},{"verse":4,"text":"Em resposta à pergunta — Não é calculado o tempo de Deus, o tempo dos anjos, o tempo dos profetas e o tempo dos homens de acordo com o planeta em que habitam?"},{"verse":5,"text":"Respondo: Sim. Mas os únicos anjos que ministram nesta Terra são os que pertencem ou que pertenceram a ela."},{"verse":6,"text":"Os anjos não habitam em um planeta como esta Terra;"},{"verse":7,"text":"Mas habitam na presença de Deus, em um globo semelhante a um mar de vidro e fogo, onde todas as coisas passadas, presentes e futuras manifestam-se para sua glória; e estão continuamente diante do Senhor."},{"verse":8,"text":"O lugar onde Deus habita é um grande Urim e Tumim."},{"verse":9,"text":"Esta Terra, em seu estado santificado e imortal, será transformada como em cristal e será um Urim e Tumim para os seus habitantes, pelo qual todas as coisas pertencentes a um reino inferior ou a todos os reinos de uma ordem inferior manifestar-se-ão àqueles que nela habitam; e esta Terra será de Cristo."},{"verse":10,"text":"Então a pedra branca, mencionada em Apocalipse 2:17, tornar-se-á um Urim e Tumim para toda pessoa que receber uma; e por ela tornar-se-ão conhecidas as coisas pertencentes a uma ordem superior de reinos;"},{"verse":11,"text":"E é dada uma pedra branca a cada um dos que entram no reino celestial, na qual está escrito um novo nome que ninguém conhece, a não ser aquele que o recebe. O novo nome é a palavra-chave."},{"verse":12,"text":"Profetizo, em nome do Senhor Deus, que o princípio das dificuldades que causarão muito derramamento de sangue antes da vinda do Filho do Homem será na Carolina do Sul."},{"verse":13,"text":"Provavelmente surgirá por causa da questão dos escravos. Isto me foi declarado por uma voz, enquanto eu orava fervorosamente sobre o assunto, em 25 de dezembro de 1832."},{"verse":14,"text":"Certa vez eu estava orando fervorosamente para saber o tempo da vinda do Filho do Homem, quando ouvi uma voz dizer o seguinte:"},{"verse":15,"text":"Joseph, meu filho, se viveres até a idade de oitenta e cinco anos, verás a face do Filho do Homem; portanto, que isto seja suficiente e não me importunes mais com esse assunto."},{"verse":16,"text":"Assim fiquei sem poder decidir se essa vinda se referia ao início do milênio ou a alguma aparição prévia, ou ainda, se eu haveria de morrer e assim ver-lhe a face."},{"verse":17,"text":"Creio que a vinda do Filho do Homem não será antes desse tempo."},{"verse":18,"text":"Qualquer princípio de inteligência que alcançarmos nesta vida surgirá conosco na ressurreição."},{"verse":19,"text":"E se nesta vida uma pessoa, por sua diligência e obediência, adquirir mais conhecimento e inteligência do que outra, ela terá tanto mais vantagem no mundo futuro."},{"verse":20,"text":"Há uma lei, irrevogavelmente decretada no céu antes da fundação deste mundo, na qual todas as bênçãos se baseiam —"},{"verse":21,"text":"E quando recebemos uma bênção de Deus, é por obediência à lei na qual ela se baseia."},{"verse":22,"text":"O Pai tem um corpo de carne e ossos tão tangível como o do homem; o Filho também; mas o Espírito Santo não tem um corpo de carne e ossos, mas é um personagem de Espírito. Se assim não fora, o Espírito Santo não poderia habitar em nós."},{"verse":23,"text":"Um homem pode receber o Espírito Santo e esse pode descer sobre ele e não permanecer com ele."}]},{"chapter":131,"verses":[{"verse":1,"text":"Na glória celestial há três céus ou graus;"},{"verse":2,"text":"E para obter o mais elevado, um homem precisa entrar nesta ordem do sacerdócio [que significa o novo e eterno convênio do casamento];"},{"verse":3,"text":"E se não o fizer, não poderá obtê-lo."},{"verse":4,"text":"Poderá entrar em outro, mas esse será o fim de seu reino; ele não poderá ter descendência."},{"verse":5,"text":"(17 de maio de 1843) A palavra mais segura de profecia significa um homem saber, por revelação e pelo espírito de profecia, que está selado para a vida eterna pelo poder do Santo Sacerdócio."},{"verse":6,"text":"É impossível ao homem ser salvo em ignorância."},{"verse":7,"text":"Não existe algo como matéria imaterial. Todo espírito é matéria, mas é mais refinado ou puro e só pode ser discernido por olhos mais puros;"},{"verse":8,"text":"Não podemos vê-lo; mas quando nosso corpo for purificado, veremos que ele é todo matéria."}]},{"chapter":132,"verses":[{"verse":1,"text":"Em verdade, assim diz o Senhor a ti, meu servo Joseph, já que te dirigiste a mim para saber e compreender como eu, o Senhor, justifiquei meus servos Abraão, Isaque e Jacó; assim como Moisés, Davi e Salomão, meus servos, no que diz respeito ao princípio e doutrina de terem muitas esposas e concubinas —"},{"verse":2,"text":"Eis que eu sou o Senhor teu Deus e responder-te-ei no tocante a esse assunto."},{"verse":3,"text":"Portanto, prepara o teu coração para receber as instruções que estou prestes a dar-te e para obedecer a elas; porque todos a quem esta lei é revelada devem obedecê-la."},{"verse":4,"text":"Pois eis que eu te revelo um novo e eterno convênio; e se não cumprires esse convênio, então serás condenado, porque ninguém pode rejeitar esse convênio e ter permissão de entrar em minha glória."},{"verse":5,"text":"Pois todos os que receberem uma bênção de minhas mãos obedecerão à lei que foi designada para essa bênção e suas condições, como instituídas desde antes da fundação do mundo."},{"verse":6,"text":"E quanto ao novo e eterno convênio, foi instituído para a plenitude de minha glória; e aquele que recebe sua plenitude deve cumprir a lei e cumpri-la-á; caso contrário, será condenado, diz o Senhor Deus."},{"verse":7,"text":"E em verdade eu te digo que estas são as condições dessa lei: Todos os convênios, contratos, vínculos, compromissos, juramentos, votos, práticas, ligações, associações ou expectativas que não forem feitos nem acertados nem selados pelo Santo Espírito da promessa, tanto para esta vida como para toda a eternidade, por meio daquele que foi ungido e isso também de maneira muito sagrada, por revelação e mandamento, por meio de meu ungido, a quem designei na Terra para possuir esse poder (e designei meu servo Joseph para possuir esse poder nos últimos dias — e nunca há mais que um, na Terra, ao mesmo tempo, a quem esse poder e as chaves desse sacerdócio são conferidas) não terão eficácia, virtude ou vigor algum na ressurreição dos mortos nem depois dela; porque todos os contratos que não são realizados com esse propósito têm fim quando os homens morrem."},{"verse":8,"text":"Eis que minha casa é uma casa de ordem, diz o Senhor Deus, e não uma casa de confusão."},{"verse":9,"text":"Aceitarei eu uma oferta, diz o Senhor, que não seja feita em meu nome?"},{"verse":10,"text":"Ou receberei de vossas mãos aquilo que não determinei?"},{"verse":11,"text":"E determinarei algo, diz o Senhor, a menos que seja por lei, como eu e meu Pai estabelecemos para vós antes da fundação do mundo?"},{"verse":12,"text":"Eu sou o Senhor vosso Deus; e dou-vos este mandamento: Ninguém virá ao Pai senão por mim ou pela minha palavra, a qual é a minha lei, diz o Senhor."},{"verse":13,"text":"E tudo que existe no mundo, quer seja ordenado por homens, por tronos ou principados ou poderes ou coisas de renome, sejam quais forem, que não for por mim nem pela minha palavra, diz o Senhor, será derrubado e não permanecerá depois que os homens morrerem; nem na ressurreição nem depois da ressurreição, diz o Senhor vosso Deus."},{"verse":14,"text":"Pois todas as coisas que permanecem são por mim; e todas as coisas que não são por mim serão abaladas e destruídas."},{"verse":15,"text":"Portanto, se um homem se casar com uma mulher no mundo e não se casar com ela por meu intermédio nem por minha palavra; e fizer convênio com ela enquanto estiver no mundo e ela com ele, seu convênio e casamento não terão valor quando morrerem e quando estiverem fora do mundo; portanto, não estarão ligados por lei alguma quando estiverem fora do mundo."},{"verse":16,"text":"Portanto, quando estão fora do mundo não se casam nem são dados em casamento, mas são designados anjos no céu, anjos esses que são servos ministradores, para ministrar em favor daqueles que são dignos de um peso muito maior, imensurável e eterno de glória."},{"verse":17,"text":"Porque esses anjos não guardaram minha lei; portanto, não podem crescer, mas permanecem separados e solteiros, sem exaltação, no seu estado de salvação, por toda a eternidade; e daí em diante não são deuses, mas anjos de Deus para todo o sempre."},{"verse":18,"text":"E também, em verdade vos digo: Se um homem se casar com uma mulher e fizer um convênio com ela para esta vida e para toda a eternidade; e se esse convênio não for feito por mim nem por minha palavra, que é a minha lei, e não for selado pelo Santo Espírito da promessa, por meio daquele que ungi e designei com esse poder, não será válido nem estará em vigor quando se encontrarem fora do mundo, porque não foram unidos por mim nem por minha palavra, diz o Senhor; quando estiverem fora do mundo não será aceito lá, porque não poderão passar pelos anjos e pelos deuses designados para ali estar; não podem, portanto, herdar minha glória; pois minha casa é uma casa de ordem, diz o Senhor Deus."},{"verse":19,"text":"E também, em verdade vos digo: Se um homem se casar com uma mulher pela minha palavra, que é a minha lei, e pelo novo e eterno convênio e for selado pelo Santo Espírito da promessa por aquele que foi ungido, a quem conferi esse poder e as chaves desse sacerdócio e for dito a eles: Surgireis na primeira ressurreição; e, se for depois da primeira ressurreição, na próxima ressurreição; e herdareis tronos, reinos, principados e poderes, domínios, todas as alturas e profundidades — então será escrito no Livro da Vida do Cordeiro que ele não cometerá assassinato, derramando sangue inocente; e se guardarem meu convênio e não cometerem assassinato, derramando sangue inocente, ser-lhes-á feito de acordo com todas as coisas que meu servo disse, nesta vida e por toda a eternidade; e estará em pleno vigor quando estiverem fora do mundo; e passarão pelos anjos e pelos deuses ali colocados, rumo a sua exaltação e glória em todas as coisas, conforme selado sobre sua cabeça; glória essa que será uma plenitude e uma continuação das sementes para todo o sempre."},{"verse":20,"text":"Então serão deuses, pois não terão fim; portanto, serão de eternidade em eternidade, porque continuarão; então serão colocados sobre tudo, porque todas as coisas lhes serão sujeitas. Então serão deuses, porque terão todo o poder e os anjos lhes serão sujeitos."},{"verse":21,"text":"Em verdade, em verdade vos digo: A não ser que guardeis minha lei, não obtereis esta glória."},{"verse":22,"text":"Pois estreita é a porta e apertado o caminho que leva à exaltação e à continuação das vidas, e poucos há que o encontram, porque no mundo não me recebeis nem me conheceis."},{"verse":23,"text":"Mas se me receberdes no mundo, então me conhecereis e recebereis vossa exaltação; para que, onde eu estiver, estejais vós também."},{"verse":24,"text":"Isto é o significado de vidas eternas: Conhecer o único sábio e verdadeiro Deus e Jesus Cristo, a quem ele enviou. Eu sou ele. Recebei, portanto, minha lei."},{"verse":25,"text":"Larga é a porta e espaçoso o caminho que conduz às mortes; e muitos há que entram por ela, porque não me recebem nem guardam minha lei."},{"verse":26,"text":"Em verdade, em verdade vos digo: Se um homem se casar com uma mulher de acordo com minha palavra e eles forem selados pelo Santo Espírito da promessa, segundo o meu preceito, e ele ou ela cometer qualquer pecado ou transgressão contra o novo e eterno convênio e toda sorte de blasfêmias; e se eles não cometerem assassinato, derramando sangue inocente, ainda surgirão na primeira ressurreição e entrarão para sua exaltação; mas serão destruídos na carne e entregues às bofetadas de Satanás até o dia da redenção, diz o Senhor Deus."},{"verse":27,"text":"A blasfêmia contra o Espírito Santo, que não será perdoada no mundo nem fora do mundo, é cometer assassinato derramando sangue inocente e consentir em minha morte depois de terdes recebido meu novo e eterno convênio, diz o Senhor Deus; e aquele que não guarda esta lei, de modo algum poderá entrar para a minha glória, mas será condenado, diz o Senhor."},{"verse":28,"text":"Eu sou o Senhor teu Deus e dar-te-ei a lei de meu santo sacerdócio, conforme ordenado por mim e meu Pai antes que o mundo existisse."},{"verse":29,"text":"Abraão recebeu todas as coisas que recebeu, por revelação e mandamento, pela minha palavra, diz o Senhor; e entrou para sua exaltação e assenta-se em seu trono."},{"verse":30,"text":"Abraão recebeu promessas relativas a sua semente e ao fruto de seus lombos — dos quais tu provéns, meu servo Joseph — promessas que haviam de continuar enquanto eles estivessem no mundo; e quanto a Abraão e sua semente, haviam de continuar fora do mundo; tanto no mundo como fora do mundo continuariam tão inumeráveis quanto as estrelas; ou, se contásseis os grãos de areia na praia, não poderíeis enumerar."},{"verse":31,"text":"Esta promessa é vossa também, porque sois de Abraão e a promessa foi feita a Abraão; e por essa lei continuam as obras de meu Pai, nas quais ele se glorifica."},{"verse":32,"text":"Ide, portanto, e fazei as obras de Abraão; guardai minha lei e sereis salvos."},{"verse":33,"text":"Mas se não guardardes minha lei, não podereis receber a promessa de meu Pai, que ele fez a Abraão."},{"verse":34,"text":"Deus deu a ordem a Abraão e Sara entregou-lhe Agar como esposa. E por que ela o fez? Porque essa era a lei; e de Agar descendeu muita gente. Isso, portanto, foi para o cumprimento, entre outras coisas, das promessas."},{"verse":35,"text":"Estava Abraão, portanto, sob condenação? Em verdade vos digo que não; porque eu, o Senhor, dei-lhe essa ordem."},{"verse":36,"text":"Foi ordenado a Abraão que sacrificasse seu filho Isaque; não obstante, estava escrito: Não matarás. Abraão, contudo, não se negou e isso lhe foi imputado por retidão."},{"verse":37,"text":"Abraão recebeu concubinas e elas geraram-lhe filhos; e isso lhe foi atribuído como sendo retidão, porque elas lhe foram dadas e ele obedeceu à minha lei; como também Isaque e Jacó nada mais fizeram do que aquilo que lhes fora ordenado; e porque nada mais fizeram do que as coisas que lhes foram ordenadas, entraram para a sua exaltação, de acordo com as promessas; e assentam-se em tronos, e não são anjos, mas são deuses."},{"verse":38,"text":"Davi também recebeu muitas esposas e concubinas, assim como Salomão e Moisés, meus servos; e também muitos outros de meus servos, desde o princípio da criação até agora; e em nada pecaram, a não ser nas coisas que não receberam de mim."},{"verse":39,"text":"As esposas e concubinas de Davi foram-lhe dadas por mim, pela mão de Natã, meu servo, e outros profetas que possuíam as chaves desse poder; e em nenhuma dessas coisas pecou ele contra mim, a não ser no caso de Urias e sua mulher; e, portanto, caiu de sua exaltação e recebeu sua porção; e não as herdará fora do mundo, porque as dei a outro, diz o Senhor."},{"verse":40,"text":"Eu sou o Senhor teu Deus e dei a ti, meu servo Joseph, uma designação; e restauro todas as coisas. Pede o que desejares e ser-te-á dado de acordo com minha palavra."},{"verse":41,"text":"E sendo que me indagaste a respeito do adultério, em verdade, em verdade eu te digo: Se um homem receber uma esposa pelo novo e eterno convênio e ela estiver com outro homem que eu não lhe houver designado pela santa unção, ela terá cometido adultério e será destruída."},{"verse":42,"text":"Se ela não tiver entrado no novo e eterno convênio e estiver com outro homem, terá cometido adultério."},{"verse":43,"text":"E se o seu marido estiver com outra mulher, estando sob voto, terá quebrado seu voto e cometido adultério."},{"verse":44,"text":"E se ela não tiver cometido adultério, mas for inocente e não tiver quebrado seu voto e o souber e eu o revelar a ti, meu servo Joseph, então terás poder, pelo poder de meu santo sacerdócio, para tomá-la e dá-la a um que não haja cometido adultério, mas tenha sido fiel; pois ele será feito governante de muitos."},{"verse":45,"text":"Porque te conferi as chaves e poderes do sacerdócio, pelo qual restauro todas as coisas; e faço-te saber todas as coisas no devido tempo."},{"verse":46,"text":"E em verdade, em verdade eu te digo que tudo o que selares na Terra será selado no céu; e tudo o que ligares na Terra, em meu nome e pela minha palavra, diz o Senhor, será ligado eternamente nos céus; e todos os pecados que remires na Terra serão remidos eternamente nos céus; e todos os pecados que retiveres na Terra serão retidos no céu."},{"verse":47,"text":"E também em verdade eu te digo: Quem abençoares eu abençoarei e quem amaldiçoares eu amaldiçoarei, diz o Senhor; pois eu, o Senhor, sou teu Deus."},{"verse":48,"text":"E também em verdade eu te digo, meu servo Joseph, que tudo o que deres na Terra e a quem quer que deres alguém na Terra, pela minha palavra e de acordo com minha lei, tudo isso será visitado com bênçãos e não com maldições e com o meu poder, diz o Senhor; e não receberá condenação, quer na Terra quer no céu."},{"verse":49,"text":"Pois eu sou o Senhor teu Deus e estarei contigo até o fim do mundo e por toda a eternidade; pois em verdade selo sobre ti tua exaltação e preparo-te um trono no reino de meu Pai, com Abraão, teu pai."},{"verse":50,"text":"Eis que tenho visto teus sacrifícios e perdoarei todos os teus pecados; vi teus sacrifícios em obediência ao que te ordenei. Vai, portanto, e preparar-te-ei um meio de escape, assim como aceitei de Abraão a oferta de seu filho Isaque."},{"verse":51,"text":"Em verdade, eu te digo: Um mandamento dou à minha serva Emma Smith, tua esposa, que a ti dei, de que ela se contenha e não participe daquilo que te ordenei oferecer-lhe; porque eu o fiz, diz o Senhor, para provar-vos a todos, como fiz com Abraão; e para exigir uma oferta de vossas mãos, por convênio e sacrifício."},{"verse":52,"text":"E que minha serva Emma Smith receba todas as que foram dadas a meu servo Joseph e que são virtuosas e puras perante mim; e as que não são puras e que se disseram puras serão destruídas, diz o Senhor Deus."},{"verse":53,"text":"Porque eu sou o Senhor vosso Deus, e obedecereis à minha voz; e concedo ao meu servo Joseph ser governante de muitas coisas; pois sobre o pouco foi fiel e, daqui em diante, fortalecê-lo-ei."},{"verse":54,"text":"E ordeno que minha serva, Emma Smith, permaneça com meu servo Joseph, apegando-se a ele e a nenhum outro. Mas se não guardar esse mandamento, ela será destruída, diz o Senhor; porque eu sou o Senhor vosso Deus e destruí-la-ei se ela não guardar minha lei."},{"verse":55,"text":"Mas se ela não guardar esse mandamento, então meu servo Joseph fará todas as coisas para ela, assim como ele disse; e abençoá-lo-ei e multiplicá-lo-ei e dar-lhe-ei cem vezes tanto neste mundo em pais e mães, irmãos e irmãs, casas e terras, esposas e filhos e coroas de vidas eternas nos mundos eternos."},{"verse":56,"text":"E também, em verdade eu digo: Que minha serva perdoe a Joseph suas ofensas; e então a ela ser-lhe-ão perdoadas suas ofensas, as que cometeu contra mim; e eu, o Senhor teu Deus, abençoá-la-ei e multiplicá-la-ei, e farei com que seu coração se regozije."},{"verse":57,"text":"E também digo: Que meu servo Joseph não se desfaça de seus bens para que não venha um inimigo e o destrua; porque Satanás procura destruir; pois eu sou o Senhor vosso Deus e ele é meu servo; e eis que estou com ele, como estive com Abraão, vosso pai, até sua exaltação e glória."},{"verse":58,"text":"Ora, no tocante à lei do sacerdócio, há muitas coisas referentes a ela."},{"verse":59,"text":"Em verdade, se um homem for chamado por meu Pai, como o foi Aarão, pela minha própria voz e pela voz daquele que me enviou; e eu o tiver investido das chaves do poder desse sacerdócio, se ele fizer qualquer coisa em meu nome e de acordo com minha lei e por minha palavra, não cometerá pecado e justificá-lo-ei."},{"verse":60,"text":"Que ninguém, portanto, censure meu servo Joseph, porque eu o justificarei; pois ele fará o sacrifício que exijo de suas mãos por suas transgressões, diz o Senhor teu Deus."},{"verse":61,"text":"E também, no tocante à lei do sacerdócio: Se um homem desposar uma virgem e desejar desposar outra e a primeira der seu consentimento; e se ele desposar a segunda e elas forem virgens e não estiverem comprometidas com qualquer outro homem, então ele estará justificado; ele não pode cometer adultério, porque elas lhe foram dadas; pois ele não pode cometer adultério com o que lhe pertence e a ninguém mais."},{"verse":62,"text":"E se dez virgens lhe forem dadas por essa lei, ele não estará cometendo adultério, porque elas lhe pertencem e lhe foram dadas; portanto, ele está justificado."},{"verse":63,"text":"Mas se uma ou qualquer das dez virgens, depois de desposada, estiver com outro homem, terá cometido adultério e será destruída; porque elas lhe são dadas para multiplicar e encher a Terra, de acordo com meu mandamento, e para cumprir a promessa feita por meu Pai antes da fundação do mundo e para sua exaltação nos mundos eternos, a fim de gerar as almas dos homens; pois nisso se perpetua a obra de meu Pai, para que ele seja glorificado."},{"verse":64,"text":"E também, em verdade, em verdade vos digo: Se um homem que possui as chaves desse poder tiver uma esposa e ensinar-lhe a lei do meu sacerdócio, no que concerne a essas coisas, ela deverá acreditar nele e apoiá-lo e ajudá-lo; caso contrário será destruída, diz o Senhor vosso Deus; pois eu a destruirei; pois magnificarei meu nome em todos os que recebem e guardam minha lei."},{"verse":65,"text":"Portanto, ser-me-á lícito, se ela não aceitar esta lei, que ele receba todas as coisas que eu, o Senhor seu Deus, lhe der, porque ela não acreditou e não o apoiou de acordo com minha palavra; e ela então se torna a transgressora; e ele será isento da lei de Sara, que apoiou Abraão de acordo com a lei, quando ordenei que Abraão tomasse Agar como esposa."},{"verse":66,"text":"E agora, no tocante a esta lei, em verdade, em verdade vos digo: Revelar-te-ei mais no futuro; portanto, que isto seja suficiente por agora. Eis que eu sou o Alfa e o Ômega. Amém."}]},{"chapter":133,"verses":[{"verse":1,"text":"Escutai, ó povo da minha igreja, diz o Senhor vosso Deus, e ouvi a voz do Senhor no que concerne a vós —"},{"verse":2,"text":"O Senhor, que subitamente virá ao seu templo; o Senhor, que descerá sobre o mundo com maldição, para julgar; sim, sobre todas as nações que se esqueceram de Deus e sobre todos os ímpios dentre vós."},{"verse":3,"text":"Pois ele desnudará o santo braço aos olhos de todas as nações e todos os confins da Terra verão a salvação de seu Deus."},{"verse":4,"text":"Portanto, preparai-vos, preparai-vos, ó meu povo; santificai-vos; reuni-vos, ó povo da minha igreja, na terra de Sião; todos vós a quem não foi ordenado que permanecessem."},{"verse":5,"text":"Deixai Babilônia. Sede puros, vós que portais os vasos do Senhor."},{"verse":6,"text":"Convocai vossas assembleias solenes e falai frequentemente uns aos outros. E que todo homem invoque o nome do Senhor."},{"verse":7,"text":"Sim, em verdade torno a dizer-vos que chegada é a hora em que a voz do Senhor se dirige a vós: Deixai Babilônia; reuni-vos dentre as nações, dos quatro ventos, de um extremo do céu até o outro."},{"verse":8,"text":"Enviai os élderes de minha igreja às nações longínquas; às ilhas do mar; enviai-os às nações estrangeiras; clamai a todas as nações, primeiro aos gentios e depois aos judeus."},{"verse":9,"text":"E eis que este será seu clamor e a voz do Senhor a todo o povo: Ide à terra de Sião, para que as fronteiras de meu povo se expandam e suas estacas se fortaleçam e para que Sião se estenda pelas regiões circunvizinhas."},{"verse":10,"text":"Sim, que o clamor alcance todos os povos: Despertai e erguei-vos e saí ao encontro do Esposo; eis que o Esposo vem; saí para encontrá-lo. Preparai-vos para o grande dia do Senhor."},{"verse":11,"text":"Vigiai, portanto, porque não sabeis o dia nem a hora."},{"verse":12,"text":"Portanto, os que estiverem no meio dos gentios, fujam para Sião."},{"verse":13,"text":"E os que forem de Judá fujam para Jerusalém, para as montanhas da casa do Senhor."},{"verse":14,"text":"Saí dentre as nações, sim, de Babilônia, do meio da iniquidade, que é a Babilônia espiritual."},{"verse":15,"text":"Mas em verdade assim diz o Senhor: Que vossa fuga não seja às pressas, mas que se preparem todas as coisas com antecedência; e o que for não olhe para trás, para que não lhe sobrevenha uma destruição repentina."},{"verse":16,"text":"Escutai e ouvi, ó habitantes da Terra. Escutai juntos, vós, élderes da minha igreja, e ouvi a voz do Senhor; porque ele clama a todos os homens e ordena que todos os homens, em todas as partes, se arrependam."},{"verse":17,"text":"Pois eis que o Senhor Deus enviou o anjo clamando no meio do céu, dizendo: Preparai o caminho do Senhor e endireitai as suas veredas, porque a hora de sua vinda está próxima —"},{"verse":18,"text":"Quando o Cordeiro aparecer no Monte Sião e, com ele, cento e quarenta e quatro mil, tendo o nome de seu Pai escrito na testa."},{"verse":19,"text":"Portanto, preparai-vos para a vinda do Esposo; saí, saí para encontrá-lo."},{"verse":20,"text":"Pois eis que ele estará de pé sobre o Monte das Oliveiras e sobre o grandioso oceano, sim, o grande abismo, e sobre as ilhas do mar e sobre a terra de Sião."},{"verse":21,"text":"E a sua voz sairá de Sião e ele falará de Jerusalém; e ouvir-se-á a sua voz entre todo o povo;"},{"verse":22,"text":"E será uma voz como a voz de muitas águas e como a voz de um grande trovão, que abaterá as montanhas; e não se acharão os vales."},{"verse":23,"text":"Ele ordenará ao grande abismo e este será empurrado para os países do norte e as ilhas se tornarão uma só terra;"},{"verse":24,"text":"E a terra de Jerusalém e a terra de Sião voltarão para seu próprio lugar; e a Terra será como era antes de sua divisão."},{"verse":25,"text":"E o Senhor, sim, o Salvador, permanecerá no meio de seu povo e reinará sobre toda a carne."},{"verse":26,"text":"E aqueles que estiverem nos países do norte serão lembrados pelo Senhor; e os seus profetas ouvirão a sua voz e não mais se conterão; e ferirão as pedras e o gelo se derreterá diante deles."},{"verse":27,"text":"E erguer-se-á uma estrada no meio do grande abismo."},{"verse":28,"text":"Seus inimigos tornar-se-ão uma presa para eles;"},{"verse":29,"text":"E nos desertos estéreis surgirão poços de água viva; e o solo ressequido já não será uma terra sedenta."},{"verse":30,"text":"E trarão seus ricos tesouros para os filhos de Efraim, meus servos."},{"verse":31,"text":"E as extremidades dos outeiros eternos estremecerão em sua presença."},{"verse":32,"text":"E lá cairão e serão coroados de glória, sim, em Sião, pelas mãos dos servos do Senhor, os filhos de Efraim."},{"verse":33,"text":"E encher-se-ão de cânticos de alegria eterna."},{"verse":34,"text":"Eis que essa é a bênção do Deus Eterno sobre as tribos de Israel e a mais rica bênção sobre a cabeça de Efraim e seus companheiros."},{"verse":35,"text":"E também os da tribo de Judá, após sua dor, serão santificados em santidade perante o Senhor, para habitar em sua presença dia e noite, para todo o sempre."},{"verse":36,"text":"E agora, em verdade diz o Senhor, para que estas coisas sejam conhecidas entre vós, ó habitantes da Terra: Enviei meu anjo voando pelo meio do céu, com o evangelho eterno, e ele apareceu a alguns e entregou-o ao homem e aparecerá a muitos que habitam na Terra."},{"verse":37,"text":"E este evangelho será pregado a toda nação e tribo e língua e povo."},{"verse":38,"text":"E os servos de Deus irão avante, dizendo em alta voz: Temei a Deus e dai-lhe glória, porque chegada é a hora de seu julgamento;"},{"verse":39,"text":"E adorai aquele que fez o céu e a Terra e o mar e as fontes das águas —"},{"verse":40,"text":"Clamando ao nome do Senhor dia e noite, dizendo: Oh! Que fendas os céus; que desças; que os montes se escoem diante de tua face!"},{"verse":41,"text":"E isso se cumprirá sobre sua cabeça; pois a presença do Senhor será como o fogo de fundição que queima e como o fogo que faz ferver as águas."},{"verse":42,"text":"Ó Senhor, tu descerás para tornar conhecido teu nome a teus adversários; e todas as nações tremerão em tua presença —"},{"verse":43,"text":"Quando fizeres coisas terríveis, coisas que eles não esperam;"},{"verse":44,"text":"Sim, quando desceres e as montanhas se escoarem em tua presença, encontrarás aquele que se regozija e pratica retidão, que se lembra de ti em teus caminhos."},{"verse":45,"text":"Pois desde o princípio do mundo homem algum ouviu nem percebeu pelo ouvido, nem olho algum viu, ó Deus, além de ti, quão grandiosas são as coisas que preparaste para aquele que espera por ti."},{"verse":46,"text":"E dir-se-á: Quem é este que vem de Deus, no céu, com vestes tingidas; sim, das regiões desconhecidas, vestido com seu traje glorioso, andando na grandiosidade de sua força?"},{"verse":47,"text":"E ele dirá: Eu sou o que fala com retidão, que tem poder para salvar."},{"verse":48,"text":"E o Senhor estará vestido de vermelho e suas vestes serão como a do que pisa no lagar de vinho."},{"verse":49,"text":"E tão grandiosa será a glória de sua presença, que o sol esconderá a face de vergonha e a lua reterá sua luz e as estrelas serão arremessadas de seus lugares."},{"verse":50,"text":"E ouvir-se-á a sua voz: Eu sozinho pisei no lagar e sobre todos os povos trouxe julgamento; e ninguém estava comigo;"},{"verse":51,"text":"E esmaguei-os no meu furor e pisei-os em minha ira e seu sangue salpiquei em minhas vestes e manchei toda a minha vestidura; pois esse era o dia da vingança que estava em meu coração."},{"verse":52,"text":"E agora, chegado é o ano de meus remidos; e eles mencionarão a bondade amorosa de seu Senhor e tudo que ele lhes conferiu de acordo com sua benignidade e de acordo com sua bondade amorosa, para todo o sempre."},{"verse":53,"text":"Em todas as suas aflições ele afligiu-se. E o anjo de sua presença salvou-os; e, em seu amor e em sua piedade redimiu-os e sustentou-os e carregou-os em todos os dias da antiguidade;"},{"verse":54,"text":"Sim, e também Enoque e os que estavam com ele; os profetas que existiram antes dele; e também Noé e os que existiram antes dele; e também Moisés e os que existiram antes dele;"},{"verse":55,"text":"E de Moisés a Elias, o profeta, e de Elias a João, os quais estavam com Cristo em sua ressurreição; e os santos apóstolos, com Abraão, Isaque e Jacó, estarão na presença do Cordeiro."},{"verse":56,"text":"E as sepulturas dos santos serão abertas; e surgirão, pondo-se à direita do Cordeiro quando ele aparecer no Monte Sião e na cidade santa, a Nova Jerusalém; e entoarão o canto do Cordeiro, noite e dia, para todo o sempre."},{"verse":57,"text":"E por essa razão, para que os homens se tornassem participantes das glórias que seriam reveladas, o Senhor enviou a plenitude do seu evangelho, o seu convênio eterno, arrazoando com clareza e simplicidade —"},{"verse":58,"text":"A fim de preparar os fracos para as coisas que advirão à Terra, como também para o trabalho do Senhor, no dia em que os fracos confundirem os sábios e o pequeno se tornar uma nação poderosa e dois puserem em fuga dezenas de milhares."},{"verse":59,"text":"E com as coisas fracas do mundo o Senhor açoitará as nações pelo poder de seu Espírito."},{"verse":60,"text":"E por esse motivo deram-se estes mandamentos; ordenou-se que fossem escondidos do mundo no dia em que foram dados, mas agora devem ser enviados a toda carne —"},{"verse":61,"text":"E isto segundo a mente e a vontade do Senhor, que reina sobre toda a carne."},{"verse":62,"text":"E ao que se arrepende e se santifica diante do Senhor será dada a vida eterna."},{"verse":63,"text":"E sobre os que não dão ouvidos à voz do Senhor cumprir-se-á o que foi escrito pelo profeta Moisés, que disse que eles seriam afastados dentre o povo."},{"verse":64,"text":"E também o que foi escrito pelo profeta Malaquias: Porque eis que aquele dia vem ardendo como fornalha; todos os soberbos e todos os que cometem impiedade serão como a palha; e o dia que está para vir os abrasará, diz o Senhor dos Exércitos, de sorte que lhes não deixará nem raiz nem ramo."},{"verse":65,"text":"Portanto, esta será a resposta do Senhor a eles:"},{"verse":66,"text":"No dia em que vim aos meus, nenhum de vós me recebeu e fostes expulsos."},{"verse":67,"text":"Quando tornei a chamar, nenhum de vós me respondeu; contudo, meu braço não se encolheu de modo algum, de maneira que eu não pudesse remir, nem meu poder para livrar."},{"verse":68,"text":"Eis que, com minha repreensão, seco o mar. Transformo os rios em deserto; seus peixes cheiram mal e morrem de sede."},{"verse":69,"text":"Visto de escuridão os céus e faço de saco sua vestidura."},{"verse":70,"text":"E isso recebereis de minha mão — em tormento jazereis."},{"verse":71,"text":"Eis que não haverá quem vos livre; pois não obedecestes à minha voz quando dos céus vos chamei; não crestes em meus servos, e quando vos foram enviados, não os recebestes."},{"verse":72,"text":"Portanto, selaram o testemunho e ligaram a lei; e fostes entregues às trevas."},{"verse":73,"text":"Estes irão para as trevas exteriores, onde há choro e pranto e ranger de dentes."},{"verse":74,"text":"Eis que o Senhor vosso Deus o disse. Amém."}]},{"chapter":134,"verses":[{"verse":1,"text":"Nós cremos que os governos foram instituídos por Deus em benefício do homem; e que ele considera os homens responsáveis por seus atos em relação aos mesmos, tanto na formulação de leis como em sua execução, para o bem e segurança da sociedade."},{"verse":2,"text":"Cremos que nenhum governo pode existir em paz a não ser que tais leis sejam feitas e mantidas invioladas, de modo a garantir a todo indivíduo o livre exercício de consciência, o direito e domínio de propriedade e a proteção da vida."},{"verse":3,"text":"Cremos que todos os governos requerem necessariamente representantes e magistrados civis para executar suas leis; e devem-se procurar e apoiar pessoas para administrar a lei com equidade e justiça, pela voz do povo, caso se trate de uma república, ou pela vontade do soberano."},{"verse":4,"text":"Cremos que a religião foi instituída por Deus; e que os homens são responsáveis perante ele e somente ele, por seu exercício, a menos que suas opiniões religiosas os levem a infringir os direitos e a liberdade de outrem; não cremos, porém, que as leis humanas tenham o direito de interferir na prescrição de regras de adoração para oprimir a consciência dos homens nem de ditar formas de devoção pública ou particular; cremos que o magistrado civil deve reprimir o crime, mas jamais controlar consciências; deve castigar delitos, mas nunca suprimir a liberdade da alma."},{"verse":5,"text":"Cremos que todos os homens têm a responsabilidade de suster e apoiar o governo do lugar em que residem, desde que protegidos em seus direitos inerentes e inalienáveis pelas leis de tal governo; e que o motim e a rebelião são inadequados a todo cidadão assim protegido e devem ser punidos convenientemente; e que todos os governos têm o direito de estabelecer leis que, a seu ver, sejam mais adequadas para assegurar os interesses públicos; ao mesmo tempo, contudo, mantendo sagrada a liberdade de consciência."},{"verse":6,"text":"Cremos que todo homem deve ser respeitado em sua posição, governantes e magistrados como tais, sendo nomeados para proteção dos inocentes e punição dos culpados; e que todos os homens devem respeito e deferência às leis visto que, sem elas, a paz e a harmonia seriam suplantadas pela anarquia e pelo terror; as leis humanas foram instituídas com o propósito expresso de regular nossos interesses como indivíduos e nações, entre um homem e outro; e as leis divinas foram dadas pelo céu, para prescrever regras sobre assuntos espirituais, para fé e adoração, devendo o homem dar contas de ambas a seu Criador."},{"verse":7,"text":"Cremos que governantes, estados e governos têm o direito e a responsabilidade de promulgar leis para a proteção de todos os cidadãos no livre exercício de suas crenças religiosas; mas não cremos terem eles o direito, por justiça, de privar os cidadãos desse privilégio nem de rejeitá-los por suas opiniões, enquanto mostrarem consideração e reverência pelas leis e suas opiniões religiosas não incentivarem motins nem conspirações."},{"verse":8,"text":"Cremos que a perpetração de um crime deve ser punida de acordo com a natureza do delito; que o homicídio, a traição, o roubo, o furto e a violação da paz geral, em todos os aspectos, devem ser punidos de acordo com sua criminalidade e sua má influência entre os homens, pelas leis do governo sob o qual o delito tiver sido cometido; e para a paz e tranquilidade públicas, todos os homens devem usar sua habilidade para entregar os transgressores das boas leis ao castigo."},{"verse":9,"text":"Não cremos ser justo misturar influência religiosa com governo civil, o que faz com que uma sociedade religiosa seja favorecida e outra, restrita em seus privilégios espirituais; e os direitos individuais de seus membros, como cidadãos, sejam negados."},{"verse":10,"text":"Cremos que todas as sociedades religiosas têm o direito de lidar com seus membros, em caso de conduta inadequada, de acordo com as regras e os regulamentos dessas sociedades; desde que tal ação se limite à participação e posição da pessoa na sociedade a que pertença; mas não cremos ter qualquer sociedade religiosa autoridade para julgar os homens quanto a seu direito a propriedade ou à vida; para confiscar-lhes os bens deste mundo, ou para pô-los em perigo de vida ou de danos físicos ou para infligir-lhes qualquer castigo físico. Podem, apenas, excomungá-los de sua sociedade e negar-lhes participação."},{"verse":11,"text":"Cremos que todos os homens devem apelar para as leis civis a fim de conseguir reparação de todas as injúrias e agravos, quando se lhes infligirem maus-tratos pessoais ou infringirem-se seus direitos à propriedade ou reputação, onde existirem leis para protegê-los; mas cremos que todos os homens são justificados por se defenderem e defenderem seus amigos e seus bens e o governo de ataques ilegais e de violações de direitos cometidos por qualquer pessoa, quando não se puder apelar de imediato às leis nem se puder obter auxílio."},{"verse":12,"text":"Cremos ser justo pregar o evangelho às nações da Terra e exortar os justos a salvarem-se da corrupção do mundo; mas não cremos ser correto interferir na vida dos escravos nem pregar-lhes o evangelho nem batizá-los contra a vontade e o desejo de seus senhores, nem envolver-se com eles ou influenciá-los de qualquer forma, de modo a torná-los descontentes com sua situação nesta vida, pondo assim em risco vidas humanas; tal interferência cremos ser ilegal e injusta e perigosa para a paz de todo governo que permita a escravidão de seres humanos."}]},{"chapter":135,"verses":[{"verse":1,"text":"Para selar o testemunho deste livro e do Livro de Mórmon, anunciamos a morte de Joseph Smith, o Profeta, e de Hyrum Smith, o Patriarca. Foram eles assassinados na cadeia de Carthage, no dia 27 de junho de 1844, perto das cinco horas da tarde, por uma turba composta de 150 a 200 pessoas armadas e pintadas de negro. Hyrum foi atingido primeiro e caiu calmamente, exclamando: Sou um homem morto! Joseph Smith saltou da janela e foi morto a tiros na tentativa, exclamando: Ó Senhor meu Deus! Depois de mortos, ambos foram brutalmente baleados, recebendo cada um quatro balas."},{"verse":2,"text":"John Taylor e Willard Richards, dois dos Doze, eram as únicas pessoas que estavam no local na ocasião; o primeiro foi ferido de maneira selvagem, com quatro balas, mas recuperou-se; o último, pela providência de Deus escapou sem mesmo um furo em sua roupa."},{"verse":3,"text":"Joseph Smith, o Profeta e Vidente do Senhor, com exceção apenas de Jesus, fez mais pela salvação dos homens neste mundo do que qualquer outro homem que jamais viveu nele. No curto espaço de vinte anos trouxe à luz o Livro de Mórmon, que traduziu pelo dom e poder de Deus, e foi o instrumento de sua publicação em dois continentes; enviou a plenitude do evangelho eterno, que o livro continha, aos quatro cantos da Terra; trouxe à luz as revelações e mandamentos que compõem este livro de Doutrina e Convênios e muitos outros sábios documentos e instruções para o benefício dos filhos dos homens; reuniu muitos milhares de santos dos últimos dias, fundou uma grande cidade e deixou fama e nome que não podem ser destruídos. Viveu grandiosamente e morreu grandiosamente aos olhos de Deus e de seu povo; e como a maior parte dos ungidos do Senhor na antiguidade, selou sua missão e suas obras com o próprio sangue; o mesmo fez seu irmão Hyrum. Em vida não foram divididos e na morte não foram separados!"},{"verse":4,"text":"Quando Joseph foi a Carthage para entregar-se às pretensas exigências da lei, dois ou três dias antes de seu assassinato, ele disse: “Vou como um cordeiro para o matadouro; mas estou calmo como uma manhã de verão; tenho a consciência limpa em relação a Deus e em relação a todos os homens. Morrerei inocente e ainda se dirá de mim: foi assassinado a sangue frio.” — Naquela mesma manhã, depois de Hyrum preparar-se para partir — dir-se-á, para a chacina? sim, pois assim aconteceu — ele leu o seguinte parágrafo, quase no fim do capítulo doze de Éter, no Livro de Mórmon, e dobrou a página para marcá-la:"},{"verse":5,"text":"E aconteceu que eu orei ao Senhor a fim de que ele desse graça aos gentios, para que tenham caridade. E aconteceu que o Senhor me disse: Se eles não têm caridade, a ti isso não importa; tu tens sido fiel; portanto, as tuas vestes se tornarão limpas. E porque viste a tua fraqueza, serás fortalecido até que te sentes no lugar que preparei nas mansões de meu Pai. E agora (…) despeço-me dos gentios, sim, e também de meus irmãos a quem amo, até que nos encontremos perante o tribunal de Cristo, onde todos os homens saberão que minhas vestes não estão manchadas com o vosso sangue. Os testadores agora estão mortos e seu testamento está em vigor."},{"verse":6,"text":"Hyrum Smith fez quarenta e quatro anos em fevereiro de 1844 e Joseph Smith fez trinta e oito em dezembro de 1843; e de agora em diante seus nomes serão incluídos entre os mártires da religião; e os leitores de todas as nações lembrar-se-ão de que o surgimento do Livro de Mórmon e deste livro de Doutrina e Convênios da igreja para a salvação de um mundo arruinado custou o melhor sangue do século dezenove; e de que, se o fogo consegue queimar uma árvore verdejante para a glória de Deus, quão facilmente não queimará as árvores secas para purificar a vinha de corrupção! Eles viveram pela glória; eles morreram pela glória; e a glória é sua eterna recompensa. De geração em geração, seus nomes passarão à posteridade como joias para os santificados."},{"verse":7,"text":"Eram inocentes de qualquer crime, como tantas vezes antes se provara, e só foram postos na prisão pela conspiração de traidores e de homens iníquos; e seu sangue inocente, no chão da cadeia de Carthage, é um grande selo afixado ao “mormonismo,” que não poderá ser rejeitado por qualquer tribunal da Terra; e seu sangue inocente sobre o brasão do Estado de Illinois, juntamente com a violação da palavra do Estado, conforme empenhada pelo governador, é uma testemunha da veracidade do evangelho eterno, que o mundo inteiro não pode refutar; e seu sangue inocente sobre o estandarte da liberdade e sobre a carta magna dos Estados Unidos é um embaixador da religião de Jesus Cristo, que tocará o coração dos homens honestos de todas as nações; e seu sangue inocente, juntamente com o sangue de todos os mártires sob o altar que João viu, clamará ao Senhor dos Exércitos até que ele vingue esse sangue na Terra. Amém."}]},{"chapter":136,"verses":[{"verse":1,"text":"A Palavra e a Vontade do Senhor quanto ao Acampamento de Israel em suas viagens para o oeste:"},{"verse":2,"text":"Que todo o povo de A Igreja de Jesus Cristo dos Santos dos Últimos Dias e aqueles que com eles viajam se organizem em companhias, fazendo o convênio e a promessa de guardar todos os mandamentos e estatutos do Senhor nosso Deus."},{"verse":3,"text":"Que se organizem as companhias com capitães de centenas, capitães de cinquenta e capitães de dez, com um presidente e seus dois conselheiros à frente, sob a direção dos Doze Apóstolos."},{"verse":4,"text":"E este será nosso convênio: Caminharemos de acordo com todas as ordenanças do Senhor."},{"verse":5,"text":"Que cada companhia providencie todas as parelhas, carroções, provisões, roupas e outras coisas que puderem, necessárias para a viagem."},{"verse":6,"text":"Quando as companhias estiverem organizadas, que dediquem toda a sua força aos preparativos, para os que deverão ficar para trás."},{"verse":7,"text":"Que cada companhia, com seus capitães e presidentes, decida quantos irão na próxima primavera; depois escolha um número suficiente de homens de boa constituição física e peritos, a fim de levar parelhas, sementes e implementos agrícolas e que irão, como pioneiros, preparar o plantio da primavera."},{"verse":8,"text":"Que cada companhia assuma a responsabilidade, proporcional ao valor de seus bens, de levar os pobres, as viúvas, os órfãos e as famílias daqueles que entraram para o exército, a fim de que os clamores das viúvas e dos órfãos não cheguem ao ouvidos do Senhor contra este povo."},{"verse":9,"text":"Que cada companhia prepare casas e campos para o cultivo de grãos, em benefício dos que, por agora, ficarem para trás; e esta é a vontade do Senhor concernente a seu povo."},{"verse":10,"text":"Que cada homem use toda a sua influência e seus bens para levar este povo ao lugar onde o Senhor estabelecerá uma estaca de Sião."},{"verse":11,"text":"E se fizerdes isto com o coração puro, com toda fidelidade, sereis abençoados; sereis abençoados em vossos rebanhos e em vossas manadas e em vossos campos e em vossas casas e em vossas famílias."},{"verse":12,"text":"Que meus servos Ezra T. Benson e Erastus Snow organizem uma companhia."},{"verse":13,"text":"E que meus servos Orson Pratt e Wilford Woodruff organizem uma companhia."},{"verse":14,"text":"Também que meus servos Amasa Lyman e George A. Smith organizem uma companhia."},{"verse":15,"text":"E designem presidentes e capitães de centenas e de cinquenta e de dez."},{"verse":16,"text":"E que meus servos que foram designados ensinem isto, a minha vontade, aos santos, a fim de que estejam prontos para ir a uma terra de paz."},{"verse":17,"text":"Segui vosso caminho e fazei o que eu vos disse; e não temais vossos inimigos, porque eles não terão poder para deter minha obra."},{"verse":18,"text":"Sião será redimida em meu próprio e devido tempo."},{"verse":19,"text":"E se qualquer homem procurar elevar-se e não buscar meu conselho, não terá poder algum; e sua insensatez será manifestada."},{"verse":20,"text":"Buscai; e cumpri todas as promessas que fizestes uns aos outros; e não cobiceis o que pertence a vosso irmão."},{"verse":21,"text":"Guardai-vos do pecado de tomar o nome do Senhor em vão, pois eu sou o Senhor vosso Deus, sim, o Deus de vossos pais, o Deus de Abraão e de Isaque e de Jacó."},{"verse":22,"text":"Eu sou aquele que tirou os filhos de Israel da terra do Egito; e meu braço estende-se nos últimos dias, para salvar meu povo Israel."},{"verse":23,"text":"Cessai de contender uns com os outros; cessai de falar mal uns dos outros."},{"verse":24,"text":"Cessai a embriaguez; e que vossas palavras contribuam para vossa edificação mútua."},{"verse":25,"text":"Se tomares algo emprestado de teu próximo, devolverás o que tomaste emprestado; e se não puderes pagar, então dize imediatamente a teu próximo, para que ele não te condene."},{"verse":26,"text":"E se achares algo que teu próximo perdeu, farás uma busca cuidadosa até lho devolveres."},{"verse":27,"text":"Preservarás diligentemente o que possuis, para que sejas um mordomo prudente; pois é dádiva gratuita do Senhor teu Deus e tu és seu mordomo."},{"verse":28,"text":"Se estiveres alegre, louva ao Senhor com cânticos, com música, com dança, e com orações de louvor e ação de graças."},{"verse":29,"text":"Se estiveres angustiado, invoca o Senhor teu Deus com súplicas a fim de que tua alma se regozije."},{"verse":30,"text":"Não temas os teus inimigos, porque eles estão nas minhas mãos e executarei a minha vontade concernente a eles."},{"verse":31,"text":"Meu povo deve ser provado em todas as coisas a fim de preparar-se para receber a glória que tenho para ele, sim, a glória de Sião; e quem não suporta correção não é digno do meu reino."},{"verse":32,"text":"Que o que for ignorante adquira sabedoria, humilhando-se e invocando o Senhor seu Deus a fim de que seus olhos sejam abertos para que ele veja e seus ouvidos, abertos para que ele ouça;"},{"verse":33,"text":"Pois meu Espírito é enviado ao mundo a fim de iluminar os humildes e contritos e para a condenação dos ímpios."},{"verse":34,"text":"Vossos irmãos vos rejeitaram — vós e vosso testemunho, sim, a nação que vos expulsou;"},{"verse":35,"text":"E agora vem o dia da sua calamidade, sim, os dias de tristeza, como uma mulher em dores de parto; e a tristeza deles será grande, a menos que se arrependam depressa, sim, muito depressa."},{"verse":36,"text":"Porque eles mataram os profetas e os que lhes foram enviados; e derramaram sangue inocente, que da terra clama contra eles."},{"verse":37,"text":"Portanto, não vos maravilheis destas coisas, pois ainda não sois puros; ainda não podeis suportar minha glória; mas contemplá-la-eis se fordes fiéis na obediência a todas as palavras que vos dei, dos dias de Adão a Abraão, de Abraão a Moisés, de Moisés a Jesus e seus apóstolos, e de Jesus e seus apóstolos a Joseph Smith, ao qual chamei por meio de meus anjos, meus servos ministradores, e pela minha própria voz desde os céus, para realizar minha obra;"},{"verse":38,"text":"Cujo alicerce ele estabeleceu; e foi fiel e tomei-o para mim."},{"verse":39,"text":"Muitos se têm maravilhado por causa de sua morte; mas era preciso que ele selasse o seu testemunho com o próprio sangue, para que ele fosse honrado e os iníquos fossem condenados."},{"verse":40,"text":"Não vos livrei de vossos inimigos, deixando uma testemunha do meu nome?"},{"verse":41,"text":"Agora, pois, escutai, ó povo da minha igreja; e vós, élderes, ouvi juntos; vós recebestes meu reino."},{"verse":42,"text":"Sede diligentes na obediência a todos os meus mandamentos, para que não vos sobrevenham julgamentos e vossa fé não vos falhe e vossos inimigos triunfem. Assim, nada mais por agora. Amém e amém."}]},{"chapter":137,"verses":[{"verse":1,"text":"Abriram-se os céus sobre nós e contemplei o reino celestial de Deus e sua glória, no corpo ou fora do corpo, não posso dizer."},{"verse":2,"text":"Vi a incomparável beleza da porta por onde entrarão os herdeiros desse reino, que se assemelhava a chamas de fogo circulantes;"},{"verse":3,"text":"Também o refulgente trono de Deus, no qual estavam sentados o Pai e o Filho."},{"verse":4,"text":"Vi as belas ruas desse reino, que pareciam ser pavimentadas de ouro."},{"verse":5,"text":"Vi o Pai Adão e Abraão; e meu pai e minha mãe; meu irmão Alvin, que há muito dorme;"},{"verse":6,"text":"E maravilhei-me de que ele houvesse recebido uma herança naquele reino, visto que partira desta vida antes que o Senhor começasse a coligar Israel pela segunda vez; e não fora batizado para a remissão de pecados."},{"verse":7,"text":"Assim veio a mim a voz do Senhor, dizendo: Todos os que morreram sem conhecimento deste evangelho, que o teriam recebido caso tivessem tido permissão de aqui permanecer, serão herdeiros do reino celestial de Deus;"},{"verse":8,"text":"Também, todos os que morrerem daqui em diante sem conhecimento dele, que o teriam recebido de todo o coração, serão herdeiros desse reino;"},{"verse":9,"text":"Pois eu, o Senhor, julgarei todos os homens segundo suas obras, segundo o desejo de seu coração."},{"verse":10,"text":"E vi também que todas as crianças que morrem antes de chegar à idade da responsabilidade são salvas no reino celestial."}]},{"chapter":138,"verses":[{"verse":1,"text":"Em três de outubro do ano de mil novecentos e dezoito, sentei-me em meus aposentos meditando sobre as escrituras;"},{"verse":2,"text":"E refletindo sobre o grande sacrifício expiatório que foi feito pelo Filho de Deus, para a redenção do mundo;"},{"verse":3,"text":"E o grande e maravilhoso amor manifestado pelo Pai e o Filho na vinda do Redentor ao mundo;"},{"verse":4,"text":"Para que, por meio de sua expiação e pela obediência aos princípios do evangelho, a humanidade fosse salva."},{"verse":5,"text":"Enquanto estava assim ocupado, minha mente voltou-se para os escritos do apóstolo Pedro aos santos da antiguidade espalhados por Ponto, Galácia, Capadócia e outras partes da Ásia Menor, onde o evangelho fora pregado após a crucificação do Senhor."},{"verse":6,"text":"Abri a Bíblia e li os capítulos três e quatro da primeira epístola de Pedro e, ao ler, fiquei muito impressionado, mais do que havia ficado antes, com as seguintes passagens:"},{"verse":7,"text":"“Porque também Cristo padeceu uma vez pelos pecados, o justo pelos injustos, para levar-nos a Deus; mortificado, na verdade, na carne, mas vivificado pelo Espírito;"},{"verse":8,"text":"No qual também foi, e pregou aos espíritos em prisão;"},{"verse":9,"text":"Os quais noutro tempo foram rebeldes, quando a longanimidade de Deus esperava nos dias de Noé, enquanto se preparava a arca; na qual poucas (isto é, oito) almas se salvaram pela água.” (1 Pedro 3:18–20)"},{"verse":10,"text":"“Porque por isto foi pregado o evangelho também aos mortos, para que, na verdade, fossem julgados segundo os homens na carne, mas vivessem segundo Deus em espírito.” (1 Pedro 4:6)"},{"verse":11,"text":"Enquanto refletia sobre essas coisas que estão escritas, os olhos de meu entendimento foram abertos e o Espírito do Senhor repousou sobre mim e vi as hostes dos mortos, tanto pequenos como grandes."},{"verse":12,"text":"E achava-se reunido em um só lugar um grupo incontável dos espíritos dos justos, que foram fiéis no testemunho de Jesus enquanto viveram na mortalidade;"},{"verse":13,"text":"E que ofereceram sacrifício à semelhança do grande sacrifício do Filho de Deus e sofreram tribulações em nome de seu Redentor."},{"verse":14,"text":"Todos esses haviam partido da vida mortal com a firme esperança de uma gloriosa ressurreição por meio da graça de Deus, o Pai, e seu Filho Unigênito, Jesus Cristo."},{"verse":15,"text":"Vi que estavam cheios de júbilo e alegria e regozijavam-se juntos porque se aproximava o dia de sua libertação."},{"verse":16,"text":"Estavam reunidos, aguardando a chegada do Filho de Deus ao mundo dos espíritos para declarar sua redenção das ligaduras da morte."},{"verse":17,"text":"Seu pó adormecido seria restaurado em sua perfeita forma, cada osso a seu osso, e os tendões e a carne sobre eles, o espírito e o corpo reunidos para nunca mais se separarem, a fim de receberem a plenitude da alegria."},{"verse":18,"text":"Enquanto essa vasta multidão esperava e conversava, regozijando-se pela hora de sua libertação das cadeias da morte, o Filho de Deus apareceu, anunciando a liberdade aos cativos que tinham sido fiéis;"},{"verse":19,"text":"E ali pregou-lhes o evangelho eterno, a doutrina da ressurreição e a redenção do gênero humano da queda e dos pecados individuais, desde que houvesse arrependimento."},{"verse":20,"text":"Aos iníquos, porém, não se dirigiu; e entre os ímpios e os impenitentes, que se corromperam enquanto estavam na carne, a sua voz não se fez ouvir;"},{"verse":21,"text":"Nem os rebeldes, que rejeitaram os testemunhos e as advertências dos profetas antigos, contemplaram sua presença ou olharam sua face."},{"verse":22,"text":"Onde estavam esses, reinava a escuridão, mas entre os justos havia paz;"},{"verse":23,"text":"E os santos regozijaram-se em sua redenção e dobraram os joelhos e reconheceram o Filho de Deus como seu Redentor e Libertador da morte e das cadeias do inferno."},{"verse":24,"text":"Seus semblantes brilhavam e a resplandecência da presença do Senhor repousou sobre eles e cantaram louvores a seu santo nome."},{"verse":25,"text":"Maravilhei-me, porque sabia que o Salvador dedicara cerca de três anos ao seu ministério entre os judeus e os da casa de Israel, procurando ensinar-lhes o evangelho eterno e chamá-los ao arrependimento;"},{"verse":26,"text":"E contudo, não obstante suas grandes obras e milagres e a proclamação da verdade com grande poder e autoridade, foram poucos os que deram ouvidos à sua voz e que se regozijaram em sua presença e receberam salvação de suas mãos."},{"verse":27,"text":"Mas seu ministério entre os que estavam mortos foi limitado ao curto período compreendido entre a crucificação e sua ressurreição;"},{"verse":28,"text":"E refleti sobre as palavras de Pedro — quando disse que o Filho de Deus pregara aos espíritos em prisão que noutro tempo haviam sido rebeldes quando a longanimidade de Deus esperava nos dias de Noé — e de como fora possível Cristo pregar àqueles espíritos e realizar o trabalho necessário entre eles em tão pouco tempo."},{"verse":29,"text":"E enquanto refletia, meus olhos foram abertos e meu entendimento vivificado; e percebi que o Senhor não se dirigira em pessoa aos iníquos e aos rebeldes que haviam rejeitado a verdade, a fim de ensiná-los;"},{"verse":30,"text":"Mas eis que, dentre os justos, organizou suas forças e designou mensageiros, revestidos de poder e autoridade, e comissionou-os para levar a luz do evangelho aos que estavam nas trevas, sim, a todos os espíritos dos homens; e assim foi o evangelho pregado aos mortos."},{"verse":31,"text":"E os mensageiros escolhidos foram anunciar o dia aceitável do Senhor e proclamar liberdade aos cativos que estavam presos, sim, a todos os que se arrependessem de seus pecados e recebessem o evangelho."},{"verse":32,"text":"Desse modo foi pregado o evangelho àqueles que haviam morrido em seus pecados, sem conhecimento da verdade ou em transgressão, tendo rejeitado os profetas."},{"verse":33,"text":"A esses foi ensinada a fé em Deus, o arrependimento do pecado, o batismo vicário para remissão de pecados, o dom do Espírito Santo pela imposição de mãos."},{"verse":34,"text":"E todos os outros princípios do evangelho que precisavam saber a fim de qualificarem-se para ser julgados segundo os homens na carne, mas viver segundo Deus no espírito."},{"verse":35,"text":"E desse modo soube-se entre os mortos, tanto pequenos como grandes, os injustos como também os fiéis, que se efetuara redenção por meio do sacrifício do Filho de Deus na cruz."},{"verse":36,"text":"Foi dessa forma que se soube que nosso Redentor passara o tempo de sua visita ao mundo dos espíritos instruindo e preparando os espíritos fiéis dos profetas que haviam testificado dele na carne;"},{"verse":37,"text":"Para que levassem a mensagem de redenção a todos os mortos a quem ele não poderia pregar pessoalmente por causa de sua rebeldia e transgressões, a fim de que eles, pelo ministério de seus servos, também ouvissem suas palavras."},{"verse":38,"text":"Entre os grandes e poderosos que estavam reunidos nessa vasta congregação dos justos encontrava-se o Pai Adão, o Ancião de Dias e pai de todos,"},{"verse":39,"text":"E nossa gloriosa Mãe Eva, com muitas de suas filhas fiéis que viveram através das eras e adoraram o Deus verdadeiro e vivo."},{"verse":40,"text":"Abel, o primeiro mártir, estava lá; e seu irmão Sete, um dos poderosos, que era a imagem expressa de seu pai, Adão."},{"verse":41,"text":"Noé, que advertira acerca do dilúvio; Sem, o grande sumo sacerdote; Abraão, o pai dos fiéis; Isaque, Jacó e Moisés, o grande legislador de Israel;"},{"verse":42,"text":"E Isaías, que anunciou, por profecia, que o Redentor fora ungido para curar os contritos de coração, proclamar liberdade aos cativos e a abertura da prisão aos presos, também estavam lá."},{"verse":43,"text":"Além desses, Ezequiel, a quem foi mostrado em visão o grande vale de ossos secos, que seriam revestidos de carne a fim de ressurgirem na ressurreição dos mortos como almas viventes;"},{"verse":44,"text":"Daniel, que previu e predisse o estabelecimento do reino de Deus nos últimos dias, para nunca mais ser destruído nem entregue a outro povo;"},{"verse":45,"text":"Elias, que estava com Moisés no Monte da Transfiguração;"},{"verse":46,"text":"E Malaquias, o profeta que testificou a vinda de Elias, o profeta — de quem também Morôni falou ao profeta Joseph Smith, declarando que ele viria antes do grande e terrível dia do Senhor — também estavam lá."},{"verse":47,"text":"O profeta Elias deveria plantar no coração dos filhos as promessas feitas a seus pais,"},{"verse":48,"text":"Prenunciando a grande obra a ser realizada nos templos do Senhor na dispensação da plenitude dos tempos, para a redenção dos mortos e o selamento dos filhos aos pais, a fim de que a Terra toda não fosse ferida com uma maldição e totalmente destruída na sua vinda."},{"verse":49,"text":"Todos esses e muitos mais, até os profetas que habitaram entre os nefitas e testificaram a vinda do Filho de Deus, misturavam-se à grande assembleia e aguardavam sua libertação,"},{"verse":50,"text":"Porque os mortos consideravam o longo tempo em que seu espírito estava ausente do corpo como uma escravidão."},{"verse":51,"text":"Esses o Senhor ensinou e deu-lhes poder para levantarem-se, depois que ele ressuscitasse dos mortos, e entrarem no reino de seu Pai, para que lá fossem coroados com imortalidade e vida eterna,"},{"verse":52,"text":"E continuassem dali em diante o seu trabalho, como fora prometido pelo Senhor, e se tornassem participantes de todas as bênçãos reservadas para aqueles que o amam."},{"verse":53,"text":"O Profeta Joseph Smith e meu pai, Hyrum Smith, Brigham Young, John Taylor, Wilford Woodruff e outros espíritos preciosos que foram reservados para nascer na plenitude dos tempos a fim de participar no estabelecimento dos alicerces da grande obra dos últimos dias,"},{"verse":54,"text":"Incluindo a construção de templos e a realização, neles, de ordenanças para a redenção dos mortos, também estavam no mundo dos espíritos."},{"verse":55,"text":"Observei que também estavam entre os grandes e nobres que foram escolhidos no princípio para serem governantes na Igreja de Deus."},{"verse":56,"text":"Mesmo antes de nascerem, eles, com muitos outros, receberam suas primeiras lições no mundo dos espíritos e foram preparados para nascer no devido tempo do Senhor, a fim de trabalharem em sua vinha para a salvação da alma dos homens."},{"verse":57,"text":"Vi que os élderes fiéis desta dispensação, quando deixam a vida mortal, continuam seus labores na pregação do evangelho do arrependimento e da redenção, por meio do sacrifício do Filho Unigênito de Deus, entre aqueles que estão nas trevas e sob a servidão do pecado no grande mundo dos espíritos dos mortos."},{"verse":58,"text":"Os mortos que se arrependerem serão redimidos por meio da obediência às ordenanças da Casa de Deus,"},{"verse":59,"text":"E depois de terem cumprido a pena por suas transgressões e de serem purificados, receberão uma recompensa de acordo com suas obras, porque são herdeiros da salvação."},{"verse":60,"text":"Assim me foi revelada a visão da redenção dos mortos e presto testemunho; e sei que esse testemunho é verdadeiro, mediante a bênção de nosso Senhor e Salvador Jesus Cristo. Assim seja. Amém."}]}]},{"id":"official-declarations","title":"Declaração Oficial","englishTitle":"Official Declarations","volume":"Doctrine and Covenants","volumeId":"dc-testament","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"A Quem Interessar Possa:"},{"verse":2,"text":"Notícias da imprensa, provenientes de Salt Lake City foram amplamente divulgadas com propósitos políticos, declarando que a Comissão de Utah, em seu recente relatório ao Ministro do Interior, alega que ainda se realizam casamentos plurais e que quarenta ou mais casamentos dessa ordem foram celebrados em Utah desde junho passado ou durante o último ano; e também que em discursos públicos os líderes da Igreja ensinaram, incentivaram e estimularam a continuação da prática da poligamia —"},{"verse":3,"text":"Eu, portanto, como presidente de A Igreja de Jesus Cristo dos Santos dos Últimos Dias, pela presente e da maneira mais solene declaro serem falsas tais acusações. Nós não estamos ensinando poligamia, ou seja, casamento plural, nem permitindo que qualquer pessoa adote tal prática; e nego que quarenta ou qualquer outro número de casamentos plurais tenham sido celebrados durante esse período em nossos templos ou em qualquer outro lugar do Território."},{"verse":4,"text":"Relatou-se um caso em que as partes declaram ter sido o casamento realizado na Casa de Investiduras, em Salt Lake City na primavera de 1889, mas não consegui descobrir quem realizou a cerimônia; o que quer que tenha sido feito nesta questão, foi sem meu conhecimento. Em consequência dessa alegada ocorrência, a Casa de Investiduras foi, por ordem minha, demolida sem demora."},{"verse":5,"text":"Sendo que o Congresso promulgou leis proibindo o casamento plural, leis essas que foram pronunciadas constitucionais pelo tribunal de última instância, eu aqui declaro minha intenção de submeter-me a essas leis e de usar minha influência junto aos membros da Igreja que presido, para que eles façam o mesmo."},{"verse":6,"text":"Nada há em meus ensinamentos à Igreja nem nos de meus companheiros, durante o tempo especificado, que se possa razoavelmente interpretar como imposição da poligamia ou estímulo a ela; e quando algum élder da Igreja usou palavras que pareciam transmitir tal ensinamento, foi prontamente repreendido. E agora declaro publicamente que meu conselho aos santos dos últimos dias é que se abstenham de celebrar casamentos proibidos pelas leis do país."},{"verse":7,"text":"Wilford Woodruff"},{"verse":8,"text":"Presidente de A Igreja de Jesus Cristo dos Santos dos Últimos Dias."},{"verse":9,"text":"O Presidente Lorenzo Snow apresentou o seguinte:"},{"verse":10,"text":"“Reconhecendo Wilford Woodruff como Presidente de A Igreja de Jesus Cristo dos Santos dos Últimos Dias e atualmente o único homem na Terra a possuir as chaves das ordenanças de selamento, proponho que o consideremos plenamente autorizado, em virtude de sua posição, a expedir o Manifesto que foi lido em nossa presença, datado de 24 de setembro de 1890; e que, como Igreja reunida em Conferência Geral, aceitemos sua declaração concernente aos casamentos plurais como oficial e obrigatória.”"},{"verse":11,"text":"Salt Lake City, Utah, 6 de outubro de 1890."},{"verse":12,"text":"O Senhor jamais permitirá que eu ou qualquer outro homem que presida esta Igreja vos desvie do caminho verdadeiro. Isso não faz parte do plano. Não é a intenção de Deus. Se eu tentasse fazê-lo, o Senhor me afastaria de meu lugar, o mesmo acontecendo com qualquer outro que tentasse afastar os filhos dos homens dos oráculos de Deus e de seus deveres. (Sexagésima Primeira Conferência Geral Semestral da Igreja, segunda-feira, 6 de outubro de 1890, Salt Lake City, Utah. Publicado no Deseret Evening News, 11 de outubro de 1890, p. 2.)"},{"verse":13,"text":"Não importa quem viva ou quem morra, ou quem seja chamado para conduzir esta Igreja — eles têm que conduzi-la pela inspiração do Deus Todo-Poderoso. Se assim não fizerem, de forma alguma o conseguirão. (…)"},{"verse":14,"text":"Ultimamente tenho recebido algumas revelações, que considero muito importantes, e relatar-vos-ei o que o Senhor me disse. Consideremos o que chamamos de manifesto. (…)"},{"verse":15,"text":"O Senhor pediu-me que fizesse uma pergunta aos santos dos últimos dias, afirmando também que, se acatarem o que eu lhes disser e responderem, pelo Espírito e poder de Deus, à pergunta feita a eles, todos responderão da mesma forma e todos crerão da mesma forma em relação a este assunto."},{"verse":16,"text":"A pergunta é: Qual o melhor caminho a ser seguido pelos santos dos últimos dias — continuar tentando a prática do casamento plural, contrariando as leis do país e enfrentando a oposição de sessenta milhões de pessoas, sofrendo o confisco e perda de todos os templos e a interrupção de todas as ordenanças neles realizadas tanto para os vivos como para os mortos, além da prisão da Primeira Presidência e dos Doze, bem como de chefes de família da Igreja, e também o confisco de propriedades particulares dos membros (o que acarretaria a interrupção dessa prática); ou então, após fazer e sofrer o que fizemos e sofremos por termos aderido a esse princípio, abandonar tal prática e submeter-nos à lei, dessa forma permitindo que os Profetas, Apóstolos e pais de família permaneçam em seus lares, de modo a poderem instruir o povo e cuidar dos assuntos da Igreja, deixando também os templos nas mãos dos santos a fim de realizarem as ordenanças do Evangelho tanto para os vivos como para os mortos?"},{"verse":17,"text":"O Senhor mostrou-me, por meio de visão e revelação, exatamente o que ocorreria se não abandonássemos essa prática. Se não a tivéssemos abandonado, esses homens do Templo de Logan (…) não teriam qualquer utilidade; pois as ordenanças seriam interrompidas em toda a terra de Sião. Reinaria confusão em Israel e muitos homens seriam encarcerados. O problema afetaria toda a Igreja e seríamos obrigados a abandonar a prática. A pergunta agora é se essa prática deveria ser interrompida dessa forma ou da forma que o Senhor nos manifestou, deixando livres nossos Profetas e Apóstolos, bem como os pais de família, e deixando os templos nas mãos do povo para que os mortos sejam redimidos. Muitos já foram libertados da prisão do mundo espiritual por este povo; e o trabalho deve continuar ou parar? Esta é a pergunta que faço aos santos dos últimos dias. Tendes que julgar por vós mesmos. Desejo que respondais por vós mesmos. Não responderei a ela; mas digo-vos que essa seria exatamente a situação em que nós, como povo, nos encontraríamos, caso não tivéssemos agido como agimos."},{"verse":18,"text":"(…) Vi exatamente o que aconteceria se algo não tivesse sido feito. Venho sentindo esse espírito há muito tempo. Desejo, porém, dizer-vos isto: Eu teria deixado que os templos nos escapassem das mãos; teria ido eu próprio para a prisão e permitido que isso acontecesse a muitos de vós, não tivesse o Deus do céu me ordenado fazer o que fiz; e quando chegou a hora em que isso me foi ordenado, tudo ficou claro para mim. Dirigi-me ao Senhor e escrevi o que Ele ordenou que eu escrevesse. (…)"},{"verse":19,"text":"Deixo-vos isto para que pondereis a respeito. O Senhor está trabalhando conosco. (Conferência da Estaca Cache, Logan, Utah, domingo, 1º de novembro de 1891. Publicado no Deseret Weekly, 14 de novembro de 1891.)"},{"verse":20,"text":"Agora vos direi o que me foi manifestado e a participação do Filho de Deus nisto. (…) Tudo isso teria sucedido, assim como o Deus Todo-Poderoso vive, caso o manifesto não tivesse sido dado. Portanto, o Filho de Deus sentiu que isto deveria ser apresentado à Igreja e ao mundo para propósitos que Ele conhecia. O Senhor decretara o estabelecimento de Sião. Decretara a conclusão deste templo. Decretara que a salvação dos vivos e dos mortos fosse oferecida nestes vales entre as montanhas. E o Deus Todo-Poderoso decretou que o Diabo não frustraria isso. Se o compreenderdes, essa é a chave para isso. (De um discurso proferido na sexta sessão dedicatória do Templo de Salt Lake, abril de 1893. Transcrição dos Serviços Dedicatórios, Arquivos, Departamento Histórico da Igreja, Salt Lake City, Utah.)"}]},{"chapter":2,"verses":[{"verse":1,"text":"A Quem Interessar Possa:"},{"verse":2,"text":"Em 30 de setembro de 1978, durante a 148ª Conferência Geral Semestral de A Igreja de Jesus Cristo dos Santos dos Últimos Dias, o Presidente N. Eldon Tanner, Primeiro Conselheiro na Primeira Presidência da Igreja apresentou o seguinte:"},{"verse":3,"text":"No início de junho deste ano, a Primeira Presidência anunciou que o Presidente Spencer W. Kimball havia recebido uma revelação concedendo o sacerdócio e as bênçãos do templo a todos os membros dignos da Igreja do sexo masculino. O Presidente Kimball pediu que eu comunicasse à congregação que após isso lhe ter sido revelado, depois de muito meditar e orar nas salas sagradas do santo templo, ele apresentou a revelação a seus conselheiros, que a aceitaram e a aprovaram. Foi então apresentada ao Quórum dos Doze Apóstolos, que a aprovou por unanimidade; tendo, a seguir, sido apresentada a todas as outras Autoridades Gerais, que, também, a aprovaram unanimemente."},{"verse":4,"text":"O Presidente Kimball pediu-me que eu agora lesse esta carta:"},{"verse":5,"text":"de junho de 1978"},{"verse":6,"text":"A todos os oficiais do sacerdócio, gerais e locais, de A Igreja de Jesus Cristo dos Santos dos Últimos Dias em todo o mundo:"},{"verse":7,"text":"Caros Irmãos:"},{"verse":8,"text":"Ao testemunharmos a expansão da obra do Senhor na Terra, sentimo-nos gratos por terem os povos de muitas nações aceitado a mensagem do evangelho restaurado, filiando-se à Igreja em número cada vez maior. Isso despertou em nós o desejo de conceder a todos os membros dignos da Igreja todos os privilégios e bênçãos que o evangelho proporciona."},{"verse":9,"text":"Cônscios das promessas feitas pelos profetas e presidentes da Igreja que nos precederam, de que, a um dado momento no plano eterno de Deus, todos os nossos irmãos dignos receberiam o sacerdócio; e testemunhando a fidelidade daqueles que haviam sido impedidos de recebê-lo, imploramos longa e fervorosamente por esses nossos fiéis irmãos, passando muitas horas na Sala Superior do Templo, a suplicar a orientação divina do Senhor."},{"verse":10,"text":"Ele ouviu nossas orações e, por revelação, confirmou que era chegado o dia, há muito prometido, em que todo homem da Igreja fiel e digno poderia receber o santo sacerdócio, com o poder para exercer sua autoridade divina e usufruir, com seus entes queridos, todas as bênçãos que dele provêm, incluindo-se as bênçãos do templo. Portanto, todos os homens dignos da Igreja podem ser ordenados ao sacerdócio, independentemente de sua raça ou cor. Instruímos os líderes do sacerdócio a seguirem a diretriz de, cuidadosamente, entrevistar todos os candidatos à ordenação, seja ao Sacerdócio Aarônico ou ao de Melquisedeque, para verificar se atendem aos padrões de dignidade estabelecidos."},{"verse":11,"text":"Declaramos solenemente que o Senhor deu agora a conhecer a sua vontade para bênção de todos os seus filhos, em toda a Terra, que atenderem à voz de seus servos autorizados, e se prepararem para receber todas as bênçãos do evangelho."},{"verse":12,"text":"Spencer W. Kimball"},{"verse":13,"text":"N. Eldon Tanner"},{"verse":14,"text":"Marion G. Romney"},{"verse":15,"text":"A Primeira Presidência"},{"verse":16,"text":"Reconhecendo Spencer W. Kimball como profeta, vidente e revelador e presidente de A Igreja de Jesus Cristo dos Santos dos Últimos Dias, é proposto que nós, como assembleia constituinte, aceitemos esta revelação como a palavra e a vontade do Senhor. Todos a favor manifestem-se, levantando o braço direito. Quem se opuser, pelo mesmo sinal."},{"verse":17,"text":"O voto para apoiar a moção foi unânime e afirmativo."},{"verse":18,"text":"Salt Lake City, Utah, 30 de setembro de 1978."}]}]},{"id":"moses","title":"Moisés","englishTitle":"Moses","volume":"Pearl of Great Price","volumeId":"pgp","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"As palavras de Deus, que ele disse a Moisés, numa ocasião em que Moisés foi arrebatado a uma montanha sumamente alta;"},{"verse":2,"text":"E viu Deus face a face e falou com ele e a glória de Deus estava sobre Moisés; portanto, Moisés podia suportar sua presença."},{"verse":3,"text":"E Deus falou a Moisés, dizendo: Eis que eu sou o Senhor Deus Todo-Poderoso; e Infinito é meu nome, pois eu sou sem princípio de dias ou fim de anos; e não é isso infinito?"},{"verse":4,"text":"E eis que tu és meu filho; portanto, olha e mostrar-te-ei as obras de minhas mãos; mas não todas, porque minhas obras não têm fim nem tampouco minhas palavras, porque jamais cessam."},{"verse":5,"text":"Portanto, nenhum homem pode contemplar todas as obras minhas sem contemplar toda a minha glória; e nenhum homem pode contemplar toda a minha glória e depois permanecer na carne sobre a Terra."},{"verse":6,"text":"E tenho uma obra para ti, Moisés, meu filho; e tu és à semelhança de meu Unigênito; e meu Unigênito é e será o Salvador, pois ele é cheio de graça e verdade; mas não há outro Deus além de mim e todas as coisas estão presentes comigo, pois eu as conheço todas."},{"verse":7,"text":"E agora, eis que te mostro isto, Moisés, meu filho, pois estás no mundo; e agora eu o mostro a ti."},{"verse":8,"text":"E aconteceu que Moisés olhou e viu o mundo no qual ele fora criado; e Moisés viu o mundo e seus confins e todos os filhos dos homens que existem e que foram criados; e maravilhou-se e assombrou-se muito com isso."},{"verse":9,"text":"E a presença de Deus apartou-se de Moisés, de modo que sua glória não estava sobre ele; e Moisés foi deixado sozinho. E, ao ficar sozinho, caiu por terra."},{"verse":10,"text":"E aconteceu que se passaram muitas horas antes que Moisés recobrasse sua força natural como homem; e disse a si mesmo: Ora, por esta razão sei que o homem nada é, coisa que nunca havia imaginado."},{"verse":11,"text":"Mas agora meus próprios olhos contemplaram Deus; não, porém, meus olhos naturais, mas, sim, meus olhos espirituais, porque meus olhos naturais não poderiam ter contemplado; pois eu teria fenecido e morrido em sua presença; mas sua glória estava sobre mim e eu contemplei sua face, pois fui transfigurado diante dele."},{"verse":12,"text":"E aconteceu que, quando Moisés pronunciou essas palavras, eis que Satanás veio tentá-lo, dizendo: Moisés, filho de homem, adora-me."},{"verse":13,"text":"E aconteceu que Moisés olhou para Satanás e disse: Quem és tu? Pois eis que sou um filho de Deus, à semelhança de seu Unigênito; e onde está tua glória, para que te adore?"},{"verse":14,"text":"Pois eis que eu não poderia olhar para Deus, a não ser que sua glória estivesse sobre mim e eu fosse transfigurado perante ele. Mas posso olhar para ti como homem natural. Não é certamente assim?"},{"verse":15,"text":"Bendito seja o nome de meu Deus, pois seu espírito não se apartou completamente de mim; por outro lado, onde está tua glória, porque para mim é treva? E posso discernir entre ti e Deus; pois Deus disse-me: Adora a Deus, porque só a ele servirás."},{"verse":16,"text":"Vai-te, Satanás, não me enganes; pois Deus me disse: Tu és à semelhança de meu Unigênito."},{"verse":17,"text":"E ele também me deu mandamentos quando me chamou, da sarça ardente, dizendo: Invoca a Deus em nome de meu Unigênito e adora-me."},{"verse":18,"text":"E também Moisés disse: Não cessarei de invocar a Deus, porque tenho outras coisas a perguntar-lhe, pois sua glória tem estado sobre mim; portanto, posso discernir entre ele e ti. Retira-te daqui, Satanás."},{"verse":19,"text":"E então, quando Moisés pronunciou essas palavras, Satanás clamou com alta voz e bramou sobre a terra e ordenou, dizendo: Eu sou o Unigênito; adora-me."},{"verse":20,"text":"E aconteceu que Moisés começou a temer muito; e ao começar a temer, viu a amargura do inferno. Não obstante, clamando a Deus recebeu forças e ordenou, dizendo: Retira-te de mim, Satanás, porque somente a este único Deus adorarei, o qual é o Deus de glória."},{"verse":21,"text":"E então Satanás começou a tremer e a terra estremeceu; e Moisés recebeu forças e invocou a Deus, dizendo: Em nome do Unigênito, retira-te daqui, Satanás."},{"verse":22,"text":"E aconteceu que Satanás clamou com alta voz, com choro e pranto e ranger de dentes; e dali se retirou, sim, da presença de Moisés, de modo que ele não mais o viu."},{"verse":23,"text":"E Moisés prestou testemunho disso; mas por causa de iniquidade, isso não se encontra entre os filhos dos homens."},{"verse":24,"text":"E aconteceu que, quando Satanás se retirou da presença de Moisés, Moisés levantou os olhos ao céu, estando cheio do Espírito Santo, o qual presta testemunho do Pai e do Filho;"},{"verse":25,"text":"E invocando o nome de Deus, tornou a contemplar sua glória, porque ela estava sobre ele; e ouviu uma voz, dizendo: Bendito és tu, Moisés, porque eu, o Todo-Poderoso, te escolhi; e serás mais forte que muitas águas, pois elas obedecerão a teu comando como se fosses Deus."},{"verse":26,"text":"E eis que estou contigo, sim, até o fim de teus dias; pois libertarás meu povo do cativeiro, sim, Israel, meu escolhido."},{"verse":27,"text":"E aconteceu que, enquanto a voz ainda falava, Moisés olhou e viu a Terra; sim, toda ela; e não houve uma partícula dela que ele não visse, discernindo-a pelo Espírito de Deus."},{"verse":28,"text":"E também viu seus habitantes; e não houve uma só alma que não tivesse visto; e discerniu-as pelo Espírito de Deus; e grande era seu número, sim, eram incontáveis como as areias da praia."},{"verse":29,"text":"E ele viu muitas terras; e cada uma se chamava Terra e havia habitantes em sua superfície."},{"verse":30,"text":"E aconteceu que Moisés clamou a Deus, dizendo: Dize-me, rogo-te, por que essas coisas são assim e por meio de que as fizeste?"},{"verse":31,"text":"E eis que a glória de Deus estava sobre Moisés, de modo que Moisés permaneceu na presença de Deus e conversou com ele face a face. E o Senhor Deus disse a Moisés: Fiz essas coisas para meu próprio intento. Aqui há sabedoria e em mim permanece."},{"verse":32,"text":"E pela palavra de meu poder criei-as, a qual é meu Filho Unigênito que é cheio de graça e verdade."},{"verse":33,"text":"E mundos incontáveis criei; e também os criei para meu próprio intento; e criei-os por meio do Filho, o qual é meu Unigênito."},{"verse":34,"text":"E ao primeiro homem de todos os homens chamei Adão, isto é, muitos."},{"verse":35,"text":"Mas far-te-ei um relato apenas sobre esta Terra e seus habitantes. Pois eis que há muitos mundos que pela palavra de meu poder passaram. E há muitos que agora permanecem e são inumeráveis para o homem; mas todas as coisas são enumeráveis para mim, pois são minhas e eu conheço-as."},{"verse":36,"text":"E aconteceu que Moisés falou ao Senhor, dizendo: Sê misericordioso para com teu servo, ó Deus, e dize-me o que concerne a esta Terra e a seus habitantes e também aos céus; e então teu servo ficará satisfeito."},{"verse":37,"text":"E o Senhor Deus falou a Moisés, dizendo: Os céus, eles são muitos e são inumeráveis para o homem; mas são enumeráveis para mim, pois são meus."},{"verse":38,"text":"E assim como uma terra passará, e o seu céu, assim outra surgirá; e não há fim para as minhas obras, nem para as minhas palavras."},{"verse":39,"text":"Pois eis que esta é minha obra e minha glória: Levar a efeito a imortalidade e vida eterna do homem."},{"verse":40,"text":"E agora, Moisés, meu filho, falar-te-ei a respeito desta Terra na qual estás; e escreverás as coisas que te direi."},{"verse":41,"text":"E no dia em que os filhos dos homens menosprezarem minhas palavras e tirarem muitas delas do livro que escreverás, eis que levantarei outro semelhante a ti; e elas outra vez estarão ao alcance dos filhos dos homens — entre todos os que crerem."},{"verse":42,"text":"(Estas palavras foram ditas a Moisés no monte cujo nome não será conhecido entre os filhos dos homens. E agora elas são ditas a ti. Não as mostres senão aos que creem. Assim seja. Amém.)"}]},{"chapter":2,"verses":[{"verse":1,"text":"E aconteceu que o Senhor falou a Moisés, dizendo: Eis que eu te revelo o que concerne a este céu e a esta Terra; escreve as palavras que eu digo. Eu sou o Princípio e o Fim, o Deus Todo-Poderoso; por meio de meu Unigênito eu criei estas coisas; sim, no princípio criei o céu e a Terra sobre a qual estás."},{"verse":2,"text":"E a Terra era sem forma e vazia; e eu fiz com que as trevas cobrissem a face do abismo; e meu Espírito moveu-se sobre a face da água; pois eu sou Deus."},{"verse":3,"text":"E eu, Deus, disse: Haja luz; e houve luz."},{"verse":4,"text":"E eu, Deus, vi a luz; e vi que a luz era boa. E eu, Deus, separei a luz das trevas."},{"verse":5,"text":"E eu, Deus, chamei à luz Dia; e às trevas chamei Noite; e isso fiz pela palavra de meu poder e foi feito conforme eu disse; e foram a tarde e a manhã o primeiro dia."},{"verse":6,"text":"E eu, Deus, tornei a dizer: Haja um firmamento no meio da água; e assim foi feito, como eu disse; e eu disse: Separe ele as águas das águas; e assim foi feito;"},{"verse":7,"text":"E eu, Deus, fiz o firmamento e dividi as águas; sim, as grandes águas, sob o firmamento, das águas que estavam acima do firmamento; e assim foi como eu disse."},{"verse":8,"text":"E eu, Deus, chamei ao firmamento Céus; e foram a tarde e a manhã o segundo dia."},{"verse":9,"text":"E eu, Deus, disse: Ajuntem-se as águas que estão debaixo dos céus em um só lugar; e assim foi. E eu, Deus, disse: Que haja terra seca; e assim foi."},{"verse":10,"text":"E eu, Deus, chamei à parte seca Terra: e ao ajuntamento das águas chamei Mar; e eu, Deus, vi que todas as coisas que eu havia feito eram boas."},{"verse":11,"text":"E eu, Deus, disse: Que a terra produza relva, a erva que dê semente, a árvore frutífera que dê fruto segundo sua espécie e a árvore que dê fruto, cuja semente esteja nele, sobre a terra; e foi como eu disse."},{"verse":12,"text":"E a terra produziu relva, toda erva que dá semente segundo sua espécie; e a árvore que dá fruto, cuja semente está nele, segundo sua espécie; e eu, Deus, vi que todas as coisas que eu havia feito eram boas;"},{"verse":13,"text":"E foram a tarde e a manhã o terceiro dia."},{"verse":14,"text":"E eu, Deus, disse: Haja luzes no firmamento do céu para dividir o dia da noite; e que elas sejam por sinais e por estações e por dias e por anos;"},{"verse":15,"text":"E que sejam por luzes no firmamento do céu para iluminar a Terra; e assim foi."},{"verse":16,"text":"E eu, Deus, fiz duas grandes luzes; a luz maior para governar o dia e a luz menor para governar a noite; e a luz maior foi o sol e a luz menor foi a lua; e também as estrelas foram feitas de acordo com minha palavra."},{"verse":17,"text":"E eu, Deus, coloquei-as no firmamento do céu para iluminar a Terra,"},{"verse":18,"text":"E o sol para governar o dia e a lua para governar a noite e para separar a luz das trevas; e eu, Deus, vi que todas as coisas que eu havia feito eram boas;"},{"verse":19,"text":"E foram a tarde e a manhã o quarto dia."},{"verse":20,"text":"E eu, Deus, disse: Produzam as águas, abundantemente, criaturas viventes que se movam e aves que possam voar sobre a terra no livre firmamento do céu."},{"verse":21,"text":"E eu, Deus, criei grandes baleias e toda criatura vivente que se move, que as águas produziram em abundância, segundo sua espécie, e toda ave alada segundo sua espécie; e eu, Deus, vi que todas as coisas que eu havia criado eram boas."},{"verse":22,"text":"E eu, Deus, abençoei-as, dizendo: Frutificai e multiplicai-vos e enchei as águas do mar; e multipliquem-se as aves na Terra;"},{"verse":23,"text":"E foram a tarde e a manhã o quinto dia."},{"verse":24,"text":"E eu, Deus, disse: Produza a terra criaturas viventes segundo sua espécie; gado e coisas rastejantes e bestas da Terra, segundo sua espécie; e assim foi."},{"verse":25,"text":"E eu, Deus, fiz as bestas da Terra, segundo sua espécie, e gado segundo sua espécie e tudo que rasteja sobre a Terra, segundo sua espécie; e eu, Deus, vi que todas essas coisas eram boas."},{"verse":26,"text":"E eu, Deus, disse ao meu Unigênito, que estava comigo desde o princípio: Façamos o homem a nossa imagem, segundo nossa semelhança; e assim foi. E eu, Deus, disse: Que eles tenham domínio sobre os peixes do mar e sobre as aves do ar e sobre o gado e sobre toda a terra e sobre toda coisa rastejante que rasteja sobre a Terra."},{"verse":27,"text":"E eu, Deus, criei o homem à minha própria imagem, à imagem de meu Unigênito o criei; homem e mulher os criei."},{"verse":28,"text":"E eu, Deus, abençoei-os e disse-lhes: Frutificai e multiplicai-vos e enchei a Terra; e sujeitai-a e dominai sobre os peixes do mar e sobre as aves dos céus e sobre todo ser vivente que se move na Terra."},{"verse":29,"text":"E eu, Deus, disse ao homem: Eis que te dei toda erva que dá semente, que está sobre a face de toda a Terra; e toda árvore em que há fruto que dê semente; para ti servirá de alimento."},{"verse":30,"text":"E a toda besta da Terra e a toda ave do ar e a todas as coisas que rastejam sobre a Terra, às quais concedo vida, toda erva limpa será dada para alimento; e assim foi, sim, como eu disse."},{"verse":31,"text":"E eu, Deus, vi todas as coisas que eu havia feito; e eis que todas as coisas que eu havia feito eram muito boas; e foram a tarde e a manhã o sexto dia."}]},{"chapter":3,"verses":[{"verse":1,"text":"Assim, o céu e a Terra foram terminados e todas as suas hostes."},{"verse":2,"text":"E no sétimo dia eu, Deus, terminei minha obra e todas as coisas que tinha feito; e descansei no sétimo dia de toda a minha obra; e todas as coisas que eu fizera estavam terminadas; e eu, Deus, vi que elas eram boas;"},{"verse":3,"text":"E eu, Deus, abençoei o sétimo dia e santifiquei-o; porque nele eu descansara de toda a minha obra que eu, Deus, criara e fizera."},{"verse":4,"text":"E agora, eis que eu te digo que estas são as gerações do céu e da Terra, quando foram criados, no dia em que eu, o Senhor Deus, fiz o céu e a Terra;"},{"verse":5,"text":"E toda planta do campo, antes de estar na Terra, e toda erva do campo, antes de brotar. Pois eu, o Senhor Deus, criei todas as coisas das quais falei espiritualmente, antes que elas existissem fisicamente na face da Terra. Pois eu, o Senhor Deus, não fizera chover sobre a face da Terra. E eu, o Senhor Deus, havia criado todos os filhos dos homens; e ainda não havia homem para lavrar a terra, pois no céu os criei; e ainda não havia carne sobre a Terra nem na água nem no ar;"},{"verse":6,"text":"Mas eu, o Senhor Deus, falei e levantou-se um vapor da Terra e regou toda a superfície do solo."},{"verse":7,"text":"E eu, o Senhor Deus, formei o homem do pó da Terra e soprei em suas narinas o fôlego da vida; e o homem tornou-se uma alma vivente, a primeira carne na Terra, também o primeiro homem; não obstante, todas as coisas foram criadas antes; mas espiritualmente foram elas criadas e feitas de acordo com minha palavra."},{"verse":8,"text":"E eu, o Senhor Deus, plantei um jardim ao oriente, no Éden, e ali pus o homem que eu havia formado."},{"verse":9,"text":"E da terra fiz eu, o Senhor Deus, brotar fisicamente toda árvore agradável à vista do homem; e o homem pôde contemplá-la. E ela tornou-se também uma alma vivente. Pois era espiritual no dia em que eu a criei, pois permanece na esfera em que eu, Deus, a criei, sim, como todas as coisas que preparei para uso do homem; o homem viu que era boa como alimento. E eu, o Senhor Deus, também plantei a árvore da vida no meio do jardim; e também a árvore do conhecimento do bem e do mal."},{"verse":10,"text":"E eu, o Senhor Deus, fiz um rio sair do Éden para regar o jardim; e dali ele se dividia e tornava-se em quatro braços."},{"verse":11,"text":"E eu, o Senhor Deus, dei ao primeiro o nome de Pisom; e ele rodeia toda a terra de Havilá, onde eu, o Senhor Deus, criei muito ouro;"},{"verse":12,"text":"E o ouro daquela terra era bom e havia bdélio e pedra ônix."},{"verse":13,"text":"E o nome do segundo rio era Giom; é o que rodeia toda a terra da Etiópia."},{"verse":14,"text":"E o nome do terceiro rio era Hidequel, o que vai para o lado oriental da Assíria. E o quarto rio era o Eufrates."},{"verse":15,"text":"E eu, o Senhor Deus, tomei o homem e coloquei-o no Jardim do Éden para lavrá-lo e guardá-lo."},{"verse":16,"text":"E eu, o Senhor Deus, ordenei ao homem, dizendo: De toda árvore do jardim podes comer livremente,"},{"verse":17,"text":"Mas da árvore do conhecimento do bem e do mal não comerás; não obstante, podes escolher segundo a tua vontade, porque te é dado; mas lembra-te de que eu o proíbo, porque no dia em que dela comeres, certamente morrerás."},{"verse":18,"text":"E eu, o Senhor Deus, disse a meu Unigênito que não era bom que o homem estivesse só; por conseguinte, farei uma adjutora própria para ele."},{"verse":19,"text":"E da terra, eu, o Senhor Deus, formei toda besta do campo e toda ave do ar; e ordenei-lhes que fossem até Adão para ver como ele as chamaria; e elas também eram almas viventes; porque eu, o Senhor Deus, soprei nelas o fôlego da vida e ordenei que o nome que Adão desse a cada criatura vivente, tal seria o seu nome."},{"verse":20,"text":"E Adão deu nome a todo o gado e a todas as aves do ar e a todos os animais do campo; mas, quanto a Adão, não havia uma adjutora própria para ele."},{"verse":21,"text":"E eu, o Senhor Deus, fiz com que caísse um sono profundo sobre Adão; e ele adormeceu e eu tomei uma de suas costelas e fechei a carne em seu lugar;"},{"verse":22,"text":"E da costela que eu, o Senhor Deus, tomara do homem, fiz eu uma mulher e levei-a ao homem."},{"verse":23,"text":"E Adão disse: Esta, agora eu sei, é osso de meus ossos e carne de minha carne; ela será chamada Mulher, porque foi tirada do homem."},{"verse":24,"text":"Portanto, o homem deixará seu pai e sua mãe e apegar-se-á a sua mulher; e eles serão uma carne."},{"verse":25,"text":"E estavam ambos nus, o homem e sua mulher, e não se envergonhavam."}]},{"chapter":4,"verses":[{"verse":1,"text":"E eu, o Senhor Deus, falei a Moisés, dizendo: Aquele Satanás a quem tu deste ordem em nome de meu Unigênito é o mesmo que existiu desde o princípio; e ele apresentou-se perante mim, dizendo: Eis-me aqui, envia-me; serei teu filho e redimirei a humanidade toda, de modo que nenhuma alma se perca; e sem dúvida eu o farei; portanto, dá-me a tua honra."},{"verse":2,"text":"Mas eis que meu Filho Amado, que foi meu Amado e meu Escolhido desde o princípio, disse-me: Pai, faça-se a tua vontade e seja tua a glória para sempre."},{"verse":3,"text":"Portanto, por ter Satanás se rebelado contra mim e procurado destruir o arbítrio do homem, o qual eu, o Senhor Deus, lhe dera; e também por querer que eu lhe desse meu próprio poder, fiz com que ele fosse expulso pelo poder do meu Unigênito."},{"verse":4,"text":"E ele tornou-se Satanás, sim, o próprio diabo, o pai de todas as mentiras, para enganar e cegar os homens e levá-los cativos segundo a sua vontade, sim, todos os que não derem ouvidos à minha voz."},{"verse":5,"text":"Ora, a serpente era mais astuta do que qualquer besta do campo que eu, o Senhor Deus, havia feito."},{"verse":6,"text":"E Satanás incitou o coração da serpente (pois ele havia atraído muitos após si) e procurou também enganar Eva, pois ele não conhecia a mente de Deus; por conseguinte, procurou destruir o mundo."},{"verse":7,"text":"E ele disse à mulher: Sim, Deus disse — Não comereis de todas as árvores do jardim? (E ele falou pela boca da serpente.)"},{"verse":8,"text":"E a mulher disse à serpente: Podemos comer do fruto das árvores do jardim;"},{"verse":9,"text":"Mas sobre o fruto da árvore que vês no meio do jardim, disse Deus: Não comereis dele nem o tocareis, para que não morrais."},{"verse":10,"text":"E a serpente disse à mulher: Certamente não morrereis;"},{"verse":11,"text":"Pois Deus sabe que no dia em que dele comerdes, vossos olhos serão abertos e sereis como deuses, conhecendo o bem e o mal."},{"verse":12,"text":"E quando a mulher viu que a árvore servia para alimento e que se tornara agradável aos olhos e uma árvore desejável para torná-la sábia, tomou de seu fruto e comeu; e deu também a seu marido e ele comeu com ela."},{"verse":13,"text":"E os olhos de ambos foram abertos e eles perceberam que estavam nus. E costuraram folhas de figueira e fizeram aventais para si."},{"verse":14,"text":"E ouviram a voz do Senhor Deus quando estavam andando no jardim, na viração do dia; e Adão e sua mulher foram esconder-se da presença do Senhor Deus entre as árvores do jardim."},{"verse":15,"text":"E eu, o Senhor Deus, chamei Adão e disse-lhe: Aonde vais?"},{"verse":16,"text":"E ele respondeu: Ouvi a tua voz no jardim, e tive medo, porque vi que estava nu; e escondi-me."},{"verse":17,"text":"E eu, o Senhor Deus, perguntei a Adão: Quem te disse que estavas nu? Comeste da árvore da qual te ordenei que não comesses, pois, se o fizesses, certamente morrerias?"},{"verse":18,"text":"E o homem disse: A mulher que me deste e ordenaste que permanecesse comigo deu-me do fruto da árvore e eu comi."},{"verse":19,"text":"E eu, o Senhor Deus, disse à mulher: O que é isso que fizeste? E a mulher disse: A serpente enganou-me e eu comi."},{"verse":20,"text":"E eu, o Senhor Deus, disse à serpente: Por teres feito isso, maldita serás sobre todo gado e toda besta do campo; sobre teu ventre andarás e pó comerás todos os dias de tua vida;"},{"verse":21,"text":"E porei inimizade entre ti e a mulher, entre a tua descendência e o seu descendente; e ele ferirá tua cabeça e tu lhe ferirás o calcanhar."},{"verse":22,"text":"À mulher eu, o Senhor Deus, disse: Multiplicarei grandemente tua dor e tua concepção. Com dor darás à luz filhos e teu desejo será para teu marido; e ele te dominará."},{"verse":23,"text":"E eu, o Senhor Deus, disse a Adão: Por haveres dado ouvidos à voz de tua mulher e teres comido do fruto da árvore de que eu ordenei, dizendo: Não comerás dele, maldita será a terra por tua causa; com dor comerás dela todos os dias de tua vida."},{"verse":24,"text":"Espinhos e cardos também produzirá para ti; e comerás a erva do campo."},{"verse":25,"text":"Pelo suor de teu rosto comerás o pão, até que retornes à terra — pois certamente morrerás — pois dela foste tirado; pois eras pó e ao pó retornarás."},{"verse":26,"text":"E Adão chamou o nome de sua mulher Eva, porque ela era a mãe de todos os viventes; pois assim eu, o Senhor Deus, chamei a primeira de todas as mulheres, que são muitas."},{"verse":27,"text":"Eu, o Senhor Deus, fiz túnicas de peles para Adão e também para sua mulher e vesti-os."},{"verse":28,"text":"E eu, o Senhor Deus, disse ao meu Unigênito: Eis que o homem se tornou como um de nós, conhecendo o bem e o mal; e agora, para que não estenda ele a mão e partilhe também da árvore da vida e coma e viva para sempre,"},{"verse":29,"text":"Eu, o Senhor Deus, expulsá-lo-ei, portanto, do Jardim do Éden, para lavrar a terra da qual foi tomado;"},{"verse":30,"text":"Pois assim como eu, o Senhor Deus, vivo, minhas palavras não podem retornar vazias, pois assim como saem de minha boca têm de ser cumpridas."},{"verse":31,"text":"Assim expulsei o homem e coloquei, ao oriente do Jardim do Éden, querubins e uma espada flamejante, que virava para todos os lados a fim de guardar o caminho da árvore da vida."},{"verse":32,"text":"(E essas são as palavras que eu disse a meu servo Moisés; e elas são verdadeiras, conforme a minha vontade; e disse-as a ti. Não as mostres a homem algum até que eu te ordene, a não ser aos que creem. Amém.)"}]},{"chapter":5,"verses":[{"verse":1,"text":"E aconteceu que, depois que eu, o Senhor Deus, os expulsei, Adão começou a lavrar a terra e a exercer domínio sobre as bestas do campo e a comer o pão com o suor de sua fronte, como eu, o Senhor, lhe ordenara: E Eva, sua mulher, também trabalhava com ele."},{"verse":2,"text":"E Adão conheceu a sua mulher e ela concebeu filhos e filhas; e eles começaram a multiplicar-se e a encher a Terra."},{"verse":3,"text":"E a partir de então, os filhos e filhas de Adão começaram a dividir-se de dois em dois na terra e a lavrar a terra e a cuidar dos rebanhos; e eles também geraram filhos e filhas."},{"verse":4,"text":"E Adão e Eva, sua mulher, invocaram o nome do Senhor e eles ouviram a voz do Senhor que vinha do caminho, em direção ao Jardim do Éden, falando-lhes; e eles não o viram, porque estavam excluídos de sua presença."},{"verse":5,"text":"E ele deu-lhes mandamentos de que adorassem ao Senhor seu Deus e oferecessem as primícias de seus rebanhos como oferta ao Senhor. E Adão foi obediente aos mandamentos do Senhor."},{"verse":6,"text":"E após muitos dias, um anjo do Senhor apareceu a Adão, dizendo: Por que ofereces sacrifícios ao Senhor? E Adão respondeu-lhe: Eu não sei, exceto que o Senhor me mandou."},{"verse":7,"text":"E então o anjo falou, dizendo: Isso é à semelhança do sacrifício do Unigênito do Pai que é cheio de graça e verdade."},{"verse":8,"text":"Portanto, farás tudo o que fizeres em nome do Filho; e arrepender-te-ás e invocarás a Deus em nome do Filho para todo o sempre."},{"verse":9,"text":"E naquele dia desceu sobre Adão o Espírito Santo, que presta testemunho do Pai e do Filho, dizendo: Eu sou o Unigênito do Pai desde o princípio, agora e para sempre, para que, assim como caíste, sejas redimido e toda a humanidade, sim, tantos quantos o desejarem."},{"verse":10,"text":"E naquele dia Adão bendisse a Deus e ficou pleno; e começou a profetizar concernente a todas as famílias da Terra, dizendo: Bendito seja o nome de Deus, pois, devido a minha transgressão, meus olhos estão abertos e nesta vida terei alegria; e novamente na carne verei a Deus."},{"verse":11,"text":"E Eva, sua mulher, ouviu todas essas coisas e alegrou-se, dizendo: Se não fosse por nossa transgressão, jamais teríamos tido semente e jamais teríamos conhecido o bem e o mal e a alegria de nossa redenção e a vida eterna que Deus concede a todos os obedientes."},{"verse":12,"text":"E Adão e Eva bendisseram o nome de Deus; e deram a conhecer todas as coisas a seus filhos e suas filhas."},{"verse":13,"text":"E Satanás apareceu no meio deles, dizendo: Eu também sou filho de Deus; e ordenou-lhes, dizendo: Não creiam; e eles não creram e amaram Satanás mais que a Deus. E os homens começaram, daquele tempo em diante, a ser carnais, sensuais e diabólicos."},{"verse":14,"text":"E o Senhor Deus chamou os homens pelo Espírito Santo em todos os lugares e ordenou-lhes que se arrependessem;"},{"verse":15,"text":"E todos os que cressem no Filho e se arrependessem de seus pecados seriam salvos; e todos os que não cressem e não se arrependessem seriam condenados; e as palavras saíram da boca de Deus em um firme decreto; portanto, têm de ser cumpridas."},{"verse":16,"text":"E Adão e Eva, sua mulher, não cessaram de clamar a Deus. E conheceu Adão a Eva, sua mulher, e ela concebeu e deu à luz Caim e disse: Obtive do Senhor um homem; portanto, ele não pode rejeitar suas palavras. Mas eis que Caim não lhe deu ouvidos e disse: Quem é o Senhor, para que eu deva conhecê-lo?"},{"verse":17,"text":"E ela tornou a conceber e deu à luz seu irmão Abel. E Abel deu ouvidos à voz do Senhor. E Abel foi pastor de ovelhas, mas Caim foi lavrador da terra."},{"verse":18,"text":"E Caim amou Satanás mais que a Deus. E Satanás ordenou-lhe, dizendo: Faze uma oferta ao Senhor."},{"verse":19,"text":"E com o correr do tempo, aconteceu que Caim levou, do fruto da terra, uma oferta ao Senhor."},{"verse":20,"text":"E Abel, ele também levou as primícias de seus rebanhos e de sua gordura. E atentou o Senhor para Abel e para sua oferta;"},{"verse":21,"text":"Mas para Caim e para a sua oferta ele não atentou. Ora, Satanás sabia disso e alegrou-se. E Caim ficou muito irado e decaiu-lhe o semblante."},{"verse":22,"text":"E o Senhor disse a Caim: Por que estás irado e por que te decaiu o semblante?"},{"verse":23,"text":"Se bem fizeres, serás aceito. E se bem não fizeres, o pecado jaz a tua porta e Satanás deseja possuir-te; e a menos que dês ouvidos a meus mandamentos, entregar-te-ei, e será feito a ti, segundo seu desejo. E tu reinarás sobre ele."},{"verse":24,"text":"Pois de agora em diante tu serás o pai de suas mentiras; serás chamado Perdição; pois também existias antes do mundo."},{"verse":25,"text":"E será dito em dias futuros que essas abominações vieram de Caim; pois ele rejeitou o conselho maior que vinha de Deus; e essa é uma maldição que porei sobre ti, a menos que te arrependas."},{"verse":26,"text":"E irou-se Caim e não mais deu ouvidos à voz do Senhor nem à de Abel, seu irmão, que andava em santidade perante o Senhor."},{"verse":27,"text":"E Adão e sua mulher lamentaram-se perante o Senhor por causa de Caim e seus irmãos."},{"verse":28,"text":"E aconteceu que Caim tomou para esposa uma das filhas de seus irmãos; e eles amaram Satanás mais que a Deus."},{"verse":29,"text":"E Satanás disse a Caim: Jura-me por tua garganta e, se o revelares, morrerás; e jurem teus irmãos pela cabeça deles e pelo Deus vivo, que não o revelarão; porque, se o revelarem, certamente morrerão; e isso para que teu pai não o saiba; e neste dia entregarei teu irmão Abel em tuas mãos."},{"verse":30,"text":"E Satanás jurou a Caim que agiria de acordo com suas ordens. E todas essas coisas foram feitas em segredo."},{"verse":31,"text":"E Caim disse: Na verdade eu sou Maã, o senhor deste grande segredo, para que eu possa matar e obter lucro. Portanto, Caim foi chamado Mestre Maã e vangloriou-se de sua iniquidade."},{"verse":32,"text":"E Caim saiu para o campo e Caim falou com Abel, seu irmão. E aconteceu que, enquanto estavam no campo, Caim levantou-se contra Abel, seu irmão, e matou-o."},{"verse":33,"text":"E Caim gloriou-se no que havia feito, dizendo: Estou livre; certamente os rebanhos de meu irmão cairão em minhas mãos."},{"verse":34,"text":"E o Senhor disse a Caim: Onde está Abel, teu irmão? E ele respondeu: Não sei. Sou eu guardador de meu irmão?"},{"verse":35,"text":"E o Senhor disse: O que fizeste? A voz do sangue de teu irmão clama a mim desde a terra."},{"verse":36,"text":"E agora serás amaldiçoado desde a Terra, que abriu a boca para receber de tua mão o sangue de teu irmão."},{"verse":37,"text":"Quando lavrares a terra, ela não te dará mais sua força. Fugitivo e vagabundo serás na Terra."},{"verse":38,"text":"E Caim disse ao Senhor: Satanás tentou-me por causa dos rebanhos de meu irmão. E também eu estava irado, porque aceitaste a oferta dele e a minha, não; meu castigo é maior do que me é possível suportar."},{"verse":39,"text":"Eis que me expulsaste este dia da face do Senhor e de tua face ficarei escondido; e serei fugitivo e vagabundo na Terra; e acontecerá que aquele que me achar me matará, por causa de minhas iniquidades; pois essas coisas não se escondem do Senhor."},{"verse":40,"text":"E eu, o Senhor, disse-lhe: Qualquer que te matar, sete vezes sofrerá vingança. E eu, o Senhor, pus um sinal em Caim, para que não o matasse qualquer que o achasse."},{"verse":41,"text":"E Caim foi banido da presença do Senhor e, com sua mulher e muitos de seus irmãos, habitou a terra de Node, a leste do Éden."},{"verse":42,"text":"E conheceu Caim a sua mulher e ela concebeu e deu à luz Enoque; e ele também gerou muitos filhos e filhas. E ele edificou uma cidade e deu à cidade o nome de seu filho, Enoque."},{"verse":43,"text":"E a Enoque nasceu Irade e outros filhos e filhas. E Irade gerou Meujael e outros filhos e filhas. E Meujael gerou Metusael e outros filhos e filhas. E Metusael gerou Lameque."},{"verse":44,"text":"E Lameque tomou para si duas mulheres; o nome de uma era Ada e o nome da outra, Zilá."},{"verse":45,"text":"E Ada gerou Jabal; ele foi o pai dos que habitam em tendas; e eram guardadores de gado; e o nome de seu irmão era Jubal, que foi o pai de todos os que tocam harpa e órgão."},{"verse":46,"text":"E Zilá, ela também gerou Tubal Caim, mestre de todo artífice que trabalha em bronze e ferro. E a irmã de Tubal Caim chamava-se Noema."},{"verse":47,"text":"E Lameque disse a suas mulheres, Ada e Zilá: Ouvi a minha voz, mulheres de Lameque, escutai as minhas palavras; pois eu matei um homem para o meu dano, e um jovem, para o meu mal."},{"verse":48,"text":"Se Caim for vingado sete vezes, em verdade Lameque o será setenta e sete vezes;"},{"verse":49,"text":"Pois Lameque havia feito um convênio com Satanás, segundo a maneira de Caim, tornando-se Mestre Maã, senhor daquele grande segredo que fora dado a Caim por Satanás; e Irade, filho de Enoque, havendo descoberto o segredo deles, começou a revelá-lo aos filhos de Adão;"},{"verse":50,"text":"Por isso Lameque, encolerizado, matou-o; não como Caim a seu irmão Abel, com o fim de obter lucro, mas matou-o por causa do juramento."},{"verse":51,"text":"Pois, desde os dias de Caim, havia uma combinação secreta e suas obras eram às escuras; e eles conheciam cada um a seu irmão."},{"verse":52,"text":"Portanto, o Senhor amaldiçoou Lameque e sua casa e todos os que haviam feito convênio com Satanás, porque não guardaram os mandamentos de Deus e isso desagradou a Deus; e não ministrou junto a eles e suas obras eram abominações e começaram a espalhar-se entre todos os filhos dos homens. E isso existia entre os filhos dos homens."},{"verse":53,"text":"E entre as filhas dos homens essas coisas não eram ditas, porque Lameque contara o segredo a suas mulheres e elas rebelaram-se contra ele e divulgaram essas coisas amplamente e não tiveram compaixão;"},{"verse":54,"text":"Portanto, Lameque foi desprezado e expulso; e ele não apareceu no meio dos filhos dos homens, para que não morresse."},{"verse":55,"text":"E assim as obras das trevas começaram a prevalecer entre todos os filhos dos homens."},{"verse":56,"text":"E Deus amaldiçoou a terra com uma pesada maldição e ficou irado com os iníquos, com todos os filhos dos homens que ele fizera;"},{"verse":57,"text":"Porque não davam ouvidos à sua voz nem acreditavam em seu Filho Unigênito, sim, naquele que ele declarou que viria no meridiano dos tempos, que foi preparado desde antes da fundação do mundo."},{"verse":58,"text":"E assim o Evangelho começou a ser pregado desde o princípio, sendo anunciado por santos anjos, enviados da presença de Deus, e por sua própria voz e pelo dom do Espírito Santo."},{"verse":59,"text":"E assim foram confirmadas todas as coisas a Adão por uma santa ordenança e pregado o Evangelho e enviado um decreto que deveria ficar no mundo até o seu fim; e assim foi. Amém."}]},{"chapter":6,"verses":[{"verse":1,"text":"E Adão deu ouvidos à voz de Deus e exortou seus filhos a se arrependerem."},{"verse":2,"text":"E Adão tornou a conhecer a sua mulher e ela deu à luz um filho; e ele deu-lhe o nome de Sete. E Adão glorificou o nome de Deus, pois ele disse: Deus concedeu-me outra semente em lugar de Abel, que Caim matou."},{"verse":3,"text":"E Deus revelou-se a Sete e ele não se rebelou, mas ofereceu um sacrifício aceitável, como seu irmão Abel. E a ele também nasceu um filho e ele deu-lhe o nome de Enos."},{"verse":4,"text":"E então começaram esses homens a invocar o nome do Senhor; e o Senhor abençoou-os."},{"verse":5,"text":"E escrevia-se um livro de recordações; e era escrito no idioma de Adão, pois a todos que invocavam a Deus era concedido escrever pelo espírito de inspiração;"},{"verse":6,"text":"E por eles seus filhos foram ensinados a ler e a escrever, tendo uma linguagem que era pura e impoluta."},{"verse":7,"text":"Ora, esse mesmo Sacerdócio, que existia no princípio, existirá também no fim do mundo."},{"verse":8,"text":"Ora, essa profecia Adão pronunciou movido pelo Espírito Santo; e registrava-se uma genealogia dos filhos de Deus. E esse era o livro das gerações de Adão e dizia: No dia em que Deus criou o homem, à semelhança de Deus o fez."},{"verse":9,"text":"À imagem de seu próprio corpo, homem e mulher, criou-os; e abençoou-os e chamou seu nome Adão, no dia em que foram criados e se tornaram almas viventes na terra, sobre o escabelo de Deus."},{"verse":10,"text":"E Adão viveu cento e trinta anos e gerou um filho a sua semelhança, segundo sua própria imagem; e chamou seu nome Sete."},{"verse":11,"text":"E foram os dias de Adão, depois que gerou Sete, oitocentos anos; e gerou muitos filhos e filhas."},{"verse":12,"text":"E todos os dias que Adão viveu foram novecentos e trinta anos; e ele morreu."},{"verse":13,"text":"Sete viveu cento e cinco anos e gerou Enos; e profetizou em todos os seus dias e ensinou seu filho Enos nos caminhos de Deus; portanto, Enos também profetizou."},{"verse":14,"text":"E viveu Sete, depois que gerou Enos, oitocentos e sete anos; e gerou muitos filhos e filhas."},{"verse":15,"text":"E os filhos dos homens eram numerosos em toda a face da terra. E naqueles dias Satanás exercia grande domínio entre os homens e enfurecia-se em seu coração; e daí em diante vieram as guerras e derramamento de sangue; e buscando o poder, a mão do homem levantava-se contra seu próprio irmão para provocar-lhe a morte, por causa de obras secretas."},{"verse":16,"text":"Todos os dias de Sete foram novecentos e doze anos; e ele morreu."},{"verse":17,"text":"E viveu Enos noventa anos e gerou Cainã. E Enos e o restante do povo de Deus saíram da terra chamada Sulon e habitaram uma terra prometida, à qual ele deu o nome de seu próprio filho, a quem chamara Cainã."},{"verse":18,"text":"E viveu Enos, depois de gerar Cainã, oitocentos e quinze anos; e gerou muitos filhos e filhas. E todos os dias de Enos foram novecentos e cinco anos; e ele morreu."},{"verse":19,"text":"E viveu Cainã setenta anos e gerou Maalalel; e Cainã viveu, após gerar Maalalel, oitocentos e quarenta anos; e gerou filhos e filhas. E todos os dias de Cainã foram novecentos e dez anos; e ele morreu."},{"verse":20,"text":"E Maalalel viveu sessenta e cinco anos e gerou Jarede; e viveu Maalalel, após gerar Jarede, oitocentos e trinta anos; e gerou filhos e filhas. E foram todos os dias de Maalalel oitocentos e noventa e cinco anos; e ele morreu."},{"verse":21,"text":"E viveu Jarede cento e sessenta e dois anos e gerou Enoque; e viveu Jarede, depois de gerar Enoque, oitocentos anos; e gerou filhos e filhas. E Jarede ensinou Enoque em todos os caminhos de Deus."},{"verse":22,"text":"E essa é a genealogia dos filhos de Adão, que era o filho de Deus, com quem o próprio Deus conversou."},{"verse":23,"text":"E eles eram pregadores de retidão e falavam e profetizavam e exortavam todos os homens, em todos os lugares, a se arrependerem; e fé foi ensinada aos filhos dos homens."},{"verse":24,"text":"E aconteceu que todos os dias de Jarede foram novecentos e sessenta e dois anos; e ele morreu."},{"verse":25,"text":"E viveu Enoque sessenta e cinco anos e gerou Matusalém."},{"verse":26,"text":"E aconteceu que Enoque viajou pela terra entre o povo; e enquanto viajava, o Espírito de Deus desceu do céu e pousou sobre ele."},{"verse":27,"text":"E ele ouviu uma voz do céu, dizendo: Enoque, meu filho, profetiza a este povo e dize-lhes: Arrependei-vos, pois assim diz o Senhor: Estou irado com este povo e minha ardente ira está acesa contra eles; porque o coração deles endureceu e seus ouvidos estão ensurdecidos e seus olhos não conseguem enxergar longe."},{"verse":28,"text":"E por essas muitas gerações, desde o dia em que os criei, têm eles se desviado e me negado e buscado seus próprios conselhos nas trevas; e em suas próprias abominações planejaram o homicídio e não guardaram os mandamentos que dei a seu pai, Adão."},{"verse":29,"text":"Portanto, eles juraram falsamente e, por seus próprios juramentos, trouxeram a morte sobre si; e um inferno preparei eu para eles, caso não se arrependam."},{"verse":30,"text":"E este é um decreto que promulguei no princípio do mundo, de minha própria boca, desde a sua fundação; e pela boca de meus servos, teus pais, decretei-o, tal como será propagado no mundo, até seus confins."},{"verse":31,"text":"E tendo ouvido essas palavras, Enoque prostrou-se ante o Senhor e falou perante o Senhor, dizendo: Por que é que encontrei graça aos teus olhos? Sou apenas um menino e todo o povo odeia-me, pois sou lento no falar; por que razão sou teu servo?"},{"verse":32,"text":"E o Senhor disse a Enoque: Vai e faze o que te ordenei e homem algum te ferirá. Abre tua boca e ela encher-se-á e dar-te-ei palavras, pois toda carne está em minhas mãos; e farei o que me parecer adequado."},{"verse":33,"text":"Dize a este povo: Decidi este dia servir ao Senhor Deus que vos fez."},{"verse":34,"text":"Eis que meu Espírito está sobre ti; portanto, todas as tuas palavras justificarei; e as montanhas fugirão diante de ti e os rios desviar-se-ão de seu curso; e tu permanecerás em mim e eu, em ti; portanto, anda comigo."},{"verse":35,"text":"E o Senhor falou a Enoque e disse-lhe: Unge teus olhos com barro e lava-os; e tu verás. E ele assim fez."},{"verse":36,"text":"E ele viu os espíritos que Deus havia criado; e também viu coisas que não eram visíveis ao olho natural; e daí em diante espalhou-se por toda a terra a expressão: Um vidente o Senhor levantou para seu povo."},{"verse":37,"text":"E aconteceu que Enoque saiu pela terra no meio do povo, pondo-se nas colinas e lugares elevados e gritou em alta voz, testificando contra suas obras; e todos os homens ofenderam-se por causa dele."},{"verse":38,"text":"E foram escutá-lo, nos lugares elevados, dizendo aos guardadores de tendas: Permanecei aqui e guardai as tendas enquanto vamos ver o vidente, pois ele profetiza e há uma coisa estranha na terra; um homem insano apareceu entre nós."},{"verse":39,"text":"E aconteceu que quando o ouviram, homem algum lhe deitou as mãos; porque o temor se apoderou de todos os que o ouviram; porque ele andava com Deus."},{"verse":40,"text":"E aproximou-se dele um homem cujo nome era Maíja e disse-lhe: Dize-nos claramente quem és e de onde vieste."},{"verse":41,"text":"E ele respondeu-lhes: Vim da terra de Cainã, a terra de meus pais, uma terra de retidão até o dia de hoje. E meu pai ensinou-me em todos os caminhos de Deus."},{"verse":42,"text":"E aconteceu, enquanto eu viajava, vindo da terra de Cainã pelo mar oriental, que tive uma visão; e eis que os céus eu vi e o Senhor falou comigo e deu-me mandamento; portanto, por esse motivo, para cumprir o mandamento, digo estas palavras."},{"verse":43,"text":"E Enoque continuou a falar, dizendo: O Senhor que falou comigo, o mesmo é o Deus do céu e ele é o meu Deus e vosso Deus; e vós sois meus irmãos. E por que aconselhais a vós mesmos e negais o Deus do céu?"},{"verse":44,"text":"Os céus ele fez; a Terra é o escabelo de seus pés e a fundação dela é sua. Eis que ele a estabeleceu e trouxe uma hoste de homens para a sua face."},{"verse":45,"text":"E a morte veio sobre nossos pais; não obstante nós os conhecemos e não podemos negar; e até o primeiro de todos conhecemos, sim, Adão."},{"verse":46,"text":"Pois um livro de lembranças escrevemos entre nós, de acordo com o modelo dado pelo dedo de Deus; e foi dado em nosso próprio idioma."},{"verse":47,"text":"E quando Enoque proferiu as palavras de Deus, o povo tremeu e não pôde permanecer em sua presença."},{"verse":48,"text":"E ele disse-lhes: Por que Adão caiu, existimos; e pela sua queda veio a morte; e fomos feitos participantes de miséria e desgraça."},{"verse":49,"text":"Eis que Satanás veio para o meio dos filhos dos homens e tentou-os para que o adorassem; e os homens tornaram-se carnais, sensuais e diabólicos e encontram-se afastados da presença de Deus."},{"verse":50,"text":"Mas Deus fez saber a nossos pais que todos os homens devem arrepender-se."},{"verse":51,"text":"E ele chamou nosso pai Adão com sua própria voz, dizendo: Eu sou Deus; eu fiz o mundo e os homens antes que existissem na carne."},{"verse":52,"text":"E ele também lhe disse: Se te voltares para mim, e deres ouvidos à minha voz, e creres, e te arrependeres de todas as tuas transgressões, e fores batizado, sim, na água, em nome de meu Filho Unigênito, que é cheio de graça e verdade, que é Jesus Cristo, o único nome que será dado debaixo do céu mediante o qual virá a salvação aos filhos dos homens, receberás o dom do Espírito Santo, pedindo todas as coisas em seu nome; e tudo o que pedires te será dado."},{"verse":53,"text":"E nosso pai Adão falou ao Senhor e disse: Por que é que os homens devem arrepender-se e ser batizados na água? E o Senhor disse a Adão: Eis que te perdoei tua transgressão no Jardim do Éden."},{"verse":54,"text":"Assim se começou a dizer entre o povo que o Filho de Deus expiara a culpa original, de modo que os pecados dos pais não podem recair sobre a cabeça dos filhos, pois estes são limpos desde a fundação do mundo."},{"verse":55,"text":"E o Senhor falou a Adão, dizendo: Visto que teus filhos são concebidos em pecado, quando eles começam a crescer, concebe-se o pecado em seu coração e eles provam o amargo para saber apreciar o bom."},{"verse":56,"text":"E a eles é dado distinguir o bem do mal, de modo que são seus próprios árbitros; e dei-te outra lei e mandamento."},{"verse":57,"text":"Portanto, ensina a teus filhos que todos os homens, em todos os lugares, devem arrepender-se, ou de maneira alguma herdarão o reino de Deus, porque nenhuma coisa impura pode ali habitar ou habitar em sua presença; pois, no idioma de Adão, Homem de Santidade é seu nome e o nome de seu Unigênito é Filho do Homem, sim, Jesus Cristo, um justo Juiz, que virá no meridiano dos tempos."},{"verse":58,"text":"Portanto, dou-te o mandamento de ensinares estas coisas liberalmente a teus filhos, dizendo:"},{"verse":59,"text":"Por causa da transgressão vem a queda, queda essa que traz a morte; e sendo que haveis nascido no mundo pela água e sangue e espírito que eu fiz e assim vos haveis transformado de pó em alma vivente, do mesmo modo tereis de nascer de novo no reino do céu, da água e do Espírito, sendo limpos por sangue, sim, o sangue de meu Unigênito; para que sejais santificados de todo pecado e desfruteis as palavras da vida eterna neste mundo e a vida eterna no mundo vindouro, sim, glória imortal;"},{"verse":60,"text":"Pois pela água guardais o mandamento, pelo Espírito sois justificados e pelo sangue sois santificados;"},{"verse":61,"text":"Portanto, é dado para habitar em vós: o testemunho do céu; o Consolador; as coisas pacíficas de glória imortal; a verdade de todas as coisas; aquilo que vivifica todas as coisas, que torna vivas todas as coisas; aquilo que conhece todas as coisas e tem todo o poder, de acordo com a sabedoria, a misericórdia, a verdade, a justiça e o juízo."},{"verse":62,"text":"E agora, eis que te digo: Este é o plano de salvação para todos os homens, por meio do sangue de meu Unigênito, que virá no meridiano dos tempos."},{"verse":63,"text":"E eis que todas as coisas têm sua semelhança e todas as coisas são criadas e feitas para prestar testemunho de mim, tanto as coisas materiais como as coisas que são espirituais; coisas que estão acima nos céus e coisas que estão na Terra e coisas que estão dentro da terra e coisas que estão embaixo da terra, tanto acima como abaixo: todas as coisas prestam testemunho de mim."},{"verse":64,"text":"E aconteceu, quando o Senhor falou com Adão, nosso pai, que Adão clamou ao Senhor e foi arrebatado pelo Espírito do Senhor e foi levado para a água e foi mergulhado na água e foi tirado da água."},{"verse":65,"text":"E assim ele foi batizado e o Espírito de Deus desceu sobre ele; e assim ele nasceu do Espírito e foi vivificado no homem interior."},{"verse":66,"text":"E ele ouviu uma voz do céu, dizendo: Foste batizado com fogo e com o Espírito Santo. Este é o testemunho do Pai e do Filho, de agora em diante e para sempre;"},{"verse":67,"text":"E tu és segundo a ordem daquele que foi sem princípio de dias ou fim de anos de toda a eternidade para toda a eternidade."},{"verse":68,"text":"Eis que tu és um em mim, um filho de Deus; e assim possam todos tornar-se meus filhos. Amém."}]},{"chapter":7,"verses":[{"verse":1,"text":"E aconteceu que Enoque continuou a falar, dizendo: Eis que nosso pai Adão ensinou estas coisas e muitos acreditaram e tornaram-se filhos de Deus; e muitos não acreditaram e pereceram em seus pecados e esperam com temor, em tormento, que a ardente indignação da ira de Deus se derrame sobre eles."},{"verse":2,"text":"E daquele tempo em diante Enoque começou a profetizar, dizendo ao povo: Quando eu estava viajando e me encontrava no lugar chamado Maúja e clamei ao Senhor, veio do céu uma voz que dizia: Volta-te e sobe ao Monte Simeon."},{"verse":3,"text":"E aconteceu que eu me voltei e subi ao monte; e enquanto estava no monte, vi os céus se abrirem e fui revestido de glória;"},{"verse":4,"text":"E vi o Senhor; e ele pôs-se diante de minha face e falou comigo, sim, como um homem fala com outro, face a face; e ele disse-me: Olha e mostrar-te-ei o mundo pelo espaço de muitas gerações."},{"verse":5,"text":"E aconteceu que olhei para o Vale de Sum e eis um grande povo que habitava em tendas, que era o povo de Sum."},{"verse":6,"text":"E o Senhor tornou a dizer-me: Olha; e olhei para o norte e vi o povo de Canaã, que habitava em tendas."},{"verse":7,"text":"E o Senhor disse-me: Profetiza; e eu profetizei, dizendo: Eis que o povo de Canaã, que é numeroso, irá batalhar contra o povo de Sum e matá-los-á até destruí-los por completo; e o povo de Canaã dividir-se-á na terra e a terra será estéril e infecunda; e nenhum outro povo viverá ali, a não ser o povo de Canaã;"},{"verse":8,"text":"Pois eis que o Senhor amaldiçoará a terra com muito calor e a sua esterilidade continuará para sempre; e uma cor negra desceu sobre todos os filhos de Canaã, de modo que foram desprezados entre todos os povos."},{"verse":9,"text":"E aconteceu que o Senhor me disse: Olha; e olhei e vi a terra de Saron e a terra de Enoque e a terra de Ômner e a terra de Heni e a terra de Sem e a terra de Haner e a terra de Hananias e os habitantes de todas elas;"},{"verse":10,"text":"E o Senhor disse-me: Dirige-te a esse povo e dize-lhes que se arrependam, para que eu não venha e os açoite com uma maldição e eles pereçam."},{"verse":11,"text":"E ele me deu um mandamento de que eu batizasse em nome do Pai e do Filho, que é cheio de graça e verdade, e do Espírito Santo, que presta testemunho do Pai e do Filho."},{"verse":12,"text":"E aconteceu que Enoque continuou a chamar todo o povo, com exceção do povo de Canaã, ao arrependimento;"},{"verse":13,"text":"E tão grande era a fé que possuía Enoque, que ele conduziu o povo de Deus; e seus inimigos saíram para batalhar contra ele e ele proferiu a palavra do Senhor e a terra tremeu e as montanhas fugiram, sim, de acordo com sua ordem; e os rios de água desviaram-se de seu curso e o rugido dos leões fez-se ouvir no deserto; e todas as nações temeram grandemente, tão poderosa era a palavra de Enoque e tão grande era o poder da linguagem que Deus lhe dera."},{"verse":14,"text":"Subiu também uma terra, das profundezas do mar, e tão grande era o temor dos inimigos do povo de Deus que eles fugiram e foram para longe, para a terra que subira das profundezas do mar."},{"verse":15,"text":"E os gigantes da terra também foram para longe; e caiu uma maldição sobre todo o povo que lutava contra Deus;"},{"verse":16,"text":"E daquele tempo em diante, houve guerras e derramamento de sangue entre eles; mas o Senhor veio habitar com seu povo e eles viveram em retidão."},{"verse":17,"text":"O temor do Senhor estava sobre todas as nações, tão grande era a glória do Senhor que se achava sobre seu povo. E o Senhor abençoou a terra e eles foram abençoados sobre as montanhas e sobre os lugares elevados; e floresceram."},{"verse":18,"text":"E o Senhor chamou seu povo Sião, porque eram unos de coração e vontade e viviam em retidão; e não havia pobres entre eles."},{"verse":19,"text":"E Enoque continuou pregando em retidão ao povo de Deus. E aconteceu em seus dias que ele edificou uma cidade que foi chamada Cidade da Santidade, sim, Sião."},{"verse":20,"text":"E aconteceu que Enoque falou com o Senhor; e ele disse ao Senhor: Certamente Sião habitará em segurança para sempre. O Senhor, porém, disse a Enoque: Sião eu abençoei, mas o restante do povo eu amaldiçoei."},{"verse":21,"text":"E aconteceu que o Senhor mostrou a Enoque todos os habitantes da Terra; e ele olhou e eis que Sião, com o correr do tempo, foi arrebatada ao céu. E o Senhor disse a Enoque: Eis minha morada para sempre."},{"verse":22,"text":"E Enoque também viu os remanescentes do povo que eram os filhos de Adão; e eram uma mistura de toda a semente de Adão, exceto a de Caim, pois a semente de Caim era negra e não tinha lugar entre eles."},{"verse":23,"text":"E depois que Sião foi arrebatada ao céu, Enoque olhou e eis que todas as nações da Terra estavam diante dele;"},{"verse":24,"text":"E geração sucedia a geração; e Enoque foi elevado e arrebatado, sim, ao seio do Pai e do Filho do Homem; e eis que o poder de Satanás estava sobre toda a face da Terra."},{"verse":25,"text":"E ele viu anjos descendo do céu; e ouviu uma alta voz, dizendo: Ai, ai dos habitantes da Terra."},{"verse":26,"text":"E ele viu Satanás; e este tinha uma grande corrente na mão, que cobria de trevas toda a face da Terra; e ele olhou para cima e riu; e seus anjos rejubilaram-se."},{"verse":27,"text":"E Enoque viu anjos que desciam do céu, prestando testemunho do Pai e do Filho; e o Espírito Santo desceu sobre muitos e eles foram arrebatados, pelos poderes do céu, a Sião."},{"verse":28,"text":"E aconteceu que o Deus do céu olhou o restante do povo e chorou; e Enoque prestou testemunho disso, dizendo: Como é que os céus choram e derramam suas lágrimas como a chuva sobre as montanhas?"},{"verse":29,"text":"E Enoque disse ao Senhor: Como é que podes chorar, sendo que és santo e de toda eternidade para toda eternidade?"},{"verse":30,"text":"E se fosse possível ao homem contar as partículas da Terra, sim, de milhões de terras como esta, não seria sequer o princípio do número de tuas criações; e tuas cortinas ainda estão estiradas; e, contudo, estás ali e teu seio está ali; e também és justo; tu és misericordioso e bondoso para sempre;"},{"verse":31,"text":"E tomaste Sião para teu próprio seio, de todas as tuas criações, de toda eternidade para toda eternidade; e nada a não ser paz, justiça e verdade é a habitação de teu trono; e a misericórdia irá adiante de tua face e não terá fim; como é que podes chorar?"},{"verse":32,"text":"O Senhor disse a Enoque: Olha estes teus irmãos; eles são a obra de minhas próprias mãos e eu dei-lhes seu conhecimento no dia em que os criei; e no Jardim do Éden dei ao homem seu arbítrio;"},{"verse":33,"text":"E a teus irmãos disse eu e também dei mandamento que se amassem uns aos outros e que escolhessem a mim, seu Pai; mas eis que eles não têm afeição e odeiam seu próprio sangue."},{"verse":34,"text":"E o fogo de minha indignação está aceso contra eles; e em meu ardente descontentamento enviarei dilúvios sobre eles, pois minha ardente ira está acesa contra eles."},{"verse":35,"text":"Eis que eu sou Deus; Homem de Santidade é o meu nome; Homem de Conselho é o meu nome; e Infinito e Eterno é o meu nome também."},{"verse":36,"text":"Portanto, posso estender minhas mãos e segurar todas as criações minhas; e meus olhos podem trespassá-las também e, entre todas as obras de minhas mãos, jamais houve tanta maldade como entre teus irmãos."},{"verse":37,"text":"Mas eis que seus pecados cairão sobre a cabeça de seus pais; Satanás será seu pai e angústia, seu destino; e todo o céu chorará sobre eles, sim, toda a obra de minhas mãos; portanto, não deverão os céus chorar, vendo que eles sofrerão?"},{"verse":38,"text":"Mas eis que estes que teus olhos contemplam perecerão nos dilúvios; e eis que os encarcerarei; uma prisão preparei para eles."},{"verse":39,"text":"E aquele que escolhi implorou diante da minha face; portanto, ele sofre pelos pecados deles, desde que se arrependam no dia em que meu Escolhido voltar para mim; e até esse dia eles estarão em tormento;"},{"verse":40,"text":"Por esse motivo, pois, chorarão os céus, sim, e toda a obra de minhas mãos."},{"verse":41,"text":"E aconteceu que o Senhor falou a Enoque e contou a Enoque todos os feitos dos filhos dos homens; portanto, Enoque sabia e contemplou as iniquidades e a angústia deles; e chorou; e estendeu os braços e dilatou-se-lhe o coração, como a eternidade; e comoveram-se-lhe as entranhas e toda a eternidade tremeu."},{"verse":42,"text":"E Enoque também viu Noé e sua família; que a posteridade de todos os filhos de Noé seria salva com uma salvação física."},{"verse":43,"text":"Portanto, Enoque viu que Noé construiu uma arca e que o Senhor sorriu diante dela e segurou-a em sua própria mão; mas, sobre o restante dos iníquos, vieram as enchentes e tragaram-nos."},{"verse":44,"text":"E quando Enoque viu isso, ficou com a alma amargurada e chorou por seus irmãos; e disse aos céus: Recusar-me-ei a ser consolado; mas o Senhor disse a Enoque: Anima-te e alegra-te; e olha."},{"verse":45,"text":"E aconteceu que Enoque olhou; e, a partir de Noé, ele viu todas as famílias da Terra; e clamou ao Senhor, dizendo: Quando chegará o dia do Senhor? Quando se derramará o sangue do Justo para que todos os que choram sejam santificados e tenham vida eterna?"},{"verse":46,"text":"E o Senhor disse: Será no meridiano dos tempos, nos dias de iniquidade e vingança."},{"verse":47,"text":"E eis que Enoque viu o dia da vinda do Filho do Homem na carne; e sua alma rejubilou-se, dizendo: O Justo é levantado e o Cordeiro, morto desde a fundação do mundo; e pela fé eu estou no seio do Pai e eis que Sião está comigo."},{"verse":48,"text":"E aconteceu que Enoque olhou a Terra; e ele ouviu uma voz que vinha de suas entranhas, dizendo: Ai, ai de mim, a mãe dos homens; estou aflita, estou fatigada por causa da iniquidade de meus filhos. Quando descansarei e serei purificada da imundície que saiu de mim? Quando me santificará o meu Criador, para que eu descanse e a retidão permaneça sobre minha face por algum tempo?"},{"verse":49,"text":"E quando Enoque ouviu o lamento da Terra, ele chorou e clamou ao Senhor, dizendo: Ó Senhor, não terás compaixão da Terra? Não abençoarás os filhos de Noé?"},{"verse":50,"text":"E aconteceu que Enoque continuou a clamar ao Senhor, dizendo: Rogo-te, ó Senhor, em nome de teu Unigênito, sim, Jesus Cristo, que tenhas misericórdia de Noé e sua semente, para que a Terra nunca seja coberta pelas enchentes."},{"verse":51,"text":"E o Senhor não pôde negar; e fez aliança com Enoque e jurou-lhe, com um juramento, que deteria as enchentes; que visitaria os filhos de Noé;"},{"verse":52,"text":"E ele expediu um decreto inalterável de que um remanescente de sua semente seria sempre encontrado entre todas as nações enquanto a Terra subsistisse;"},{"verse":53,"text":"E o Senhor disse: Bendito é aquele por meio de cuja semente o Messias virá; pois ele diz: Eu sou o Messias, o Rei de Sião, a Rocha do Céu, que é extensa como a eternidade; quem entrar pela porta e subir por meu intermédio, jamais cairá; portanto, benditos são aqueles de quem falei, porque virão com canções de alegria eterna."},{"verse":54,"text":"E aconteceu que Enoque clamou ao Senhor, dizendo: Quando o Filho do Homem vier na carne, descansará a Terra? Rogo-te que me mostres essas coisas."},{"verse":55,"text":"E o Senhor disse a Enoque: Olha; e ele olhou e viu o Filho do Homem levantado na cruz, segundo o costume dos homens;"},{"verse":56,"text":"E ele ouviu uma alta voz; e os céus foram cobertos; e todas as criações de Deus choraram; e a Terra gemeu; e as rochas partiram-se; e os santos levantaram-se e foram coroados à direita do Filho do Homem, com coroas de glória;"},{"verse":57,"text":"E todos os espíritos que estavam na prisão saíram e puseram-se à direita de Deus; e o restante foi retido em cadeias de trevas até o julgamento do grande dia."},{"verse":58,"text":"E Enoque tornou a chorar e a clamar ao Senhor, dizendo: Quando descansará a Terra?"},{"verse":59,"text":"E Enoque viu o Filho do Homem ascender ao Pai; e clamou ao Senhor, dizendo: Não virás outra vez à Terra? Pois tu és Deus e conheço-te; e juraste-me e ordenaste-me que eu pedisse em nome do teu Unigênito; fizeste-me e deste-me direito a teu trono; e não por mim mesmo, mas por meio de tua própria graça; portanto, te pergunto se não virás outra vez à Terra."},{"verse":60,"text":"E o Senhor disse a Enoque: Como eu vivo, assim virei nos últimos dias, nos dias de iniquidade e vingança, para cumprir o juramento que te fiz concernente aos filhos de Noé;"},{"verse":61,"text":"E chegará o dia em que a Terra descansará, mas antes desse dia os céus escurecerão e um véu de trevas cobrirá a Terra; e os céus tremerão, assim como a Terra; e haverá grandes tribulações entre os filhos dos homens, mas meu povo eu preservarei;"},{"verse":62,"text":"E retidão enviarei dos céus; e verdade farei brotar da terra para prestar testemunho do meu Unigênito; de sua ressurreição dentre os mortos; sim, e também da ressurreição de todos os homens; e retidão e verdade farei varrerem a Terra, como um dilúvio, a fim de reunir meus eleitos dos quatro cantos da Terra em um lugar que prepararei, uma Cidade Santa, para que meu povo cinja os lombos e anseie pelo tempo da minha vinda; pois ali estará meu tabernáculo e chamar-se-á Sião, uma Nova Jerusalém."},{"verse":63,"text":"E o Senhor disse a Enoque: Então irás com toda a tua cidade encontrá-los lá; e recebê-los-emos em nosso seio e eles ver-nos-ão; e debruçar-nos-emos sobre seu pescoço e eles debruçar-se-ão sobre nosso pescoço; e beijar-nos-emos uns aos outros;"},{"verse":64,"text":"E lá será a minha morada e será Sião, a qual sairá dentre todas as criações minhas; e pelo espaço de mil anos a Terra descansará."},{"verse":65,"text":"E aconteceu que Enoque viu o dia da vinda do Filho do Homem nos últimos dias, para habitar na Terra, em retidão, pelo espaço de mil anos;"},{"verse":66,"text":"Mas antes desse dia ele viu grandes tribulações entre os iníquos; e também viu o mar, que se agitava, e o coração dos homens, que desfalecia, esperando com temor os julgamentos do Deus Todo-Poderoso, os quais haveriam de cair sobre os iníquos."},{"verse":67,"text":"E o Senhor mostrou a Enoque todas as coisas, sim, até o fim do mundo; e ele viu o dia dos justos, a hora de sua redenção; e recebeu uma plenitude de alegria;"},{"verse":68,"text":"E todos os dias de Sião, nos dias de Enoque, foram trezentos e sessenta e cinco anos."},{"verse":69,"text":"E Enoque e todo o seu povo andavam com Deus e ele habitou no meio de Sião; e aconteceu que Sião já não existia, porque Deus a recebeu em seu próprio seio; e daí em diante se começou a dizer: Sião Fugiu."}]},{"chapter":8,"verses":[{"verse":1,"text":"E todos os dias de Enoque foram quatrocentos e trinta anos."},{"verse":2,"text":"E aconteceu que Matusalém, o filho de Enoque, não foi levado, a fim de que se cumprissem os convênios que o Senhor fizera com Enoque; porque ele verdadeiramente fez convênio com Enoque de que Noé sairia do fruto de seus lombos."},{"verse":3,"text":"E aconteceu que Matusalém profetizou que de seus lombos nasceriam todos os reinos da Terra (através de Noé); e ele tomou a glória para si."},{"verse":4,"text":"E sobreveio uma grande fome na terra; e o Senhor amaldiçoou a Terra com uma dolorosa maldição e muitos de seus habitantes morreram."},{"verse":5,"text":"E aconteceu que Matusalém viveu cento e oitenta e sete anos; e gerou Lameque;"},{"verse":6,"text":"E Matusalém viveu, depois que gerou Lameque, setecentos e oitenta e dois anos e gerou filhos e filhas;"},{"verse":7,"text":"E todos os dias de Matusalém foram novecentos e sessenta e nove anos; e ele morreu."},{"verse":8,"text":"E Lameque viveu cento e oitenta e dois anos e gerou um filho;"},{"verse":9,"text":"E deu-lhe o nome de Noé, dizendo: Este filho irá consolar-nos quanto a nossa obra e ao trabalho de nossas mãos, por causa da terra que o Senhor amaldiçoou."},{"verse":10,"text":"E Lameque viveu, após gerar Noé, quinhentos e noventa e cinco anos e gerou filhos e filhas;"},{"verse":11,"text":"E todos os dias de Lameque foram setecentos e setenta e sete anos; e morreu."},{"verse":12,"text":"E Noé tinha quatrocentos e cinquenta anos e gerou Jafé; e quarenta e dois anos depois gerou Sem, daquela que foi a mãe de Jafé; e quando tinha quinhentos anos, gerou Cão."},{"verse":13,"text":"E Noé e seus filhos deram ouvidos ao Senhor e obedeceram-lhe; e foram chamados filhos de Deus."},{"verse":14,"text":"E quando esses homens começaram a multiplicar-se na face da Terra e tiveram filhas, os filhos dos homens viram que essas filhas eram belas e tomaram-nas para esposas, segundo sua escolha."},{"verse":15,"text":"E o Senhor disse a Noé: As filhas de teus filhos venderam-se; pois eis que a minha ira está acesa contra os filhos dos homens, porque não dão ouvidos à minha voz."},{"verse":16,"text":"E aconteceu que Noé profetizou e ensinou as coisas de Deus, assim como era no princípio."},{"verse":17,"text":"E o Senhor disse a Noé: O meu Espírito não permanecerá para sempre no homem, pois ele saberá que toda carne há de morrer; contudo, seus dias serão cento e vinte anos; e se os homens não se arrependerem, enviarei enchentes sobre eles."},{"verse":18,"text":"E naqueles dias havia gigantes na Terra e eles procuraram Noé para tirar-lhe a vida; mas o Senhor estava com Noé e o poder de Deus estava sobre ele."},{"verse":19,"text":"E o Senhor ordenou Noé segundo sua própria ordem e mandou que ele fosse anunciar seu Evangelho aos filhos dos homens, sim, tal como foi dado a Enoque."},{"verse":20,"text":"E aconteceu que Noé clamou aos filhos dos homens para que se arrependessem, mas eles não deram ouvidos às suas palavras;"},{"verse":21,"text":"E também, depois de ouvi-lo, chegaram diante dele, dizendo: Eis que somos os filhos de Deus; não temos tomado para nós as filhas dos homens? Não estamos comendo e bebendo e casando-nos e dando em casamento? E nossas mulheres nos dão filhos e os mesmos são homens poderosos, semelhantes aos homens da antiguidade, homens de grande renome. E não deram ouvidos às palavras de Noé."},{"verse":22,"text":"E Deus viu que a iniquidade dos homens se tornara grande na Terra; e que todos os homens se ensoberbeciam na imaginação dos pensamentos de seu coração, sendo apenas maus continuamente."},{"verse":23,"text":"E aconteceu que Noé continuou a sua pregação ao povo, dizendo: Escutai, e dai ouvidos às minhas palavras;"},{"verse":24,"text":"Acreditai e arrependei-vos de vossos pecados e batizai-vos em nome de Jesus Cristo, o Filho de Deus, assim como nossos pais; e recebereis o Espírito Santo a fim de que todas as coisas se manifestem a vós; e, se não o fizerdes, as enchentes vos sobrevirão; não obstante, eles não deram ouvidos."},{"verse":25,"text":"E Noé sentiu pesar e doeu-lhe o coração por ter o Senhor formado o homem na Terra; e isso lhe afligiu o coração."},{"verse":26,"text":"E o Senhor disse: Farei desaparecer o homem, a quem criei, da face da Terra, tanto o homem como os animais e as coisas que rastejam e as aves do ar; pois Noé sentiu pesar por eu tê-los criado e tê-los feito; e invocou-me porque tentaram tirar-lhe a vida."},{"verse":27,"text":"E assim Noé encontrou graça aos olhos do Senhor; porque Noé era um homem justo e perfeito em sua geração; e ele andava com Deus, bem como seus três filhos, Sem, Cão e Jafé."},{"verse":28,"text":"A Terra estava corrompida diante de Deus e encheu-se de violência."},{"verse":29,"text":"E Deus olhou para a Terra e eis que ela estava corrompida, pois toda carne corrompera seu caminho sobre a Terra."},{"verse":30,"text":"E Deus disse a Noé: Chegou para mim o fim de toda carne, pois a Terra está cheia de violência, e eis que farei desaparecer toda carne da Terra."}]}]},{"id":"abraham","title":"Abraão","englishTitle":"Abraham","volume":"Pearl of Great Price","volumeId":"pgp","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Na terra dos caldeus, na residência de meus pais, eu, Abraão, vi que me era necessário encontrar outro lugar para morar;"},{"verse":2,"text":"E achando que havia maior felicidade e paz e descanso para mim, busquei as bênçãos dos pais, e o direito ao qual eu deveria ser ordenado para ministrá-las; tendo eu mesmo sido seguidor da retidão, desejando também ser possuidor de grande conhecimento, e ser maior seguidor da retidão, e possuir maior conhecimento, e ser pai de muitas nações, um príncipe da paz, e desejando receber instruções, e guardar os mandamentos de Deus, tornei-me um herdeiro legítimo, um Sumo Sacerdote, portando o direito que pertencia aos pais."},{"verse":3,"text":"Foi-me conferido pelos pais; veio dos pais desde o princípio do tempo, sim, desde o princípio, ou seja, antes da fundação da Terra, até o presente, sim, o direito do primogênito, ou seja, do primeiro homem, que é Adão, ou seja, o primeiro pai; e por meio dos pais até mim."},{"verse":4,"text":"Busquei minha designação ao Sacerdócio, de acordo com a designação de Deus aos pais, concernente à descendência."},{"verse":5,"text":"Meus pais, tendo-se afastado de sua retidão, e dos santos mandamentos que o Senhor seu Deus lhes dera, voltando-se para a adoração dos deuses dos pagãos, recusaram-se totalmente a dar ouvidos à minha voz;"},{"verse":6,"text":"Pois o seu coração estava determinado a fazer o mal, e estava completamente voltado para o deus de Elquena, e o deus de Libna, e o deus de Mamacra, e o deus de Corás, e o deus do Faraó, rei do Egito;"},{"verse":7,"text":"Portanto, voltaram o coração para o sacrifício dos pagãos, oferecendo os seus filhos a esses ídolos mudos, e não deram ouvidos à minha voz; mas tentaram tirar-me a vida pela mão do sacerdote de Elquena. O sacerdote de Elquena era também o sacerdote do Faraó."},{"verse":8,"text":"Ora, naquele tempo era costume o sacerdote do Faraó, rei do Egito, oferecer, sobre o altar que fora construído na terra da Caldeia para ofertas a esses deuses estranhos, homens, mulheres e crianças."},{"verse":9,"text":"E aconteceu que o sacerdote fez uma oferta ao deus do Faraó, e também ao deus de Sagreel, sim, segundo o costume dos egípcios. Ora, o deus de Sagreel era o sol."},{"verse":10,"text":"Até mesmo uma criança o sacerdote do Faraó ofereceu, como oferta de gratidão, sobre o altar que se achava junto à colina chamada Colina de Potifar, à cabeceira da planície de Olisem."},{"verse":11,"text":"Ora, esse sacerdote oferecera sobre esse altar três virgens de uma só vez, as quais eram filhas de Onita, um descendente real direto dos lombos de Cão. Essas virgens foram oferecidas em sacrifício por causa de sua virtude; recusaram-se a curvar-se para adorar deuses de madeira ou de pedra; foram, portanto, mortas sobre esse altar segundo o costume dos egípcios."},{"verse":12,"text":"E aconteceu que os sacerdotes usaram de violência contra mim, a fim de matar-me também, como fizeram com aquelas virgens sobre esse altar; e para que tenhais conhecimento desse altar, indicar-vos-ei a representação que se encontra no início deste registro."},{"verse":13,"text":"Ele era feito na forma de uma cama, como as que se usavam entre os caldeus, e ficava na frente dos deuses de Elquena, Libna, Mamacra, Corás, e também um deus parecido com o do Faraó, rei do Egito."},{"verse":14,"text":"Para que tenhais uma compreensão desses deuses, apresentei-vos a imagem deles nas figuras que se encontram no início, tipo esse de figuras chamado pelos caldeus de Raleenos, que significa hieróglifos."},{"verse":15,"text":"E quando levantavam as mãos sobre mim, a fim de sacrificar-me e tirar-me a vida, eis que elevei a minha voz ao Senhor meu Deus; e o Senhor escutou e ouviu, e encheu-me com a visão do Todo-Poderoso; e o anjo de sua presença pôs-se a meu lado, e imediatamente soltou as minhas ligaduras;"},{"verse":16,"text":"E a sua voz disse-me: Abraão, Abraão, eis que meu nome é Jeová, e te ouvi e desci para livrar-te, e para levar-te da casa de teu pai, e de toda a tua parentela, para uma terra estranha que não conheces;"},{"verse":17,"text":"E isso porque desviaram de mim o coração, a fim de adorarem o deus de Elquena, e o deus de Libna, e o deus de Mamacra, e o deus de Corás, e o deus do Faraó, rei do Egito; portanto, desci para visitá-los, e para destruir aquele que levantou a mão contra ti, Abraão, meu filho, para tirar-te a vida."},{"verse":18,"text":"Eis que te conduzirei pela minha mão, e levar-te-ei para pôr sobre ti o meu nome, sim, o Sacerdócio de teu pai; e o meu poder estará sobre ti."},{"verse":19,"text":"Como foi com Noé, assim será contigo; mas, mediante o teu ministério, meu nome será conhecido na Terra para sempre, pois eu sou o teu Deus."},{"verse":20,"text":"Eis que a Colina de Potifar ficava na terra de Ur da Caldeia. E o Senhor quebrou o altar de Elquena, e dos deuses da terra, e destruiu-os totalmente, e feriu o sacerdote, de modo que ele morreu; e houve grande lamentação na Caldeia, e também na corte do Faraó; e Faraó significa rei por sangue real."},{"verse":21,"text":"Ora, esse rei do Egito descendia dos lombos de Cão e, por nascimento, era participante do sangue dos cananeus."},{"verse":22,"text":"Dessa descendência nasceram todos os egípcios, e assim se conservou o sangue dos cananeus na terra."},{"verse":23,"text":"A terra do Egito sendo primeiramente descoberta por uma mulher, que era filha de Cão e filha de Egitus que, em caldeu, significa Egito, e quer dizer aquilo que é proibido;"},{"verse":24,"text":"Quando essa mulher descobriu a terra, esta estava debaixo de água; posteriormente estabeleceu seus filhos nela; e assim nasceu de Cão a raça que conservou a maldição naquela região."},{"verse":25,"text":"Ora, o primeiro governo do Egito foi estabelecido pelo Faraó, filho mais velho de Egitus, filha de Cão, e foi à semelhança do governo de Cão, que era patriarcal."},{"verse":26,"text":"O Faraó, sendo um homem justo, estabeleceu o seu reino e julgou o seu povo sábia e justamente todos os seus dias, procurando sinceramente imitar a ordem estabelecida pelos pais nas primeiras gerações, nos dias do primeiro reinado patriarcal, sim, no reinado de Adão e também de Noé, seu pai, que o abençoou com as bênçãos da terra, e com as bênçãos da sabedoria, mas amaldiçoou-o com respeito ao Sacerdócio."},{"verse":27,"text":"Sendo o Faraó dessa linhagem pela qual ele não tinha direito ao Sacerdócio, embora os Faraós o reivindicassem por sua descendência de Noé, através de Cão; assim meu pai foi desviado pela idolatria deles;"},{"verse":28,"text":"Mas tentarei, daqui em diante, delinear a cronologia, partindo de mim e remontando ao princípio da criação, pois os registros chegaram às minhas mãos, e conservo-os até hoje."},{"verse":29,"text":"Ora, após o sacerdote de Elquena ser ferido e morrer, cumpriram-se as coisas que me foram ditas com respeito à terra da Caldeia, que haveria fome na terra."},{"verse":30,"text":"Consequentemente, houve fome por toda a terra da Caldeia, e meu pai foi dolorosamente atormentado por causa da fome; e arrependeu-se do mal que determinara contra mim, de tirar-me a vida."},{"verse":31,"text":"Mas os registros dos pais, sim, dos patriarcas, a respeito do direito ao Sacerdócio, o Senhor meu Deus preservou em minhas próprias mãos; portanto, um conhecimento do princípio da criação, e também dos planetas e das estrelas, como fora dado a conhecer aos patriarcas, conservei até hoje; e procurarei escrever algumas dessas coisas neste registro, para benefício de minha posteridade que virá após mim."}]},{"chapter":2,"verses":[{"verse":1,"text":"Ora, o Senhor Deus fez com que a fome se agravasse na terra de Ur, tanto que Harã, meu irmão, morreu; mas Terá, meu pai, ainda vivia na terra de Ur dos caldeus."},{"verse":2,"text":"E aconteceu que eu, Abraão, tomei Sarai para esposa; e Naor, meu irmão, tomou para esposa Milca, que era filha de Harã."},{"verse":3,"text":"Ora, o Senhor dissera-me: Abraão, sai de teu país, e de tua parentela, e da casa de teu pai, para uma terra que te mostrarei."},{"verse":4,"text":"Portanto, deixei a terra de Ur dos caldeus, a fim de ir para a terra de Canaã; e tomei Ló, filho de meu irmão, e sua mulher e Sarai, minha mulher; e também meu pai me seguiu à terra que denominamos Harã."},{"verse":5,"text":"E a fome diminuiu; e meu pai permaneceu em Harã e lá habitou, porque havia muitos rebanhos em Harã; e meu pai retornou à sua idolatria; assim, ficou em Harã."},{"verse":6,"text":"Mas eu, Abraão, e Ló, filho de meu irmão, oramos ao Senhor, e o Senhor apareceu-me, e disse-me: Levanta-te, e toma Ló contigo; pois pretendo tirar-te de Harã, e fazer de ti um ministro que porte o meu nome em uma terra estranha, a qual darei a tua semente depois de ti por possessão eterna, quando derem ouvidos à minha voz."},{"verse":7,"text":"Pois eu sou o Senhor teu Deus; eu habito no céu; a Terra é o meu escabelo; estendo a mão sobre o mar, e ele obedece à minha voz; faço com que o vento e o fogo sejam a minha carruagem; digo às montanhas: Parti daqui; e eis que elas são levadas por um torvelinho, em um instante, repentinamente."},{"verse":8,"text":"Meu nome é Jeová, e conheço o fim desde o princípio; portanto, minha mão estará sobre ti."},{"verse":9,"text":"E farei de ti uma grande nação, e abençoar-te-ei sobremaneira, e engrandecerei o teu nome entre todas as nações; e serás uma bênção para tua semente depois de ti, para que em suas mãos levem este ministério e Sacerdócio a todas as nações;"},{"verse":10,"text":"E abençoá-las-ei por meio de teu nome; pois todos os que receberem este Evangelho serão chamados segundo o teu nome, e contados como tua semente; e levantar-se-ão e abençoar-te-ão como seu pai;"},{"verse":11,"text":"E abençoarei os que te abençoarem, e amaldiçoarei os que te amaldiçoarem; e em ti (isto é, em teu Sacerdócio) e em tua semente (isto é, teu Sacerdócio), pois faço-te a promessa de que este direito continuará em ti, e em tua semente depois de ti (isto quer dizer a semente literal, ou seja, a semente do corpo), serão abençoadas todas as famílias da Terra, sim, com as bênçãos do Evangelho, que são as bênçãos de salvação, sim, de vida eterna."},{"verse":12,"text":"Ora, depois que o Senhor acabou de falar-me, e retirou sua face de minha presença, eu disse em meu coração: Teu servo procurou-te fervorosamente; agora te encontrei;"},{"verse":13,"text":"Enviaste o teu anjo para livrar-me dos deuses de Elquena, e bem farei dando ouvidos à tua voz; portanto, deixa o teu servo levantar-se e partir em paz."},{"verse":14,"text":"Assim eu, Abraão, parti como o Senhor me dissera, e Ló comigo; e eu, Abraão, tinha sessenta e dois anos de idade quando parti de Harã."},{"verse":15,"text":"E levei Sarai, a quem tomara para esposa quando me encontrava em Ur, na Caldeia, e Ló, filho de meu irmão, e todas as provisões que havíamos reunido, bem como as almas que havíamos conquistado em Harã; e tomamos o caminho da terra de Canaã; e habitamos em tendas no caminho;"},{"verse":16,"text":"Portanto, a eternidade foi nosso abrigo e nossa rocha e nossa salvação, enquanto viajamos de Harã, pelo caminho de Jérson, para a terra de Canaã."},{"verse":17,"text":"Ora eu, Abraão, construí um altar na terra de Jérson, e fiz uma oferta ao Senhor; e orei para que a fome se desviasse da casa de meu pai, a fim de que não perecessem."},{"verse":18,"text":"E de Jérson atravessamos a terra até o lugar de Sequém; ficava nas planícies de Moré, e já havíamos entrado pelas fronteiras da terra dos cananeus; e eu ofereci sacrifício lá nas planícies de Moré, e invoquei o Senhor fervorosamente, porque já havíamos entrado na terra desta nação idólatra."},{"verse":19,"text":"E o Senhor apareceu-me em resposta às minhas orações, e disse-me: À tua semente darei esta terra."},{"verse":20,"text":"E eu, Abraão, levantei-me do local do altar que eu construíra ao Senhor, e de lá parti para uma montanha no lado oriental de Betel; e ali armei minha tenda, tendo Betel ao ocidente, e Ai ao oriente; e lá construí outro altar ao Senhor, e tornei a invocar o nome do Senhor."},{"verse":21,"text":"E eu, Abraão, continuei viajando em direção ao sul; e a fome continuava na terra; e eu, Abraão, decidi descer para o Egito a fim de lá habitar, porquanto a fome agravara-se muito."},{"verse":22,"text":"E aconteceu que quando eu estava para entrar no Egito, o Senhor disse-me: Eis que Sarai, tua esposa, é uma mulher muito formosa à vista;"},{"verse":23,"text":"Portanto, acontecerá que quando os egípcios a virem, dirão: Ela é mulher dele; e matar-te-ão, mas a ela guardarão em vida; portanto, faze desta maneira:"},{"verse":24,"text":"Que ela diga aos egípcios que é tua irmã, e a tua alma viverá."},{"verse":25,"text":"E aconteceu que eu, Abraão, contei a Sarai, minha mulher, tudo o que o Senhor me dissera. Portanto, dize-lhes, rogo-te, que és minha irmã, para que me vá bem por tua causa, e minha alma viva graças a ti."}]},{"chapter":3,"verses":[{"verse":1,"text":"E eu, Abraão, tinha o Urim e Tumim, que o Senhor meu Deus me dera em Ur dos caldeus;"},{"verse":2,"text":"E vi as estrelas e elas eram muito grandes; e vi que uma delas estava mais perto do trono de Deus; e havia muitas grandes que estavam perto dele;"},{"verse":3,"text":"E o Senhor disse-me: Estas são as que regem; e o nome da grande é Colobe, porque ela está próxima de mim, pois eu sou o Senhor teu Deus; coloquei esta para reger todas as que pertencem à mesma ordem daquela onde te encontras."},{"verse":4,"text":"E o Senhor disse-me, pelo Urim e Tumim, que Colobe seguia, em suas revoluções, o padrão do Senhor quanto às suas épocas e estações; que uma revolução era um dia para o Senhor, segundo a sua maneira de calcular, sendo mil anos conforme o tempo designado para onde te encontras. Esse é o cálculo do tempo do Senhor, de acordo com o cálculo de Colobe."},{"verse":5,"text":"E o Senhor disse-me: O planeta que é a luz menor, menor que aquele que é para governar o dia, e que governa a noite, está acima ou é maior, em questão de cálculo, do que aquele no qual te encontras, porque se move numa ordem mais vagarosa; isto segue a ordem, porque ele fica acima da Terra na qual te encontras; portanto, o cálculo de seu tempo não é tão grande no que se refere ao número de seus dias, e de meses, e de anos."},{"verse":6,"text":"E o Senhor disse-me: Ora, Abraão, estes dois fatos existem, eis que teus olhos veem; a ti é dado conhecer o cálculo dos tempos, e o tempo estabelecido, sim, o tempo estabelecido da Terra na qual te encontras; e o tempo estabelecido da luz maior, que foi posta para governar o dia, e o tempo estabelecido da luz menor, que foi posta para governar a noite."},{"verse":7,"text":"Ora, o tempo estabelecido da luz menor é um tempo mais longo, quanto ao seu cálculo, do que o cálculo do tempo da Terra na qual te encontras."},{"verse":8,"text":"E onde esses dois fatos existirem, haverá um outro fato acima deles, isto é, haverá outro planeta cujo cálculo de tempo será ainda mais longo;"},{"verse":9,"text":"E assim haverá o cálculo do tempo de um planeta acima de outro, até que te aproximes de Colobe; e Colobe segue o cálculo do tempo do Senhor; e Colobe está perto do trono de Deus, a fim de governar todos os planetas pertencentes à mesma ordem daquele em que te encontras."},{"verse":10,"text":"E a ti é dado saber o tempo estabelecido de todas as estrelas que foram postas para dar luz, até que te aproximes do trono de Deus."},{"verse":11,"text":"Assim eu, Abraão, falei com o Senhor face a face, como um homem fala com outro; e ele falou-me das obras que suas mãos haviam feito;"},{"verse":12,"text":"E ele disse-me: Meu filho, meu filho (e sua mão estava estendida), eis que te mostrarei todas elas. E ele pôs a mão sobre meus olhos e eu vi aquelas coisas que suas mãos haviam feito; e eram muitas. E elas multiplicaram-se ante meus olhos, e não consegui ver seu fim."},{"verse":13,"text":"E ele disse-me: Este é Sineá, que é o sol. E ele disse-me: Colobe, que é estrela. E disse-me: Olea, que é a lua. E ele disse-me: Cocaubeam, que significa estrelas, ou seja, todas as grandes luzes que estavam no firmamento do céu."},{"verse":14,"text":"E era noite quando o Senhor me disse estas palavras: Multiplicarei a ti e a tua semente depois de ti, como estas: e se puderes contar o número das areias, assim será o número de tuas sementes."},{"verse":15,"text":"E o Senhor disse-me: Abraão, mostro-te estas coisas antes de ires para o Egito, para que declares todas estas palavras."},{"verse":16,"text":"Se existirem duas coisas, e houver uma acima da outra, haverá coisas maiores acima delas; portanto, Colobe é a maior de todas as Cocaubeam que viste, porque é a que está mais próxima de mim."},{"verse":17,"text":"Ora, se houver duas coisas, uma acima da outra, e a lua estiver acima da Terra, então poderá haver um planeta ou uma estrela acima dela; e nada há que o Senhor teu Deus se proponha a fazer que não faça."},{"verse":18,"text":"Não obstante, ele fez a maior estrela; assim também, se houver dois espíritos, e um for mais inteligente que o outro, esses dois espíritos, não obstante um ser mais inteligente que o outro, não tiveram princípio; eles existiam antes, eles não terão fim, eles existirão depois, pois são gnolaum, ou seja, eternos."},{"verse":19,"text":"E o Senhor disse-me: Estes dois fatos realmente existem, que há dois espíritos, sendo um mais inteligente que o outro; haverá um outro mais inteligente que eles; eu sou o Senhor teu Deus, eu sou mais inteligente que todos eles."},{"verse":20,"text":"O Senhor teu Deus enviou seu anjo para livrar-te das mãos do sacerdote de Elquena."},{"verse":21,"text":"Eu habito no meio de todos eles; agora, portanto, desci até ti para anunciar-te as obras de minhas mãos, pelas quais minha sabedoria supera todos eles, pois reino nos céus acima e na Terra abaixo, com toda a sabedoria e prudência, sobre todas as inteligências que teus olhos viram desde o princípio; desci, no princípio, no meio de todas as inteligências que viste."},{"verse":22,"text":"Ora, o Senhor mostrara a mim, Abraão, as inteligências que foram organizadas antes de o mundo existir; e entre todas essas havia muitas das nobres e grandes;"},{"verse":23,"text":"E Deus viu que essas almas eram boas; e ele estava no meio delas e disse: A estes farei meus governantes; pois ele se encontrava entre aqueles que eram espíritos, e viu que eles eram bons; e disse-me: Abraão, tu és um deles; foste escolhido antes de nasceres."},{"verse":24,"text":"E estava entre eles um que era semelhante a Deus; e ele disse aos que se achavam com ele: Desceremos, pois há espaço lá, e tomaremos destes materiais, e faremos uma terra onde estes possam habitar;"},{"verse":25,"text":"E assim os provaremos para ver se farão todas as coisas que o Senhor seu Deus lhes ordenar;"},{"verse":26,"text":"E os que guardarem seu primeiro estado receberão um acréscimo; e os que não guardarem seu primeiro estado não terão glória no mesmo reino que aqueles que guardarem seu primeiro estado; e os que guardarem seu segundo estado terão um acréscimo de glória sobre sua cabeça para todo o sempre."},{"verse":27,"text":"E o Senhor disse: Quem enviarei? E um semelhante ao Filho do Homem respondeu: Eis-me aqui, envia-me. E outro respondeu e disse: Eis-me aqui, envia-me. E o Senhor disse: Enviarei o primeiro."},{"verse":28,"text":"E o segundo irou-se, e não guardou seu primeiro estado; e, naquele dia, muitos o seguiram."}]},{"chapter":4,"verses":[{"verse":1,"text":"E então o Senhor disse: Desçamos. E eles desceram no princípio; e eles, isto é, os Deuses, organizaram e formaram os céus e a Terra."},{"verse":2,"text":"E a Terra, depois de formada, estava vazia e desolada, porque eles não haviam formado coisa alguma a não ser a Terra; e as trevas reinavam sobre a face do abismo, e o Espírito dos Deuses pairava sobre a face das águas."},{"verse":3,"text":"E eles (os Deuses) disseram: Haja luz; e houve luz."},{"verse":4,"text":"E eles (os Deuses) tiveram consciência da luz, pois era brilhante; e eles separaram a luz, ou melhor, fizeram com que ela fosse separada das trevas."},{"verse":5,"text":"E os Deuses chamaram à luz Dia e às trevas chamaram Noite. E aconteceu que, do entardecer até a manhã chamaram noite; e da manhã até o entardecer chamaram dia; e isso foi o primeiro, ou seja, o princípio do que eles chamaram dia e noite."},{"verse":6,"text":"E os Deuses também disseram: Haja uma expansão no meio das águas; e ela separará as águas das águas."},{"verse":7,"text":"E os Deuses ordenaram a expansão, de modo que ela separou as águas que estavam debaixo da expansão das que estavam por cima da expansão; e assim foi, como eles ordenaram."},{"verse":8,"text":"E os Deuses chamaram à expansão Céu. E aconteceu que foi do entardecer até a manhã que eles chamaram noite; e aconteceu que foi da manhã até o entardecer que eles chamaram dia; e essa foi a segunda vez que eles chamaram noite e dia."},{"verse":9,"text":"E os Deuses ordenaram, dizendo: Ajuntem-se as águas debaixo do céu num lugar e a terra surja seca; e foi como eles ordenaram;"},{"verse":10,"text":"E os Deuses chamaram à porção seca, Terra; e ao ajuntamento das águas chamaram Grandes Águas; e os Deuses viram que foram obedecidos."},{"verse":11,"text":"E os Deuses disseram: Preparemos a terra para produzir relva; a erva que dê semente; a árvore frutífera que dê fruto segundo sua espécie, cuja semente reproduza sua própria semelhança na Terra; e assim foi, como eles ordenaram."},{"verse":12,"text":"E os Deuses organizaram a terra para produzir relva de sua própria semente e a erva para produzir erva de sua própria semente, dando semente segundo sua espécie; e a terra para produzir a árvore de sua própria semente, dando fruto cuja semente pudesse apenas produzir o que estivesse em si, segundo sua espécie; e os Deuses viram que foram obedecidos."},{"verse":13,"text":"E aconteceu que eles contaram os dias; do entardecer até a manhã chamaram noite; e aconteceu que, da manhã até o entardecer, chamaram dia; e foi a terceira vez."},{"verse":14,"text":"E os Deuses organizaram as luzes na expansão do céu, e fizeram-nas separar o dia da noite; e organizaram-nas para serem por sinais e por estações, e por dias e por anos;"},{"verse":15,"text":"E organizaram-nas para serem por luzes na expansão do céu, a fim de darem luz à Terra; e assim foi."},{"verse":16,"text":"E os Deuses organizaram as duas grandes luzes, a luz maior para governar o dia e a luz menor para governar a noite; com a luz menor também fixaram as estrelas;"},{"verse":17,"text":"E os Deuses fixaram-nas na expansão dos céus para darem luz à Terra, e para governarem o dia e a noite, e para separarem a luz das trevas."},{"verse":18,"text":"E os Deuses vigiaram aquelas coisas que eles haviam ordenado, até elas obedecerem."},{"verse":19,"text":"E aconteceu que, do entardecer até a manhã, foi noite; e aconteceu que, da manhã até o entardecer, foi dia; e foi a quarta vez."},{"verse":20,"text":"E os Deuses disseram: Preparemos as águas para produzirem abundantemente as criaturas que se movem e que têm vida; e as aves, para que voem acima da Terra na expansão aberta do céu."},{"verse":21,"text":"E os Deuses prepararam as águas para que produzissem grandes baleias, e toda criatura vivente que se move, que as águas haviam de produzir abundantemente segundo sua espécie; e toda ave alada segundo sua espécie. E os Deuses viram que seriam obedecidos, e que seu plano era bom."},{"verse":22,"text":"E os Deuses disseram: Abençoá-los-emos, e faremos com que frutifiquem e se multipliquem, e encham as águas nos mares, ou seja, nas grandes águas; e faremos com que as aves se multipliquem na Terra."},{"verse":23,"text":"E aconteceu que foi do entardecer até a manhã que eles chamaram noite; e aconteceu que foi da manhã até o entardecer que eles chamaram dia; e foi a quinta vez."},{"verse":24,"text":"E os Deuses prepararam a Terra para produzir criaturas viventes segundo sua espécie, gado e coisas que rastejam e bestas da Terra segundo sua espécie; e foi como eles tinham dito."},{"verse":25,"text":"E os Deuses organizaram a Terra para produzir as bestas segundo sua espécie, e gado segundo sua espécie, e todas as coisas que rastejam sobre a Terra segundo sua espécie; e os Deuses viram que eles obedeceriam."},{"verse":26,"text":"E os Deuses aconselharam-se entre si e disseram: Desçamos e formemos o homem a nossa imagem, segundo nossa semelhança; e dar-lhe-emos domínio sobre os peixes do mar, e sobre as aves do ar, e sobre o gado e sobre toda a Terra, e sobre todas as coisas que rastejam sobre a Terra."},{"verse":27,"text":"Então os Deuses desceram para organizar o homem a sua própria imagem, para formá-lo à imagem dos Deuses, para formá-los homem e mulher."},{"verse":28,"text":"E os Deuses disseram: Abençoá-los-emos. E os Deuses disseram: Faremos com que sejam frutíferos e se multipliquem e encham a terra e subjuguem-na e tenham domínio sobre os peixes do mar e sobre as aves do ar e sobre toda coisa vivente que se move sobre a Terra."},{"verse":29,"text":"E os Deuses disseram: Eis que lhes daremos toda erva que contém semente que cresça na face de toda a Terra e toda árvore que tenha fruto; sim, e dar-lhes-emos o fruto da árvore que produz semente; ser-lhes-á para alimento."},{"verse":30,"text":"E a toda besta da Terra e a toda ave do ar e a toda coisa que rasteja sobre a Terra, eis que daremos vida; e também lhes daremos toda erva verde para alimento e todas estas coisas serão assim organizadas."},{"verse":31,"text":"E os Deuses disseram: Faremos tudo o que dissemos e organizá-los-emos; e eis que serão muito obedientes. E aconteceu que foi do entardecer até a manhã que eles chamaram noite; e aconteceu que foi da manhã até o entardecer que eles chamaram dia; e eles contaram a sexta vez."}]},{"chapter":5,"verses":[{"verse":1,"text":"E assim terminaremos os céus e a Terra, e todas as suas hostes."},{"verse":2,"text":"E os Deuses disseram entre si: Na sétima vez terminaremos nossa obra, sobre a qual deliberamos; e descansaremos na sétima vez de toda nossa obra sobre a qual deliberamos."},{"verse":3,"text":"E os Deuses concluíram na sétima vez, porque na sétima vez eles descansariam de todas as obras que eles (os Deuses) decidiram entre si formar; e santificaram-na. E assim foram suas decisões quando decidiram entre si formar os céus e a Terra."},{"verse":4,"text":"E os Deuses desceram e formaram essas gerações dos céus e da Terra, quando foram feitas no dia em que os Deuses criaram a Terra e os céus,"},{"verse":5,"text":"De acordo com tudo o que eles haviam dito concernente a toda planta do campo antes de estar na terra, e toda erva do campo antes de crescer; pois os Deuses não haviam feito chover sobre a Terra quando decidiram criá-las; e não haviam formado um homem para lavrar o solo."},{"verse":6,"text":"Mas subiu um vapor da Terra, e regou toda a superfície do solo."},{"verse":7,"text":"E os Deuses formaram o homem do pó da terra, e tomaram o seu espírito (isto é, o espírito do homem) e puseram-no nele; e sopraram em suas narinas o fôlego da vida; e o homem tornou-se uma alma vivente."},{"verse":8,"text":"E os Deuses plantaram um jardim no Éden, na parte oriental, e ali colocaram o homem, cujo espírito tinham posto no corpo que haviam formado."},{"verse":9,"text":"E da terra fizeram os Deuses brotar toda árvore que é agradável à vista e boa para alimento; também a árvore da vida no meio do jardim, e a árvore do conhecimento do bem e do mal."},{"verse":10,"text":"Havia um rio que saía do Éden, para regar o jardim; e dali se dividia e se tornava em quatro braços."},{"verse":11,"text":"E os Deuses tomaram o homem e puseram-no no Jardim do Éden, para cultivá-lo e guardá-lo."},{"verse":12,"text":"E os Deuses ordenaram ao homem, dizendo: De toda árvore do jardim podes comer livremente,"},{"verse":13,"text":"Mas da árvore do conhecimento do bem e do mal não comerás; porque no tempo em que dela comeres, certamente morrerás. Ora eu, Abraão, vi que era segundo o tempo do Senhor, que era segundo o tempo de Colobe; porque até então os Deuses não tinham dado a Adão a maneira de calcular seu tempo."},{"verse":14,"text":"E os Deuses disseram: Façamos uma adjutora adequada para o homem, porque não é bom que o homem esteja só; portanto, formaremos uma adjutora adequada para ele."},{"verse":15,"text":"E os Deuses fizeram um sono profundo cair sobre Adão e ele dormiu; e eles tomaram de uma de suas costelas e fecharam a carne em seu lugar;"},{"verse":16,"text":"E da costela que os Deuses haviam tirado do homem, eles formaram uma mulher e levaram-na para o homem."},{"verse":17,"text":"E Adão disse: Esta era osso de meus ossos e carne de minha carne; agora ela será chamada Mulher, porque foi tirada do homem;"},{"verse":18,"text":"Portanto, deixará o homem seu pai e sua mãe e apegar-se-á a sua mulher; e eles serão uma carne."},{"verse":19,"text":"E estavam ambos nus, o homem e sua mulher, e não se envergonhavam."},{"verse":20,"text":"E da terra os Deuses formaram toda besta do campo e toda ave do ar; e levaram-nas a Adão para ver como as chamaria; e o que Adão chamasse cada criatura vivente, tal seria seu nome."},{"verse":21,"text":"E Adão deu nome a todo o gado, às aves do ar, a toda besta do campo; e para Adão foi encontrada uma adjutora própria para ele."}]}]},{"id":"joseph-smith-matthew","title":"Joseph Smith—Mateus","englishTitle":"Joseph Smith-Matthew","volume":"Pearl of Great Price","volumeId":"pgp","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Porque eu vos digo que desde agora não me vereis, nem sabereis que sou aquele de quem os profetas escreveram, até que digais: Bendito o que vem em nome do Senhor, nas nuvens do céu, e todos os santos anjos com ele. Então entenderam seus discípulos que ele retornaria à Terra, depois de haver sido glorificado e coroado à mão direita de Deus."},{"verse":2,"text":"E Jesus saiu, e afastou-se do templo; e aproximaram-se dele os seus discípulos para ouvi-lo, dizendo: Mestre, fala-nos a respeito dos edifícios do templo, pois disseste: Serão derrubados e se vos farão desertos."},{"verse":3,"text":"E Jesus disse-lhes: Não vedes todas essas coisas, e não as compreendeis? Em verdade vos digo: Não ficará aqui, neste templo, pedra sobre pedra que não seja derrubada."},{"verse":4,"text":"E Jesus deixou-os, e subiu ao Monte das Oliveiras. E estando assentado no Monte das Oliveiras, chegaram-se a ele os seus discípulos, em particular, dizendo: Dize-nos quando serão essas coisas que disseste a respeito da destruição do templo, e dos judeus; e qual é o sinal da tua vinda e do fim do mundo, ou seja, a destruição dos iníquos, que é o fim do mundo?"},{"verse":5,"text":"E Jesus respondeu, e disse-lhes: Acautelai-vos, que ninguém vos engane;"},{"verse":6,"text":"Porque muitos virão em meu nome, dizendo: Eu sou Cristo; e enganarão a muitos;"},{"verse":7,"text":"Então vos hão de entregar para serdes atormentados, e matar-vos-ão; e sereis odiados por todas as nações por causa de meu nome;"},{"verse":8,"text":"E então muitos serão levados a pecar, e trair-se-ão uns aos outros, e uns aos outros se odiarão;"},{"verse":9,"text":"E surgirão muitos falsos profetas, e enganarão a muitos;"},{"verse":10,"text":"E por sobejar a iniquidade, o amor de muitos esfriará;"},{"verse":11,"text":"Mas o que permanecer firme e não for vencido, esse será salvo."},{"verse":12,"text":"Quando, pois, virdes a abominação da desolação, de que falou o profeta Daniel, concernente à destruição de Jerusalém, então estareis no lugar santo; quem ler, entenda."},{"verse":13,"text":"Então, os que estiverem na Judeia fujam para os montes;"},{"verse":14,"text":"Quem estiver sobre o telhado fuja, e não volte para tirar coisa alguma de sua casa;"},{"verse":15,"text":"Nem volte para buscar suas vestes aquele que estiver no campo;"},{"verse":16,"text":"E ai das grávidas, e das que amamentarem naqueles dias;"},{"verse":17,"text":"Portanto, rogai ao Senhor para que vossa fuga não aconteça no inverno, nem no dia do Sábado;"},{"verse":18,"text":"Porque então, naqueles dias, haverá grandes aflições sobre os judeus, e sobre os habitantes de Jerusalém, tais como nunca foram antes enviadas por Deus sobre Israel, desde o princípio de seu reino até agora; não, nem jamais tornarão a ser enviadas sobre Israel."},{"verse":19,"text":"Todas as coisas que lhes aconteceram são somente o princípio das dores que lhes advirão."},{"verse":20,"text":"E a não ser que aqueles dias fossem abreviados, nenhum de sua carne se salvaria; mas por causa dos eleitos, de acordo com o convênio, aqueles dias serão abreviados."},{"verse":21,"text":"Eis que essas coisas vos disse em relação aos judeus; e também, após as aflições daqueles dias, que cairão sobre Jerusalém, se alguém vos disser: Eis que o Cristo está aqui, ou ali; não lhe deis crédito;"},{"verse":22,"text":"Porque nesses dias surgirão também falsos Cristos, e falsos profetas; e farão tão grandes sinais e prodígios que, se possível, enganarão até os eleitos, que são os eleitos de acordo com o convênio."},{"verse":23,"text":"Eis que vos digo essas coisas por causa dos eleitos; e também ouvireis de guerras, e rumores de guerras; vede que não vos inquieteis, pois tudo que vos disse deve acontecer; mas ainda não é o fim."},{"verse":24,"text":"Eis que eu vo-lo disse antes;"},{"verse":25,"text":"Portanto, se vos disserem: Eis que ele está no deserto; não saiais; Eis que ele está nas câmaras secretas; não acrediteis;"},{"verse":26,"text":"Porque assim como a luz da manhã sai do oriente, e brilha até o ocidente, e cobre toda a Terra, assim será também a vinda do Filho do Homem."},{"verse":27,"text":"E agora vos dou uma parábola: Eis que onde estiver o cadáver, ali se ajuntarão as águias; assim também serão meus eleitos reunidos dos quatro cantos da Terra."},{"verse":28,"text":"E eles ouvirão de guerras, e rumores de guerras."},{"verse":29,"text":"Eis que falo por causa de meus eleitos; porque nação se levantará contra nação, e reino contra reino; haverá fomes, e pestes, e terremotos em vários lugares."},{"verse":30,"text":"E também, por sobejar a iniquidade, o amor de muitos esfriará; mas o que não for vencido, esse será salvo."},{"verse":31,"text":"E também este Evangelho do Reino será pregado em todo o mundo, em testemunho a todas as nações; e então virá o fim, ou seja, a destruição dos iníquos;"},{"verse":32,"text":"E também será cumprida a abominação da desolação de que falou o profeta Daniel."},{"verse":33,"text":"E imediatamente após a aflição desses dias, o sol escurecerá, e a lua não dará a sua luz; e as estrelas cairão do céu, e os poderes do céu serão abalados."},{"verse":34,"text":"Em verdade vos digo: Essa geração, na qual essas coisas serão mostradas, não passará até que tudo o que eu disse seja cumprido."},{"verse":35,"text":"Contudo, chegarão os dias em que o céu e a Terra hão de passar; minhas palavras, porém, não passarão, mas todas serão cumpridas."},{"verse":36,"text":"E, como eu disse antes, depois da aflição desses dias, e de os poderes dos céus serem abalados, então aparecerá o sinal do Filho do Homem no céu; e então todas as tribos da Terra se lamentarão; e verão o Filho do Homem vindo nas nuvens do céu, com poder e grande glória;"},{"verse":37,"text":"E o que entesourar minha palavra não será enganado, porque o Filho do Homem virá e enviará seus anjos adiante dele com o grande som de uma trombeta; e eles ajuntarão o restante de seus eleitos dos quatro ventos, de uma a outra extremidade do céu."},{"verse":38,"text":"Aprendei, pois, a parábola da figueira: Quando já os seus ramos se tornam tenros e ela começa a dar folhas, sabeis que está próximo o verão;"},{"verse":39,"text":"Assim também, meus eleitos, quando eles virem todas essas coisas, saberão que ele está próximo, sim, às portas;"},{"verse":40,"text":"Mas daquele dia e hora ninguém sabe; não, nem os anjos de Deus no céu, mas unicamente meu Pai."},{"verse":41,"text":"Mas como foi nos dias de Noé, assim será também na vinda do Filho do Homem;"},{"verse":42,"text":"Porque será com eles como foi nos dias anteriores ao dilúvio; porque até o dia em que Noé entrou na arca, eles comiam e bebiam, casavam-se e davam-se em casamento;"},{"verse":43,"text":"E não o perceberam até que veio o dilúvio, e levou-os a todos; assim será também a vinda do Filho do Homem."},{"verse":44,"text":"Então será cumprido aquilo que está escrito: Que nos últimos dias, estando dois no campo, será levado um, e deixado o outro;"},{"verse":45,"text":"Estando dois moendo no moinho, será levado um, e deixado o outro;"},{"verse":46,"text":"E o que digo a um digo a todos os homens; vigiai, pois, porque não sabeis a que hora há de vir o vosso Senhor."},{"verse":47,"text":"Mas sabei isto: Se o bom pai de família soubesse a que vigília viria o ladrão, teria vigiado e não teria deixado minar a sua casa, mas estaria preparado."},{"verse":48,"text":"Por isso, estai vós preparados também, porque o Filho do Homem há de vir à hora em que não pensais."},{"verse":49,"text":"Quem é, pois, o servo fiel e prudente, a quem o seu senhor constituiu sobre a sua casa, para dar o sustento a seu tempo?"},{"verse":50,"text":"Bem-aventurado é aquele servo que o seu senhor, quando vier, achar fazendo assim; e em verdade vos digo que o porá sobre todos os seus bens."},{"verse":51,"text":"Mas se aquele mau servo disser no seu coração: O meu senhor retarda sua vinda;"},{"verse":52,"text":"E começar a espancar os seus conservos, e a comer e a beber com os ébrios,"},{"verse":53,"text":"Virá o senhor daquele servo num dia em que não o espera, e à hora em que ele não sabe;"},{"verse":54,"text":"E separá-lo-á e destinará a sua parte com os hipócritas; ali haverá pranto e ranger de dentes."},{"verse":55,"text":"E assim virá o fim dos iníquos, de acordo com a profecia de Moisés, que diz: Eles serão afastados dentre o povo; contudo, não é ainda o fim da Terra, mas está próximo."}]}]},{"id":"joseph-smith-history","title":"Joseph Smith—História","englishTitle":"Joseph Smith-History","volume":"Pearl of Great Price","volumeId":"pgp","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Devido às muitas publicações que foram postas em circulação, por pessoas maldosas e insidiosas, com relação ao surgimento e progresso de A Igreja de Jesus Cristo dos Santos dos Últimos Dias, todas elas destinadas pelos autores a combater sua reputação como Igreja e seu progresso no mundo — fui levado a escrever esta história para elucidar a mente pública e apresentar, aos que buscam a verdade, os fatos tal como sucederam, tanto em relação a mim como à Igreja e até onde tenho conhecimento desses fatos."},{"verse":2,"text":"Nesta história apresentarei, com verdade e em retidão, os vários acontecimentos relacionados a esta Igreja, como se passaram ou como existem presentemente, sendo agora [1838] o oitavo ano da organização da referida Igreja."},{"verse":3,"text":"Nasci no ano de nosso Senhor de 1805, no dia vinte e três de dezembro, na cidade de Sharon, Condado de Windsor, Estado de Vermont. (…) Meu pai, Joseph Smith Sênior, saiu do Estado de Vermont e mudou-se para Palmyra, no Condado de Ontário (atualmente Wayne), no Estado de Nova York, quando eu tinha mais ou menos dez anos. Cerca de quatro anos depois da chegada de meu pai a Palmyra, ele mudou-se com a família para Manchester, no mesmo Condado de Ontário —"},{"verse":4,"text":"Sua família consistia em onze almas, a saber: meu pai, Joseph Smith; minha mãe, Lucy Smith (cujo nome antes do casamento era Mack, filha de Solomon Mack); meus irmãos, Alvin (que morreu em 19 de novembro de 1823, aos 25 anos de idade), Hyrum, eu, Samuel Harrison, William, Don Carlos; e minhas irmãs, Sophronia, Catherine e Lucy."},{"verse":5,"text":"No decorrer do segundo ano após nossa mudança para Manchester, houve, no lugar onde morávamos, um alvoroço incomum por questões religiosas. Começou com os metodistas, mas logo se generalizou entre todas as seitas daquela parte do país. Em verdade, toda a região parecia afetada por esse alvoroço e grandes multidões uniram-se aos diferentes grupos religiosos, o que criou considerável agitação e divisão entre o povo, clamando alguns “Eis aqui!” e outros “Eis ali!” Uns contendiam pela fé metodista, outros pela presbiteriana e outros pela batista."},{"verse":6,"text":"Pois apesar do grande amor que os conversos dessas diferentes crenças expressavam na época de sua conversão e do grande zelo demonstrado pelos respectivos cleros, que ativamente se levantavam para promover esse quadro singular de sentimento religioso com o fim de converter a todos, como se compraziam em afirmar, deixando que as pessoas se unissem à seita que mais lhes agradasse; contudo, quando os conversos começaram a afastar-se, uns para um grupo e outros para outro, verificou-se que os supostos bons sentimentos, tanto dos sacerdotes como dos conversos, eram mais pretensos que reais; pois criou-se um ambiente de grande confusão e animosidade — sacerdote contendendo com sacerdote e converso com converso; de modo que todos os bons sentimentos mútuos, se é que jamais haviam existido, perderam-se inteiramente numa luta de palavras e choque de opiniões."},{"verse":7,"text":"Nessa época eu estava com quatorze anos de idade. A família de meu pai fora convertida à fé presbiteriana e quatro deles uniram-se a essa igreja, a saber: minha mãe, Lucy, meus irmãos Hyrum e Samuel Harrison e minha irmã Sophronia."},{"verse":8,"text":"Durante esses dias de grande alvoroço, minha mente foi levada a sérias reflexões e grande inquietação; mas embora os meus sentimentos fossem profundos e muitas vezes pungentes, ainda assim me conservei afastado de todos esses grupos, embora assistisse às suas diversas reuniões tão frequentemente quanto a ocasião me permitisse. Com o correr do tempo, inclinei-me um tanto para a seita metodista e senti algum desejo de unir-me a eles; mas tão grandes eram a confusão e a contenda entre as diferentes denominações, que para alguém jovem como eu, tão inexperiente em relação aos homens e às coisas, era impossível chegar a qualquer conclusão definitiva acerca de quem estava certo e de quem estava errado."},{"verse":9,"text":"Minha mente, às vezes, alvoroçava-se bastante, tão grandes e incessantes eram o clamor e o tumulto. Os presbiterianos eram decididamente contra os batistas e os metodistas, e valiam-se de toda a força, tanto da razão como de sofismas, para provar os erros deles, ou pelo menos fazer o povo acreditar que eles estavam errados. Por outro lado, os batistas e os metodistas eram igualmente zelosos no esforço de estabelecer suas próprias doutrinas e refutar todas as outras."},{"verse":10,"text":"Em meio a essa guerra de palavras e divergência de opiniões, muitas vezes disse a mim mesmo: Que deve ser feito? Quem, dentre todos esses grupos está certo, ou estão todos igualmente errados? Se algum deles é correto, qual é, e como poderei sabê-lo?"},{"verse":11,"text":"Em meio à inquietação extrema causada pelas controvérsias desses grupos de religiosos, li um dia na Epístola de Tiago, primeiro capítulo, versículo cinco, o seguinte: E, se algum de vós tem falta de sabedoria, peça-a a Deus, que a todos dá liberalmente, e o não lança em rosto, e ser-lhe-á dada."},{"verse":12,"text":"Jamais uma passagem de escritura penetrou com mais poder no coração de um homem do que essa, naquele momento, no meu. Pareceu entrar com grande força em cada fibra de meu coração. Refleti repetidamente sobre ela, tendo consciência de que se alguém necessitava da sabedoria de Deus, era eu, pois eu não sabia como agir e, a menos que conseguisse obter mais sabedoria do que a que tinha então, nunca saberia; pois os religiosos das diferentes seitas interpretavam as mesmas passagens de escritura de maneira tão diferente, que destruíam toda a confiança na solução do problema através de uma consulta à Bíblia."},{"verse":13,"text":"Finalmente cheguei à conclusão de que teria de permanecer em trevas e confusão, ou fazer como Tiago aconselha, isto é, pedir a Deus. Resolvi “pedir a Deus,” concluindo que, se ele dava sabedoria aos que tinham falta dela, e concedia-a liberalmente, sem censura, eu podia aventurar-me."},{"verse":14,"text":"Assim, seguindo minha determinação de pedir a Deus, retirei-me para um bosque a fim de fazer a tentativa. Foi na manhã de um belo e claro dia, no início da primavera de 1820. Era a primeira vez na vida que fazia tal tentativa, pois em meio a todas as ansiedades que tivera, jamais havia experimentado orar em voz alta."},{"verse":15,"text":"Depois de me haver retirado para o lugar que previamente escolhera, tendo olhado ao redor e encontrando-me só, ajoelhei-me e comecei a oferecer a Deus os desejos de meu coração. Apenas iniciara, imediatamente se apoderou de mim uma força que me dominou por completo; e tão assombrosa foi sua influência que se me travou a língua, de modo que eu não podia falar. Uma densa escuridão formou-se ao meu redor e pareceu-me, por um momento, que eu estava condenado a uma destruição súbita."},{"verse":16,"text":"Mas usando todas as forças para clamar a Deus que me livrasse do poder desse inimigo que me subjugara, no momento exato em que estava prestes a sucumbir ao desespero e abandonar-me à destruição — não a uma ruína imaginária, mas ao poder de algum ser real do mundo invisível, que possuía uma força tão assombrosa como eu jamais sentira em qualquer ser — exatamente nesse momento de grande alarme, vi um pilar de luz acima de minha cabeça, mais brilhante que o sol, que descia gradualmente sobre mim."},{"verse":17,"text":"Assim que apareceu, senti-me livre do inimigo que me sujeitava. Quando a luz pousou sobre mim, vi dois Personagens cujo esplendor e glória desafiam qualquer descrição, pairando no ar, acima de mim. Um deles falou-me, chamando-me pelo nome, e disse, apontando para o outro: Este é Meu Filho Amado. Ouve-O!"},{"verse":18,"text":"Meu objetivo ao dirigir-me ao Senhor era saber qual de todas as seitas estava certa, a fim de saber a qual me unir. Portanto, tão logo me controlei o suficiente para poder falar, perguntei aos Personagens que estavam na luz acima de mim qual de todas as seitas estava certa (pois até aquele momento jamais me ocorrera que todas estivessem erradas) e a qual me unir."},{"verse":19,"text":"Foi-me respondido que não me unisse a qualquer delas, pois estavam todas erradas; e o Personagem que se dirigia a mim disse que todos os seus credos eram uma abominação a sua vista; que aqueles religiosos eram todos corruptos; que “eles se aproximam de mim com os lábios, mas seu coração está longe de mim; ensinam como doutrina os mandamentos de homens, tendo aparência de religiosidade, mas negam o seu poder.”"},{"verse":20,"text":"Novamente me proibiu de unir-me a qualquer delas; e muitas outras coisas disse-me, as quais não posso, no momento, escrever. Quando tornei a voltar a mim, estava deitado de costas, olhando para o céu. Quando a luz se retirou, eu estava sem forças; mas tendo logo me recuperado em parte, fui para casa. Ao apoiar-me na lareira, minha mãe perguntou-me o que se passava. Respondi: “Não se preocupe, tudo está bem — eu estou bem.” Então disse a ela: “Aprendi por mim mesmo que o presbiterianismo não é verdadeiro.” Parece que o adversário sabia, nos primeiros anos de minha vida, que eu estava destinado a ser um perturbador e um importunador de seu reino; senão, por que os poderes das trevas se uniriam contra mim? Por que a oposição e a perseguição que se levantaram contra mim, quase em minha infância?"},{"verse":21,"text":"Alguns dias após essa visão, encontrei-me, por acaso, na companhia de um dos pregadores metodistas, que era muito ativo no já mencionado alvoroço religioso; e, conversando com ele sobre religião, aproveitei a oportunidade para relatar-lhe a visão que tivera. Fiquei muito surpreso com seu comportamento; tratou meu relato não só levianamente, mas com grande desprezo, dizendo que tudo aquilo era do diabo, que não havia tais coisas como visões ou revelações nestes dias; que todas essas coisas haviam cessado com os apóstolos e que nunca mais existiriam."},{"verse":22,"text":"Logo descobri, entretanto, que minha narração da história havia provocado muito preconceito contra mim entre os religiosos, tornando-se motivo de grande perseguição, a qual continuou a aumentar; e embora eu fosse um menino obscuro, de apenas quatorze para quinze anos de idade, e minha situação na vida fizesse de mim um menino sem importância no mundo, homens influentes preocupavam-se o bastante para incitar a opinião pública contra mim e provocar uma perseguição implacável. E isto se tornou ponto comum entre todas as seitas — todas se uniram para perseguir-me."},{"verse":23,"text":"Isso me levou a refletir seriamente, na época, e muitas vezes a partir daí; quão estranho era que um obscuro menino de pouco mais de quatorze anos de idade, que estava, também, condenado à necessidade de obter um sustento escasso com seu trabalho diário, fosse considerado suficientemente importante para atrair a atenção dos grandes das seitas mais populares da época, criando neles o espírito da mais implacável perseguição e injúria! Mas, estranho ou não, assim aconteceu e isso foi, com frequência, causa de grande tristeza para mim."},{"verse":24,"text":"Contudo, era um fato ter tido eu uma visão. Tenho pensado que me sentia como Paulo, quando apresentou sua defesa perante o rei Agripa e relatou a visão que tivera, quando viu uma luz e ouviu uma voz; mas poucos foram também os que acreditaram nele; alguns disseram que ele era desonesto, outros, que estava louco; e foi ridicularizado e injuriado. Tudo isso, porém, não destruiu a realidade da visão. Ele tivera uma visão, sabia que a tivera, e toda a perseguição debaixo do céu não poderia fazer com que fosse de outra forma; e ainda que o perseguissem até a morte, ele sabia e saberia até o último alento que tinha visto uma luz e ouvido uma voz falando-lhe; e o mundo inteiro não poderia fazê-lo pensar ou crer de outra maneira."},{"verse":25,"text":"Assim era comigo. Tinha realmente visto uma luz e, no meio dessa luz, dois Personagens; e eles realmente falaram comigo; e embora eu fosse odiado e perseguido por dizer que tivera uma visão, isso era verdade; e enquanto me perseguiam, injuriando-me e afirmando falsamente toda espécie de maldades contra mim por dizê-lo, fui levado a pensar em meu coração: Por que perseguir-me por contar a verdade? Tive realmente uma visão; e quem sou eu para opor-me a Deus, ou por que pensa o mundo fazer-me negar o que realmente vi? Porque eu tivera uma visão; eu sabia-o e sabia que Deus o sabia e não podia negá-la nem ousaria fazê-lo; pelo menos eu tinha consciência de que, se o fizesse, ofenderia a Deus e estaria sob condenação."},{"verse":26,"text":"Minha mente já estava satisfeita no que concernia ao mundo sectário — não era meu dever unir-me a qualquer das seitas, mas continuar como estava até nova orientação. Descobrira ser verdadeiro o testemunho de Tiago: que um homem que necessitasse de sabedoria podia pedi-la a Deus e obtê-la, sem ser repreendido."},{"verse":27,"text":"Continuei minhas ocupações comuns na vida até o dia vinte e um de setembro de mil oitocentos e vinte e três, sofrendo todo o tempo severa perseguição nas mãos de todos os tipos de homens, tanto religiosos como irreligiosos, porque eu continuava a afirmar que tivera uma visão."},{"verse":28,"text":"No espaço de tempo entre a ocasião em que tive a visão e o ano de mil oitocentos e vinte e três — tendo sido proibido de unir-me a qualquer das seitas religiosas da época e sendo ainda muito jovem e perseguido por aqueles que deveriam ter sido meus amigos e me tratado com bondade — e se supunham eles que eu estava iludido, deveriam ter procurado, de maneira apropriada e afetuosa, reconquistar-me — fui abandonado a toda sorte de tentações; e, misturando-me a todo tipo de gente, caí frequentemente em muitos erros tolos, exibindo as fraquezas da juventude e as debilidades da natureza humana; o que, sinto dizer, levou-me a tentações diversas, ofensivas à vista de Deus. Ao fazer esta confissão, ninguém deve crer-me culpado de quaisquer pecados grandes ou malignos. Jamais existiu em minha natureza disposição para tal. Mas fui culpado de leviandades e, às vezes, andava com companhias joviais, etc., o que não condizia com a conduta que devia ser mantida por uma pessoa que fora chamada por Deus, como eu. Isso, porém, não parecerá estranho para quem se recorda de minha juventude e conhece meu temperamento naturalmente alegre."},{"verse":29,"text":"Em consequência dessas coisas, muitas vezes senti-me condenado por minhas fraquezas e imperfeições. Foi então que, na noite do já mencionado vinte e um de setembro, depois de me haver recolhido, recorri à oração e à súplica ao Deus Todo-Poderoso para pedir perdão por todos os meus pecados e imprudências, pedindo também uma manifestação para que eu pudesse saber qual era o meu estado e posição perante ele; pois tinha plena confiança de receber uma manifestação divina, como acontecera anteriormente."},{"verse":30,"text":"Enquanto estava assim suplicando a Deus, descobri uma luz surgindo em meu quarto, a qual continuou a aumentar até o aposento ficar mais iluminado do que ao meio-dia; imediatamente apareceu ao lado de minha cama um personagem em pé, no ar, pois seus pés não tocavam o solo."},{"verse":31,"text":"Ele vestia uma túnica solta, da mais rara brancura. Era uma brancura que excedia a qualquer coisa terrena que eu já vira; nem acredito que qualquer coisa terrena possa parecer tão extraordinariamente branca e brilhante. Tinha as mãos descobertas e os braços também, um pouco acima dos pulsos; os pés também estavam descobertos, bem como as pernas, um pouco acima dos tornozelos. A cabeça e o pescoço também estavam nus. Verifiquei que ele não usava outra roupa além dessa túnica, pois estava aberta, de modo que eu lhe podia ver o peito."},{"verse":32,"text":"Não somente sua túnica era muito branca, mas toda a sua pessoa era indescritivelmente gloriosa e seu semblante era verdadeiramente como o relâmpago. O quarto estava muito claro, mas não tão luminoso como ao redor de sua pessoa. No momento em que o vi, tive medo; mas o medo logo desapareceu."},{"verse":33,"text":"Chamou-me pelo nome e disse-me que era um mensageiro enviado a mim da presença de Deus e que seu nome era Morôni; que Deus tinha uma obra a ser executada por mim; e que meu nome seria considerado bom e mau entre todas as nações, tribos e línguas, ou que entre todos os povos se falaria bem e mal de meu nome."},{"verse":34,"text":"Disse-me que havia um livro escondido, escrito em placas de ouro, que continha um relato dos antigos habitantes deste continente, assim como de sua origem e procedência. Disse também que o livro continha a plenitude do evangelho eterno, tal como fora entregue pelo Salvador aos antigos habitantes."},{"verse":35,"text":"Disse também que havia duas pedras em aros de prata — e essas pedras, presas a um peitoral, constituíam o que é chamado Urim e Tumim — depositadas com as placas; e que a posse e o uso dessas pedras era o que constituía os “videntes” nos tempos antigos; e que Deus as tinha preparado para serem usadas na tradução do livro."},{"verse":36,"text":"Depois de me dizer essas coisas, começou a citar as profecias do Velho Testamento. Primeiro citou parte do terceiro capítulo de Malaquias; e citou também o quarto ou último capítulo da mesma profecia, embora com pequena variação do modo como aparece na Bíblia. Em vez de citar o primeiro versículo conforme está em nossos livros, citou-o assim:"},{"verse":37,"text":"Porque eis que vem o dia que arderá como fornalha e todos os soberbos, sim, e todos os que cometem impiedade, queimarão como a palha; e aqueles que hão de vir os abrasarão, diz o Senhor dos Exércitos, de sorte que lhes não deixarão nem raiz nem ramo."},{"verse":38,"text":"E também citou o quinto versículo assim: Eis que eu vos revelarei o Sacerdócio, pela mão de Elias, o profeta, antes que venha o grande e terrível dia do Senhor."},{"verse":39,"text":"Citou também o versículo seguinte diferentemente: E ele plantará no coração dos filhos as promessas feitas aos pais; e o coração dos filhos voltar-se-á para seus pais. Se assim não fosse, toda a terra seria totalmente devastada na sua vinda."},{"verse":40,"text":"Além desses, citou o capítulo onze de Isaías, dizendo que estava prestes a ser cumprido. Citou também o terceiro capítulo de Atos, versículos vinte e dois e vinte e três, exatamente como aparecem em nosso Novo Testamento. Disse que aquele profeta era Cristo, mas que ainda não chegara o dia em que “toda a alma que não escutar esse profeta será exterminada dentre o povo,” mas logo chegaria."},{"verse":41,"text":"Também citou o segundo capítulo de Joel, do versículo vinte e oito até o último. Disse também que isso não havia sido cumprido, mas logo o seria. E disse mais: que a plenitude dos gentios logo ocorreria. Citou muitas outras passagens de escritura e ofereceu muitas explicações que não podem ser mencionadas aqui."},{"verse":42,"text":"Disse-me ainda que quando eu recebesse as placas sobre as quais ele havia falado — porquanto o momento em que elas deveriam ser obtidas ainda não chegara —, a ninguém deveria mostrá-las; nem o peitoral com o Urim e Tumim, salvo àqueles a quem me fosse ordenado mostrá-los; e se eu o fizesse, seria destruído. Enquanto falava comigo a respeito das placas, minha mente abriu-se de tal modo que visualizei o lugar em que estavam depositadas, e isto tão clara e nitidamente que reconheci o local quando o visitei."},{"verse":43,"text":"Após essa comunicação, vi a luz do quarto começar a concentrar-se imediatamente ao redor do personagem que estivera falando comigo; e assim continuou até o quarto voltar à escuridão, exceto ao redor dele; e imediatamente vi como se fora um conduto, que levava até o céu; e ele ascendeu até desaparecer completamente, e o quarto voltou ao estado em que estava antes de essa luz celestial aparecer."},{"verse":44,"text":"Fiquei meditando sobre a singularidade da cena, grandemente maravilhado com o que me dissera o extraordinário mensageiro, quando, em meio à minha meditação, descobri subitamente que meu quarto começava novamente a ser iluminado e imediatamente vi o mesmo mensageiro celestial outra vez ao lado de minha cama."},{"verse":45,"text":"Relatou-me novamente, sem a mínima alteração, as mesmas coisas que me dissera na primeira visita; a seguir me informou de grandes julgamentos que recairiam sobre a Terra, com grandes desolações causadas pela fome, espada e pestilências; e que esses dolorosos julgamentos recairiam sobre a Terra nesta geração. Tendo-me comunicado essas coisas, novamente ascendeu, como fizera antes."},{"verse":46,"text":"Naquele momento, tão profundas eram as impressões causadas em minha mente, que perdi o sono por completo, atônito com o que havia visto e ouvido. Mas qual não foi minha surpresa quando vi novamente o mesmo mensageiro ao lado de minha cama e ouvi-o repetir as mesmas coisas que me dissera antes; e também advertiu-me, informando-me que Satanás procuraria tentar-me (em consequência da pobreza da família de meu pai) a obter as placas com o fim de enriquecer-me. Proibiu-me isso, dizendo que eu não deveria ter qualquer outro objetivo em vista, ao receber as placas, a não ser o de glorificar a Deus; e que eu não deveria ser influenciado por qualquer outro motivo, senão o de edificar o seu reino; caso contrário, não as poderia obter."},{"verse":47,"text":"Após essa terceira visita ele ascendeu ao céu, como antes; e outra vez fiquei meditando sobre a estranheza do que acabara de acontecer; quase imediatamente após o mensageiro celestial ter ascendido pela terceira vez, o galo cantou e vi que o dia se aproximava, de modo que as entrevistas deviam ter durado toda aquela noite."},{"verse":48,"text":"Pouco depois me levantei e, como de costume, fui cuidar dos afazeres do dia; mas ao tentar trabalhar como normalmente fazia, senti-me tão exausto que não consegui. Meu pai, que trabalhava perto de mim, percebeu que eu não estava bem e disse-me que fosse para casa. Saí com essa intenção, mas ao tentar atravessar a cerca do campo onde estávamos, faltaram-me as forças por completo e caí inerte ao solo, ficando completamente inconsciente durante algum tempo."},{"verse":49,"text":"A primeira coisa de que me lembro é uma voz chamando-me pelo nome. Olhei para cima e vi o mesmo mensageiro acima de minha cabeça, cercado de luz como antes. Repetiu-me tudo o que havia relatado na noite anterior e ordenou-me que fosse contar a meu pai a visão e os mandamentos que havia recebido."},{"verse":50,"text":"Obedeci, voltando para onde estava meu pai, no campo, e relatei-lhe todo o ocorrido. Ele respondeu-me que aquilo era obra de Deus e disse-me que fizesse o que o mensageiro ordenara. Deixei o campo e fui até o local onde o mensageiro dissera estarem depositadas as placas; e devido à nitidez da visão que tivera, referente ao local, reconheci-o no instante em que lá cheguei."},{"verse":51,"text":"Próximo à vila de Manchester, no Condado de Ontário, Estado de Nova York, existe uma colina de considerável tamanho, sendo a mais alta da redondeza. No lado oeste dessa colina, não muito distante do cume, sob uma pedra de considerável tamanho, estavam as placas, depositadas em uma caixa de pedra. No meio, na parte superior, essa pedra era grossa e arredondada; era, porém, mais fina na direção das extremidades, de modo que a parte central ficava visível acima do solo, mas as bordas em toda a volta estavam cobertas de terra."},{"verse":52,"text":"Tendo removido a terra, arranjei uma alavanca, introduzi-a sob a borda da pedra e consegui levantá-la com um pequeno esforço. Olhei e lá realmente vi as placas, o Urim e Tumim e o peitoral, como afirmara o mensageiro. A caixa na qual se encontravam era formada de pedras unidas por uma espécie de cimento. No fundo da caixa havia duas pedras colocadas transversalmente, e sobre elas estavam as placas e as outras coisas."},{"verse":53,"text":"Fiz uma tentativa de retirá-las, mas fui proibido pelo mensageiro, que outra vez me informou ainda não haver chegado o momento de retirá-las, dizendo que esse momento não chegaria a não ser quatro anos após aquela data. Disse-me que eu deveria voltar àquele local precisamente um ano mais tarde e que lá ele se encontraria comigo, devendo eu continuar a assim proceder até que chegasse o tempo de receber as placas."},{"verse":54,"text":"De acordo com o que me fora ordenado, voltei lá ao fim de cada ano e todas as vezes encontrei o mesmo mensageiro. Em cada uma das entrevistas recebi dele instruções e conhecimento com respeito ao que o Senhor ia fazer e à maneira pela qual o seu reino deveria ser conduzido nos últimos dias."},{"verse":55,"text":"Como a situação econômica de meu pai fosse muito limitada, víamo-nos obrigados a trabalhar com as mãos, empregando-nos fora, por dia ou de outras maneiras, segundo surgia a oportunidade. Às vezes estávamos em casa, outras, fora; e, trabalhando continuamente, conseguíamos viver de maneira confortável."},{"verse":56,"text":"No ano de 1823, a família de meu pai passou por uma grande dor com a morte de meu irmão mais velho, Alvin. No mês de outubro de 1825, empreguei-me com um senhor idoso chamado Josiah Stoal, que morava no Condado de Chenango, Estado de Nova York. Ele tinha ouvido falar de uma mina de prata aberta pelos espanhóis em Harmony, Condado de Susquehanna, Estado da Pensilvânia; e antes de me empregar, havia feito escavações com o fim de, se possível, descobrir a mina. Depois que fui morar com ele, levou-me com o resto de seus empregados para escavar, em busca da mina de prata, no que continuei a trabalhar por aproximadamente um mês sem alcançar sucesso em nosso empreendimento; e finalmente convenci aquele senhor a desistir de procurar a mina. Assim surgiu a história muito divulgada de haver sido eu um cavador de dinheiro."},{"verse":57,"text":"Durante o tempo em que estive nesse emprego, hospedei-me com o Sr. Isaac Hale, daquele lugar; foi lá que pela primeira vez vi minha mulher (filha dele), Emma Hale. Casamo-nos no dia 18 de janeiro de 1827, enquanto eu ainda estava a serviço do Sr. Stoal."},{"verse":58,"text":"Devido a minha insistência em afirmar que tivera uma visão, continuava a ser perseguido e a família do pai de minha mulher opôs-se muito a nosso casamento. Precisei, portanto, levá-la para outra parte; assim, casamo-nos na casa do Juiz Tarbill em South Bainbridge, Condado de Chenango, Estado de Nova York. Imediatamente após meu casamento, deixei o emprego com o Sr. Stoal e fui para a casa de meu pai, trabalhando com ele no campo durante aquela estação."},{"verse":59,"text":"Finalmente chegou a época de receber as placas, o Urim e Tumim e o peitoral. No dia vinte e dois de setembro de mil oitocentos e vinte e sete, tendo ido, como de costume, ao fim de mais um ano, ao local onde estavam depositados, o mesmo mensageiro celestial entregou-os a mim, com a advertência de que eu seria responsável por eles; que se eu os deixasse extraviar por algum descuido ou negligência, seria cortado; mas que se eu empregasse todos os esforços para preservá-los até que ele, o mensageiro, os reclamasse, eles seriam protegidos."},{"verse":60,"text":"Logo verifiquei a razão de tão severas recomendações para que os guardasse em segurança, e por que o mensageiro dissera que quando eu tivesse realizado o que me fora ordenado, ele viria buscá-los. Pois tão logo se soube que estavam em meu poder, foram empregados os mais tenazes esforços para tirá-los de mim. Todos os estratagemas possíveis foram usados com esse propósito. A perseguição tornou-se mais amarga e severa que antes, e multidões mantinham-se continuamente alertas para tirá-los de mim, se possível. Mas pela sabedoria de Deus, eles continuaram seguros em minhas mãos até que cumpri, por meio deles, o que me fora requerido. Quando o mensageiro os reclamou, de acordo com o combinado, entreguei-os a ele, que os tem sob sua guarda até esta data, dois de maio de mil oitocentos e trinta e oito."},{"verse":61,"text":"O alvoroço, contudo, ainda continuava e os rumores, com suas mil línguas, eram empregados todo o tempo para fazer circular falsidades sobre a família de meu pai e sobre mim. Se eu relatasse a milésima parte deles, encheria volumes. A perseguição, contudo, tornou-se tão intolerável que fui obrigado a sair de Manchester e ir com minha mulher para o Condado de Susquehanna, no Estado da Pensilvânia. Enquanto me preparava para partir — sendo muito pobre e sofrendo uma perseguição tão grande que não haveria possibilidade de que fosse de outra forma — em meio a nossas aflições encontramos um amigo na pessoa de Martin Harris, que nos procurou e me deu cinquenta dólares para auxiliar-nos na viagem. O Sr. Harris era morador do distrito de Palmyra, Condado de Wayne, no Estado de Nova York, e fazendeiro bem conceituado."},{"verse":62,"text":"Mediante essa ajuda oportuna, pude chegar ao lugar de meu destino, na Pensilvânia; e, imediatamente após minha chegada, comecei a copiar os caracteres das placas. Copiei um número considerável deles e, por meio do Urim e Tumim, traduzi alguns, o que fiz entre os meses de dezembro, quando cheguei à casa de meu sogro, e fevereiro do ano seguinte."},{"verse":63,"text":"Nesse mesmo mês de fevereiro, o já mencionado Sr. Martin Harris veio a nossa casa, tomou os caracteres que eu havia copiado das placas e partiu com eles para a cidade de Nova York. Quanto ao que aconteceu em relação a ele e aos caracteres, refiro-me ao seu próprio relato dos acontecimentos, como me contou quando de seu regresso, e que é o seguinte:"},{"verse":64,"text":"“Fui à cidade de Nova York e apresentei os caracteres que tinham sido traduzidos, assim como sua tradução, ao professor Charles Anthon, famoso por seus conhecimentos literários. O professor Anthon declarou que a tradução estava correta, muito mais que qualquer tradução do egípcio que já vira. Mostrei-lhe então os que ainda não haviam sido traduzidos e ele disse-me serem egípcios, caldeus, assírios e arábicos; e acrescentou que eram caracteres autênticos. Deu-me uma declaração, atestando ao povo de Palmyra que eram autênticos e que a tradução, como fora feita, também estava correta. Peguei a declaração e coloquei-a no bolso; estava saindo da casa quando o Sr. Anthon me chamou e perguntou-me como soubera o jovem que havia placas de ouro no lugar onde ele as encontrara. Respondi-lhe que um anjo de Deus lho revelara."},{"verse":65,"text":"Disse-me então: ‘Deixe-me ver essa declaração’. Tirei-a do bolso e entreguei-a a ele, que a pegou e rasgou em pedacinhos, dizendo que já não existiam coisas como ministério de anjos e que, se eu lhe desse as placas, ele as traduziria. Informei-o de que parte das placas estava selada e que me era proibido levá-las. Ele respondeu: ‘Não posso ler um livro selado’. Saí de lá e procurei o Dr. Mitchell, que confirmou tudo o que o Sr. Anthon dissera a respeito dos caracteres e da tradução.”"},{"verse":66,"text":"No dia 5 de abril de 1829, Oliver Cowdery, que eu jamais vira até aquele dia, veio a minha casa. Disse-me que, sendo professor da escola localizada nas proximidades da casa de meu pai e sendo meu pai um dos que tinham filhos na escola, hospedara-se por algum tempo em sua casa; e que enquanto lá estivera, a família relatara-lhe as circunstâncias em que eu recebera as placas e que, por isso, viera obter informações."},{"verse":67,"text":"Dois dias após a chegada do Sr. Cowdery (estávamos em 7 de abril), comecei a traduzir o Livro de Mórmon e ele começou a escrever para mim."},{"verse":68,"text":"Continuávamos ainda o trabalho da tradução, quando, no mês seguinte (maio de 1829), fomos certo dia a um bosque para orar e consultar o Senhor a respeito do batismo para a remissão dos pecados, mencionado na tradução das placas. Enquanto orávamos e invocávamos o Senhor, um mensageiro do céu desceu em uma nuvem de luz e, colocando as mãos sobre nós, ordenou-nos, dizendo:"},{"verse":69,"text":"A vós, meus conservos, em nome do Messias, eu confiro o Sacerdócio de Aarão, que possui as chaves do ministério de anjos e do evangelho do arrependimento e do batismo por imersão para remissão dos pecados; e este nunca mais será tirado da Terra, até que os filhos de Levi tornem a fazer, em retidão, uma oferta ao Senhor."},{"verse":70,"text":"Disse que esse Sacerdócio Aarônico não tinha o poder de imposição de mãos para o dom do Espírito Santo, mas que isso nos seria conferido mais tarde; e mandou que nos batizássemos, dando instruções para que eu batizasse Oliver Cowdery e depois ele me batizasse."},{"verse":71,"text":"Assim, fomos batizados. Eu batizei-o primeiro e, em seguida, ele batizou-me — após o que, coloquei as mãos sobre sua cabeça e ordenei-o ao Sacerdócio Aarônico; e em seguida ele pôs as mãos sobre minha cabeça e ordenou-me ao mesmo sacerdócio — pois assim nos fora mandado.*"},{"verse":72,"text":"O mensageiro que nos visitou nessa ocasião e conferiu-nos esse sacerdócio disse que seu nome era João, o mesmo que é chamado João Batista no Novo Testamento; e que agia sob a direção de Pedro, Tiago e João, que possuíam as chaves do Sacerdócio de Melquisedeque, sacerdócio esse que, declarou ele, nos seria conferido no devido tempo; e que eu seria o primeiro élder da Igreja e ele (Oliver Cowdery), o segundo. No dia quinze de maio de 1829 fomos ordenados pela mão desse mensageiro e batizados."},{"verse":73,"text":"Assim que saímos da água, após termos sido batizados, recebemos grandes e gloriosas bênçãos de nosso Pai Celestial. Apenas terminei de batizar Oliver Cowdery, o Espírito Santo desceu sobre ele e ele, pondo-se de pé, profetizou muitas coisas que logo deveriam acontecer. E tão logo fui batizado por ele, também recebi o espírito de profecia e profetizei sobre a edificação desta Igreja e muitas outras coisas ligadas à Igreja e a esta geração dos filhos dos homens. Estávamos cheios do Espírito Santo e regozijamo-nos no Deus de nossa salvação."},{"verse":74,"text":"Estando então nossa mente iluminada, as escrituras começaram a abrir-se ao nosso entendimento e o verdadeiro significado e intenção de suas passagens mais misteriosas revelaram-se a nós de uma forma que jamais havíamos conseguido antes e que sequer imaginávamos. Entrementes, fomos forçados a guardar segredo sobre as circunstâncias em que havíamos recebido o sacerdócio e sido batizados, devido ao espírito de perseguição que já se havia manifestado nas redondezas."},{"verse":75,"text":"De tempos em tempos ameaçavam espancar-nos, isso também pelos que professavam ser religiosos. E a intenção que tinham de nos espancar era somente neutralizada pela influência da família de meu sogro (sob a Divina providência), que se tornara muito minha amiga e que era contrária a turbas, desejando que me fosse permitido continuar o trabalho de tradução sem interrupções; e assim nos ofereceu e prometeu proteção, no que lhes fosse possível, contra qualquer ato ilegal."},{"verse":76,"text":"Oliver Cowdery relata esses acontecimentos da seguinte maneira: “Esses foram dias inolvidáveis — ouvir o som de uma voz ditada pela inspiração do céu despertou neste peito uma profunda gratidão! Dia após dia continuei ininterruptamente a escrever o que lhe saía da boca, enquanto ele traduzia a história ou relato chamado ‘O Livro de Mórmon’ com o Urim e Tumim, ou, como teriam dito os nefitas, ‘Intérpretes’."},{"verse":77,"text":"Fazer menção, ainda que em poucas palavras, do interessante relato que Mórmon e seu filho Morôni escreveram com relação a um povo que foi amado e favorecido pelo céu seria desviar-me de minha presente intenção; deixarei, portanto, esse assunto para o futuro; e, como disse na introdução, passarei mais diretamente a alguns incidentes imediatamente ligados ao surgimento desta Igreja, que serão de interesse para alguns milhares que, em meio ao desagrado de fanáticos e das calúnias de hipócritas, abraçaram o Evangelho de Cristo."},{"verse":78,"text":"Nenhum homem, no domínio de suas faculdades, poderia traduzir e escrever as instruções dadas aos nefitas pela boca do Salvador a respeito da maneira precisa em que os homens deveriam edificar sua Igreja — especialmente quando a corrupção espalhara a incerteza sobre todas as formas e sistemas praticados entre os homens — sem desejar o privilégio de mostrar a disposição de ser imerso na sepultura líquida, para responder a uma ‘boa consciência (…) pela ressurreição de Jesus Cristo’."},{"verse":79,"text":"Depois de escrever o relato do ministério do Salvador aos remanescentes da semente de Jacó neste continente, foi fácil ver, como o profeta disse que seria, que trevas cobriam a Terra e densas trevas, a mente do povo. Refletindo um pouco mais, foi fácil ver que, na grande contenda e no grande clamor com respeito a religião, ninguém tinha a autoridade de Deus para administrar as ordenanças do evangelho. Pois se podia perguntar: Têm os homens que negam as revelações autoridade para administrar em nome de Cristo, sendo que o testemunho dele não é senão o espírito de profecia e que sua religião baseia-se em revelações diretas, e por elas é edificada e apoiada em qualquer época do mundo em que ele teve um povo na Terra? Se esses fatos foram enterrados e cuidadosamente escondidos por homens cujas artimanhas estariam em perigo caso lhes fosse permitido brilhar diante dos homens, para nós já não o estavam; e somente esperávamos que se desse o mandamento: ‘Levantai-vos e sede batizados’."},{"verse":80,"text":"Não tardou muito para que esse desejo se realizasse. O Senhor, grande em misericórdia e sempre disposto a atender à oração constante e humilde, depois que o havíamos invocado fervorosamente, afastados das habitações dos homens, condescendeu em manifestar-nos a sua vontade. Repentinamente, como se fora do meio da eternidade, a voz do Redentor manifestou-nos paz; ao mesmo tempo o véu abriu-se e um anjo de Deus desceu, revestido de glória, e transmitiu a esperada mensagem e as chaves do Evangelho do arrependimento. Que alegria! Que admiração! Que assombro! Enquanto o mundo se encontrava atormentado, confundido — enquanto milhões andavam às apalpadelas como cegos procurando a parede e enquanto todos os homens mergulhavam na incerteza, como a massa em geral, nossos olhos viram, nossos ouvidos ouviram, como no ‘fulgor do dia’; sim, mais ainda — acima do resplendor do sol de primavera que nesse momento banhava com seu brilho a face da natureza. Então, a sua voz, ainda que humilde, penetrou até o âmago e suas palavras ‘Sou vosso conservo’ desvaneceu todo temor. Escutamos! Contemplamos! Admiramos! Era a voz de um anjo da glória, era uma mensagem do Altíssimo! E, ao ouvir, rejubilamo-nos, enquanto seu amor nos aquecia a alma e éramos envoltos pela visão do Onipotente! Havia lugar para dúvidas? Nenhum; a incerteza desvanecera-se. A dúvida desaparecera para jamais voltar, enquanto a ficção e o engano se desvaneceram para sempre."},{"verse":81,"text":"Mas, querido irmão, pensa, pensa um pouco mais na alegria que nos encheu o coração e na surpresa com que nos curvamos (pois quem não teria dobrado os joelhos para receber tal bênção?), quando recebemos de suas mãos o Santo Sacerdócio, ao dizer ele: ‘A vós, meus conservos, em nome do Messias, eu confiro este Sacerdócio e esta autoridade que permanecerá na Terra a fim de que os Filhos de Levi possam ainda fazer, em retidão, uma oferta ao Senhor!’"},{"verse":82,"text":"Não procurarei descrever-te os sentimentos deste coração nem a majestosa beleza e glória que nos envolveram nessa ocasião; mas acreditar-me-ás quando te disser que nem a Terra nem os homens, com a eloquência do tempo, podem sequer começar a expressar-se de modo tão interessante e sublime como esse santo personagem. Não! Nem tem esta Terra poder para dar a alegria, conceder a paz ou captar a sabedoria contida em cada uma dessas frases proferidas pelo poder do Santo Espírito! Os homens podem enganar seus semelhantes, enganos podem suceder a enganos e os filhos do maligno podem ter o poder de seduzir os néscios e ignorantes até o ponto em que nada, a não ser a ficção, alimente as multidões e os frutos da mentira arrastem, em sua correnteza, os insensatos até a tumba; mas um toque do dedo de seu amor, sim, um raio de glória do céu ou uma palavra da boca do Senhor, do seio da eternidade, faz com que tudo pareça insignificante, apagando-o para sempre da mente. A certeza de que estávamos na presença de um anjo, de que ouvíamos a voz de Jesus e a verdade imaculada que emanava de um personagem puro, ditada pela vontade de Deus, é para mim indescritível e sempre considerarei essa expressão da bondade do Salvador com assombro e gratidão enquanto me for permitido viver; e nas mansões onde a perfeição habita e o pecado nunca chega, espero adorar no dia que jamais cessará.” — Messenger and Advocate, Vol. 1 (outubro de 1834), pp. 14–16."}]}]},{"id":"articles-of-faith","title":"Regras de Fé","englishTitle":"Articles of Faith","volume":"Pearl of Great Price","volumeId":"pgp","chapters":[{"chapter":1,"verses":[{"verse":1,"text":"Cremos em Deus, o Pai Eterno, e em Seu Filho, Jesus Cristo, e no Espírito Santo."},{"verse":2,"text":"Cremos que os homens serão punidos por seus próprios pecados e não pela transgressão de Adão."},{"verse":3,"text":"Cremos que, por meio da Expiação de Cristo, toda a humanidade pode ser salva, pela obediência às leis e ordenanças do Evangelho."},{"verse":4,"text":"Cremos que os primeiros princípios e ordenanças do Evangelho são: primeiro, Fé no Senhor Jesus Cristo; segundo, Arrependimento; terceiro, Batismo por imersão para a remissão de pecados; quarto, Imposição de mãos para o dom do Espírito Santo."},{"verse":5,"text":"Cremos que um homem deve ser chamado por Deus, por profecia, e pela imposição de mãos, por quem possua autoridade, para pregar o Evangelho e administrar as suas ordenanças."},{"verse":6,"text":"Cremos na mesma organização que existia na Igreja Primitiva, isto é, apóstolos, profetas, pastores, mestres, evangelistas, etc."},{"verse":7,"text":"Cremos no dom de línguas, profecia, revelação, visões, cura, interpretação de línguas, etc."},{"verse":8,"text":"Cremos ser a Bíblia a palavra de Deus, desde que esteja traduzida corretamente; também cremos ser o Livro de Mórmon a palavra de Deus."},{"verse":9,"text":"Cremos em tudo o que Deus revelou, em tudo o que Ele revela agora, e cremos que Ele ainda revelará muitas coisas grandiosas e importantes relativas ao Reino de Deus."},{"verse":10,"text":"Cremos na coligação literal de Israel e na restauração das Dez Tribos; que Sião (a Nova Jerusalém) será construída no continente americano; que Cristo reinará pessoalmente na Terra; e que a Terra será renovada e receberá a sua glória paradisíaca."},{"verse":11,"text":"Pretendemos o privilégio de adorar a Deus Todo-Poderoso de acordo com os ditames de nossa própria consciência; e concedemos a todos os homens o mesmo privilégio, deixando-os adorar como, onde, ou o que desejarem."},{"verse":12,"text":"Cremos na submissão a reis, presidentes, governantes, e magistrados; na obediência, honra, e manutenção da lei."},{"verse":13,"text":"Cremos em ser honestos, verdadeiros, castos, benevolentes, virtuosos, e em fazer o bem a todos os homens; na realidade, podemos dizer que seguimos a admoestação de Paulo: Cremos em todas as coisas, confiamos em todas as coisas, suportamos muitas coisas e esperamos ter a capacidade de tudo suportar. Se houver qualquer coisa virtuosa, amável, de boa fama ou louvável, nós a procuraremos."},{"verse":14,"text":"Joseph Smith."}]}]}]'),o={language:"pt",sourceLanguage:"por",sourcePage:e,books:a};export{o as r};
